static void die(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "test_cluster [%s]: FAIL: ", scen);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n  (server logs in %s/n*.log)\n", base);
    va_end(ap);
    static int dying;
    if (!dying++) { /* a server a sanitizer stopped (halt_on_error) shows only as a timeout here: name its report */
        for (int i = 0; i < N; i++) {
            char path[PATH_MAX + 96], ln[512];
            snprintf(path, sizeof path, "%s/n%d.log", base, i);
            FILE *fp = fopen(path, "r");
            int shown = -1;
            while (fp && shown < 12 && fgets(ln, sizeof ln, fp)) {
                if (shown < 0 && (strstr(ln, "WARNING: ThreadSanitizer") || strstr(ln, "ERROR: AddressSanitizer") ||
                                  strstr(ln, "runtime error:"))) {
                    fprintf(stderr, "  -- server %d's log has a sanitizer report (%s):\n", i, path);
                    shown = 0;
                }
                if (shown >= 0) {
                    fprintf(stderr, "  %s", ln);
                    shown++;
                }
            }
            if (fp)
                fclose(fp);
        }
    }
    if (dying == 1) { /* what every live server says, for the report */
        const char *cli = getenv("TSDB_CLI") ? getenv("TSDB_CLI") : "./build/tsdb";
        for (int i = 0; i < N; i++)
            if (pids[i] > 0 && pports[i] && !stopped[i]) {
                char cmd[PATH_MAX * 2 + 128];
                snprintf(cmd, sizeof cmd, "%s cluster status 127.0.0.1:%d --secret-file %s 1>&2", cli, pports[i],
                         secret_path);
                fprintf(stderr, "  -- server %d:\n", i);
                if (system(cmd) != 0)
                    fprintf(stderr, "  (no status)\n");
            }
    }
    for (int i = 0; i < N; i++)
        if (pids[i] > 0)
            kill(pids[i], SIGKILL);
    exit(1);
}

/* signals only a child this test started: never pid 0 or -1 (AGENTS.md) */
static void signal_child(pid_t pid, int sig)
{
    if (pid <= 0)
        die("refusing to signal pid %d", (int)pid);
    kill(pid, sig);
}

static uint64_t now_ms(void);
static void await_log(int i, const char *needle, int ms, const char *what);

/* Whether every thread of pid is in the group stop (state T in /proc/PID/task/TID/stat); names the first that is not
 * in busy, and sets *gone when the process itself is a zombie (it exited before the pause). io_uring's kernel workers
 * (iou-wrk-*, iou-sqp-*) are not counted: they need not enter the group stop and may still complete I/O queued before
 * it, so "stopped" does not cover io_uring-driven paths (tsdbd's client loop); a replica's repld and peer links use
 * plain calls and stop with the process. */
static int all_threads_stopped(pid_t pid, char *busy, size_t n, int *gone)
{
    *gone = 0;
#ifdef __linux__
    char path[64];
    snprintf(path, sizeof path, "/proc/%d/task", (int)pid);
    DIR *d = opendir(path);
    if (!d) {
        snprintf(busy, n, "no %s: %s", path, strerror(errno));
        return 0;
    }
    int ok = 1, seen = 0;
    struct dirent *e;
    while (ok && (e = readdir(d))) {
        if (e->d_name[0] == '.')
            continue;
        char sp[300], buf[512];
        snprintf(sp, sizeof sp, "/proc/%d/task/%s/stat", (int)pid, e->d_name);
        int fd = open(sp, O_RDONLY);
        if (fd < 0)
            continue; /* the thread exited */
        ssize_t got = read(fd, buf, sizeof buf - 1);
        close(fd);
        if (got <= 0)
            continue;
        buf[got] = 0;
        char *open_p = strchr(buf, '('), *close_p = strrchr(buf, ')');
        if (!open_p || !close_p || close_p[1] != ' ')
            continue;
        *close_p = 0;
        if (!strncmp(open_p + 1, "iou-", 4))
            continue;
        seen++;
        if (close_p[2] == 'Z' && atoi(e->d_name) == (int)pid)
            *gone = 1;
        if (close_p[2] != 'T') {
            snprintf(busy, n, "thread %.20s (%.32s) in state %c", e->d_name, open_p + 1, close_p[2]);
            ok = 0;
        }
    }
    closedir(d);
    if (ok && !seen) {
        snprintf(busy, n, "no thread of %d listed", (int)pid);
        ok = 0;
    }
    return ok;
#else
    (void)pid;
    (void)busy;
    (void)n;
    return 1; /* no /proc: the stop is only as certain as the signal (docs/tasks/macos.md) */
#endif
}

/* SIGSTOP is not a stop when kill() returns: the kernel wakes ONE thread to take the signal, and only that thread,
 * once it runs, stops the others. Until then every other thread of the server runs on (on a loaded machine for ms or
 * more): a replica "paused" before a write could still receive, log and acknowledge it (closegone-above checks that
 * no replica wrote after its pause returned). So a pause returns only once every thread is stopped.
 * TEST_CLUSTER_PAUSE_NOWAIT=1 returns right after kill(), as the old harness did; TEST_CLUSTER_PAUSE_TRACE=1 logs
 * what was still running (with NOWAIT that one look at /proc delays the return, which narrows the window). */
static void pause_server(int i, int on)
{
    signal_child(pids[i], on ? SIGSTOP : SIGCONT);
    stopped[i] = on;
    if (!on)
        return;
    const char *nw = getenv("TEST_CLUSTER_PAUSE_NOWAIT"), *tr = getenv("TEST_CLUSTER_PAUSE_TRACE");
    int nowait = nw && *nw == '1', trace = tr && *tr == '1';
    if (nowait && !trace)
        return;
    char busy[160] = "", first[160] = "";
    uint64_t t0 = now_ms();
    int polls = 0, gone;
    while (!all_threads_stopped(pids[i], busy, sizeof busy, &gone)) {
        if (gone) { /* a crash point or a fail-stop: name the exit, never wait 10 s for a stop that cannot come */
            int st = 0;
            if (waitpid(pids[i], &st, WNOHANG) == pids[i]) {
                pids[i] = 0;
                stopped[i] = 0;
                die("server %d exited (status 0x%x) before its pause", i, st);
            }
            die("server %d (pid %d) is a zombie before its pause", i, (int)pids[i]);
        }
        if (!polls++)
            snprintf(first, sizeof first, "%s", busy);
        if (nowait)
            break;
        if (now_ms() - t0 > 10000)
            die("server %d (pid %d) not stopped 10 s after SIGSTOP: %s", i, (int)pids[i], busy);
        nanosleep(&(struct timespec){0, 200000}, NULL);
    }
    if (trace)
        fprintf(stderr, "  pause server %d (pid %d): %s after %d polls, %" PRIu64 " ms%s%s\n", i, (int)pids[i],
                nowait ? "not waited" : "every thread stopped", polls, now_ms() - t0, *first ? "; at first " : "",
                first);
}

static uint64_t now_ms(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
}

static void server_dir(int i, char *out, size_t n) { snprintf(out, n, "%s/n%d", base, i); }

static int auth_on[N]; /* server i runs with login (no --no-auth): its root has USERS */
/* Servers run with TSDB_REPLICA_READS=1 (replicas holding a lease answer reads, so a scenario can count a replica's
 * rows) unless a scenario sets strict_reads: then every read goes to the leader (D5), as in production. */
static int strict_reads;
static int fwd_on; /* the servers forward requests for volumes led elsewhere (tsdbd's default; else --forward off) */
static int epoll_after_two; /* D15: io_uring on at most two servers (0 and 1), epoll on the rest (22-node scenarios) */
static int cports[N];  /* the client port of server i */

/* Forks and execs server i; writes its portfile path into pf (size pfn) and records pids[i]. */
static pid_t spawn_server(int i, char *pf, size_t pfn)
{
    char dir[PATH_MAX + 80], log[PATH_MAX + 80], flag[64];
    server_dir(i, dir, sizeof dir);
    snprintf(log, sizeof log, "%s/n%d.log", base, i);
    th_portfile(pf, pfn, dir);
    th_follow_me(flag, sizeof flag);
    const char *bin = getenv("TSDBD") ? getenv("TSDBD") : "./build/tsdbd";
    pid_t pid = fork();
    if (pid < 0)
        die("fork: %s", strerror(errno));
    if (pid == 0) {
        int fd = open(log, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (fd >= 0)
            dup2(fd, 2);
        if (strict_reads)
            unsetenv("TSDB_REPLICA_READS");
        else
            setenv("TSDB_REPLICA_READS", "1", 1);
        if (envs[i])
            setenv("TSDB_CLUSTER_TEST", envs[i], 1);
        else
            unsetenv("TSDB_CLUSTER_TEST");
        char penvbuf[PATH_MAX * 2 + 256];
        snprintf(penvbuf, sizeof penvbuf, "%s", penv[i] ? penv[i] : "");
        for (char *t = strtok(penvbuf, " "); t; t = strtok(NULL, " ")) {
            char *eq = strchr(t, '=');
            if (eq) {
                *eq = 0;
                setenv(t, eq + 1, 1);
            }
        }
        char state[PATH_MAX + 90];
        snprintf(state, sizeof state, "%s/state", dir);
        const char *argv[64];
        int n = 0;
        argv[n++] = "tsdbd";
        if (!auth_on[i])
            argv[n++] = "--no-auth";
        argv[n++] = flag;
        if (is_witness[i])
            argv[n++] = "--witness";
        else {
            argv[n++] = "--dir";
            argv[n++] = dir;
            argv[n++] = "--port";
            argv[n++] = "0";
        }
        argv[n++] = "--port-file";
        argv[n++] = pf;
        argv[n++] = "--cluster";
        argv[n++] = "--cluster-secret-file";
        argv[n++] = secret_path;
        argv[n++] = "--state-dir";
        argv[n++] = state;
        if (!fwd_on) { /* the scenarios written before forwarding (S2-2) judge s2e's MOVED off the leader */
            argv[n++] = "--forward";
            argv[n++] = "off";
        }
        if (epoll_after_two && i >= 2 && !is_witness[i]) {
            argv[n++] = "--io";
            argv[n++] = "epoll";
        } else if (getenv("TSDBD_IO") && !is_witness[i]) { /* as test_server: epoll or uring (default: tsdbd's choice) */
            argv[n++] = "--io";
            argv[n++] = getenv("TSDBD_IO");
        }
        if (getenv("TSDB_CLUSTER_PEER_RDMA") && *getenv("TSDB_CLUSTER_PEER_RDMA")) {
            argv[n++] = "--peer-rdma";
            argv[n++] = getenv("TSDB_CLUSTER_PEER_RDMA");
        }
        if (getenv("TSDB_CLUSTER_PEER_RDMA_POOL_MB") && *getenv("TSDB_CLUSTER_PEER_RDMA_POOL_MB")) {
            argv[n++] = "--peer-rdma-pool-mb";
            argv[n++] = getenv("TSDB_CLUSTER_PEER_RDMA_POOL_MB");
        }
        if (getenv("TSDB_CLUSTER_PEER_RDMA_DEV") && *getenv("TSDB_CLUSTER_PEER_RDMA_DEV")) {
            argv[n++] = "--peer-rdma-device";
            argv[n++] = getenv("TSDB_CLUSTER_PEER_RDMA_DEV");
        }
        char extra[PATH_MAX + 512];
        snprintf(extra, sizeof extra, "%s", xargs[i] ? xargs[i] : "");
        for (char *t = strtok(extra, " "); t && n < 60; t = strtok(NULL, " "))
            argv[n++] = t;
        argv[n] = NULL;
        execv(bin, (char *const *)argv);
        _exit(127);
    }
    pids[i] = pid;
    stopped[i] = 0;
    return pid;
}

/* Starts server i; returns th_await's answer (the client port, or TH_EXITED with th_status, or TH_BAD). */
static int start_try(int i)
{
    char pf[PATH_MAX + 128];
    pid_t pid = spawn_server(i, pf, sizeof pf);
    int port = th_await(pf, pid, 20000);
    if (port == TH_EXITED)
        pids[i] = 0; /* reaped */
    return port;
}

static void start(int i)
{
    int port = start_try(i);
    if (port <= 0)
        die("server %d: %s", i, th_why);
    __atomic_store_n(&cports[i], port, __ATOMIC_RELAXED); /* the transfer writers read it while a server restarts */
    if (!th_pport)
        die("server %d: the port file names no peer port", i);
    pports[i] = th_pport;
}

/* Starts the servers named by idxs[0..count-1] in parallel (fork all first, then poll all port files together). */
static void start_many(const int *idxs, int count)
{
    static char pf[N][PATH_MAX + 128];
    int ready[N] = {0}, left = count;
    for (int k = 0; k < count; k++)
        spawn_server(idxs[k], pf[k], sizeof pf[k]);
    uint64_t t0 = now_ms();
    while (left > 0 && now_ms() - t0 < 45000) {
        for (int k = 0; k < count; k++) {
            if (ready[k])
                continue;
            int i = idxs[k];
            pid_t child = pids[i];
            int st = 0;
            if (waitpid(child, &st, WNOHANG) == child) {
                pids[i] = 0;
                die("server %d (pid %d) exited (status 0x%x) before it listened", i, (int)child, st);
            }
            FILE *f = fopen(pf[k], "r");
            if (!f)
                continue;
            int port = 0, pid = 0, mport = 0, pport = 0;
            int n = fscanf(f, "%d %d %d %d", &port, &pid, &mport, &pport);
            fclose(f);
            if (n < 2 || port <= 0)
                continue;
            if (pid != (int)child)
                die("server %d: %s names pid %d, expected %d", i, pf[k], pid, (int)child);
            if (!th_owns_port(child, port) || (n >= 3 && mport && !th_owns_port(child, mport)) ||
                (n == 4 && !th_owns_port(child, pport)))
                continue;
            if (n != 4 || !pport)
                die("server %d: the port file names no peer port", i);
            __atomic_store_n(&cports[i], port, __ATOMIC_RELAXED);
            pports[i] = pport;
            ready[k] = 1;
            left--;
        }
        if (left > 0)
            usleep(10000);
    }
    if (left > 0) {
        for (int k = 0; k < count; k++)
            if (!ready[k])
                die("server %d (pid %d) wrote no %s within 45000 ms", idxs[k], (int)pids[idxs[k]], pf[k]);
    }
}

static void start_range(int count)
{
    int idxs[N];
    for (int i = 0; i < count; i++)
        idxs[i] = i;
    start_many(idxs, count);
}

/* Check FD, memory, and scratch-disk limits before launching many nodes (e.g. 22 for ec16); refuses clearly if low. */
static void check_host_limits(int nnodes)
{
    rlim_t need_fds = (rlim_t)(nnodes > 8 ? 4096 : 1024);
    struct rlimit rl;
    if (getrlimit(RLIMIT_NOFILE, &rl) == 0 && rl.rlim_cur < need_fds) {
        rlim_t want = (rl.rlim_max == RLIM_INFINITY || need_fds <= rl.rlim_max) ? need_fds : rl.rlim_max;
        if (want > rl.rlim_cur) {
            struct rlimit nr = {want, rl.rlim_max};
            (void)setrlimit(RLIMIT_NOFILE, &nr);
            (void)getrlimit(RLIMIT_NOFILE, &rl);
        }
        if (rl.rlim_cur < need_fds)
            die("refused: RLIMIT_NOFILE is %llu (hard %llu), %d nodes need at least %llu (raise with ulimit -n)",
                (unsigned long long)rl.rlim_cur, (unsigned long long)rl.rlim_max, nnodes,
                (unsigned long long)need_fds);
    }
    if (getrlimit(RLIMIT_AS, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY && rl.rlim_cur < (256ULL << 20))
        die("refused: RLIMIT_AS is %llu MiB, need at least 256 MiB", (unsigned long long)(rl.rlim_cur >> 20));
    FILE *mf = fopen("/proc/meminfo", "r");
    if (mf) {
        char ln[256];
        uint64_t avail_kb = 0, free_kb = 0;
        while (fgets(ln, sizeof ln, mf)) {
            unsigned long long v = 0;
            if (sscanf(ln, "MemAvailable: %llu kB", &v) == 1)
                avail_kb = (uint64_t)v;
            else if (sscanf(ln, "MemFree: %llu kB", &v) == 1)
                free_kb = (uint64_t)v;
        }
        fclose(mf);
        uint64_t mb = (avail_kb ? avail_kb : free_kb) / 1024;
        uint64_t need_mb = (uint64_t)nnodes * 64;
        if (mb && mb < need_mb)
            die("refused: only %" PRIu64 " MiB RAM available, %d nodes need at least %" PRIu64 " MiB", mb, nnodes,
                need_mb);
    }
    struct statvfs sv;
    if (statvfs(base, &sv) == 0) {
        uint64_t avail_mb = ((uint64_t)sv.f_bavail * (uint64_t)sv.f_frsize) >> 20;
        uint64_t need_disk_mb = (uint64_t)nnodes * 16;
        if (avail_mb < need_disk_mb)
            die("refused: only %" PRIu64 " MiB free on %s, %d nodes need at least %" PRIu64 " MiB", avail_mb, base,
                nnodes, need_disk_mb);
    }
}

static void stop(int i, int sig)
{
    if (stopped[i])
        pause_server(i, 0);
    signal_child(pids[i], sig);
    int status;
    if (waitpid(pids[i], &status, 0) != pids[i])
        die("waitpid %d: %s", (int)pids[i], strerror(errno));
    if (sig == SIGTERM && !(WIFEXITED(status) && WEXITSTATUS(status) == 0))
        die("server %d did not stop cleanly on SIGTERM (status 0x%x)", i, status);
    pids[i] = 0;
}

/* waits up to ms for server i to exit on its own: its exit status (128 + signal), or -1 when it did not */
static int await_exit(int i, int ms)
{
    uint64_t t0 = now_ms();
    for (;;) {
        int st;
        pid_t r = waitpid(pids[i], &st, WNOHANG);
        if (r == pids[i]) {
            pids[i] = 0;
            return WIFEXITED(st) ? WEXITSTATUS(st) : 128 + WTERMSIG(st);
        }
        if (r < 0)
            die("waitpid %d: %s", (int)pids[i], strerror(errno));
        if (now_ms() - t0 > (uint64_t)ms)
            return -1;
        usleep(50000);
    }
}

static int log_has(int i, const char *needle)
{
    char path[PATH_MAX + 80];
    snprintf(path, sizeof path, "%s/n%d.log", base, i);
    FILE *f = fopen(path, "r");
    if (!f)
        return 0;
    char line[4096];
    int hit = 0;
    while (!hit && fgets(line, sizeof line, f))
        hit = strstr(line, needle) != NULL;
    fclose(f);
    return hit;
}

static uint32_t isr_of(int via, const char *name, uint64_t *version);
static void await_isr(int via, const char *name, uint32_t n, int ms, const char *what);
static uint64_t tr_count(int i, int which);

/* stops every live server in parallel (SIGTERM, status 0) and starts a new scenario in its own directory */
static void stop_all(void)
{
    for (int i = 0; i < N; i++)
        if (pids[i] > 0) {
            if (stopped[i])
                pause_server(i, 0);
            signal_child(pids[i], SIGTERM);
        }
    for (int i = 0; i < N; i++)
        if (pids[i] > 0) {
            int status;
            if (waitpid(pids[i], &status, 0) != pids[i])
                die("waitpid %d: %s", (int)pids[i], strerror(errno));
            if (!(WIFEXITED(status) && WEXITSTATUS(status) == 0))
                die("server %d did not stop cleanly on SIGTERM (status 0x%x)", i, status);
            pids[i] = 0;
        }
}

static uint32_t init_rebuild_after_s, init_failstop_out_s, init_opening_hold_s, init_out_guard_pct,
    init_out_guard_hold_s, init_voters; /* r9-out / r9-ops scenarios (0: default) */

static void scenario(const char *name)
{
    stop_all();
    scen = name;
    memset(ids, 0, sizeof ids);
    memset(pports, 0, sizeof pports);
    memset(stopped, 0, sizeof stopped);
    memset(envs, 0, sizeof envs);
    memset(xargs, 0, sizeof xargs);
    memset(penv, 0, sizeof penv);
    strict_reads = 0;
    fwd_on = 0;
    epoll_after_two = 0;
    init_rebuild_after_s = 0;
    init_failstop_out_s = 0;
    init_opening_hold_s = 0;
    init_out_guard_pct = 0;
    init_out_guard_hold_s = 0;
    init_voters = 0;
    memset(is_witness, 0, sizeof is_witness);
    memset(auth_on, 0, sizeof auth_on);
    snprintf(base, sizeof base, "%s/%s", root, name);
    if (mkdir(base, 0755) != 0)
        die("mkdir %s: %s", base, strerror(errno));
    printf(" %s\n", name);
    fflush(stdout);
}

static void peer_of(int i, char *out, size_t n) { snprintf(out, n, "127.0.0.1:%d", pports[i]); }

/* One admin op to server i; follows NOTLEADER once when `follow`. Returns the op's result; dies when unreachable.
 * The deadline is 30 s: the five servers of a scenario under AddressSanitizer on a machine that other gates keep busy
 * answered a STATUS after more than 10 s (test-trust gate tt4-asan: "closed the connection" at [feed], the deadline
 * of the handshake passing between its two halves); a hung server is the watchdog's to end, not this deadline's. */
static int admin(int i, int op, const void *req, size_t rl, int follow, uint8_t **reply, size_t *len)
{
    char target[META_ADDR_MAX + 1], err[1024];
    peer_of(i, target, sizeof target);
    for (int hop = 0;; hop++) {
        int rc;
        *reply = NULL;
        *len = 0;
        if (cluster_admin(target, secret, secret_len, op, req, rl, 30000, &rc, reply, len, err, sizeof err) != 0)
            die("admin op %d to %s: %s", op, target, err);
        if (rc == CLUSTER_ERR_NOTLEADER && follow && hop == 0 && *len > 0 && *len < sizeof target) {
            memcpy(target, *reply, *len);
            target[*len] = 0;
            free(*reply);
            continue;
        }
        return rc;
    }
}

struct view {
    struct cluster_status st;
    struct meta_state m;
    raft_config cfg;
    uint8_t *raw;
};

static void view_free(struct view *v)
{
    cluster_status_free(&v->st);
    meta_free(&v->m);
    free(v->raw);
}

/* STATUS of server i, its image decoded (an empty image leaves m empty) */
static void view(int i, struct view *v)
{
    size_t len;
    memset(v, 0, sizeof *v);
    meta_init(&v->m);
    int rc = admin(i, CLUSTER_OP_STATUS, NULL, 0, 0, &v->raw, &len);
    if (rc != 0)
        die("status of server %d: %s", i, cluster_strerror(rc));
    if (cluster_status_parse(v->raw, len, &v->st) != 0)
        die("status of server %d does not parse", i);
    if (v->st.image_len && meta_snapshot_decode(&v->m, v->st.image, v->st.image_len) != META_OK)
        die("the image of server %d does not decode", i);
    if (v->m.config_len && !raft_config_decode(v->m.config, v->m.config_len, &v->cfg))
        die("the configuration of server %d does not decode", i);
}

static unsigned voters(const struct view *v) { return raft_config_voters(&v->cfg); }

static int is_voter(const struct view *v, uint32_t id)
{
    const raft_member *m = raft_config_find(&v->cfg, id);
    return m && !m->learner;
}

static int leader_index(const struct view *v)
{
    for (int i = 0; i < N; i++)
        if (pids[i] > 0 && ids[i] && ids[i] == v->st.leader)
            return i;
    return -1;
}

/* Waits until `pred` holds for the view of server i (polling every 100 ms); dies naming `what` after ms. */
static void await_view_ms(int i, int (*pred)(const struct view *, void *), void *arg, const char *what, int ms)
{
    uint64_t t0 = now_ms();
    for (;;) {
        struct view v;
        view(i, &v);
        int ok = pred(&v, arg);
        uint64_t applied = v.st.applied, commit = v.st.commit;
        uint32_t leader = v.st.leader;
        unsigned nv = voters(&v);
        view_free(&v);
        if (ok)
            return;
        if (now_ms() - t0 > (uint64_t)ms)
            die("server %d: %s did not happen within %d ms (commit %" PRIu64 ", applied %" PRIu64 ", leader %" PRIu32
                ", %u voters)",
                i, what, ms, commit, applied, leader, nv);
        usleep(100000);
    }
}

static void await_view(int i, int (*pred)(const struct view *, void *), void *arg, const char *what)
{
    await_view_ms(i, pred, arg, what, WAIT_MS);
}

static int p_leader_self(const struct view *v, void *a)
{
    (void)a;
    return v->st.mode == CLUSTER_MODE_CORE && v->st.role == RAFT_LEADER && v->st.leader == v->st.self &&
           v->m.initialised;
}

static int p_voters(const struct view *v, void *a)
{
    return v->st.mode == CLUSTER_MODE_CORE && v->st.role == RAFT_LEADER && voters(v) == *(unsigned *)a &&
           v->cfg.n == *(unsigned *)a; /* no learner left over */
}

struct state_want {
    uint32_t id;
    int state;
    uint64_t min_incarnation;
};
static int p_member_state(const struct view *v, void *a)
{
    const struct state_want *w = a;
    const struct meta_member *mb = meta_member(&v->m, w->id);
    return mb && mb->state == w->state && mb->incarnation >= w->min_incarnation;
}

struct catch_up {
    uint64_t applied, hash;
};
static int p_caught_up(const struct view *v, void *a)
{
    const struct catch_up *c = a;
    /* not stale: a restarted voter shows its persisted copy, equal to the leader's, until its core has applied that far */
    return !v->st.stale && v->st.applied >= c->applied && v->m.applied >= c->applied &&
           (v->m.applied != c->applied || meta_hash(&v->m) == c->hash);
}

static size_t node_add_req(int newi, uint8_t *req)
{
    char np[META_ADDR_MAX];
    peer_of(newi, np, sizeof np);
    size_t n = strlen(np);
    req[0] = (uint8_t)n;
    req[1] = (uint8_t)(n >> 8);
    memcpy(req + 2, np, n);
    return n + 2;
}

static void node_add(int via, int newi)
{
    char np[META_ADDR_MAX];
    peer_of(newi, np, sizeof np);
    uint8_t req[META_ADDR_MAX + 2];
    size_t n = node_add_req(newi, req);
    uint8_t *reply;
    size_t len;
    int rc = admin(via, CLUSTER_OP_NODE_ADD, req, n, 1, &reply, &len);
    free(reply);
    if (rc != 0)
        die("node add of server %d through server %d: %s", newi, via, cluster_strerror(rc));
    /* its id: the member whose peer address is the new server's */
    struct view v;
    view(via, &v);
    for (uint32_t k = 0; k < v.m.nmembers; k++)
        if (!strcmp(v.m.members[k].peer, np))
            ids[newi] = v.m.members[k].id;
    view_free(&v);
    if (!ids[newi]) {
        /* `via` may be a watcher a little behind: ask the new server itself */
        uint64_t t0 = now_ms();
        while (!ids[newi] && now_ms() - t0 < WAIT_MS) {
            view(newi, &v);
            if (v.st.self && v.st.mode != CLUSTER_MODE_NONE)
                ids[newi] = v.st.self;
            view_free(&v);
            usleep(100000);
        }
    }
    if (!ids[newi])
        die("server %d got no member id", newi);
    printf("  server %d joined as member %" PRIu32 "\n", newi, ids[newi]);
}

static uint32_t init_min_isr; /* nonzero: INIT's min_isr (the volumes' min_isr, at most their replicas) */
static uint32_t init_node_timeout_ms; /* > 0: init_mode sets node_timeout to this instead of 1.5 s */
static uint32_t init_heartbeat_ms;    /* > 0: init_mode sets heartbeat_ms to this instead of 200 ms */
static uint32_t init_retain_s; /* nonzero: INIT's repl_retain_s */
static uint32_t init_retain_down_gb; /* when init_retain_down_set: INIT's repl_retain_down_gb */
static int init_retain_down_set;
static int init_r4_set; /* nonzero: INIT's four settings of R4 off their defaults (snapversion reads them back) */
static uint32_t init_isr_lag_ms; /* nonzero: INIT's isr_lag_ms */
static uint32_t init_rebuild_mb_s, init_rebuild_max; /* nonzero: INIT's rebuild_mb_s, rebuild_max */

static uint32_t init_transfer_wait_ms, init_leader_balance_s; /* r4-transfer's scenarios (0: the default) */

/* INIT on server i with fast timings (down after 1.5 s, a dead voter replaced after replace_s); it leads */
static void init_mode(int i, uint32_t replace_s, int mode)
{
    struct meta_settings s;
    meta_settings_default(&s);
    if (init_min_isr)
        s.min_isr = init_min_isr;
    if (init_retain_s) {
        s.repl_retain_s = init_retain_s;
        /* R3/R4 scenarios set init_retain_s to force snapshot catch-up; disable DOWN retention unless opted in. */
        if (!init_retain_down_set)
            s.repl_retain_down_gb = 0;
    }
    if (init_retain_down_set)
        s.repl_retain_down_gb = init_retain_down_gb;
    if (init_isr_lag_ms)
        s.isr_lag_ms = init_isr_lag_ms;
    if (init_rebuild_mb_s)
        s.rebuild_mb_s = init_rebuild_mb_s;
    if (init_rebuild_max)
        s.rebuild_max = init_rebuild_max;
    s.node_timeout_ms = init_node_timeout_ms ? init_node_timeout_ms : 1500;
    s.heartbeat_ms = init_heartbeat_ms ? init_heartbeat_ms : 200;
    s.voter_replace_s = replace_s;
    if (init_transfer_wait_ms)
        s.transfer_wait_ms = init_transfer_wait_ms;
    if (init_leader_balance_s)
        s.leader_balance_s = init_leader_balance_s;
    if (init_rebuild_after_s)
        s.rebuild_after_s = init_rebuild_after_s;
    if (init_failstop_out_s)
        s.failstop_out_s = init_failstop_out_s;
    if (init_opening_hold_s)
        s.opening_hold_s = init_opening_hold_s;
    if (init_out_guard_pct)
        s.out_guard_pct = init_out_guard_pct;
    if (init_out_guard_hold_s)
        s.out_guard_hold_s = init_out_guard_hold_s;
    if (init_voters)
        s.voters = init_voters;
    if (init_r4_set) {
        s.rebuild_mb_s = 300;
        s.rebuild_max = 3;
        s.transfer_wait_ms = 2500;
        s.leader_balance_s = 60;
    }
    uint8_t req[4 * (META_SETTINGS_WORDS + 1)], *reply;
    size_t len;
    size_t rl = cluster_settings_encode(&s, mode, req);
    int rc = admin(i, CLUSTER_OP_INIT, req, rl, 0, &reply, &len);
    free(reply);
    if (rc != 0)
        die("init: %s", cluster_strerror(rc));
    ids[i] = 1;
    await_view(i, p_leader_self, NULL, "leading the initialised cluster");
}

static void init_cluster(int i, uint32_t replace_s) { init_mode(i, replace_s, META_MODE_REPLICATED); }
static void init_fast(int i) { init_cluster(i, 3); }

/* A core member names the leader once it has heard from it: a restarted voter whose own snapshot is already at the
 * leader's index is caught up before the first heartbeat reaches it, and names no leader (0) until then. */
static int p_names_leader(const struct view *v, void *a)
{
    return v->st.mode != CLUSTER_MODE_CORE || v->st.leader == *(const uint32_t *)a;
}

/* Every live server's STATUS agrees on the leader and, once caught up, on the state (meta_hash). */
static void check_all_agree(int leader_i, uint32_t members)
{
    struct view lv;
    view(leader_i, &lv);
    struct catch_up c = {lv.m.applied, meta_hash(&lv.m)};
    uint32_t leader = lv.st.leader;
    view_free(&lv);
    for (int i = 0; i < N; i++) {
        if (pids[i] <= 0)
            continue;
        await_view(i, p_caught_up, &c, "catching up with the leader's state");
        await_view(i, p_names_leader, &leader, "naming the leader");
        struct view v;
        view(i, &v);
        if (v.st.self != ids[i])
            die("server %d says it is member %" PRIu32 ", expected %" PRIu32, i, v.st.self, ids[i]);
        if (v.st.mode == CLUSTER_MODE_CORE && v.st.leader != leader)
            die("server %d (core) names leader %" PRIu32 ", the leader says %" PRIu32, i, v.st.leader, leader);
        if (members && v.m.nmembers != members)
            die("server %d sees %" PRIu32 " members, expected %" PRIu32, i, v.m.nmembers, members);
        /* no stalled disk here: a leader that hands leadership on has misread a sync as stalled (the clock read
         * before the sync began made its age 2^64 - x: has1-cl6, leadership flapping and a reseed that never ended) */
        if (log_has(i, "handing leadership"))
            die("server %d handed leadership on although no disk stalled", i);
        view_free(&v);
    }
}

static void cli_status(int i, int members)
{
    const char *cli = getenv("TSDB_CLI") ? getenv("TSDB_CLI") : "./build/tsdb";
    char cmd[PATH_MAX * 2 + 128], peer[META_ADDR_MAX], line[1024];
    peer_of(i, peer, sizeof peer);
    snprintf(cmd, sizeof cmd, "%s cluster status %s --secret-file %s", cli, peer, secret_path);
    /* the peer links' lines ("peer links KIND: none N header N full N") come once the forwarding links to the
     * members are up, which the members' own dials decide: asked again until one is there (a promised state) */
    for (uint64_t until = now_ms() + 20000;;) {
        FILE *p = popen(cmd, "r");
        if (!p)
            die("popen %s: %s", cmd, strerror(errno));
        int node = 0, group = 0, up = 0, links = 0;
        while (fgets(line, sizeof line, p)) {
            node += !strncmp(line, "node ", 5);
            group += !strncmp(line, "group voters ", 13);
            up += !strncmp(line, "member ", 7) && strstr(line, " up ");
            if (!strncmp(line, "peer links ", 11)) {
                char kind[16];
                unsigned a, b, c;
                if (sscanf(line, "peer links %15[a-z]: none %u header %u full %u", kind, &a, &b, &c) != 4)
                    die("`%s`: a peer links line that does not parse: %s", cmd, line);
                links += !strcmp(kind, "fwd") && a > 0 && b == 0 && c == 0; /* none, the default level */
            }
        }
        int st = pclose(p);
        if (st != 0 || node != 1 || group != 1 || up != members)
            die("`%s`: status %d, %d node, %d group, %d up member lines (expected 0, 1, 1, %d)", cmd, st, node, group,
                up, members);
        if (links == 1)
            break;
        if (now_ms() > until)
            die("`%s`: no line \"peer links fwd: none N header 0 full 0\" with N > 0 in 20 s", cmd);
        usleep(200 * 1000);
    }
}

/* the leader as server i's view names it, or -1 */
static int leader_of(int i)
{
    struct view v;
    view(i, &v);
    int l = leader_index(&v);
    view_free(&v);
    return l;
}

/* ------------------------------------------------------------------ raw links (the relay, long frames) */

static int dial_peer(int i)
{
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
    struct sockaddr_in a = {.sin_family = AF_INET, .sin_port = htons((uint16_t)pports[i])};
    a.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    if (fd < 0 || connect(fd, (struct sockaddr *)&a, sizeof a) != 0)
        die("connect to server %d: %s", i, strerror(errno));
    return fd;
}

static void send_all(int fd, const void *p, size_t n)
{
    const uint8_t *b = p;
    while (n) {
        ssize_t w = send(fd, b, n, MSG_NOSIGNAL);
        if (w < 0 && errno == EINTR)
            continue;
        if (w <= 0)
            return; /* the other side closed: what the caller checks next */
        b += w;
        n -= (size_t)w;
    }
}

/* 0, -1 at EOF or an error, -2 after ms */
static int read_full(int fd, void *p, size_t n, int ms)
{
    uint64_t end = now_ms() + (uint64_t)ms;
    size_t got = 0;
    while (got < n) {
        uint64_t t = now_ms();
        if (t >= end)
            return -2;
        struct pollfd pf = {.fd = fd, .events = POLLIN};
        int r = poll(&pf, 1, (int)(end - t));
        if (r < 0 && errno == EINTR)
            continue;
        if (r == 0)
            return -2;
        ssize_t k = read(fd, (uint8_t *)p + got, n - got);
        if (k < 0 && errno == EINTR)
            continue;
        if (k <= 0)
            return -1;
        got += (size_t)k;
    }
    return 0;
}

/* one whole frame, its length prefix included: 0, -1 (closed), -2 (nothing within ms) */
static int raw_frame(int fd, int ms, uint8_t **f, size_t *flen)
{
    uint8_t h[4];
    int r = read_full(fd, h, 4, ms);
    if (r)
        return r;
    uint32_t n = (uint32_t)h[0] | (uint32_t)h[1] << 8 | (uint32_t)h[2] << 16 | (uint32_t)h[3] << 24;
    if (n == 0 || n > (1u << 24))
        return -1;
    *f = malloc(4 + (size_t)n);
    if (!*f)
        die("out of memory");
    memcpy(*f, h, 4);
    r = read_full(fd, *f + 4, n, ms);
    if (r) {
        free(*f);
        return r;
    }
    *flen = 4 + (size_t)n;
    return 0;
}

static void frame_len(uint8_t *f, size_t flen)
{
    uint32_t n = (uint32_t)(flen - 4);
    for (int k = 0; k < 4; k++)
        f[k] = (uint8_t)(n >> (8 * k));
}

/* Reads frames from fd until it closes. 1 when an ADMIN_REPLY came, 0 when it closed without one, 2 when it stayed
 * open for ms. */
static int closes_without_reply(int fd, int ms)
{
    uint64_t end = now_ms() + (uint64_t)ms;
    for (;;) {
        uint64_t t = now_ms();
        if (t >= end)
            return 2;
        uint8_t *f;
        size_t fl;
        int r = raw_frame(fd, (int)(end - t), &f, &fl);
        if (r == -1)
            return 0;
        if (r == -2)
            return 2;
        int reply = f[4] == W_ADMIN_REPLY;
        free(f);
        if (reply)
            return 1;
    }
}

/* forwards bytes both ways until one side closes or ms pass */
static void pump_both(int a, int b, int ms)
{
    uint64_t end = now_ms() + (uint64_t)ms;
    uint8_t buf[65536];
    while (now_ms() < end) {
        struct pollfd pf[2] = {{.fd = a, .events = POLLIN}, {.fd = b, .events = POLLIN}};
        int r = poll(pf, 2, 100);
        if (r < 0 && errno != EINTR)
            return;
        for (int k = 0; k < 2; k++)
            if (pf[k].revents) {
                ssize_t n = read(pf[k].fd, buf, sizeof buf);
                if (n <= 0)
                    return;
                send_all(pf[1 - k].fd, buf, (size_t)n);
            }
    }
}

enum { RELAY_PLAIN, RELAY_CLAIM, RELAY_SWAP };

/* A CLI (a child process) asks STATUS of a relay this test runs, which connects to server `target`. RELAY_PLAIN
 * forwards everything: the CLI gets its answer (the control: the relay itself works). RELAY_CLAIM rewrites the CLI's
 * HELLO to claim member `cid` (its uuid, identity and peer address, with the CLI's own nonce) and passes the answer
 * back: the CLI must refuse it, and the server must answer nothing the relay sends after it. RELAY_SWAP forwards the
 * handshake as it is and puts a request of its own in place of the CLI's (with the CLI's tag): the server must close
 * the link without an answer. Returns the CLI's exit status (0: it got a STATUS reply). */
static int relay(int target, int mode, const struct view *v, uint32_t cid)
{
    int ls = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
    struct sockaddr_in a = {.sin_family = AF_INET};
    a.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    socklen_t al = sizeof a;
    if (ls < 0 || bind(ls, (struct sockaddr *)&a, sizeof a) != 0 || listen(ls, 4) != 0 ||
        getsockname(ls, (struct sockaddr *)&a, &al) != 0)
        die("relay socket: %s", strerror(errno));
    pid_t kid = fork();
    if (kid < 0)
        die("fork: %s", strerror(errno));
    if (kid == 0) {
        char addr[64], err[512];
        snprintf(addr, sizeof addr, "127.0.0.1:%d", ntohs(a.sin_port));
        int rc;
        uint8_t *rep = NULL;
        size_t rl;
        int r = cluster_admin(addr, secret, secret_len, CLUSTER_OP_STATUS, NULL, 0, 3000, &rc, &rep, &rl, err,
                              sizeof err);
        _exit(r == 0 && rc == 0 ? 0 : 2);
    }
    struct pollfd pf = {.fd = ls, .events = POLLIN};
    if (poll(&pf, 1, 5000) != 1)
        die("the CLI did not connect to the relay");
    int cli = accept(ls, NULL, NULL);
    close(ls);
    int srv = dial_peer(target);
    uint8_t *f, *g;
    size_t fl, gl;
    if (cli < 0 || raw_frame(cli, 5000, &f, &fl) != 0 || f[4] != W_HELLO || fl < 80)
        die("relay: no HELLO from the CLI");
    if (mode == RELAY_CLAIM) {
        /* [len][type][magic 4][ver 1][id 4][uuid 16][ident 16][nonce 32][peer: u16 + bytes][kind 1] */
        const struct meta_member *m = meta_member(&v->m, cid);
        if (!m)
            die("relay: no member %" PRIu32, cid);
        size_t pl = strlen(m->peer);
        g = malloc(81 + pl);
        if (!g)
            die("out of memory");
        memcpy(g, f, 10);
        for (int k = 0; k < 4; k++)
            g[10 + k] = (uint8_t)(cid >> (8 * k));
        memcpy(g + 14, v->m.uuid, 16);
        memcpy(g + 30, m->ident, 16);
        memcpy(g + 46, f + 46, 32); /* the CLI's nonce */
        g[78] = (uint8_t)pl;
        g[79] = (uint8_t)(pl >> 8);
        memcpy(g + 80, m->peer, pl);
        g[80 + pl] = f[fl - 1]; /* the link kind (HELLO of protocol 4 ends with it) */
        gl = 81 + pl;
        frame_len(g, gl);
        free(f);
        f = g;
        fl = gl;
    }
    send_all(srv, f, fl);
    free(f);
    if (raw_frame(srv, 5000, &f, &fl) != 0)
        die("relay: no HELLO_ACK from server %d (mode %d)", target, mode);
    send_all(cli, f, fl);
    free(f);
    if (mode == RELAY_PLAIN) {
        pump_both(cli, srv, 5000);
    } else {
        /* what the CLI sends next: AUTH and its request (none when it refused the HELLO_ACK) */
        uint8_t *auth = NULL, *req = NULL;
        size_t authl = 0, reql = 0;
        if (raw_frame(cli, 1000, &auth, &authl) == 0 && raw_frame(cli, 1000, &req, &reql) != 0)
            req = NULL;
        if (mode == RELAY_SWAP && (!auth || !req || auth[4] != W_AUTH || req[4] != W_ADMIN || reql != 4 + 38))
            die("relay: the CLI sent no AUTH and request after a handshake passed through unchanged");
        if (!auth) {
            authl = 4 + 1 + 32;
            auth = calloc(1, authl);
            if (!auth)
                die("out of memory");
            auth[4] = W_AUTH;
            frame_len(auth, authl);
        }
        send_all(srv, auth, authl);
        /* the relay's own request: STATUS, request id 7, with the CLI's tag (or zeros) */
        uint8_t own[4 + 38] = {0};
        own[4] = W_ADMIN;
        own[5] = CLUSTER_OP_STATUS;
        own[6] = 7;
        if (req && reql == sizeof own)
            memcpy(own + 10, req + 10, 32);
        frame_len(own, sizeof own);
        if (mode == RELAY_CLAIM && req)
            send_all(srv, req, reql); /* the CLI took the forged handshake: what its own request gets shows it */
        else
            send_all(srv, own, sizeof own);
        free(auth);
        free(req);
        int r = closes_without_reply(srv, 3000);
        if (r == 1)
            die("a relayed handshake (mode %s) got an admin reply from server %d",
                mode == RELAY_CLAIM ? "claiming another member" : "with a request of the relay's", target);
        if (r == 2)
            die("server %d kept a relayed link (mode %d) open after a frame that does not authenticate", target, mode);
    }
    close(cli);
    close(srv);
    int st;
    if (waitpid(kid, &st, 0) != kid)
        die("waitpid: %s", strerror(errno));
    return WIFEXITED(st) ? WEXITSTATUS(st) : 128;
}

/* ------------------------------------------------------------------ scenarios */

static void scen_life(void)
{
    scenario("life");
    for (int i = 0; i < LIFE; i++)
        start(i);
    printf("  %d servers up\n", LIFE);

    init_fast(0);
    {
        struct meta_settings s;
        meta_settings_default(&s);
        uint8_t req[4 * (META_SETTINGS_WORDS + 1)], *reply;
        size_t len, rl = cluster_settings_encode(&s, META_MODE_REPLICATED, req);
        int rc = admin(0, CLUSTER_OP_INIT, req, rl, 0, &reply, &len);
        free(reply);
        if (rc != CLUSTER_ERR_EXISTS)
            die("a second init answered %d (%s), expected EXISTS", rc, cluster_strerror(rc));
    }
    unsigned want = 1;
    await_view(0, p_voters, &want, "one voter");
    /* a server in no cluster refuses NODE_ADD as not the leader, with no leader to name */
    {
        uint8_t r2[META_ADDR_MAX + 2], *reply;
        size_t len, n = node_add_req(2, r2);
        int rc = admin(1, CLUSTER_OP_NODE_ADD, r2, n, 0, &reply, &len);
        free(reply);
        if (rc == 0)
            die("server 1, in no cluster, accepted a NODE_ADD");
    }
    printf("  initialised; member 1 leads\n");

    node_add(0, 1);
    node_add(0, 2);
    want = 3;
    await_view(0, p_voters, &want, "three voters with three members");
    printf("  three members, three voters\n");

    /* the fourth through a member that is not the leader: NOTLEADER, then the leader */
    node_add(1, 3);
    {
        struct view v;
        view(3, &v);
        int watching = v.st.mode == CLUSTER_MODE_WATCH;
        view_free(&v);
        want = 3;
        await_view(0, p_voters, &want, "three voters with four members");
        /* with four members one watches; it is server 3 unless the leader made it a voter in place of another */
        struct view lv;
        view(0, &lv);
        int watcher = -1;
        for (int i = 0; i < 4; i++)
            if (!raft_config_find(&lv.cfg, ids[i]))
                watcher = i;
        struct catch_up c = {lv.m.applied, meta_hash(&lv.m)};
        view_free(&lv);
        if (watcher < 0)
            die("four members and no watcher");
        await_view(watcher, p_caught_up, &c, "the watcher catching up");
        view(watcher, &v);
        if (v.st.mode != CLUSTER_MODE_WATCH)
            die("server %d is in no configuration but in mode %d", watcher, v.st.mode);
        view_free(&v);
        printf("  four members: server %d watches and caught up (server 3 %s at first)\n", watcher,
               watching ? "watched" : "did not watch");
    }
    node_add(0, 4);
    want = 5;
    await_view(0, p_voters, &want, "five voters with five members");
    printf("  five members, five voters\n");
    check_all_agree(0, LIFE);
    cli_status(2, LIFE);
    printf("  status agrees on every server; the CLI prints it\n");

    /* SIGKILL of the leader */
    struct view lv;
    view(0, &lv);
    int li = leader_index(&lv);
    uint64_t old_term = lv.st.term;
    view_free(&lv);
    if (li < 0)
        die("no live server leads");
    uint32_t dead = ids[li];
    struct state_want w = {dead, META_UP, 1};
    {
        struct view v;
        view(li, &v);
        w.min_incarnation = meta_member(&v.m, dead)->incarnation + 1;
        view_free(&v);
    }
    stop(li, SIGKILL);
    printf("  killed the leader, server %d (member %" PRIu32 ", term %" PRIu64 ")\n", li, dead, old_term);
    int other = (li + 1) % LIFE, ni = -1;
    uint64_t t0 = now_ms();
    while (ni < 0) {
        struct view v;
        view(other, &v);
        if (v.st.leader && v.st.leader != dead && v.st.term > old_term) {
            for (int i = 0; i < N; i++)
                if (pids[i] > 0 && ids[i] == v.st.leader)
                    ni = i;
        }
        view_free(&v);
        if (ni < 0 && now_ms() - t0 > WAIT_MS)
            die("no new leader within %d ms", WAIT_MS);
        if (ni < 0)
            usleep(100000);
    }
    await_view(ni, p_leader_self, NULL, "the new leader leading");
    printf("  server %d (member %" PRIu32 ") leads after %" PRIu64 " ms\n", ni, ids[ni], now_ms() - t0);
    struct state_want down = {dead, META_DOWN, 0};
    await_view(ni, p_member_state, &down, "the dead member marked down");
    /* no healthy server is left to replace it with (all four are voters), so it just goes; the leader removes no
     * healthy voter to reach the odd target of three (4 voters lose one as 3 do) */
    want = 4;
    await_view(ni, p_voters, &want, "four voters without the dead one");
    {
        struct view v;
        view(ni, &v);
        if (is_voter(&v, dead))
            die("the dead member %" PRIu32 " is still a voter", dead);
        view_free(&v);
    }
    printf("  member %" PRIu32 " down and out of the voters\n", dead);

    /* back on the same directory: incarnation + 1, up, a voter again */
    start(li);
    await_view(ni, p_member_state, &w, "the restarted member up with a new incarnation");
    want = 5;
    {
        /* the leader may change while the group grows: ask whoever leads */
        uint64_t t1 = now_ms();
        for (;;) {
            int l = leader_of(ni);
            if (l >= 0) {
                struct view x;
                view(l, &x);
                int ok = p_voters(&x, &want) && is_voter(&x, dead);
                view_free(&x);
                if (ok) {
                    ni = l;
                    break;
                }
            }
            if (now_ms() - t1 > WAIT_MS)
                die("the restarted member did not become a voter again within %d ms", WAIT_MS);
            usleep(100000);
        }
    }
    printf("  member %" PRIu32 " back: up, incarnation %" PRIu64 ", five voters\n", dead, w.min_incarnation);
    check_all_agree(ni, LIFE);
}

static void scen_secret(void)
{
    scenario("secret");
    start(0);
    /* another secret: refused in the handshake */
    uint8_t other[32];
    memcpy(other, "another-secret-of-32-bytes-00000", 32);
    char addr[META_ADDR_MAX], err[1024];
    peer_of(0, addr, sizeof addr);
    int rc;
    uint8_t *rep = NULL;
    size_t rl;
    if (cluster_admin(addr, other, sizeof other, CLUSTER_OP_STATUS, NULL, 0, 3000, &rc, &rep, &rl, err,
                      sizeof err) == 0)
        die("a STATUS with a wrong secret was answered (rc %d)", rc);
    if (!strstr(err, "secret"))
        die("a wrong secret failed with \"%s\", not a word of the secret", err);
    printf("  a wrong secret is refused: %s\n", err);
    /* The message names the cause: a peer that is slow (the deadline passed) and one that closed the link looked alike,
     * which left the tt4-asan failure of [feed] undecidable. A listener that never answers, and one that closes. */
    for (int closes = 0; closes < 2; closes++) {
        int lfd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
        struct sockaddr_in la = {.sin_family = AF_INET};
        la.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        socklen_t ll = sizeof la;
        if (lfd < 0 || bind(lfd, (struct sockaddr *)&la, sizeof la) != 0 || listen(lfd, 4) != 0 ||
            getsockname(lfd, (struct sockaddr *)&la, &ll) != 0)
            die("listener for the cause test: %s", strerror(errno));
        char ls[64];
        snprintf(ls, sizeof ls, "127.0.0.1:%d", (int)ntohs(la.sin_port));
        pid_t kid = closes ? fork() : 0;
        if (kid == 0 && closes) { /* accepts one link and closes it at once, with the HELLO unread */
            int a = accept(lfd, NULL, NULL);
            if (a >= 0)
                close(a);
            _exit(0);
        }
        if (cluster_admin(ls, secret, secret_len, CLUSTER_OP_STATUS, NULL, 0, 400, &rc, &rep, &rl, err, sizeof err) == 0)
            die("a listener that %s gave an answer", closes ? "closes" : "never answers");
        const char *cause = strerror(closes ? ECONNRESET : ETIMEDOUT);
        if (!strstr(err, cause))
            die("a peer that %s: \"%s\", the cause (%s) is not named", closes ? "closes the link" : "never answers", err,
                cause);
        if (kid > 0)
            waitpid(kid, NULL, 0);
        close(lfd);
    }
    /* a long frame before the handshake: closed at once, never buffered */
    int fd = dial_peer(0);
    uint8_t h[5] = {0, 0, 0x10, 0, W_HELLO}; /* 1 MiB */
    uint8_t junk[4096] = {0};
    uint64_t t0 = now_ms();
    send_all(fd, h, sizeof h);
    send_all(fd, junk, sizeof junk);
    uint8_t x[64];
    int r;
    while ((r = read_full(fd, x, sizeof x, 4000)) == 0)
        ;
    uint64_t took = now_ms() - t0;
    close(fd);
    if (r == -2 || took > 1000)
        die("a 1 MiB frame before the handshake kept the connection for %" PRIu64 " ms", took);
    printf("  a 1 MiB frame before the handshake: closed after %" PRIu64 " ms\n", took);
    /* the secret file: only its owner may read it */
    char p[sizeof base + 32];
    snprintf(p, sizeof p, "%s/open-secret", base);
    FILE *f = fopen(p, "w");
    if (!f || fputs("0123456789abcdef0123456789abcdef\n", f) < 0 || fclose(f) != 0)
        die("writing %s", p);
    chmod(p, 0644);
    uint8_t buf[CLUSTER_SECRET_MAX];
    size_t len;
    if (cluster_read_secret(p, buf, sizeof buf, &len, err, sizeof err) == 0)
        die("a secret file of mode 0644 was accepted");
    snprintf(p, sizeof p, "%s/made-secret", base);
    struct stat sb;
    if (cluster_make_secret(p, err, sizeof err) != 0)
        die("cluster_make_secret: %s", err);
    if (stat(p, &sb) != 0 || (sb.st_mode & 0777) != 0600)
        die("a made secret has mode %o", (unsigned)(sb.st_mode & 0777));
    if (cluster_read_secret(p, buf, sizeof buf, &len, err, sizeof err) != 0 || len < 32)
        die("a made secret does not read back: %s", err);
    if (cluster_make_secret(p, err, sizeof err) == 0)
        die("cluster_make_secret overwrote an existing file");
    /* SEC-07: cluster_read_secret must refuse symlinks (O_NOFOLLOW) */
    char lp[sizeof base + 32];
    snprintf(lp, sizeof lp, "%s/link-secret", base);
    if (symlink(p, lp) != 0)
        die("symlink %s -> %s: %s", lp, p, strerror(errno));
    if (cluster_read_secret(lp, buf, sizeof buf, &len, err, sizeof err) == 0)
        die("cluster_read_secret followed a symlink to a 0600 secret file");
    unlink(lp);
    printf("  a secret file of mode 0644 or a symlink is refused; a made one is 0600 and reads back\n");
}

static void scen_relay(void)
{
    scenario("relay");
    start(0);
    start(1);
    init_fast(0);
    node_add(0, 1);
    struct view v;
    view(0, &v);
    struct catch_up c = {v.m.applied, meta_hash(&v.m)};
    await_view(1, p_caught_up, &c, "catching up");
    if (relay(1, RELAY_PLAIN, &v, 0) != 0)
        die("the CLI got no answer through a relay that changes nothing (the relay itself is broken)");
    printf("  a relay that changes nothing passes the CLI's STATUS (the control)\n");
    if (relay(1, RELAY_CLAIM, &v, ids[0]) == 0)
        die("the CLI accepted a relayed handshake that claimed member %" PRIu32 " to server 1", ids[0]);
    printf("  a relayed HELLO that claims member %" PRIu32 ": the CLI refuses, server 1 answers nothing\n", ids[0]);
    if (relay(1, RELAY_SWAP, &v, 0) == 0)
        die("the CLI got an answer although the relay replaced its request");
    printf("  a relayed handshake with the relay's own request: server 1 drops the link\n");
    view_free(&v);
}

static void meta_tmp(int i, int make)
{
    char p[PATH_MAX + 128];
    snprintf(p, sizeof p, "%s/n%d/state/snapshot.tmp", base, i);
    if ((make ? mkdir(p, 0755) : rmdir(p)) != 0)
        die("%s %s: %s", make ? "mkdir" : "rmdir", p, strerror(errno));
}

/* a crash between NODE and the first snapshot of an init (a directory in the way of the snapshot's temporary file
 * fail-stops the server there): the next init finishes it */
static void scen_initcrash(void)
{
    scenario("initcrash");
    start(0);
    meta_tmp(0, 1);
    struct meta_settings s;
    meta_settings_default(&s);
    s.node_timeout_ms = 1500;
    s.heartbeat_ms = 200;
    uint8_t req[4 * (META_SETTINGS_WORDS + 1)], *rep = NULL;
    size_t rl = cluster_settings_encode(&s, META_MODE_REPLICATED, req), len;
    char addr[META_ADDR_MAX], err[1024];
    peer_of(0, addr, sizeof addr);
    int rc;
    if (cluster_admin(addr, secret, secret_len, CLUSTER_OP_INIT, req, rl, 5000, &rc, &rep, &len, err,
                      sizeof err) == 0) {
        free(rep);
        if (rc == 0)
            die("an init whose snapshot cannot be written succeeded");
    }
    int st = await_exit(0, 10000);
    if (st != 1 || !log_has(0, "cannot write"))
        die("the init that could not write its snapshot ended with status %d", st);
    meta_tmp(0, 0);
    start(0);
    init_fast(0);
    printf("  an init cut short before its snapshot is finished by the next init\n");
}

/* a failed directory fsync after a snapshot is named stops the server (status 1) */
static void scen_dirsync(void)
{
    scenario("dirsync");
    envs[0] = "snap_every=2,fail_snap_dirsync=1";
    start(0);
    start(1);
    /* the init, then a node add, make the entries a snapshot is due after (the server may stop before it answers) */
    struct meta_settings s;
    meta_settings_default(&s);
    uint8_t req[META_ADDR_MAX + 64], *rep = NULL;
    size_t n = cluster_settings_encode(&s, META_MODE_REPLICATED, req), len;
    char addr[META_ADDR_MAX], err[1024];
    peer_of(0, addr, sizeof addr);
    int rc;
    if (cluster_admin(addr, secret, secret_len, CLUSTER_OP_INIT, req, n, 5000, &rc, &rep, &len, err, sizeof err) == 0)
        free(rep);
    n = node_add_req(1, req);
    if (await_exit(0, 1000) < 0 &&
        cluster_admin(addr, secret, secret_len, CLUSTER_OP_NODE_ADD, req, n, 5000, &rc, &rep, &len, err,
                      sizeof err) == 0)
        free(rep);
    int st = pids[0] ? await_exit(0, WAIT_MS) : 1;
    if (st != 1 || !log_has(0, "cannot sync"))
        die("a failed directory fsync after a snapshot: status %d (expected 1 with \"cannot sync\" in the log)", st);
    printf("  a failed directory fsync after naming a snapshot stops the server\n");
}

/* exitthreads: the two ends of tsdbd that are not its clean stop keep the status the harness waits for when a thread
 * has finished and nobody has joined it yet. Under ThreadSanitizer (make tsan: halt_on_error=1) the finalizer of an exit
 * reports such a thread as a leak and ends the process with 66 (test_cluster initcrash, snapkill: "status 66"); in
 * other builds both parts pass with or without the fixes. 1: a crash point (crashpt.c) ends as a power cut, with 99,
 * whatever threads there are: a child of this test, the point armed, a joinable thread that has returned. 2: tsdbd's
 * chunk peer source thread (chunkpeer_cluster.c) no longer returns once the epoch source is set, so a member that
 * fail-stops after that (its next snapshot's directory fsync fails) ends with 1. */
#ifdef __linux__
static atomic_long crashpt_child_tid;

static void *crashpt_child_thread(void *arg)
{
    (void)arg;
    atomic_store(&crashpt_child_tid, (long)syscall(SYS_gettid));
    return NULL;
}

static int crashpt_child(void)
{
    pthread_t t;
    if (pthread_create(&t, NULL, crashpt_child_thread, NULL) != 0)
        return 3;
    /* the thread has finished once the kernel has let go of it: its /proc/self/task entry is gone (never a count of the
     * tasks: ThreadSanitizer starts a background thread of its own at the first pthread_create; 10 s bound: a thread
     * that only stores its id) */
    uint64_t t0 = now_ms();
    for (;;) {
        long tid = atomic_load(&crashpt_child_tid);
        char path[64];
        struct stat st;
        snprintf(path, sizeof path, "/proc/self/task/%ld", tid);
        if (tid > 0 && stat(path, &st) != 0 && errno == ENOENT)
            break;
        if (now_ms() - t0 > 10000)
            return 4;
        usleep(1000);
    }
    setenv("TSDB_CRASH_AT", "serving", 1);
    crash_point(CP_SERVING);
    return 5; /* the point did not fire */
}
static int crashpt_long_child(void)
{
    char big[600];
    memset(big, 'a', sizeof big - 1);
    big[sizeof big - 1] = '\0';
    setenv("TSDB_CRASH_AT", big, 1);
    crash_point(CP_SERVING);
    return 5; /* unknown name must exit(2) */
}
#endif

static void scen_exitthreads(void)
{
    scenario("exitthreads");
#ifdef __linux__
    char self[PATH_MAX];
    ssize_t sl = readlink("/proc/self/exe", self, sizeof self - 1);
    if (sl <= 0)
        die("readlink /proc/self/exe: %s", strerror(errno));
    self[sl] = '\0';
    pid_t pid = fork();
    if (pid < 0)
        die("fork: %s", strerror(errno));
    if (pid == 0) {
        execl(self, self, "crashpt-child", (char *)NULL);
        _exit(127);
    }
    int st = -1;
    if (waitpid(pid, &st, 0) != pid)
        die("waitpid: %s", strerror(errno));
    if (!WIFEXITED(st) || WEXITSTATUS(st) != CRASH_EXIT_STATUS)
        die("a crash point passed with a finished, unjoined thread ended with status 0x%x, not %d (66: a sanitizer's "
            "report at exit)",
            st, CRASH_EXIT_STATUS);
    printf("  a crash point ends with %d beside a finished thread nobody joined\n", CRASH_EXIT_STATUS);

    /* SEC-03: a long TSDB_CRASH_AT value must clamp say() output to its stack buffer (no stack over-read) */
    int pfd[2];
    if (pipe(pfd) != 0)
        die("pipe: %s", strerror(errno));
    pid = fork();
    if (pid < 0)
        die("fork: %s", strerror(errno));
    if (pid == 0) {
        close(pfd[0]);
        dup2(pfd[1], 2);
        close(pfd[1]);
        execl(self, self, "crashpt-long-child", (char *)NULL);
        _exit(127);
    }
    close(pfd[1]);
    char ebuf[1024];
    size_t egot = 0;
    for (;;) {
        ssize_t r = read(pfd[0], ebuf + egot, sizeof ebuf - egot);
        if (r < 0 && errno == EINTR)
            continue;
        if (r <= 0)
            break;
        egot += (size_t)r;
        if (egot == sizeof ebuf)
            break;
    }
    close(pfd[0]);
    st = -1;
    if (waitpid(pid, &st, 0) != pid)
        die("waitpid: %s", strerror(errno));
    if (!WIFEXITED(st) || WEXITSTATUS(st) != 2)
        die("long TSDB_CRASH_AT ended with status 0x%x, not 2 (ASan stack over-read?)", st);
    if (egot == 0 || egot >= 200)
        die("long TSDB_CRASH_AT wrote %zu bytes to stderr (expected 1..199, clamped to stack buffer)", egot);
    printf("  a 600-byte TSDB_CRASH_AT exited 2 and wrote %zu clamped bytes to stderr\n", egot);
#else
    printf("  skipped: the crash point's child (a thread's /proc/self/task entry; Linux only)\n");
#endif

#ifdef TSDB_EC
    envs[0] = "snap_every=1,fail_snap_dirsync=2";
    start(0);
    start(1);
    init_fast(0);
    await_log(0, "chunk peer: the epoch source is set", WAIT_MS, "the member's chunk peer never set its epoch source");
    char ff[PATH_MAX + 64];
    snprintf(ff, sizeof ff, "%s/n0/state/faildirsync", base); /* the next snapshot's directory fsync fails: exit(1) */
    int fd = open(ff, O_CREAT | O_WRONLY, 0644);
    if (fd < 0)
        die("%s: %s", ff, strerror(errno));
    close(fd);
    uint8_t req[META_ADDR_MAX + 64], *rep = NULL;
    size_t n = node_add_req(1, req), len;
    char addr[META_ADDR_MAX], err[1024];
    peer_of(0, addr, sizeof addr);
    int rc;
    if (cluster_admin(addr, secret, secret_len, CLUSTER_OP_NODE_ADD, req, n, 5000, &rc, &rep, &len, err,
                      sizeof err) == 0)
        free(rep);
    int ex = await_exit(0, WAIT_MS);
    if (ex != 1 || !log_has(0, "cannot sync"))
        die("a member whose snapshot's directory fsync failed after its chunk peer started ended with status %d (want 1 "
            "with \"cannot sync\" in its log; 66: a sanitizer's report at exit)",
            ex);
    printf("  a member whose chunk peer runs fail-stops with status 1\n");
#else
    printf("  skipped: NO_EC build\n");
#endif
}

/* a crash inside a snapshot install: the log is reset to the image's index, the snapshot not written (a directory in
 * the way of its temporary file makes restore() stop there). The restarted server must catch up, not sit at applied
 * 0 over a log based past its snapshot: from the image it kept before the reset (install), or, that image gone too
 * (damage; reseed), by emptying its log for a new image. */
enum { KEPT_TAKEN, KEPT_GONE, HEADER_TORN };

static void install_crash(int mode)
{
    int drop_kept = mode == KEPT_GONE;
    scenario(mode == KEPT_GONE ? "reseed" : mode == HEADER_TORN ? "torn" : "install");
    for (int i = 0; i < 3; i++)
        envs[i] = "snap_every=2,snap_retain=1,seg_bytes=200"; /* small segments: compaction drops whole ones */
    for (int i = 0; i < 3; i++)
        start(i);
    init_fast(0);
    node_add(0, 1); /* two members: one voter, server 1 watches */
    meta_tmp(2, 1);
    node_add(0, 2); /* three: servers 1 and 2 become learners, and the leader's log begins after 1: installs */
    int st = await_exit(2, WAIT_MS);
    if (st != 1 || !log_has(2, "cannot write"))
        die("the learner whose snapshot cannot be written ended with status %d", st);
    meta_tmp(2, 0);
    char kept[PATH_MAX + 128];
    snprintf(kept, sizeof kept, "%s/n2/state/snapshot.install", base);
    if (access(kept, F_OK) != 0)
        die("server 2 stopped inside an install without the image kept in %s", kept);
    if (drop_kept && unlink(kept) != 0)
        die("cannot remove %s: %s", kept, strerror(errno));
    if (mode == HEADER_TORN) {
        /* the crash inside the reset's last step: the segment the log starts again on is named, its header is not
         * durable. It is the lone segment, named for the image's index + 1, which the snapshot (still the old one)
         * is not at: the open refused it as damage before it knew the store the reset was made for. */
        char dir[PATH_MAX + 128], seg[PATH_MAX + 256], name[300] = "";
        snprintf(dir, sizeof dir, "%s/n2/state/raft", base);
        DIR *d = opendir(dir);
        int nseg = 0;
        for (struct dirent *e; d && (e = readdir(d));)
            if (!strncmp(e->d_name, "log-", 4)) {
                snprintf(name, sizeof name, "%s", e->d_name);
                nseg++;
            }
        if (d)
            closedir(d);
        if (nseg != 1)
            die("the install crash left %d log segments in %s, expected the one the reset made", nseg, dir);
        snprintf(seg, sizeof seg, "%s/%s", dir, name);
        if (truncate(seg, 0) != 0)
            die("cannot truncate %s: %s", seg, strerror(errno));
    }
    start(2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    check_all_agree(0, 3);
    if (drop_kept) {
        if (!log_has(2, "fencing the vote"))
            die("server 2 did not take the path of an unfinished install (the test proves nothing)");
        printf("  a crash inside an install, the kept image gone: the server empties its log, gets a new image and "
               "catches up\n");
        return;
    }
    if (!log_has(2, "taking the install image kept in"))
        die("server 2 did not take the image it kept for the unfinished install (the test proves nothing)");
    if (log_has(2, "fencing the vote"))
        die("server 2 emptied its log although it had kept the image");
    if (mode == HEADER_TORN)
        printf("  a crash inside an install, the new segment's header torn: the server takes the image it kept, and "
               "catches up\n");
    else
        printf("  a crash inside an install: the server takes the image it kept, and catches up\n");
}

static void scen_install(void) { install_crash(KEPT_TAKEN); }
static void scen_reseed(void) { install_crash(KEPT_GONE); }
static void scen_torn(void) { install_crash(HEADER_TORN); }

/* A log that ends below the snapshot beside it, as a reset stopped between its deletes (or a lazily written durable
 * floor and a rotten tail) leaves: the newest segments are removed from a follower's directory. The start makes the
 * snapshot the log's base (the store holds what the dropped entries did) and the follower catches up from the leader,
 * where it used to boot with a log ending below its applied index (proposals at an index the store has applied). */
static void scen_rebase(void)
{
    scenario("rebase");
    for (int i = 0; i < 3; i++)
        envs[i] = "snap_every=2,snap_retain=1000,seg_bytes=200"; /* every entry stays: no installs */
    for (int i = 0; i < 3; i++)
        start(i);
    init_fast(0);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    check_all_agree(0, 3);
    stop(2, SIGKILL);
    char dir[PATH_MAX + 128], path[PATH_MAX + 256];
    snprintf(path, sizeof path, "%s/n2/state/snapshot", base);
    FILE *f = fopen(path, "rb");
    uint8_t img[1 << 16];
    size_t len = f ? fread(img, 1, sizeof img, f) : 0;
    if (f)
        fclose(f);
    struct meta_state m;
    meta_init(&m);
    if (!len || meta_snapshot_decode(&m, img, len) != META_OK)
        die("server 2 has no snapshot to put the log below (%s)", path);
    uint64_t applied = m.applied;
    meta_free(&m);
    if (applied < 4)
        die("server 2's snapshot is at %" PRIu64 ", too early to put the log below", applied);
    snprintf(dir, sizeof dir, "%s/n2/state/raft", base);
    DIR *d = opendir(dir);
    int kept = 0, removed = 0;
    for (struct dirent *e; d && (e = readdir(d));) {
        unsigned long long first;
        if (sscanf(e->d_name, "log-%llu", &first) != 1)
            continue;
        if (first + 1 >= applied) { /* the segment holds an entry at or above applied - 1: the log must end lower */
            snprintf(path, sizeof path, "%s/%s", dir, e->d_name);
            if (unlink(path) != 0)
                die("cannot remove %s: %s", path, strerror(errno));
            removed++;
        } else
            kept++;
    }
    if (d)
        closedir(d);
    /* the durable floor (the hard state's note of what was synced and committed) is what refuses a log cut below
     * it as rot; a reset lowers it to 0 first, so a log it left cut is open to this start. The test lowers it the
     * only way a file can: no hard state (this server was a learner for a moment; its term and vote come back from
     * the leader's next message). */
    snprintf(path, sizeof path, "%s/hard", dir);
    if (unlink(path) != 0)
        die("cannot remove %s: %s", path, strerror(errno));
    if (!kept || !removed)
        die("could not cut server 2's log below its snapshot at %" PRIu64 " (%d kept, %d removed)", applied, kept,
            removed);
    start(2);
    await_view(0, p_voters, &want, "three voters");
    check_all_agree(0, 3);
    if (!log_has(2, "starting the log on it"))
        die("server 2 did not start its log on the snapshot (the test proves nothing)");
    printf("  a log that ends below the snapshot: the server starts it on the snapshot and catches up\n");
}

/* An install that takes longer than voter_replace_s (here: the new servers drop the leader's images for 6 s). A core
 * booted by the leader's first APPEND has an empty configuration until the image arrives; it must keep sending
 * heartbeats, or the leader marks it down, removes it as a learner, and never adds it again (seen once under TSan on a
 * loaded machine: a learner at applied 0, "not heard" for 30 s). */
static void scen_slowinstall(void)
{
    scenario("slowinstall");
    envs[0] = "snap_every=2,snap_retain=1,seg_bytes=200";
    envs[1] = envs[2] = "snap_every=2,snap_retain=1,seg_bytes=200,hold_install_ms=6000";
    for (int i = 0; i < 3; i++)
        start(i);
    init_fast(0);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters after installs slower than voter_replace_s");
    check_all_agree(0, 3);
    if (log_has(0, "removes learner"))
        die("the leader removed a learner whose install was on its way");
    printf("  installs slower than voter_replace_s: the learners stay heard, are kept, and become voters\n");
}

/* the leader stopped while a node add is in flight; the next leader adds another server; the first again */
static void scen_ids(void)
{
    scenario("ids");
    for (int i = 0; i < 5; i++)
        start(i);
    init_fast(0);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    const int A = 3, B = 4, L = 0;
    pause_server(A, 1);
    pid_t kid = fork();
    if (kid < 0)
        die("fork: %s", strerror(errno));
    if (kid == 0) {
        uint8_t req[META_ADDR_MAX + 2], *rep = NULL;
        size_t n = node_add_req(A, req), len;
        char addr[META_ADDR_MAX], err[1024];
        peer_of(L, addr, sizeof addr);
        int rc;
        cluster_admin(addr, secret, secret_len, CLUSTER_OP_NODE_ADD, req, n, 8000, &rc, &rep, &len, err, sizeof err);
        _exit(0);
    }
    usleep(500000);
    pause_server(L, 1);
    int nl = -1;
    uint64_t t0 = now_ms();
    while (nl < 0) {
        nl = leader_of(1);
        if (nl == L)
            nl = -1;
        if (nl < 0 && now_ms() - t0 > WAIT_MS)
            die("no leader in place of the stopped one within %d ms", WAIT_MS);
        if (nl < 0)
            usleep(100000);
    }
    pause_server(L, 0);
    pause_server(A, 0);
    int st;
    waitpid(kid, &st, 0);
    node_add(nl, B);
    node_add(nl, A);
    if (ids[A] == ids[B])
        die("servers %d and %d are both member %" PRIu32, A, B, ids[A]);
    uint32_t a1 = ids[A];
    node_add(nl, A); /* again: the same id */
    if (ids[A] != a1)
        die("a second node add of server %d gave member %" PRIu32 " after %" PRIu32, A, ids[A], a1);
    int l = leader_of(nl);
    check_all_agree(l < 0 ? nl : l, 5);
    for (int i = 0; i < 5; i++) {
        struct view v;
        view(i, &v);
        for (uint32_t x = 0; x < v.m.nmembers; x++)
            for (uint32_t y = x + 1; y < v.m.nmembers; y++)
                if (!memcmp(v.m.members[x].ident, v.m.members[y].ident, 16))
                    die("members %" PRIu32 " and %" PRIu32 " have one identity", v.m.members[x].id,
                        v.m.members[y].id);
        view_free(&v);
    }
    printf("  a node add cut short by a new leader: servers %d and %d are members %" PRIu32 " and %" PRIu32 "\n", A, B,
           ids[A], ids[B]);

    /* an impostor: member 2's NODE in another directory (another identity) */
    char src[PATH_MAX + 128], dst[PATH_MAX + 128];
    snprintf(dst, sizeof dst, "%s/n5", base);
    mkdir(dst, 0755);
    snprintf(dst, sizeof dst, "%s/n5/state", base);
    mkdir(dst, 0755);
    snprintf(src, sizeof src, "%s/n1/state/NODE", base);
    snprintf(dst, sizeof dst, "%s/n5/state/NODE", base);
    {
        FILE *in = fopen(src, "rb"), *out = fopen(dst, "wb");
        char b[4096];
        size_t k;
        if (!in || !out)
            die("copying %s: %s", src, strerror(errno));
        while ((k = fread(b, 1, sizeof b, in)) > 0)
            fwrite(b, 1, k, out);
        fclose(in);
        if (fclose(out) != 0)
            die("writing %s", dst);
    }
    l = leader_of(nl);
    if (l < 0)
        die("no leader");
    struct view v;
    view(l, &v);
    char peer1[META_ADDR_MAX];
    snprintf(peer1, sizeof peer1, "%s", meta_member(&v.m, ids[1])->peer);
    view_free(&v);
    start(5);
    usleep(4000000); /* more than two node timeouts of heartbeats */
    view(l, &v);
    const struct meta_member *m = meta_member(&v.m, ids[1]);
    if (strcmp(m->peer, peer1) != 0 || m->state != META_UP)
        die("an impostor of member %" PRIu32 " moved its record to %s (state %d)", ids[1], m->peer, m->state);
    view_free(&v);
    int refused = 0;
    for (int i = 0; i < 5; i++) {
        char needle[64];
        snprintf(needle, sizeof needle, "claims node %" PRIu32, ids[1]);
        refused |= log_has(i, needle);
    }
    if (!refused)
        die("no member logged that it refused the impostor of member %" PRIu32, ids[1]);
    stop(5, SIGKILL);
    printf("  a copy of member %" PRIu32 "'s NODE elsewhere is refused; the member's address stays\n", ids[1]);
}

/* a watcher whose voter hangs: SIGSTOP of each voter in turn; the watcher must see that voter marked down */
static void scen_watch(void)
{
    scenario("watch");
    for (int i = 0; i < 4; i++)
        start(i);
    init_cluster(0, 600); /* a stopped voter stays a voter: each of the three is stopped in turn */
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    node_add(0, 3);
    await_view(0, p_voters, &want, "three voters with four members");
    struct view lv;
    view(0, &lv);
    int watcher = -1, vs[3], nv = 0;
    for (int i = 0; i < 4; i++)
        if (!raft_config_find(&lv.cfg, ids[i]))
            watcher = i;
        else if (nv < 3)
            vs[nv++] = i;
    view_free(&lv);
    if (watcher < 0 || nv != 3)
        die("four members, no watcher");
    for (int k = 0; k < 3; k++) {
        int v = vs[k], u = vs[(k + 1) % 3];
        pause_server(v, 1);
        struct state_want down = {ids[v], META_DOWN, 0};
        await_view(u, p_member_state, &down, "the stopped voter marked down");
        struct view x;
        view(u, &x);
        struct catch_up c = {x.m.applied, meta_hash(&x.m)};
        view_free(&x);
        /* a node timeout (1.5 s) behind, then another voter: well within 10 s */
        await_view_ms(watcher, p_caught_up, &c, "the watcher keeping up while a voter hangs", 10000);
        pause_server(v, 0);
        struct state_want up = {ids[v], META_UP, 0};
        await_view(u, p_member_state, &up, "the voter up again");
        printf("  voter %" PRIu32 " stopped: the watcher kept up\n", ids[v]);
    }
}

/* M11 (item 2): the leader's disk stalls (its log sync hangs, for hours on a hard mount). The cluster thread must keep
 * answering and heartbeating (the member is never marked down), and after 2 s (stall_ms=1500 here) the leader hands
 * leadership to another voter. The knob holds the worker's sync while <state-dir>/stall exists. */
static void scen_stall(void)
{
    scenario("stall");
    for (int i = 0; i < 4; i++) {
        envs[i] = "sync_stall_file=1,stall_ms=1500";
        start(i);
    }
    init_cluster(0, 600); /* a silent voter stays a voter */
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    int L = leader_of(0);
    if (L < 0 || L > 2)
        die("no leader among the voters");
    int U = (L + 1) % 3;
    char path[PATH_MAX + 160];
    snprintf(path, sizeof path, "%s/n%d/state/stall", base, L);
    FILE *f = fopen(path, "w");
    if (!f || fclose(f) != 0)
        die("making %s", path);
    /* a proposal on the stalled leader: its sync round never ends. The answer may time out or be refused. */
    char addr[META_ADDR_MAX], err[1024];
    peer_of(L, addr, sizeof addr);
    uint8_t req[META_ADDR_MAX + 2], *rep = NULL;
    size_t rl = node_add_req(3, req), replen = 0;
    int rc;
    cluster_admin(addr, secret, secret_len, CLUSTER_OP_NODE_ADD, req, rl, 1500, &rc, &rep, &replen, err,
                  sizeof err);
    free(rep);
    /* the thread is not blocked on the disk: STATUS answers at once, 2.5 s into the stall */
    uint64_t t0 = now_ms();
    while (now_ms() - t0 < 2500)
        usleep(50000);
    uint64_t q0 = now_ms();
    struct view v;
    view(L, &v);
    view_free(&v);
    if (now_ms() - q0 > 1000)
        die("STATUS of the stalled leader took %" PRIu64 " ms: the cluster thread waits for the disk", now_ms() - q0);
    /* leadership has moved to another voter */
    uint64_t t1 = now_ms();
    int nl = -1;
    while (now_ms() - t1 < 10000) {
        view(U, &v);
        nl = leader_index(&v);
        view_free(&v);
        if (nl >= 0 && nl != L)
            break;
        usleep(100000);
    }
    if (nl < 0 || nl == L)
        die("the stalled leader did not hand leadership on within 10 s");
    printf("  leader %d stalled: server %d leads after %" PRIu64 " ms\n", L, nl, now_ms() - t0);
    if (!log_has(L, "handing leadership"))
        die("the stalled leader says nothing of handing leadership on");
    /* well past the 1.5 s of node_timeout: its heartbeats still arrive */
    t0 = now_ms();
    while (now_ms() - t0 < 3000)
        usleep(50000);
    struct state_want up = {ids[L], META_UP, 0};
    await_view_ms(nl, p_member_state, &up, "the stalled node still up (its heartbeats flow)", 3000);
    unlink(path);
    view(nl, &v);
    struct catch_up c = {v.m.applied, meta_hash(&v.m)};
    view_free(&v);
    await_view_ms(L, p_caught_up, &c, "the node catching up once its disk returns", 10000);
    printf("  the stall ended: server %d is a follower again and caught up\n", L);
}


/* A witness (item 7): a cluster member with no --dir, no engine and no volumes. It holds a Raft core (a voter), its
 * member record says volumes_ok 0, and nothing in its directory looks like a volume. */
static void scen_witness(void)
{
    scenario("witness");
    start(0);
    is_witness[1] = 1;
    xargs[1] = "--peer-port 0"; /* a witness takes the peer port 7071 unless told */
    char wdir[PATH_MAX + 160];
    snprintf(wdir, sizeof wdir, "%s/n1", base); /* no --dir makes it; the state directory goes inside */
    if (mkdir(wdir, 0755) != 0)
        die("mkdir %s: %s", wdir, strerror(errno));
    start(1);
    start(2);
    init_fast(0);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters (the witness is one)");
    struct view v;
    view(0, &v);
    const struct meta_member *w = meta_member(&v.m, ids[1]);
    if (!w || (w->flags & META_MF_VOLUMES_OK) || !(w->flags & META_MF_VOTER_OK))
        die("the witness's record has flags %u, expected voter_ok without volumes_ok", w ? (unsigned)w->flags : 99u);
    const struct meta_member *m0 = meta_member(&v.m, ids[0]);
    if (!m0 || !(m0->flags & META_MF_VOLUMES_OK))
        die("a normal member's record lacks volumes_ok");
    view_free(&v);
    char path[PATH_MAX + 160];
    snprintf(path, sizeof path, "%s/n1/SERIES", base);
    if (access(path, F_OK) == 0)
        die("the witness made %s: it holds volumes", path);
    snprintf(path, sizeof path, "%s/n1/state/NODE", base);
    if (access(path, F_OK) != 0)
        die("the witness has no NODE file in its state directory");
    printf("  a witness is a voter without volumes_ok and without a data directory\n");
}

/* Flags (item 6) and the copy (item 8): a server that reports voter_ok 0 (no room in its state directory) joins as a
 * member, is never added to the group, and, as a watcher, keeps a copy of the metadata that it serves, marked stale,
 * after a restart with the group down. */
static void scen_flags(void)
{
    scenario("flags");
    envs[2] = "free_min=9999999999999999"; /* more than any disk has: voter_ok 0 */
    envs[1] = "claim_ok=0"; /* its claims fail: claim_ok 0 in its record (the leader lifts a bar only on 0 -> 1) */
    for (int i = 0; i < 3; i++)
        start(i);
    init_fast(0);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 2;
    await_view(0, p_voters, &want, "two voters, the third server is not one");
    /* it stays out for well past voter_replace_s and the learner rounds of the leader */
    uint64_t t0 = now_ms();
    while (now_ms() - t0 < 5000)
        usleep(100000);
    struct view v;
    view(0, &v);
    const struct meta_member *m = meta_member(&v.m, ids[2]);
    if (!m || (m->flags & META_MF_VOTER_OK) || !(m->flags & META_MF_VOLUMES_OK))
        die("server 2's record has flags %u, expected volumes_ok without voter_ok", m ? (unsigned)m->flags : 99u);
    if (v.cfg.n != 2 || raft_config_find(&v.cfg, ids[2]))
        die("a member with voter_ok 0 is in the Raft group");
    const struct meta_member *m1 = meta_member(&v.m, ids[1]);
    if (!m1 || (m1->flags & META_MF_CLAIM_OK) || !(m1->flags & META_MF_VOTER_OK))
        die("server 1's record has flags %u, expected voter_ok without claim_ok", m1 ? (unsigned)m1->flags : 99u);
    struct catch_up c = {v.m.applied, meta_hash(&v.m)};
    uint32_t members = v.m.nmembers;
    view_free(&v);
    await_view(2, p_caught_up, &c, "the watcher catching up");
    printf("  voter_ok 0 keeps a member out of the group\n");
    /* the copy: all down, then the watcher alone */
    usleep(1000000); /* the copy is written a moment after the applied entries */
    stop(2, SIGTERM);
    stop(1, SIGTERM);
    stop(0, SIGTERM);
    start(2);
    view(2, &v);
    if (!v.st.stale || v.m.nmembers != members)
        die("the restarted watcher shows stale %d and %u members, expected a stale copy with %u", (int)v.st.stale,
            (unsigned)v.m.nmembers, (unsigned)members);
    view_free(&v);
    printf("  a restarted watcher serves its copy of the metadata, marked stale\n");
}

/* Heartbeat sections (item 1): a server that reports a volume with a fault and a slow domain shows both in the
 * leader's status, and the fault timer grows while the reports keep it. */
static void scen_hbsections(void)
{
    scenario("hbsections");
    envs[1] = "vol=7/1/1/5/diskA,dom=diskA/2"; /* volume 7, role 1, health local fault, epoch 5; domain diskA FAULT */
    for (int i = 0; i < 2; i++)
        start(i);
    init_fast(0);
    node_add(0, 1);
    usleep(3500000); /* a watcher of the group reports through heartbeats as well */
    struct view v;
    view(0, &v);
    const struct cluster_heard *h = NULL;
    for (uint32_t k = 0; k < v.st.nheard; k++)
        if (v.st.heard[k].id == ids[1])
            h = &v.st.heard[k];
    if (!h || h->nvols != 1 || h->ndoms != 1)
        die("the leader's heard entry of server 1 has %u volumes and %u domains, expected 1 and 1",
            h ? (unsigned)h->nvols : 99u, h ? (unsigned)h->ndoms : 99u);
    if (h->vols[0].v.volume != 7 || h->vols[0].v.epoch != 5 || h->vols[0].v.health != 1 ||
        strcmp(h->vols[0].v.domain, "diskA") || h->doms[0].state != 2 || strcmp(h->doms[0].name, "diskA"))
        die("the volume or domain report of server 1 is not what it sent");
    if (h->vols[0].local_fault_s < 2)
        die("the fault timer of server 1's volume reads %" PRIu64 " s after 3.5 s of reports", h->vols[0].local_fault_s);
    printf("  volume and domain reports reach the leader; the fault timer runs (%" PRIu64 " s)\n",
           h->vols[0].local_fault_s);
    view_free(&v);
}

/* A Raft log fault in shared mode (item 3) ends the voter role only: the server drops its core, writes `retired`,
 * stays up as a watcher, and the leader replaces it by another member; a restart does not boot the core again. */
static void scen_retired(void)
{
    scenario("retired");
    envs[2] = "fail_sync_file=1";
    for (int i = 0; i < 4; i++)
        start(i);
    init_mode(0, 3, META_MODE_SHARED);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    char path[PATH_MAX + 160];
    snprintf(path, sizeof path, "%s/n2/state/failsync", base);
    FILE *f = fopen(path, "w");
    if (!f || fclose(f) != 0)
        die("making %s", path);
    node_add(0, 3); /* an entry: server 2 must sync it, and cannot */
    uint64_t t0 = now_ms();
    while (!log_has(2, "ends the voter role only") && now_ms() - t0 < 10000)
        usleep(100000);
    if (!log_has(2, "ends the voter role only"))
        die("server 2 did not end its voter role on a failed log sync");
    /* the log line comes before core_stop and the mark's write: wait for the mark, not just the line */
    snprintf(path, sizeof path, "%s/n2/state/retired", base);
    t0 = now_ms();
    while (access(path, F_OK) != 0 && now_ms() - t0 < 10000)
        usleep(50000);
    if (access(path, F_OK) != 0)
        die("server 2 wrote no retired mark within 10 s of its log line");
    int rc = waitpid(pids[2], NULL, WNOHANG);
    if (rc != 0)
        die("server 2 is gone: a log fault in shared mode must end the voter role only");
    /* the leader replaces it with server 3, which was added as a member beside the three */
    struct view v;
    t0 = now_ms();
    int ok = 0;
    while (now_ms() - t0 < 40000 && !ok) {
        view(0, &v);
        ok = is_voter(&v, ids[3]) && !raft_config_find(&v.cfg, ids[2]);
        view_free(&v);
        usleep(200000);
    }
    if (!ok)
        die("server 3 did not replace server 2 in the group");
    view(2, &v);
    if (v.st.mode == CLUSTER_MODE_CORE)
        die("server 2 still runs a Raft core");
    view_free(&v);
    printf("  a log fault ends the voter role: server 2 is retired, serves as a watcher, server 3 took its place\n");
    stop(2, SIGTERM);
    snprintf(path, sizeof path, "%s/n2/state/failsync", base);
    unlink(path);
    start(2);
    view(2, &v);
    if (v.st.mode == CLUSTER_MODE_CORE)
        die("a retired server booted a Raft core after its restart");
    view_free(&v);
    printf("  after a restart it still holds no core\n");
}

/* A sync round out while more entries are appended (a slow disk): the core asked for a sync once per append, and the
 * round that returns must start the next one, or the entries wait for an append that may never come (has1: a node add
 * that never answered, one start in three). Each sync takes 300 ms here, so INIT is proposed under the first round. */
static void scen_syncrace(void)
{
    scenario("syncrace");
    for (int i = 0; i < 2; i++) {
        envs[i] = "sync_delay_ms=300";
        start(i);
    }
    init_fast(0);
    node_add(0, 1);
    struct view v;
    view(0, &v);
    if (v.m.nmembers != 2)
        die("two members expected, %u", (unsigned)v.m.nmembers);
    view_free(&v);
    printf("  entries appended under an outstanding sync round are synced by the next one\n");
}

/* Power loss on the metadata state (crashfs under server 0's state directory): what the leader acknowledged, it keeps.
 * Three watchers join (the one voter commits each entry after its own sync), then the power fails at the next write
 * the server makes. After the restart the state holds everything that was acknowledged and the term has gone up.
 * Catches a log that is never synced at all (applied falls back), a hard state that is never saved (the term restarts
 * from the start) and, with `snaps` (the log is compacted behind the snapshot), a snapshot lost with its directory
 * entry where no other sync covers it; a single missing sync site is another matter, see below.
 * What each scenario catches was measured, not assumed (test-trust review,
 * 2026-11-09): with every fdatasync of raft_log.c removed `power` fails; with only the hard state's sync removed (C2)
 * `power` and `powersnap` PASS, because the term saved at the restart is synced by the log's own rounds, and only
 * `powervote` (below) fails it, in every run, and `make test` plants it (cluster-mutants). NOT caught (measured, 6 runs
 * each): the log's two fdatasync sites removed (C1) by `power`, and the snapshot's rename without its directory fsync
 * (C7, cluster.c write of the snapshot) by `powersnap`: other syncs cover them, so those two have no test yet. The clean
 * server passes every run. crashfs follows dup'ed descriptors for this (the log syncs duplicates of its segments).
 * No CRASHFS_TEAR: a tear may keep every unsynced byte, which would let the unsynced log pass now and then.
 * CRASHFS_REWRITE=old: a hard-state slot rewritten in place and not yet synced comes back as the old slot, not as zeros
 * (a blank slot beside sequence N > 1 is damage by the log's own rule, and a disk leaves old or new bytes there: with
 * zeros the restart refused to open in about 1 run in 10, 2 of 20 in tt-cluster-20b). */
static void power_loss(int snaps)
{
    scenario(snaps ? "powersnap" : "power");
    const char *so = getenv("CRASHFS_SO") ? getenv("CRASHFS_SO") : "./build/libcrashfs.so";
    if (access(so, F_OK) != 0) {
#ifdef __linux__
        /* a missing shim must not pass as a skipped test (ha-s1 review 8): make builds it with this test */
        die("no %s (make build/libcrashfs.so): the power-loss scenarios cannot run, and must not pass as skipped", so);
#else
        printf("  skipped: no %s\n", so);
        return;
#endif
    }
    /* the ASan runtime must come first in the library list: with crashfs preloaded the server refuses to start */
    int asan = 0;
#if defined(__SANITIZE_ADDRESS__)
    asan = 1;
#elif defined(__has_feature)
#if __has_feature(address_sanitizer)
    asan = 1;
#endif
#endif
    if (asan) {
        printf("  skipped: crashfs cannot be preloaded into an AddressSanitizer build\n");
        return;
    }
    static char pe[PATH_MAX * 2 + 128];
    char st[PATH_MAX + 160];
    snprintf(st, sizeof st, "%s/n0/state", base);
    char dir0[PATH_MAX + 160];
    snprintf(dir0, sizeof dir0, "%s/n0", base);
    if (mkdir(dir0, 0755) != 0 || mkdir(st, 0755) != 0)
        die("mkdir %s: %s", st, strerror(errno));
    snprintf(pe, sizeof pe, "LD_PRELOAD=%s CRASHFS_ROOT=%s CRASHFS_REWRITE=old", so, st);
    penv[0] = pe;
    envs[0] = snaps ? "snap_every=2,snap_retain=1,seg_bytes=200" : NULL;
    for (int i = 1; i < 5; i++)
        envs[i] = "free_min=9999999999999999"; /* watchers: never voters, so server 0 stays the one voter */
    for (int i = 0; i < 5; i++)
        start(i);
    init_fast(0);
    for (int i = 1; i < 4; i++)
        node_add(0, i);
    /* a clean restart first: the term goes up and must be saved */
    usleep(500000);
    stop(0, SIGTERM);
    start(0);
    await_view(0, p_leader_self, NULL, "server 0 leading again");
    usleep(1500000);
    struct view v;
    view(0, &v);
    uint64_t term0 = v.st.term, applied0 = v.m.applied;
    uint32_t members0 = v.m.nmembers;
    view_free(&v);
    if (members0 != 4)
        die("server 0 has %u members before the power loss, expected 4", (unsigned)members0);
    /* the power fails at the next tracked operation: a proposal makes one */
    signal_child(pids[0], SIGUSR2);
    char addr[META_ADDR_MAX], err[1024];
    peer_of(0, addr, sizeof addr);
    uint8_t req[META_ADDR_MAX + 2], *rep = NULL;
    size_t rl = node_add_req(4, req), replen = 0;
    int rc;
    cluster_admin(addr, secret, secret_len, CLUSTER_OP_NODE_ADD, req, rl, 2000, &rc, &rep, &replen, err, sizeof err);
    free(rep);
    int status = await_exit(0, 15000);
    if (status != 99)
        die("server 0 ended with status %d after the power loss, expected 99 (crashfs)", status);
    start(0);
    await_view(0, p_leader_self, NULL, "server 0 leading after the power loss");
    /* A restarted leader knows its commit index only once an entry of its own term is committed (the one voter syncs
     * it and commits at once), so until then `applied` is the earlier copy of the state (run 17 of 20 read applied 7 of
     * 10 right after "leader"). Wait for it, bounded: a log that lost acknowledged entries never gets back to
     * applied0 (its first new entry gets applied0 - k + 1), and the check below fails with its numbers. */
    uint64_t t_applied = now_ms();
    for (;;) {
        view(0, &v);
        if ((v.m.nmembers >= members0 && v.m.applied >= applied0) || now_ms() - t_applied > 10000)
            break;
        view_free(&v);
        usleep(100000);
    }
    if (v.m.nmembers < members0 || v.m.applied < applied0)
        die("after the power loss server 0 holds %u members and applied %" PRIu64 ", it had acknowledged %u and %" PRIu64,
            (unsigned)v.m.nmembers, v.m.applied, (unsigned)members0, applied0);
    if (v.st.term <= term0)
        die("after the power loss the term is %" PRIu64 ", it was %" PRIu64 " (the hard state was not kept)", v.st.term,
            term0);
    printf("  after a power loss the leader holds all %u acknowledged members (applied %" PRIu64 " of %" PRIu64
           "), term %" PRIu64 " -> %" PRIu64 "\n",
           (unsigned)members0, v.m.applied, applied0, term0, v.st.term);
    view_free(&v);
}
static void scen_power(void) { power_loss(0); }

/* A voter's vote survives a power loss (ha-s1 review 8; the single-voter power scenario sees only the term). Three
 * voters, crashfs under n2. The leader is killed, n1 and n2 elect one in a higher term T (n2 votes for the winner or
 * for itself, saving the hard state first), then n2 loses power at its next tracked operation (a proposal's append).
 * What its state directory holds then must say it voted in T, and for whom: a hard save that kept the term but lost
 * the vote would let it vote again for another candidate in T (two leaders), and one that kept nothing is worse. */
static int powervote_round(int attempt)
{
    if (attempt == 0)
        scenario("powervote");
    else {
        char name[32];
        snprintf(name, sizeof name, "powervote%d", attempt);
        scenario(name);
    }
    const char *so = getenv("CRASHFS_SO") ? getenv("CRASHFS_SO") : "./build/libcrashfs.so";
    if (access(so, F_OK) != 0) {
#ifdef __linux__
        die("no %s (make build/libcrashfs.so): the power-loss scenarios cannot run, and must not pass as skipped", so);
#else
        printf("  skipped: no %s\n", so);
        return 1;
#endif
    }
#if defined(__SANITIZE_ADDRESS__)
    printf("  skipped: crashfs cannot be preloaded into an AddressSanitizer build\n");
    return 1;
#elif defined(__has_feature)
#if __has_feature(address_sanitizer)
    printf("  skipped: crashfs cannot be preloaded into an AddressSanitizer build\n");
    return 1;
#endif
#endif
    static char pe[PATH_MAX * 2 + 128];
    char st[PATH_MAX + 160], dir2[PATH_MAX + 160];
    snprintf(dir2, sizeof dir2, "%s/n2", base);
    snprintf(st, sizeof st, "%s/n2/state", base);
    if (mkdir(dir2, 0755) != 0 || mkdir(st, 0755) != 0)
        die("mkdir %s: %s", st, strerror(errno));
    snprintf(pe, sizeof pe, "LD_PRELOAD=%s CRASHFS_ROOT=%s CRASHFS_REWRITE=old", so, st);
    penv[2] = pe;
    envs[3] = "free_min=9999999999999999"; /* a watcher: the proposal that makes n2 append */
    for (int i = 0; i < 4; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    struct view v;
    view(0, &v);
    struct catch_up c = {v.m.applied, meta_hash(&v.m)};
    uint64_t term0 = v.st.term;
    view_free(&v);
    await_view(2, p_caught_up, &c, "n2 caught up");
    stop(0, SIGKILL);
    uint64_t t0 = now_ms(), term = 0;
    uint32_t leader = 0;
    while (now_ms() - t0 < 20000 && !leader) {
        view(2, &v);
        if (v.st.term > term0 && v.st.leader && v.st.leader != ids[0]) {
            term = v.st.term;
            leader = v.st.leader;
        }
        view_free(&v);
        if (!leader)
            usleep(100000);
    }
    if (!leader)
        die("no new leader after the first one was killed");
    if (leader == ids[2]) {
        /* n2 won the election itself: it is the leader now, and its own log syncs (its first entries) make the hard
         * state durable too, whether or not the hard save syncs. That run cannot tell a vote that was not synced
         * (planted C2: it passed in 3 of 8 runs), so the cluster is made again until n2 is the one that votes for
         * another candidate. */
        printf("  n2 won term %" PRIu64 " itself: its vote proves nothing here, trying again\n", term);
        return 0;
    }
    int li = leader == ids[1] ? 1 : 2;
    signal_child(pids[2], SIGUSR2); /* the power fails at n2's next tracked operation */
    char addr[META_ADDR_MAX], err[1024];
    peer_of(li, addr, sizeof addr);
    uint8_t req[META_ADDR_MAX + 2], *rep = NULL;
    size_t rl = node_add_req(3, req), replen = 0;
    int rc;
    cluster_admin(addr, secret, secret_len, CLUSTER_OP_NODE_ADD, req, rl, 2000, &rc, &rep, &replen, err, sizeof err);
    free(rep);
    int status = await_exit(2, 15000);
    if (status != 99)
        die("server 2 ended with status %d after the power loss, expected 99 (crashfs)", status);
    char rd[PATH_MAX + 200];
    snprintf(rd, sizeof rd, "%s/raft", st);
    raft_hard_state hs;
    memset(&hs, 0, sizeof hs);
    char lerr[512] = "";
    if (raft_log_hard_load(rd, &hs, lerr, sizeof lerr) != ISO_OK)
        die("after the power loss server 2 holds no hard state (it voted in term %" PRIu64 "): %s", term, lerr);
    if (hs.term < term || (hs.term == term && hs.vote != leader))
        die("after the power loss server 2's hard state is term %" PRIu64 " voted for %" PRIu32 ", it voted in term %" PRIu64
            " for %" PRIu32,
            (uint64_t)hs.term, (uint32_t)hs.vote, term, leader);
    printf("  a voter's vote in term %" PRIu64 " (for node %" PRIu32 ") survives a power loss\n", term, leader);
    return 1;
}
static void scen_powervote(void)
{
    for (int attempt = 0; attempt < 12; attempt++)
        if (powervote_round(attempt))
            return;
    die("n2 won its own election in 12 clusters in a row (a fair coin: 1 in 4096): the vote was never checked");
}
static void scen_powersnap(void) { power_loss(1); }

/* A power cut between a hard state save's write and its sync (jepsen-cluster kv power, seed 1, 2026-11-17: "slot 1 of the
 * raft hard state in raft/hard is blank beside sequence 6 in slot 0", and the node never started again). A disk keeps
 * the slot's old sectors or the new ones, which the reader takes; crashfs zeroed rewrites it was not told to keep, and
 * the reader rightly takes a zeroed slot beside a later save for rot. So every power-loss harness of tsdbd --cluster
 * runs crashfs with the old bytes coming back (CRASHFS_REWRITE=old, the default; main's KEEP_OLD): here a child saves six hard states (seq 6 in slot 0, seq 5 in slot 1), writes
 * the seventh save's slot 1 without its sync and loses power at exit. With the old bytes the hard state reads back as
 * term 6; with CRASHFS_REWRITE=zero it must be refused, which is the state the jepsen node was left in. */
static int hardslot_child(const char *dir)
{
    char err[512];
    raft_log *l;
    raft_log_opts o = {0};
    o.segment_bytes = RAFT_LOG_SEGMENT_MIN;
    if (raft_log_open(dir, &o, 0, 0, &l, err, sizeof err) != ISO_OK) {
        fprintf(stderr, "hardslot child: open %s: %s\n", dir, err);
        _exit(3);
    }
    for (unsigned t = 1; t <= 6; t++) {
        raft_hard_state hs = {.term = t, .vote = 1};
        if (raft_log_hard_save(l, &hs, err, sizeof err) != ISO_OK) {
            fprintf(stderr, "hardslot child: save %u: %s\n", t, err);
            _exit(3);
        }
    }
    char hp[PATH_MAX + 16];
    snprintf(hp, sizeof hp, "%s/hard", dir);
    int fd = open(hp, O_RDWR | O_CLOEXEC);
    static uint8_t slot[4096];
    memset(slot, 0xab, sizeof slot);
    if (fd < 0 || pwrite(fd, slot, sizeof slot, 4096) != (ssize_t)sizeof slot) { /* seq 7 goes to slot 1 */
        fprintf(stderr, "hardslot child: rewrite %s: %s\n", hp, strerror(errno));
        _exit(3);
    }
    exit(0); /* CRASHFS_AT_EXIT: the power fails here, before the seventh save's sync */
}

static void scen_hardslot(void)
{
    scenario("hardslot");
    const char *so = getenv("CRASHFS_SO") ? getenv("CRASHFS_SO") : "./build/libcrashfs.so";
    if (access(so, F_OK) != 0) {
#ifdef __linux__
        die("no %s (make build/libcrashfs.so): the power-loss scenarios cannot run, and must not pass as skipped", so);
#else
        printf("  skipped: no %s\n", so);
        return;
#endif
    }
#if defined(__SANITIZE_ADDRESS__)
    printf("  skipped: crashfs cannot be preloaded into an AddressSanitizer build\n");
    return;
#elif defined(__has_feature)
#if __has_feature(address_sanitizer)
    printf("  skipped: crashfs cannot be preloaded into an AddressSanitizer build\n");
    return;
#endif
#endif
    char self[PATH_MAX];
    ssize_t sl = readlink("/proc/self/exe", self, sizeof self - 1);
    if (sl <= 0)
        die("readlink /proc/self/exe: %s", strerror(errno));
    self[sl] = '\0';
    for (int keep = 1; keep >= 0; keep--) {
        char top[PATH_MAX + 64], rd[PATH_MAX + 80];
        snprintf(top, sizeof top, "%s/hardslot-%d", base, keep);
        snprintf(rd, sizeof rd, "%s/raft", top);
        /* made before the child: crashfs does not track its root's own entries, and the open does not sync the parent
         * of a new directory */
        if (mkdir(top, 0755) != 0 || mkdir(rd, 0755) != 0)
            die("mkdir %s: %s", rd, strerror(errno));
        pid_t pid = fork();
        if (pid < 0)
            die("fork: %s", strerror(errno));
        if (pid == 0) {
            setenv("LD_PRELOAD", so, 1);
            setenv("CRASHFS_ROOT", top, 1);
            setenv("CRASHFS_PROB", "0", 1);
            setenv("CRASHFS_AT_EXIT", "1", 1);
            setenv("CRASHFS_REWRITE", keep ? "old" : "zero", 1); /* old bytes back (the default), or zeros (the harsher mode) */
            unsetenv("CRASHFS_TEAR");
            execl(self, self, "hardslot-child", rd, (char *)NULL);
            _exit(127);
        }
        int st = -1;
        if (waitpid(pid, &st, 0) != pid || !WIFEXITED(st) || WEXITSTATUS(st) != 0)
            die("the hardslot child (keep %d) ended with status 0x%x", keep, st);
        raft_hard_state hs;
        memset(&hs, 0, sizeof hs);
        char lerr[512] = "";
        iso_err e = raft_log_hard_load(rd, &hs, lerr, sizeof lerr);
        if (keep) {
            if (e != ISO_OK || hs.term != 6)
                die("CRASHFS_REWRITE=old: after a power cut inside the seventh hard save the state reads as rc %d term %" PRIu64
                    " (want term 6): %s",
                    (int)e, (uint64_t)hs.term, lerr);
            printf("  CRASHFS_REWRITE=old: a power cut inside a hard save leaves the previous one (term 6)\n");
        } else {
            if (e == ISO_OK)
                die("with CRASHFS_REWRITE=zero the zeroed slot read as term %" PRIu64 ": this scenario no longer reaches "
                    "the state the jepsen node was left in",
                    (uint64_t)hs.term);
            printf("  crashfs's default zeroes the slot, and the reader refuses it: %.120s\n", lerr);
        }
    }
}

/* Placement (item 10): a replacement voter comes from a power feed the voters do not use. */
static void scen_feed(void)
{
    scenario("feed");
    static const char *feed[5] = {"--power-feed A", "--power-feed A", "--power-feed B", "--power-feed A",
                                  "--power-feed C"};
    for (int i = 0; i < 5; i++) {
        xargs[i] = feed[i];
        start(i);
    }
    init_fast(0);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    node_add(0, 3); /* server 3 (feed A) joins before server 4 (feed C): the order alone would pick it */
    node_add(0, 4);
    stop(1, SIGKILL); /* a voter on feed A goes: the replacement must be the one on feed C */
    struct view v;
    uint64_t t0 = now_ms();
    int ok = 0;
    while (now_ms() - t0 < 40000 && !ok) {
        view(0, &v);
        ok = voters(&v) == 3 && v.cfg.n == 3 && !raft_config_find(&v.cfg, ids[1]);
        if (ok && (!is_voter(&v, ids[4]) || is_voter(&v, ids[3])))
            die("the replacement voter is server 3 (feed A) or not server 4 (feed C)");
        view_free(&v);
        usleep(200000);
    }
    if (!ok)
        die("the group was not repaired");
    printf("  the replacement voter comes from the feed the voters do not use\n");
}

/* REVIEW 1: a restarted member's persisted copy never goes back to an older image from a lagging voter. n2 is paused
 * while the leader commits a MEMBER_STATE and the watcher n3 persists its copy; then n3, n0 and n1 are killed, n2
 * resumed and n3 restarted: n2 is the only voter n3 can reach, and it is behind the copy. n3 used to take n2's image
 * (a persisted copy "yielded to any live image"), mark itself fresh and write the old state over its copy file. */
static int p_fresh_from(const struct view *v, void *a)
{
    return !v->st.stale && v->m.applied >= *(uint64_t *)a;
}

static void scen_copyback(void)
{
    scenario("copyback");
    envs[3] = "free_min=9999999999999999"; /* a watcher */
    for (int i = 0; i < 4; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    node_add(0, 3);
    pause_server(2, 1); /* n2 lags from here on */
    struct state_want down = {ids[2], META_DOWN, 0};
    await_view(0, p_member_state, &down, "n2 marked down");
    struct view x;
    view(0, &x);
    struct catch_up c = {x.m.applied, meta_hash(&x.m)};
    view_free(&x);
    await_view(3, p_caught_up, &c, "the watcher caught up");
    usleep(1500000); /* the copy file */
    uint64_t a = c.applied;
    stop(3, SIGKILL);
    stop(0, SIGKILL); /* the watcher's dial to them is refused at once: the lagging n2 is the one it reaches */
    stop(1, SIGKILL);
    pause_server(2, 0);
    view(2, &x);
    if (x.m.applied >= a)
        die("n2 is not behind the watcher's copy (%" PRIu64 " >= %" PRIu64 "): the test proves nothing", x.m.applied, a);
    view_free(&x);
    start(3);
    uint64_t t0 = now_ms();
    while (now_ms() - t0 < 6000) { /* n2 answers the watcher's dial: its older image must not be taken */
        view(3, &x);
        if (x.m.applied < a || !x.st.stale)
            die("the restarted watcher took a lagging voter's image: applied %" PRIu64 " (its copy %" PRIu64
                "), stale %d",
                x.m.applied, a, (int)x.st.stale);
        view_free(&x);
        usleep(200000);
    }
    stop(3, SIGTERM); /* a copy that went back would be what this start finds */
    start(3);
    view(3, &x);
    if (x.m.applied < a || !x.st.stale)
        die("the copy file went back to applied %" PRIu64 " (was %" PRIu64 ")", x.m.applied, a);
    view_free(&x);
    printf("  a restarted watcher keeps its copy against a lagging voter's older image\n");
}

/* REVIEW 2: a voter restarted while the group is away serves its persisted copy, marked stale (it used to serve an
 * empty state, or its last snapshot, as if it were current). */
static void scen_voterstale(void)
{
    scenario("voterstale");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    struct view x;
    view(0, &x);
    struct catch_up c = {x.m.applied, meta_hash(&x.m)};
    view_free(&x);
    await_view(1, p_caught_up, &c, "n1 caught up");
    usleep(1000000);
    pause_server(0, 1); /* the group is away (paused: a restart gets a new port, and the others would not find it) */
    pause_server(2, 1);
    stop(1, SIGTERM);
    start(1);
    usleep(3000000);
    view(1, &x);
    if (!x.st.stale || x.m.applied < c.applied || x.m.nmembers != 3)
        die("the voter restarted alone shows stale %d, applied %" PRIu64 " (was %" PRIu64 "), %u members (3 expected)",
            (int)x.st.stale, x.m.applied, c.applied, x.m.nmembers);
    view_free(&x);
    pause_server(0, 0);
    pause_server(2, 0);
    await_view(1, p_fresh_from, &c.applied, "the voter confirmed once the group is back");
    printf("  a voter restarted while the group is away serves its copy, marked stale, then the live state\n");
}

/* Regression: a voter restarted from a snapshot whose C.sm holds stale peer ports for voters that restarted while it
 * was down (or before C.sm applied past their MEMBER_ADDR) must prefer the fresher peer addresses from its watch probe
 * (C.wsm) and persisted copy (C.cpy) instead of dialing dead ports forever. */
static void scen_snapmove(void)
{
    scenario("snapmove");
    for (int i = 0; i < 5; i++) {
        envs[i] = "snap_every=2";
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 5; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters");
    struct view x;
    view(0, &x);
    struct catch_up c = {x.m.applied, meta_hash(&x.m)};
    view_free(&x);
    await_view(1, p_caught_up, &c, "n1 caught up");
    char snap[PATH_MAX + 128];
    snprintf(snap, sizeof snap, "%s/n1/state/snapshot", base);
    for (uint64_t t0 = now_ms(); access(snap, F_OK) != 0; usleep(50000))
        if (now_ms() - t0 > 15000)
            die("n1 did not write %s", snap);
    /* Stop n1 (its snapshot holds the original peer ports of n0, n2, n3, n4), then restart n0, n2, n3 one by one so
     * each moves to a new ephemeral peer port while n4 stays at its original port (reachable by n1's watch probe). */
    stop(1, SIGTERM);
    int moved[3] = {0, 2, 3};
    for (int k = 0; k < 3; k++) {
        int i = moved[k];
        struct state_want up = {ids[i], META_UP, 2};
        stop(i, SIGTERM);
        start(i);
        await_view(4, p_member_state, &up, "moved voter back UP");
    }
    /* Ensure the Raft leader is one of the moved voters (0, 2, or 3), not n4: if n4 leads, pause it briefly so a
     * moved voter wins leadership (quorum 3 of {0, 2, 3}), then unpause n4. */
    view(4, &x);
    uint32_t lead = x.st.leader;
    view_free(&x);
    if (lead != ids[0] && lead != ids[2] && lead != ids[3]) {
        pause_server(4, 1);
        for (uint64_t t0 = now_ms();; usleep(100000)) {
            view(0, &x);
            lead = x.st.leader;
            view_free(&x);
            if (lead == ids[0] || lead == ids[2] || lead == ids[3])
                break;
            if (now_ms() - t0 > 30000)
                die("no moved voter led while n4 was paused (leader %" PRIu32 ")", lead);
        }
        pause_server(4, 0);
    }
    /* Now restart n1 at a new ephemeral peer port: the leader (a moved voter) only knows n1's old port, and n1's
     * snapshot only knows the leader's old port; n1 must learn the leader's new port via its watch probe to n4. */
    start(1);
    struct state_want n1_up = {ids[1], META_UP, 2};
    await_view(4, p_member_state, &n1_up, "restarted voter back UP after leader moved ports");
    view(4, &x);
    uint64_t app = x.m.applied;
    view_free(&x);
    await_view(1, p_fresh_from, &app, "restarted voter caught up with moved leader");
    printf("  voter restarted from stale snapshot learned moved leader's new peer port via watch probe\n");
}

/* REVIEW 4: in shared mode a fault on the state directory ends the voter role only: tsdbd and its volumes go on. */
static void scen_dirsync_shared(void)
{
    scenario("dirsyncshared");
    envs[0] = "snap_every=2,fail_snap_dirsync=1";
    start(0);
    start(1);
    struct meta_settings s;
    meta_settings_default(&s);
    uint8_t req[META_ADDR_MAX + 64], *rep = NULL;
    size_t n = cluster_settings_encode(&s, META_MODE_SHARED, req), len;
    char addr[META_ADDR_MAX], err[1024];
    peer_of(0, addr, sizeof addr);
    int rc;
    if (cluster_admin(addr, secret, secret_len, CLUSTER_OP_INIT, req, n, 5000, &rc, &rep, &len, err, sizeof err) == 0)
        free(rep);
    n = node_add_req(1, req);
    if (cluster_admin(addr, secret, secret_len, CLUSTER_OP_NODE_ADD, req, n, 5000, &rc, &rep, &len, err,
                      sizeof err) == 0)
        free(rep);
    uint64_t t0 = now_ms();
    while (now_ms() - t0 < 10000 && !log_has(0, "ends the voter role only"))
        usleep(100000);
    if (!log_has(0, "ends the voter role only"))
        die("shared mode: a failed directory fsync after a snapshot did not end the voter role");
    if (await_exit(0, 1500) >= 0)
        die("shared mode: a failed state-directory fsync after a snapshot stopped tsdbd");
    printf("  shared mode: a failed directory fsync after a snapshot ends the voter role, tsdbd goes on\n");
}

/* REVIEW 4: the same for an install whose snapshot cannot be written (a directory in the way of its temp file). */
static void install_shared(int pend)
{
    scenario(pend ? "pendshared" : "installshared");
    for (int i = 0; i < 3; i++)
        envs[i] = "snap_every=2,snap_retain=1,seg_bytes=200";
    if (pend)
        envs[2] = "snap_every=2,snap_retain=1,seg_bytes=200,fail_pend_dirsync=1"; /* the kept image's directory sync */
    for (int i = 0; i < 3; i++)
        start(i);
    init_mode(0, 3, META_MODE_SHARED);
    node_add(0, 1);
    if (!pend)
        meta_tmp(2, 1);
    node_add(0, 2);
    uint64_t t0 = now_ms();
    while (now_ms() - t0 < 15000 && !log_has(2, "ends the voter role only"))
        usleep(100000);
    if (!log_has(2, "ends the voter role only"))
        die("shared mode: an install that cannot be written did not end the voter role");
    if (await_exit(2, 1500) >= 0)
        die("shared mode: an install that cannot be written stopped tsdbd");
    if (!pend)
        meta_tmp(2, 0);
    printf("  shared mode: a snapshot install that cannot be %s ends the voter role, tsdbd goes on\n",
           pend ? "kept" : "written");
}
static void scen_install_shared(void) { install_shared(0); }
static void scen_pend_shared(void) { install_shared(1); }

/* REVIEW 4: a coreless member's copy file whose directory cannot be synced: replicated mode stops, shared mode logs. */
static void scen_copyfault(void)
{
    scenario("copyfault");
    envs[1] = "free_min=9999999999999999,fail_copy_dirsync=1"; /* a watcher */
    start(0);
    start(1);
    init_mode(0, 600, META_MODE_SHARED);
    node_add(0, 1);
    uint64_t t0 = now_ms();
    while (now_ms() - t0 < 10000 && !log_has(1, "sync the directory of"))
        usleep(100000);
    if (!log_has(1, "sync the directory of"))
        die("the watcher never wrote its copy (the test proves nothing)");
    if (await_exit(1, 1500) >= 0)
        die("shared mode: a copy file whose directory cannot be synced stopped tsdbd");
    printf("  shared mode: a copy file that cannot be synced is logged, tsdbd goes on\n");
}

/* ---- replicated volumes (r3c-volumes; design-cluster.md 3.1, 8.5, DECISION D2) ---- */

/* a client library result, printed (the engine's tsdb_strerror is not linked here) */
static const char *ers(int rc)
{
    static char b[4][24];
    static int k;
    k = (k + 1) & 3;
    snprintf(b[k], sizeof b[k], "error %d", rc);
    return b[k];
}

static int vol_add(int i, const char *name, uint32_t replicas, uint32_t *number)
{
    uint8_t req[2 + META_NAME_MAX + 4], *reply;
    size_t len, rl = cluster_volume_add_encode(name, replicas, req);
    int rc = admin(i, CLUSTER_OP_VOLUME_ADD, req, rl, 1, &reply, &len);
    *number = 0;
    for (size_t k = 0; rc == 0 && k < 4 && k < len; k++)
        *number |= (uint32_t)reply[k] << (8 * k);
    free(reply);
    return rc;
}

/* volume `name` in server i's copy, or NULL (copied out: the view is freed) */
static int vol_rec(int i, const char *name, struct meta_volume *out)
{
    struct view v;
    view(i, &v);
    int found = 0;
    for (uint32_t k = 0; k < v.m.nvolumes && !found; k++)
        if (!strcmp(v.m.volumes[k].name, name)) {
            *out = v.m.volumes[k];
            out->hist = NULL;
            out->nhist = 0;
            found = 1;
        }
    view_free(&v);
    return found;
}

static const struct meta_replica *rep_of(const struct meta_volume *v, int i)
{
    for (uint32_t k = 0; k < v->nrep; k++)
        if (v->rep[k].node == ids[i])
            return &v->rep[k];
    return NULL;
}

static int server_of(uint32_t node)
{
    for (int i = 0; i < N; i++)
        if (ids[i] == node)
            return i;
    return -1;
}

/* waits until server `via`'s copy records open generation >= gen for server i (rid unchanged when rid != 0) */
static void await_open_gen(int via, const char *name, int i, uint64_t gen, uint64_t rid)
{
    uint64_t t0 = now_ms();
    struct meta_volume v;
    while (now_ms() - t0 < 30000) {
        const struct meta_replica *r;
        if (vol_rec(via, name, &v) && (r = rep_of(&v, i)) && r->open_gen >= gen) {
            if (rid && r->rid != rid)
                die("server %d's replica of %s changed rid %016" PRIx64 " -> %016" PRIx64, i, name, rid, r->rid);
            return;
        }
        usleep(100000);
    }
    die("server %d's open generation %" PRIu64 " of %s was not recorded", i, gen, name);
}

static int log_count(int i, const char *needle)
{
    char path[PATH_MAX + 80], line[4096];
    snprintf(path, sizeof path, "%s/n%d.log", base, i);
    FILE *f = fopen(path, "r");
    int hits = 0;
    while (f && fgets(line, sizeof line, f))
        hits += strstr(line, needle) != NULL;
    if (f)
        fclose(f);
    return hits;
}

/* the lines of server i's log with `needle` after its first `skip` lines (log_count(i, "") counts every line) */
static int log_count_from(int i, const char *needle, int skip)
{
    char path[PATH_MAX + 80], line[4096];
    snprintf(path, sizeof path, "%s/n%d.log", base, i);
    FILE *f = fopen(path, "r");
    int hits = 0;
    for (int n = 0; f && fgets(line, sizeof line, f); n++)
        hits += n >= skip && strstr(line, needle) != NULL;
    if (f)
        fclose(f);
    return hits;
}

static void await_log_count(int i, const char *needle, int want, int ms)
{
    uint64_t t0 = now_ms();
    while (log_count(i, needle) < want) {
        if (now_ms() - t0 > (uint64_t)ms)
            die("server %d: no %d lines with \"%s\" in %d ms", i, want, needle, ms);
        usleep(50000);
    }
}

static void slurp(const char *path, char *buf, size_t n)
{
    FILE *f = fopen(path, "r");
    if (!f)
        die("%s: %s", path, strerror(errno));
    size_t got = fread(buf, 1, n - 1, f);
    buf[got] = 0;
    fclose(f);
}

/* the REPL file of server i's v<number>: rid and open generation of the slot with the newer file generation (the
 * layout of src/replfile.c, which this test does not link: two 4 KiB slots, magic "DS_BREP2" at 0, generation at 8,
 * rid at 72, open generation at 80; the checksum is the server's to check) */
static void repl_of(int i, uint32_t number, uint64_t *rid, uint64_t *gen)
{
    char dir[PATH_MAX + 80], path[PATH_MAX + 160];
    uint8_t pg[2][4096];
    server_dir(i, dir, sizeof dir);
    snprintf(path, sizeof path, "%s/v%" PRIu32 "/REPL", dir, number);
    FILE *f = fopen(path, "r");
    if (!f)
        die("%s: %s", path, strerror(errno));
    size_t got = fread(pg, 1, sizeof pg, f);
    fclose(f);
    if (got != sizeof pg)
        die("%s: %zu bytes, not two slots", path, got);
    uint64_t g[2];
    for (int k = 0; k < 2; k++) {
        memcpy(&g[k], pg[k] + 8, 8);
        if (memcmp(pg[k], "DS_BREP2", 8) != 0)
            die("%s: slot %d has no REPL magic", path, k);
    }
    int n = g[1] > g[0];
    memcpy(rid, pg[n] + 72, 8);
    memcpy(gen, pg[n] + 80, 8);
}

static int nrows;
static int count_rows(void *ctx, const int64_t *ts, const float *v, size_t n)
{
    (void)ctx, (void)ts, (void)v;
    nrows += (int)n;
    return 0;
}

static tsdbc *client(int i)
{
    tsdbc *c;
    int rc = tsdbc_connect("127.0.0.1", cports[i], &c);
    if (rc != 0)
        die("connect to server %d: %s", i, ers(rc));
    tsdbc_set_retry(c, 0); /* the test looks at every UNAVAILABLE */
    return c;
}

/* rc is MOVED, one entry: volume `vol` to node `node` at server s's client address (the copy's MEMBER_ADDR) */
static void expect_moved(tsdbc *c, int rc, uint32_t vol, uint32_t node, int s, const char *what)
{
    tsdbc_err_info e;
    char want[64];
    snprintf(want, sizeof want, "127.0.0.1:%d", cports[s]);
    if (rc != TSDB_ERR_MOVED || tsdbc_last_error(c, &e) != TSDB_ERR_MOVED || e.nmoved != 1 || e.moved[0].vol != vol ||
        e.moved[0].node_id != node || strcmp(e.moved[0].addr, want) != 0)
        die("%s: %s, %u MOVED (volume %u node %u at %s), want MOVED of volume %u to node %u at %s", what, ers(rc),
            rc == TSDB_ERR_MOVED ? e.nmoved : 0, rc == TSDB_ERR_MOVED && e.nmoved ? e.moved[0].vol : 0,
            rc == TSDB_ERR_MOVED && e.nmoved ? (unsigned)e.moved[0].node_id : 0,
            rc == TSDB_ERR_MOVED && e.nmoved ? e.moved[0].addr : "-", (unsigned)vol, (unsigned)node, want);
}

/* rc is UNAVAILABLE and its body names volume `vol` (TSDB_VOL_ANY: any) and reason `why` */
static void expect_unavail(tsdbc *c, int rc, uint16_t vol, int why, const char *what)
{
    tsdb_unavail e;
    unsigned n = 0;
    if (rc != TSDB_ERR_UNAVAILABLE)
        die("%s: %s, not UNAVAILABLE", what, ers(rc));
    if (tsdbc_unavailable(c, &e, 1, &n) != 0 || n != 1 || (vol != TSDB_VOL_ANY && e.vol != vol) || e.reason != why)
        die("%s: UNAVAILABLE names volume %u reason %u (%u entries), not volume %u reason %d", what, n ? e.vol : 0,
            n ? e.reason : 0, n, vol, why);
}

/* rc is server s's answer for volume `name` (number vol) that is not open there (held, refused, stale): the entry
 * node decides from the copy alone (route_decide), so the volume's leader answers UNAVAILABLE (RECOVERING) and any
 * other server MOVED to that leader, whatever its own directory holds */
static void expect_held(tsdbc *c, int rc, int s, const char *name, uint16_t vol, const char *what)
{
    struct meta_volume w;
    if (!vol_rec(0, name, &w) || w.number != vol)
        die("%s: the record of %s is missing", what, name);
    int ls = server_of(w.leader);
    if (ls < 0)
        die("%s: the leader of %s is node %u, no server", what, name, (unsigned)w.leader);
    if (ls == s)
        expect_unavail(c, rc, vol, TSDB_WHY_RECOVERING, what);
    else
        expect_moved(c, rc, vol, w.leader, ls, what);
}

/* expect_moved with the epoch checked (design-cluster.md 6.3): a write to a replicated volume on a server that does not lead it, naming
 * volume `vol` and its leader `node` at `epoch` with that server's client address */
static void expect_moved_ep(tsdbc *c, int rc, uint16_t vol, uint32_t node, uint64_t epoch, const char *what)
{
    tsdbc_err_info e;
    if (rc != TSDB_ERR_MOVED)
        die("%s: %s, not MOVED", what, ers(rc));
    if (tsdbc_last_error(c, &e) != TSDB_ERR_MOVED || !e.has_body || e.nmoved != 1)
        die("%s: MOVED without one entry (body %d, %u entries)", what, e.has_body, e.nmoved);
    int s = server_of(node);
    char port[16];
    snprintf(port, sizeof port, ":%d", s >= 0 ? cports[s] : -1);
    size_t al = strlen(e.moved[0].addr), pl = strlen(port);
    if (e.moved[0].vol != vol || e.moved[0].node_id != node || e.moved[0].epoch != epoch || al < pl ||
        strcmp(e.moved[0].addr + al - pl, port) != 0)
        die("%s: MOVED names volume %u, node %u at epoch %u, address %s; not volume %u, node %u at epoch %" PRIu64
            ", port %s", what, e.moved[0].vol, e.moved[0].node_id, e.moved[0].epoch, e.moved[0].addr, vol, node, epoch,
            port + 1);
}

/* a write of one row to a server that no longer leads `vol` after a promotion, expected to be MOVED to (node, epoch).
 * The server answers from its own copy of the record, which the group's watch delivers a little after the record
 * another server reported: until then it may say UNAVAILABLE (its volume is fenced and the record still names it) or
 * MOVED to the leader of an older epoch. Both refuse before numbering anything, so they are retried for 5 s; anything
 * else, or a stale answer after that, fails (r3e-clus4: writerdepose got UNAVAILABLE right after the record moved). */
static void insert_expect_moved(tsdbc *c, tsdb_sid id, int64_t ts, float val, uint16_t vol, uint32_t node,
                                uint64_t epoch, const char *what)
{
    for (uint64_t t0 = now_ms();; usleep(50000)) {
        int rc = tsdbc_insert_series(c, id, &ts, &val, 1);
        tsdbc_err_info e;
        int stale = rc == TSDB_ERR_UNAVAILABLE ||
                    (rc == TSDB_ERR_MOVED && tsdbc_last_error(c, &e) == TSDB_ERR_MOVED && e.has_body &&
                     e.nmoved == 1 && e.moved[0].epoch < epoch);
        if (!stale || now_ms() - t0 > 5000) {
            expect_moved_ep(c, rc, vol, node, epoch, what);
            return;
        }
    }
}

/* series pump7.flow in `vol` on server i: made, written and read back (returns its id) */
static tsdb_sid write_read(tsdbc *c, const char *vol, int64_t t0)
{
    tsdb_sid id = 0;
    int rc = tsdbc_series_at(c, "pump7.flow", vol, &id);
    if (rc != 0)
        die("series pump7.flow in %s: %s", vol, ers(rc));
    int64_t ts[3] = {t0, t0 + 1000, t0 + 2000};
    float v[3] = {1, 2, 3};
    if ((rc = tsdbc_insert_series(c, id, ts, v, 3)) != 0)
        die("insert into %s: %s", vol, ers(rc));
    return id;
}

static int rows_of(tsdbc *c, tsdb_sid id)
{
    nrows = 0;
    int rc = tsdbc_query_raw(c, id, 0, INT64_MAX / 2, count_rows, NULL);
    if (rc != 0)
        die("query: %s", ers(rc));
    return nrows;
}

static int cli_run(const char *args, const char *in, char *out, size_t n)
{
    const char *cli = getenv("TSDB_CLI") ? getenv("TSDB_CLI") : "./build/tsdb";
    char cmd[PATH_MAX * 3 + 256];
    snprintf(cmd, sizeof cmd, "%s%s%s %s 2>&1", in ? in : "", in ? " | " : "", cli, args);
    FILE *p = popen(cmd, "r");
    if (!p)
        die("popen %s: %s", cmd, strerror(errno));
    size_t got = fread(out, 1, n - 1, p);
    out[got] = 0;
    int st = pclose(p);
    return WIFEXITED(st) ? WEXITSTATUS(st) : 255;
}

/* `tsdb ARGS` started without waiting (cli_finish reads its output and status): two CLI calls at once */
static FILE *cli_start(const char *args)
{
    const char *cli = getenv("TSDB_CLI") ? getenv("TSDB_CLI") : "./build/tsdb";
    char cmd[PATH_MAX * 3 + 256];
    snprintf(cmd, sizeof cmd, "%s %s 2>&1", cli, args);
    FILE *p = popen(cmd, "r");
    if (!p)
        die("popen %s: %s", cmd, strerror(errno));
    return p;
}

static int cli_finish(FILE *p, char *out, size_t n)
{
    size_t got = fread(out, 1, n - 1, p);
    out[got] = 0;
    int st = pclose(p);
    return WIFEXITED(st) ? WEXITSTATUS(st) : 255;
}

struct users_want {
    const char *present[3];
    const char *absent;
};
static int p_users(const struct view *v, void *a)
{
    const struct users_want *w = a;
    for (int k = 0; k < 3 && w->present[k]; k++)
        if (!meta_user(&v->m, w->present[k]))
            return 0;
    return !w->absent || !meta_user(&v->m, w->absent);
}

static int p_users_caught_up(const struct view *v, void *a)
{
    (void)a;
    return v->st.users_caught_up == 1;
}

/* the file a server's users probe wrote (TSDB_CLUSTER_TEST users_probe=1), "" while there is none */
static void probe_read(int i, const char *name, char *out, size_t n)
{
    char path[PATH_MAX + 96];
    server_dir(i, path, sizeof path);
    strcat(path, "/state/");
    strcat(path, name);
    out[0] = 0;
    FILE *f = fopen(path, "r");
    if (f) {
        size_t got = fread(out, 1, n - 1, f);
        out[got] = 0;
        fclose(f);
    }
}

static void await_probe(int i, const char *name, const char *want, const char *what)
{
    char out[8192];
    uint64_t t0 = now_ms();
    for (probe_read(i, name, out, sizeof out); !strstr(out, want); probe_read(i, name, out, sizeof out)) {
        if (now_ms() - t0 > WAIT_MS)
            die("server %d: %s: no \"%s\" in its %s: %s", i, what, want, name, out);
        usleep(50000);
    }
}

/* S2-1: users in the metadata group. `cluster init --superuser` puts root (uid 1) in the first entries; two `cluster
 * user add` of different names through two servers at once get different uids, the same in every copy (the state
 * machine assigns them; the CLI sends uid 0, so this checks the end to end path only: the uid rules have their mutant,
 * uidfromproposer, in test_meta); a grant made through one server is listed by another; the users watch and
 * cluster_user_propose (users_probe); a drop with a member stopped (SIGSTOP) is answered after --wait-ms naming that
 * member as lagging, and the member applies the drop once it runs again. With no quorum a USER_DEL is never answered
 * OK (mutant dropnotcommitted: OK at propose). The watch ring drops entries past its bytes. A restarted member whose
 * Raft core is held reports users_caught_up only after it heard a leader's commit index and applied that far (mutants
 * caughtupearly: true from the start; floornoapplied: true once the commit index is heard). */
/* SEC-01: assert state dir and raft/ dir are 0700 and every file under them (snapshots, NODE, IDENT, hard, segments)
 * has no group/other permission bits (mode & 077 == 0). */
static void check_state_perms(int i)
{
    char sdir[PATH_MAX + 64], rdir[PATH_MAX + 80];
    server_dir(i, sdir, sizeof sdir);
    strcat(sdir, "/state");
    snprintf(rdir, sizeof rdir, "%s/raft", sdir);
    struct stat st;
    if (stat(sdir, &st) != 0 || !S_ISDIR(st.st_mode) || (st.st_mode & 077) != 0)
        die("server %d: state dir %s has mode %03o (want 0700)", i, sdir, (unsigned)(st.st_mode & 0777));
    if (stat(rdir, &st) != 0 || !S_ISDIR(st.st_mode) || (st.st_mode & 077) != 0)
        die("server %d: raft dir %s has mode %03o (want 0700)", i, rdir, (unsigned)(st.st_mode & 0777));
    int saw_snap = 0, saw_hard = 0, saw_seg = 0;
    const char *dirs[2] = {sdir, rdir};
    for (int d = 0; d < 2; d++) {
        DIR *dp = opendir(dirs[d]);
        if (!dp)
            die("opendir %s: %s", dirs[d], strerror(errno));
        for (struct dirent *e; (e = readdir(dp));) {
            if (!strcmp(e->d_name, ".") || !strcmp(e->d_name, ".."))
                continue;
            char fp[PATH_MAX + 384];
            snprintf(fp, sizeof fp, "%s/%s", dirs[d], e->d_name);
            if (lstat(fp, &st) != 0)
                continue;
            if (S_ISREG(st.st_mode) && (st.st_mode & 077) != 0)
                die("server %d: %s has mode %03o (group/other bits set)", i, fp, (unsigned)(st.st_mode & 0777));
            if (d == 0 && !strcmp(e->d_name, "snapshot"))
                saw_snap = 1;
            if (d == 1 && !strcmp(e->d_name, "hard"))
                saw_hard = 1;
            if (d == 1 && !strncmp(e->d_name, "log-", 4))
                saw_seg = 1;
        }
        closedir(dp);
    }
    if (!saw_snap || !saw_hard || !saw_seg)
        die("server %d: missing expected state files (snap=%d hard=%d seg=%d)", i, saw_snap, saw_hard, saw_seg);
}

static void scen_users(void)
{
    scenario("users");
    mode_t old_umask = umask(0022); /* SEC-01: verify 0700/0600 even under default 0022 umask */
    strict_reads = 1; /* a replica moves reads to the leader (D5), as in production */
    /* frequent snapshots: the member restarted below loads its copy (members, addresses, carol) from one, so it reaches
     * the leader with its Raft core held; server 1 registers a users watch and drops probe-drop through
     * cluster_user_propose; a watch ring of 256 KiB, which two big blobs pass */
    envs[0] = envs[2] = "snap_every=2,ring_bytes=262144";
    envs[1] = "snap_every=2,ring_bytes=262144,users_probe=1";
    for (int i = 0; i < 3; i++)
        start(i);
    char pw[PATH_MAX + 80], args[PATH_MAX * 2 + 512], out[8192], out2[8192], p[3][META_ADDR_MAX];
    snprintf(pw, sizeof pw, "%s/pw", base);
    FILE *f = fopen(pw, "w");
    if (!f || fputs("correct horse battery\n", f) < 0 || fclose(f) != 0)
        die("cannot write %s", pw);
    for (int i = 0; i < 3; i++)
        peer_of(i, p[i], sizeof p[i]);
    /* a password file that cannot be read is found before INIT: the cluster stays uninitialised (the init below works) */
    snprintf(args, sizeof args, "cluster init %s --secret-file %s --superuser root --password-file %s/missing", p[0],
             secret_path, base);
    if (cli_run(args, NULL, out, sizeof out) == 0 || strstr(out, "initialised"))
        die("cluster init with an unreadable password file: %s", out);
    snprintf(args, sizeof args,
             "cluster init %s --secret-file %s --node-timeout-ms 1500 --heartbeat-ms 200 --voter-replace-s 600 "
             "--superuser root --password-file %s",
             p[0], secret_path, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user root: uid 1, index "))
        die("cluster init --superuser root: %s", out);
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");

    /* two adds at once, through the leader and through a follower */
    char a1[PATH_MAX * 2 + 512], a2[PATH_MAX * 2 + 512];
    snprintf(a1, sizeof a1, "cluster user add %s alice --password-file %s --secret-file %s", p[0], pw, secret_path);
    snprintf(a2, sizeof a2, "cluster user add %s bob --password-file %s --secret-file %s", p[1], pw, secret_path);
    FILE *c1 = cli_start(a1), *c2 = cli_start(a2);
    int r1 = cli_finish(c1, out, sizeof out), r2 = cli_finish(c2, out2, sizeof out2);
    if (r1 != 0 || !strstr(out, "put user alice: uid "))
        die("user add alice: %s", out);
    if (r2 != 0 || !strstr(out2, "put user bob: uid "))
        die("user add bob: %s", out2);
    struct users_want all3 = {{"root", "alice", "bob"}, NULL};
    uint32_t uid[3][3];
    for (int i = 0; i < 3; i++) {
        await_view(i, p_users, &all3, "root, alice and bob in its copy");
        struct view v;
        view(i, &v);
        for (int k = 0; k < 3; k++)
            uid[i][k] = meta_user(&v.m, all3.present[k])->uid;
        view_free(&v);
        if (uid[i][0] != 1 || uid[i][1] == uid[i][2] || uid[i][1] < 2 || uid[i][1] > 3 || uid[i][2] < 2 ||
            uid[i][2] > 3)
            die("server %d: uids root %" PRIu32 ", alice %" PRIu32 ", bob %" PRIu32 " (want 1 and 2, 3 apart)", i,
                uid[i][0], uid[i][1], uid[i][2]);
        if (i && memcmp(uid[i], uid[0], sizeof uid[0]))
            die("server %d has other uids than server 0", i);
    }
    printf("  root uid 1, alice uid %" PRIu32 ", bob uid %" PRIu32 " in every copy\n", uid[0][1], uid[0][2]);

    /* server 1's users watch has the three; probe-drop, added through server 0, is dropped by server 1's probe through
     * cluster_user_propose (a follower: it sends to the leader), in every copy */
    await_probe(1, "userswatch", "user alice uid ", "the users watch");
    await_probe(1, "userswatch", "user bob uid ", "the users watch");
    await_probe(1, "userswatch", "user root uid 1 ", "the users watch");
    snprintf(args, sizeof args, "cluster user add %s probe-drop --password-file %s --secret-file %s", p[0], pw,
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user probe-drop: uid "))
        die("user add probe-drop: %s", out);
    await_probe(1, "userpropose", "rc 0 index ", "cluster_user_propose's DEL");
    for (int i = 0; i < 3; i++)
        await_view(i, p_users, &(struct users_want){{"root", "alice", "bob"}, "probe-drop"}, "probe-drop dropped");
    {
        char w[8192];
        uint64_t t1 = now_ms();
        for (probe_read(1, "userswatch", w, sizeof w); strstr(w, "probe-drop"); probe_read(1, "userswatch", w, sizeof w))
            if (now_ms() - t1 > WAIT_MS)
                die("server 1's users watch still lists probe-drop: %s", w);
            else
                usleep(50000);
    }
    printf("  users watch and cluster_user_propose: probe-drop dropped from server 1\n");

    /* a grant through a follower, listed by the third server from its copy */
    snprintf(args, sizeof args, "cluster user grant %s alice prefix:plant. read --secret-file %s", p[1], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user alice: uid "))
        die("user grant: %s", out);
    snprintf(args, sizeof args, "cluster user list %s alice --secret-file %s", p[2], secret_path);
    uint64_t t0 = now_ms();
    while (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "\ngrant prefix:plant. read\n"))
        if (now_ms() - t0 > WAIT_MS)
            die("server 2 does not list alice's grant: %s", out);
        else
            usleep(100000);
    snprintf(args, sizeof args, "cluster user list %s root --secret-file %s", p[2], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "\nsuperuser yes\npassword yes\n"))
        die("root is no superuser with a password: %s", out);
    /* a name longer than USERS allows is refused before anything is built (it overflowed a stack buffer) */
    {
        char lname[400];
        memset(lname, 'a', sizeof lname - 1);
        lname[sizeof lname - 1] = 0;
        snprintf(args, sizeof args, "cluster user list %s %s --secret-file %s", p[2], lname, secret_path);
        int lrc = cli_run(args, NULL, out, sizeof out);
        if (lrc != 2 || !strstr(out, "not a valid user name"))
            die("user list with a 399-byte name: rc %d: %s", lrc, out);
    }
    snprintf(args, sizeof args, "cluster user list %s --secret-file %s", p[1], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "user root uid 1 version ") ||
        !strstr(out, "user alice uid ") || !strstr(out, "user bob uid "))
        die("user list: %s", out);

    /* a drop with server 2 stopped: answered after the wait, naming server 2 as lagging (server 1 is not) */
    pause_server(2, 1);
    snprintf(args, sizeof args, "cluster user drop %s alice --wait-ms 1500 --secret-file %s", p[0], secret_path);
    t0 = now_ms();
    int rc = cli_run(args, NULL, out, sizeof out);
    uint64_t took = now_ms() - t0;
    char lag2[64], lag1[64];
    snprintf(lag2, sizeof lag2, "lagging: node %" PRIu32 " applied ", ids[2]);
    snprintf(lag1, sizeof lag1, "lagging: node %" PRIu32 " applied ", ids[1]);
    if (rc != 0 || !strstr(out, "dropped user alice") || !strstr(out, lag2) || strstr(out, lag1) || took < 1400)
        die("user drop with server 2 stopped (%" PRIu64 " ms): %s", took, out);
    printf("  drop answered after %" PRIu64 " ms naming node %" PRIu32 " as lagging\n", took, ids[2]);
    struct users_want gone = {{"root", "bob", NULL}, "alice"};
    await_view(1, p_users, &gone, "alice dropped on server 1");
    pause_server(2, 0);
    await_view(2, p_users, &gone, "alice dropped on server 2 once it runs again");

    /* no quorum: a USER_DEL is never answered OK */
    pause_server(1, 1);
    pause_server(2, 1);
    {
        uint8_t req[64], *reply = NULL;
        size_t rl = 0, len = 0;
        req[rl++] = 3;
        req[rl++] = 0;
        memcpy(req + rl, "bob", 3);
        rl += 3;
        memset(req + rl, 0, 12); /* version 0, wait_ms 0 */
        rl += 12;
        char err[1024];
        int arc = 0;
        int sent = cluster_admin(p[0], secret, secret_len, CLUSTER_OP_USER_DEL, req, rl, 3000, &arc, &reply, &len,
                                 err, sizeof err);
        free(reply);
        if (sent == 0 && arc == 0)
            die("USER_DEL answered OK with two of three voters stopped: before it committed");
        printf("  no quorum: USER_DEL %s\n", sent ? err : cluster_strerror(arc));
    }
    pause_server(1, 0);
    pause_server(2, 0);

    /* the no-quorum check may have moved the leadership: the member stopped below is one that does not lead */
    int l = -1;
    for (uint64_t t2 = now_ms(); l < 0; usleep(100000)) {
        for (int i = 0; i < 3 && l < 0; i++) {
            struct view v;
            view(i, &v);
            if (p_leader_self(&v, NULL))
                l = i;
            view_free(&v);
        }
        if (l < 0 && now_ms() - t2 > WAIT_MS)
            die("no leader after the no-quorum check");
    }
    int x = l == 2 ? 1 : 2;
    /* the watch ring is bounded by bytes, not only by entries: every put carries the whole blob (up to 1 MiB) */
    for (int k = 0; k < 2; k++) {
        size_t bl = 200 << 10, rl = 0, len = 0;
        uint8_t *req = calloc(1, 64 + bl), *reply = NULL;
        if (!req)
            die("out of memory");
        req[rl++] = 7;
        req[rl++] = 0;
        memcpy(req + rl, k ? "bigblob" : "bigblub", 7);
        rl += 7;
        rl += 12; /* version 0 (a new user), wait_ms 0 */
        memcpy(req + rl, &(uint32_t){(uint32_t)bl}, 4); /* little-endian, as the wire */
        rl += 4 + bl;
        char err[1024];
        int arc = 0;
        if (cluster_admin(p[l], secret, secret_len, CLUSTER_OP_USER_PUT, req, rl, 10000, &arc, &reply, &len, err,
                          sizeof err) != 0 || arc != 0)
            die("USER_PUT of a 200 KiB blob: %s", arc ? cluster_strerror(arc) : err);
        free(reply);
        memcpy(req + 2, k ? "bigblob" : "bigblub", 7);
        if (cluster_admin(p[l], secret, secret_len, CLUSTER_OP_USER_DEL, req, 2 + 7 + 12, 10000, &arc, &reply, &len,
                          err, sizeof err) != 0 || arc != 0)
            die("USER_DEL of a 200 KiB blob's user: %s", arc ? cluster_strerror(arc) : err);
        free(reply);
        free(req);
    }
    /* the server checks a name itself (the CLI does too, so only a raw request reaches this): a control byte is refused */
    {
        uint8_t req[64], *reply = NULL;
        size_t rl = 0, len = 0;
        req[rl++] = 8;
        req[rl++] = 0;
        memcpy(req + rl, "bad\tname", 8);
        rl += 8;
        memset(req + rl, 0, 12); /* version 0 (a new user), wait_ms 0 */
        rl += 12;
        memcpy(req + rl, &(uint32_t){4}, 4);
        rl += 4;
        memset(req + rl, 0, 4); /* the uid placeholder */
        rl += 4;
        char err[1024];
        int arc = 0;
        int sent = cluster_admin(p[l], secret, secret_len, CLUSTER_OP_USER_PUT, req, rl, 10000, &arc, &reply, &len, err,
                                 sizeof err);
        free(reply);
        if (sent != 0 || arc != META_ERR_INVALID)
            die("USER_PUT of the name \"bad\\tname\": %s, not INVALID", sent ? err : cluster_strerror(arc));
        printf("  a name with a control byte is refused by the server\n");
    }
    t0 = now_ms();
    while (!log_has(l, "the watch ring holds") && now_ms() - t0 < WAIT_MS)
        usleep(50000);
    if (!log_has(l, "the watch ring holds"))
        die("server %d kept 400 KiB of blobs in a watch ring of 256 KiB", l);
    printf("  the watch ring drops its oldest entries past its bytes\n");
    /* a restarted member is not caught up until it heard a leader's commit index and applied it: carol is dropped while
     * member x is down; it restarts with its Raft core held (hold_raft_file): its copy comes from its last snapshot
     * (which names the members, so its heartbeats reach the leader), it hears the leader's commit index in the acks but
     * applies nothing, and must not say it is caught up while its copy still has carol */
    snprintf(args, sizeof args, "cluster user add %s carol --password-file %s --secret-file %s", p[l], pw, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user carol: uid "))
        die("user add carol: %s", out);
    struct users_want carol = {{"root", "carol", NULL}, "alice"};
    await_view(x, p_users, &carol, "carol on the member to stop");
    stop(x, SIGTERM);
    snprintf(args, sizeof args, "cluster user drop %s carol --wait-ms 100 --secret-file %s", p[l], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "dropped user carol"))
        die("user drop carol with server %d down: %s", x, out);
    char holdraft[PATH_MAX + 96];
    server_dir(x, holdraft, sizeof holdraft);
    strcat(holdraft, "/state/holdraft");
    FILE *hr = fopen(holdraft, "w");
    if (!hr || fclose(hr) != 0)
        die("cannot make %s", holdraft);
    envs[x] = "snap_every=2,hold_raft_file=1";
    start(x);
    /* the leader runs and is heard (its acks carry its commit index); the copy, which applies nothing, still has carol
     * (mutants caughtupearly and floornoapplied) */
    t0 = now_ms();
    while (now_ms() - t0 < 2500) {
        struct view v;
        view(x, &v);
        int cu = v.st.users_caught_up, has = meta_user(&v.m, "carol") != NULL;
        view_free(&v);
        if (!has)
            die("server %d applied carol's drop with its Raft core held", x);
        if (cu)
            die("server %d says its users are caught up while its copy still has carol, dropped while it was down", x);
        usleep(100000);
    }
    if (unlink(holdraft) != 0)
        die("cannot remove %s", holdraft);
    await_view(x, p_users_caught_up, NULL, "users caught up after a leader was heard");
    struct users_want root_only = {{"root", NULL, NULL}, "carol"};
    await_view(x, p_users, &root_only, "the restarted copy without carol");
    printf("  restarted member caught up only after hearing the leader\n");

    /* SEC-01: state dirs are 0700 and snapshots, NODE, IDENT, Raft hard/segments are 0600 (even under umask 0022),
     * and overly permissive existing state dirs/files are tightened on reopen. */
    for (int i = 0; i < 3; i++)
        check_state_perms(i);
    stop(x, SIGTERM);
    {
        char sdir[PATH_MAX + 64], rdir[PATH_MAX + 80], fp[PATH_MAX + 384];
        server_dir(x, sdir, sizeof sdir);
        strcat(sdir, "/state");
        snprintf(rdir, sizeof rdir, "%s/raft", sdir);
        if (chmod(sdir, 0755) != 0 || chmod(rdir, 0755) != 0)
            die("chmod state/raft dir: %s", strerror(errno));
        snprintf(fp, sizeof fp, "%s/snapshot", sdir);
        if (chmod(fp, 0644) != 0)
            die("chmod snapshot: %s", strerror(errno));
        snprintf(fp, sizeof fp, "%s/hard", rdir);
        if (chmod(fp, 0644) != 0)
            die("chmod hard: %s", strerror(errno));
        DIR *dp = opendir(rdir);
        if (dp) {
            for (struct dirent *e; (e = readdir(dp));) {
                if (!strncmp(e->d_name, "log-", 4)) {
                    snprintf(fp, sizeof fp, "%s/%s", rdir, e->d_name);
                    (void)chmod(fp, 0644);
                }
            }
            closedir(dp);
        }
    }
    envs[x] = "snap_every=2";
    start(x);
    await_view(x, p_users_caught_up, NULL, "reopened member caught up after chmod tightening");
    check_state_perms(x);
    umask(old_umask);
    printf("  SEC-01: cluster state dir (0700) and Raft/snapshot files (0600) verified, including tighten-on-reopen\n");
}

/* writes `text` and a newline to base/NAME; its path in out */
static void put_file(const char *name, const char *text, char *out, size_t n)
{
    snprintf(out, n, "%s/%s", base, name);
    FILE *f = fopen(out, "w");
    if (!f || fprintf(f, "%s\n", text) < 0 || fclose(f) != 0)
        die("cannot write %s", out);
}

/* a login as user on server i: 0, or the error (the client does not retry AUTH_START) */
static int try_login(int i, const char *user, const char *pw)
{
    tsdbc *c = NULL;
    int rc = tsdbc_connect_auth("127.0.0.1", cports[i], user, pw, &c);
    if (rc == 0)
        tsdbc_close(c);
    return rc;
}

/* waits for a login that works (a change reaches a server's copy a heartbeat after it committed) */
static void await_login(int i, const char *user, const char *pw)
{
    uint64_t t0 = now_ms();
    int rc;
    while ((rc = try_login(i, user, pw)) != 0) {
        if (now_ms() - t0 > WAIT_MS)
            die("server %d: no login as %s: %s", i, user, ers(rc));
        usleep(100000);
    }
}

static tsdbc *login_on(int i, const char *user, const char *pw)
{
    tsdbc *c = NULL;
    int rc = tsdbc_connect_auth("127.0.0.1", cports[i], user, pw, &c);
    if (rc != 0)
        die("server %d: login as %s: %s", i, user, ers(rc));
    return c;
}

/* S2-1, login from the metadata group's copy on every server (server/auth.c "The cluster store"): a user added once
 * logs in on all three; a password changed over the client protocol through a follower: the old one is refused on
 * every server once the reply came (the change is answered after every member applied it, and a member's watch is
 * given the users before its heartbeat reports the index); a grant revoked and then the user dropped while a session
 * is open on the third server: its next request is DENIED, then AUTH; a user dropped while the third server was down
 * (SIGKILL), which restarts with its Raft core held (it hears the leader but applies nothing, its copy from its last
 * snapshot still has the user): every login there is UNAVAILABLE, never AUTH and never in; once it applies, the dropped
 * user is refused and root logs in. Mutants (TSDB_AUTH_MUTANT): authlocalusers (the server does not start: its root
 * has no USERS), adminlocal (the old password still works), loginbeforecatchup (the dropped user logs in). */
static void *unlink_later(void *path)
{
    usleep(1500000);
    if (unlink(path) != 0)
        fprintf(stderr, "cannot remove %s: %s\n", (const char *)path, strerror(errno));
    return NULL;
}

static void scen_login(void)
{
    scenario("login");
    strict_reads = 1; /* a replica moves reads to the leader (D5), as in production */
    const char *mut = getenv("TSDB_AUTH_MUTANT");
    static char mpenv[128], mpenv2[PATH_MAX + 256];
    char failpush[PATH_MAX + 96], holdraft[PATH_MAX + 96];
    snprintf(failpush, sizeof failpush, "%s/failpush", base);
    snprintf(mpenv, sizeof mpenv, "TSDB_AUTH_MUTANT=%s", mut ? mut : "");
    snprintf(mpenv2, sizeof mpenv2, "TSDB_AUTH_MUTANT=%s TSDB_AUTH_TEST=failpush_file=%s", mut ? mut : "", failpush);
    for (int i = 0; i < 3; i++) {
        auth_on[i] = 1;
        envs[i] = i == 2 ? "snap_every=2,hold_raft_file=1" : "snap_every=2";
        if (mut)
            penv[i] = mpenv;
        if (i == 2)
            penv[i] = mpenv2;
        start(i);
    }
    server_dir(2, holdraft, sizeof holdraft);
    strcat(holdraft, "/state/holdraft");
    char pw[PATH_MAX + 80], pw2[PATH_MAX + 80], args[PATH_MAX * 2 + 512], out[8192], p[3][META_ADDR_MAX];
    put_file("pw", "root-pw", pw, sizeof pw);
    put_file("pw2", "alice-pw", pw2, sizeof pw2);
    for (int i = 0; i < 3; i++)
        peer_of(i, p[i], sizeof p[i]);
    /* before INIT no server has heard a leader: the barrier, not "no such user" */
    int rc = try_login(0, "root", "root-pw");
    if (rc != TSDB_ERR_UNAVAILABLE)
        die("a login before the cluster exists: %s, not UNAVAILABLE", ers(rc));
    snprintf(args, sizeof args,
             "cluster init %s --secret-file %s --node-timeout-ms 1500 --heartbeat-ms 200 --voter-replace-s 600 "
             "--superuser root --password-file %s",
             p[0], secret_path, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user root: uid 1, index "))
        die("cluster init --superuser root: %s", out);
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    for (int i = 0; i < 3; i++)
        await_view(i, p_users_caught_up, NULL, "users caught up");
    /* `tsdb DIR user ...` on a cluster server's root: refused, naming `tsdb cluster user`, and no USERS made */
    {
        char root1[PATH_MAX + 80], uf[PATH_MAX + 96];
        server_dir(1, root1, sizeof root1);
        snprintf(args, sizeof args, "%s user add local --password-file %s", root1, pw2);
        if (cli_run(args, NULL, out, sizeof out) == 0 || !strstr(out, "is a cluster server's root") ||
            !strstr(out, "tsdb cluster user"))
            die("`tsdb DIR user add` on a cluster server's root was not refused: %s", out);
        snprintf(uf, sizeof uf, "%s/USERS", root1);
        if (access(uf, F_OK) == 0)
            die("`tsdb DIR user add` on a cluster server's root made %s", uf);
    }

    snprintf(args, sizeof args, "cluster user add %s alice --password-file %s --secret-file %s", p[0], pw2,
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user alice: uid "))
        die("user add alice: %s", out);
    for (int i = 0; i < 3; i++) {
        await_login(i, "root", "root-pw");
        if ((rc = try_login(i, "alice", "alice-pw")) != 0)
            die("server %d: alice, added before, does not log in: %s", i, ers(rc));
        if ((rc = try_login(i, "alice", "wrong")) != TSDB_ERR_AUTH)
            die("server %d: alice with a wrong password: %s, not AUTH", i, ers(rc));
    }
    printf("  one cluster user add: the user logs in on all three servers\n");

    /* passwd over the client protocol, through a follower */
    tsdbc *r1 = login_on(1, "root", "root-pw");
    if ((rc = tsdbc_user_password(r1, "alice", "alice-new", 0)) != 0)
        die("passwd of alice through server 1: %s", ers(rc));
    for (int i = 0; i < 3; i++) {
        if ((rc = try_login(i, "alice", "alice-pw")) != TSDB_ERR_AUTH)
            die("server %d: alice's old password after the passwd was answered: %s, not AUTH", i, ers(rc));
        if ((rc = try_login(i, "alice", "alice-new")) != 0)
            die("server %d: alice's new password: %s", i, ers(rc));
    }
    /* a create through a follower: the name taken is refused as by one server */
    if ((rc = tsdbc_user_create(r1, "alice", "x-pw", 0, 0)) != TSDB_ERR_INVALID)
        die("a create of a name taken: %s, not INVALID", ers(rc));
    printf("  passwd through a follower: the old password refused on every server after the reply\n");

    /* a session open on server 2: a grant reaches it, its revoke (through server 0) and alice's drop too */
    tsdbc *a2 = login_on(2, "alice", "alice-new");
    tsdb_sid sid = 0;
    if ((rc = tsdbc_series(a2, "plant.x", 0, &sid)) != TSDB_ERR_DENIED)
        die("alice's lookup without a grant: %s, not DENIED", ers(rc));
    if ((rc = tsdbc_grant(r1, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
        die("grant: %s", ers(rc));
    if ((rc = tsdbc_series(a2, "plant.x", 0, &sid)) != TSDB_ERR_NOTFOUND)
        die("alice's lookup after the grant was answered: %s, not NOTFOUND", ers(rc));
    tsdbc *r0 = login_on(0, "root", "root-pw");
    if ((rc = tsdbc_revoke(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
        die("revoke: %s", ers(rc));
    if ((rc = tsdbc_series(a2, "plant.x", 0, &sid)) != TSDB_ERR_DENIED)
        die("alice's open session on server 2 after the revoke was answered: %s, not DENIED", ers(rc));
    if ((rc = tsdbc_user_drop(r0, "alice")) != 0)
        die("drop alice: %s", ers(rc));
    if ((rc = tsdbc_series(a2, "plant.x", 0, &sid)) != TSDB_ERR_AUTH)
        die("alice's open session on server 2 after her drop was answered: %s, not AUTH", ers(rc));
    tsdbc_close(a2);
    for (int i = 0; i < 3; i++)
        if ((rc = try_login(i, "alice", "alice-new")) != TSDB_ERR_AUTH)
            die("server %d: alice logs in after her drop: %s", i, ers(rc));
    printf("  an open session on another server: the revoke is DENIED, the drop AUTH on its next request\n");

    /* a push of the users that server 2 fails to take (as out of memory) is pushed again until it is taken (mutant
     * pushnoretry: server 2 keeps the old password until the next change of the users) */
    if ((rc = tsdbc_user_create(r0, "bob", "bob-pw", 0, 0)) != 0)
        die("create bob: %s", ers(rc));
    await_login(2, "bob", "bob-pw");
    char fp2[PATH_MAX + 96];
    put_file("failpush", "", fp2, sizeof fp2);
    if ((rc = tsdbc_user_password(r0, "bob", "bob-new", 0)) != 0)
        die("passwd of bob: %s", ers(rc));
    usleep(500000);
    if ((rc = try_login(2, "bob", "bob-pw")) != 0)
        die("server 2, failing its pushes: bob's old password %s, not in (the test has no teeth)", ers(rc));
    if (unlink(failpush) != 0)
        die("cannot remove %s", failpush);
    uint64_t tp = now_ms();
    while ((rc = try_login(2, "bob", "bob-pw")) != TSDB_ERR_AUTH) {
        if (now_ms() - tp > 5000)
            die("server 2, its pushes taken again: bob's old password %s after 5 s, not AUTH", ers(rc));
        usleep(100000);
    }
    printf("  a push server 2 failed to take is pushed again: the old password refused there once it is taken\n");
    /* an admin op through server 2 while its copy is behind: the conditional put finds bob changed (STALE), waits for
     * the newer copy and checks again (mutant onetry: UNAVAILABLE); and one answered only once server 2's own copy
     * has it, so its next login there sees it (mutant nolocalwait: answered once the members reported the index,
     * server 2's copy still failing its pushes) */
    tsdbc *r2 = login_on(2, "root", "root-pw");
    if (tsdbc_set_retry(r2, 0) != 0)
        die("tsdbc_set_retry");
    put_file("failpush", "", fp2, sizeof fp2);
    if ((rc = tsdbc_user_password(r0, "bob", "bob-3", 0)) != 0)
        die("passwd of bob through server 0: %s", ers(rc));
    pthread_t ul;
    if (pthread_create(&ul, NULL, unlink_later, failpush) != 0)
        die("pthread_create");
    rc = tsdbc_user_password(r2, "bob", "bob-4", 0);
    pthread_join(ul, NULL);
    if (rc != 0)
        die("passwd through server 2, its copy behind: %s (STALE not checked again on the newer copy)", ers(rc));
    put_file("failpush", "", fp2, sizeof fp2);
    if (pthread_create(&ul, NULL, unlink_later, failpush) != 0)
        die("pthread_create");
    tp = now_ms();
    rc = tsdbc_user_password(r2, "bob", "bob-5", 0);
    uint64_t took = now_ms() - tp;
    int old = try_login(2, "bob", "bob-4");
    pthread_join(ul, NULL);
    if (rc != 0)
        die("passwd through server 2: %s", ers(rc));
    if (old != TSDB_ERR_AUTH)
        die("server 2 answered a passwd after %" PRIu64 " ms, before its own copy had it: the old password %s, "
            "not AUTH", took, ers(old));
    tsdbc_close(r2);
    printf("  through a server whose copy is behind: STALE checked again on the newer copy; the reply waits for "
           "its own copy (%" PRIu64 " ms)\n", took);

    /* the actor guard: a superuser demoted through server 0 while server 2 lags (its Raft core held) has a session
     * open on server 2, whose copy still says superuser: their user create there must not commit (mutant noguard) */
    if ((rc = tsdbc_user_create(r0, "mallory", "mallory-pw", 0, TSDB_USER_SUPERUSER)) != 0)
        die("create mallory: %s", ers(rc));
    await_login(2, "mallory", "mallory-pw");
    tsdbc *m2 = login_on(2, "mallory", "mallory-pw");
    if (tsdbc_set_retry(m2, 0) != 0)
        die("tsdbc_set_retry");
    FILE *hr = fopen(holdraft, "w");
    if (!hr || fclose(hr) != 0)
        die("cannot make %s", holdraft);
    if ((rc = tsdbc_user_alter(r0, "mallory", 0)) != 0) /* server 2 lags: answered after the wait */
        die("demote mallory with server 2 held: %s", ers(rc));
    uint64_t tm = now_ms();
    rc = tsdbc_user_create(m2, "mallory2", "m2-pw", 0, TSDB_USER_SUPERUSER);
    if (rc == 0 || try_login(0, "mallory2", "m2-pw") == 0)
        die("a superuser demoted through server 0 created a superuser through lagging server 2 (%s)", ers(rc));
    if (rc != TSDB_ERR_UNAVAILABLE)
        die("the demoted actor's create on lagging server 2: %s, not UNAVAILABLE", ers(rc));
    printf("  a demoted actor's admin op on a lagging server: UNAVAILABLE after %" PRIu64 " ms, nothing made\n",
           now_ms() - tm);
    if (unlink(holdraft) != 0)
        die("cannot remove %s", holdraft);
    tp = now_ms();
    while ((rc = tsdbc_user_create(m2, "mallory2", "m2-pw", 0, TSDB_USER_SUPERUSER)) != TSDB_ERR_DENIED) {
        if (rc == 0 || now_ms() - tp > WAIT_MS)
            die("the demoted actor's create once server 2 caught up: %s, not DENIED", ers(rc));
        usleep(100000);
    }
    tsdbc_close(m2);

    /* the restart barrier: carol dropped while server 2 is down; it comes back with its Raft core held */
    snprintf(args, sizeof args, "cluster user add %s carol --password-file %s --secret-file %s", p[0], pw2,
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user carol: uid "))
        die("user add carol: %s", out);
    snprintf(args, sizeof args, "cluster user add %s dave --password-file %s --secret-file %s", p[0], pw2,
             secret_path); /* a second entry: server 2's last snapshot (snap_every=2) holds carol */
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user dave: uid "))
        die("user add dave: %s", out);
    await_login(2, "carol", "alice-pw");
    stop(2, SIGKILL);
    if ((rc = tsdbc_user_drop(r0, "carol")) != 0) /* server 2 lags: answered after the wait, OK */
        die("drop carol with server 2 down: %s", ers(rc));
    hr = fopen(holdraft, "w");
    if (!hr || fclose(hr) != 0)
        die("cannot make %s", holdraft);
    start(2); /* its copy is pushed from its snapshot, carol in it (mutant barrierifempty: logins pass) */
    uint64_t t0 = now_ms();
    int tries = 0;
    while (now_ms() - t0 < 2500) {
        struct view v;
        view(2, &v);
        int has = meta_user(&v.m, "carol") != NULL;
        view_free(&v);
        if (!has)
            die("server 2 applied carol's drop with its Raft core held (the test has no teeth)");
        if ((rc = try_login(2, "carol", "alice-pw")) != TSDB_ERR_UNAVAILABLE)
            die("server 2, not caught up, its copy still holding carol: carol's login %s, not UNAVAILABLE", ers(rc));
        if ((rc = try_login(2, "root", "root-pw")) != TSDB_ERR_UNAVAILABLE)
            die("server 2, not caught up: root's login %s, not UNAVAILABLE", ers(rc));
        tries++;
        usleep(100000);
    }
    put_file("failpush", "", fp2, sizeof fp2); /* the pushes after it applies fail: the barrier waits for one taken */
    if (unlink(holdraft) != 0)
        die("cannot remove %s", holdraft);
    /* applied, its pushes failing: the barrier stays closed (mutant pushnoretry: open, its copy the snapshot's) */
    t0 = now_ms();
    int seen_drop = 0;
    while (now_ms() - t0 < WAIT_MS && !seen_drop) {
        struct view v;
        view(2, &v);
        seen_drop = meta_user(&v.m, "carol") == NULL;
        view_free(&v);
        usleep(100000);
    }
    if (!seen_drop)
        die("server 2 did not apply carol's drop once its Raft core was let go");
    usleep(1000000);
    if ((rc = try_login(2, "root", "root-pw")) != TSDB_ERR_UNAVAILABLE)
        die("server 2, applied but its users watch failing every push: root's login %s, not UNAVAILABLE", ers(rc));
    if (unlink(failpush) != 0)
        die("cannot remove %s", failpush);
    await_view(2, p_users_caught_up, NULL, "users caught up once it applies");
    if ((rc = try_login(2, "carol", "alice-pw")) != TSDB_ERR_AUTH)
        die("server 2, caught up: carol, dropped while it was down: %s, not AUTH", ers(rc));
    if ((rc = try_login(2, "root", "root-pw")) != 0 || (rc = try_login(2, "dave", "alice-pw")) != 0)
        die("server 2, caught up: root or dave: %s", ers(rc));
    printf("  restarted with its Raft core held: %d logins UNAVAILABLE; caught up, the dropped user is refused\n",
           tries);

    /* an outcome unknown (the leader stopped after it may have got the entry): no answer, the connection closes;
     * never UNAVAILABLE, which says "not applied" and has the client send it again (mutant retryunavail) */
    await_view(0, p_leader_self, NULL, "server 0 leading");
    if (tsdbc_set_retry(r1, 0) != 0 || tsdbc_set_timeout(r1, 60000) != 0)
        die("tsdbc_set_retry, tsdbc_set_timeout");
    pause_server(0, 1);
    tm = now_ms();
    rc = tsdbc_user_create(r1, "erin", "erin-pw", 0, 0);
    pause_server(0, 0);
    if (rc == 0 || rc == TSDB_ERR_UNAVAILABLE)
        die("a create whose leader stopped (outcome unknown): %s after %" PRIu64 " ms, not a closed connection",
            ers(rc), now_ms() - tm);
    tsdbc_user *who = NULL;
    if (tsdbc_whoami(r1, &who) == 0) {
        tsdbc_users_free(who, 1);
        die("the connection of an outcome unknown is still open");
    }
    printf("  an admin op of unknown outcome: no answer, the connection closed after %" PRIu64 " ms (%s)\n",
           now_ms() - tm, ers(rc));
    tsdbc_close(r0);
    tsdbc_close(r1);
}

/* A cluster of three for the users scenarios below, root the superuser, login on; server 2 gets `env2` (a test hook)
 * besides the mutants of TSDB_AUTH_MUTANT and TSDB_CLUSTER_MUTANT. Servers 1 and 2 are added only when `add`. */
static void users_cluster(const char *env2, int add)
{
    static char menv[3][PATH_MAX + 384];
    const char *am = getenv("TSDB_AUTH_MUTANT"), *cm = getenv("TSDB_CLUSTER_MUTANT");
    for (int i = 0; i < 3; i++) {
        auth_on[i] = 1;
        snprintf(menv[i], sizeof menv[i], "TSDB_AUTH_MUTANT=%s TSDB_CLUSTER_MUTANT=%s%s%s", am ? am : "",
                 cm ? cm : "", i == 2 && env2 ? " " : "", i == 2 && env2 ? env2 : "");
        penv[i] = menv[i];
        start(i);
    }
    char pw[PATH_MAX + 80], args[PATH_MAX * 2 + 512], out[8192], p0[META_ADDR_MAX];
    put_file("pw", "root-pw", pw, sizeof pw);
    peer_of(0, p0, sizeof p0);
    snprintf(args, sizeof args,
             "cluster init %s --secret-file %s --node-timeout-ms 1500 --heartbeat-ms 200 --voter-replace-s 600 "
             "--superuser root --password-file %s",
             p0, secret_path, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user root: uid 1, index "))
        die("cluster init --superuser root: %s", out);
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    if (!add)
        return;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    for (int i = 0; i < 3; i++) {
        await_view(i, p_users_caught_up, NULL, "users caught up");
        await_login(i, "root", "root-pw");
    }
}

/* a lookup of plant.x as user/pw on server i: NOTFOUND with the grant, DENIED without it; a failed login is its
 * result (plant_lookup_try) */
static int plant_lookup_try(int i, const char *user, const char *pw)
{
    tsdbc *c = NULL;
    int rc = tsdbc_connect_auth("127.0.0.1", cports[i], user, pw, &c);
    if (rc != 0)
        return rc;
    tsdb_sid sid = 0;
    rc = tsdbc_series(c, "plant.x", 0, &sid);
    tsdbc_close(c);
    return rc;
}
static int plant_lookup(int i, const char *user, const char *pw)
{
    tsdbc *c = login_on(i, user, pw);
    tsdb_sid sid = 0;
    int rc = tsdbc_series(c, "plant.x", 0, &sid);
    tsdbc_close(c);
    return rc;
}

struct stale_op {
    tsdbc *c;
    int what; /* 0 grant, 1 revoke, 2 drop, 3 passwd */
    const char *user;
    int rc;
    uint64_t end; /* now_ms() when it was answered */
};
static void *stale_op_run(void *a)
{
    struct stale_op *o = a;
    o->rc = o->what == 0   ? tsdbc_grant(o->c, o->user, TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)
            : o->what == 1 ? tsdbc_revoke(o->c, o->user, TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)
            : o->what == 2 ? tsdbc_user_drop(o->c, o->user)
                           : tsdbc_user_password(o->c, o->user, "new-pw", 0);
    o->end = now_ms();
    return NULL;
}

/* An admin op through server 2 while its copy of the users lags a change acknowledged through server 0 (its pushes
 * failing, TSDB_AUTH_TEST failpush_file, until 1.5 s later; then once SIGSTOPped): a check there finds nothing to
 * change or refuses, from a copy that does not have the change. That answer must not go out from the copy (A32): a
 * grant answered OK (already held) while the acknowledged revoke stands is an acknowledged grant that holds nowhere;
 * a revoke, drop or passwd refused NOTFOUND contradicts the acknowledged grant or add. server/auth.c admin_group: the
 * read barrier, then the check again. Mutants (TSDB_AUTH_MUTANT): nooplocal (no barrier), syncnowait (the barrier's
 * index not waited for in server 2's copy). */
static void scen_userstale(void)
{
    scenario("userstale");
    strict_reads = 1;
    char failpush[PATH_MAX + 96], fenv[PATH_MAX + 128], fp[PATH_MAX + 96];
    snprintf(failpush, sizeof failpush, "%s/failpush", base);
    snprintf(fenv, sizeof fenv, "TSDB_AUTH_TEST=failpush_file=%s", failpush);
    users_cluster(fenv, 1);
    tsdbc *r0 = login_on(0, "root", "root-pw"), *r2 = login_on(2, "root", "root-pw");
    if (tsdbc_set_retry(r2, 0) != 0)
        die("tsdbc_set_retry");
    int rc;
    if ((rc = tsdbc_user_create(r0, "alice", "alice-pw", 0, 0)) != 0 ||
        (rc = tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
        die("create alice, grant: %s", ers(rc));
    await_login(2, "alice", "alice-pw");
    /* what the barrier costs a plain no-op (every copy caught up): the mean of 20 grants already held */
    for (uint64_t t0 = now_ms(); plant_lookup(2, "alice", "alice-pw") != TSDB_ERR_NOTFOUND;)
        if (now_ms() - t0 > WAIT_MS)
            die("server 2 never saw alice's grant");
        else
            usleep(50000);
    uint64_t tn = now_ms();
    for (int k = 0; k < 20; k++)
        if ((rc = tsdbc_grant(r2, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
            die("a grant already held, through server 2: %s", ers(rc));
    printf("  a no-op grant through server 2, every copy caught up: %.1f ms (mean of 20)\n", (now_ms() - tn) / 20.0);
    static const char *names[] = {"grant", "revoke", "drop", "passwd"};
    for (int what = 0; what < 4; what++) {
        const char *user = what < 2 ? "alice" : what == 2 ? "bob" : "carol";
        if (what == 1 && (rc = tsdbc_revoke(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
            die("revoke through server 0: %s", ers(rc));
        if (what == 1) /* server 2 must have the revoke before it falls behind the grant */
            for (uint64_t t0 = now_ms(); plant_lookup(2, "alice", "alice-pw") != TSDB_ERR_DENIED;) {
                if (now_ms() - t0 > WAIT_MS)
                    die("server 2 never saw alice's revoke");
                usleep(50000);
            }
        put_file("failpush", "", fp, sizeof fp);
        /* the change server 2's copy does not get */
        rc = what == 0   ? tsdbc_revoke(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)
             : what == 1 ? tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)
                         : tsdbc_user_create(r0, user, "user-pw", 0, 0);
        if (rc != 0)
            die("the change through server 0 before the %s: %s", names[what], ers(rc));
        pthread_t ul;
        if (pthread_create(&ul, NULL, unlink_later, failpush) != 0)
            die("pthread_create");
        uint64_t t0 = now_ms();
        struct stale_op o = {r2, what, user, 0};
        stale_op_run(&o);
        uint64_t took = now_ms() - t0;
        pthread_join(ul, NULL);
        if (o.rc != 0)
            die("%s through server 2, its users behind an acknowledged change: %s after %" PRIu64 " ms, answered "
                "from its stale copy", names[what], ers(o.rc), took);
        /* and what it acknowledged holds in the group: server 0 says so */
        if (what == 0 && (rc = plant_lookup(0, "alice", "alice-pw")) != TSDB_ERR_NOTFOUND)
            die("grant through server 2 answered OK after %" PRIu64 " ms while the revoke stands: alice's lookup on "
                "server 0 %s, not NOTFOUND (an acknowledged grant that holds nowhere)", took, ers(rc));
        if (what == 1 && (rc = plant_lookup(0, "alice", "alice-pw")) != TSDB_ERR_DENIED)
            die("revoke through server 2: alice's lookup on server 0 %s, not DENIED", ers(rc));
        if (what >= 2 && (rc = try_login(0, user, what == 2 ? "user-pw" : "new-pw")) != (what == 2 ? TSDB_ERR_AUTH : 0))
            die("%s of %s through server 2: login on server 0 %s", names[what], user, ers(rc));
        printf("  %s through server 2, its users behind: confirmed against the group, %" PRIu64 " ms\n", names[what],
               took);
    }

    /* the same with server 2 paused (SIGSTOP) across the revoke, and the grant sent to it before it resumes */
    await_login(2, "carol", "new-pw");
    if ((rc = tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
        die("grant: %s", ers(rc));
    for (uint64_t t0 = now_ms(); plant_lookup(2, "alice", "alice-pw") != TSDB_ERR_NOTFOUND;) {
        if (now_ms() - t0 > WAIT_MS)
            die("server 2 never saw alice's grant");
        usleep(50000);
    }
    pause_server(2, 1);
    if ((rc = tsdbc_revoke(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
        die("revoke through server 0 with server 2 paused: %s", ers(rc));
    struct stale_op o = {r2, 0, "alice", 0};
    pthread_t t;
    if (pthread_create(&t, NULL, stale_op_run, &o) != 0)
        die("pthread_create");
    usleep(300000);
    pause_server(2, 0);
    pthread_join(t, NULL);
    /* OK (the grant made again) or UNAVAILABLE (the barrier did not pass in time: nothing changed, the client asks
     * again); anything else is a regression that the check below would not see */
    if (o.rc != 0 && o.rc != TSDB_ERR_UNAVAILABLE)
        die("grant through server 2 paused across a revoke: %s, neither OK nor UNAVAILABLE", ers(o.rc));
    if (o.rc == 0 && (rc = plant_lookup(0, "alice", "alice-pw")) != TSDB_ERR_NOTFOUND)
        die("grant through server 2 answered OK on its resume while the revoke stands: alice's lookup on server 0 "
            "%s, not NOTFOUND (an acknowledged grant that holds nowhere)", ers(rc));
    printf("  grant through server 2 paused across a revoke: %s, and it holds\n", ers(o.rc));

    /* A no-op's OK acknowledges a state, so it waits for the members as the change did (A32): server 1 paused across
     * a grant through server 0, then the same grant through server 2 (a no-op there) is answered only once server 1
     * has the grant, so that a client of server 1 sees it after the OK. Mutant: nomembers. */
    if ((rc = tsdbc_revoke(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0 && rc != TSDB_ERR_NOTFOUND)
        die("revoke: %s", ers(rc));
    for (uint64_t t0 = now_ms(); plant_lookup(1, "alice", "alice-pw") != TSDB_ERR_DENIED;) {
        if (now_ms() - t0 > WAIT_MS)
            die("server 1 never saw alice's revoke");
        usleep(50000);
    }
    pause_server(1, 1);
    if ((rc = tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
        die("grant through server 0 with server 1 paused: %s", ers(rc));
    for (uint64_t t0 = now_ms(); plant_lookup(2, "alice", "alice-pw") != TSDB_ERR_NOTFOUND;) {
        if (now_ms() - t0 > WAIT_MS)
            die("server 2 never saw alice's grant");
        usleep(50000);
    }
    struct stale_op d = {r2, 0, "alice", 0};
    uint64_t t0 = now_ms();
    if (pthread_create(&t, NULL, stale_op_run, &d) != 0)
        die("pthread_create");
    usleep(1500000);
    uint64_t resumed = now_ms();
    pause_server(1, 0);
    pthread_join(t, NULL);
    uint64_t done = d.end;
    if (d.rc != 0)
        die("the grant again through server 2 (a no-op there) with server 1 paused: %s", ers(d.rc));
    if (done < resumed)
        die("the grant again through server 2 answered OK after %" PRIu64 " ms, before server 1 (paused) had the "
            "grant: a no-op's OK did not wait for the members", done - t0);
    if ((rc = plant_lookup(1, "alice", "alice-pw")) != TSDB_ERR_NOTFOUND)
        die("the grant again through server 2 answered OK, then alice's lookup on server 1 %s, not NOTFOUND: a "
            "no-op's OK did not wait for the members", ers(rc));
    printf("  a no-op through server 2 with server 1 paused: OK after %" PRIu64 " ms, %" PRIu64 " ms after server 1 "
           "resumed\n", done - t0, done - resumed);

    /* SEC-09: TSDB_OP_USER_LIST runs a cluster read barrier (group_sync), so a lagging or partitioned node never
     * serves a stale user list after an acknowledged create/drop. */
    put_file("failpush", "", fp, sizeof fp);
    if ((rc = tsdbc_user_create(r0, "list_seen", "list-pw", 0, 0)) != 0)
        die("create list_seen through server 0: %s", ers(rc));
    {
        pthread_t ul_thr;
        if (pthread_create(&ul_thr, NULL, unlink_later, failpush) != 0)
            die("pthread_create");
        tsdbc_user *list = NULL;
        size_t nlist = 0;
        rc = tsdbc_user_list(r2, &list, &nlist);
        pthread_join(ul_thr, NULL);
        if (rc != 0)
            die("USER_LIST through lagging server 2: %s", ers(rc));
        int found = 0;
        for (size_t i = 0; i < nlist; i++)
            if (!strcmp(list[i].name, "list_seen"))
                found = 1;
        tsdbc_users_free(list, nlist);
        if (!found)
            die("USER_LIST through lagging server 2 missed list_seen: answered from its stale copy");
    }
    put_file("failpush", "", fp, sizeof fp);
    if ((rc = tsdbc_user_drop(r0, "list_seen")) != 0)
        die("drop list_seen through server 0: %s", ers(rc));
    {
        pthread_t ul_thr;
        if (pthread_create(&ul_thr, NULL, unlink_later, failpush) != 0)
            die("pthread_create");
        tsdbc_user *list = NULL;
        size_t nlist = 0;
        rc = tsdbc_user_list(r2, &list, &nlist);
        pthread_join(ul_thr, NULL);
        if (rc != 0)
            die("USER_LIST after drop through lagging server 2: %s", ers(rc));
        int found = 0;
        for (size_t i = 0; i < nlist; i++)
            if (!strcmp(list[i].name, "list_seen"))
                found = 1;
        tsdbc_users_free(list, nlist);
        if (found)
            die("USER_LIST through lagging server 2 still listed dropped list_seen: answered from its stale copy");
    }
    /* No quorum: server 2 cut off from the majority must refuse USER_LIST with UNAVAILABLE, never stale OK */
    pause_server(0, 1);
    pause_server(1, 1);
    {
        tsdbc_user *list = NULL;
        size_t nlist = 0;
        rc = tsdbc_user_list(r2, &list, &nlist);
        tsdbc_users_free(list, nlist);
        if (rc != TSDB_ERR_UNAVAILABLE)
            die("USER_LIST on server 2 with no quorum returned %s, not UNAVAILABLE: answered from its stale copy",
                ers(rc));
    }
    pause_server(0, 0);
    pause_server(1, 0);
    printf("  SEC-09: USER_LIST waits for read barrier on lagging follower and returns UNAVAILABLE without quorum\n");

    tsdbc_close(r0);
    tsdbc_close(r2);
}

struct promo_probe {
    int i;
    tsdbc *s;
    atomic_int stop;
    int refused, ended, logins;
    char why[160];
};
static void *promo_probe_run(void *a)
{
    struct promo_probe *p = a;
    while (!atomic_load(&p->stop)) {
        int rc = try_login(p->i, "root", "root-pw");
        p->logins++;
        if (rc != 0 && !p->refused++)
            snprintf(p->why, sizeof p->why, "login %s", ers(rc));
        tsdb_sid sid = 0;
        rc = tsdbc_series(p->s, "plant.x", 0, &sid);
        if (rc != TSDB_ERR_NOTFOUND && !p->ended++ && !p->why[0])
            snprintf(p->why, sizeof p->why, "the open session's lookup %s", ers(rc));
        usleep(2000);
    }
    return NULL;
}

/* A member that becomes a voter (a watcher made a learner, then a voter: core_boot rebuilds its metadata copy from
 * nothing or its snapshot, and the log replays) keeps answering logins from the users it had: during the rebuild no
 * login is refused there and an open session goes on (server/cluster.c users_push holds the watch while the copy is
 * below what it was given). Its STATUS shows the watcher's state meanwhile, never an empty image. Mutants
 * (TSDB_CLUSTER_MUTANT): pushrebuild (the empty copy is pushed), bootempty (STATUS shows the empty core's state). */
static void scen_userpromote(void)
{
    scenario("userpromote");
    strict_reads = 1;
    /* the leader's log compacted (an install is needed) and server 1's install held 2 s: its core starts from nothing
     * and stays empty that long, a window no login can miss */
    envs[0] = "snap_every=2,snap_retain=1,seg_bytes=200";
    envs[1] = "snap_every=2,snap_retain=1,seg_bytes=200,hold_install_ms=2000";
    users_cluster(NULL, 0);
    node_add(0, 1); /* two members: server 1 watches, no core */
    await_view(1, p_users_caught_up, NULL, "users caught up");
    await_login(1, "root", "root-pw");
    struct promo_probe p = {.i = 1, .s = login_on(1, "root", "root-pw")};
    if (tsdbc_set_retry(p.s, 0) != 0)
        die("tsdbc_set_retry");
    pthread_t t;
    if (pthread_create(&t, NULL, promo_probe_run, &p) != 0)
        die("pthread_create");
    node_add(0, 2); /* three: servers 1 and 2 become learners, then voters */
    unsigned want = 3;
    /* server 1's STATUS through the promotion shows the state it served as a watcher (marked stale) while its core
     * starts from nothing and its install is held, never an empty image (core_boot keeps that state as the copy; a
     * test reading a volume there found none: setchurn; mutant bootempty) */
    int held = 0, polls = 0;
    for (uint64_t t0 = now_ms();; polls++) {
        struct view v1, v0;
        view(1, &v1);
        int empty = !v1.m.initialised || v1.m.nmembers < 2;
        held += v1.st.mode == CLUSTER_MODE_CORE && v1.st.stale;
        unsigned mode = v1.st.mode, stale = v1.st.stale;
        uint64_t applied = v1.st.applied;
        view_free(&v1);
        if (empty)
            die("server 1 made a learner: its STATUS showed an empty image (mode %u, stale %u, applied %" PRIu64
                ", after %d polls)", mode, stale, applied, polls);
        view(0, &v0);
        int done = p_voters(&v0, &want);
        view_free(&v0);
        if (done)
            break;
        if (now_ms() - t0 > WAIT_MS)
            die("server 0: three voters did not happen within %d ms", WAIT_MS);
        usleep(20000);
    }
    if (!held)
        die("server 1 made a learner: none of %d STATUS answers fell in its held install", polls);
    await_view(1, p_users_caught_up, NULL, "users caught up");
    usleep(1000000);
    atomic_store(&p.stop, 1);
    pthread_join(t, NULL);
    tsdbc_close(p.s);
    if (p.refused || p.ended)
        die("server 1 made a voter: %d of %d logins refused, %d lookups of the open session failed (first: %s)",
            p.refused, p.logins, p.ended, p.why);
    if (log_has(1, "the cluster's users went back"))
        die("server 1 made a voter: its users went back (an older list pushed while its copy was rebuilt)");
    printf("  server 1 made a voter: %d logins and the open session's lookups all answered; %d of %d STATUS answers"
           " showed its watcher's state during the held install, none an empty image\n", p.logins, held, polls);
}

struct replay_probe {
    atomic_int stop;
    int n, wrong;
    char why[160];
};
static void *replay_probe_run(void *a)
{
    struct replay_probe *p = a;
    while (!atomic_load(&p->stop)) {
        int rc = plant_lookup_try(1, "alice", "alice-pw2");
        p->n++;
        if (rc != TSDB_ERR_DENIED && !p->wrong++)
            snprintf(p->why, sizeof p->why, "alice's lookup %s, not DENIED", ers(rc));
        usleep(1000);
    }
    return NULL;
}

/* A promoted member's copy rebuilt by replaying the log from the start (no snapshot: the first append is 256 entries,
 * applied before the leader sends more) passes through older lists of users, non-empty ones: alice granted before her
 * revoke, with her old password. None of them may reach the users watch (users_push holds it until the copy is back at
 * what it gave, A32): the revoke would be undone on that server for the window. auth.c logs a list that goes back;
 * a probe as alice looks too (the window is short: the log line is the deterministic check; push_every_apply on
 * server 1 offers the watch every list the replay passes, where heartbeats alone hit the window by chance). Mutants
 * (TSDB_CLUSTER_MUTANT): holdempty (held only while the copy has no users), pushrebuild. */
static void scen_userreplay(void)
{
    scenario("userreplay");
    strict_reads = 1;
    envs[1] = "push_every_apply=1"; /* every list the replay passes reaches the watch, not only one at a heartbeat */
    users_cluster(NULL, 0);
    tsdbc *r0 = login_on(0, "root", "root-pw");
    int rc;
    if ((rc = tsdbc_user_create(r0, "alice", "alice-pw", 0, 0)) != 0 ||
        (rc = tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0 ||
        (rc = tsdbc_user_create(r0, "churn", "churn-pw", 0, 0)) != 0)
        die("create alice, grant, create churn: %s", ers(rc));
    /* past the first append: the copy at entry 256 has alice granted */
    for (int k = 0; k < 150; k++)
        if ((rc = tsdbc_grant(r0, "churn", TSDB_SEL_PREFIX, "c.", TSDB_RIGHT_READ)) != 0 ||
            (rc = tsdbc_revoke(r0, "churn", TSDB_SEL_PREFIX, "c.", TSDB_RIGHT_READ)) != 0)
            die("churn %d: %s", k, ers(rc));
    if ((rc = tsdbc_revoke(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0 ||
        (rc = tsdbc_user_password(r0, "alice", "alice-pw2", 0)) != 0)
        die("revoke alice, passwd: %s", ers(rc));
    node_add(0, 1); /* server 1 watches: its copy comes whole from the stream */
    await_view(1, p_users_caught_up, NULL, "users caught up");
    await_login(1, "alice", "alice-pw2");
    if ((rc = plant_lookup(1, "alice", "alice-pw2")) != TSDB_ERR_DENIED)
        die("server 1 before its promotion: alice's lookup %s, not DENIED", ers(rc));
    struct replay_probe p = {0};
    pthread_t t;
    if (pthread_create(&t, NULL, replay_probe_run, &p) != 0)
        die("pthread_create");
    node_add(0, 2); /* servers 1 and 2 become voters: server 1's core replays from entry 1 */
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    await_view(1, p_users_caught_up, NULL, "users caught up");
    usleep(1000000);
    atomic_store(&p.stop, 1);
    pthread_join(t, NULL);
    tsdbc_close(r0);
    if (log_has(1, "the cluster's users went back"))
        die("server 1 made a voter: its users went back while its copy replayed (an older list pushed)");
    if (p.wrong)
        die("server 1 made a voter: %d of %d probes wrong (first: %s)", p.wrong, p.n, p.why);
    printf("  server 1 made a voter, its copy replayed from entry 1: the watch kept the newest users (%d probes)\n",
           p.n);
}

/* The read barrier answers only from a leader that holds its lease (A32): server 0, the leader, has its Raft core
 * held (hold_raft_file: neither ticked nor given a message; its admin ops and heartbeats go on), so servers 1 and 2
 * elect another and a revoke commits there. Server 0 still takes itself for the leader: a grant of what its copy
 * says alice holds (a no-op there) asks itself for the barrier, which must refuse (no lease): UNAVAILABLE, never an
 * OK while the revoke stands. Mutant (TSDB_CLUSTER_MUTANT): syncnolease. Not covered: the barrier's check that the
 * commit index is of the leader's term (a SYNC between an election and the new leader's first commit).
 * The revoke goes through the new leader at once: its own users' change must go to itself from the moment it leads.
 * It used to follow the address the 100 ms duty last stored, server 0's for up to 100 ms after the election; server 0,
 * held, appended the revoke and never committed it, and the revoke's connection closed after 20 s (2 of 7 runs).
 * ul_tick_stale on servers 1 and 2 keeps that duty from moving the address, so only the role change can: mutant
 * uladdrtick (the address moved by the duty alone) fails here every time. */
static void scen_userlease(void)
{
    scenario("userlease");
    strict_reads = 1;
    envs[0] = "hold_raft_file=1";
    envs[1] = envs[2] = "ul_tick_stale=1";
    users_cluster(NULL, 1);
    tsdbc *r0 = login_on(0, "root", "root-pw");
    if (tsdbc_set_retry(r0, 0) != 0)
        die("tsdbc_set_retry");
    int rc;
    if ((rc = tsdbc_user_create(r0, "alice", "alice-pw", 0, 0)) != 0 ||
        (rc = tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
        die("create alice, grant: %s", ers(rc));
    for (int i = 1; i < 3; i++)
        for (uint64_t t0 = now_ms(); plant_lookup(i, "alice", "alice-pw") != TSDB_ERR_NOTFOUND;) {
            if (now_ms() - t0 > WAIT_MS)
                die("server %d never saw alice's grant", i);
            usleep(50000);
        }
    char holdraft[PATH_MAX + 96];
    server_dir(0, holdraft, sizeof holdraft);
    strcat(holdraft, "/state/holdraft");
    FILE *hr = fopen(holdraft, "w");
    if (!hr || fclose(hr) != 0)
        die("cannot make %s", holdraft);
    int nl = 0;
    for (uint64_t t0 = now_ms(); !nl;) {
        for (int i = 1; i < 3 && !nl; i++) {
            struct view v;
            view(i, &v);
            if (p_leader_self(&v, NULL))
                nl = i;
            view_free(&v);
        }
        if (!nl && now_ms() - t0 > WAIT_MS)
            die("no new leader among servers 1 and 2 with server 0's Raft core held");
        if (!nl)
            usleep(100000);
    }
    tsdbc *rl = login_on(nl, "root", "root-pw"); /* retries UNAVAILABLE (30 s), as clients do */
    uint64_t tr = now_ms();
    if ((rc = tsdbc_revoke(rl, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ)) != 0)
        die("revoke through server %d, the new leader: %s after %" PRIu64 " ms (sent to server 0, the leader it "
            "replaced?)", nl, ers(rc), now_ms() - tr);
    tsdbc_close(rl);
    if ((rc = plant_lookup(0, "alice", "alice-pw")) != TSDB_ERR_NOTFOUND)
        die("server 0, its Raft core held, has alice's revoke: %s (the scenario needs it behind)", ers(rc));
    uint64_t t0 = now_ms();
    int g = tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ);
    uint64_t took = now_ms() - t0;
    if (g == 0 && (rc = plant_lookup(nl, "alice", "alice-pw")) != TSDB_ERR_NOTFOUND)
        die("grant through server 0 (cut off, its lease gone) answered OK after %" PRIu64 " ms while the revoke "
            "stands: alice's lookup on server %d %s, not NOTFOUND (a barrier from a leader without its lease)", took,
            nl, ers(rc));
    if (g != TSDB_ERR_UNAVAILABLE)
        die("grant through server 0 (cut off, its lease gone): %s after %" PRIu64 " ms, not UNAVAILABLE", ers(g), took);
    if (unlink(holdraft) != 0)
        die("cannot remove %s", holdraft);
    for (uint64_t t1 = now_ms(); plant_lookup(0, "alice", "alice-pw") != TSDB_ERR_DENIED;) {
        if (now_ms() - t1 > WAIT_MS)
            die("server 0 never caught up with alice's revoke");
        usleep(50000);
    }
    tsdbc_close(r0);
    printf("  grant through a leader cut off from its group: UNAVAILABLE after %" PRIu64 " ms\n", took);
}

/* `tsdb cluster user import PEER DIR...` (tools/cluster-user-cli.c): the USERS of two stopped servers, the same (a
 * user with 5,000 grants among them), go in as they are: the verifiers copied, so the passwords log in on a cluster
 * server, the grants count and are in force; a rerun skips what the group holds the same. Two that differ (a grant
 * more in one, a user missing from the other) import nothing and name each such user, until --from-node says whose
 * copy wins. Mutant importmerge (differing users imported silently) must fail here. */
static void scen_userimport(void)
{
    scenario("userimport");
    strict_reads = 1; /* a replica moves reads to the leader (D5), as in production */
    auth_on[0] = 1;
    start(0);
    init_fast(0);
    char pw[PATH_MAX + 80], args[PATH_MAX * 4 + 512], out[16384], p0[META_ADDR_MAX];
    char a[PATH_MAX + 80], b[PATH_MAX + 80], c[PATH_MAX + 80], d[PATH_MAX + 80], f1[PATH_MAX + 96], f2[PATH_MAX + 96];
    peer_of(0, p0, sizeof p0);
    put_file("pw", "imported-pw", pw, sizeof pw);
    snprintf(a, sizeof a, "%s/old-a", base);
    snprintf(b, sizeof b, "%s/old-b", base);
    snprintf(c, sizeof c, "%s/old-c", base);
    snprintf(d, sizeof d, "%s/old-d", base);
    const char *dirs[4] = {a, b, c, d};
    for (int k = 0; k < 4; k++)
        if (mkdir(dirs[k], 0755) != 0)
            die("mkdir %s: %s", dirs[k], strerror(errno));
    snprintf(args, sizeof args, "%s user add ops --superuser --password-file %s", a, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("`tsdb %s`: %s", args, out);
    snprintf(args, sizeof args, "%s user add big --password-file %s", a, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("`tsdb %s`: %s", args, out);
    users us;
    int rc = users_open(&us, a, true);
    if (rc != 0)
        die("users_open %s: %s", a, ers(rc));
    for (int g = 0; g < 5000; g++) {
        char sel[64];
        int sl = snprintf(sel, sizeof sel, "plant.s%04d", g);
        if ((rc = users_grant(&us, 0, "big", TSDB_SEL_NAME, sel, (size_t)sl, TSDB_RIGHT_READ)) != 0)
            die("grant %d: %s", g, ers(rc));
    }
    users_close(&us);
    snprintf(f1, sizeof f1, "%s/USERS", a);
    snprintf(f2, sizeof f2, "%s/USERS", b);
    snprintf(args, sizeof args, "cp %s %s", f1, f2);
    if (system(args) != 0)
        die("%s", args);

    snprintf(args, sizeof args, "cluster user import %s %s %s --secret-file %s", p0, a, b, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "imported 2 users (0 in the group already)"))
        die("import of two equal USERS: %s", out);
    snprintf(args, sizeof args, "cluster user list %s big --secret-file %s", p0, secret_path);
    static char big[1 << 20];
    if (cli_run(args, NULL, big, sizeof big) != 0)
        die("user list big: %.400s", big);
    int ng = 0;
    for (const char *q = big; (q = strstr(q, "\ngrant name:plant.s")); q++)
        ng++;
    if (ng != 5000)
        die("big has %d grants in the group, not 5000: %.400s", ng, big);
    await_login(0, "big", "imported-pw");
    tsdbc *cb = login_on(0, "big", "imported-pw");
    tsdb_sid sid;
    if ((rc = tsdbc_series(cb, "plant.s4999", 0, &sid)) != TSDB_ERR_NOTFOUND)
        die("big's lookup of a name granted: %s, not NOTFOUND", ers(rc));
    if ((rc = tsdbc_series(cb, "plant.t0", 0, &sid)) != TSDB_ERR_DENIED)
        die("big's lookup of a name not granted: %s, not DENIED", ers(rc));
    tsdbc_close(cb);
    await_login(0, "ops", "imported-pw");
    snprintf(args, sizeof args, "cluster user import %s %s %s --secret-file %s", p0, a, b, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "imported 0 users (2 in the group already)"))
        die("the import again: %s", out);
    printf("  two equal USERS imported (5,000 grants; the passwords log in); a rerun skips them\n");

    /* c: dora and eve; d: dora with a grant more, no eve */
    snprintf(args, sizeof args, "%s user add dora --password-file %s", c, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("`tsdb %s`: %s", args, out);
    snprintf(f1, sizeof f1, "%s/USERS", c);
    snprintf(f2, sizeof f2, "%s/USERS", d);
    snprintf(args, sizeof args, "cp %s %s", f1, f2);
    if (system(args) != 0)
        die("%s", args);
    snprintf(args, sizeof args, "%s user add eve --password-file %s", c, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("`tsdb %s`: %s", args, out);
    snprintf(args, sizeof args, "%s user grant dora read prefix:line3.", d);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("`tsdb %s`: %s", args, out);
    /* frank, the same on both but for his password (A33: which one is the newest is not known; mutant
     * noverifiercmp) */
    char pwd[PATH_MAX + 80];
    put_file("pw-frank-d", "frank-d-pw", pwd, sizeof pwd);
    for (int k = 0; k < 2; k++) {
        snprintf(args, sizeof args, "%s user add frank --password-file %s", k ? d : c, k ? pwd : pw);
        if (cli_run(args, NULL, out, sizeof out) != 0)
            die("`tsdb %s`: %s", args, out);
    }
    snprintf(args, sizeof args, "cluster user import %s %s %s --secret-file %s", p0, c, d, secret_path);
    if (cli_run(args, NULL, out, sizeof out) == 0 || !strstr(out, "user dora differs between the servers") ||
        !strstr(out, "user eve differs between the servers") || !strstr(out, "user frank differs between the servers") ||
        !strstr(out, "3 users differ") || !strstr(out, "nothing imported"))
        die("import of two USERS that differ: %s", out);
    for (int k = 0; k < 2; k++) {
        snprintf(args, sizeof args, "cluster user list %s %s --secret-file %s", p0, k ? "eve" : "dora", secret_path);
        if (cli_run(args, NULL, out, sizeof out) == 0)
            die("%s is in the group after an import that differed: %s", k ? "eve" : "dora", out);
    }
    snprintf(args, sizeof args, "cluster user import %s %s %s --from-node %s --secret-file %s", p0, c, d, d,
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "imported 2 users"))
        die("import with --from-node: %s", out);
    await_login(0, "frank", "frank-d-pw");
    if ((rc = try_login(0, "frank", "imported-pw")) != TSDB_ERR_AUTH)
        die("frank's password of the losing copy: %s, not AUTH", ers(rc));
    snprintf(args, sizeof args, "cluster user list %s dora --secret-file %s", p0, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "grant prefix:line3."))
        die("dora as old-d had her: %s", out);
    snprintf(args, sizeof args, "cluster user list %s eve --secret-file %s", p0, secret_path);
    if (cli_run(args, NULL, out, sizeof out) == 0)
        die("eve, absent from the winning copy, was imported: %s", out);
    printf("  two USERS that differ: nothing imported, each user named; --from-node takes that copy\n");
}

/* 3 servers, a volume of 3 replicas: every server makes v1 with the right META and REPL and opens it once the
 * metadata group recorded its open generation; the leader (TSDB_CLUSTER_WRITES=1) takes writes, the replicas
 * refuse them (UNAVAILABLE, FENCED, naming the volume); a restart keeps the rid and raises the generation, which is
 * registered; a copy of the directory from before is refused; with no quorum a restarted server does not open its
 * volume (the generation cannot be recorded). Mutants: TSDB_CVOL_MUTANT=samerid and noopengen must fail here. */
static void scen_volumes(void)
{
    scenario("volumes");
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_CLUSTER_WRITES=1";
        envs[i] = "hold_opens_file=1";
        start(i);
    }
    init_cluster(0, 600); /* restarts take seconds: no voter is replaced meanwhile */
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc = vol_add(1, "big", 4, &num); /* through a follower: the request is followed to the leader */
    if (rc != CLUSTER_ERR_FEW)
        die("a volume of 4 replicas on 3 servers: %s, not CLUSTER_ERR_FEW", cluster_strerror(rc));
    if ((rc = vol_add(1, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    if ((rc = vol_add(0, "plant", 3, &num)) == 0)
        die("a second volume named plant was added (number %" PRIu32 ")", num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    for (int i = 0; i < 3; i++)
        await_log_count(i, "(plant): open as the", 1, 10000);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v) || v.nrep != 3 || v.number != 1)
        die("the record of plant is missing or has %u replicas", v.nrep);
    char hex[33];
    for (int k = 0; k < 16; k++)
        snprintf(hex + 2 * k, 3, "%02x", v.uuid[k]);
    uint64_t rids[3];
    for (int i = 0; i < 3; i++) {
        char dir[PATH_MAX + 80], path[PATH_MAX + 160], meta[2048], need[96];
        server_dir(i, dir, sizeof dir);
        snprintf(path, sizeof path, "%s/v1/META", dir);
        slurp(path, meta, sizeof meta);
        snprintf(need, sizeof need, "volume_uuid=%s\n", hex);
        if (!strstr(meta, "\nvolume=1\n") || !strstr(meta, need) || !strstr(meta, "\ncluster=") ||
            !strstr(meta, "requires=cluster,replica\n"))
            die("server %d: %s lacks volume=1, %s, cluster= or requires=cluster,replica:\n%s", i, path, need, meta);
        uint64_t rid, gen;
        repl_of(i, 1, &rid, &gen);
        const struct meta_replica *r = rep_of(&v, i);
        if (!r || rid != r->rid || gen != 1)
            die("server %d: REPL rid %016" PRIx64 " gen %" PRIu64 ", the record rid %016" PRIx64, i, rid, gen,
                r ? r->rid : 0);
        rids[i] = rid;
    }
    if (rids[0] == rids[1] || rids[1] == rids[2] || rids[0] == rids[2])
        die("two replicas share a rid");
    char out[8192];
    char args[PATH_MAX * 3 + 256];
    snprintf(args, sizeof args, "cluster status 127.0.0.1:%d --secret-file %s", pports[2], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "\nvolume 1 name plant ") ||
        !strstr(out, "replica volume 1 node 1 ") || !strstr(out, "replica volume 1 node 3 "))
        die("`tsdb %s` does not list the volume and its replicas:\n%s", args, out);
    printf("  volume 1 on 3 servers: META, REPL and the open generations recorded\n");

    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = write_read(c, "plant", 1000);
    if (TSDB_SID_VOLUME(id) != 1 || rows_of(c, id) != 3)
        die("the leader: id %" PRIx64 " or the rows read back are wrong", (uint64_t)id);
    /* P-03: many-series batch on the leader succeeds (cvol_refuse_ids deduplicates volume 1) */
    {
        tsdb_sid mids[64];
        int64_t mts[64];
        float mval[64];
        for (int k = 0; k < 64; k++) {
            mids[k] = id;
            mts[k] = 10000 + k;
            mval[k] = (float)(10 + k);
        }
        if ((rc = tsdbc_insert(c, mids, mts, mval, 64)) != 0 || rows_of(c, id) != 67)
            die("many-series insert on leader: %s (rows %" PRIu64 ")", ers(rc), rows_of(c, id));
    }
    tsdb_sid x;
    if ((rc = tsdbc_series_at(c, "pump7.flow", "nosuch", &x)) != TSDB_ERR_NOTFOUND)
        die("a series in an unknown volume: %s, not NOTFOUND", ers(rc));
    if ((rc = tsdbc_series(c, "pump7.flow2", 1, &x)) == 0)
        die("a series was made in the root of a cluster node (id %" PRIx64 ")", (uint64_t)x);
    tsdbc_close(c);
    for (int i = 0; i < 3; i++) {
        if (i == L)
            continue;
        c = client(i);
        rc = tsdbc_series_at(c, "pump7.flow", "plant", &x);
        expect_moved(c, rc, 1, v.leader, L, "series made on a replica");
        int64_t ts = 5000;
        float val = 5;
        rc = tsdbc_insert_series(c, id, &ts, &val, 1);
        expect_moved(c, rc, 1, v.leader, L, "insert on a replica");
        /* the packed frames name a series per row: an id the replica's dictionary does not know yet (the leader made
         * it, nothing replicates) is still MOVED to the leader by its volume, never INVALID (route_ids) */
        tsdb_sid ids2[2] = {id, id};
        int64_t ts2[2] = {5000, 5001};
        float val2[2] = {5, 6};
        rc = tsdbc_insert(c, ids2, ts2, val2, 2);
        expect_moved(c, rc, 1, v.leader, L, "a packed insert on a replica");
        tsdb_values tv = {TSDB_FLOAT32, val2, NULL};
        rc = tsdbc_insert_values(c, ids2, ts2, &tv, 2);
        expect_moved(c, rc, 1, v.leader, L, "a packed typed insert on a replica");
        /* P-03: interleaved batch (skipped/malformed ids mixed with cluster vol-1 id, and 64-row multi-series batch)
         * still catches volume 1 after deduplication -> MOVED; spanning vol 0 (local) + vol 1 (remote) -> INVALID. */
        tsdb_sid mix_ids[8] = {0, 1, id, 0, id, 1, id, id};
        int64_t mix_ts[8] = {5010, 5011, 5012, 5013, 5014, 5015, 5016, 5017};
        float mix_v[8] = {1, 2, 3, 4, 5, 6, 7, 8};
        rc = tsdbc_insert(c, mix_ids, mix_ts, mix_v, 8);
        expect_moved(c, rc, 1, v.leader, L, "interleaved skipped+vol1 insert on a replica");
        tsdb_values mix_tv = {TSDB_FLOAT32, mix_v, NULL};
        rc = tsdbc_insert_values(c, mix_ids, mix_ts, &mix_tv, 8);
        expect_moved(c, rc, 1, v.leader, L, "interleaved skipped+vol1 typed insert on a replica");
        tsdb_sid span_ids[4] = {TSDB_SID(0, 0), id, TSDB_SID(0, 0), id};
        rc = tsdbc_insert(c, span_ids, mix_ts, mix_v, 4);
        if (rc != TSDB_ERR_INVALID)
            die("spanning vol 0 + vol 1 insert on a replica: %s, want INVALID", ers(rc));
        tsdbc_close(c);
    }
    printf("  the leader takes writes and reads them back, the replicas move them to it (MOVED)\n");

    /* restarts: the same rid, the generation raised, saved and recorded; the leader's rows are still there */
    char dir1[PATH_MAX + 80], v1[PATH_MAX + 120], old1[PATH_MAX + 120], cmd[PATH_MAX * 4];
    server_dir(1, dir1, sizeof dir1);
    snprintf(v1, sizeof v1, "%s/v1", dir1);
    snprintf(old1, sizeof old1, "%s/v1.gen1", dir1);
    for (int i = 0; i < 3; i++) {
        stop(i, SIGTERM);
        if (i == 1) { /* the directory as it was at generation 1, for later */
            snprintf(cmd, sizeof cmd, "cp -a %s %s", v1, old1);
            if (system(cmd) != 0)
                die("%s failed", cmd);
        }
        start(i);
        await_open_gen(i == 0 ? 1 : 0, "plant", i, 2, rids[i]);
        await_log_count(i, "(plant): open as the", 2, 30000);
        uint64_t rid, gen;
        repl_of(i, 1, &rid, &gen);
        if (rid != rids[i] || gen != 2)
            die("server %d after a restart: REPL rid %016" PRIx64 " gen %" PRIu64 " (rid %016" PRIx64 ", gen 2)", i, rid,
                gen, rids[i]);
    }
    c = client(L);
    if (rows_of(c, id) != 67)
        die("the leader lost its rows across a restart");
    tsdbc_close(c);
    printf("  every restart keeps the rid, raises the generation to 2 and the group records it\n");

    /* an older copy of the directory (generation 1 < the recorded 2) is refused, naming both */
    uint64_t inc1;
    {
        struct view w;
        view(0, &w);
        const struct meta_member *mb = meta_member(&w.m, ids[1]);
        if (!mb)
            die("server 1 is not a member");
        inc1 = mb->incarnation;
        view_free(&w);
    }
    stop(1, SIGTERM);
    snprintf(cmd, sizeof cmd, "rm -rf %s && mv %s %s", v1, old1, v1);
    if (system(cmd) != 0)
        die("%s failed", cmd);
    start(1);
    await_log_count(1, "is at open generation 1, below the 2 the metadata group recorded", 1, 40000);
    c = client(1);
    expect_held(c, tsdbc_series_at(c, "pump7.flow", "plant", &x), 1, "plant", 1, "an old copy");
    tsdbc_close(c);
    if (log_count(1, "(plant): open as the") != 2)
        die("server 1 opened its old copy of v1");
    printf("  a copy from generation 1 is refused, naming both generations\n");
    /* its log line comes from the server's own copy, before it rejoined: the volume added next needs all three up */
    struct state_want up1 = {ids[1], META_UP, inc1 + 1};
    await_view_ms(0, p_member_state, &up1, "server 1 up again after the refused copy", 40000);

    /* a volume added while the leader proposes no REPLICA_OPEN (hold_opens_file) stays closed everywhere: no server
     * serves before the group recorded its generation (mutant noopengen) */
    for (int i = 0; i < 3; i++) {
        char hold[PATH_MAX + 96];
        server_dir(i, hold, sizeof hold);
        strcat(hold, "/state/holdopens");
        FILE *h = fopen(hold, "w");
        if (!h || fclose(h) != 0)
            die("%s: %s", hold, strerror(errno));
    }
    if ((rc = vol_add(0, "tank", 3, &num)) != 0 || num != 2)
        die("volume add tank: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_log_count(i, "(tank): open generation 1, waiting", 1, 20000);
    usleep(2500000);
    for (int i = 0; i < 3; i++) {
        if (log_count(i, "(tank): open as the"))
            die("server %d opened tank before the group recorded its open generation", i);
        c = client(i);
        expect_held(c, tsdbc_series_at(c, "pump7.flow", "tank", &x), i, "tank", 2, "tank held");
        tsdbc_close(c);
    }
    for (int i = 0; i < 3; i++) {
        char hold[PATH_MAX + 96];
        server_dir(i, hold, sizeof hold);
        strcat(hold, "/state/holdopens");
        unlink(hold);
    }
    for (int i = 0; i < 3; i++)
        await_log_count(i, "(tank): open as the", 1, 20000);
    printf("  a volume whose open generations are not recorded stays closed (RECOVERING), then opens\n");

    /* a crash while making v3 leaves v3.tmp holding any of its files (META, REPL, FNO and their tmps): the next make
     * removes it whole and makes v3 (one that left FNO behind refused the volume for good) */
    char v3[PATH_MAX + 120], old3[PATH_MAX + 120];
    snprintf(v3, sizeof v3, "%s/v3", dir1);
    snprintf(old3, sizeof old3, "%s/v3.gen1", dir1);
    {
        char t3[PATH_MAX + 128];
        snprintf(t3, sizeof t3, "%s.tmp", v3);
        if (mkdir(t3, 0755) != 0)
            die("%s: %s", t3, strerror(errno));
        static const char *left[] = {"META", "REPL", "REPL.tmp", "FNO", "FNO.tmp"};
        for (size_t k = 0; k < sizeof left / sizeof left[0]; k++) {
            char f[PATH_MAX + 160];
            snprintf(f, sizeof f, "%s/%s", t3, left[k]);
            FILE *h = fopen(f, "w");
            if (!h || fputs("left by a crash\n", h) < 0 || fclose(h) != 0)
                die("%s: %s", f, strerror(errno));
        }
    }
    if ((rc = vol_add(0, "pipe", 3, &num)) != 0 || num != 3)
        die("volume add pipe: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_log_count(i, "(pipe): open as the", 1, 20000);
    printf("  a v3.tmp left by a crash while making v3 is removed whole, and v3 is made and opened\n");

    /* an older copy of v3 opened on a metadata copy one REPLICA_OPEN behind (stale_first_watch; the push waits for the
     * copy to hold the run's incarnation, so this stands for a bug there): it saves generation 2, which the group holds
     * from the open the copy predates. Neither that record (another nonce) nor, after a restart on a current copy,
     * the REPL that open saved (generation 2 under its own nonce) lets it serve. Mutants anynonce, replnonce. */
    stop(1, SIGTERM);
    snprintf(cmd, sizeof cmd, "cp -a %s %s", v3, old3);
    if (system(cmd) != 0)
        die("%s failed", cmd);
    start(1);
    await_open_gen(0, "pipe", 1, 2, 0);
    await_log_count(1, "(pipe): open as the", 2, 30000);
    stop(1, SIGTERM);
    snprintf(cmd, sizeof cmd, "rm -rf %s && mv %s %s", v3, old3, v3);
    if (system(cmd) != 0)
        die("%s failed", cmd);
    envs[1] = "hold_opens_file=1,stale_first_watch=1";
    start(1);
    envs[1] = "hold_opens_file=1";
    await_log_count(1, "(pipe): open generation 2, waiting", 2, 40000);
    if ((rc = vol_add(0, "spare", 1, &num)) != 0) /* a commit: every copy moves and is pushed again */
        die("volume add spare: %s", cluster_strerror(rc));
    await_log_count(1, "(pipe): the metadata group recorded open generation 2 of another open", 1, 30000);
    c = client(1);
    expect_held(c, tsdbc_series_at(c, "pump7.flow", "pipe", &x), 1, "pipe", 3, "a stale open");
    tsdbc_close(c);
    if (log_count(1, "(pipe): open as the") != 2)
        die("server 1 opened its older copy of v3 under the generation of the open it predates");
    stop(1, SIGTERM);
    start(1);
    await_log_count(1, "saved open generation 2 in another open than the one the metadata group recorded", 1, 40000);
    usleep(1500000);
    if (log_count(1, "(pipe): open as the") != 2)
        die("server 1 opened its older copy of v3 after a restart");
    printf("  an older copy that saved the recorded generation in a stale open is refused, also after a restart\n");

    /* without a quorum a restarted server answers RECOVERING, never NOTFOUND, and opens nothing */
    int s = L == 2 ? 1 : 2;
    for (int i = 0; i < 3; i++)
        stop(i, SIGTERM);
    start(s);
    usleep(3000000);
    c = client(s);
    /* its copy is stale (no core caught up): plant may not be declared yet (RECOVERING), or declared with its leader
     * on server L, which the copy may still show UP (MOVED there: the entry node decides from the copy alone) or not
     * (PROMOTING); never NOTFOUND, never served here */
    rc = tsdbc_series_at(c, "pump7.flow", "plant", &x);
    if (rc == TSDB_ERR_MOVED) {
        expect_moved(c, rc, 1, v.leader, L, "no quorum");
    } else {
        tsdb_unavail e;
        unsigned n = 0;
        if (rc != TSDB_ERR_UNAVAILABLE || tsdbc_unavailable(c, &e, 1, &n) != 0 || n != 1 ||
            (e.reason != TSDB_WHY_RECOVERING && e.reason != TSDB_WHY_PROMOTING))
            die("no quorum: %s (reason %u), not MOVED to the old leader or UNAVAILABLE (RECOVERING, PROMOTING)",
                ers(rc), n ? e.reason : 0);
    }
    tsdbc_close(c);
    if (log_count(s, "(plant): open as the") != 2)
        die("server %d opened plant before the metadata group recorded its generation", s);
    printf("  with no quorum a restarted server keeps its volume closed\n");
    stop(s, SIGTERM);

    /* outside a cluster the directory is refused (requires=cluster), and so is a feed */
    char vdir[PATH_MAX + 128];
    server_dir(0, vdir, sizeof vdir);
    strcat(vdir, "/v1");
    snprintf(args, sizeof args, "%s query pump7.flow 0 10000", vdir);
    if (cli_run(args, NULL, out, sizeof out) == 0 || !strstr(out, "cluster"))
        die("`tsdb %s` opened a cluster volume outside the cluster:\n%s", args, out);
    snprintf(args, sizeof args, "%s feed enable", vdir);
    if (cli_run(args, NULL, out, sizeof out) == 0 || !strstr(out, "cluster"))
        die("`tsdb %s` was not refused:\n%s", args, out);
    printf("  the CLI refuses a cluster volume (requires=cluster) and a feed on it\n");
}

/* A node refuses to start with --wal-sync-ms other than 0, with series in its root or with VOLUMES (DECISION D2:
 * the root holds USERS only); login stays per node (USERS in the root). */
/* R8 D11, E14, E26, E27 (server/chunksrv*.c): two tsdbd with --chunk-dir. A store whose META names another node or
 * another cluster refuses the start with a line naming both; a store another tsdbd holds (its flock) and one named
 * twice refuse it too. Then puts through the real peer links (the hook TSDB_CHUNKSRV_TEST in chunksrv_cluster.c):
 * a chunk put from A to B reads back whole, B's fence raised to 5 refuses a put at 3 and a delete at 4; B killed with
 * SIGKILL and restarted still holds the chunk and the fence (a put at 4 is FENCED). The cell checks, power loss around
 * PUT_OK and the unsure stores are test_chunksrv's (with its mutants). */
static void chunk_store_make(const char *path, const uint8_t uuid[16], uint32_t node)
{
    char hex[33], args[PATH_MAX + 128], out[4096];
    for (int k = 0; k < 16; k++)
        snprintf(hex + 2 * k, 3, "%02x", uuid[k]);
    snprintf(args, sizeof args, "chunk-store init %s --cluster %s --node %" PRIu32, path, hex, node);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("`tsdb %s`: %s", args, out);
}

static void scen_chunksrv(void)
{
    scenario("chunksrv");
    for (int i = 0; i < 3; i++) /* three voters: a restarted one publishes its new peer address */
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    struct view v;
    view(0, &v);
    uint8_t uuid[16], other[16];
    memcpy(uuid, v.m.uuid, 16);
    const struct meta_member *mb = meta_member(&v.m, ids[1]);
    struct state_want up = {ids[1], META_UP, mb ? mb->incarnation + 1 : 1};
    view_free(&v);
    memcpy(other, uuid, 16);
    other[5] ^= 0x20;
    stop(1, SIGTERM); /* one server down at a time: the other two keep the group's quorum */
    char s0[PATH_MAX], s1[PATH_MAX], sf[PATH_MAX], so[PATH_MAX], stage[PATH_MAX], hex[33], need[256];
    snprintf(s0, sizeof s0, "%s/cs0", base);
    snprintf(s1, sizeof s1, "%s/cs1", base);
    snprintf(sf, sizeof sf, "%s/csf", base);
    snprintf(so, sizeof so, "%s/cso", base);
    snprintf(stage, sizeof stage, "%s/stage", base);
    if (mkdir(stage, 0755) != 0)
        die("mkdir %s: %s", stage, strerror(errno));
    chunk_store_make(s0, uuid, ids[0]);
    chunk_store_make(s1, uuid, ids[1]);
    chunk_store_make(sf, uuid, ids[1] + 40); /* another member's disk */
    chunk_store_make(so, other, ids[1]);     /* this node id in another cluster */
    for (int k = 0; k < 16; k++)
        snprintf(hex + 2 * k, 3, "%02x", uuid[k]);

    char xa[PATH_MAX * 2 + 64];
    snprintf(xa, sizeof xa, "--chunk-dir %s", sf);
    xargs[1] = xa;
    int rc = start_try(1);
    snprintf(need, sizeof need, "belongs to cluster %s node %" PRIu32 ", but this is cluster %s node %" PRIu32, hex,
             ids[1] + 40, hex, ids[1]);
    if (rc != TH_EXITED || !WIFEXITED(th_status) || WEXITSTATUS(th_status) != 1 || !log_has(1, need))
        die("a store of another node did not refuse the start naming both (%d, 0x%x)", rc, th_status);
    snprintf(xa, sizeof xa, "--chunk-dir %s", so);
    rc = start_try(1);
    char ohex[33];
    for (int k = 0; k < 16; k++)
        snprintf(ohex + 2 * k, 3, "%02x", other[k]);
    snprintf(need, sizeof need, "belongs to cluster %s node %" PRIu32 ", but this is cluster %s node %" PRIu32, ohex,
             ids[1], hex, ids[1]);
    if (rc != TH_EXITED || !WIFEXITED(th_status) || WEXITSTATUS(th_status) != 1 || !log_has(1, need))
        die("a store of another cluster did not refuse the start naming both (%d, 0x%x)", rc, th_status);
    snprintf(xa, sizeof xa, "--chunk-dir %s --chunk-dir %s", s1, s1);
    rc = start_try(1);
    if (rc != TH_EXITED || !WIFEXITED(th_status) || WEXITSTATUS(th_status) == 0)
        die("a store named twice did not refuse the start (%d, 0x%x)", rc, th_status);
    printf("  a store of another node, of another cluster and one named twice refuse the start\n");

    snprintf(xa, sizeof xa, "--chunk-dir %s", s1);
    start(1);
    await_view(0, p_member_state, &up, "server 1 back with a new incarnation");
    stop(0, SIGTERM);
    char xb[PATH_MAX + 64], pe[PATH_MAX + 96];
    snprintf(xb, sizeof xb, "--chunk-dir %s", s1); /* server 0 names server 1's store: its flock refuses */
    xargs[0] = xb;
    rc = start_try(0);
    if (rc != TH_EXITED || !WIFEXITED(th_status) || WEXITSTATUS(th_status) == 0 || !log_has(0, "is open elsewhere"))
        die("a store another tsdbd holds did not refuse the start (%d, 0x%x)", rc, th_status);
    printf("  a store another tsdbd holds refuses the start\n");

    snprintf(xb, sizeof xb, "--chunk-dir %s", s0);
    snprintf(pe, sizeof pe, "TSDB_CHUNKSRV_TEST=put:%" PRIu32 ":%s", ids[1], stage);
    penv[0] = pe;
    start(0);
    await_log_count(0, "chunksrv test: ", 1, 90000);
    if (!log_has(0, "chunksrv test: pass put"))
        die("the put through two tsdbd failed (n0.log: chunksrv test: FAIL ...)");
    printf("  a chunk put from A to B reads back whole; B's fence at 5 refuses a put at 3 and a delete at 4\n");

    struct view vk;
    view(0, &vk);
    const struct meta_member *mk = meta_member(&vk.m, ids[1]);
    up.min_incarnation = mk ? mk->incarnation + 1 : 1;
    view_free(&vk);
    stop(1, SIGKILL);
    start(1);
    await_view(0, p_member_state, &up, "the killed member back with a new incarnation");
    stop(0, SIGTERM);
    snprintf(pe, sizeof pe, "TSDB_CHUNKSRV_TEST=check:%" PRIu32 ":%s", ids[1], stage);
    start(0);
    await_log_count(0, "chunksrv test: ", 2, 90000);
    if (!log_has(0, "chunksrv test: pass check"))
        die("after B's SIGKILL the chunk or the fence was gone (n0.log: chunksrv test: FAIL ...)");
    printf("  B killed and restarted: the chunk reads back whole, a put at 4 is still FENCED\n");
}

/* R4 (the plan's D9): the metadata snapshot is version 6 (R8; R4 made it 5). A directory of another version (a
 * cluster a preview build made before) is refused at start with a line naming both versions, never read as damage
 * or replayed, and before NODE is written again: here a one-server cluster's `snapshot`, then (that one put back)
 * its `copy`, is rewritten as version 4 (checksum and all) while it is down. Before that, INIT's four settings of R4 (cluster.c's
 * settings words 19-22) are read back from STATUS. */
uint32_t iso_crc32c(uint32_t crc, const void *buf, size_t len); /* src/raft/compat.c, as meta.c declares it */
static size_t snapv_read(const char *path, uint8_t *img, size_t cap)
{
    FILE *f = fopen(path, "rb");
    if (!f)
        die("cannot read %s: %s", path, strerror(errno));
    size_t n = fread(img, 1, cap, f);
    fclose(f);
    if (n == cap)
        die("%s is larger than %zu bytes", path, cap);
    return n;
}
static void snapv_write(const char *path, const uint8_t *img, size_t n)
{
    FILE *f = fopen(path, "wb");
    if (!f || fwrite(img, 1, n, f) != n || fclose(f) != 0)
        die("rewriting %s", path);
}
/* `path` rewritten as version `oldv`: the start must fail naming it and both versions, and leave NODE as it was */
static void snapv_refused_ver(const char *dir, const char *name, uint32_t oldv)
{
    static uint8_t img[1 << 20], keep[1 << 20], node0[4096], node1[4096];
    char path[PATH_MAX + 300], nodef[PATH_MAX + 300];
    snprintf(path, sizeof path, "%s/%s", dir, name);
    snprintf(nodef, sizeof nodef, "%s/NODE", dir);
    size_t n = snapv_read(path, img, sizeof img);
    memcpy(keep, img, n);
    if (n < 28 || meta_snapshot_version(img, n) != META_SNAP_VERSION)
        die("%s is no image of version %d (%zu bytes)", path, META_SNAP_VERSION, n);
    uint32_t crc;
    memcpy(img + 4, &oldv, 4);
    crc = iso_crc32c(0, img, n - 4);
    memcpy(img + n - 4, &crc, 4);
    snapv_write(path, img, n);
    size_t nn0 = snapv_read(nodef, node0, sizeof node0);
    int rc = start_try(0);
    char want[PATH_MAX + 400];
    snprintf(want, sizeof want, "%s holds metadata of snapshot version %" PRIu32 " and this build reads version %d",
             path, oldv, META_SNAP_VERSION);
    if (rc != TH_EXITED || !WIFEXITED(th_status) || WEXITSTATUS(th_status) == 0 || !log_has(0, want))
        die("a %s of snapshot version %" PRIu32 " was not refused naming both versions (%d, 0x%x)", name, oldv, rc,
            th_status);
    size_t nn1 = snapv_read(nodef, node1, sizeof node1);
    if (nn1 != nn0 || memcmp(node0, node1, nn0) != 0)
        die("the start refused for %s of version %" PRIu32 " wrote NODE again", name, oldv);
    snapv_write(path, keep, n);
    printf("  a %s of snapshot version %" PRIu32
           " is refused at start, NODE untouched: \"... %s holds metadata of snapshot "
           "version %" PRIu32 " and this build reads version %d\"\n",
           name, oldv, name, oldv, META_SNAP_VERSION);
}
static void snapv_refused(const char *dir, const char *name)
{
    snapv_refused_ver(dir, name, 4);
    snapv_refused_ver(dir, name, META_SNAP_VERSION - 1);
}
static void scen_snapversion(void)
{
    scenario("snapversion");
#ifdef TSDB_TEST_HOOKS
    envs[0] = "live_objs_test=1";
#endif
    start(0);
    init_r4_set = 1;
    init_fast(0);
    init_r4_set = 0;
    struct view v;
    view(0, &v);
    const struct meta_settings *st = &v.m.set;
    if (st->rebuild_mb_s != 300 || st->rebuild_max != 3 || st->transfer_wait_ms != 2500 || st->leader_balance_s != 60)
        die("INIT's settings came back as rebuild_mb_s %u, rebuild_max %u, transfer_wait_ms %u, leader_balance_s %u "
            "(sent 300, 3, 2500, 60)", st->rebuild_mb_s, st->rebuild_max, st->transfer_wait_ms, st->leader_balance_s);
    view_free(&v);
    printf("  INIT's rebuild_mb_s, rebuild_max, transfer_wait_ms and leader_balance_s read back from STATUS\n");

    /* R10 (D26, D28): verify HBS_LIVE_OBJS -> heard_sections -> cl_heard_live_objs -> STATUS round-trip
     * (uses TSDB_TEST_HOOKS live_objs_test=1) */
#ifdef TSDB_TEST_HOOKS
    {
        int got = 0;
        uint64_t t0 = now_ms();
        while (!got && now_ms() - t0 < 5000) {
            view(0, &v);
            if (v.st.nheard >= 1 && v.st.heard[0].nlive_objs == 2) {
                const struct cluster_live_objs_report *a = &v.st.heard[0].live_objs[0];
                const struct cluster_live_objs_report *b = &v.st.heard[0].live_objs[1];
                if (a->volume != 1 || a->epoch != 1 || a->stripe_version != 9 || a->overflow != 0 ||
                    a->nsv != META_LIVE_SV_MAX)
                    die("STATUS live_objs[0] mismatch: vol %u ep %" PRIu64 " sv %" PRIu64 " ov %u nsv %u",
                        a->volume, a->epoch, a->stripe_version, a->overflow, a->nsv);
                for (uint32_t k = 0; k < META_LIVE_SV_MAX; k++)
                    if (a->sv[k].stripe_version != k + 1 || a->sv[k].count != (uint64_t)(k + 1) * 10)
                        die("STATUS live_objs[0].sv[%u] mismatch: (%" PRIu64 ", %" PRIu64 ")", k,
                            a->sv[k].stripe_version, a->sv[k].count);
                if (b->volume != 2 || b->epoch != 2 || b->stripe_version != 3 || b->overflow != 1 || b->nsv != 0)
                    die("STATUS live_objs[1] mismatch: vol %u ep %" PRIu64 " sv %" PRIu64 " ov %u nsv %u",
                        b->volume, b->epoch, b->stripe_version, b->overflow, b->nsv);
                got = 1;
            }
            view_free(&v);
            if (!got)
                usleep(50000);
        }
        if (!got)
            die("STATUS never returned HBS_LIVE_OBJS entries published via live_objs_test=1");
        if (log_has(0, "live_objs_test self-check"))
            die("server 0 failed cl_heard_live_objs self-check");
        printf("  HBS_LIVE_OBJS (full 8-entry vector + overflow) round-tripped through heartbeat and STATUS\n");
    }
#else
    printf("  HBS_LIVE_OBJS round-trip skipped (built without TSDB_TEST_HOOKS)\n");
#endif

    char dir[PATH_MAX + 200], path[PATH_MAX + 300];
    snprintf(dir, sizeof dir, "%s/n0/state", base);
    snprintf(path, sizeof path, "%s/copy", dir);
    uint64_t t0 = now_ms();
    while (access(path, F_OK) != 0 && now_ms() - t0 < 10000)
        usleep(50000);
    envs[0] = NULL;
    stop(0, SIGTERM);
    snapv_refused(dir, "snapshot");
    snapv_refused(dir, "copy");
}

static void scen_volrefuse(void)
{
    scenario("volrefuse");
    char out[8192], args[PATH_MAX * 3 + 256], dir[PATH_MAX + 80], in[PATH_MAX + 80];
    xargs[0] = "--wal-sync-ms 10";
    int rc = start_try(0);
    if (rc != TH_EXITED || !WIFEXITED(th_status) || WEXITSTATUS(th_status) != 2 ||
        !log_has(0, "--cluster needs --wal-sync-ms 0"))
        die("--cluster with --wal-sync-ms 10 was not refused with status 2 (%d, 0x%x)", rc, th_status);

    server_dir(1, dir, sizeof dir);
    snprintf(args, sizeof args, "%s insert pump7.flow", dir);
    if (cli_run(args, "echo 1000,1", out, sizeof out) != 0)
        die("`tsdb %s`: %s", args, out);
    rc = start_try(1);
    if (rc != TH_EXITED || !WIFEXITED(th_status) || WEXITSTATUS(th_status) != 1 ||
        !log_has(1, "the root holds 1 series"))
        die("a node with a series in its root started (%d, 0x%x)", rc, th_status);

    server_dir(2, dir, sizeof dir);
    start(2); /* a node that ran once (its root exists), then a volume added to it locally while it was down */
    stop(2, SIGTERM);
    snprintf(in, sizeof in, "%s/n2-local", base);
    if (mkdir(in, 0755) != 0)
        die("mkdir %s: %s", in, strerror(errno));
    snprintf(args, sizeof args, "%s volume add %s", dir, in);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("`tsdb %s`: %s", args, out);
    rc = start_try(2);
    if (rc != TH_EXITED || !WIFEXITED(th_status) || WEXITSTATUS(th_status) != 1 || !log_has(2, "VOLUMES lists volume 1"))
        die("a node with a local volume started (%d, 0x%x)", rc, th_status);
    printf("  --wal-sync-ms 10, a series in the root and a local volume are refused at start, naming them\n");

    /* S2-1: a root that holds USERS is refused (with and without login: the file would look valid), naming the
     * import; without it the server starts, marks its root, and `tsdb DIR user` refuses there naming `tsdb cluster
     * user`; a superuser of the metadata group writes to a volume of 1 replica */
    server_dir(3, dir, sizeof dir);
    snprintf(in, sizeof in, "%s/pw", base);
    FILE *f = fopen(in, "w");
    if (!f || fputs("s3cret-pw\n", f) < 0 || fclose(f) != 0)
        die("%s: %s", in, strerror(errno));
    snprintf(args, sizeof args, "%s user add admin --superuser --password-file %s", dir, in);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("`tsdb %s`: %s", args, out);
    for (int on = 0; on < 2; on++) {
        auth_on[3] = on;
        rc = start_try(3);
        if (rc != TH_EXITED || !WIFEXITED(th_status) || WEXITSTATUS(th_status) == 0 ||
            !log_has(3, "never from its root: move the file aside (out of "))
            die("a cluster node with USERS in its root started (login %s; %d, 0x%x)", on ? "on" : "off", rc,
                th_status);
    }
    char upath[PATH_MAX + 96];
    snprintf(upath, sizeof upath, "%s/USERS", dir);
    if (unlink(upath) != 0)
        die("unlink %s: %s", upath, strerror(errno));
    penv[3] = "TSDB_CLUSTER_WRITES=1";
    start(3);
    snprintf(args, sizeof args, "%s user add admin --superuser --password-file %s", dir, in);
    if (cli_run(args, NULL, out, sizeof out) == 0 || !strstr(out, "use 'tsdb cluster user add PEER"))
        die("`tsdb DIR user add` on a cluster node's root: %s", out);
    if (access(upath, F_OK) == 0)
        die("`tsdb DIR user add` made %s on a cluster node's root", upath);
    init_fast(3);
    char p3[META_ADDR_MAX];
    peer_of(3, p3, sizeof p3);
    snprintf(args, sizeof args, "cluster user add %s admin --superuser --password-file %s --secret-file %s", p3, in,
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "put user admin: uid "))
        die("cluster user add admin: %s", out);
    printf("  a root USERS is refused naming the import; `tsdb DIR user` refuses on a cluster root\n");
    uint32_t num;
    if ((rc = vol_add(3, "solo", 1, &num)) != 0 || num != 1)
        die("volume add solo: %s", cluster_strerror(rc));
    await_open_gen(3, "solo", 3, 1, 0);
    await_log_count(3, "(solo): open as the writer", 1, 10000);
    tsdbc *c;
    if ((rc = tsdbc_connect_auth("127.0.0.1", cports[3], "admin", "wrong", &c)) != TSDB_ERR_AUTH)
        die("a wrong password: %s, not AUTH", ers(rc));
    if ((rc = tsdbc_connect_auth("127.0.0.1", cports[3], "admin", "s3cret-pw", &c)) != 0)
        die("login: %s", ers(rc));
    tsdb_sid id = write_read(c, "solo", 1000);
    if (rows_of(c, id) != 3)
        die("the rows written with a login are not read back");
    tsdbc_close(c);
    printf("  login with a user of the metadata group; a volume of 1 replica takes writes\n");
}


/* links: the hand-off of data links in the cluster thread's acceptor (server/cluster.c handshake(), conn_handoff), in
 * this process (cluster_start here, no tsdbd): a data link's HELLO is refused while no peerlink is set, and for a
 * server that is no member of the cluster, one with another identity, another or no cluster uuid; a member's is handed
 * to the peerlink, comes up on both sides and carries a frame; the metadata links go on working beside them. */
static _Atomic int lk_ups[2], lk_frames[2];
static void lk_on_link(void *arg, struct plink *l, int up)
{
    (void)l;
    if (up)
        atomic_fetch_add(&lk_ups[(intptr_t)arg], 1);
}
static void lk_on_frame(void *arg, struct plink *l, uint8_t type, const uint8_t *p, size_t n)
{
    (void)l, (void)type, (void)p, (void)n;
    atomic_fetch_add(&lk_frames[(intptr_t)arg], 1);
}

static struct peerlink *lk_peerlink(int which, uint32_t id, const uint8_t uuid[16], const uint8_t ident[16])
{
    struct pl_cfg c;
    memset(&c, 0, sizeof c);
    c.self.id = id;
    memcpy(c.self.uuid, uuid, 16);
    memcpy(c.self.ident, ident, 16);
    c.secret = secret;
    c.secret_len = secret_len;
    c.arg = (void *)(intptr_t)which;
    c.on_link = lk_on_link;
    c.on_frame = lk_on_frame;
    c.ping_ms = 100;
    c.dead_ms = 1000;
    c.backoff_min_ms = 20;
    c.backoff_max_ms = 100;
    struct peerlink *pl = peerlink_new(&c);
    if (!pl)
        die("peerlink_new");
    return pl;
}

/* a dialer as (id, uuid, ident) to `addr`: does a link of `kind` come up within ms? */
static int lk_dials(const char *addr, uint32_t id, const uint8_t uuid[16], const uint8_t ident[16], int kind, int ms)
{
    struct peerlink *b = lk_peerlink(1, id, uuid, ident);
    int before = atomic_load(&lk_ups[1]);
    struct plink *l = peerlink_dial(b, 0, addr, kind);
    if (!l)
        die("peerlink_dial");
    int up = 0;
    for (int t = 0; t < ms && !up; t += 20) {
        up = atomic_load(&lk_ups[1]) > before && plink_up(l);
        if (!up)
            usleep(20 * 1000);
    }
    if (up) { /* a frame from the dialer reaches the server's peerlink */
        int f0 = atomic_load(&lk_frames[0]);
        if (plink_send(l, 1, "hello", 5, 1000) != PL_OK)
            up = 0;
        for (int t = 0; t < 3000 && atomic_load(&lk_frames[0]) == f0; t += 10)
            usleep(10 * 1000);
        if (atomic_load(&lk_frames[0]) == f0)
            die("links: a frame over the data link did not arrive");
    }
    peerlink_free(b);
    return up;
}

/* every node holds a FWD and a FWDQ link to every other member, with no replicated volume anywhere (s2d), and
 * dials a member again after it restarts */
static void fwd_await(int i, uint32_t peer, const char *kind, int conn)
{
    char needle[128];
    snprintf(needle, sizeof needle, "fwd link to node %" PRIu32 " (%s) up, connection %d", peer, kind, conn);
    uint64_t t0 = now_ms();
    while (!log_has(i, needle) && now_ms() - t0 < WAIT_MS)
        usleep(50000);
    if (!log_has(i, needle))
        die("server %d: no \"%s\"", i, needle);
}

static int status_key(int i, const char *key, char *val, size_t vn);

/* STATUS's links.KIND.CHECK of server i: at least `least` connections at `check`, none at the other levels */
static void links_await(int i, const char *kind, const char *check, int least)
{
    static const char *const lv[] = {"none", "header", "full"};
    char key[64], val[32];
    int n[3] = {-1, -1, -1};
    for (uint64_t t0 = now_ms();; usleep(50000)) {
        for (int c = 0; c < 3; c++) {
            snprintf(key, sizeof key, "links.%s.%s", kind, lv[c]);
            n[c] = status_key(i, key, val, sizeof val) ? atoi(val) : -1;
        }
        int ok = 1;
        for (int c = 0; c < 3; c++)
            ok &= strcmp(lv[c], check) == 0 ? n[c] >= least : n[c] == 0;
        if (ok)
            break;
        if (now_ms() - t0 > WAIT_MS)
            die("server %d: STATUS says links.%s none %d header %d full %d, want %d or more at %s", i, kind, n[0], n[1],
                n[2], least, check);
    }
}

static void scen_fwdlinks(void)
{
    scenario("fwdlinks");
    strict_reads = 1; /* a replica moves reads to the leader (D5), as in production */
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            if (i != j) {
                fwd_await(i, ids[j], "fwd", 1);
                fwd_await(i, ids[j], "fwdq", 1);
            }
    stop(2, SIGTERM);
    start(2);
    for (int i = 0; i < 2; i++) {
        fwd_await(i, ids[2], "fwd", 2);
        fwd_await(i, ids[2], "fwdq", 2);
    }
    for (int i = 0; i < 3; i++) { /* STATUS says each link's frame check: none, the default */
        links_await(i, "fwd", "none", 2);
        links_await(i, "fwdq", "none", 2);
    }
    printf("  fwdlinks: 3 servers, each with FWD and FWDQ links to both others; both redial a restarted one; STATUS "
           "says their check (none)\n");
}

static void scen_links(void)
{
    scenario("links");
    char sd[PATH_MAX + 128], padv[64], err[1024];
    snprintf(sd, sizeof sd, "%s/state", base);
    int pfd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
    struct sockaddr_in sa = {.sin_family = AF_INET};
    sa.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    socklen_t sl = sizeof sa;
    int one = 1;
    setsockopt(pfd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);
    if (pfd < 0 || bind(pfd, (struct sockaddr *)&sa, sizeof sa) != 0 || listen(pfd, 64) != 0 ||
        getsockname(pfd, (struct sockaddr *)&sa, &sl) != 0)
        die("links: listener: %s", strerror(errno));
    snprintf(padv, sizeof padv, "127.0.0.1:%d", ntohs(sa.sin_port));
    struct cluster_cfg cc = {.state_dir = sd, .peer_fd = pfd, .advertise = "127.0.0.1:1", .peer_advertise = padv,
                             .rack = "", .power_feed = "", .bmc = "", .secret = secret, .secret_len = secret_len};
    if (cluster_start(&cc) != 0)
        die("links: cluster_start");
    struct meta_settings s;
    meta_settings_default(&s);
    uint8_t req[4 * (META_SETTINGS_WORDS + 1)], *rep = NULL;
    size_t rl = cluster_settings_encode(&s, META_MODE_REPLICATED, req), len;
    int rc;
    if (cluster_admin(padv, secret, secret_len, CLUSTER_OP_INIT, req, rl, 10000, &rc, &rep, &len, err, sizeof err) != 0 ||
        rc != 0)
        die("links: init: %s", err);
    free(rep);
    struct cluster_self me;
    if (cluster_self(&me) != 0 || me.id != 1)
        die("links: cluster_self after init: have_node %d id %u", me.have_node, (unsigned)me.id);
    /* a second member: a real tsdbd, added through this node (the leader) */
    start(1);
    char np[META_ADDR_MAX];
    peer_of(1, np, sizeof np);
    uint8_t areq[META_ADDR_MAX + 2];
    size_t an = node_add_req(1, areq);
    if (cluster_admin(padv, secret, secret_len, CLUSTER_OP_NODE_ADD, areq, an, 20000, &rc, &rep, &len, err, sizeof err) != 0 ||
        rc != 0)
        die("links: node add: %s", err);
    free(rep);
    uint32_t mid = 0;
    uint8_t mident[16] = {0};
    for (uint64_t t0 = now_ms(); !mid && now_ms() - t0 < WAIT_MS; usleep(100000)) {
        struct view v;
        view(1, &v);
        const struct meta_member *m = v.st.self ? meta_member(&v.m, v.st.self) : NULL;
        static const uint8_t unknown[16]; /* zero: not known; a random ident may begin with a zero byte */
        if (m && memcmp(m->ident, unknown, 16) != 0) {
            mid = m->id;
            memcpy(mident, m->ident, 16);
        }
        view_free(&v);
    }
    if (!mid)
        die("links: the second member did not show up");
    /* a peer of the previous cluster version at tsdbd's peer port: refused, with a line that names both versions */
    {
        uint8_t h[128];
        size_t o = 4;
        h[o++] = 1; /* HELLO: magic, version, id, uuid, ident, nonce, no address, kind, check types */
        uint32_t magic = PL_CL_MAGIC, nid = 9;
        memcpy(h + o, &magic, 4), o += 4;
        h[o++] = PL_CL_VERSION - 1;
        memcpy(h + o, &nid, 4), o += 4;
        memcpy(h + o, me.uuid, 16), o += 16;
        memset(h + o, 0x77, 16 + 32), o += 16 + 32;
        h[o++] = 0, h[o++] = 0, h[o++] = PL_KIND_LOG, h[o++] = 2;
        uint32_t hl = (uint32_t)(o - 4);
        memcpy(h, &hl, 4);
        int rfd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
        struct sockaddr_in ra = {.sin_family = AF_INET, .sin_port = htons((uint16_t)pports[1])};
        ra.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        if (rfd < 0 || connect(rfd, (struct sockaddr *)&ra, sizeof ra) != 0 || write(rfd, h, o) != (ssize_t)o)
            die("links: raw HELLO: %s", strerror(errno));
        char want[96];
        snprintf(want, sizeof want, "refused a peer of cluster version %d (node 9,", PL_CL_VERSION - 1);
        int seen = 0;
        for (uint64_t t0 = now_ms(); !(seen = log_has(1, want)) && now_ms() - t0 < WAIT_MS;)
            usleep(50000);
        close(rfd);
        char both[64];
        snprintf(both, sizeof both, "this server speaks %d", PL_CL_VERSION);
        if (!seen || !log_has(1, both))
            die("links: no line naming cluster versions %d and %d for a peer of the old version", PL_CL_VERSION - 1,
                PL_CL_VERSION);
    }
    uint8_t zero[16] = {0}, other[16], bad_ident[16], rnd[16];
    memcpy(other, me.uuid, 16);
    other[0] ^= 1;
    memcpy(bad_ident, mident, 16);
    bad_ident[3] ^= 1;
    for (int i = 0; i < 16; i++)
        rnd[i] = (uint8_t)(0x40 + i);

    /* no peerlink set: refused (every other check passes) */
    if (lk_dials(padv, mid, me.uuid, mident, PL_KIND_LOG, 1500))
        die("links: a data link came up while no peerlink was set");
    struct peerlink *srv = lk_peerlink(0, me.id, me.uuid, me.ident);
    /* the acceptor's table (cluster_set_peerlink_kind): a kind goes only to the peerlink registered for it (mutant
     * kindall); the metadata kind and kinds past the table cannot be registered */
    if (cluster_set_peerlink_kind(PL_KIND_META, srv) != -1 || cluster_set_peerlink_kind(CLUSTER_PL_KINDS, srv) != -1 ||
        cluster_set_peerlink_kind(-1, srv) != -1)
        die("links: the table took the metadata kind or a kind out of range");
    cluster_set_peerlink_kind(PL_KIND_LOG, srv);
    if (lk_dials(padv, mid, me.uuid, mident, PL_KIND_BULK, 1500))
        die("links: a bulk link came up while only the log kind had a peerlink");
    if (!lk_dials(padv, mid, me.uuid, mident, PL_KIND_LOG, 10000))
        die("links: a log link did not come up with the log kind registered");
    cluster_set_peerlink(srv);
    if (lk_dials(padv, mid, me.uuid, bad_ident, PL_KIND_LOG, 1500))
        die("links: a data link came up for a member's id with another identity");
    if (lk_dials(padv, me.id, me.uuid, me.ident, PL_KIND_LOG, 1500))
        die("links: a data link came up from this server's own identity");
    if (lk_dials(padv, 7, me.uuid, rnd, PL_KIND_LOG, 1500))
        die("links: a data link came up for an id that is no member");
    if (lk_dials(padv, 0, me.uuid, rnd, PL_KIND_LOG, 1500))
        die("links: a data link came up for id 0");
    if (lk_dials(padv, mid, other, mident, PL_KIND_LOG, 1500))
        die("links: a data link came up for another cluster's uuid");
    if (lk_dials(padv, mid, zero, mident, PL_KIND_LOG, 1500))
        die("links: a data link came up for a zero cluster uuid");
    /* the member: both kinds come up */
    if (!lk_dials(padv, mid, me.uuid, mident, PL_KIND_LOG, 10000))
        die("links: a member's log link did not come up");
    if (!lk_dials(padv, mid, me.uuid, mident, PL_KIND_BULK, 10000))
        die("links: a member's bulk link did not come up");
    if (!lk_dials(padv, mid, me.uuid, mident, PL_KIND_SNAP, 10000)) /* R4's snapshot kind, handed to the same peerlink */
        die("links: a member's snapshot link (kind 5) did not come up");
    /* the metadata port still serves its admin ops */
    if (cluster_admin(padv, secret, secret_len, CLUSTER_OP_STATUS, NULL, 0, 5000, &rc, &rep, &len, err, sizeof err) != 0 ||
        rc != 0)
        die("links: status after the data links: %s", err);
    free(rep);
    cluster_set_peerlink(NULL);
    cluster_stop();
    peerlink_free(srv);
    stop_all();
    printf("  data links: refused without a peerlink, for a kind without one, for a non-member, a wrong identity or uuid; a "
           "member's come up\n");
}

/* replicate: a volume of 3 replicas with the replication driver (server/repld.c; no TSDB_CLUSTER_WRITES): the leader
 * promotes itself once its EPOCH marker is committed, takes writes, and every replica holds the same rows. */
static const char *const rep_names[] = {"pump1.flow", "pump2.flow", "pump3.big", "pump4.slow"};
#define REP_NAMES 4

/* waits until the leader takes a series creation in vol (it is still promoting: UNAVAILABLE) */
static tsdb_sid rep_series(tsdbc *c, const char *name, const char *vol, int ms)
{
    uint64_t t0 = now_ms();
    for (;;) {
        tsdb_sid id = 0;
        int rc = tsdbc_series_at(c, name, vol, &id);
        if (rc == 0)
            return id;
        if (rc != TSDB_ERR_UNAVAILABLE || now_ms() - t0 > (uint64_t)ms)
            die("series %s in %s: %s", name, vol, ers(rc));
        struct timespec ts = {0, 20000000};
        nanosleep(&ts, NULL);
    }
}

/* every server's copy of volume 1, read in-process after a clean stop: the same rows and digests, `want` rows each */
static void rep_same(const uint64_t *want, const char *what)
{
    uint64_t rows[3][REP_NAMES], h[3][REP_NAMES];
    for (int i = 0; i < 3; i++) {
        char dir[PATH_MAX + 80], v[PATH_MAX + 120];
        server_dir(i, dir, sizeof dir);
        snprintf(v, sizeof v, "%s/v1", dir);
        int rc = cvol_digest(v, rep_names, REP_NAMES, rows[i], h[i]);
        if (rc != 0)
            die("%s: open %s read-only: %s", what, v, ers(rc));
        static const char *const files[] = {"SERIES", "CLASSES", "RETENTION"};
        for (int f = 0; i && f < 3; f++) {
            char a[PATH_MAX + 160], b[PATH_MAX + 160], cmd[2 * PATH_MAX + 400];
            snprintf(a, sizeof a, "%s/n0/v1/%s", base, files[f]);
            snprintf(b, sizeof b, "%s/n%d/v1/%s", base, i, files[f]);
            snprintf(cmd, sizeof cmd, "cmp -s '%s' '%s'", a, b);
            if (access(a, F_OK) != 0) { /* CLASSES comes with a series' first class switch */
                if (f == 0 || access(b, F_OK) == 0)
                    die("%s: server 0 has no %s%s", what, files[f], f ? " and another server has" : "");
                continue;
            }
            if (system(cmd) != 0)
                die("%s: server %d's %s differs from server 0's", what, i, files[f]);
        }
        for (int k = 0; k < REP_NAMES; k++) {
            if (rows[i][k] != want[k])
                die("%s: server %d holds %" PRIu64 " rows of %s, not %" PRIu64, what, i, rows[i][k], rep_names[k],
                    want[k]);
            if (i && h[i][k] != h[0][k])
                die("%s: server %d's rows of %s differ from server 0's", what, i, rep_names[k]);
        }
    }
}

struct rep_writer {
    int port;
    tsdb_sid id;
    int64_t t0;
    int count, done, rc;
    int big; /* > 0: one insert of this many rows instead of `count` single rows */
    int acked; /* rows acknowledged so far (rows t0, t0 + 1000, ...) */
};
static int rep_timeout_ms; /* > 0: every answer to a rep_write_thread within this, or the write fails (a hang shows as
                              a failure, not as a test that never ends) */

/* small writes of one row each from another connection, while the main thread kills and restarts a replica */
static void *rep_write_thread(void *a)
{
    struct rep_writer *w = a;
    tsdbc *c;
    w->rc = tsdbc_connect("127.0.0.1", w->port, &c);
    if (w->rc == 0) {
        tsdbc_set_retry(c, 0);
        if (rep_timeout_ms > 0)
            tsdbc_set_timeout(c, rep_timeout_ms);
        if (w->big > 0) {
            int64_t *ts = malloc((size_t)w->big * sizeof *ts);
            float *val = malloc((size_t)w->big * sizeof *val);
            if (!ts || !val)
                die("out of memory");
            for (int j = 0; j < w->big; j++)
                ts[j] = w->t0 + 1000LL * j, val[j] = (float)(j % 613);
            w->rc = tsdbc_insert_series(c, w->id, ts, val, w->big);
            if (w->rc == 0)
                __atomic_store_n(&w->acked, w->big, __ATOMIC_RELEASE);
            free(ts);
            free(val);
        }
        for (int j = 0; j < w->count && w->rc == 0; j++) {
            int64_t ts = w->t0 + 1000LL * j;
            float val = (float)j;
            w->rc = tsdbc_insert_series(c, w->id, &ts, &val, 1);
            if (w->rc == 0)
                __atomic_store_n(&w->acked, j + 1, __ATOMIC_RELEASE);
        }
        tsdbc_close(c);
    }
    __atomic_store_n(&w->done, 1, __ATOMIC_RELEASE);
    return NULL;
}

static void scen_replicate(void)
{
    scenario("replicate");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id[REP_NAMES];
    for (int k = 0; k < REP_NAMES; k++)
        id[k] = rep_series(c, rep_names[k], "plant", 30000);
    uint64_t n[REP_NAMES] = {0};
    /* small writes, one row each: the log stream and the commit point */
    for (int j = 0; j < 200; j++) {
        int64_t ts = 1000 + 1000LL * j;
        float val = (float)j;
        if ((rc = tsdbc_insert_series(c, id[0], &ts, &val, 1)) != 0)
            die("small insert %d: %s", j, ers(rc));
        n[0]++;
    }
    {
        int64_t ts[3] = {1000, 2000, 3000};
        float val[3] = {1, 2, 3};
        if ((rc = tsdbc_insert_series(c, id[1], ts, val, 3)) != 0)
            die("insert of 3 rows: %s", ers(rc));
        n[1] += 3;
    }
    /* a large insert (straight to parts: shipped on the bulk link, staged, committed by a marker) */
    {
        enum { BIG = 100000 };
        int64_t *ts = malloc(BIG * sizeof *ts);
        float *val = malloc(BIG * sizeof *val);
        if (!ts || !val)
            die("out of memory");
        for (int j = 0; j < BIG; j++)
            ts[j] = 1000 + 1000LL * j, val[j] = (float)(j % 977);
        if ((rc = tsdbc_insert_series(c, id[2], ts, val, BIG)) != 0)
            die("large insert: %s", ers(rc));
        n[2] += BIG;
        /* a delete, and a replace of a range by fewer rows */
        if ((rc = tsdbc_delete_range(c, id[2], 1000 + 1000LL * 100, 1000 + 1000LL * 200)) != 0)
            die("delete: %s", ers(rc));
        for (int j = 0; j < 10; j++)
            ts[j] = 1000 + 1000LL * (500 + 7 * j), val[j] = -1;
        tsdb_values tv = {TSDB_FLOAT32, val, NULL};
        if ((rc = tsdbc_replace_range(c, id[2], 1000 + 1000LL * 500, 1000 + 1000LL * 600, ts, &tv, 10)) != 0)
            die("replace: %s", ers(rc));
        n[2] = (uint64_t)rows_of(c, id[2]); /* the replicas must hold what the leader answers */
        if (n[2] >= BIG - 100)
            die("the delete and the replace removed nothing: %" PRIu64 " rows", n[2]);
        free(ts);
        free(val);
    }
    /* a slow fresh series: its first flush (flush_interval_ms 5 s) gives it a class of its own (a CLASS marker) */
    {
        int64_t ts[200];
        float val[200];
        for (int j = 0; j < 200; j++)
            ts[j] = 3600000LL * j, val[j] = (float)j;
        if ((rc = tsdbc_insert_series(c, id[3], ts, val, 200)) != 0)
            die("insert of the slow series: %s", ers(rc));
        n[3] = 200;
        /* RETENTION: a limit that keeps every row (the rows are from 1970) */
        if ((rc = tsdbc_set_retention(c, id[0], 100LL * 366 * 86400000)) != 0)
            die("retention: %s", ers(rc));
        char cls[PATH_MAX + 120];
        snprintf(cls, sizeof cls, "%s/n%d/v1/CLASSES", base, L);
        uint64_t t0 = now_ms();
        while (access(cls, F_OK) != 0) {
            if (now_ms() - t0 > 30000)
                die("the slow series got no class of its own (no %s)", cls);
            struct timespec w = {0, 100000000};
            nanosleep(&w, NULL);
        }
        int64_t t1 = 3600000LL * 200;
        float v1 = 7;
        if ((rc = tsdbc_insert_series(c, id[3], &t1, &v1, 1)) != 0) /* after the switch */
            die("insert after the class switch: %s", ers(rc));
        n[3]++;
    }
    for (int k = 0; k < REP_NAMES; k++)
        if ((uint64_t)rows_of(c, id[k]) != n[k])
            die("the leader reads %d rows of %s, not %" PRIu64, rows_of(c, id[k]), rep_names[k], n[k]);
    printf("  the leader promoted itself and took small and large writes, a delete, a replace, a retention limit and a class switch\n");

    /* a replica killed while the leader takes writes: restarted, it catches up from the leader's log (a restart of
     * every server would come back on new peer ports, which the metadata group does not know) */
    int R = (L + 1) % 3;
    stop(R, SIGKILL);
    struct rep_writer w = {cports[L], id[0], 10000000, 300, 0, 0, 0, 0};
    /* and a large insert: its part is shipped while R is down; R, back, does not stage the first file it receives
     * (TSDB_REPLD_TEST=dropbulk), finds the COMMIT marker in the log without the file and fetches it from the leader
     * by the marker's position (eng_leader_file_open serves a name only for the marker that named it) */
    struct rep_writer wb = {cports[L], id[2], 2000000000, 0, 0, 0, 100000, 0}; /* above wal_max_batch_rows */
    pthread_t th, thb;
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0 || pthread_create(&thb, NULL, rep_write_thread, &wb) != 0)
        die("pthread_create");
    struct timespec pause = {1, 500000000};
    nanosleep(&pause, NULL);
    /* the part shipped to R once it is back is lost: R must fetch it, and asks only 5 s after it found the file missing
     * (fetchlate), when its log has long passed the marker and the leader has sealed and flushed the marker's segment:
     * the leader keeps that segment, and the link the file is served from, by R's durable end, which stops below the
     * marker (keepwritten: by R's written end it went, and R never got the file) */
    penv[R] = "TSDB_REPLD_TEST=dropbulk,fetchlate";
    start(R);
    penv[R] = NULL;
    uint64_t t0 = now_ms();
    while (!__atomic_load_n(&w.done, __ATOMIC_ACQUIRE) || !__atomic_load_n(&wb.done, __ATOMIC_ACQUIRE)) {
        if (now_ms() - t0 > 60000)
            die("300 small writes and a large one with a replica down and back did not finish in 60 s");
        struct timespec ms = {0, 10000000};
        nanosleep(&ms, NULL);
    }
    pthread_join(th, NULL);
    pthread_join(thb, NULL);
    if (w.rc != 0)
        die("a small write with a replica down: %s", ers(w.rc));
    if (wb.rc != 0)
        die("a large write with a replica down: %s", ers(wb.rc));
    n[0] += 300;
    n[2] += 100000;
    /* the writes no longer wait for R: once R is silent for isr_lag_ms it leaves the ISR and they go on. R catches up
     * as a learner and grows back; only then has it surely seen the COMMIT marker and fetched the part. 60 s: under
     * TSan the restart, the catch-up and the fetch (5 s late on purpose) took the whole of 30 s (r3d-isr g3 tsan).
     * A replica that refuses its own log is named apart from a slow rejoin. (Under the default keep caps R removes no
     * segment here, so floornotsaved is repcheck's: its caps are 2 s.) */
    for (uint64_t t1 = now_ms(); isr_of(L, "plant", NULL) != 3;) {
        if (log_has(R, "the log starts above the commit floor"))
            die("the replica restarted under writes refused its log: the log starts above the commit floor");
        if (now_ms() - t1 > 60000)
            die("the replica restarted under writes: the ISR of plant has %" PRIu32 " members, not 3, after 60000 ms",
                isr_of(L, "plant", NULL));
        struct timespec ms = {0, 50000000};
        nanosleep(&ms, NULL);
    }
    if (!log_has(R, "fetches"))
        die("the replica restarted under a large write never fetched its part from the leader");
    await_open_gen(L, "plant", R, 2, 0);
    if ((uint64_t)rows_of(c, id[0]) != n[0])
        die("the leader reads %d rows of %s, not %" PRIu64, rows_of(c, id[0]), rep_names[0], n[0]);
    tsdbc_close(c);
    stop_all();
    rep_same(n, "after a clean stop");
    printf("  a replica killed under writes and restarted catches up, fetching the part it missed; every replica holds the leader's rows\n");
}

/* the ISR of volume `name` in server via's copy: its member count, *version its ISR version */
static uint32_t isr_of(int via, const char *name, uint64_t *version)
{
    struct meta_volume v;
    if (!vol_rec(via, name, &v))
        die("no record of %s", name);
    if (version)
        *version = v.isr_version;
    return v.nisr;
}

static void await_isr(int via, const char *name, uint32_t n, int ms, const char *what)
{
    uint64_t t0 = now_ms();
    while (isr_of(via, name, NULL) != n) {
        if (now_ms() - t0 > (uint64_t)ms)
            die("%s: the ISR of %s has %" PRIu32 " members, not %" PRIu32 ", after %d ms", what, name,
                isr_of(via, name, NULL), n, ms);
        struct timespec w = {0, 50000000};
        nanosleep(&w, NULL);
    }
}

static void hold_isr(int on)
{
    for (int i = 0; i < 3; i++) {
        char hold[PATH_MAX + 96];
        server_dir(i, hold, sizeof hold);
        strcat(hold, "/state/holdisr");
        if (on) {
            FILE *h = fopen(hold, "w");
            if (!h || fclose(h) != 0)
                die("%s: %s", hold, strerror(errno));
        } else if (unlink(hold) != 0 && errno != ENOENT) {
            die("%s: %s", hold, strerror(errno));
        }
    }
}

/* waits for a writer thread; dies after ms */
static void await_writer(struct rep_writer *w, pthread_t th, int ms, const char *what)
{
    uint64_t t0 = now_ms();
    while (!__atomic_load_n(&w->done, __ATOMIC_ACQUIRE)) {
        if (now_ms() - t0 > (uint64_t)ms)
            die("%s: not answered after %d ms", what, ms);
        struct timespec w10 = {0, 10000000};
        nanosleep(&w10, NULL);
    }
    pthread_join(th, NULL);
    if (w->rc != 0)
        die("%s: %s", what, ers(w->rc));
}

/* isr (design-cluster.md 6.1, 8.1 step 5): a replica that stops acknowledging leaves the ISR after isr_lag_ms through
 * an ISR_CHANGE the Raft leader proposes on the request's basis, and writes go on without it; back, it catches up and
 * joins again. While the change is not committed (hold_isr_file) the commit point still waits for the member (mutant
 * commitpastremoved); a late duplicate of the old shrink request (isr_replay) is refused at the apply (mutant
 * shrinknocond). */
static void scen_isr(void)
{
    scenario("isr");
    for (int i = 0; i < 3; i++) {
        envs[i] = "hold_isr_file=1,isr_replay=1";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    uint64_t rows = 0;
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    rows++;
    await_isr(0, "plant", 3, 5000, "every replica up");

    /* a killed replica while the metadata group commits no ISR change: the write waits */
    int R1 = (L + 1) % 3, R2 = (L + 2) % 3;
    hold_isr(1);
    stop(R1, SIGKILL);
    struct rep_writer w = {cports[L], id, 2000, 1, 0, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0)
        die("pthread_create");
    /* The window is counted from the leader's ask, a condition, never from the kill: how soon the leader notices the
     * dead replica (and then isr_lag_ms) is not the test's to guess. The plant hands its META over in the same call
     * as the ask, so its wrong acknowledgement follows at once and 3 s from the ask is margin; a slow detection of
     * the kill no longer lets the mutant pass as "isr passed" */
    uint64_t t0 = now_ms();
    while (!log_has(L, "asks for an ISR of 2 members")) {
        if (now_ms() - t0 > 30000)
            die("the leader never asked for an ISR without the killed replica (30 s)");
        usleep(20000);
    }
    t0 = now_ms();
    while (now_ms() - t0 < 3000 && !__atomic_load_n(&w.done, __ATOMIC_ACQUIRE))
        usleep(10000);
    if (__atomic_load_n(&w.done, __ATOMIC_ACQUIRE))
        die("a write was acknowledged without a killed ISR member before the ISR change committed (rc %d)", w.rc);
    if (log_has(L, "planted META was dropped"))
        die("the leader's core dropped the planted META (TSDB_REPLD_MUTANT commitpastremoved planted nothing)");
    if (isr_of(0, "plant", NULL) != 3)
        die("the ISR changed while the proposals were held");
    hold_isr(0);
    struct timespec s3 = {3, 0};
    await_writer(&w, th, 5000, "the write held by an uncommitted ISR change, once the change could commit");
    rows++;
    await_isr(0, "plant", 2, 5000, "a replica killed");
    /* writes go on without it, each quickly */
    for (int j = 0; j < 50; j++) {
        uint64_t t0 = now_ms();
        int64_t t = 10000 + 1000LL * j;
        if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0)
            die("a write with a replica out of the ISR: %s", ers(rc));
        if (now_ms() - t0 > 1000)
            die("a write with a replica out of the ISR took %" PRIu64 " ms", now_ms() - t0);
        rows++;
    }
    uint64_t v1;
    isr_of(0, "plant", &v1);
    /* back, it catches up and joins; the old shrink request replayed late (isr_replay) must change nothing */
    start(R1);
    await_isr(0, "plant", 3, 30000, "the killed replica restarted");
    uint64_t v2;
    isr_of(0, "plant", &v2);
    nanosleep(&s3, NULL);
    uint64_t v3;
    if (isr_of(0, "plant", &v3) != 3 || v3 != v2)
        die("after the replica joined again the ISR moved: %" PRIu32 " members, version %" PRIu64 " -> %" PRIu64
            " (a stale ISR request applied)", isr_of(0, "plant", NULL), v2, v3);
    int replayed = 0;
    for (int i = 0; i < 3; i++)
        replayed |= log_has(i, "test: replays an ISR request");
    if (!replayed)
        die("no server replayed the old ISR request: the check above proves nothing");
    printf("  a killed replica leaves the ISR only once the change committed (versions %" PRIu64 ", %" PRIu64
           "), writes go on, and it joins again; a stale request is refused\n", v1, v2);

    /* a stopped replica (SIGSTOP: its stream breaks, no ACK) likewise, and comes back by itself */
    pause_server(R2, 1);
    for (int j = 0; j < 20; j++) {
        int64_t t = 100000 + 1000LL * j;
        if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0)
            die("a write with a replica stopped: %s", ers(rc));
        rows++;
    }
    await_isr(0, "plant", 2, 10000, "a replica stopped");
    pause_server(R2, 0);
    await_isr(0, "plant", 3, 30000, "the stopped replica continued");
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    for (int i = 0; i < 3; i++)
        envs[i] = NULL;
    uint64_t wantr[REP_NAMES] = {rows, 0, 0, 0};
    rep_same(wantr, "after a clean stop");
    printf("  a stopped replica leaves the ISR and joins again once it runs; every replica holds the leader's rows\n");
}

/* topology: TOPOLOGY, STATUS and MOVED of a cluster node come from its metadata copy (cluster_copy_get; S2-1). */
static const char *const topo_vols[] = {"east", "west"};

/* server i's TOPOLOGY against the records of server via's copy: the three members (client address, alive unless
 * server `down`), and for each volume one entry per replica with the record's epoch, its member's client address and
 * the role D9 gives it (leader OWNER, ISR STANDBY, else FOLLOWER); a replica of server `down` UNAVAILABLE
 * (UNREACHABLE). 0 when they agree, else a line in why; *followers counts the FOLLOWER entries. */
static int topo_agrees(int i, int via, int down, char *why, size_t wn, int *followers)
{
    tsdbc *c = client(i);
    tsdbc_topo *t = NULL;
    int rc = tsdbc_topology(c, &t), bad = 0;
    tsdbc_close(c);
    if (rc != 0) {
        snprintf(why, wn, "TOPOLOGY: %s", ers(rc));
        return -1;
    }
    *followers = 0;
    if (t->nnodes != 3) {
        snprintf(why, wn, "%zu nodes, not 3", t->nnodes);
        bad = 1;
    }
    for (int s = 0; s < 3 && !bad; s++) {
        char want[64];
        snprintf(want, sizeof want, "127.0.0.1:%d", cports[s]);
        size_t k = 0;
        while (k < t->nnodes && t->nodes[k].node_id != ids[s])
            k++;
        if (k == t->nnodes || strcmp(t->nodes[k].addr, want) != 0 || t->nodes[k].alive != (s != down)) {
            snprintf(why, wn, "node %u (server %d): %s, alive %d (want %s, alive %d)", (unsigned)ids[s], s,
                     k < t->nnodes ? t->nodes[k].addr : "missing", k < t->nnodes ? t->nodes[k].alive : -1, want,
                     s != down);
            bad = 1;
        }
    }
    size_t seen = 0;
    for (int n = 0; n < 2 && !bad; n++) {
        struct meta_volume v;
        if (!vol_rec(via, topo_vols[n], &v))
            die("topology: no record of %s", topo_vols[n]);
        for (uint32_t k = 0; k < v.nrep && !bad; k++) {
            uint32_t node = v.rep[k].node;
            int in_isr = 0;
            for (uint32_t j = 0; j < v.nisr; j++)
                in_isr |= v.isr[j] == node;
            int role = node == v.leader ? TSDB_ROLE_OWNER : in_isr ? TSDB_ROLE_STANDBY : TSDB_ROLE_FOLLOWER;
            int s = server_of(node);
            char want[64];
            snprintf(want, sizeof want, "127.0.0.1:%d", s >= 0 ? cports[s] : 0);
            size_t e = 0;
            while (e < t->nvols && !(t->vols[e].vol == v.number && t->vols[e].owner == node))
                e++;
            if (e == t->nvols) {
                snprintf(why, wn, "%s: no entry for node %u", topo_vols[n], (unsigned)node);
                bad = 1;
                break;
            }
            const tsdbc_vol *tv = &t->vols[e];
            seen++;
            *followers += tv->role == TSDB_ROLE_FOLLOWER;
            if (tv->role != role || tv->epoch != v.epoch || strcmp(tv->addr, want) != 0) {
                snprintf(why, wn, "%s node %u: role %u epoch %u addr %s, the record says role %d epoch %" PRIu64 " %s",
                         topo_vols[n], (unsigned)node, tv->role, tv->epoch, tv->addr, role, v.epoch, want);
                bad = 1;
            } else if (s == down && role != TSDB_ROLE_OWNER &&
                       (tv->health != TSDB_HEALTH_UNAVAILABLE || tv->reason != TSDB_WHY_UNREACHABLE)) {
                snprintf(why, wn, "%s: the down replica %u has health %u reason %u", topo_vols[n], (unsigned)node,
                         tv->health, tv->reason);
                bad = 1;
            } else if (s == down && role == TSDB_ROLE_OWNER &&
                       (tv->health != TSDB_HEALTH_UNAVAILABLE || tv->reason != TSDB_WHY_NO_OWNER)) {
                snprintf(why, wn, "%s: the down leader %u has health %u reason %u, not NO_OWNER", topo_vols[n],
                         (unsigned)node, tv->health, tv->reason);
                bad = 1;
            } else if (s != down && role == TSDB_ROLE_OWNER && i != s && tv->health != TSDB_HEALTH_AVAILABLE) {
                snprintf(why, wn, "%s: the leader %u, up and elsewhere, has health %u reason %u", topo_vols[n],
                         (unsigned)node, tv->health, tv->reason);
                bad = 1;
            }
        }
    }
    if (!bad && seen != t->nvols) {
        snprintf(why, wn, "%zu entries, the records have %zu", t->nvols, seen);
        bad = 1;
    }
    tsdbc_topology_free(t);
    return bad ? -1 : 0;
}

static void await_topo(int via, int down, int ms, int need_follower, const char *what)
{
    char why[512] = "";
    uint64_t t0 = now_ms();
    for (;;) {
        int ok = 1, fol = 0;
        for (int i = 0; i < 3 && ok; i++) {
            int f = 0;
            if (i != down && topo_agrees(i, via, down, why, sizeof why, &f) != 0) {
                ok = 0;
                snprintf(why + strlen(why), sizeof why - strlen(why), " (server %d)", i);
            }
            fol += f;
        }
        if (ok && (!need_follower || fol))
            return;
        if (ok)
            snprintf(why, sizeof why, "no entry is a FOLLOWER");
        if (now_ms() - t0 > (uint64_t)ms)
            die("%s: TOPOLOGY does not agree with the records after %d ms: %s", what, ms, why);
        usleep(100000);
    }
}

/* STATUS through c lists every server but `self` as a peer: its client and peer addresses, alive unless `down` */
static void status_peers(tsdbc *c, int self, int down, const char *what)
{
    char *text = NULL, line[160];
    int rc = tsdbc_status(c, &text);
    if (rc != 0)
        die("%s: STATUS: %s", what, ers(rc));
    if (!strstr(text, "\ncluster.applied="))
        die("%s: STATUS has no cluster.applied line", what);
    for (int s = 0; s < 3; s++) {
        if (s == self)
            continue;
        snprintf(line, sizeof line, "\npeer.%u.addr=127.0.0.1:%d\n", (unsigned)ids[s], cports[s]);
        int ok = strstr(text, line) != NULL;
        snprintf(line, sizeof line, "\npeer.%u.peer=127.0.0.1:%d\n", (unsigned)ids[s], pports[s]);
        ok = ok && strstr(text, line);
        snprintf(line, sizeof line, "\npeer.%u.alive=%d\n", (unsigned)ids[s], s != down);
        if (!ok || !strstr(text, line))
            die("%s: STATUS of server %d does not list server %d (node %u) as a peer at %d/%d, alive %d:\n%s", what,
                self, s, (unsigned)ids[s], cports[s], pports[s], s != down, text);
    }
    snprintf(line, sizeof line, "\npeer.%u.", (unsigned)ids[self]);
    if (strstr(text, line))
        die("%s: STATUS of server %d lists itself as a peer", what, self);
    free(text);
}

/* STATUS of server i through c says node.id=want */
static void status_id(tsdbc *c, uint32_t want, const char *what)
{
    char *text = NULL, line[64];
    int rc = tsdbc_status(c, &text);
    if (rc != 0)
        die("%s: STATUS: %s", what, ers(rc));
    snprintf(line, sizeof line, "node.id=%u\n", (unsigned)want);
    if (strncmp(text, line, strlen(line)) != 0)
        die("%s: STATUS begins \"%.40s\", not %s", what, text, line);
    free(text);
}

static void scen_topology(void)
{
    scenario("topology");
    strict_reads = 1; /* a replica moves reads to the leader (D5), as in production */
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDBD_TEST_ROUTE_MOVED=1";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num[2];
    int rc;
    if ((rc = vol_add(0, "east", 3, &num[0])) != 0 || (rc = vol_add(0, "west", 2, &num[1])) != 0)
        die("volume add: %s", cluster_strerror(rc));
    for (int n = 0; n < 2; n++) {
        struct meta_volume v;
        if (!vol_rec(0, topo_vols[n], &v))
            die("no record of %s", topo_vols[n]);
        for (uint32_t k = 0; k < v.nrep; k++)
            await_open_gen(0, topo_vols[n], server_of(v.rep[k].node), 1, 0);
    }
    await_isr(0, "east", 3, 20000, "east with every replica up");
    /* every node answers the same leaders, epochs and replica sets (the records of server 0's copy) */
    await_topo(0, -1, 20000, 0, "every server up");
    /* STATUS: each server its own id (one of them is not 1) */
    for (int i = 0; i < 3; i++) {
        tsdbc *c = client(i);
        status_id(c, ids[i], "STATUS");
        status_peers(c, i, -1, "STATUS");
        tsdbc_close(c);
    }
    struct meta_volume ev;
    if (!vol_rec(0, "east", &ev))
        die("no record of east");
    int L = server_of(ev.leader);
    if (L < 0 || L > 2)
        die("the leader of east is node %u", ev.leader);
    int k = L == 0 ? 1 : 3 - L; /* neither the leader of east nor server 0 (the metadata group's first leader) */
    struct meta_volume wv;
    if (!vol_rec(0, "west", &wv))
        die("no record of west");
    int W = server_of(wv.leader);
    if (W > 0 && W != L)
        k = W;         /* kill west's leader where that is allowed: route_moved then says PROMOTING (leader not UP) */
    int j = 3 - L - k; /* the third: neither leads east */
    /* the replica of west that is not its leader, for route_moved's PROMOTING once that leader is down */
    int wr = -1;
    for (uint32_t r = 0; r < wv.nrep; r++)
        if (wv.rep[r].node != wv.leader)
            wr = server_of(wv.rep[r].node);
    tsdb_sid wid = 0;
    if (W == k && wr >= 0 && wr != k) {
        tsdbc *wc = client(W);
        wid = rep_series(wc, "pump.west", "west", 30000);
        tsdbc_close(wc);
    }
    /* MOVED from the copy (the test hook routes a write to a volume led elsewhere): the leader's id, epoch and client
     * address; the C client follows it and writes there */
    {
        tsdbc *lc = client(L);
        tsdb_sid id = rep_series(lc, "pump.moved", "east", 30000);
        tsdbc_close(lc);
        tsdbc *c = client(j);
        int64_t ts = 1000;
        float val = 1;
        rc = tsdbc_insert_series(c, id, &ts, &val, 1); /* by id: the hook sees the volume of an id */
        tsdbc_err_info e;
        char want_addr[64];
        snprintf(want_addr, sizeof want_addr, "127.0.0.1:%d", cports[L]);
        if (rc != TSDB_ERR_MOVED || tsdbc_last_error(c, &e) != TSDB_ERR_MOVED || e.nmoved != 1 ||
            e.moved[0].node_id != ev.leader || e.moved[0].epoch != ev.epoch || e.moved[0].vol != ev.number ||
            strcmp(e.moved[0].addr, want_addr) != 0)
            die("a write to east on server %d: %s, MOVED to node %u epoch %u at %s (want node %u epoch %" PRIu64
                " at %s)", j, ers(rc), e.nmoved ? (unsigned)e.moved[0].node_id : 0, e.nmoved ? e.moved[0].epoch : 0,
                e.nmoved ? e.moved[0].addr : "-", (unsigned)ev.leader, ev.epoch, want_addr);
        tsdbc_set_retry(c, 20000);
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("the client did not follow MOVED to the leader of east: %s", ers(rc));
        status_id(c, ev.leader, "STATUS after MOVED"); /* the connection is the leader's now */
        tsdbc_close(c);
    }
    /* a member marked down: alive 0 on every other node; once east's ISR drops it its entry is a FOLLOWER */
    stop(k, SIGKILL);
    struct state_want sw = {ids[k], META_DOWN, 0};
    await_view(L, p_member_state, &sw, "the killed member marked down");
    await_isr(L, "east", 2, 30000, "east without the killed replica");
    await_topo(L, k, 30000, 1, "a member down");
    {
        tsdbc *c = client(L);
        status_peers(c, L, k, "STATUS with a member down");
        tsdbc_close(c);
    }
    /* west's leader killed: a write on its other replica gets UNAVAILABLE (PROMOTING, the record names a leader whose
     * member is not UP: route_fill) from route_moved, not MOVED to the dead leader, while the record still names it (a
     * promotion would move the record on: then no verdict) */
    if (wid) {
        uint64_t t0 = now_ms();
        for (;;) {
            tsdbc *c = client(wr);
            int64_t ts = 2000;
            float val = 2;
            int rc2 = tsdbc_insert_series(c, wid, &ts, &val, 1);
            tsdbc_err_info e;
            tsdbc_last_error(c, &e);
            tsdbc_close(c);
            struct meta_volume now;
            if (!vol_rec(L, "west", &now) || now.leader != wv.leader) {
                printf("  (west was promoted away from its killed leader: no PROMOTING check)\n");
                break;
            }
            if (rc2 == TSDB_ERR_UNAVAILABLE && e.nunavail == 1 && e.unavail[0].reason == TSDB_WHY_PROMOTING &&
                e.nmoved == 0)
                break;
            if (now_ms() - t0 > 20000)
                die("a write to west on server %d with its leader (server %d) down: %s, %u MOVED, reason %u (want "
                    "UNAVAILABLE, PROMOTING)", wr, k, ers(rc2), e.nmoved, e.nunavail ? e.unavail[0].reason : 0);
            usleep(100000);
        }
    } else {
        printf("  (west's leader is server 0 or east's leader: no PROMOTING check of route_moved)\n");
    }
    stop_all();
    printf("  TOPOLOGY from the copy agrees on every node (roles, epochs, addresses, alive); STATUS names each node; "
           "MOVED names the leader and the C client follows it\n");
}

/* movedself: route_moved on the leader itself (TSDBD_TEST_ROUTE_MOVED=2 routes every INSERT to a cluster volume,
 * one led here too) answers UNAVAILABLE, never MOVED to its own address (a client would follow that in a circle
 * until its retry budget ran out); mutant ownerself */
static void scen_movedself(void)
{
    scenario("movedself");
    strict_reads = 1; /* a replica moves reads to the leader (D5), as in production */
    penv[0] = "TSDBD_TEST_ROUTE_MOVED=2";
    start(0);
    init_cluster(0, 600);
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "solo", 1, &num)) != 0)
        die("volume add: %s", cluster_strerror(rc));
    await_open_gen(0, "solo", 0, 1, 0);
    tsdbc *c = client(0);
    tsdb_sid id = rep_series(c, "pump.self", "solo", 30000);
    int64_t ts = 1000;
    float val = 1;
    uint64_t t0 = now_ms();
    for (;;) { /* the copy may not name this server as the leader yet: then NO_OWNER as well */
        rc = tsdbc_insert_series(c, id, &ts, &val, 1);
        tsdbc_err_info e;
        tsdbc_last_error(c, &e);
        if (rc == TSDB_ERR_MOVED || e.nmoved)
            die("the leader answered MOVED to itself (node %u at %s)", e.nmoved ? (unsigned)e.moved[0].node_id : 0,
                e.nmoved ? e.moved[0].addr : "-");
        if (rc != TSDB_ERR_UNAVAILABLE || e.nunavail != 1 || e.unavail[0].vol != num)
            die("the routed write on the leader: %s (%d), %u entries, volume %u, after %llu ms (want UNAVAILABLE for "
                "volume %u)", ers(rc), rc, e.nunavail, e.nunavail ? (unsigned)e.unavail[0].vol : 0,
                (unsigned long long)(now_ms() - t0), (unsigned)num);
        if (now_ms() - t0 > 3000)
            break;
        usleep(100000);
    }
    tsdbc_close(c);
    stop_all();
    printf("  route_moved on the volume's own leader answers UNAVAILABLE, never MOVED to itself\n");
}

/* rc is MOVED to the leader `node` of volume `vol` at server s's client address (the copy's MOVED, never UNAVAILABLE) */
static tsdbc *login_retry(int i, const char *user, const char *pw, int budget_ms)
{
    tsdbc *c = login_on(i, user, pw);
    if (tsdbc_set_retry(c, budget_ms) != 0)
        die("tsdbc_set_retry");
    return c;
}

/* route (S2-1, s2e: the entry node's decision). Three servers with login on; east on all three, south and north on one
 * each, lone on all three but shown with no leader in every copy (TSDB_CLUSTER_TEST copy_noleader). On a server that
 * does not lead east, writes and reads by id, by path and in packed frames are MOVED to east's leader (never answered
 * there: a replica serves no read), and the C client follows MOVED to the leader within its budget; lone answers
 * UNAVAILABLE (NO_OWNER) off its real leader; a user with a prefix grant writes through a server that holds no copy of
 * south and is moved, not DENIED, and an id outside the grant is still DENIED at the owner; a frame naming volumes
 * led on two servers is INVALID and writes nothing; a volume the copy has no record of is NO_OWNER, never an empty read.
 * Mutants (TSDB_ROUTE_MUTANT): rightsbeforeroute, movedoffcopy, replicaread, spanaccepted, nocopyserved. */
static int count_series(void *ctx, const tsdb_series_result *r)
{
    (void)r;
    ++*(int *)ctx;
    return 0;
}

/* The requests that name many series by id, sent off the owner of `id`'s volume: QUERY_MULTI, QUERY_LATEST,
 * STATS_SERIES and the unpacked many-series inserts (INSERT and INSERT_VALUES, compression off) are each MOVED to node
 * `node` at server s, and none is answered here (route_ids in every handler, review F2, F3a-c) */
static void moved_many(tsdbc *c, tsdb_sid id, uint32_t vol, uint32_t node, int s, const char *where)
{
    char what[160];
    int got = 0;
    tsdb_multi_query q = {.kind = TSDB_MULTI_VALUES, .start = 0, .end = INT64_MAX / 2, .opts = {TSDB_ASC, 0}};
    snprintf(what, sizeof what, "QUERY_MULTI %s", where);
    expect_moved(c, tsdbc_query_multi(c, &q, &id, 1, NULL, count_series, &got), vol, node, s, what);
    if (got != 0)
        die("%s answered %d series before MOVED", what, got);
    tsdb_latest_result lr;
    snprintf(what, sizeof what, "QUERY_LATEST %s", where);
    expect_moved(c, tsdbc_latest(c, &id, 1, NULL, &lr), vol, node, s, what);
    tsdb_series_stat st;
    snprintf(what, sizeof what, "STATS_SERIES %s", where);
    expect_moved(c, tsdbc_series_stats(c, &id, 1, 0, &st), vol, node, s, what);
    tsdb_sid two[2] = {id, id};
    int64_t ts[2] = {5000, 6000};
    float val[2] = {5, 6};
    tsdb_values col = {TSDB_FLOAT32, val, NULL};
    int rc;
    if ((rc = tsdbc_set_compression(c, 0)) != 0)
        die("compression off: %s", ers(rc));
    snprintf(what, sizeof what, "an unpacked many-series INSERT %s", where);
    expect_moved(c, tsdbc_insert(c, two, ts, val, 2), vol, node, s, what);
    snprintf(what, sizeof what, "an unpacked many-series INSERT_VALUES %s", where);
    expect_moved(c, tsdbc_insert_values(c, two, ts, &col, 2), vol, node, s, what);
    if ((rc = tsdbc_set_compression(c, 1)) != 0)
        die("compression on: %s", ers(rc));
}

static void scen_route(void)
{
    scenario("route");
    strict_reads = 1; /* a replica moves reads to the leader (D5), as in production */
    const char *mut = getenv("TSDB_ROUTE_MUTANT");
    static char menv[128];
    snprintf(menv, sizeof menv, "TSDB_ROUTE_MUTANT=%s", mut ? mut : "");
    for (int i = 0; i < 3; i++) {
        auth_on[i] = 1;
        envs[i] = "copy_noleader=2";
        if (mut)
            penv[i] = menv;
        start(i);
    }
    char pw[PATH_MAX + 80], pw2[PATH_MAX + 80], args[PATH_MAX * 2 + 512], out[8192], p0[META_ADDR_MAX];
    put_file("pw", "root-pw", pw, sizeof pw);
    put_file("pw2", "alice-pw", pw2, sizeof pw2);
    peer_of(0, p0, sizeof p0);
    snprintf(args, sizeof args,
             "cluster init %s --secret-file %s --node-timeout-ms 1500 --heartbeat-ms 200 --voter-replace-s 600 "
             "--superuser root --password-file %s",
             p0, secret_path, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("cluster init --superuser root: %s", out);
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    snprintf(args, sizeof args, "cluster user add %s alice --password-file %s --secret-file %s", p0, pw2,
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("user add alice: %s", out);
    for (int i = 0; i < 3; i++) {
        await_view(i, p_users_caught_up, NULL, "users caught up");
        await_login(i, "root", "root-pw");
    }
    static const char *const names[4] = {"east", "lone", "south", "north"};
    static const uint32_t reps[4] = {3, 3, 1, 1};
    uint32_t num[4];
    struct meta_volume v[4];
    int rc;
    for (int n = 0; n < 4; n++)
        if ((rc = vol_add(0, names[n], reps[n], &num[n])) != 0)
            die("volume add %s: %s", names[n], cluster_strerror(rc));
    if (num[1] != 2)
        die("lone is volume %u, not 2 (copy_noleader names 2)", (unsigned)num[1]);
    for (int n = 0; n < 4; n++) {
        if (!vol_rec(0, names[n], &v[n]))
            die("no record of %s", names[n]);
        for (uint32_t k = 0; k < v[n].nrep; k++)
            await_open_gen(0, names[n], server_of(v[n].rep[k].node), 1, 0);
    }
    await_isr(0, "east", 3, 20000, "east with every replica up");
    int L = server_of(v[0].leader), R = (L + 1) % 3, LL = server_of(v[1].leader);
    {
        tsdbc *r0 = login_on(0, "root", "root-pw");
        if ((rc = tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ | TSDB_RIGHT_INSERT)) != 0)
            die("grant: %s", ers(rc));
        tsdbc_close(r0);
    }

    /* east's leader serves; a replica of it moves writes, reads, paths and packed frames to the leader */
    tsdbc *c = login_retry(L, "root", "root-pw", 0);
    tsdb_sid id = rep_series(c, "plant.a", "east", 30000), other = rep_series(c, "other.a", "east", 30000);
    int64_t ts[2] = {1000, 2000};
    float val[2] = {1, 2};
    if ((rc = tsdbc_insert_series(c, id, ts, val, 1)) != 0)
        die("a write on east's leader: %s", ers(rc));
    tsdbc_close(c);
    c = login_retry(R, "root", "root-pw", 0);
    tsdb_sid x;
    expect_moved(c, tsdbc_insert_series(c, id, ts + 1, val + 1, 1), num[0], v[0].leader, L, "a write on a replica");
    nrows = 0;
    expect_moved(c, tsdbc_query_raw(c, id, 0, INT64_MAX / 2, count_rows, NULL), num[0], v[0].leader, L,
                 "a read on a replica");
    if (nrows != 0)
        die("a replica answered %d rows of a read before MOVED", nrows);
    expect_moved(c, tsdbc_series_at(c, "plant.b", "east", &x), num[0], v[0].leader, L, "a series by path on a replica");
    tsdb_sid two[2] = {id, id};
    expect_moved(c, tsdbc_insert(c, two, ts, val, 2), num[0], v[0].leader, L, "a packed write on a replica");
    moved_many(c, id, num[0], v[0].leader, L, "on a replica");
    tsdbc_close(c);
    c = login_retry(R, "root", "root-pw", 20000);
    if ((rc = tsdbc_insert_series(c, id, ts + 1, val + 1, 1)) != 0)
        die("the client did not follow MOVED to east's leader: %s", ers(rc));
    status_id(c, v[0].leader, "STATUS after a write was moved");
    tsdbc_close(c);
    c = login_retry(R, "root", "root-pw", 20000);
    if (rows_of(c, id) != 2)
        die("the read through a replica, moved to the leader, has %d rows, not 2", nrows);
    status_id(c, v[0].leader, "STATUS after a read was moved");
    tsdb_latest_result lr;
    if ((rc = tsdbc_latest(c, &id, 1, NULL, &lr)) != 0 || lr.status != 0 || lr.ts != 2000)
        die("QUERY_LATEST through a replica, moved to the leader: %s, status %d, ts %" PRId64 ", not 2000", ers(rc),
            (int)lr.status, lr.ts);
    tsdbc_close(c);
    printf("  a replica moves writes, reads, paths, packed and many-series frames, QUERY_MULTI, QUERY_LATEST and "
           "STATS_SERIES to the leader; the client follows MOVED\n");

    /* lone: no leader in the copy; its real leader serves it (led here), every other server answers NO_OWNER */
    int nl = LL == 0 ? 1 : 0;
    c = login_retry(nl, "root", "root-pw", 0);
    expect_unavail(c, tsdbc_series_at(c, "plant.c", "lone", &x), (uint16_t)num[1], TSDB_WHY_NO_OWNER,
                   "a volume with no leader in the copy");
    /* a volume the copy has no record of (here never made; in jepsen-cluster a restarted server before its copy was
     * built): not open here, so the engine would answer an empty read; NO_OWNER until the copy knows it */
    tsdb_sid ghost = TSDB_SID(9, 0);
    nrows = 0;
    expect_unavail(c, tsdbc_query_raw(c, ghost, 0, INT64_MAX / 2, count_rows, NULL), 9, TSDB_WHY_NO_OWNER,
                   "a read of a volume the copy does not know");
    if (nrows != 0)
        die("a read of a volume the copy does not know answered %d rows", nrows);
    expect_unavail(c, tsdbc_insert_series(c, ghost, ts, val, 1), 9, TSDB_WHY_NO_OWNER,
                   "a write to a volume the copy does not know");
    tsdbc_close(c);
    printf("  a volume with no leader in the copy, or none in it: UNAVAILABLE (NO_OWNER)\n");

    /* south, on one server: a user with a prefix grant writes by id through a server without a copy of it and
     * is moved, never DENIED there (the id is not resolved through that server's names); outside the grant: DENIED at
     * the owner */
    int so = server_of(v[2].leader), to = (so + 1) % 3, no = server_of(v[3].leader);
    c = login_retry(so, "root", "root-pw", 0);
    tsdb_sid sid = rep_series(c, "plant.s", "south", 30000), sother = rep_series(c, "other.s", "south", 30000);
    tsdbc_close(c);
    tsdbc *a = login_retry(to, "alice", "alice-pw", 0);
    expect_moved(a, tsdbc_insert_series(a, sid, ts, val, 1), num[2], v[2].leader, so, "alice's write off the owner");
    moved_many(a, sid, num[2], v[2].leader, so, "by alice off the owner");
    tsdbc_close(a);
    a = login_retry(to, "alice", "alice-pw", 20000);
    if ((rc = tsdbc_insert_series(a, sid, ts, val, 1)) != 0)
        die("alice's write through server %d, moved to south's owner: %s", to, ers(rc));
    tsdbc_close(a);
    a = login_retry(to, "alice", "alice-pw", 20000);
    if ((rc = tsdbc_insert_series(a, sother, ts, val, 1)) != TSDB_ERR_DENIED)
        die("alice's write outside her grant, moved to the owner: %s, not DENIED", ers(rc));
    tsdbc_close(a);
    a = login_retry(R, "alice", "alice-pw", 20000);
    if ((rc = tsdbc_insert_series(a, other, ts, val, 1)) != TSDB_ERR_DENIED)
        die("alice's write to east outside her grant through a replica: %s, not DENIED", ers(rc));
    tsdbc_close(a);
    printf("  a user is moved before her rights are checked, and DENIED at the owner outside her grant\n");

    /* a frame naming volumes led on two servers: INVALID, nothing written */
    int sa = -1, sb = -1;
    tsdb_sid ia = 0, ib = 0;
    if (so != L)
        sa = L, sb = so, ia = id, ib = sid;
    else if (no != L) {
        c = login_retry(no, "root", "root-pw", 0);
        ib = rep_series(c, "plant.n", "north", 30000);
        tsdbc_close(c);
        sa = L, sb = no, ia = id;
    }
    /* placement is the metadata's: when east, south and north are led on one server, more volumes are made until
     * one is led elsewhere (the check never skips itself: review F4) */
    for (int k = 1; sa < 0 && k <= 6; k++) {
        char nm[16];
        uint32_t nn;
        struct meta_volume w;
        snprintf(nm, sizeof nm, "span%d", k);
        if ((rc = vol_add(0, nm, 1, &nn)) != 0)
            die("volume add %s: %s", nm, cluster_strerror(rc));
        if (!vol_rec(0, nm, &w))
            die("no record of %s", nm);
        int ws = server_of(w.leader);
        if (ws < 0)
            die("%s is led by node %u, no server", nm, (unsigned)w.leader);
        await_open_gen(0, nm, ws, 1, 0);
        if (ws != L) {
            c = login_retry(ws, "root", "root-pw", 0);
            ib = rep_series(c, "plant.p", nm, 30000);
            tsdbc_close(c);
            sa = L, sb = ws, ia = id;
        }
    }
    if (sa < 0)
        die("east, south, north and six more volumes are all led on server %d: no spanning check", L);
    {
        tsdb_sid span[2] = {ia, ib};
        int64_t sts[2] = {9000, 9000};
        for (int via = 0; via < 3; via++) {
            c = login_retry(via, "root", "root-pw", 0);
            if ((rc = tsdbc_insert(c, span, sts, val, 2)) != TSDB_ERR_INVALID)
                die("a frame naming volumes led on servers %d and %d, through server %d: %s, not INVALID", sa, sb, via,
                    ers(rc));
            tsdbc_close(c);
        }
        for (int k = 0; k < 2; k++) {
            c = login_retry(k ? sb : sa, "root", "root-pw", 0);
            nrows = 0;
            if ((rc = tsdbc_query_raw(c, span[k], 9000, 9001, count_rows, NULL)) != 0 || nrows != 0)
                die("the refused spanning frame left %d rows on server %d (%s)", nrows, k ? sb : sa, ers(rc));
            tsdbc_close(c);
        }
        printf("  a frame naming volumes led on two servers: INVALID on every server, nothing written\n");
    }
    stop_all();
}

/* forward (S2-2: one hop to the volume's leader). Three servers with login on, strict reads, every server with two
 * workers (--workers 2); east on all three. Through a replica R of east, writes (by id, packed, many-series, a series by
 * path) are applied on east's leader L and every read (raw, buckets, LTTB, TWA, QUERY_MULTI, QUERY_LATEST,
 * STATS_SERIES) answers what L answers, with LAST_STATS from L's tail and the hop counted in R's STATUS; a user's
 * forwarded write is judged by her rights at the owner (DENIED outside her grant); a frame held at the entry past
 * fwd_max_age_ms is UNAVAILABLE and never applied; a forward waiting on a stopped owner leaves R's own volumes served
 * (the wait counts as a waiting worker); a written forward whose link breaks closes the client's connection (unknown
 * outcome), never UNAVAILABLE; a user added while the owner's users lag (TSDB_CLUSTER_TEST hold_users_file) is retried
 * through UNAVAILABLE until the owner has her, never refused AUTH. Through TSDBD_TEST_FWD_KNOBS: a request held at the
 * entry after its parse (j) or at the owner before it runs (k) past fwd_max_age_ms is UNAVAILABLE and never applied; a
 * forward the owner cannot read closes the client's connection at once (l: the owner's unknown outcome, D12); a
 * forward stamped with another epoch than its owner's is refused (n: UNAVAILABLE or MOVED, not applied); a client that leaves while its forward waits has
 * it given up within about a second (m, STATUS fwd.inflight). Mutants (TSDBD_FWD_MUTANT): fwdoldframe, fwdunavonbreak,
 * fwdnouser, fwdnowait, fwdauthlag, fwdarrival, fwdownerage, fwdownerclose, fwdtailclose, fwdepoch, fwdgone. */
static uint64_t fw_fnv(uint64_t h, const void *p, size_t n)
{
    const uint8_t *b = p;
    for (size_t i = 0; i < n; i++)
        h = (h ^ b[i]) * 1099511628211ull;
    return h;
}

struct fw_acc {
    uint64_t h;
    size_t n;
};

static int fw_vals(void *ctx, const int64_t *ts, const tsdb_values *v, size_t n)
{
    struct fw_acc *a = ctx;
    a->h = fw_fnv(a->h, ts, n * sizeof *ts);
    if (v->type == TSDB_FLOAT32)
        a->h = fw_fnv(a->h, v->values, n * sizeof(float));
    a->n += n;
    return 0;
}

static int fw_raw(void *ctx, const int64_t *ts, const float *v, size_t n)
{
    struct fw_acc *a = ctx;
    a->h = fw_fnv(fw_fnv(a->h, ts, n * sizeof *ts), v, n * sizeof *v);
    a->n += n;
    return 0;
}

static int fw_multi(void *ctx, const tsdb_series_result *r)
{
    struct fw_acc *a = ctx;
    if (r->status != 0)
        die("QUERY_MULTI: series %zu answered %s", r->index, ers(r->status));
    a->h = fw_fnv(fw_fnv(a->h, &r->index, sizeof r->index), r->ts, r->n * sizeof *r->ts);
    a->n += r->n;
    return 0;
}

/* every read of ids[0..n) through c, as one line to compare between servers */
static void fw_answers(tsdbc *c, const tsdb_sid *ids, size_t n, char *out, size_t cap, const char *where)
{
    int rc;
    size_t o = 0;
    for (size_t k = 0; k < n; k++) {
        struct fw_acc raw = {14695981039346656037ull, 0}, lt = raw;
        if ((rc = tsdbc_query_raw(c, ids[k], 0, INT64_MAX / 2, fw_raw, &raw)) != 0)
            die("QUERY_RAW %s: %s", where, ers(rc));
        tsdb_query_stats qs;
        if ((rc = tsdbc_last_query_stats(c, &qs)) != 0 || qs.rows != raw.n)
            die("LAST_STATS %s after %zu rows: %s, rows %" PRIu64, where, raw.n, ers(rc), qs.rows);
        tsdb_bucket *b = NULL;
        size_t nb = 0;
        if ((rc = tsdbc_query_agg(c, ids[k], 0, INT64_MAX / 2, 60000, &b, &nb)) != 0)
            die("buckets %s: %s", where, ers(rc));
        uint64_t hb = fw_fnv(14695981039346656037ull, b, nb * sizeof *b);
        free(b);
        if ((rc = tsdbc_query_lttb(c, ids[k], 0, INT64_MAX / 2, 100, fw_vals, &lt)) != 0)
            die("LTTB %s: %s", where, ers(rc));
        tsdb_twa_bucket *t = NULL;
        size_t nt = 0;
        tsdb_twa_opts to = {0};
        if ((rc = tsdbc_query_twa(c, ids[k], 0, 10000000, 600000, &to, &t, &nt)) != 0)
            die("TWA %s: %s", where, ers(rc));
        uint64_t ht = fw_fnv(14695981039346656037ull, t, nt * sizeof *t);
        free(t);
        o += (size_t)snprintf(out + o, o < cap ? cap - o : 0,
                              "[%zu] raw %zu/%016" PRIx64 " buckets %zu/%016" PRIx64 " lttb %zu/%016" PRIx64
                              " twa %zu/%016" PRIx64 "; ",
                              k, raw.n, raw.h, nb, hb, lt.n, lt.h, nt, ht);
    }
    struct fw_acc m = {14695981039346656037ull, 0};
    tsdb_multi_query q = {.kind = TSDB_MULTI_VALUES, .start = 0, .end = INT64_MAX / 2, .opts = {TSDB_ASC, 0}};
    if ((rc = tsdbc_query_multi(c, &q, ids, n, NULL, fw_multi, &m)) != 0)
        die("QUERY_MULTI %s: %s", where, ers(rc));
    tsdb_latest_result lr[8];
    tsdb_series_stat st[8];
    if (n > 8)
        die("fw_answers: %zu ids", n);
    if ((rc = tsdbc_latest(c, ids, n, NULL, lr)) != 0)
        die("QUERY_LATEST %s: %s", where, ers(rc));
    if ((rc = tsdbc_series_stats(c, ids, n, 0, st)) != 0)
        die("STATS_SERIES %s: %s", where, ers(rc));
    o += (size_t)snprintf(out + o, o < cap ? cap - o : 0, "multi %zu/%016" PRIx64 " latest", m.n, m.h);
    for (size_t k = 0; k < n; k++)
        o += (size_t)snprintf(out + o, o < cap ? cap - o : 0, " %d/%" PRId64 "/%g stats %d/%" PRIu64, (int)lr[k].status,
                              lr[k].ts, (double)lr[k].v.f32, (int)st[k].status, st[k].rows);
}

/* the frames forwarded from this server to node `peer` (STATUS peer.<peer>.fwd.frames) */
static uint64_t fw_frames(tsdbc *c, uint32_t peer)
{
    char *text = NULL, key[64];
    int rc = tsdbc_status(c, &text);
    if (rc != 0)
        die("STATUS: %s", ers(rc));
    snprintf(key, sizeof key, "\npeer.%u.fwd.frames=", (unsigned)peer);
    const char *p = strstr(text, key);
    uint64_t n = p ? strtoull(p + strlen(key), NULL, 10) : 0;
    free(text);
    return n;
}

struct fw_write {
    tsdbc *c;
    tsdb_sid id;
    int64_t ts;
    int rc;
    uint64_t ms;
};

static void *fw_write_run(void *arg)
{
    struct fw_write *w = arg;
    float v = 7;
    uint64_t t0 = now_ms();
    w->rc = tsdbc_insert_series(w->c, w->id, &w->ts, &v, 1);
    w->ms = now_ms() - t0;
    return NULL;
}

/* rows of id at ts on server s (through its leader: s is the leader) */
static int fw_has(int s, tsdb_sid id, int64_t ts)
{
    tsdbc *c = login_retry(s, "root", "root-pw", 0);
    nrows = 0;
    int rc = tsdbc_query_raw(c, id, ts, ts + 1, count_rows, NULL);
    if (rc != 0)
        die("read of %" PRId64 " on server %d: %s", ts, s, ers(rc));
    tsdbc_close(c);
    return nrows;
}

/* a value of STATUS on c ("fwd.inflight"); 0 when absent */
static uint64_t fw_stat(tsdbc *c, const char *name)
{
    char *text = NULL, key[96];
    int rc = tsdbc_status(c, &text);
    if (rc != 0)
        die("STATUS: %s", ers(rc));
    snprintf(key, sizeof key, "\n%s=", name);
    const char *p = strstr(text, key);
    uint64_t n = p ? strtoull(p + strlen(key), NULL, 10) : 0;
    free(text);
    return n;
}

/* TSDBD_TEST_FWD_KNOBS (server/tsdbd.c fwd_knob): <base>/fwdknobs/NAME exists while on */
static void fw_knob(const char *name, int on)
{
    char p[PATH_MAX + 80];
    snprintf(p, sizeof p, "%s/fwdknobs", base);
    mkdir(p, 0755);
    snprintf(p, sizeof p, "%s/fwdknobs/%s", base, name);
    if (on) {
        int fd = open(p, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd < 0)
            die("%s: %s", p, strerror(errno));
        close(fd);
    } else if (unlink(p) != 0 && errno != ENOENT) {
        die("unlink %s: %s", p, strerror(errno));
    }
}

/* one write through R held by the knob for 1.5 s: it must be answered UNAVAILABLE and never reach L */
static void fw_held_write(int L, int R, tsdb_sid id, int64_t ts, const char *knob, const char *what)
{
    struct fw_write w = {.c = login_retry(R, "root", "root-pw", 0), .id = id, .ts = ts};
    fw_knob(knob, 1);
    pthread_t th;
    if (pthread_create(&th, NULL, fw_write_run, &w) != 0)
        die("pthread_create");
    usleep(1500000);
    fw_knob(knob, 0);
    pthread_join(th, NULL);
    tsdbc_close(w.c);
    if (w.rc != TSDB_ERR_UNAVAILABLE)
        die("a write held 1.5 s %s: %s, not UNAVAILABLE", what, ers(w.rc));
    usleep(300000);
    if (fw_has(L, id, ts) != 0)
        die("a write held 1.5 s %s and answered UNAVAILABLE was applied on the leader", what);
    printf("  a write held past fwd_max_age_ms %s is UNAVAILABLE and never applied\n", what);
}

static void scen_forward(void)
{
    scenario("forward");
    strict_reads = 1;
    fwd_on = 1;
    const char *mut = getenv("TSDBD_FWD_MUTANT");
    char stall[PATH_MAX + 80];
    snprintf(stall, sizeof stall, "%s/fwd-stall", base);
    static char menv[PATH_MAX * 2 + 400];
    snprintf(menv, sizeof menv, "TSDBD_FWD_MUTANT=%s TSDBD_TEST_FWD_STALL=%s TSDBD_TEST_FWD_KNOBS=%s/fwdknobs",
             mut ? mut : "", stall, base);
    for (int i = 0; i < 3; i++) {
        auth_on[i] = 1;
        penv[i] = menv;
        envs[i] = "hold_users_file=1"; /* part i: <state>/holdusers on the owner makes its users lag */
        xargs[i] = "--workers 2";
        start(i);
    }
    char pw[PATH_MAX + 80], pw2[PATH_MAX + 80], args[PATH_MAX * 2 + 512], out[8192], p0[META_ADDR_MAX];
    put_file("pw", "root-pw", pw, sizeof pw);
    put_file("pw2", "alice-pw", pw2, sizeof pw2);
    peer_of(0, p0, sizeof p0);
    snprintf(args, sizeof args,
             "cluster init %s --secret-file %s --node-timeout-ms 1500 --heartbeat-ms 200 --voter-replace-s 600 "
             "--superuser root --password-file %s",
             p0, secret_path, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("cluster init --superuser root: %s", out);
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    snprintf(args, sizeof args, "cluster user add %s alice --password-file %s --secret-file %s", p0, pw2,
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("user add alice: %s", out);
    for (int i = 0; i < 3; i++) {
        await_view(i, p_users_caught_up, NULL, "users caught up");
        await_login(i, "root", "root-pw");
    }
    uint32_t num;
    struct meta_volume v;
    int rc;
    if ((rc = vol_add(0, "east", 3, &num)) != 0)
        die("volume add east: %s", cluster_strerror(rc));
    if (!vol_rec(0, "east", &v))
        die("no record of east");
    for (uint32_t k = 0; k < v.nrep; k++)
        await_open_gen(0, "east", server_of(v.rep[k].node), 1, 0);
    await_isr(0, "east", 3, 20000, "east with every replica up");
    int L = server_of(v.leader), R = (L + 1) % 3;
    {
        tsdbc *r0 = login_on(0, "root", "root-pw");
        if ((rc = tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ | TSDB_RIGHT_INSERT)) != 0)
            die("grant: %s", ers(rc));
        tsdbc_close(r0);
    }

    /* a. through the replica R: every write lands on L, every read answers L's answer */
    tsdbc *c = login_retry(L, "root", "root-pw", 0);
    tsdb_sid id = rep_series(c, "plant.a", "east", 30000), other = rep_series(c, "other.a", "east", 30000);
    tsdbc_close(c);
    c = login_retry(R, "root", "root-pw", 0); /* budget 0: a MOVED would fail the call */
    uint64_t f0 = fw_frames(c, v.leader);
    tsdb_sid pid;
    if ((rc = tsdbc_series_at(c, "plant.p", "east", &pid)) != 0)
        die("a series by path through the replica: %s", ers(rc));
    enum { NR = 3000 };
    static int64_t ts[NR];
    static float val[NR];
    for (int k = 0; k < NR; k++)
        ts[k] = 1000 + (int64_t)k * 1000, val[k] = (float)(k % 97) * 0.5f;
    if ((rc = tsdbc_insert_series(c, id, ts, val, NR / 2)) != 0)
        die("a write by id through the replica: %s", ers(rc));
    tsdb_sid two[4] = {id, pid, other, id};
    int64_t ts2[4] = {ts[NR / 2], 1000, 1000, ts[NR / 2 + 1]};
    float v2[4] = {1, 2, 3, 4};
    if ((rc = tsdbc_insert(c, two, ts2, v2, 4)) != 0) /* packed */
        die("a packed write through the replica: %s", ers(rc));
    if ((rc = tsdbc_set_compression(c, 0)) != 0)
        die("compression off: %s", ers(rc));
    int64_t ts3[2] = {ts[NR / 2 + 2], 2000};
    tsdb_sid two3[2] = {id, pid};
    if ((rc = tsdbc_insert(c, two3, ts3, v2, 2)) != 0)
        die("an unpacked many-series write through the replica: %s", ers(rc));
    if ((rc = tsdbc_set_compression(c, 1)) != 0)
        die("compression on: %s", ers(rc));
    if ((rc = tsdbc_insert_series(c, id, ts + NR / 2 + 3, val + NR / 2 + 3, NR - NR / 2 - 3)) != 0)
        die("a second write by id through the replica: %s", ers(rc));
    static char ar[4096], al[4096];
    tsdb_sid q3[3] = {id, pid, other};
    fw_answers(c, q3, 3, ar, sizeof ar, "through the replica");
    uint64_t f1 = fw_frames(c, v.leader);
    tsdbc_close(c);
    c = login_retry(L, "root", "root-pw", 0);
    fw_answers(c, q3, 3, al, sizeof al, "on the leader");
    if (rows_of(c, id) != NR)
        die("east's leader holds %d rows of plant.a, not %d", nrows, NR);
    tsdbc_close(c);
    if (strcmp(ar, al) != 0)
        die("the answers through the replica differ from the leader's:\n  R: %s\n  L: %s", ar, al);
    if (f1 < f0 + 10)
        die("STATUS of the replica counts %" PRIu64 " frames forwarded to node %u, not at least 10 more than %" PRIu64,
            f1, (unsigned)v.leader, f0);
    printf("  through a replica: writes by id, packed, many-series and by path land on the leader; raw, buckets, LTTB, "
           "TWA, QUERY_MULTI, QUERY_LATEST and STATS_SERIES answer the leader's answers (%" PRIu64 " frames)\n",
           f1 - f0);

    /* b. a user's forwarded write is judged at the owner by her rights */
    tsdbc *a = login_retry(R, "alice", "alice-pw", 0);
    int64_t tb = 99000000;
    float vb = 1;
    if ((rc = tsdbc_insert_series(a, id, &tb, &vb, 1)) != 0)
        die("alice's write in her grant through the replica: %s", ers(rc));
    if ((rc = tsdbc_insert_series(a, other, &tb, &vb, 1)) != TSDB_ERR_DENIED)
        die("alice's write outside her grant through the replica: %s, not DENIED", ers(rc));
    tsdbc_close(a);
    if (fw_has(L, id, tb) != 1 || fw_has(L, other, tb) != 0)
        die("after alice's writes through the replica the leader holds %d row(s) in her grant and %d outside it",
            fw_has(L, id, tb), fw_has(L, other, tb));
    printf("  a user's write through a replica is applied in her grant and DENIED at the owner outside it\n");

    /* i. a user added while the owner's users lag (its watch held): she logs in on the entry, her forwarded write is
     * UNAVAILABLE (RELOADING) at the owner until it has her, which the client retries, never AUTH (fwdauthlag) */
    {
        char holdu[PATH_MAX + 96], pw3[PATH_MAX + 80];
        server_dir(L, holdu, sizeof holdu);
        strcat(holdu, "/state/holdusers");
        FILE *hu = fopen(holdu, "w");
        if (!hu)
            die("%s: %s", holdu, strerror(errno));
        fclose(hu);
        usleep(300000); /* a round of L's cluster thread: its watch has stopped */
        put_file("pw3", "bob-pw", pw3, sizeof pw3);
        snprintf(args, sizeof args, "cluster user add %s bob --superuser --password-file %s --secret-file %s --wait-ms 200",
                 p0, pw3, secret_path);
        if (cli_run(args, NULL, out, sizeof out) != 0 && !strstr(out, "lag"))
            die("user add bob: %s", out);
        await_login(R, "bob", "bob-pw");
        struct fw_write wb = {.c = login_retry(R, "bob", "bob-pw", 20000), .id = id, .ts = 97000000};
        pthread_t tb2;
        if (pthread_create(&tb2, NULL, fw_write_run, &wb) != 0)
            die("pthread_create");
        usleep(1000000);
        unlink(holdu);
        pthread_join(tb2, NULL);
        tsdbc_close(wb.c);
        if (wb.rc != 0)
            die("bob's write through the replica while the owner's users lagged: %s, not retried until it had him",
                ers(wb.rc));
        if (wb.ms < 800)
            die("bob's write through the replica was answered after %" PRIu64 " ms with the owner's users held 1 s: "
                "the lag was not exercised", wb.ms);
        if (fw_has(L, id, wb.ts) != 1)
            die("bob's write through the replica is not on the leader");
        printf("  a user added while the owner's users lagged: her forwarded write waited %" PRIu64
               " ms (UNAVAILABLE, retried), never AUTH\n", wb.ms);
    }

    /* c. a frame held at the entry past fwd_max_age_ms (1 s): UNAVAILABLE, never applied */
    struct fw_write w = {.c = login_retry(R, "root", "root-pw", 0), .id = id, .ts = 98000000};
    put_file("fwd-stall", "", stall, sizeof stall);
    pthread_t th;
    if (pthread_create(&th, NULL, fw_write_run, &w) != 0)
        die("pthread_create");
    usleep(1500000);
    unlink(stall);
    pthread_join(th, NULL);
    tsdbc_close(w.c);
    if (w.rc != TSDB_ERR_UNAVAILABLE)
        die("a write held 1.5 s at the entry: %s, not UNAVAILABLE", ers(w.rc));
    usleep(300000);
    if (fw_has(L, id, w.ts) != 0)
        die("a write held 1.5 s at the entry and answered UNAVAILABLE was applied on the leader");
    printf("  a write held past fwd_max_age_ms at the entry is UNAVAILABLE and never applied\n");

    /* j. held at the entry after its parse but before its forward is built: the age counts from the parse (a request
     *    that waited for a worker is as old as one that waited for the link) */
    fw_held_write(L, R, id, 98000100, "prestall", "at the entry before its forward began");
    /* k. held at the owner before it runs the forward: the owner's own check (envelope age plus its queue) */
    fw_held_write(L, R, id, 98000200, "ownerstall", "at the owner before it ran the forward");

    /* l. a forward the owner cannot read: the owner answers by closing (unknown outcome, D12), and the entry closes the
     *    client's connection at once instead of leaving it waiting for a reply that never comes */
    {
        struct fw_write wl = {.c = login_retry(R, "root", "root-pw", 0), .id = id, .ts = 98000300};
        tsdbc_set_timeout(wl.c, 8000);
        fw_knob("badenv", 1);
        fw_write_run(&wl);
        fw_knob("badenv", 0);
        tsdbc_close(wl.c);
        if (wl.rc != TSDB_ERR_IO || wl.ms >= 4000)
            die("a forward the owner could not read: %s after %" PRIu64 " ms, not a closed connection at once (IO)",
                ers(wl.rc), wl.ms);
        if (fw_has(L, id, wl.ts) != 0)
            die("a forward the owner could not read was applied");
        printf("  a forward the owner could not read closes the client's connection (%" PRIu64 " ms)\n", wl.ms);
    }

    /* m. a write that reaches the owner on the read link (FWDQ), as a flipped op or kind would with the link's frame
     *    check off (the default): the owner refuses it by ending that connection, so the write is never applied and the
     *    entry closes its client's connection (written and lost) at once; served, it would be acknowledged */
    {
        struct fw_write wm = {.c = login_retry(R, "root", "root-pw", 0), .id = id, .ts = 98000350};
        tsdbc_set_timeout(wm.c, 8000);
        fw_knob("opkind", 1);
        fw_write_run(&wm);
        fw_knob("opkind", 0);
        tsdbc_close(wm.c);
        if (fw_has(L, id, wm.ts) != 0)
            die("a write sent on the read link was applied (%s)", ers(wm.rc));
        if (wm.rc != TSDB_ERR_IO || wm.ms >= 4000)
            die("a write sent on the read link: %s after %" PRIu64 " ms, not a closed connection at once (IO)",
                ers(wm.rc), wm.ms);
        printf("  a write sent on the read link is refused by the owner: the connection closes (%" PRIu64 " ms)\n",
               wm.ms);
    }

    /* m2. the other way: a read that reaches the owner on the write link (FWD) is refused the same way; served, a
     *     flipped op on FWD could make a write look like a read there (review F5: the check one way only) */
    {
        tsdbc *cq = login_retry(R, "root", "root-pw", 0);
        tsdbc_set_timeout(cq, 8000);
        fw_knob("opkind", 1);
        uint64_t t0 = now_ms();
        int rq = tsdbc_query_raw(cq, id, 0, INT64_MAX / 2, count_rows, NULL);
        uint64_t ms = now_ms() - t0;
        fw_knob("opkind", 0);
        tsdbc_close(cq);
        if (rq != TSDB_ERR_IO || ms >= 4000)
            die("a read sent on the write link: %s after %" PRIu64 " ms, not a closed connection at once (IO)",
                ers(rq), ms);
        printf("  a read sent on the write link is refused by the owner: the connection closes (%" PRIu64 " ms)\n", ms);
    }

    /* n. the owner leads at another epoch than the one the entry stamped: refused before anything is done, never run.
     *    The owner's copy names itself, so route_fill answers UNAVAILABLE (MOVED to itself would send the client round in
     *    a circle); an owner whose copy names another leader answers MOVED. Either says "not applied": the client resends
     *    and the entry node routes again. */
    {
        tsdbc *cn = login_retry(R, "root", "root-pw", 0);
        int64_t tn = 98000400;
        float vn = 1;
        fw_knob("epoch", 1);
        rc = tsdbc_insert_series(cn, id, &tn, &vn, 1);
        fw_knob("epoch", 0);
        tsdbc_close(cn);
        if (rc != TSDB_ERR_MOVED && rc != TSDB_ERR_UNAVAILABLE)
            die("a forward stamped with another epoch than its owner's: %s, not MOVED or UNAVAILABLE", ers(rc));
        if (fw_has(L, id, tn) != 0)
            die("a forward stamped with another epoch than its owner's was applied");
        printf("  a forward stamped with another epoch than its owner leads at is %s, never run\n", ers(rc));
    }

    /* m. a client that leaves while its forward waits (the owner holds it): the entry gives the forward up (cancel) in
     *    about a second, not after fwd_reply_ms (30 s) or whenever the owner answers */
    {
        tsdbc *cm = login_retry(R, "root", "root-pw", 0), *sm = login_retry(R, "root", "root-pw", 0);
        tsdbc_set_timeout(cm, 300);
        int64_t tm = 98000500;
        float vm = 1;
        fw_knob("ownerstall", 1);
        rc = tsdbc_insert_series(cm, id, &tm, &vm, 1);
        uint64_t inflight = fw_stat(sm, "fwd.inflight");
        if (inflight != 1) {
            fw_knob("ownerstall", 0);
            die("a forward held at the owner: %" PRIu64 " forwards in flight on the entry, not 1", inflight);
        }
        tsdbc_close(cm);
        uint64_t t0 = now_ms(), gone_ms = 0;
        while ((inflight = fw_stat(sm, "fwd.inflight")) != 0 && now_ms() - t0 < 3000)
            usleep(20000);
        gone_ms = now_ms() - t0;
        uint64_t left = inflight;
        fw_knob("ownerstall", 0);
        tsdbc_close(sm);
        if (rc != TSDB_ERR_IO)
            die("a forward held at the owner past the client's 300 ms timeout: %s, not IO", ers(rc));
        if (left != 0)
            die("a forward whose client left is still in flight on the entry %" PRIu64 " ms later (owner holding it)",
                gone_ms);
        printf("  a forward whose client left is given up %" PRIu64 " ms after the client closed\n", gone_ms);
    }

    /* m3. a client that pipelines past PIPE_CAP (disarming recv on the entry) and then closes while its first
     *     forwarded request is held at the owner: fe_gone must still notice the closed socket within ~1-2 s */
    {
        tsdbc *cm = login_retry(R, "root", "root-pw", 0), *sm = login_retry(R, "root", "root-pw", 0);
        tsdbc_set_compression(cm, 0);
        tsdbc_set_timeout(cm, 300);
        int64_t tm = 98000550;
        float vm = 1;
        size_t pnr = 44000; /* ~528 KB uncompressed per frame; 7 < PIPE_CAP (4 MiB) < 8 (~4.22 MB, 0 unread left) */
        int64_t *pts = malloc(pnr * sizeof *pts);
        float *pvs = malloc(pnr * sizeof *pvs);
        if (!pts || !pvs)
            die("malloc");
        for (size_t i = 0; i < pnr; i++) {
            pts[i] = 98000600 + (int64_t)i;
            pvs[i] = 1.0f;
        }
        fw_knob("ownerstall", 1);
        rc = tsdbc_insert_series_async(cm, id, &tm, &vm, 1);
        if (rc != 0) {
            fw_knob("ownerstall", 0);
            die("pipelined clientgone: first async insert: %s", ers(rc));
        }
        uint64_t w0 = now_ms(), inflight = 0;
        while ((inflight = fw_stat(sm, "fwd.inflight")) != 1 && now_ms() - w0 < 2000)
            usleep(10000);
        if (inflight != 1) {
            fw_knob("ownerstall", 0);
            die("pipelined clientgone: %" PRIu64 " forwards in flight on the entry, not 1", inflight);
        }
        for (int k = 0; k < 8 && rc == 0; k++)
            rc = tsdbc_insert_series_async(cm, id, pts, pvs, pnr);
        if (rc != 0) {
            fw_knob("ownerstall", 0);
            die("pipelined clientgone: pipelining past PIPE_CAP failed: %s", ers(rc));
        }
        usleep(100000); /* let the entry event loop parse past PIPE_CAP and disarm recv */
        rc = tsdbc_wait(cm);
        tsdbc_close(cm);
        free(pts);
        free(pvs);
        uint64_t t0 = now_ms(), gone_ms = 0;
        while ((inflight = fw_stat(sm, "fwd.inflight")) != 0 && now_ms() - t0 < 3000)
            usleep(20000);
        gone_ms = now_ms() - t0;
        uint64_t left = inflight;
        fw_knob("ownerstall", 0);
        tsdbc_close(sm);
        if (rc != TSDB_ERR_IO)
            die("pipelined clientgone: wait past timeout returned %s, not IO", ers(rc));
        if (left != 0)
            die("pipelined clientgone: forward still in flight %" PRIu64 " ms after backpressured client closed",
                gone_ms);
        printf("  a forward whose backpressured (>PIPE_CAP) client left is given up %" PRIu64 " ms after close\n",
               gone_ms);
    }

    /* e. forwards waiting on a stopped owner hold no worker of R: a volume led on R is served at once */
    char solo[16] = "";
    for (int k = 1; k <= 8 && !*solo; k++) {
        char nm[16];
        uint32_t nn;
        struct meta_volume s;
        snprintf(nm, sizeof nm, "solo%d", k);
        if ((rc = vol_add(0, nm, 1, &nn)) != 0)
            die("volume add %s: %s", nm, cluster_strerror(rc));
        if (!vol_rec(0, nm, &s))
            die("no record of %s", nm);
        await_open_gen(0, nm, server_of(s.leader), 1, 0);
        if (server_of(s.leader) == R)
            snprintf(solo, sizeof solo, "%s", nm);
    }
    if (!*solo)
        die("no volume of 8 with one replica is led on server %d", R);
    c = login_retry(R, "root", "root-pw", 0);
    tsdb_sid lid = rep_series(c, "plant.l", solo, 30000);
    struct fw_write hw[2];
    pthread_t ht[2];
    for (int k = 0; k < 2; k++)
        hw[k] = (struct fw_write){.c = login_retry(R, "root", "root-pw", 0), .id = id, .ts = 97000000 + k};
    pause_server(L, 1);
    for (int k = 0; k < 2; k++)
        if (pthread_create(&ht[k], NULL, fw_write_run, &hw[k]) != 0)
            die("pthread_create");
    usleep(200000);
    uint64_t t0 = now_ms();
    int64_t tl = 1000;
    float vl = 1;
    rc = tsdbc_insert_series(c, lid, &tl, &vl, 1);
    uint64_t took = now_ms() - t0;
    usleep(took < 1000 ? (useconds_t)(1000 - took) * 1000 : 0);
    pause_server(L, 0);
    for (int k = 0; k < 2; k++) {
        pthread_join(ht[k], NULL);
        tsdbc_close(hw[k].c);
    }
    tsdbc_close(c);
    if (rc != 0)
        die("a write to %s led on server %d while two forwards wait on the stopped leader of east: %s", solo, R,
            ers(rc));
    if (took > 600)
        die("a write to %s led on server %d took %" PRIu64 " ms while two forwards waited on a stopped owner (--workers 2)",
            solo, R, took);
    printf("  two forwards waiting on a stopped owner leave a volume led on the entry served (%" PRIu64 " ms, --workers 2); "
           "they then answered %s and %s\n",
           took, hw[0].rc ? ers(hw[0].rc) : "OK", hw[1].rc ? ers(hw[1].rc) : "OK");

    /* d. a forward written to an owner that dies before it answers: the client's connection is closed (the outcome is
     * unknown), never UNAVAILABLE (which says nothing was applied) */
    await_isr(0, "east", 3, 20000, "east with every replica up again");
    if (!vol_rec(0, "east", &v))
        die("no record of east");
    L = server_of(v.leader), R = (L + 1) % 3;
    w = (struct fw_write){.c = login_retry(R, "root", "root-pw", 0), .id = id, .ts = 96000000};
    pause_server(L, 1);
    if (pthread_create(&th, NULL, fw_write_run, &w) != 0)
        die("pthread_create");
    usleep(300000);
    signal_child(pids[L], SIGKILL); /* never SIGCONT first: the owner must not answer */
    int st;
    if (waitpid(pids[L], &st, 0) != pids[L])
        die("waitpid %d: %s", (int)pids[L], strerror(errno));
    pids[L] = 0, stopped[L] = 0;
    pthread_join(th, NULL);
    tsdbc_close(w.c);
    if (w.rc != TSDB_ERR_IO)
        die("a forwarded write whose owner was killed before it answered: %s after %" PRIu64 " ms, not a closed "
            "connection (IO)",
            ers(w.rc), w.ms);
    printf("  a forwarded write whose owner died before it answered closes the client's connection (%" PRIu64
           " ms)\n",
           w.ms);
}

/* fwdseries (S2-2, found by r4-move): series and state codes looked up and created by path through members that
 * do not lead the volume, with replica reads on (TSDB_REPLICA_READS=1, this file's default: REPLICA_OK). A SERIES or
 * STATE whose `create` byte is set is a write: it goes to the leader like an INSERT, forwarded in one hop. It was judged
 * a read by its need alone (any right), so a replica serving reads ran it on its own engine, which refused to create
 * (READONLY), and the client got MOVED. Three servers with login on; east on two of them (leader L, replica R), the
 * third (N) holds no copy. Through R and N with a retry budget of 0 (a MOVED fails the call): tsdbc_series_at creates
 * and finds again, tsdbc_series_create creates a state series, tsdbc_state creates a code; the ids and codes are the
 * leader's. R's plain lookup by name finds the id from its copy. alice (prefix grant plant.) is NOTFOUND for a missing
 * name inside her grant, then creates it through the same member, and is DENIED outside it. Mutant (TSDBD_FWD_MUTANT):
 * fwdcreateread (a create judged a read). fwdseriesstrict runs the same with strict reads (production: every read of a
 * volume led elsewhere is forwarded, so creates were forwarded there before the fix too), R's plain lookup left out. */
static void fwdseries_run(int strict)
{
    scenario(strict ? "fwdseriesstrict" : "fwdseries");
    fwd_on = 1;
    strict_reads = strict; /* 0: replicas with a lease serve reads; 1: every read on the leader (D5), as in production */
    const char *mut = getenv("TSDBD_FWD_MUTANT");
    static char menv[128];
    snprintf(menv, sizeof menv, "TSDBD_FWD_MUTANT=%s", mut ? mut : "");
    for (int i = 0; i < 3; i++) {
        auth_on[i] = 1;
        penv[i] = menv;
        start(i);
    }
    char pw[PATH_MAX + 80], pw2[PATH_MAX + 80], args[PATH_MAX * 2 + 512], out[8192], p0[META_ADDR_MAX];
    put_file("pw", "root-pw", pw, sizeof pw);
    put_file("pw2", "alice-pw", pw2, sizeof pw2);
    peer_of(0, p0, sizeof p0);
    snprintf(args, sizeof args,
             "cluster init %s --secret-file %s --node-timeout-ms 1500 --heartbeat-ms 200 --voter-replace-s 600 "
             "--superuser root --password-file %s",
             p0, secret_path, pw);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("cluster init --superuser root: %s", out);
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    snprintf(args, sizeof args, "cluster user add %s alice --password-file %s --secret-file %s", p0, pw2,
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("user add alice: %s", out);
    for (int i = 0; i < 3; i++) {
        await_view(i, p_users_caught_up, NULL, "users caught up");
        await_login(i, "root", "root-pw");
    }
    uint32_t num;
    struct meta_volume v;
    int rc;
    if ((rc = vol_add(0, "east", 2, &num)) != 0)
        die("volume add east: %s", cluster_strerror(rc));
    if (!vol_rec(0, "east", &v) || v.nrep != 2)
        die("no record of east with two replicas");
    for (uint32_t k = 0; k < v.nrep; k++)
        await_open_gen(0, "east", server_of(v.rep[k].node), 1, 0);
    await_isr(0, "east", 2, 20000, "east with both replicas up");
    int L = server_of(v.leader), R = server_of(v.rep[0].node == v.leader ? v.rep[1].node : v.rep[0].node),
        O = 3 - L - R; /* the member without a copy */
    {
        tsdbc *r0 = login_on(0, "root", "root-pw");
        if ((rc = tsdbc_grant(r0, "alice", TSDB_SEL_PREFIX, "plant.", TSDB_RIGHT_READ | TSDB_RIGHT_INSERT)) != 0)
            die("grant: %s", ers(rc));
        tsdbc_close(r0);
    }
    for (int i = 0; i < 3; i++)
        await_view(i, p_users_caught_up, NULL, "users caught up after the grant");
    { /* east's leader writes (its first write may be UNAVAILABLE while the volume opens, retried here) */
        tsdbc *c = login_retry(L, "root", "root-pw", 0);
        rep_series(c, "plant.warm", "east", 30000);
        tsdbc_close(c);
    }

    /* a. root through the replica R and through N: creates by path and finds again; a state series and a code */
    static const char *const ename[2] = {"replica", "member without a copy"};
    int ent[2] = {R, O};
    tsdb_sid sid[2], stid[2];
    uint32_t code[2];
    for (int e = 0; e < 2; e++) {
        tsdbc *c = login_retry(ent[e], "root", "root-pw", 0); /* budget 0: a MOVED fails the call */
        char nm[64], st[64];
        snprintf(nm, sizeof nm, "plant.via%d", e);
        snprintf(st, sizeof st, "plant.mode%d", e);
        tsdb_sid again = 0;
        if ((rc = tsdbc_series_at(c, nm, "east", &sid[e])) != 0)
            die("a series created by path through the %s: %s, not its id", ename[e], ers(rc));
        if ((rc = tsdbc_series_at(c, nm, "east", &again)) != 0 || again != sid[e])
            die("the series found again by path through the %s: %s, id %" PRIu64 " not %" PRIu64, ename[e], ers(rc),
                (uint64_t)again, (uint64_t)sid[e]);
        if ((rc = tsdbc_series_create(c, st, TSDB_STATE, "east", &stid[e])) != 0)
            die("a state series created (SERIES_CREATE) through the %s: %s", ename[e], ers(rc));
        if ((rc = tsdbc_state(c, stid[e], "running", &code[e])) != 0)
            die("a state code created through the %s: %s, not its code", ename[e], ers(rc));
        tsdbc_close(c);
    }
    {
        tsdbc *c = login_retry(L, "root", "root-pw", 0);
        for (int e = 0; e < 2; e++) {
            char nm[64], st[64];
            snprintf(nm, sizeof nm, "plant.via%d", e);
            snprintf(st, sizeof st, "plant.mode%d", e);
            tsdb_sid id = 0, sx = 0;
            uint32_t cx = 0;
            if ((rc = tsdbc_series_at(c, nm, "east", &id)) != 0 || id != sid[e])
                die("on the leader %s is %s, id %" PRIu64 ", not the id %" PRIu64 " made through the %s", nm, ers(rc),
                    (uint64_t)id, (uint64_t)sid[e], ename[e]);
            if ((rc = tsdbc_series_at(c, st, "east", &sx)) != 0 || sx != stid[e])
                die("on the leader %s is %s, id %" PRIu64 ", not the id %" PRIu64 " made through the %s", st, ers(rc),
                    (uint64_t)sx, (uint64_t)stid[e], ename[e]);
            if ((rc = tsdbc_state_lookup(c, stid[e], "running", &cx)) != 0 || cx != code[e])
                die("on the leader the code of running is %s, %u, not the %u made through the %s", ers(rc),
                    (unsigned)cx, (unsigned)code[e], ename[e]);
        }
        tsdbc_close(c);
    }
    if (!strict) { /* a plain lookup by name on R: served from its copy (REPLICA_OK), once it has applied the creation */
        tsdbc *c = login_retry(R, "root", "root-pw", 0);
        uint64_t t0 = now_ms();
        tsdb_sid id = 0;
        while ((rc = tsdbc_series(c, "plant.via0", 0, &id)) == TSDB_ERR_NOTFOUND && now_ms() - t0 < 20000)
            nanosleep(&(struct timespec){0, 20000000}, NULL);
        if (rc != 0 || id != sid[0])
            die("a lookup by name on the replica: %s, id %" PRIu64 ", not %" PRIu64, ers(rc), (uint64_t)id,
                (uint64_t)sid[0]);
        tsdbc_close(c);
    }
    printf("  through a replica and a member without a copy: series by path and state codes are created on the "
           "leader and found again, with the leader's ids and codes\n");

    /* b. alice: NOTFOUND inside her grant, then created through the same member; DENIED outside it */
    for (int e = 0; e < 2; e++) {
        tsdbc *a = login_retry(ent[e], "alice", "alice-pw", 0);
        char nm[64], on[64];
        snprintf(nm, sizeof nm, "plant.alice%d", e);
        snprintf(on, sizeof on, "other.alice%d", e);
        tsdb_sid id = 0, lid = 0;
        /* no client call sends a path with create 0: this lookup names no volume (TSDB_VOL_ANY) and is answered by
         * the member itself, from the volumes it holds (none of east on N) */
        if ((rc = tsdbc_series(a, nm, 0, &id)) != TSDB_ERR_NOTFOUND)
            die("alice's lookup of a missing name in her grant through the %s: %s, not NOTFOUND", ename[e], ers(rc));
        if ((rc = tsdbc_series_at(a, nm, "east", &id)) != 0)
            die("alice's series created by path in her grant through the %s: %s", ename[e], ers(rc));
        if ((rc = tsdbc_series_at(a, on, "east", &(tsdb_sid){0})) != TSDB_ERR_DENIED)
            die("alice's series created by path outside her grant through the %s: %s, not DENIED", ename[e], ers(rc));
        tsdbc_close(a);
        tsdbc *c = login_retry(L, "root", "root-pw", 0);
        if ((rc = tsdbc_series_at(c, nm, "east", &lid)) != 0 || lid != id)
            die("on the leader alice's %s is %s, id %" PRIu64 ", not %" PRIu64, nm, ers(rc), (uint64_t)lid,
                (uint64_t)id);
        tsdbc_close(c);
    }
    printf("  alice through both: NOTFOUND in her grant (a lookup by name only, served here), then created there by path "
           "with the leader's id; DENIED outside it\n");
}
static void scen_fwdseries(void) { fwdseries_run(0); }
static void scen_fwdseries_strict(void) { fwdseries_run(1); }

/* ccstress: the copy's get/put/swap in-process (cluster_copy_stress, no server): 32 readers loop get/put while 5,000
 * snapshots are swapped in. The writer must get through (one counter for every reader starved it for good: mutant
 * cconeslot), and no reader may see its snapshot change or freed (ccnowait; ASan names the use after free). */
static void scen_ccstress(void)
{
    scenario("ccstress");
    char why[256];
    int rc = cluster_copy_stress(32, 5000, 30000, why, sizeof why);
    if (rc != 0)
        die("the copy's get/put/swap under load: %s", why);
    printf("  the copy's get/put/swap under load: %s\n", why);
}

/* copyhold: a reader that holds a snapshot of the copy while 50 more are published keeps what it held (the
 * cluster thread frees a snapshot only at its last reference); mutant snapfreeheld */
static void scen_copyhold(void)
{
    scenario("copyhold");
    strict_reads = 1; /* a replica moves reads to the leader (D5), as in production */
    envs[0] = "copy_hold=50";
    start(0);
    init_cluster(0, 600);
    tsdbc *c = client(0);
    uint64_t t0 = now_ms();
    while (!log_has(0, "copy hold: intact") && !log_has(0, "copy hold: FAILED")) {
        tsdbc_topo *t = NULL; /* readers beside it */
        int rc = tsdbc_topology(c, &t);
        if (rc == 0)
            tsdbc_topology_free(t);
        else if (rc != TSDB_ERR_UNAVAILABLE)
            die("TOPOLOGY beside the hold: %s", ers(rc));
        if (await_exit(0, 0) >= 0)
            die("the server exited while a reader held a snapshot");
        if (now_ms() - t0 > 60000)
            die("no verdict of the hold check in 60 s");
        usleep(20000);
    }
    tsdbc_close(c);
    if (log_has(0, "copy hold: FAILED") || log_has(0, "copy: a snapshot"))
        die("the held snapshot changed or a reference went wrong (see %s/n0.log)", base);
    stop_all();
    printf("  a snapshot held across 50 published ones is unchanged\n");
}

/* minisr: with min_isr 3, a leader whose ISR shrank to 2 refuses a write before anything is written (REPL_E_ISR:
 * UNAVAILABLE, WHY UNREACHABLE), serves reads (a STATE of a name that has its code too, although its create byte is
 * set), and takes writes again once the replica is back in the ISR (mutant nominisr). A write admitted while the ISR was 3 whose commit point comes only after the shrink is not acknowledged
 * until the ISR is back (mutant ackbelowminisr). The second kill happens while nothing is written: a silent member
 * goes after isr_lag (repl.c MUT(40)). With three nodes min_isr 3 stands for "two of three replicas down": two down
 * would take the metadata group's quorum, and with it every ISR change. */
static void scen_minisr(void)
{
    scenario("minisr");
    init_min_isr = 3;
    for (int i = 0; i < 3; i++) {
        envs[i] = "hold_isr_file=1";
        start(i);
    }
    init_cluster(0, 600);
    init_min_isr = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v = {0};
    if (!vol_rec(0, "plant", &v) || v.min_isr != 3)
        die("plant has no record or min_isr %" PRIu32 ", not 3", v.min_isr);
    int L = server_of(v.leader);
    tsdbc *c = client(L);
    tsdbc_set_retry(c, 0);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    ts = 2000;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a second write with every replica up: %s", ers(rc));
    tsdb_sid stid = 0; /* a state code made now, asked for again below min_isr */
    uint32_t code = 0;
    if ((rc = tsdbc_series_create(c, "plant.mode", TSDB_STATE, "plant", &stid)) != 0)
        die("a state series with every replica up: %s", ers(rc));
    if ((rc = tsdbc_state(c, stid, "running", &code)) != 0)
        die("a state code with every replica up: %s", ers(rc));
    await_isr(0, "plant", 3, 5000, "every replica up");
    int R1 = (L + 1) % 3;
    /* a write admitted with the ISR at 3, its commit point reached only once the shrink to 2 committed: held */
    hold_isr(1);
    stop(R1, SIGKILL);
    struct rep_writer w = {cports[L], id, 2500, 1, 0, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0)
        die("pthread_create");
    struct timespec s2 = {2, 0};
    nanosleep(&s2, NULL);
    hold_isr(0);
    await_isr(0, "plant", 2, 10000, "a replica killed");
    uint64_t tw = now_ms();
    while (!log_has(L, "below min_isr 3: writes are refused")) {
        if (now_ms() - tw > 5000)
            die("the leader never said that its ISR is below min_isr");
        nanosleep(&(struct timespec){0, 20000000}, NULL);
    }
    nanosleep(&s2, NULL);
    if (__atomic_load_n(&w.done, __ATOMIC_ACQUIRE))
        die("a write committed only after the ISR shrank below min_isr was answered (rc %d)", w.rc);
    for (int j = 0; j < 5; j++) {
        uint64_t t0 = now_ms();
        ts = 3000 + 1000LL * j;
        rc = tsdbc_insert_series(c, id, &ts, &val, 1);
        if (rc != TSDB_ERR_UNAVAILABLE)
            die("a write below min_isr was answered %d (%s), not UNAVAILABLE", rc, ers(rc));
        if (now_ms() - t0 > 1000)
            die("a write below min_isr took %" PRIu64 " ms to be refused", now_ms() - t0);
        tsdb_unavail u[4];
        unsigned nu = 0;
        if (tsdbc_unavailable(c, u, 4, &nu) != 0 || nu < 1 || u[0].reason == TSDB_WHY_NONE)
            die("a write below min_isr was refused without a reason (%u entries)", nu);
        if (u[0].reason != TSDB_WHY_UNREACHABLE)
            die("a write below min_isr was refused with reason %u, not UNREACHABLE", u[0].reason);
    }
    if (rows_of(c, id) != 2)
        die("the leader reads %d rows after the refused writes, not 2", rows_of(c, id));
    { /* tsdbc_state always sends create = 1: for a name that has its code it is a read, served (fwd-series review) */
        uint32_t again = 0;
        if ((rc = tsdbc_state(c, stid, "running", &again)) != 0 || again != code)
            die("the code of an existing state name below min_isr: %s, %u, not %u (a STATE that creates nothing is a "
                "read)", ers(rc), (unsigned)again, (unsigned)code);
    }
    start(R1);
    await_isr(0, "plant", 3, 30000, "the replica back");
    await_writer(&w, th, 10000, "the write held below min_isr, once the replica is back");
    ts = 9000;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write once the replicas are back: %s", ers(rc));
    if (rows_of(c, id) != 4)
        die("the leader reads %d rows, not 4 (a refused write was written)", rows_of(c, id));
    tsdbc_close(c);
    stop_all();
    for (int i = 0; i < 3; i++)
        envs[i] = NULL;
    uint64_t wantr[REP_NAMES] = {4, 0, 0, 0};
    rep_same(wantr, "after a clean stop");
    printf("  below min_isr a write is refused at once with a reason and nothing written, one committed only after the"
           " shrink waits for the ISR to grow; above it writes go on\n");
}

/* closegone (a leader's shutdown with its replicas gone): an orphaned tsdbd once logged "shutting down" as the leader of
 * a volume whose replicas had stopped and then sat for hours in futex waits. A close must not wait for a commit point
 * that cannot move: tsdbd deposes the leader (repld_stop, eng_close) and the rows above the commit point stay in the
 * WAL for the next epoch. SIGTERM ends the leader in bounded time with nothing above its commit point, and with a write
 * waiting there (its replicas stopped before they acknowledged it, then killed; two of three voters gone, so no ISR
 * change can commit). --exit-with-parent stops a server the same way (it sets `stopping` as SIGTERM does). The write
 * is answered with an error; every directory opens afterwards, the replicas without the row. */
static int term_within(int i, int ms, const char *what)
{
    uint64_t t0 = now_ms();
    signal_child(pids[i], SIGTERM);
    int st = await_exit(i, ms);
    if (st < 0)
        die("%s: server %d still runs %d ms after SIGTERM (its close waits for a commit point that cannot move)", what,
            i, ms);
    if (st != 0)
        die("%s: server %d exited with status %d on SIGTERM, not 0", what, i, st);
    stopped[i] = 0;
    return (int)(now_ms() - t0);
}

/* a cluster of three in its own directory with volume plant on all of them, two rows written and the ISR full; the
 * leader's index. (A scenario never restarts all three: every restart takes new ports, and no server would know where
 * another one is.) */
static int closegone_setup(const char *name, const char *env, tsdb_sid *id)
{
    scenario(name);
    for (int i = 0; i < 3; i++) {
        penv[i] = env;
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdbc_set_retry(c, 0);
    tsdbc_set_timeout(c, 20000); /* a commit point that never moves (writersync's mutant) fails, never hangs, the test */
    *id = rep_series(c, rep_names[0], "plant", 30000);
    float val = 1;
    for (int64_t ts = 1000; ts <= 2000; ts += 1000)
        if ((rc = tsdbc_insert_series(c, *id, &ts, &val, 1)) != 0)
            die("a write with every replica up: %s", ers(rc));
    await_isr(0, "plant", 3, 5000, "every replica up");
    tsdbc_close(c);
    return L;
}

/* What a volume directory's WAL is: its segments' names and sizes (order-free), and their bytes. A stopped server writes
 * nothing, so these do not change between its pause and its SIGKILL. */
static uint64_t wal_print(const char *vd, uint64_t *bytes)
{
    uint64_t h = 0;
    *bytes = 0;
    DIR *d = opendir(vd);
    if (!d)
        die("opendir %s: %s", vd, strerror(errno));
    struct dirent *e;
    while ((e = readdir(d))) {
        if (strncmp(e->d_name, "wal_", 4) != 0)
            continue;
        char p[PATH_MAX + 400];
        struct stat st;
        snprintf(p, sizeof p, "%s/%s", vd, e->d_name);
        if (stat(p, &st) != 0)
            die("stat %s: %s", p, strerror(errno));
        uint64_t f = 1469598103934665603ULL;
        for (const char *c = e->d_name; *c; c++)
            f = (f ^ (unsigned char)*c) * 1099511628211ULL;
        h += (f ^ (uint64_t)st.st_size) * 0x9e3779b97f4a7c15ULL;
        *bytes += (uint64_t)st.st_size;
    }
    closedir(d);
    return h;
}

static void scen_closegone(void)
{
    tsdb_sid id;
    /* 1: both replicas stopped cleanly, nothing above the leader's commit point */
    int L = closegone_setup("closegone", NULL, &id);
    stop((L + 1) % 3, SIGTERM);
    stop((L + 2) % 3, SIGTERM);
    int ms1 = term_within(L, 15000, "the leader with its replicas stopped, nothing above its commit point");

    /* 2: a write waits above the commit point: the replicas are stopped (SIGSTOP) before they acknowledge it */
    L = closegone_setup("closegone-above", NULL, &id);
    pause_server((L + 1) % 3, 1);
    pause_server((L + 2) % 3, 1);
    /* the replicas' WAL once both pauses returned: should a replica still log the write, that names the cause (the
     * pause was no stop yet), not "holds 3 rows" below */
    uint64_t wh[3] = {0}, wb[3] = {0};
    for (int r = 0; r < 3; r++)
        if (r != L) {
            char dir[PATH_MAX + 80], vd[PATH_MAX + 120];
            server_dir(r, dir, sizeof dir);
            snprintf(vd, sizeof vd, "%s/v1", dir);
            wh[r] = wal_print(vd, &wb[r]);
        }
    struct rep_writer w = {cports[L], id, 3000, 1, 0, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0)
        die("pthread_create");
    nanosleep(&(struct timespec){1, 500000000}, NULL);
    if (__atomic_load_n(&w.done, __ATOMIC_ACQUIRE))
        die("a write with both replicas stopped was answered (%s): nothing waits above the commit point", ers(w.rc));
    for (int r = 0; r < 3; r++) {
        if (r == L)
            continue;
        signal_child(pids[r], SIGKILL); /* a stopped process dies of SIGKILL without running again */
        int st;
        if (waitpid(pids[r], &st, 0) != pids[r])
            die("waitpid %d: %s", (int)pids[r], strerror(errno));
        pids[r] = 0;
        stopped[r] = 0;
        char dir[PATH_MAX + 80], vd[PATH_MAX + 120];
        server_dir(r, dir, sizeof dir);
        snprintf(vd, sizeof vd, "%s/v1", dir);
        uint64_t b, hh = wal_print(vd, &b);
        if (hh != wh[r])
            die("server %d (a replica) wrote its WAL after its pause returned (%" PRIu64 " -> %" PRIu64 " bytes)", r,
                wb[r], b);
    }
    int ms2 = term_within(L, 15000, "the leader with a write above its commit point and its replicas killed");
    uint64_t tw = now_ms();
    while (!__atomic_load_n(&w.done, __ATOMIC_ACQUIRE)) {
        if (now_ms() - tw > 5000)
            die("the write above the commit point got no answer after its server stopped");
        nanosleep(&(struct timespec){0, 10000000}, NULL);
    }
    pthread_join(th, NULL);
    if (w.rc == 0)
        die("a write no replica acknowledged was answered as written");
    /* every directory opens; the replicas never saw the row, the leader's WAL may keep it for the next epoch */
    uint64_t lrows = 0;
    for (int i = 0; i < 3; i++) {
        char dir[PATH_MAX + 80], vd[PATH_MAX + 120];
        server_dir(i, dir, sizeof dir);
        snprintf(vd, sizeof vd, "%s/v1", dir);
        uint64_t rows[REP_NAMES], h[REP_NAMES];
        int rc = cvol_digest(vd, rep_names, REP_NAMES, rows, h);
        if (rc != 0)
            die("open %s read-only after the stop: %s", vd, ers(rc));
        if (i == L ? rows[0] < 2 || rows[0] > 3 : rows[0] != 2)
            die("server %d (%s) holds %" PRIu64 " rows after the stop", i, i == L ? "the leader" : "a replica",
                rows[0]);
        if (i == L)
            lrows = rows[0];
    }

    /* 3: the engine writes after the driver stopped (a record admitted before the depose, a NOW marker while the
     * read lease lasts): latewal keeps the leader in place 2.5 s past the freeing of the links and lets the stopped
     * driver admit records whatever its lease, so the flusher's NOW markers (one a second from the moment the volume
     * is led, mutant lateclock: only from its first SAVE as a writer, after this test's SIGTERM) come through the WAL
     * hooks. They used to send on the freed links (a use after free: status 139 or an ASan report). The leader's log
     * says that the hooks ran after the stop, or this case proved nothing. */
    L = closegone_setup("closegone-late", "TSDB_REPLD_TEST=latewal", &id);
    int ms3 = term_within(L, 15000, "the leader writing NOW markers after its driver stopped");
    if (!log_has(L, "after its driver stopped"))
        die("closegone-late: the leader wrote no WAL record after its driver stopped (no NOW marker in 2.5 s: is its "
            "clock started when it begins to lead?)");
    for (int i = 0; i < 3; i++)
        penv[i] = NULL;
    printf("  a leader whose replicas are gone stops on SIGTERM in %d ms (nothing above its commit point) and %d ms (a"
           " write waiting there, answered %s; its directory reads %" PRIu64 " rows); its WAL written after the driver"
           " stopped, in %d ms\n",
           ms1, ms2, ers(w.rc), lrows, ms3);
}

/* writersync: the writer's SYNC actions against its engine's own reports of a durable WAL. With concurrent writes the
 * engine's group sync covers more than the SYNC in flight was issued for; the core caps what it is told at that SYNC's
 * end and issues another, which the driver once answered only when the WAL had moved past its last report: it had
 * not, so the core's durable end, and the commit point, stayed behind a durable WAL until a later record (backpressure
 * hung there after its last write, its flusher waiting; mutant syncbyrep). Batches of eight connections writing single
 * rows: at the end of a batch, or once every writer waits, nothing moves the WAL, since noclock turns the NOW markers
 * and the idle seal off. The leader's log says the overtaking happened, or this case proved nothing. syncbyhook makes
 * the driver answer a SYNC from what op_synced reported, never from a fresh read of the engine (which used to rescue
 * the old code whenever the engine had synced again before op_synced ran), and synclate holds every other report of
 * op_synced back to the driver's next tick, so that the report after it covers records written behind the SYNC in
 * flight: the overtaking happens in the first batch, and under syncbyrep the core's durable end lags one report behind
 * for good, which leaves the last write of a batch unanswered. */
static void scen_writersync(void)
{
    tsdb_sid id;
    int L = closegone_setup("writersync", "TSDB_REPLD_TEST=noclock,syncbyhook,synclate", &id);
    enum { CONNS = 8, BATCHES = 10, MAX_BATCHES = 100, WRITES = 20 };
    struct rep_writer w[CONNS];
    pthread_t th[CONNS];
    rep_timeout_ms = 5000;
    uint64_t t0 = now_ms();
    int b, seen = 0, seen_at = -1;
    /* BATCHES at least, on until the overtaking was seen (synclate makes it happen in the first), and two batches past it */
    for (b = 0; b < MAX_BATCHES && (b < BATCHES || !seen || b <= seen_at + 2); b++) {
        for (int k = 0; k < CONNS; k++) {
            w[k] = (struct rep_writer){cports[L], id, 100000000LL * (b * CONNS + k + 1), WRITES, 0, 0, 0, 0};
            if (pthread_create(&th[k], NULL, rep_write_thread, &w[k]) != 0)
                die("pthread_create");
        }
        for (int k = 0; k < CONNS; k++)
            pthread_join(th[k], NULL);
        for (int k = 0; k < CONNS; k++)
            if (w[k].rc != 0)
                die("writersync: batch %d, a write from connection %d: %s (its commit point stayed below the "
                    "leader's durable WAL?)", b, k, ers(w[k].rc));
        if (!seen && (seen = log_has(L, "an engine sync went past the SYNC in flight")))
            seen_at = b;
    }
    uint64_t ms = now_ms() - t0;
    rep_timeout_ms = 0;
    if (!seen)
        die("writersync: no engine sync went past a SYNC in flight in %d batches (the case proved nothing)", b);
    tsdbc *c = client(L);
    int n = rows_of(c, id);
    tsdbc_close(c);
    if (n != 2 + CONNS * b * WRITES)
        die("writersync: the leader reads %d rows, not %d", n, 2 + CONNS * b * WRITES);
    stop_all();
    for (int i = 0; i < 3; i++)
        penv[i] = NULL;
    printf("  %d batches of %d connections x %d single-row writes in %" PRIu64 " ms, the engine's syncs overtaking the"
           " SYNC in flight first in batch %d\n", b, CONNS, WRITES, ms, seen_at);
}

/* the WAL segments in server i's directory of volume num */
static int wal_count(int i, uint32_t num)
{
    char dir[PATH_MAX + 80], v[PATH_MAX + 120];
    server_dir(i, dir, sizeof dir);
    snprintf(v, sizeof v, "%s/v%" PRIu32, dir, num);
    DIR *d = opendir(v);
    if (!d)
        die("opendir %s: %s", v, strerror(errno));
    int n = 0;
    errno = 0;
    for (struct dirent *e; (e = readdir(d));)
        n += !strncmp(e->d_name, "wal_", 4);
    if (errno)
        die("readdir %s: %s", v, strerror(errno));
    closedir(d);
    return n;
}

/* the bytes of the WAL segments in server i's directory of volume num (the transfer's kept-segment preload) */
static uint64_t wal_bytes(int i, uint32_t num)
{
    char dir[PATH_MAX + 80], v[PATH_MAX + 120], f[PATH_MAX + 400];
    server_dir(i, dir, sizeof dir);
    snprintf(v, sizeof v, "%s/v%" PRIu32, dir, num);
    DIR *d = opendir(v);
    if (!d)
        die("opendir %s: %s", v, strerror(errno));
    uint64_t n = 0;
    errno = 0;
    for (struct dirent *e; (e = readdir(d));) {
        struct stat st;
        snprintf(f, sizeof f, "%s/%s", v, e->d_name);
        if (!strncmp(e->d_name, "wal_", 4) && stat(f, &st) == 0)
            n += (uint64_t)st.st_size;
    }
    if (errno)
        die("readdir %s: %s", v, strerror(errno));
    closedir(d);
    return n;
}

/* A writer of 1000-row inserts on one connection until `stop` (inboxshared's stalled volume) */
struct flood {
    int port;
    tsdb_sid id;
    int stop, rc, rounds;
};
static void *flood_thread(void *a)
{
    struct flood *f = a;
    while (!__atomic_load_n(&f->stop, __ATOMIC_ACQUIRE)) {
        struct rep_writer w = {f->port, f->id, 1000000000LL * (__atomic_load_n(&f->rounds, __ATOMIC_RELAXED) + 1), 0, 0,
                               0, 1000, 0};
        rep_write_thread(&w);
        if (w.rc != 0) {
            __atomic_store_n(&f->rc, w.rc, __ATOMIC_RELEASE);
            break;
        }
        __atomic_add_fetch(&f->rounds, 1, __ATOMIC_RELEASE); /* rejoin reads it while this runs */
#if defined(__SANITIZE_THREAD__)
        /* Under TSan the catch-up of a restarted replica is slowed several times more than a client's write into a
         * tmpfs: two writers of 1000-row inserts outran it, and rejoinsteady's learner never got close enough to join
         * in 30 s, with the old tick rule as with the new (2026-11-18, /tmp a tmpfs: 2 of 3 and 1 of 3 runs). The
         * writes still never pause; they come at most 100 a second per writer. */
        nanosleep(&(struct timespec){0, 10000000}, NULL);
#endif
    }
    return NULL;
}

/* inboxshared (r3d-isr review H1): one data link carries every volume between two nodes, and its frames are handed
 * to the volumes' inboxes on the link's one thread. A volume whose inbox is full and stays so (its disk stuck: here
 * TSDB_REPLD_TEST=stallinbox with <dir>/stallinbox.<number>) must not hold that thread: the other volume, led by the
 * same node, keeps the stalled node in its ISR and its single-row writes answer as fast as before. The thread used to
 * wait 500 ms for every frame of the full volume (mutant inboxwaitall), and its leader's resends kept it asleep. */
static void scen_inboxshared(void)
{
    scenario("inboxshared");
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=smallinbox,stallinbox";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    /* two volumes with the same leader: of four, two share one of the three nodes */
    static const char *const names[] = {"va", "vb", "vc", "vd"};
    uint32_t num[4];
    int lead[4], A = -1, B = -1;
    for (int k = 0; k < 4 && B < 0; k++) {
        int rc = vol_add(0, names[k], 3, &num[k]);
        if (rc != 0)
            die("volume add %s: %s", names[k], cluster_strerror(rc));
        for (int i = 0; i < 3; i++)
            await_open_gen(0, names[k], i, 1, 0);
        struct meta_volume v;
        if (!vol_rec(0, names[k], &v))
            die("no record of %s", names[k]);
        lead[k] = server_of(v.leader);
        for (int j = 0; j < k && B < 0; j++)
            if (lead[j] == lead[k])
                A = j, B = k;
    }
    if (B < 0)
        die("inboxshared: no two of four volumes have one leader");
    int L = lead[A], R = (L + 1) % 3;
    if (L < 0 || L > 2)
        die("the leader of %s is not one of the nodes", names[A]);
    tsdbc *c = client(L);
    tsdb_sid sa = rep_series(c, "stalled", names[A], 30000), sb = rep_series(c, "healthy", names[B], 30000);
    await_isr(L, names[A], 3, 15000, "every replica of the volume to stall up");
    await_isr(L, names[B], 3, 15000, "every replica of the healthy volume up");
    char stall[PATH_MAX + 96];
    server_dir(R, stall, sizeof stall);
    snprintf(stall + strlen(stall), sizeof stall - strlen(stall), "/stallinbox.%" PRIu32, num[A]);
    FILE *sf = fopen(stall, "w");
    if (!sf)
        die("create %s", stall);
    fclose(sf);
    struct flood f[2] = {{cports[L], sa, 0, 0, 0}, {cports[L], sa, 0, 0, 0}};
    pthread_t th[2];
    for (int k = 0; k < 2; k++) {
        f[k].rounds = k * 1000; /* other timestamps */
        if (pthread_create(&th[k], NULL, flood_thread, &f[k]) != 0)
            die("pthread_create");
    }
    /* 8 s of single-row writes to the healthy volume, its ISR checked between them */
    uint64_t t0 = now_ms(), worst = 0, last_isr = 0;
    int writes = 0, full_at = -1;
    while (now_ms() - t0 < 8000) {
        int64_t ts = 1000LL * (writes + 1);
        float val = (float)writes;
        uint64_t w0 = now_ms();
        int rc = tsdbc_insert_series(c, sb, &ts, &val, 1);
        uint64_t ms = now_ms() - w0;
        if (rc != 0)
            die("inboxshared: a write to the healthy volume: %s", ers(rc));
        if (ms > worst)
            worst = ms;
        writes++;
        if (full_at < 0 && log_has(R, "frames are dropped"))
            full_at = writes;
        if (now_ms() - last_isr >= 100) {
            last_isr = now_ms();
            uint32_t n = isr_of(L, names[B], NULL);
            if (n != 3)
                die("inboxshared: the healthy volume %s has %" PRIu32 " ISR members while %s's inbox on n%d is full"
                    " (the shared link's thread waited for it)", names[B], n, names[A], R);
        }
    }
    for (int k = 0; k < 2; k++)
        __atomic_store_n(&f[k].stop, 1, __ATOMIC_RELEASE);
    for (int k = 0; k < 2; k++) {
        pthread_join(th[k], NULL);
        if (f[k].rc != 0)
            die("inboxshared: a write to the stalled volume: %s", ers(f[k].rc));
    }
    if (full_at < 0)
        die("inboxshared: the stalled volume's inbox never filled (the case proved nothing)");
    if (worst > 1000)
        die("inboxshared: a single-row write to the healthy volume took %" PRIu64 " ms while %s's inbox was full",
            worst, names[A]);
    unlink(stall);
    await_isr(L, names[A], 3, 60000, "the stalled volume's replica catching up");
    if (rows_of(c, sb) != writes)
        die("inboxshared: the leader reads %d rows of the healthy volume, not %d", rows_of(c, sb), writes);
    tsdbc_close(c);
    stop_all();
    for (int i = 0; i < 3; i++)
        penv[i] = NULL;
    printf("  %s stalled on n%d (inbox full from write %d): %d writes to %s, the slowest %" PRIu64 " ms, its ISR "
           "stayed 3\n", names[A], R, full_at, writes, names[B], worst);
}

/* backpressure into a replica (r3d review M3): a replica that stops handling its peer frames (TSDB_REPLD_TEST=stallinbox
 * while <dir>/stallinbox exists: a stalled disk's stand-in) leaves the ISR, and with a small inbox bound (smallinbox)
 * drops the frames past the bound instead of holding the leader's stream in memory; unstalled, it catches up from the
 * resends and grows back; a part above the spill threshold (spill: 64
 * KiB) is received into a stage_s* file, not memory, and every replica ends with the leader's rows */
static void scen_backpressure(void)
{
    scenario("backpressure");
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=spill";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    int R = (L + 1) % 3, S2 = (L + 2) % 3;
    stop(R, SIGTERM);
    penv[R] = "TSDB_REPLD_TEST=spill,smallinbox,stallinbox";
    start(R);
    tsdbc *c = client(L);
    tsdb_sid id[REP_NAMES];
    for (int k = 0; k < REP_NAMES; k++)
        id[k] = rep_series(c, rep_names[k], "plant", 30000);
    await_isr(L, "plant", 3, 15000, "every replica up");
    uint64_t n[REP_NAMES] = {0};
    /* R stalls: it leaves the ISR and the writes go on at full speed, streamed to R, whose inbox fills */
    char stall[PATH_MAX + 80];
    server_dir(R, stall, sizeof stall);
    strcat(stall, "/stallinbox");
    FILE *sf = fopen(stall, "w");
    if (!sf)
        die("create %s", stall);
    fclose(sf);
    /* 1000-row writes from four connections for 4 s */
    struct rep_writer w[4];
    pthread_t th[4];
    uint64_t t0 = now_ms();
    int rounds = 0;
    while (now_ms() - t0 < 4000) {
        for (int k = 0; k < 4; k++) {
            w[k] = (struct rep_writer){cports[L], id[0], 4000000LL * rounds + 1000000LL * k, 0, 0, 0,
                                       1000, 0};
            if (pthread_create(&th[k], NULL, rep_write_thread, &w[k]) != 0)
                die("pthread_create");
        }
        for (int k = 0; k < 4; k++) {
            pthread_join(th[k], NULL);
            if (w[k].rc != 0)
                die("a write with a stalled replica: %s", ers(w[k].rc));
        }
        n[0] += 4000;
        rounds++;
    }
    /* and a large write: its part is shipped as a file above the spill threshold */
    struct rep_writer wb = {cports[L], id[2], 2000000000, 0, 0, 0, 100000, 0};
    rep_write_thread(&wb);
    if (wb.rc != 0)
        die("a large write with a stalled replica: %s", ers(wb.rc));
    n[2] += 100000;
    if (!log_has(R, "frames are dropped"))
        die("the stalled replica held the leader's whole stream in its inbox (no frame dropped at the bound)");
    unlink(stall);
    if (!log_has(S2, "not into memory"))
        die("a replica received a part above the spill threshold into memory");
    await_isr(L, "plant", 3, 60000, "the stalled replica catching up");
    if ((uint64_t)rows_of(c, id[0]) != n[0])
        die("the leader reads %d rows of %s, not %" PRIu64, rows_of(c, id[0]), rep_names[0], n[0]);
    tsdbc_close(c);
    stop_all();
    for (int i = 0; i < 3; i++)
        penv[i] = NULL;
    rep_same(n, "after a clean stop");
    printf("  a stalled replica drops frames past its inbox bound and catches up (%d rounds of writes), a large part is"
           " received into a file; every replica holds the leader's rows\n", rounds);
}

/* stallstop (2026-11-18): a replica whose volume thread is stalled (TSDB_REPLD_TEST=stallinbox, <dir>/stallinbox in
 * place) stops cleanly on SIGTERM within seconds. The stall used to end only when the file went, so a test that died
 * with the file in place left its replica in repld_stop's join for ever, under init and holding an io_uring ring:
 * every later io_uring jepsen-cluster run on the machine failed with "io_uring: Cannot allocate memory". */
static void scen_stallstop(void)
{
    scenario("stallstop");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    int R = (L + 1) % 3;
    stop(R, SIGTERM);
    penv[R] = "TSDB_REPLD_TEST=smallinbox,stallinbox";
    start(R);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    tsdbc_close(c);
    await_isr(L, "plant", 3, 15000, "every replica up");
    char stall[PATH_MAX + 80];
    server_dir(R, stall, sizeof stall);
    strcat(stall, "/stallinbox");
    FILE *sf = fopen(stall, "w");
    if (!sf)
        die("create %s", stall);
    fclose(sf);
    /* writes until R's inbox is past its bound: its volume thread is then asleep in the stall */
    uint64_t t0 = now_ms();
    for (int round = 0; !log_has(R, "frames are dropped"); round++) {
        if (now_ms() - t0 > 20000) {
            unlink(stall);
            die("the stalled replica's inbox never filled in 20 s (the case proved nothing)");
        }
        struct rep_writer w = {cports[L], id, 1000000LL * round + 1, 0, 0, 0, 1000, 0};
        rep_write_thread(&w);
        if (w.rc != 0) {
            unlink(stall);
            die("a write with a stalled replica: %s", ers(w.rc));
        }
    }
    signal_child(pids[R], SIGTERM);
    int st = await_exit(R, 10000);
    unlink(stall);
    if (st != 0) {
        if (st < 0) {
            signal_child(pids[R], SIGKILL);
            waitpid(pids[R], NULL, 0);
            pids[R] = 0;
        }
        die("a replica stalled in its inbox %s on SIGTERM", st < 0 ? "did not stop in 10 s" : "did not stop cleanly");
    }
    penv[R] = NULL;
    stop_all();
    printf("  a replica stalled in its inbox stops cleanly on SIGTERM\n");
}

/* rejoin (the merge's jepsen-cluster kill run, 2026-11-17): a replica killed and restarted below what the leader sent
 * it, while the writes never pause, joins the ISR again while they go on. The leader's fast path kept the peer's cursor at the live end, moving
 * sent_ms with every record, so the restarted replica refused every APPEND for the gap and the driver never moved the
 * cursor back to what it held (mutant fastride): in that run a replica's log stayed where it died for 30 minutes.
 *
 * rejoinsteady: the same with two writers (a write always in flight) and the restarted replica's ACKs reporting what
 * it had 100 ms before (TSDB_REPLD_TEST=slowack: a far replica, always a few writes behind the leader's end). A
 * learner joined only once its log reached the commit point, which under such writes it never does: the run of the
 * merge had n1 out of the ISR for 30 minutes while it received everything. The leader now holds the commit point
 * for a learner close behind until it has it (repl.c isr_check; mutant nojoinhold: the old rule).
 *
 * rejoinslow: the leader's catch-up reads take 10 ms each (TSDB_REPLD_TEST=slowread: longer than a tick). The driver
 * ran a due tick (with its catch-up) before the inbox, so with each tick longer than one the next was always due and
 * the healthy replica's ACKs waited in the inbox while the core's clock ran: the leader dropped it for silence (in
 * the merge's repro the ISR went 3 -> 2 -> 1 during a rejoin). After each tick the inbox now gets a tick's time
 * (mutant inboxstarve: none). The healthy replica must stay in the ISR throughout.
 *
 * rejoinlate: every tick of the leader takes 6 ms (TSDB_REPLD_TEST=latetick), so its volume thread is never current
 * (as under TSan with a full inbox). Late ticks run without a catch-up step (tickwall), but one still runs as long
 * after the last as that took: a version that ran steps only on current ticks never caught the replica up
 * (rejoinsteady under TSan; mutant stepcurrentonly). */
enum { REJ_GAP, REJ_STEADY, REJ_SLOW, REJ_LATE };
static void rejoin_run(const char *name, int how)
{
    scenario(name);
    for (int i = 0; i < 3; i++) {
        penv[i] = how == REJ_SLOW ? "TSDB_REPLD_TEST=slowread" : how == REJ_LATE ? "TSDB_REPLD_TEST=latetick" : NULL;
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    int nf = how == REJ_STEADY ? 2 : 1;
    tsdb_sid id[2];
    for (int k = 0; k < nf; k++)
        id[k] = rep_series(c, rep_names[k], "plant", 30000);
    await_isr(L, "plant", 3, 10000, "every replica up");
    struct flood f[2];
    pthread_t th[2];
    for (int k = 0; k < nf; k++) {
        f[k] = (struct flood){cports[L], id[k], 0, 0, 0};
        if (pthread_create(&th[k], NULL, flood_thread, &f[k]) != 0)
            die("pthread_create");
    }
    struct timespec s1 = {1, 0};
    nanosleep(&s1, NULL);
    /* stopped first (SIGSTOP: its link stays up and the leader's records go into it until its queue is full), then
     * killed while stopped: what was sent and never read is lost, so the replica comes back below the cursor */
    int R = (L + 1) % 3;
    pause_server(R, 1);
    uint64_t t0 = now_ms();
    uint32_t n;
    while ((n = isr_of(L, "plant", NULL)) == 3) {
        if (now_ms() - t0 > 10000)
            die("a replica stopped under writes: the ISR of plant has 3 members after 10000 ms");
        struct timespec ms = {0, 50000000};
        nanosleep(&ms, NULL);
    }
    if (how == REJ_SLOW && (n < 2 || log_has(L, "asks for an ISR of 1 members")))
        die("the leader dropped the healthy replica from the ISR while another was away (its ACKs waited behind the "
            "catch-up)");
    nanosleep(&s1, NULL);
    signal_child(pids[R], SIGKILL);
    if (waitpid(pids[R], NULL, 0) != pids[R])
        die("waitpid %d: %s", (int)pids[R], strerror(errno));
    pids[R] = 0;
    stopped[R] = 0;
    int r0 = 0;
    for (int k = 0; k < nf; k++)
        r0 += __atomic_load_n(&f[k].rounds, __ATOMIC_RELAXED);
    if (how == REJ_STEADY)
        penv[R] = "TSDB_REPLD_TEST=slowack";
    start(R);
    t0 = now_ms();
    int rounds = 0;
    while ((n = isr_of(L, "plant", NULL)) != 3) {
        rounds = 0;
        for (int k = 0; k < nf; k++) {
            if (__atomic_load_n(&f[k].rc, __ATOMIC_RELAXED))
                die("a write while the replica was away: %s", ers(f[k].rc));
            rounds += __atomic_load_n(&f[k].rounds, __ATOMIC_RELAXED);
        }
        if (how == REJ_SLOW && (n < 2 || log_has(L, "asks for an ISR of 1 members")))
            die("the leader dropped the healthy replica from the ISR while another caught up (its ACKs waited behind "
                "the catch-up)");
        if (now_ms() - t0 > 30000)
            die("the replica restarted under writes that never pause did not join the ISR again in 30 s (%d writes "
                "since its restart)", rounds - r0);
        struct timespec ms = {0, 50000000};
        nanosleep(&ms, NULL);
    }
    rounds = 0;
    for (int k = 0; k < nf; k++)
        rounds += __atomic_load_n(&f[k].rounds, __ATOMIC_RELAXED);
    int joined = rounds - r0;
    uint64_t took = now_ms() - t0;
    for (int k = 0; k < nf; k++) {
        __atomic_store_n(&f[k].stop, 1, __ATOMIC_RELEASE);
        pthread_join(th[k], NULL);
        if (f[k].rc != 0)
            die("a write while the replica was away: %s", ers(f[k].rc));
    }
    if (how == REJ_SLOW && log_has(L, "asks for an ISR of 1 members"))
        die("the leader dropped the healthy replica from the ISR while another caught up (its ACKs waited behind the "
            "catch-up)");
    if (joined < 5)
        die("only %d writes went on between the restart and the join: the writes paused, so this proved nothing", joined);
    tsdbc_close(c);
    stop_all();
    for (int i = 0; i < 3; i++)
        penv[i] = NULL;
    uint64_t wantr[REP_NAMES] = {0};
    for (int k = 0; k < nf; k++)
        wantr[k] = (uint64_t)f[k].rounds * 1000;
    rep_same(wantr, "after a clean stop");
    printf("  a replica killed and restarted under writes that never paused joined the ISR again in %" PRIu64 " ms (%d "
           "writes in between)%s; every replica holds the leader's rows\n", took, joined,
           how == REJ_STEADY ? ", its ACKs 100 ms late" : how == REJ_SLOW ? ", the leader's reads slow, the healthy "
           "replica in the ISR throughout" : "");
}

static void scen_rejoin(void) { rejoin_run("rejoin", REJ_GAP); }
static void scen_rejoinsteady(void) { rejoin_run("rejoinsteady", REJ_STEADY); }
static void scen_rejoinslow(void) { rejoin_run("rejoinslow", REJ_SLOW); }
static void scen_rejoinlate(void) { rejoin_run("rejoinlate", REJ_LATE); }

/* tickwall (r3d-isr review M1): isr_lag is wall time. The core counts it in ticks, and every catch-up step of the
 * leader ran inside a tick, a late tick dropped: with a step of 20 ms (TSDB_REPLD_TEST=slowtick, every tick) a core
 * tick took 25 ms, and a stopped member held the writes for 5 s instead of isr_lag (1 s). Now a late tick is the
 * clock catching up and runs without a step (mutant tickstretch: the old rule). A member stopped under writes must
 * leave the ISR within 3.5 s (isr_lag, the ask and the metadata group's round, with room for a slow machine). */
static void scen_tickwall(void)
{
    scenario("tickwall");
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=slowtick";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    await_isr(L, "plant", 3, 10000, "every replica up");
    struct flood f = {cports[L], id, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, flood_thread, &f) != 0)
        die("pthread_create");
    struct timespec s1 = {1, 0};
    nanosleep(&s1, NULL);
    int R = (L + 1) % 3;
    pause_server(R, 1);
    uint64_t t0 = now_ms(), took;
    while (isr_of(L, "plant", NULL) == 3) {
        if (now_ms() - t0 > 20000)
            die("a member stopped under writes: the ISR of plant has 3 members after 20000 ms");
        struct timespec ms = {0, 10000000};
        nanosleep(&ms, NULL);
    }
    took = now_ms() - t0;
    pause_server(R, 0);
    __atomic_store_n(&f.stop, 1, __ATOMIC_RELEASE);
    pthread_join(th, NULL);
    if (f.rc != 0)
        die("a write while a member was stopped: %s", ers(f.rc));
    if (took > 3500)
        die("a member stopped under writes left the ISR only after %" PRIu64 " ms (isr_lag 1000 ms): the core's ticks "
            "ran slower than the wall clock", took);
    await_isr(L, "plant", 3, 60000, "the stopped member back");
    tsdbc_close(c);
    stop_all();
    for (int i = 0; i < 3; i++)
        penv[i] = NULL;
    uint64_t wantr[REP_NAMES] = {(uint64_t)f.rounds * 1000, 0, 0, 0};
    rep_same(wantr, "after a clean stop");
    printf("  with a catch-up step of 20 ms at every tick a member stopped under writes left the ISR after %" PRIu64
           " ms\n", took);
}

/* The keep caps (design-cluster.md 8.3): a replica out of the ISR holds the leader's flushed segments only for
 * repl_retain_s (2 s here); past it they go, and the replica, back, is told it needs a snapshot and stays a learner. */
static void scen_keepcap(void)
{
    scenario("keepcap");
    init_retain_s = 2;
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    init_retain_s = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    await_isr(0, "plant", 3, 5000, "every replica up");
    int R = (L + 1) % 3;
    stop(R, SIGKILL);
    await_isr(0, "plant", 2, 10000, "a replica killed");
    /* a segment a second, each flushed: with the replica away the keep bound stays where it was */
    struct timespec s1 = {1, 0};
    int64_t t = 10000;
    for (int k = 0; k < 7; k++) {
        int64_t tv[100];
        float vv[100];
        for (int j = 0; j < 100; j++)
            tv[j] = t++, vv[j] = (float)j;
        if ((rc = tsdbc_insert_series(c, id, tv, vv, 100)) != 0)
            die("a write with a replica away: %s", ers(rc));
        if ((rc = tsdbc_flush(c)) != 0)
            die("flush: %s", ers(rc));
        nanosleep(&s1, NULL);
    }
    if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0) /* a commit after the last flush: the log start moves */
        die("a write with a replica away: %s", ers(rc));
    int nw = wal_count(L, 1);
    if (nw > 4)
        die("the leader keeps %d WAL segments for a replica away longer than repl_retain_s (7 flushed, 1 s apart)",
            nw);
    start(R);
    uint64_t t0 = now_ms();
    while (!log_has(R, "it needs a snapshot")) {
        if (now_ms() - t0 > 15000)
            die("the replica back past the keep cap never heard it needs a snapshot");
        struct timespec ms100 = {0, 100000000};
        nanosleep(&ms100, NULL);
    }
    /* r4-xferinst: it fetches a snapshot from the leader, installs it, opens again and joins the ISR */
    t0 = now_ms();
    while (!log_has(R, "snapshot installed")) {
        if (now_ms() - t0 > 30000)
            die("the replica that needs a snapshot never installed one");
        struct timespec ms100 = {0, 100000000};
        nanosleep(&ms100, NULL);
    }
    await_isr(0, "plant", 3, 30000, "the replica that installed a snapshot joins the ISR");
    t++;
    if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0)
        die("a write after the replica installed a snapshot: %s", ers(rc));
    int want_rows = rows_of(c, id), got_rows = -1;
    tsdbc *cr = client(R);
    for (t0 = now_ms(); (got_rows = rows_of(cr, id)) != want_rows && now_ms() - t0 < 10000;)
        usleep(50000);
    if (got_rows != want_rows)
        die("the replica that installed a snapshot has %d rows, the leader %d", got_rows, want_rows);
    tsdbc_close(cr);
    tsdbc_close(c);
    stop_all();
    printf("  past repl_retain_s the leader keeps %d WAL segments, the replica back is told it needs a snapshot,"
           " installs one, joins the ISR and holds the leader's %d rows\n", nw, want_rows);
}

/* ---- snapshot transfer (r4-xferlink; server/rsnap.c, R4 plan D2, D5, D7, D18) */

struct snapset {
    int L, R, O; /* the leader of plant, the replica that needs a snapshot, the other member */
    int lead[2];  /* the leader of each volume */
    int nvol;
    tsdbc *c[2];
    tsdb_sid id[2];
    int64_t t;
};

/* the snap.* lines of server i's STATUS (server/rsnap.c's counters) */
struct rsnap_stats {
    uint64_t asked, sent, received, refused_space, failed, busy, bytes_sent, bytes_received, installed, refused_stale;
    uint64_t kind5_bytes, kind2_bytes; /* what the node's kind-5 and kind-2 links took from their buckets */
};
static void status_snap(int i, struct rsnap_stats *st)
{
    tsdbc *c = client(i);
    char *text = NULL;
    int rc = tsdbc_status(c, &text);
    if (rc != 0)
        die("STATUS of server %d: %s", i, ers(rc));
    static const char *keys[] = {"asked", "sent", "received", "refused_space", "failed", "busy", "bytes_sent",
                                 "bytes_received", "installed", "refused_stale", "kind5_bytes", "kind2_bytes"};
    uint64_t *v[] = {&st->asked, &st->sent, &st->received, &st->refused_space, &st->failed, &st->busy,
                     &st->bytes_sent, &st->bytes_received, &st->installed, &st->refused_stale, &st->kind5_bytes,
                     &st->kind2_bytes};
    for (size_t k = 0; k < sizeof keys / sizeof keys[0]; k++) {
        char key[64];
        snprintf(key, sizeof key, "\nsnap.%s=", keys[k]);
        const char *at = strstr(text, key);
        if (!at)
            die("STATUS of server %d has no snap.%s line:\n%s", i, keys[k], text);
        *v[k] = strtoull(at + strlen(key), NULL, 10);
    }
    free(text);
    tsdbc_close(c);
}

/* snap.install_last_s of server i's STATUS (the seconds of its last install) */
static double status_install_s(int i)
{
    tsdbc *c = client(i);
    char *text = NULL;
    int rc = tsdbc_status(c, &text);
    if (rc != 0)
        die("STATUS of server %d: %s", i, ers(rc));
    const char *at = strstr(text, "\nsnap.install_last_s=");
    if (!at)
        die("STATUS of server %d has no snap.install_last_s line:\n%s", i, text);
    double v = strtod(at + strlen("\nsnap.install_last_s="), NULL);
    free(text);
    tsdbc_close(c);
    return v;
}

static const char *snap_vols[2] = {"plant", "plant2"};

/* n rows of random values (about 3.6 bytes each in a part) from ts *t on */
static void snap_rows(tsdbc *c, tsdb_sid id, int64_t *t, size_t n)
{
    size_t step = n < 1000000 ? n : 1000000;
    int64_t *tv = malloc(step * sizeof *tv);
    float *vv = malloc(step * sizeof *vv);
    if (!tv || !vv)
        die("out of memory");
    static uint64_t x = 88172645463325252ull;
    for (size_t done = 0; done < n;) {
        size_t k = n - done < step ? n - done : step;
        for (size_t j = 0; j < k; j++) {
            x ^= x << 13, x ^= x >> 7, x ^= x << 17;
            tv[j] = (*t)++;
            vv[j] = (float)(x >> 40) / 1024.0f;
        }
        int rc = tsdbc_insert_series(c, id, tv, vv, k);
        if (rc != 0)
            die("a write of %zu rows: %s", k, ers(rc));
        done += k;
    }
    free(tv);
    free(vv);
}

/* keepcap's way to a replica that needs a snapshot: nvol volumes of three replicas, `big` rows of random values in
 * each with every replica up, then R (a member that leads none of them) killed and seven flushed segments written a
 * second apart, past repl_retain_s (2 s). R is not started again: the caller sets penv[R] first. */
static void snap_setup(int nvol, size_t big, struct snapset *s)
{
    memset(s, 0, sizeof *s);
    s->nvol = nvol;
    init_retain_s = 2;
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    init_retain_s = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    int rc;
    for (int k = 0; k < nvol; k++) {
        uint32_t num;
        if ((rc = vol_add(0, snap_vols[k], 3, &num)) != 0 || num != (uint32_t)k + 1)
            die("volume add %s: %s, number %" PRIu32, snap_vols[k], cluster_strerror(rc), num);
        for (int i = 0; i < 3; i++)
            await_open_gen(0, snap_vols[k], i, 1, 0);
        struct meta_volume v;
        if (!vol_rec(0, snap_vols[k], &v))
            die("no record of %s", snap_vols[k]);
        s->lead[k] = server_of(v.leader);
        if (s->lead[k] < 0 || s->lead[k] > 2)
            die("the leader of %s is node %u", snap_vols[k], v.leader);
    }
    s->L = s->lead[0];
    s->R = (s->L + 1) % 3;
    if (nvol > 1 && s->R == s->lead[1])
        s->R = (s->R + 1) % 3;
    if (s->R == s->L || (nvol > 1 && s->R == s->lead[1]))
        die("no member leads none of the volumes");
    s->O = 3 - s->L - s->R;
    s->t = 1000;
    for (int k = 0; k < nvol; k++) {
        s->c[k] = client(s->lead[k]);
        s->id[k] = rep_series(s->c[k], rep_names[0], snap_vols[k], 30000);
        int64_t t = s->t;
        snap_rows(s->c[k], s->id[k], &t, big ? big : 1);
        await_isr(0, snap_vols[k], 3, 5000, "every replica up");
    }
    s->t += (int64_t)(big ? big : 1);
    stop(s->R, SIGKILL);
    for (int k = 0; k < nvol; k++)
        await_isr(0, snap_vols[k], 2, 10000, "a replica killed");
    struct timespec s1 = {1, 0};
    for (int r = 0; r < 7; r++) {
        for (int k = 0; k < nvol; k++) {
            int64_t t = s->t;
            snap_rows(s->c[k], s->id[k], &t, 100);
            if ((rc = tsdbc_flush(s->c[k])) != 0)
                die("flush: %s", ers(rc));
        }
        s->t += 100;
        nanosleep(&s1, NULL);
    }
    for (int k = 0; k < nvol; k++) { /* a commit after the last flush: the log start moves */
        int64_t t = s->t;
        snap_rows(s->c[k], s->id[k], &t, 1);
    }
    s->t++;
}

static void snap_close(struct snapset *s)
{
    for (int k = 0; k < s->nvol; k++)
        if (s->c[k])
            tsdbc_close(s->c[k]);
    s->c[0] = s->c[1] = NULL;
}

static void await_log(int i, const char *needle, int ms, const char *what)
{
    uint64_t t0 = now_ms();
    while (!log_has(i, needle)) {
        if (now_ms() - t0 > (uint64_t)ms)
            die("%s (server %d never logged \"%s\" in %d ms)", what, i, needle, ms);
        usleep(50000);
    }
}

/* the last line of server i's log with `needle`, into out ("" when none) */
static void log_line(int i, const char *needle, char *out, size_t n)
{
    char path[PATH_MAX + 80], line[4096];
    snprintf(path, sizeof path, "%s/n%d.log", base, i);
    FILE *f = fopen(path, "r");
    out[0] = 0;
    while (f && fgets(line, sizeof line, f))
        if (strstr(line, needle))
            snprintf(out, n, "%s", line);
    if (f)
        fclose(f);
}

/* entries of server i's directory `sub` whose names begin with `prefix` (-1: no such directory) */
static int dir_count(int i, const char *sub, const char *prefix)
{
    char d[PATH_MAX + 80], p[PATH_MAX + 200];
    server_dir(i, d, sizeof d);
    snprintf(p, sizeof p, "%s/%s", d, sub);
    DIR *dd = opendir(p);
    if (!dd)
        return errno == ENOENT ? -1 : (die("opendir %s: %s", p, strerror(errno)), -1);
    int n = 0;
    for (struct dirent *e; (e = readdir(dd));)
        n += strcmp(e->d_name, ".") && strcmp(e->d_name, "..") && !strncmp(e->d_name, prefix, strlen(prefix));
    closedir(dd);
    return n;
}

/* the copy server i received (TSDB_REPLD_TEST=snaphold keeps it as v<num>.snapheld) holds exactly the files its
 * SNAPMAN names, each of the size and xxh64 SNAPMAN records; returns their bytes (links counted once) */
static uint64_t snap_verify_held(int i, uint32_t num, size_t *nfiles)
{
    char d[PATH_MAX + 80], held[PATH_MAX + 120], f[PATH_MAX + 300];
    server_dir(i, d, sizeof d);
    snprintf(held, sizeof held, "%s/v%" PRIu32 ".snapheld", d, num);
    struct snap_man m;
    memset(&m, 0, sizeof m);
    int rc = snap_man_read(held, &m);
    if (rc != 0)
        die("the snapshot server %d received (%s): its SNAPMAN does not read: %s", i, held, ers(rc));
    uint64_t bytes = 0;
    for (size_t k = 0; k < m.nfiles; k++) {
        snprintf(f, sizeof f, "%s/%s", held, m.files[k].name);
        int fd = open(f, O_RDONLY | O_CLOEXEC);
        if (fd < 0)
            die("the received snapshot lacks %s, which its SNAPMAN names: %s", m.files[k].name, strerror(errno));
        uint64_t size = 0, x = 0;
        if (snap_xxh64_fd(fd, &size, &x) != 0)
            die("read %s: %s", f, strerror(errno));
        close(fd);
        if (size != m.files[k].size || x != m.files[k].xxh64)
            die("the received snapshot's %s has %" PRIu64 " bytes, xxh64 %016" PRIx64 "; its SNAPMAN says %" PRIu64
                ", %016" PRIx64, m.files[k].name, size, x, m.files[k].size, m.files[k].xxh64);
        if (!m.files[k].link)
            bytes += size;
    }
    char sub[64];
    snprintf(sub, sizeof sub, "v%" PRIu32 ".snapheld", num);
    int n = dir_count(i, sub, "");
    if (n != (int)m.nfiles + 1)
        die("the received snapshot holds %d files besides SNAPMAN, which names %zu", n - 1, m.nfiles);
    *nfiles = m.nfiles;
    snap_man_free(&m);
    return bytes;
}

/* the leader's snap_* directories gone (released) within ms */
static void await_released(int L, uint32_t num, int ms)
{
    char sub[32];
    snprintf(sub, sizeof sub, "v%" PRIu32, num);
    uint64_t t0 = now_ms();
    int n;
    while ((n = dir_count(L, sub, SNAP_PREFIX)) > 0) {
        if (now_ms() - t0 > (uint64_t)ms)
            die("the leader still holds %d snapshot directories %d ms after the receiver had them all", n, ms);
        usleep(50000);
    }
}

/* snapxfer: a replica back past the keep caps asks its leader for a snapshot, which the leader makes and sends; the
 * first copy, with a byte flipped on the source after the make, is refused and asked again; the copy received matches
 * its SNAPMAN file for file, and the leader releases its snapshot. The first make takes 4 s, twice the source's
 * link-down timer (2 s here): the source dials its kind-5 link with the first file, so during that make it has none
 * (snaplost's stale refusal dials it first, which is why the check is here), and a make must not count as down
 * (review F3). */
static void scen_snapxfer(void)
{
    scenario("snapxfer");
    for (int i = 0; i < 3; i++) /* the first snapshot made has a byte flipped after SNAPMAN took its hash */
        penv[i] = "TSDB_REPLD_TEST=snapflip,snapslowmake=4000,snapdownms=2000";
    struct snapset s;
    snap_setup(1, 200000, &s);
    char held[PATH_MAX + 64], needle[128];
    penv[s.R] = "TSDB_REPLD_TEST=snaphold";
    start(s.R);
    await_log(s.R, "it needs a snapshot and asks the leader", 15000, "the replica back past the keep cap never asked");
    await_log(s.R, "(snaphold)", 60000, "the replica never received the whole snapshot");
    if (!log_has(s.L, "(snapslowmake)"))
        die("the leader's make did not take the hook's 4 s: the test proves nothing");
    if (log_has(s.L, "stayed down"))
        die("the leader released a snapshot while making it (its link-down timer ran during the make)");
    if (!log_has(s.L, "(snapflip)") || !log_has(s.R, "a file's xxh64 is not the one SNAPMAN names"))
        die("the copy with a flipped byte was not refused (flipped on the leader: %d)", log_has(s.L, "(snapflip)"));
    snprintf(needle, sizeof needle, "snapshot sent to node %" PRIu32 ":", ids[s.R]);
    await_log(s.L, needle, 10000, "the leader never heard the receiver had every file");
    size_t nf = 0;
    uint64_t bytes = snap_verify_held(s.R, 1, &nf);
    await_released(s.L, 1, 5000);
    if (dir_count(s.R, "v1.snap", "") >= 0)
        die("v1.snap is still on the receiver beside the kept copy");
    if (!log_has(s.L, "snapshot made for node"))
        die("the leader never said it made the snapshot");
    struct rsnap_stats sl, sr;
    status_snap(s.L, &sl);
    status_snap(s.R, &sr);
    if (sl.sent != 1 || sl.bytes_sent < bytes || sr.asked < 1 || sr.received != 1 || sr.bytes_received < bytes)
        die("STATUS: the leader sent %" PRIu64 " (%" PRIu64 " bytes), the receiver asked %" PRIu64 " and received %"
            PRIu64 " (%" PRIu64 " bytes); the copy has %" PRIu64 " bytes", sl.sent, sl.bytes_sent, sr.asked,
            sr.received, sr.bytes_received, bytes);
    snprintf(held, sizeof held, "snapshot received from node %" PRIu32 ":", ids[s.L]);
    char line[4096];
    log_line(s.R, held, line, sizeof line);
    int64_t t = s.t++;
    float val = 1;
    int rc = tsdbc_insert_series(s.c[0], s.id[0], &t, &val, 1);
    if (rc != 0)
        die("a write after the snapshot: %s", ers(rc));
    snap_close(&s);
    stop_all();
    printf("  the replica back past the keep cap asked for a snapshot and received %zu files, %" PRIu64 " bytes, each"
           " as SNAPMAN records it; the leader released its copy\n  %s", nf, bytes, line);
}

/* snapnospace (D5): a snapshot larger than the receiver's free space (the hook reports 4 KiB) is refused once SNAPMAN
 * is in, before any file: said once, counted, asked again at a later notice, no file of it written, and the live
 * volumes go on. */
static void scen_snapnospace(void)
{
    scenario("snapnospace");
    struct snapset s;
    snap_setup(1, 0, &s);
    penv[s.R] = "TSDB_REPLD_TEST=snaphold,snapfree=4096";
    start(s.R);
    /* snapfree=4096 lies between the copy's size (a few KB) and that size plus the margin (1 GiB at least): refused for
     * the margin, which D5 keeps for the live volumes (a copy larger than the free space is refused a fortiori) */
    await_log(s.R, "is refused: the file system", 20000,
              "a snapshot whose size plus the margin exceeds the free space was not refused");
    char rl[4096];
    log_line(s.R, "is refused: the file system", rl, sizeof rl);
    const char *of = strstr(rl, "a snapshot of ");
    uint64_t refused = of ? strtoull(of + 14, NULL, 10) : 0;
    if (!refused || refused >= 4096)
        die("the refused snapshot has %" PRIu64 " bytes: not the case of a copy below the free space (%s)", refused, rl);
    char needle[128];
    snprintf(needle, sizeof needle, "snapshot made for node %" PRIu32 ":", ids[s.R]);
    await_log_count(s.L, needle, 2, 20000); /* asked again */
    if (log_count(s.R, "is refused: the file system") != 1)
        die("the refusal for space was said %d times (once per volume)", log_count(s.R, "is refused: the file system"));
    if (log_has(s.R, "snapshot received from node") || dir_count(s.R, "v1.snapheld", "") >= 0)
        die("a snapshot refused for its space was taken");
    snprintf(needle, sizeof needle, "snapshot sent to node %" PRIu32 ":", ids[s.R]);
    if (log_has(s.L, needle))
        die("the leader sent the files of a snapshot the receiver refused");
    int n = dir_count(s.R, "v1.snap", "");
    if (n > 1)
        die("the receiver that refused a snapshot for its space holds %d of its files", n);
    struct rsnap_stats st;
    status_snap(s.R, &st);
    if (st.refused_space < 1 || st.received)
        die("STATUS of the receiver: %" PRIu64 " refused for space, %" PRIu64 " received (want >= 1, 0)",
            st.refused_space, st.received);
    int64_t t = s.t++;
    float val = 1;
    int rc = tsdbc_insert_series(s.c[0], s.id[0], &t, &val, 1);
    if (rc != 0)
        die("a write while the receiver refuses snapshots: %s", ers(rc));
    snap_close(&s);
    stop_all();
    printf("  a snapshot above the free space was refused once SNAPMAN was in (counted %" PRIu64 "), asked again,"
           " no file written\n", st.refused_space);
}

/* snapbusy (D2): a leader that is promoting (the hook) answers BUSY and the receiver asks again once it is not; with
 * rebuild_max 1 a second volume's snapshot waits for the first. */
static void scen_snapbusy(void)
{
    scenario("snapbusy");
    for (int i = 0; i < 3; i++)
        penv[i] = "TSDB_REPLD_TEST=snaphold,snappromoting,snapfakesrc";
    init_rebuild_max = 1, init_rebuild_mb_s = 2;
    struct snapset s;
    snap_setup(2, 1000000, &s);
    init_rebuild_max = 0, init_rebuild_mb_s = 0;
    char hook[PATH_MAX + 80], d[PATH_MAX + 40];
    server_dir(s.L, d, sizeof d);
    snprintf(hook, sizeof hook, "%s/snappromoting", d);
    int fd = open(hook, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
    if (fd < 0)
        die("%s: %s", hook, strerror(errno));
    close(fd);
    /* a source job on each side (the hook): the leader's fills its rebuild_max, the receiver's must not count
     * against its receivers (two members feeding each other would answer each other BUSY for good) */
    char fakel[PATH_MAX + 80], faker[PATH_MAX + 80];
    snprintf(fakel, sizeof fakel, "%s/snapfakesrc", d);
    server_dir(s.R, d, sizeof d);
    snprintf(faker, sizeof faker, "%s/snapfakesrc", d);
    for (int k = 0; k < 2; k++) {
        if ((fd = open(k ? faker : fakel, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0644)) < 0)
            die("%s: %s", k ? faker : fakel, strerror(errno));
        close(fd);
    }
    start(s.R);
    await_log(s.R, "it needs a snapshot and asks the leader", 20000,
              "the receiver did not ask while a source job ran on it (rebuild_max counted the source)");
    await_log(s.R, "is busy (promoting)", 20000, "a leader that is promoting did not answer BUSY");
    char needle[128];
    snprintf(needle, sizeof needle, "volume 1: snapshot made for node %" PRIu32 ":", ids[s.R]);
    if (log_has(s.L, needle))
        die("a leader that is promoting made a snapshot");
    unlink(hook);
    await_log(s.R, "is busy (rebuild_max)", 20000, "a leader running rebuild_max sources did not answer BUSY");
    if (log_has(s.L, needle))
        die("a leader running rebuild_max sources made a snapshot");
    unlink(fakel);
    await_log_count(s.R, "snapshot received from node", 2, 90000);
    if (!log_has(s.R, "needs a snapshot and waits"))
        die("two snapshots ran at once on the receiver with rebuild_max 1");
    size_t nf;
    snap_verify_held(s.R, 1, &nf);
    snap_verify_held(s.R, 2, &nf);
    struct rsnap_stats st;
    status_snap(s.R, &st);
    if (st.busy < 1 || st.received != 2)
        die("STATUS of the receiver: %" PRIu64 " busy, %" PRIu64 " received (want >= 1, 2)", st.busy, st.received);
    snap_close(&s);
    stop_all();
    printf("  a promoting leader and one at rebuild_max answered BUSY and were asked again; with rebuild_max 1 the"
           " second snapshot waited, and a source job did not hold the receiver\n");
}

/* snapsrckill: the source killed in the middle of a transfer: the receiver drops its partial copy when the new
 * leader's notice names another source, and asks the new leader, whose copy arrives whole. */
static void scen_snapsrckill(void)
{
    scenario("snapsrckill");
    init_rebuild_mb_s = 2;
    struct snapset s;
    snap_setup(1, 2000000, &s);
    init_rebuild_mb_s = 0;
    penv[s.R] = "TSDB_REPLD_TEST=snaphold";
    start(s.R);
    char needle[128];
    snprintf(needle, sizeof needle, "snapshot made for node %" PRIu32 ":", ids[s.R]);
    await_log(s.L, needle, 20000, "the leader never made the snapshot");
    usleep(1500000);
    if (log_has(s.R, "snapshot received from node"))
        die("the snapshot arrived before the source could be killed (too small for this test)");
    if (dir_count(s.R, "v1.snap", "") < 2)
        die("the receiver holds no file of the snapshot 1.5 s into its transfer");
    snap_close(&s);
    stop(s.L, SIGKILL);
    await_log(s.R, "is abandoned", 40000, "the receiver kept a transfer from a killed source");
    if (!log_has(s.R, "the notice names another source"))
        die("the receiver dropped the killed source's transfer for another reason than the new leader's notice");
    snprintf(needle, sizeof needle, "snapshot received from node %" PRIu32 ":", ids[s.O]);
    await_log(s.R, needle, 90000, "the new leader's snapshot never arrived");
    size_t nf;
    uint64_t bytes = snap_verify_held(s.R, 1, &nf);
    stop_all();
    printf("  the source killed mid-transfer: the partial copy was dropped and the new leader's (%zu files, %" PRIu64
           " bytes) arrived whole\n", nf, bytes);
}

/* snaplarge (D7): a large insert while a snapshot moves at rebuild_mb_s 2 is not held by it (the snapshot's kind 5
 * does not hold the COMMITs' kind 2), and the transfer takes at least its size over the rate.
 *
 * The proof is a byte budget, not a time limit, so it holds on a machine of any speed (a 2000000-row insert takes a
 * few hundred ms in a normal build and over a second under TSan on 4 CPUs; neither matters). Every bulk link of one
 * kind takes its chunks from that kind's token bucket (server/peerlink.c, bucket_take: a chunk goes only when the
 * bucket's virtual clock is at or below now, the clock never starts more than 50 ms behind now, and each chunk moves
 * it on by its size over the rate). So over any window of W ms one bucket at R bytes/s lets through at most
 * R * (W + 50) / 1000 bytes plus one chunk, whatever the machine. The leader's STATUS counts the bytes each kind took
 * from its bucket (snap.kind5_bytes, snap.kind2_bytes). The window spans the whole insert (the counters are read
 * before it began and after it was acknowledged), and the insert is acknowledged only after its COMMIT files reached
 * the other member, so they are in the window's kind-2 bytes (13.5 MB). The snapshot keeps its own bucket busy for
 * the whole window (it moved before the window and is still moving after it), so kind 5 alone takes close to R * W,
 * and the COMMIT files come on top of it whatever W is: kinds 2 and 5 together moved more than one bucket at R could,
 * so they did not share one. Were the COMMIT files to share the snapshot's bucket (the planted snapsamelink: the
 * snapshot's files on kind 2, at rebuild_mb_s), everything the window moved would have passed that one bucket, and
 * the sum could never exceed its bound, however fast or slow the machine. The rate is low (2 MB/s) so that a slow
 * insert still lies inside the transfer; a snapshot that ended inside the window is reported as proving nothing,
 * never as a pass. */
static void scen_snaplarge(void)
{
    scenario("snaplarge");
    const uint64_t rate = 2u << 20; /* rebuild_mb_s 2, in bytes/s as rsnap.c takes it */
    init_rebuild_mb_s = 2;
    struct snapset s;
    snap_setup(1, 6000000, &s);
    init_rebuild_mb_s = 0;
    penv[s.R] = "TSDB_REPLD_TEST=snaphold";
    start(s.R);
    char needle[128], line[4096];
    snprintf(needle, sizeof needle, "snapshot made for node %" PRIu32 ":", ids[s.R]);
    await_log(s.L, needle, 30000, "the leader never made the snapshot");
    /* the snapshot's files are moving (more than SNAPMAN, a few KB, has arrived): a condition, not a pause */
    struct rsnap_stats st, a, b;
    uint64_t w0 = now_ms();
    for (status_snap(s.R, &st); st.bytes_received < (1u << 20); status_snap(s.R, &st)) {
        if (now_ms() - w0 > 60000)
            die("the snapshot's files did not begin to move in 60 s (%" PRIu64 " bytes received)", st.bytes_received);
        usleep(50000);
    }
    uint64_t ta = now_ms();
    status_snap(s.L, &a);
    uint64_t t0 = now_ms();
    snap_rows(s.c[0], s.id[0], &s.t, 2000000);
    uint64_t took = now_ms() - t0;
    status_snap(s.L, &b);
    uint64_t win = now_ms() - ta;
    if (log_has(s.R, "snapshot received from node"))
        die("the snapshot was in before the window of the large insert ended: the test proves nothing");
    uint64_t k5 = b.kind5_bytes - a.kind5_bytes, k2 = b.kind2_bytes - a.kind2_bytes;
    uint64_t one_bucket = rate * (win + 50) / 1000 + (256u << 10); /* PL_BULK_CHUNK */
    if (k2 + k5 <= one_bucket)
        die("a large insert of 2000000 rows during a snapshot: kinds 2 and 5 moved %" PRIu64 " + %" PRIu64
            " bytes in %" PRIu64 " ms, no more than one bucket at rebuild_mb_s passes (%" PRIu64
            "): kind 5 holds kind 2", k2, k5, win, one_bucket);
    if (!k5)
        die("no byte of the snapshot moved on kind 5 during the large insert (%" PRIu64 " ms)", win);
    await_log(s.R, "(snaphold)", 120000, "the snapshot never arrived");
    size_t nf;
    uint64_t bytes = snap_verify_held(s.R, 1, &nf);
    log_line(s.R, "snapshot received from node", line, sizeof line);
    const char *in = strstr(line, " bytes in ");
    double secs = in ? strtod(in + 10, NULL) : 0;
    double least = (double)bytes / (double)rate;
    if (secs < least * 0.9)
        die("%" PRIu64 " bytes moved in %.1f s at rebuild_mb_s 2 (at least %.1f s)", bytes, secs, least);
    snap_close(&s);
    stop_all();
    printf("  a large insert of 2000000 rows took %" PRIu64 " ms during a snapshot of %" PRIu64 " bytes (%.1f s at"
           " 2 MB/s); in its %" PRIu64 " ms window kind 2 moved %" PRIu64 " and kind 5 %" PRIu64 " bytes, more than"
           " one bucket's %" PRIu64 "\n", took, bytes, secs, win, k2, k5, one_bucket);
}

/* snaplost: the losses of a transfer's control frames. The first request names a newer set version (the hook): the
 * leader refuses it as stale and is asked again (a make past the link-down timer is snapxfer's). The DONE of a data
 * file is lost to a cut
 * connection after the receiver had the file whole: the sender begins it again, and the receiver must neither count
 * it twice nor call an incomplete copy received (F1). The receiver's DONE 0 is lost: the source, waiting for it,
 * releases its copy after its timer (3 s here) instead of holding it and a rebuild_max slot for 6 hours (F2). */
static void scen_snaplost(void)
{
    scenario("snaplost");
    for (int i = 0; i < 3; i++)
        penv[i] = "TSDB_REPLD_TEST=snapdownms=2000,snapwaitdonems=3000";
    struct snapset s;
    snap_setup(1, 200000, &s);
    penv[s.R] = "TSDB_REPLD_TEST=snaphold,snapcutdone,snapnodone,snapstalereq";
    start(s.R);
    await_log(s.R, "(snapstalereq)", 15000, "the replica back past the keep cap never asked");
    await_log(s.L, "is refused as stale", 15000, "a request of another set version was served");
    await_log(s.R, "(snaphold)", 40000, "the replica never received the whole snapshot");
    uint64_t t0 = now_ms();
    if (!log_has(s.R, "(snapcutdone)"))
        die("no DONE of a file was lost to a cut connection: the test proves nothing");
    size_t nf = 0;
    uint64_t bytes = snap_verify_held(s.R, 1, &nf);
    struct rsnap_stats sr;
    status_snap(s.R, &sr);
    if (sr.received != 1 || sr.failed != 0)
        die("STATUS of the receiver: %" PRIu64 " received, %" PRIu64 " failed (want 1, 0): the file begun again after"
            " its lost DONE broke the first copy", sr.received, sr.failed);
    char needle[160];
    snprintf(needle, sizeof needle, "snapshot made for node %" PRIu32 ":", ids[s.R]);
    if (log_has(s.L, "stayed down") || log_count(s.L, needle) != 1)
        die("the leader made %d snapshots for one served request (want 1)", log_count(s.L, needle));
    await_log(s.L, "never said it had the last file", 15000, "the leader kept waiting for a DONE that was lost");
    await_released(s.L, 1, 5000);
    printf("  a stale request refused; a file begun again after its lost DONE"
           " counted once (%zu files, %" PRIu64 " bytes, whole); the source freed %.1f s after the copy was in although"
           " its DONE was lost\n", nf, bytes, (double)(now_ms() - t0) / 1000);
    snap_close(&s);
    stop_all();
}

/* snapstall: a source that stalls while it stays the leader (the hook: the first ignores GO) is left by the receiver
 * when nothing arrives for its stall timer (3 s here), which asks again; a receiver killed while its source waits
 * for its DONE (lost, the hook) releases the source after the link-down timer (2 s here), well before the 60 s of
 * the DONE timer. Each release here has no other path that would end it. */
static void scen_snapstall(void)
{
    scenario("snapstall");
    for (int i = 0; i < 3; i++)
        penv[i] = "TSDB_REPLD_TEST=snapsrcstall,snapdownms=2000";
    struct snapset s;
    snap_setup(1, 0, &s);
    penv[s.R] = "TSDB_REPLD_TEST=snaphold,snapstallms=3000,snapnodone";
    start(s.R);
    await_log(s.R, "(snaphold)", 40000, "the replica never received the snapshot");
    if (!log_has(s.L, "(snapsrcstall)") || !log_has(s.R, "nothing arrived for"))
        die("the receiver of a stalled source did not leave it (stalled: %d)", log_has(s.L, "(snapsrcstall)"));
    size_t nf;
    snap_verify_held(s.R, 1, &nf);
    char needle[160];
    snprintf(needle, sizeof needle, "snapshot made for node %" PRIu32 ":", ids[s.R]);
    if (log_count(s.L, needle) != 2)
        die("the leader made %d snapshots (want 2: the stalled one and the one asked again)", log_count(s.L, needle));
    usleep(500000); /* the source waits for the DONE that is not sent */
    char sub[32];
    snprintf(sub, sizeof sub, "v1");
    if (dir_count(s.L, sub, SNAP_PREFIX) < 1)
        die("the leader released its copy before the receiver's link went down: the test proves nothing");
    stop(s.R, SIGKILL);
    uint64_t t0 = now_ms();
    await_log(s.L, "stayed down", 10000, "a source whose receiver is gone was not released");
    await_released(s.L, 1, 5000);
    snap_close(&s);
    stop_all();
    printf("  a stalled source left after the stall timer and asked again; a source whose receiver died released"
           " after %.1f s\n", (double)(now_ms() - t0) / 1000);
}

/* ---- snapshot install (r4-xferinst; server/snapinst_run.c, cvol_install, R4 plan D5, D6, D18) */

/* n rows (at most 200) into plant on its leader, every 7th a null, flushed when asked; *count += n */
static void snap_more(struct snapset *s, size_t n, int flush, uint64_t *count)
{
    int64_t tv[200];
    float vv[200];
    uint32_t nb = TSDB_NULL_F32_BITS;
    for (size_t j = 0; j < n; j++) {
        tv[j] = s->t++;
        vv[j] = (float)j * 0.5f;
        if (j % 7 == 3)
            memcpy(&vv[j], &nb, 4);
    }
    int rc = tsdbc_insert_series(s->c[0], s->id[0], tv, vv, n);
    if (rc != 0)
        die("a write of %zu rows to plant: %s", n, ers(rc));
    if (flush && (rc = tsdbc_flush(s->c[0])) != 0)
        die("flush: %s", ers(rc));
    *count += n;
}

/* R away again past the keep cap: killed, seven flushed segments a second apart, a commit after them */
static void snap_away(struct snapset *s, uint64_t *count)
{
    stop(s->R, SIGKILL);
    await_isr(0, "plant", 2, 10000, "a replica killed");
    for (int r = 0; r < 7; r++) {
        snap_more(s, 100, 1, count);
        sleep(1);
    }
    snap_more(s, 1, 0, count);
}

/* the fence F and the old fence K of server i's last "snapshot installed" line (0 when none) */
static int snap_installed(int i, uint64_t *f, uint64_t *k, double *secs)
{
    char line[4096];
    log_line(i, "snapshot installed: P", line, sizeof line);
    const char *a = strstr(line, "REPL fence "), *b = strstr(line, "(it was "), *c = strstr(line, ", in ");
    if (!a || !b || !c)
        return 0;
    *f = strtoull(a + 11, NULL, 10);
    *k = strtoull(b + 8, NULL, 10);
    if (secs)
        *secs = strtod(c + 5, NULL);
    return 1;
}

/* the state/holdopens files of every server: while they exist the metadata leader proposes no REPLICA_OPEN */
static void hold_opens(int on)
{
    for (int i = 0; i < 3; i++) {
        char hold[PATH_MAX + 96];
        server_dir(i, hold, sizeof hold);
        strcat(hold, "/state/holdopens");
        FILE *h = on ? fopen(hold, "w") : NULL;
        if (on ? (!h || fclose(h) != 0) : (unlink(hold) != 0 && errno != ENOENT))
            die("%s: %s", hold, strerror(errno));
    }
}

/* snapcatch: R away for ten flushed segments past repl_retain_s under writes, back: it is sent a snapshot, installs
 * it (closing its open engine), opens again, catches up and joins the ISR; every replica then holds the same rows,
 * nulls included, and no acknowledged write is lost. The install's close is
 * delayed (snapclosedelay) to hold REPLICA_OPEN back meanwhile: the installed copy must not open before the group
 * recorded its generation (mutant snapservebeforeopen). Caught up, R asks again (snapask): a copy whose P is at or
 * below its log end is refused, never installed (mutant snapinstallstale: R's log would go back to P). */
static void scen_snapcatch(void)
{
    scenario("snapcatch");
    for (int i = 0; i < 3; i++) /* hold_opens() acts only where the server reads the files */
        envs[i] = "hold_opens_file=1";
    struct snapset s;
    snap_setup(1, 0, &s);
    uint64_t n[REP_NAMES] = {702, 0, 0, 0};
    for (int r = 0; r < 3; r++) { /* ten flushes with R away, three of them with nulls */
        snap_more(&s, 100, 1, &n[0]);
        sleep(1);
    }
    penv[s.R] = "TSDB_REPLD_TEST=snapclosedelay=1500,snapask,snapblind";
    start(s.R);
    uint64_t t0 = now_ms();
    int held = 0, opens = 0;
    while (!log_has(s.R, "snapshot installed: P")) { /* writes go on while the copy is made, sent and installed */
        if (now_ms() - t0 > 60000)
            die("the replica back past the keep cap installed no snapshot in 60 s");
        if (!held && log_has(s.R, "(snapclosedelay)")) {
            hold_opens(1);
            held = 1;
            opens = log_count(s.R, "(plant): open as the");
        }
        snap_more(&s, 20, 0, &n[0]);
        usleep(100000);
    }
    if (!held)
        die("the install came without its close delay");
    for (int k = 0; k < 25; k++) { /* 2.5 s with no REPLICA_OPEN: the installed copy waits */
        if (log_count(s.R, "(plant): open as the") != opens)
            die("the replica opened its installed copy before the group recorded its open generation");
        snap_more(&s, 10, 0, &n[0]);
        usleep(100000);
    }
    hold_opens(0);
    await_isr(0, "plant", 3, 60000, "the replica that installed a snapshot joins the ISR");
    for (int k = 0; k < 5; k++)
        snap_more(&s, 100, k == 2, &n[0]);
    uint64_t f = 0, kf = 0;
    double secs = 0;
    if (!snap_installed(s.R, &f, &kf, &secs))
        die("no install line with a fence");
    /* caught up, R asks for a copy as if it were behind: its P is at or below R's log end */
    char ask[PATH_MAX + 64];
    server_dir(s.R, ask, sizeof ask);
    strcat(ask, "/snapask");
    FILE *a = fopen(ask, "w");
    if (!a || fclose(a) != 0)
        die("%s: %s", ask, strerror(errno));
    /* without the driver's check the copy reaches the install, which closes the volume and then refuses a P below
     * the commit floor (snap_install's D6 check); a P between the floor and the log end it would install */
    int floor_refused = log_count(s.R, "is below this replica's commit floor");
    /* R may have installed twice before it joined the ISR: with repl_retain_s 2 a slow install finds the leader past
     * its copy's P and asks again, before it is in the ISR. Only installs after the ask count. */
    int installs = log_count(s.R, "snapshot installed: P");
    t0 = now_ms();
    while (!log_has(s.R, "is stale and not installed")) {
        if (log_count(s.R, "snapshot installed: P") != installs)
            die("a replica in the ISR installed a copy at or below its log end (its log went back to P)");
        if (log_count(s.R, "is below this replica's commit floor") != floor_refused)
            die("a replica in the ISR took a copy at or below its log end to the install (its volume closed for it)");
        if (now_ms() - t0 > 60000)
            die("the caught-up replica's request was neither refused as stale nor installed in 60 s");
        snap_more(&s, 10, 0, &n[0]);
        usleep(100000);
    }
    unlink(ask);
    sleep(2);
    if (log_count(s.R, "snapshot installed: P") != installs)
        die("a replica in the ISR installed a copy at or below its log end (its log went back to P)");
    await_isr(0, "plant", 3, 60000, "the replica that refused a stale copy stays in the ISR");
    /* the log passes P between the check before the close and the close (planted: snapblind hides the log end from that
     * check): the check after the close, on the stopped driver's end, refuses the copy (mutant snapnoendafter) */
    char blind[PATH_MAX + 64];
    server_dir(s.R, blind, sizeof blind);
    strcat(blind, "/snapblind");
    FILE *b = fopen(blind, "w");
    if (!b || fclose(b) != 0 || !(a = fopen(ask, "w")) || fclose(a) != 0)
        die("%s, %s: %s", blind, ask, strerror(errno));
    t0 = now_ms();
    while (!log_has(s.R, "is stale and not installed after the close")) {
        if (log_count(s.R, "snapshot installed: P") != installs)
            die("a replica in the ISR installed a copy at or below its log end (its log went back to P)");
        if (log_count(s.R, "is below this replica's commit floor") != floor_refused)
            die("a replica in the ISR took a copy at or below the log end its stopped driver left to the install");
        if (now_ms() - t0 > 60000)
            die("a copy at or below the log end, unseen before the close, was not refused after it in 60 s");
        snap_more(&s, 10, 0, &n[0]);
        usleep(100000);
    }
    unlink(ask);
    unlink(blind);
    await_isr(0, "plant", 3, 60000, "the replica that refused a stale copy after its close joins the ISR again");
    if (log_count(s.R, "snapshot installed: P") != installs)
        die("a replica in the ISR installed a copy at or below its log end (its log went back to P)");
    struct rsnap_stats sr;
    status_snap(s.R, &sr);
    if (sr.refused_stale < 2 || sr.installed != (uint64_t)installs)
        die("STATUS of the receiver: installed %" PRIu64 ", refused_stale %" PRIu64 " (want %d and >= 2)", sr.installed,
            sr.refused_stale, installs);
    double last_s = status_install_s(s.R);
    if (last_s <= 0)
        die("STATUS of the receiver: snap.install_last_s %.3f after an install", last_s);
    snap_close(&s);
    stop_all();
    rep_same(n, "snapcatch: after a clean stop");
    printf("  a replica ten segments behind installed a snapshot in %.1f s (REPL fence %" PRIu64 "), waited for its"
           " open generation, caught up and joined the ISR; a stale copy was refused before and after the close (STATUS:"
           " last install %.3f s); all three hold the same %" PRIu64
           " rows\n", secs, f, last_s, n[0]);
}

static void touch_plant(int i, uint32_t num);

/* snapdiverged: a caught-up replica whose volume turns DIVERGED (planted: the DIVERGED file a failed digest writes)
 * stops, asks the leader for a snapshot, installs it and comes back without the flag: it joins the ISR, stops no more
 * and holds the leader's rows (mutant snapkeepdiverged: the flag carried into the installed copy) */
/* the ISR of `name` is n members and the leader's (server `lead`) latest ISR request asked for n and is committed:
 * no shrink is in flight that an ISR read before it would miss */
static void isr_settled(int lead, const char *name, uint32_t n, int ms, const char *what)
{
    uint64_t t0 = now_ms();
    for (;;) {
        char line[4096];
        unsigned m = 0;
        unsigned long long asked = 0;
        uint64_t v = 0;
        log_line(lead, "asks for an ISR of", line, sizeof line);
        const char *a = strstr(line, "asks for an ISR of");
        if (a && sscanf(a, "asks for an ISR of %u members (ISR version %llu", &m, &asked) == 2 && m == n &&
            isr_of(lead, name, &v) == n && v >= asked)
            return;
        if (now_ms() - t0 > (uint64_t)ms)
            die("%s (server %d's latest ISR request: \"%s\")", what, lead, a ? a : "none");
        usleep(100000);
    }
}

static void scen_snapdiverged(void)
{
    scenario("snapdiverged");
    struct snapset s;
    snap_setup(1, 0, &s);
    uint64_t n[REP_NAMES] = {702, 0, 0, 0};
    penv[s.R] = "TSDB_REPLD_TEST=plantdiverge";
    start(s.R);
    await_log(s.R, "snapshot installed: P", 60000, "the replica back past the keep cap installed no snapshot");
    await_isr(0, "plant", 3, 60000, "the replica that installed a snapshot joins the ISR");
    snap_more(&s, 100, 1, &n[0]);
    touch_plant(s.R, 1);
    await_log(s.R, "stopped: the volume is DIVERGED", 20000, "the planted DIVERGED did not stop the replica");
    uint64_t t0 = now_ms();
    while (log_count(s.R, "snapshot installed: P") < 2) {
        if (now_ms() - t0 > 60000)
            die("the DIVERGED replica was not rebuilt by a snapshot in 60 s");
        snap_more(&s, 20, 0, &n[0]);
        usleep(100000);
    }
    await_isr(0, "plant", 3, 60000, "the rebuilt replica joins the ISR");
    for (int k = 0; k < 3; k++) {
        snap_more(&s, 100, k == 1, &n[0]);
        sleep(1);
    }
    if (log_count(s.R, "stopped: the volume is DIVERGED") != 1)
        die("the rebuilt replica stopped as DIVERGED again: the flag was carried into the fresh copy");
    await_isr(0, "plant", 3, 10000, "the rebuilt replica stays in the ISR");
    /* again with no write after the plant: the diverged replica's log already reaches the leader's P, which must still
     * rebuild it (mutant snapdivlogend: refused as stale for good) */
    int stale0 = log_count(s.R, "is stale and not installed");
    touch_plant(s.R, 1);
    for (t0 = now_ms(); log_count(s.R, "stopped: the volume is DIVERGED") < 2; usleep(100000))
        if (now_ms() - t0 > 20000)
            die("the second planted DIVERGED did not stop the replica");
    for (t0 = now_ms(); log_count(s.R, "snapshot installed: P") < 3; usleep(100000))
        if (now_ms() - t0 > 60000)
            die("the DIVERGED replica whose log reaches the leader's P was not rebuilt by a snapshot in 60 s");
    /* the copy that rebuilt it may lie above its log end (the ISR shrink's record): a refusal before it is the bug */
    if (log_count(s.R, "is stale and not installed") != stale0)
        die("the DIVERGED replica whose log reaches the leader's P refused a copy as stale");
    await_isr(0, "plant", 3, 60000, "the replica rebuilt with no write meanwhile joins the ISR");
    snap_more(&s, 100, 0, &n[0]);
    if (log_count(s.R, "stopped: the volume is DIVERGED") != 2)
        die("the rebuilt replica stopped as DIVERGED again: the flag was carried into the fresh copy");
    /* the ISR of 3 above may be the one before the leader dropped the stopped replica (slow servers): the last write
     * is on every replica only once the leader's latest ISR request is for 3 members and committed */
    isr_settled(0, "plant", 3, 60000, "the rebuilt replica rejoins the ISR after the last write");
    snap_close(&s);
    stop_all();
    rep_same(n, "snapdiverged: after a clean stop");
    printf("  a DIVERGED replica was rebuilt by a snapshot (also with its log at the leader's P), joined the ISR and"
           " holds the same %" PRIu64 " rows\n", n[0]);
}

/* snapkill: the receiver killed at snap-received (files in, nothing installed) and at snap-swapped (after the swap's
 * root fsync): restarted, it finishes the swap or asks again, joins the ISR and holds the leader's rows */
static void scen_snapkill(void)
{
    scenario("snapkill");
    struct snapset s;
    snap_setup(1, 0, &s);
    uint64_t n[REP_NAMES] = {702, 0, 0, 0};
    static const char *const pts[3] = {"snap-received", "snap-swapped", "snap-halfswap"};
    static char env[3][64];
    for (int p = 0; p < 3; p++) {
        if (p)
            snap_away(&s, &n[0]);
        snprintf(env[p], sizeof env[p], "TSDB_CRASH_AT=%s", pts[p]);
        penv[s.R] = env[p];
        start(s.R);
        int st = await_exit(s.R, 60000);
        if (st != 99)
            die("the receiver armed at %s ended with %d, not 99", pts[p], st);
        penv[s.R] = NULL;
        int got = log_count(s.R, "snapshot received from node");
        start(s.R);
        await_isr(0, "plant", 3, 60000, "the receiver restarted after its crash joins the ISR");
        if (dir_count(s.R, "v1.snap", "") >= 0 || dir_count(s.R, "v1.old", "") >= 0)
            die("after the crash at %s the receiver still has v1.snap or v1.old", pts[p]);
        /* between the renames only snap_leftovers mends it (v1.old back or the copy in): never by a copy fetched again
         * (mutant snapnoleftovers) */
        if (p == 2 && log_count(s.R, "snapshot received from node") != got)
            die("after the crash at %s the receiver fetched a copy again instead of finishing the swap", pts[p]);
        snap_more(&s, 50, 0, &n[0]);
    }
    snap_close(&s);
    stop_all();
    rep_same(n, "snapkill: after a clean stop");
    printf("  a receiver killed at snap-received, at snap-swapped and between the swap's renames came back, joined the"
           " ISR and holds the rows\n");
}

/* snappower: crashfs under the receiver's directory, a power loss right after each step of its install (before the
 * close, after the verify, after SNAPDONE, after the swap): restarted, it holds the old or the new directory, joins
 * the ISR and every replica holds the same rows */
static void scen_snappower(void)
{
    scenario("snappower");
    const char *so = getenv("CRASHFS_SO") ? getenv("CRASHFS_SO") : "./build/libcrashfs.so";
    if (access(so, F_OK) != 0)
        die("no %s (make build/libcrashfs.so): snappower cannot run, and must not pass as skipped", so);
#if defined(__SANITIZE_ADDRESS__)
    printf("  skipped: crashfs cannot be preloaded into an AddressSanitizer build\n");
    return;
#endif
    struct snapset s;
    snap_setup(1, 0, &s);
    uint64_t n[REP_NAMES] = {702, 0, 0, 0};
    static char env[4][PATH_MAX * 2 + 200];
    char d[PATH_MAX + 80];
    server_dir(s.R, d, sizeof d);
    for (int k = 0; k < 4; k++) {
        if (k)
            snap_away(&s, &n[0]);
        snprintf(env[k], sizeof env[k],
                 "LD_PRELOAD=%s CRASHFS_ROOT=%s CRASHFS_TEAR=1 CRASHFS_REWRITE=old TSDB_REPLD_TEST=snappowerat=%d", so, d,
                 k);
        penv[s.R] = env[k];
        start(s.R);
        int st = await_exit(s.R, 90000);
        if (st != 99)
            die("the receiver with a power loss after install step %d ended with %d, not 99", k, st);
        penv[s.R] = NULL;
        start(s.R);
        await_isr(0, "plant", 3, 90000, "the receiver back from a power loss joins the ISR");
        if (dir_count(s.R, "v1.snap", "") >= 0 || dir_count(s.R, "v1.old", "") >= 0)
            die("after the power loss at install step %d the receiver still has v1.snap or v1.old", k);
        snap_more(&s, 50, 0, &n[0]);
    }
    snap_close(&s);
    stop_all();
    rep_same(n, "snappower: after a clean stop");
    printf("  a power loss after each of the four install steps: the receiver came back, joined and holds the rows\n");
}

/* snapfence: the receiver's close for the install waits 5 s (snapclosedelay) and the leader dies in it: the new
 * leader's FENCE reaches the receiver before its old REPL is read as keep, so the stale copy is refused or the
 * installed REPL holds the raised fence (mutant snapstalekeep: keep read before the close, the fence lowered) */
static void scen_snapfence(void)
{
    scenario("snapfence");
    struct snapset s;
    snap_setup(1, 0, &s);
    struct meta_volume v;
    if (!vol_rec(s.O, "plant", &v))
        die("no record of plant");
    uint64_t e0 = v.epoch;
    penv[s.R] = "TSDB_REPLD_TEST=snapclosedelay=5000,snapleftoversrace";
    start(s.R);
    await_log(s.R, "(snapclosedelay)", 60000, "the receiver never got to the install");
    snap_close(&s);
    stop(s.L, SIGKILL);
    uint64_t t0 = now_ms(), e1 = e0;
    for (; now_ms() - t0 < 30000; usleep(100000))
        if (vol_rec(s.O, "plant", &v) && v.epoch > e0 && server_of(v.leader) == s.O) {
            e1 = v.epoch;
            break;
        }
    if (e1 == e0)
        die("no new leader of plant after the leader died (epoch %" PRIu64 ")", e0);
    uint64_t f = 0, kf = 0;
    t0 = now_ms();
    while (!snap_installed(s.R, &f, &kf, NULL) || f < e1) {
        if (snap_installed(s.R, &f, &kf, NULL) && f < e1)
            die("the receiver installed a REPL with fence %" PRIu64 " (kept %" PRIu64 ") below the epoch %" PRIu64
                " a FENCE raised it to during its close", f, kf, e1);
        if (now_ms() - t0 > 60000) {
            if (log_has(s.R, "is not installed: this replica is fenced at") && isr_of(s.O, "plant", NULL) == 2)
                break; /* refused, then caught up from the new leader's log with no snapshot */
            die("the receiver neither installed with the raised fence nor refused the stale copy and joined");
        }
        usleep(100000);
    }
    await_isr(s.O, "plant", 2, 60000, "the receiver joins the new leader's ISR");
    /* the old leader's copy (P of epoch e0 or below) met a fence of e1 after the close: refused, never installed
     * (requirement 1; mutant snapnofence installs it with the raised fence kept, which the loop above lets pass) */
    if (!log_has(s.R, "is not installed: this replica is fenced at"))
        die("the old leader's copy was installed on a receiver fenced at %" PRIu64 " above its epoch, not refused", e1);
    /* snapleftoversrace: the refused copy was removed before the volume went back (mutant snapdropafter: removed by
     * the worker during the prepare's leftovers, which refuses the volume until a restart) */
    if (log_has(s.R, "(snapleftoversrace)"))
        die("the refused copy was removed by the snapshot worker during the prepare after the volume went back");
    stop_all();
    printf("  a FENCE during the install's close: the stale copy was refused%s (epoch %" PRIu64 " -> %" PRIu64 ")\n",
           f >= e1 ? " and the new leader's copy installed with the raised fence" : "", e0, e1);
}

/* keepfloor: below the caps the leader keeps every segment a replica away has not acked (design-cluster.md 8.3). The
 * replica is killed, the leader writes and flushes segments past it, and the replica back must catch up from them,
 * join the ISR again and never be told it needs a snapshot (r3d review: keep_ignores_peers survived every test). */
static void scen_keepfloor(void)
{
    scenario("keepfloor");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1;
    uint64_t rows = 0;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    rows++;
    await_isr(0, "plant", 3, 5000, "every replica up");
    int R = (L + 1) % 3;
    stop(R, SIGKILL);
    await_isr(0, "plant", 2, 10000, "a replica killed");
    int64_t t = 10000;
    for (int k = 0; k < 5; k++) {
        int64_t tv[100];
        float vv[100];
        for (int j = 0; j < 100; j++)
            tv[j] = t++, vv[j] = (float)j;
        if ((rc = tsdbc_insert_series(c, id, tv, vv, 100)) != 0)
            die("a write with a replica away: %s", ers(rc));
        rows += 100;
        if ((rc = tsdbc_flush(c)) != 0)
            die("flush: %s", ers(rc));
    }
    if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0) /* a commit after the last flush: a save of the keep */
        die("a write with a replica away: %s", ers(rc));
    rows++;
    struct timespec s1 = {1, 0};
    nanosleep(&s1, NULL);
    int nw = wal_count(L, 1);
    if (nw < 5)
        die("the leader keeps %d WAL segments, not the 5 flushed ones a replica away has not acked", nw);
    start(R);
    await_isr(0, "plant", 3, 30000, "the killed replica back and caught up from the kept segments");
    if (log_has(R, "it needs a snapshot"))
        die("a replica back within the keep caps was told it needs a snapshot");
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    uint64_t wantr[REP_NAMES] = {rows, 0, 0, 0};
    rep_same(wantr, "after a clean stop");
    printf("  with a replica away the leader keeps its %d flushed segments; the replica back catches up from them and"
           " holds the leader's rows\n", nw);
}

static void metrics_get(int port, char *buf, size_t n);

static uint64_t metrics_vol_u64(int port, uint32_t num, const char *metric)
{
    static char buf[1 << 20];
    metrics_get(port, buf, sizeof buf);
    char key[128];
    snprintf(key, sizeof key, "\n%s{volume=\"%" PRIu32 "\",path=\"", metric, num);
    const char *l = strstr(buf, key);
    const char *e = l ? strstr(l + 1, "\"} ") : NULL;
    if (!e)
        die("metrics port %d: missing %s for volume %" PRIu32, port, metric, num);
    return strtoull(e + 3, NULL, 10);
}

/* reopenhold: a replica killed with a COMMIT marker in its log whose file it has not staged starts its core with the
 * durable end below that marker (repl_durable.hold), never at its log end. It did start at the log end: its first ACK
 * after the restart claimed the whole log, the leader's keep bound passed the marker, the segment and the link the
 * file is served from went, and the replica asked for the file in vain for the rest of the run (jepsen-cluster kill,
 * kv and classes, 2026-11-18: "it needs a snapshot", the ISR never whole again). R does not stage the large write's
 * file (dropbulk) and sends no FETCH (nofetch); its log passes the marker and the leader seals the marker's segment;
 * R is killed, and back its syncs wait 4 s (syncpause: its ACKs carry the durable end its core opened with) and it
 * fetches only 5 s late (fetchlate): time enough for the leader, which goes on writing, to save its keep bound by a
 * false ACK and drop the segment. Also checks that a held replica does not spin WAL syncs while waiting for a missing
 * file, and wakes promptly via IN_WAKE once the fetched file is staged. Mutant opennohold. */
static void scen_reopenhold(void)
{
    scenario("reopenhold");
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=noclock";
        start(i);
        penv[i] = NULL;
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id0 = rep_series(c, rep_names[0], "plant", 30000), id2 = rep_series(c, rep_names[2], "plant", 30000);
    uint64_t n[REP_NAMES] = {0};
    int64_t t = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id0, &t, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    n[0]++;
    await_isr(0, "plant", 3, 10000, "every replica up");
    int R = (L + 1) % 3;
    stop(R, SIGKILL);
    await_isr(0, "plant", 2, 10000, "a replica killed");
    penv[R] = "TSDB_REPLD_TEST=noclock,dropbulk,nofetch";
    xargs[R] = "--metrics-port auto";
    start(R);
    penv[R] = NULL;
    xargs[R] = NULL;
    int mport_r = th_mport;
    await_open_gen(L, "plant", R, 2, 0);
    struct rep_writer wb = {cports[L], id2, 2000000000, 0, 0, 0, 100000, 0}; /* above wal_max_batch_rows */
    rep_write_thread(&wb);
    if (wb.rc != 0)
        die("a large write with a replica that drops its file: %s", ers(wb.rc));
    n[2] += 100000;
    for (uint64_t t0 = now_ms(); !log_has(R, "withholds the FETCH");) {
        if (now_ms() - t0 > 20000)
            die("the replica that dropped the large write's file did not find its COMMIT marker without it in 20 s");
        struct timespec ms = {0, 50000000};
        nanosleep(&ms, NULL);
    }
    /* the leader seals the marker's segment, and R's log passes its end. The large write flushed the memtable before
     * its marker, and a flush of an empty memtable starts no segment: a row first, or the marker's segment stays open
     * until an idle seal that the 1.5 s below may miss, and the leader drops it only after R fetched (the mutant
     * survived 2 runs of 3) */
    t += 1000;
    if ((rc = tsdbc_insert_series(c, id0, &t, &val, 1)) != 0)
        die("a write after the large one: %s", ers(rc));
    n[0]++;
    if ((rc = tsdbc_flush(c)) != 0)
        die("flush: %s", ers(rc));
    for (int k = 0; k < 20; k++) {
        t += 1000;
        if ((rc = tsdbc_insert_series(c, id0, &t, &val, 1)) != 0)
            die("a write after the large one: %s", ers(rc));
        n[0]++;
    }
    /* while R is held by the missing COMMIT file and idle, do_sync must back off instead of spinning fdatasync() */
    struct timespec ms200 = {0, 200000000};
    nanosleep(&ms200, NULL);
    uint64_t ws0 = metrics_vol_u64(mport_r, num, "tsdb_wal_syncs_total");
    struct timespec s15 = {1, 500000000};
    nanosleep(&s15, NULL);
    uint64_t ws1 = metrics_vol_u64(mport_r, num, "tsdb_wal_syncs_total");
    if (ws1 - ws0 > 2)
        die("a held replica spun WAL syncs while waiting for a missing file: +%" PRIu64 " syncs in 1.5 s", ws1 - ws0);
    stop(R, SIGKILL);
    penv[R] = "TSDB_REPLD_TEST=noclock,fetchlate,syncpause";
    start(R);
    penv[R] = NULL;
    /* writes go on meanwhile: the leader saves its floor, and with it the keep bound, only as the commit point moves */
    for (uint64_t t0 = now_ms(); isr_of(L, "plant", NULL) != 3 || !log_has(R, "fetches");) {
        t += 1000;
        if ((rc = tsdbc_insert_series(c, id0, &t, &val, 1)) != 0)
            die("a write while the replica is back: %s", ers(rc));
        n[0]++;
        if (log_has(L, "it needs a snapshot"))
            die("the leader dropped the file of a COMMIT marker that a restarted replica had not staged: it needs a "
                "snapshot");
        if (now_ms() - t0 > 60000)
            die("the replica restarted without the large write's file: ISR %" PRIu32 " members, fetched %d, after "
                "60000 ms", isr_of(L, "plant", NULL), log_has(R, "fetches"));
        struct timespec ms = {0, 50000000};
        nanosleep(&ms, NULL);
    }
    struct timespec s1 = {1, 0};
    nanosleep(&s1, NULL);
    if (log_has(L, "it needs a snapshot"))
        die("the leader dropped the file of a COMMIT marker that a restarted replica had not staged: it needs a "
            "snapshot");
    t += 1000;
    if ((rc = tsdbc_insert_series(c, id0, &t, &val, 1)) != 0)
        die("a write with every replica back: %s", ers(rc));
    n[0]++;
    await_isr(0, "plant", 3, 30000, "every replica back");
    /* IN_WAKE: when a replica in the ISR drops a bulk file and fetches it (with noclock so no NOW marker can mask a
     * missed wake), staging must wake do_sync() promptly (well below the 1 s retry timer) without spinning WAL syncs */
    stop(R, SIGKILL);
    await_isr(0, "plant", 2, 10000, "a replica killed for wake check");
    penv[R] = "TSDB_REPLD_TEST=noclock,dropbulk";
    xargs[R] = "--metrics-port auto";
    start(R);
    penv[R] = NULL;
    xargs[R] = NULL;
    mport_r = th_mport;
    await_open_gen(L, "plant", R, 4, 0);
    t += 1000;
    if ((rc = tsdbc_insert_series(c, id0, &t, &val, 1)) != 0)
        die("a write before dropbulk wake check: %s", ers(rc));
    n[0]++;
    await_isr(0, "plant", 3, 10000, "replica ready for dropbulk wake");
    int drops0 = log_count(R, "received and not staged (dropbulk)"), fetches0 = log_count(R, "fetches");
    uint64_t ws2 = metrics_vol_u64(mport_r, num, "tsdb_wal_syncs_total");
    struct rep_writer wb2 = {cports[L], id2, 3000000000, 0, 0, 0, 66000, 0}; /* above wal_max_batch_rows */
    pthread_t thw;
    if (pthread_create(&thw, NULL, rep_write_thread, &wb2) != 0)
        die("pthread_create");
    uint64_t t_fetch = 0;
    for (uint64_t t0 = now_ms(); !__atomic_load_n(&wb2.done, __ATOMIC_ACQUIRE);) {
        if (!t_fetch && log_count(R, "fetches") > fetches0)
            t_fetch = now_ms();
        if (now_ms() - t0 > 30000)
            die("dropbulk wake write did not finish in 30 s");
        struct timespec ms = {0, 5000000};
        nanosleep(&ms, NULL);
    }
    uint64_t wake_ms = t_fetch ? now_ms() - t_fetch : 0;
    pthread_join(thw, NULL);
    uint64_t ws3 = metrics_vol_u64(mport_r, num, "tsdb_wal_syncs_total");
    if (wb2.rc != 0)
        die("a large write with dropbulk wake check: %s", ers(wb2.rc));
    n[2] += 66000;
    if (log_count(R, "received and not staged (dropbulk)") <= drops0 || log_count(R, "fetches") <= fetches0)
        die("dropbulk wake check did not exercise drop + fetch on server %d", R);
    if (isr_of(L, "plant", NULL) != 3)
        die("replica dropped from ISR during dropbulk fetch/wake (wake %" PRIu64 " ms)", wake_ms);
    if (wake_ms > 800)
        die("dropbulk fetch + IN_WAKE took %" PRIu64 " ms (expected < 800 ms; IN_WAKE missed?)", wake_ms);
    if (ws3 - ws2 > 10)
        die("dropbulk fetch/wake spun WAL syncs: +%" PRIu64, ws3 - ws2);
    tsdbc_close(c);
    stop_all();
    rep_same(n, "after a clean stop");
    printf("  a replica killed with a COMMIT marker whose file it had not staged acknowledges below it when back; the"
           " leader keeps the file, the replica fetches it and holds the leader's rows (held syncs +%" PRIu64
           ", dropbulk IN_WAKE %" PRIu64 " ms)\n", ws1 - ws0, wake_ms);
}

/* the part files in server i's copy of volume 1 (retired ones too: a merge leaves its sources under retired_) */
static int part_count(int i)
{
    char dir[PATH_MAX + 80], v[PATH_MAX + 120];
    server_dir(i, dir, sizeof dir);
    snprintf(v, sizeof v, "%s/v1", dir);
    DIR *d = opendir(v);
    if (!d)
        die("opendir %s: %s", v, strerror(errno));
    int n = 0;
    struct dirent *e;
    while ((e = readdir(d))) {
        size_t l = strlen(e->d_name);
        n += l > 5 && !strcmp(e->d_name + l - 5, ".part") && strncmp(e->d_name, "tmp_", 4) &&
             strncmp(e->d_name, "stage_", 6) && strncmp(e->d_name, "retired_", 8);
    }
    closedir(d);
    return n;
}

/* the newest WAL segment of server i's copy of volume 1: one more for each flush (no promotion in between) */
static uint64_t wal_newest(int i)
{
    char dir[PATH_MAX + 80], v[PATH_MAX + 120];
    server_dir(i, dir, sizeof dir);
    snprintf(v, sizeof v, "%s/v1", dir);
    DIR *d = opendir(v);
    if (!d)
        die("opendir %s: %s", v, strerror(errno));
    uint64_t hi = 0, seq;
    struct dirent *e;
    while ((e = readdir(d)))
        if (sscanf(e->d_name, "wal_%" SCNx64 ".log", &seq) == 1 && seq > hi)
            hi = seq;
    closedir(d);
    return hi;
}

/* The idle seal (design-cluster.md 5.3, D7): with flushes 10 min apart, an idle leader flushes its memtable after
 * idle_seal_ms (1 s) and its next NOW marker starts a new segment, so the replicas seal and flush theirs too. */
static void scen_idleseal(void)
{
    scenario("idleseal");
    for (int i = 0; i < 3; i++) {
        xargs[i] = "--flush-interval-ms 600000";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t tv[100];
    float vv[100];
    for (int j = 0; j < 100; j++)
        tv[j] = 1000 + j, vv[j] = (float)j;
    if ((rc = tsdbc_insert_series(c, id, tv, vv, 100)) != 0)
        die("a write: %s", ers(rc));
    uint64_t t0 = now_ms(), took[3] = {0, 0, 0};
    for (int left = 3; left;) {
        if (now_ms() - t0 > 6000)
            die("an idle volume's rows were not in parts on every server 6 s after the write (leader %d: %d parts,"
                " replicas %d, %d)", L, part_count(L), part_count((L + 1) % 3), part_count((L + 2) % 3));
        for (int i = 0; i < 3; i++)
            if (!took[i] && part_count(i) > 0)
                took[i] = now_ms() - t0, left--;
        struct timespec ms50 = {0, 50000000};
        nanosleep(&ms50, NULL);
    }
    printf("  an idle volume is in parts after %" PRIu64 " ms on the leader, %" PRIu64 " and %" PRIu64
           " ms on the replicas (idle_seal_ms 1000, flushes 10 min apart)\n",
           took[L], took[(L + 1) % 3], took[(L + 2) % 3]);
    /* the cost: a write every 2 s is a flush every 2 s (the parts of an hour, before merges) */
    uint64_t w0 = wal_newest(L);
    for (int k = 0; k < 10; k++) {
        int64_t t = 5000 + k;
        if ((rc = tsdbc_insert_series(c, id, &t, vv, 1)) != 0)
            die("a write: %s", ers(rc));
        struct timespec s2 = {2, 0};
        nanosleep(&s2, NULL);
    }
    int made = (int)(wal_newest(L) - w0);
    printf("  a write every 2 s: %d flushes in 20 s on the leader (about %d parts an hour, before merges)\n", made,
           made * 180);
    if (made < 5)
        die("a write every 2 s made %d flushes in 20 s: the idle seal does not flush", made);
    /* and an idle volume's WAL grows by its NOW markers alone */
    char dir[PATH_MAX + 80], wp[PATH_MAX + 160];
    server_dir(L, dir, sizeof dir);
    struct stat st0, st1;
    struct timespec s5 = {5, 0};
    /* The last write's seal may still be under way (slow under ASan): its segment then goes once flushed and the NOW
     * marker starts the next one. Measure a segment that stays for the whole 5 s; a third roll is a failure. */
    for (int tries = 0;; tries++) {
        uint64_t w = wal_newest(L);
        snprintf(wp, sizeof wp, "%s/v1/wal_%016" PRIx64 ".log", dir, w);
        if (stat(wp, &st0) == 0 && (nanosleep(&s5, NULL), stat(wp, &st1)) == 0)
            break;
        int e = errno;
        if (e != ENOENT || tries == 2 || wal_newest(L) == w)
            die("stat %s: %s", wp, strerror(e));
        printf("  the newest segment rolled while measured (the last seal still running); again\n");
    }
    printf("  an idle leader's WAL grows by %lld bytes in 5 s (NOW markers; about %lld KB an hour)\n",
           (long long)(st1.st_size - st0.st_size), (long long)(st1.st_size - st0.st_size) * 720 / 1024);
    tsdbc_close(c);
    stop_all();
    uint64_t wantr[REP_NAMES] = {110, 0, 0, 0};
    rep_same(wantr, "after a clean stop");
}

/* shipstall (the r3d review's M2): a large write over ten partitions with a replica stopped (SIGSTOP: its links stay
 * up, no DONE comes back) waits for its files under one deadline per COMMIT, and not past the moment the stopped
 * replica leaves the ISR; it used to wait 30 s per file (mutant shipperfile). Running again, the replica fetches what
 * it missed, joins the ISR and holds the leader's rows. */
static void scen_shipstall(void)
{
    scenario("shipstall");
    for (int i = 0; i < 3; i++)
        start(i);
    init_isr_lag_ms = 500; /* the stopped replica leaves the ISR well before the ship deadline (3 s) */
    init_cluster(0, 600);
    init_isr_lag_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts1 = 1000;
    float val1 = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts1, &val1, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    await_isr(0, "plant", 3, 5000, "every replica up");

    enum { BIG = 100000 };
    int64_t *ts = malloc(BIG * sizeof *ts);
    float *val = malloc(BIG * sizeof *val);
    if (!ts || !val)
        die("out of memory");
    for (int j = 0; j < BIG; j++) /* ten days from 2024-01-01: ten partitions, ten files in one COMMIT */
        ts[j] = 1704067200000LL + 8640LL * j, val[j] = (float)(j % 977);
    int R = (L + 1) % 3;
    pause_server(R, 1);
    uint64_t t0 = now_ms();
    if ((rc = tsdbc_insert_series(c, id, ts, val, BIG)) != 0)
        die("a large write with a replica stopped: %s", ers(rc));
    uint64_t took = now_ms() - t0;
    free(ts);
    free(val);
    /* the write ends once the stopped replica has left the ISR (isr_lag_ms 500, then a heartbeat and the metadata
     * group: about 1 s), not at the ship deadline (3 s: mutant shipnoisr) nor later (r3d-isr review M6: a bound of
     * 15 s let a deadline five times too long pass) */
    if (took > 2500)
        die("a large write over ten partitions with a replica stopped took %" PRIu64 " ms (the ship wait did not end"
            " when the replica left the ISR?)", took);
    await_isr(0, "plant", 2, 10000, "a replica stopped under a large write");
    pause_server(R, 0);
    await_isr(0, "plant", 3, 30000, "the stopped replica continued");
    uint64_t rows = 1 + BIG;
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    uint64_t wantr[REP_NAMES] = {rows, 0, 0, 0};
    rep_same(wantr, "after a clean stop");
    printf("  a large write with a replica stopped took %" PRIu64 " ms; the replica caught up and holds its rows\n",
           took);
}

/* replindet (D12): a replicated write whose outcome is unknown (appended on the leader, which then stops, deposing
 * itself, before the commit point passed it) never reaches the client as TSDB_ERR_INDETERMINATE (-110) or as a
 * refusal: tsdbd closes the connection without an answer, and the client sees a lost connection (TSDB_ERR_IO). */
static void scen_replindet(void)
{
    scenario("replindet");
    for (int i = 0; i < 3; i++) {
        /* every node may lead: rep_series' retries reach the new writer between its swap and M_WRITER, where a
         * write once deposed the fresh leader for good (the volume then answered UNAVAILABLE until a restart) */
        penv[i] = "TSDB_REPLD_TEST=promotewait";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    tsdbc_close(c);
    int R1 = (L + 1) % 3, R2 = (L + 2) % 3;
    pause_server(R1, 1); /* no replica acknowledges: the commit point stops below the next write */
    pause_server(R2, 1);
    struct rep_writer w = {cports[L], id, 2000, 1, 0, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0)
        die("pthread_create");
    struct timespec ms500 = {0, 500000000};
    nanosleep(&ms500, NULL);
    if (__atomic_load_n(&w.done, __ATOMIC_ACQUIRE))
        die("a write with both replicas paused was answered: %s", ers(w.rc));
    stop(L, SIGTERM); /* the driver deposes the leader: the waiting write's outcome is unknown */
    pthread_join(th, NULL);
    if (w.rc != TSDB_ERR_IO)
        die("a write of unknown outcome was answered %d (%s), not with a closed connection", w.rc, ers(w.rc));
    pause_server(R1, 0);
    pause_server(R2, 0);
    stop_all();
    printf("  a write left of unknown outcome by its leader's stop gets a closed connection, never an answer\n");
}

/* The rows of `id` in [from, to) on server i, once its answer is not UNAVAILABLE (a promotion under way): -1 after ms */
static int rows_in(int i, tsdb_sid id, int64_t from, int64_t to, int ms)
{
    uint64_t t0 = now_ms();
    for (;;) {
        tsdbc *c = client(i);
        nrows = 0;
        int rc = tsdbc_query_raw(c, id, from, to, count_rows, NULL);
        tsdbc_close(c);
        if (rc == 0)
            return nrows;
        if (now_ms() - t0 > (uint64_t)ms)
            return -1;
        usleep(50000);
    }
}

/* Says which of the rows t0, t0 + 1000, ... (n of them) server i lacks: a failed check names what it lost */
static unsigned char *seen_rows;
static int seen_n;
static int64_t seen_t0;
static int mark_rows(void *ctx, const int64_t *ts, const float *v, size_t n)
{
    (void)ctx, (void)v;
    for (size_t k = 0; k < n; k++) {
        int64_t j = (ts[k] - seen_t0) / 1000;
        if (j >= 0 && j < seen_n && (ts[k] - seen_t0) % 1000 == 0)
            seen_rows[j] = 1;
    }
    return 0;
}

static void missing_rows(int i, tsdb_sid id, int64_t t0, int n)
{
    seen_rows = calloc((size_t)n + 1, 1);
    if (!seen_rows)
        return;
    seen_n = n, seen_t0 = t0;
    tsdbc *c = client(i);
    int rc = tsdbc_query_raw(c, id, t0, t0 + 1000LL * n, mark_rows, NULL);
    tsdbc_close(c);
    printf("  server %d (query %s) lacks:", i, ers(rc));
    for (int j = 0; j < n; j++)
        if (!seen_rows[j])
            printf(" row %d (ts %" PRId64 ")", j, (int64_t)(t0 + 1000LL * j));
    printf("\n");
    fflush(stdout);
    free(seen_rows);
    seen_rows = NULL;
}

/* design-cluster.md 6.2-6.3 (r3e-failover): the leader of a replicated volume is killed under writes. The Raft leader
 * sees it down (node_timeout, then its lease's end), fences the ISR, and a replica leads at epoch e+1; every
 * acknowledged write is there; the new leader takes writes; the old leader restarts as a replica (led e: it never
 * resumes), is cut by the new leader's history, catches up and holds the same rows as the others. */
static void scen_failover(void)
{
    scenario("failover");
    strict_reads = 1; /* every read on the leader (D5), as in production */
    for (int i = 0; i < 3; i++)
        start(i);
    /* isr_lag_ms well above unanswered_ms (1000): the killed old leader, which the promotion keeps in the ISR as
     * unanswered, must leave it by unanswered_ms, not by the lag rule (design-cluster.md 6.2; mutant keepunanswered) */
    init_isr_lag_ms = 10000;
    init_cluster(0, 600);
    init_isr_lag_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "fo", 3, &num)) != 0 || num != 1)
        die("volume add fo: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "fo", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "fo", &v))
        die("no record of fo");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of fo is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "fo", 30000);
    tsdbc_close(c);
    await_isr(0, "fo", 3, 30000, "every replica in the ISR before the kill");
    struct rep_writer w = {cports[L], id, 1000000, 1000000, 0, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0)
        die("pthread_create");
    uint64_t t0 = now_ms();
    while (__atomic_load_n(&w.acked, __ATOMIC_ACQUIRE) < 300) {
        if (now_ms() - t0 > 30000)
            die("the writer had %d rows acknowledged in 30 s", __atomic_load_n(&w.acked, __ATOMIC_ACQUIRE));
        usleep(10000);
    }
    signal_child(pids[L], SIGKILL);
    uint64_t tk = now_ms();
    if (await_exit(L, 5000) < 0)
        die("server %d did not die of SIGKILL", L);
    pthread_join(th, NULL);
    int acked = __atomic_load_n(&w.acked, __ATOMIC_ACQUIRE);
    int via = (L + 1) % 3, Nw = -1;
    for (;;) {
        if (vol_rec(via, "fo", &v) && v.leader != ids[L] && v.epoch > e0) {
            Nw = server_of(v.leader);
            break;
        }
        if (now_ms() - tk > 30000)
            die("no new leader of fo 30 s after its leader was killed (epoch %" PRIu64 ", leader %u)", v.epoch, v.leader);
        usleep(20000);
    }
    if (v.epoch != e0 + 1 || Nw < 0 || Nw == L)
        die("the new record of fo: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v.epoch, e0, v.leader);
    uint64_t tr = now_ms();
    /* the promotion kept the dead old leader in the ISR, unanswered: it goes after unanswered_ms (1 s), well before the
     * lag rule's 10 s would take it (until then it holds the new leader's commit point, its EPOCH marker first) */
    {
        uint64_t version;
        while (isr_of(via, "fo", &version) != 2) {
            if (now_ms() - tr > 4000)
                die("the killed old leader was still in the ISR of fo %" PRIu64 " ms after the promotion (unanswered_ms "
                    "1000, isr_lag_ms 10000)", now_ms() - tr);
            usleep(50000);
        }
        printf("  the killed old leader left the ISR %" PRIu64 " ms after the record named the new leader\n",
               now_ms() - tr);
    }
    /* a replica answers reads from what it applied (it may lag the commit point): the new leader's own answer counts,
     * once it leads (after its EPOCH marker is committed and applied, and the engine reopened as the writer) */
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(Nw, lead, 1, 30000);
    uint64_t tl = now_ms();
    int got = rows_in(Nw, id, 1000000, 1000000 + 1000LL * acked, 30000); /* [from, to): rows 0 .. acked - 1 */
    if (got != acked) {
        missing_rows(Nw, id, 1000000, acked);
        die("the new leader (server %d) holds %d of the %d acknowledged rows", Nw, got, acked);
    }
    printf("  leader %d killed after %d acknowledged rows: the record names server %d at epoch %" PRIu64 " after %" PRIu64
           " ms, which leads after %" PRIu64 " ms and holds every one\n", L, acked, Nw, v.epoch, tr - tk, tl - tk);
    /* the new leader takes writes */
    c = client(Nw);
    tsdbc_set_retry(c, 10000);
    int64_t ts = 9000000;
    float val = 7;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write to the new leader: %s", ers(rc));
    tsdbc_close(c);
    /* a write to the other replica is MOVED to the new leader, and a client with a budget follows it there */
    int R = 3 - L - Nw;
    c = client(R);
    ts = 9001000;
    insert_expect_moved(c, id, ts, val, 1, v.leader, v.epoch, "a write to a replica after the failover");
    tsdbc_set_retry(c, 10000);
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write that follows MOVED from server %d: %s", R, ers(rc));
    tsdbc_close(c);
    /* the old leader restarts as a replica and rejoins; it never resumes leading: writes to it are MOVED */
    start(L);
    await_isr(via, "fo", 3, 60000, "the old leader back in the ISR");
    c = client(L);
    ts = 9002000;
    insert_expect_moved(c, id, ts, val, 1, v.leader, v.epoch, "a write to the old leader after it rejoined");
    tsdbc_close(c);
    int total = rows_in(Nw, id, 0, INT64_MAX / 2, 10000);
    if (total < acked + 2)
        die("the new leader holds %d rows after the rejoin, fewer than the %d acknowledged", total, acked + 2);
    stop_all();
    uint64_t wantr[REP_NAMES] = {0};
    wantr[0] = (uint64_t)total;
    rep_same(wantr, "after the failover");
    printf("  the old leader came back as a replica, was cut and caught up: every server holds the same %d rows\n",
           total);
}

/* failoverkeep: a replica keeps its flushed segments under the retention caps past its commit floor (design-cluster.md
 * 8.3), so that, promoted, it can serve a member that was away. R is killed, the leader L writes and flushes segments
 * past it (B, the other replica, flushes them too and its floor passes them), L is killed and B leads; R back must catch
 * up from B's segments and join the ISR, never be told it needs a snapshot (jepsen-cluster partition, fHdR4T: a
 * promoted replica had unlinked what a laggard still needed). Mutant replicadropsfloor (the floor alone again). */
static void scen_failoverkeep(void)
{
    scenario("failoverkeep");
    /* two witnesses (servers 3, 4): five voters, so the metadata group keeps a majority with L and R down, and the
     * volume's replicas are on servers 0-2 */
    for (int i = 3; i < 5; i++) {
        is_witness[i] = 1;
        xargs[i] = "--peer-port 0";
        char wdir[PATH_MAX + 160];
        snprintf(wdir, sizeof wdir, "%s/n%d", base, i);
        if (mkdir(wdir, 0755) != 0)
            die("mkdir %s: %s", wdir, strerror(errno));
    }
    for (int i = 0; i < 5; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 5; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters (two witnesses)");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "fk", 3, &num)) != 0 || num != 1)
        die("volume add fk: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "fk", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "fk", &v))
        die("no record of fk");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of fk is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "fk", 30000);
    int64_t ts = 1000;
    float val = 1;
    uint64_t rows = 0;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    rows++;
    await_isr(L, "fk", 3, 5000, "every replica up");
    int R = (L + 1) % 3, B = (L + 2) % 3;
    stop(R, SIGKILL);
    await_isr(L, "fk", 2, 10000, "a replica killed");
    int64_t t = 10000;
    for (int k = 0; k < 5; k++) {
        int64_t tv[100];
        float vv[100];
        for (int j = 0; j < 100; j++)
            tv[j] = t++, vv[j] = (float)j;
        if ((rc = tsdbc_insert_series(c, id, tv, vv, 100)) != 0)
            die("a write with a replica away: %s", ers(rc));
        rows += 100;
        if ((rc = tsdbc_flush(c)) != 0)
            die("flush: %s", ers(rc));
    }
    if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0) /* a commit after the last flush: B's floor passes them */
        die("a write with a replica away: %s", ers(rc));
    rows++;
    tsdbc_close(c);
    struct timespec s1 = {1, 0};
    nanosleep(&s1, NULL);
    int nb = wal_count(B, 1);
    stop(L, SIGKILL);
    uint64_t tk = now_ms();
    for (;;) {
        if (vol_rec(B, "fk", &v) && v.leader == ids[B] && v.epoch > e0)
            break;
        if (now_ms() - tk > 30000)
            die("server %d was not promoted 30 s after the leader was killed (epoch %" PRIu64 ", leader %u)", B, v.epoch,
                v.leader);
        usleep(20000);
    }
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(B, lead, 1, 30000);
    start(R);
    uint64_t t0 = now_ms();
    for (;;) {
        if (log_has(R, "it needs a snapshot"))
            die("the replica away during the failover was told it needs a snapshot by the promoted leader (which held %d"
                " WAL segments before the failover)", nb);
        int in = 0;
        if (vol_rec(B, "fk", &v))
            for (uint32_t k = 0; k < v.nisr; k++)
                in |= v.isr[k] == ids[R];
        if (in)
            break;
        if (now_ms() - t0 > 30000)
            die("the replica away during the failover did not join the new leader's ISR in 30 s");
        usleep(50000);
    }
    c = client(B);
    tsdbc_set_retry(c, 10000);
    t++;
    if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0)
        die("a write to the new leader: %s", ers(rc));
    rows++;
    if ((uint64_t)rows_of(c, id) != rows)
        die("the new leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    start(L);
    await_isr(B, "fk", 3, 60000, "the old leader back");
    stop_all();
    uint64_t wantr[REP_NAMES] = {rows, 0, 0, 0};
    rep_same(wantr, "after a clean stop");
    printf("  the promoted replica had kept %d WAL segments past its floor; the member away caught up from them and "
           "every server holds the same %" PRIu64 " rows\n", nb, rows);
}

static long long file_len(const char *path)
{
    struct stat st;
    return stat(path, &st) == 0 ? (long long)st.st_size : -1;
}

/* classfailover (D17): at the default caps (repl_retain_s 1800) a class switch on the new leader after a failover waits
 * only until every member acknowledges in the new epoch and has its old segments in parts and named in RSTATE `kept`:
 * a few seconds. Before D17 a replica's replay start was its log start, which the keep caps hold up to repl_retain_s
 * back, and the switch waited (CLS_DEFER) that long. The replicas' flushed segments stay (the caps), and every member
 * holds the same rows at the end. Mutant replaystartlog (the replay start is the log start again). */
static void scen_classfailover(void)
{
    scenario("classfailover");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "cf", 3, &num)) != 0 || num != 1)
        die("volume add cf: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "cf", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "cf", &v))
        die("no record of cf");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of cf is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "cf", 30000);
    await_isr(L, "cf", 3, 30000, "every replica up");
    int64_t t = 1000;
    uint64_t rows = 0;
    for (int k = 0; k < 4; k++) { /* flushed segments on every member before the failover */
        int64_t tv[100];
        float vv[100];
        for (int j = 0; j < 100; j++)
            tv[j] = t++, vv[j] = (float)j;
        if ((rc = tsdbc_insert_series(c, id, tv, vv, 100)) != 0)
            die("a write before the failover: %s", ers(rc));
        rows += 100;
        if ((rc = tsdbc_flush(c)) != 0)
            die("flush: %s", ers(rc));
    }
    /* a slow fresh series: its first flush (flush_interval_ms 5 s) gives it a long class (CLASSES on every member) */
    tsdb_sid slow = rep_series(c, rep_names[3], "cf", 30000);
    int64_t ts[200];
    float val[200];
    for (int j = 0; j < 200; j++)
        ts[j] = 3600000LL * j, val[j] = (float)j;
    if ((rc = tsdbc_insert_series(c, slow, ts, val, 200)) != 0)
        die("insert of the slow series: %s", ers(rc));
    uint64_t srows = 200;
    tsdbc_close(c);
    char cls[PATH_MAX + 120];
    for (int i = 0; i < 3; i++) {
        snprintf(cls, sizeof cls, "%s/n%d/v1/CLASSES", base, i);
        uint64_t tc = now_ms();
        while (file_len(cls) <= 0) {
            if (now_ms() - tc > 30000)
                die("the slow series got no class of its own on server %d (no %s)", i, cls);
            usleep(100000);
        }
    }
    struct timespec s1 = {1, 0};
    nanosleep(&s1, NULL);
    stop(L, SIGKILL);
    int B = -1;
    uint64_t tk = now_ms();
    for (;;) {
        for (int i = 0; i < 3 && B < 0; i++)
            if (i != L && vol_rec(i, "cf", &v) && v.epoch > e0 && server_of(v.leader) == i)
                B = i;
        if (B >= 0)
            break;
        if (now_ms() - tk > 30000)
            die("no server was promoted 30 s after the leader was killed");
        usleep(20000);
    }
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(B, lead, 1, 30000);
    start(L);
    await_isr(B, "cf", 3, 60000, "the old leader back");
    uint64_t t_isr = now_ms(); /* every member acknowledges in the new epoch from here */
    snprintf(cls, sizeof cls, "%s/n%d/v1/CLASSES", base, B);
    long long len0 = file_len(cls);
    c = client(B);
    tsdbc_set_retry(c, 10000);
    /* the slow series gets much faster: the next flush moves it to class 0, a switch whose T must lie past every row a
     * member may replay, which waits for the replay floor (CLS_DEFER) and is measured again at each flush */
    int64_t st = 3600000LL * 200;
    while (file_len(cls) <= len0) {
        if (now_ms() - t_isr > 60000)
            die("a class switch on the new leader waited more than 60 s after every member was back in its ISR (the "
                "replay floor stayed below the epoch: %s %lld bytes)", cls, file_len(cls));
        for (int j = 0; j < 200; j++)
            ts[j] = st + j, val[j] = (float)j;
        if ((rc = tsdbc_insert_series(c, slow, ts, val, 200)) != 0)
            die("a write to the new leader: %s", ers(rc));
        st += 200;
        srows += 200;
        usleep(500000);
    }
    uint64_t waited = now_ms() - t_isr;
    if ((uint64_t)rows_of(c, id) != rows || (uint64_t)rows_of(c, slow) != srows)
        die("the new leader reads %d and %d rows, not %" PRIu64 " and %" PRIu64, rows_of(c, id), rows_of(c, slow), rows,
            srows);
    tsdbc_close(c);
    for (int i = 0; i < 3; i++) /* (the leader lets go of what every replica holds: eng_leader_keep) */
        if (i != B && wal_count(i, 1) < 2)
            die("replica %d keeps %d WAL segments of cf: the flushed ones went before the caps (repl_retain_s 1800)", i,
                wal_count(i, 1));
    stop_all();
    uint64_t wantr[REP_NAMES] = {rows, 0, 0, srows};
    rep_same(wantr, "after a clean stop");
    printf("  after a failover at the default caps a class switch waited %" PRIu64 " ms after every member was back in "
           "the ISR; the replicas keep their flushed segments and every server holds the same rows\n", waited);
}

/* D13: an engine failure (EIO on a WAL fdatasync, crashfs) of one replica of a cluster volume stops that volume
 * there, quiesced and reported LOCAL_FAULT in the server's heartbeat; the server itself goes on (its root answers)
 * and exits cleanly on SIGTERM. Without D13 tsdbd exits with status 1 on any failed volume outside a domain. */
static void scen_replfail(void)
{
    scenario("replfail");
    /* the ASan runtime must come first in the library list: with crashfs preloaded the server refuses to start */
#if defined(__SANITIZE_ADDRESS__)
    printf("  skipped: crashfs cannot be preloaded into an AddressSanitizer build\n");
    return;
#elif defined(__has_feature)
#if __has_feature(address_sanitizer)
    printf("  skipped: crashfs cannot be preloaded into an AddressSanitizer build\n");
    return;
#endif
#endif
    const char *so = getenv("CRASHFS_SO") ? getenv("CRASHFS_SO") : "./build/libcrashfs.so";
    static char pe[3][PATH_MAX * 3 + 256];
    char mark[3][PATH_MAX + 80];
    for (int i = 0; i < 3; i++) {
        char dir[PATH_MAX + 80];
        server_dir(i, dir, sizeof dir);
        if (mkdir(dir, 0755) != 0 && errno != EEXIST)
            die("mkdir %s: %s", dir, strerror(errno));
        snprintf(mark[i], sizeof mark[i], "%s/eio-n%d", base, i);
        snprintf(pe[i], sizeof pe[i],
                 "LD_PRELOAD=%s CRASHFS_ROOT=%s CRASHFS_MODE=eio CRASHFS_EIO_ONLY=wal_ CRASHFS_EIO_ON=fdatasync "
                 "CRASHFS_MARK=%s",
                 so, dir, mark[i]);
        penv[i] = pe[i];
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    tsdbc_close(c);
    int R = (L + 1) % 3;
    signal_child(pids[R], SIGUSR2); /* crashfs: the next fdatasync of a wal_ file there fails with EIO */
    struct rep_writer w = {cports[L], id, 2000, 1000000, 0, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0)
        die("pthread_create");
    uint64_t t0 = now_ms();
    while (access(mark[R], F_OK) != 0) {
        if (now_ms() - t0 > 30000)
            die("no fdatasync of server %d's log failed in 30 s", R);
        usleep(20000);
    }
    if (await_exit(R, 2000) >= 0)
        die("server %d exited on its cluster volume's engine failure (D13: only the volume stops)", R);
    /* the heartbeat of R reports the volume LOCAL_FAULT to the metadata leader */
    int fault = 0;
    for (t0 = now_ms(); !fault && now_ms() - t0 < 10000; usleep(100000))
        for (int i = 0; i < 3 && !fault; i++) {
            struct view vw;
            if (i == R)
                continue;
            view(i, &vw);
            for (uint32_t k = 0; k < vw.st.nheard; k++)
                if (vw.st.heard[k].id == ids[R])
                    for (uint32_t j = 0; j < vw.st.heard[k].nvols; j++)
                        if (vw.st.heard[k].vols[j].v.volume == num &&
                            vw.st.heard[k].vols[j].v.health == CL_HEALTH_LOCAL_FAULT)
                            fault = 1;
        }
    if (!fault)
        die("server %d's heartbeat never reported volume %" PRIu32 " LOCAL_FAULT", R, num);
    tsdbc *cr = client(R); /* the root of R still answers */
    tsdb_sid any;
    if ((rc = tsdbc_series(cr, "replfail.none", 0, &any)) != TSDB_ERR_NOTFOUND)
        die("a lookup in server %d's root after its volume failed: %s", R, ers(rc));
    tsdbc_close(cr);
    stop(R, SIGTERM); /* a clean stop: the failed volume is no failure of the server */
    stop(L, SIGTERM);
    pthread_join(th, NULL);
    stop_all();
    printf("  a replica whose engine failed stops that volume only, reports it LOCAL_FAULT and stops cleanly\n");
}

/* crashfs is preloaded into these scenarios' servers: 0 when it can be, else why not (printed as the skip) */
static const char *crashfs_skip(const char **so)
{
    *so = getenv("CRASHFS_SO") ? getenv("CRASHFS_SO") : "./build/libcrashfs.so";
#if defined(__SANITIZE_ADDRESS__)
    return "crashfs cannot be preloaded into an AddressSanitizer build";
#elif defined(__has_feature)
#if __has_feature(address_sanitizer)
    return "crashfs cannot be preloaded into an AddressSanitizer build";
#endif
#endif
    if (access(*so, F_OK) != 0) {
#ifdef __linux__
        die("no %s (make build/libcrashfs.so): the scenario cannot run, and must not pass as skipped", *so);
#else
        return "no libcrashfs.so";
#endif
    }
    return NULL;
}

/* the heartbeat of server R reports volume num LOCAL_FAULT to the others within 10 s */
static void await_local_fault(int R, uint32_t num, int nserv)
{
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 10000; usleep(100000))
        for (int i = 0; i < nserv; i++) {
            struct view vw;
            if (i == R || pids[i] <= 0)
                continue;
            view(i, &vw);
            int fault = 0;
            for (uint32_t k = 0; k < vw.st.nheard; k++)
                if (vw.st.heard[k].id == ids[R])
                    for (uint32_t j = 0; j < vw.st.heard[k].nvols; j++)
                        fault |= vw.st.heard[k].vols[j].v.volume == num &&
                                 vw.st.heard[k].vols[j].v.health == CL_HEALTH_LOCAL_FAULT;
            view_free(&vw);
            if (fault)
                return;
        }
    die("server %d's heartbeat never reported volume %" PRIu32 " LOCAL_FAULT", R, num);
}

/* ackdurable (M6, design 5.1: a write is committed once it is durable on every member of the ISR): writes are
 * acknowledged, then the power fails (crashfs: what was never synced is gone) on both replicas at their next
 * append and then on the leader. Each replica, restarted with the leader still down (so it cannot catch up from the
 * leader) and stopped cleanly, holds every acknowledged row, read in-process and read-only. Two witnesses keep the
 * metadata group's quorum while the data nodes are down, and learn the restarted replicas' new peer ports.
 * TSDB_REPLD_MUTANT=ackbeforesync (a replica reports its written end as durable without a sync) fails it. */
static void scen_ackdurable(void)
{
    scenario("ackdurable");
    const char *so, *skip = crashfs_skip(&so);
    if (skip) {
        printf("  skipped: %s\n", skip);
        return;
    }
    static char pe[3][PATH_MAX * 2 + 128];
    for (int i = 0; i < 3; i++) {
        char dir[PATH_MAX + 80];
        server_dir(i, dir, sizeof dir);
        if (mkdir(dir, 0755) != 0 && errno != EEXIST)
            die("mkdir %s: %s", dir, strerror(errno));
        snprintf(pe[i], sizeof pe[i], "LD_PRELOAD=%s CRASHFS_ROOT=%s CRASHFS_REWRITE=old", so, dir);
        penv[i] = pe[i];
    }
    for (int i = 3; i < 5; i++) {
        is_witness[i] = 1;
        xargs[i] = "--peer-port 0"; /* a witness takes the peer port 7071 unless told */
        char wdir[PATH_MAX + 80];
        server_dir(i, wdir, sizeof wdir); /* no --dir makes it; the state directory goes inside */
        if (mkdir(wdir, 0755) != 0)
            die("mkdir %s: %s", wdir, strerror(errno));
    }
    for (int i = 0; i < 5; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 5; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters, two of them witnesses");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    enum { ACKED = 40 };
    for (int j = 0; j < ACKED; j++) {
        int64_t ts = 1000 + 1000LL * j;
        float val = (float)j;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d with every replica up: %s", j, ers(rc));
    }
    tsdbc_close(c);
    /* at once (a replica's flush would make the rows durable in a part): the power fails at each replica's next
     * tracked operation, the append of the next write, which therefore is never acknowledged */
    int R1 = (L + 1) % 3, R2 = (L + 2) % 3;
    signal_child(pids[R1], SIGUSR2);
    signal_child(pids[R2], SIGUSR2);
    struct rep_writer w1 = {cports[L], id, 1000 + 1000LL * ACKED, 1, 0, 0, 0, 0};
    pthread_t th1, th2;
    if (pthread_create(&th1, NULL, rep_write_thread, &w1) != 0)
        die("pthread_create");
    for (int r = 0; r < 2; r++) {
        int R = r ? R2 : R1, st = await_exit(R, 15000);
        if (st != 99)
            die("server %d ended with status %d after the power loss, expected 99 (crashfs)", R, st);
    }
    signal_child(pids[L], SIGUSR2); /* and the leader's, at its next append */
    struct rep_writer w2 = {cports[L], id, 1000 + 1000LL * (ACKED + 1), 1, 0, 0, 0, 0};
    if (pthread_create(&th2, NULL, rep_write_thread, &w2) != 0)
        die("pthread_create");
    int st = await_exit(L, 15000);
    if (st != 99)
        die("server %d (the leader) ended with status %d after the power loss, expected 99 (crashfs)", L, st);
    pthread_join(th1, NULL);
    pthread_join(th2, NULL);
    if (w1.rc == 0 || w2.rc == 0)
        die("a write was acknowledged with both replicas down");
    /* one at a time: a restarted server has a new peer port, which it tells the group (the witnesses) */
    int R[2] = {R1, R2};
    for (int r = 0; r < 2; r++) {
        start(R[r]);
        await_open_gen(3, "plant", R[r], 2, 0);
    }
    for (int r = 0; r < 2; r++)
        stop(R[r], SIGTERM);
    for (int r = 0; r < 2; r++) {
        char dir[PATH_MAX + 80], vd[PATH_MAX + 120];
        server_dir(R[r], dir, sizeof dir);
        snprintf(vd, sizeof vd, "%s/v1", dir);
        uint64_t rows, h;
        if ((rc = cvol_digest(vd, rep_names, 1, &rows, &h)) != 0)
            die("open %s read-only: %s", vd, ers(rc));
        if (rows < ACKED || rows > ACKED + 2)
            die("after a power loss replica %d holds %" PRIu64 " rows, %d were acknowledged (at most 2 more were sent)",
                R[r], rows, ACKED);
    }
    stop_all();
    printf("  %d acknowledged writes survive a power loss of both replicas and then of the leader, on each replica\n",
           ACKED);
}

/* a write on its own connection; afterwards `after` is what a lookup in the root on that same connection gave */
struct wf_writer {
    tsdbc *c;
    tsdb_sid id;
    int64_t ts;
    int rc, after, done;
};
static void *wf_write_thread(void *a)
{
    struct wf_writer *w = a;
    int64_t ts = w->ts;
    float val = 5;
    w->rc = tsdbc_insert_series(w->c, w->id, &ts, &val, 1);
    tsdb_sid any;
    w->after = tsdbc_series(w->c, "writerfail.none", 0, &any);
    __atomic_store_n(&w->done, 1, __ATOMIC_RELEASE);
    return NULL;
}

/* writerfail (M5, D13 on the writer): the leader's engine fails (crashfs: EIO on its next fdatasync of a wal_ file:
 * a second write's) while a write waits for a paused replica. The driver deposes the writer: the outcome of both
 * writes is unknown (each went to the replicas), so their connections close without an answer (D12); the volume is
 * quiesced (UNAVAILABLE), the group promotes a replica at e+1 and writes and reads on the old leader are MOVED to it; the
 * server reports the volume LOCAL_FAULT, answers in its root, keeps its vote and its other
 * volumes (a later volume add commits and opens there) and stops cleanly. writerfail runs on strict reads (D5, the
 * production path), where routing refuses the failed volume's reads before its engine is asked, so the quiesce
 * itself is observed by writerfailq: the same run under TSDB_REPLICA_READS=1, whose routing lets a read of the failed
 * volume through to its engine (a replica's FENCED with a lease), so only the quiesce answers it UNAVAILABLE (then
 * MOVED by frame_put). TSDB_REPLD_MUTANT=nodepose fails both, noquiesce writerfailq. */
/* waits up to 30 s for server `via`'s copy of volume `name` to name a leader other than node `old` at an epoch above
 * e0 (a promotion, design-cluster.md 6.2); returns its server */
static int await_promoted(int via, const char *name, uint32_t old, uint64_t e0, struct meta_volume *v)
{
    for (uint64_t t0 = now_ms();; usleep(20000)) {
        if (vol_rec(via, name, v) && v->leader != old && v->epoch > e0)
            return server_of(v->leader);
        if (now_ms() - t0 > 30000)
            die("no new leader of %s 30 s after its leader %u failed it (epoch %" PRIu64 ", leader %u)", name, old,
                v->epoch, v->leader);
    }
}

static void writerfail_run(const char *name, int strict)
{
    scenario(name);
    const char *so, *skip = crashfs_skip(&so);
    if (skip) {
        printf("  skipped: %s\n", skip);
        return;
    }
    strict_reads = strict; /* 1: every read on the leader (D5), as in production; 0: the engine's own refusal */
    static char pe[3][PATH_MAX * 3 + 256];
    static char mark[3][PATH_MAX + 80];
    for (int i = 0; i < 3; i++) {
        char dir[PATH_MAX + 80];
        server_dir(i, dir, sizeof dir);
        if (mkdir(dir, 0755) != 0 && errno != EEXIST)
            die("mkdir %s: %s", dir, strerror(errno));
        snprintf(mark[i], sizeof mark[i], "%s/eio-n%d", base, i);
        snprintf(pe[i], sizeof pe[i],
                 "LD_PRELOAD=%s CRASHFS_ROOT=%s CRASHFS_MODE=eio CRASHFS_EIO_ONLY=wal_ CRASHFS_EIO_ON=fdatasync "
                 "CRASHFS_MARK=%s",
                 so, dir, mark[i]);
        penv[i] = pe[i];
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    int R1 = (L + 1) % 3;
    pause_server(R1, 1); /* the commit point stops below the next write (the other replica keeps the lease) */
    struct wf_writer w[2] = {{client(L), id, 5000, 0, 0, 0}, {client(L), id, 6000, 0, 0, 0}};
    pthread_t th[2];
    if (pthread_create(&th[0], NULL, wf_write_thread, &w[0]) != 0)
        die("pthread_create");
    struct timespec ms300 = {0, 300000000};
    nanosleep(&ms300, NULL);
    if (__atomic_load_n(&w[0].done, __ATOMIC_ACQUIRE))
        die("a write with a replica paused was answered: %s", ers(w[0].rc));
    signal_child(pids[L], SIGUSR2); /* crashfs: the leader's next fdatasync of a wal_ file (w[1]'s) fails with EIO */
    if (pthread_create(&th[1], NULL, wf_write_thread, &w[1]) != 0)
        die("pthread_create");
    uint64_t t0 = now_ms();
    while (access(mark[L], F_OK) != 0) {
        if (now_ms() - t0 > 30000)
            die("no fdatasync of server %d's log failed in 30 s", L);
        usleep(20000);
    }
    static const char *const which[2] = {"waiting for the commit point", "whose sync failed"};
    for (int k = 0; k < 2; k++) {
        for (t0 = now_ms(); !__atomic_load_n(&w[k].done, __ATOMIC_ACQUIRE); usleep(20000))
            if (now_ms() - t0 > 10000)
                die("the write %s on the failed writer was not ended in 10 s (the writer was not deposed)", which[k]);
        pthread_join(th[k], NULL);
        if (w[k].rc != TSDB_ERR_IO || w[k].after != TSDB_ERR_IO)
            die("the write %s on the failed writer got %d (%s), then its connection %d (%s): not a closed connection",
                which[k], w[k].rc, ers(w[k].rc), w[k].after, ers(w[k].after));
        tsdbc_close(w[k].c);
    }
    if (await_exit(L, 1000) >= 0)
        die("server %d exited on its cluster volume's engine failure (D13: only the volume stops)", L);
    pause_server(R1, 0);
    /* the failed volume: the group promotes a replica (reason FENCED, D13), writes and reads on L are MOVED to it
     * (reads too, D5: the failed volume answers nothing); the root answers */
    uint64_t e0 = v.epoch;
    int Nw = await_promoted((L + 1) % 3, "plant", ids[L], e0, &v);
    if (Nw < 0 || Nw == L || v.epoch != e0 + 1)
        die("the new record of plant: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v.epoch, e0, v.leader);
    tsdbc *c2 = client(L);
    ts = 7000;
    insert_expect_moved(c2, id, ts, val, 1, v.leader, v.epoch, "a write to the failed volume");
    tsdb_points p;
    rc = tsdbc_query_points(c2, id, INT64_MIN, INT64_MAX, &p); /* D5: reads go to the leader as well; writerfailq: the
                                                                  * quiesced engine's UNAVAILABLE, MOVED by frame_put */
    expect_moved_ep(c2, rc, 1, v.leader, v.epoch, "a read of the failed volume");
    tsdb_sid any;
    if ((rc = tsdbc_series(c2, "writerfail.none", 0, &any)) != TSDB_ERR_NOTFOUND)
        die("a lookup in server %d's root after its volume failed: %s", L, ers(rc));
    tsdbc_close(c2);
    tsdbc_close(c);
    await_local_fault(L, num, 3);
    /* its vote and its other volumes: a volume added now commits (L is one of three voters) and opens on L too */
    struct view vw;
    view(L, &vw);
    int voter = is_voter(&vw, ids[L]);
    view_free(&vw);
    if (!voter)
        die("server %d is no voter after its volume failed", L);
    if ((rc = vol_add((L + 2) % 3, "second", 3, &num)) != 0 || num != 2)
        die("volume add second: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen((L + 2) % 3, "second", i, 1, 0);
    /* the replicas are given no position past the failure: R1 has been resumed for a while (anything the driver still
     * shipped would have reached it), more writes were refused meanwhile, and each replica holds the acknowledged row
     * and at most the two whose outcome is unknown (5000, 6000), never a refused one */
    for (int k = 0; k < 5; k++) {
        tsdbc *c3 = client(L);
        ts = 8000 + k;
        insert_expect_moved(c3, id, ts, val, 1, v.leader, v.epoch, "a later write to the failed volume");
        tsdbc_close(c3);
        usleep(200000);
    }
    for (int i = 0; i < 3; i++)
        stop(i, SIGTERM); /* a clean stop: the failed volume is no failure of the server */
    for (int r = 0; r < 3; r++) {
        if (r == L)
            continue;
        char dir[PATH_MAX + 80], vd[PATH_MAX + 120];
        server_dir(r, dir, sizeof dir);
        snprintf(vd, sizeof vd, "%s/v1", dir);
        uint64_t rows, h;
        if ((rc = cvol_digest(vd, rep_names, 1, &rows, &h)) != 0)
            die("open %s read-only: %s", vd, ers(rc));
        if (rows < 1 || rows > 3)
            die("replica %d holds %" PRIu64 " rows: 1 was acknowledged, 3 written before the volume failed", r, rows);
    }
    stop_all();
    printf("  a leader whose engine failed closes the connections of the writes in flight, a replica leads at epoch "
           "%" PRIu64 ", the old leader answers writes and reads MOVED, keeps its root, its vote and its "
           "other volumes and stops cleanly; the replicas hold nothing "
           "written after the failure\n",
           v.epoch);
}

/* GET /metrics from a metrics port (--metrics-port auto): the reply in buf, which it NUL-terminates */
static void metrics_get(int port, char *buf, size_t n)
{
    int fd = socket(AF_INET, SOCK_STREAM | SOCK_CLOEXEC, 0);
    struct sockaddr_in sa = {.sin_family = AF_INET, .sin_port = htons((uint16_t)port)};
    inet_pton(AF_INET, "127.0.0.1", &sa.sin_addr);
    if (fd < 0 || port <= 0 || connect(fd, (struct sockaddr *)&sa, sizeof sa) != 0)
        die("connect to the metrics port %d: %s", port, strerror(errno));
    struct timeval tv = {10, 0};
    setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);
    static const char req[] = "GET /metrics HTTP/1.0\r\n\r\n";
    if (write(fd, req, sizeof req - 1) != (ssize_t)sizeof req - 1)
        die("write to the metrics port: %s", strerror(errno));
    size_t got = 0;
    for (ssize_t k; got < n - 1 && (k = read(fd, buf + got, n - 1 - got)) > 0;)
        got += (size_t)k;
    buf[got] = 0;
    close(fd);
}

/* tsdb_volume_diverged of volume num on server i's metrics port is `want` (0 or 1) */
static void metrics_diverged(int i, int port, uint32_t num, int want, const char *what)
{
    static char buf[1 << 20];
    metrics_get(port, buf, sizeof buf);
    char key[64];
    snprintf(key, sizeof key, "\ntsdb_volume_diverged{volume=\"%" PRIu32 "\",path=\"", num);
    const char *l = strstr(buf, key);
    const char *e = l ? strstr(l + 1, "\"} ") : NULL;
    if (!e || atoi(e + 3) != want)
        die("%s: server %d's metrics say tsdb_volume_diverged of volume %" PRIu32 " is %s, not %d", what, i, num,
            e ? e + 3 : "missing", want);
}

/* STATUS of server i says vol.<num>.health=unavailable and vol.<num>.reason=diverged within ms */
static void await_status_diverged(int i, uint32_t num, int ms, const char *what)
{
    char line[96], *text = NULL;
    snprintf(line, sizeof line, "\nvol.%" PRIu32 ".health=unavailable\nvol.%" PRIu32 ".reason=diverged\n", num, num);
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        tsdbc *c = client(i);
        int rc = tsdbc_status(c, &text);
        tsdbc_close(c);
        if (rc == 0 && strstr(text, line)) {
            free(text);
            return;
        }
        if (now_ms() - t0 > (uint64_t)ms)
            die("%s: STATUS of server %d does not say volume %" PRIu32 " is diverged after %d ms (%s):\n%s", what, i,
                num, ms, ers(rc), rc == 0 ? text : "");
        free(text);
        text = NULL;
    }
}

static void touch_plant(int i, uint32_t num)
{
    char f[PATH_MAX + 120];
    server_dir(i, f, sizeof f);
    snprintf(f + strlen(f), sizeof f - strlen(f), "/diverge.%" PRIu32, num);
    FILE *fp = fopen(f, "w");
    if (!fp)
        die("create %s: %s", f, strerror(errno));
    fclose(fp);
}

/* diverged (r8i, design-cluster-data.md D8, D13, D23): a volume whose DIVERGED file says a settled copy failed its
 * digest (planted by TSDB_REPLD_TEST=plantdiverge, the same ec_diverge a settle calls) stops like a failed one. On a
 * replica: LOCAL_FAULT in its heartbeat, out of the ISR, STATUS and /metrics name it DIVERGED, the writes go on at the
 * leader. On a leader: deposed, another member leads, a client is MOVED there and writes there. A restart opens the
 * volume DIVERGED again (the file; `tsdb DIR volume diverged --clear` refuses a cluster volume naming R4), and the
 * volume, opened as a replica (a deposed leader too), is rebuilt by a snapshot (r4-xferinst: no DIVERGED, in the ISR).
 * TSDB_REPLD_MUTANT=divergeisr (the driver ignores DIVERGED) fails it. */
static void scen_diverged(void)
{
    scenario("diverged");
    static int mports[3];
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=plantdiverge,snaphold"; /* a rebuild is asked for but never installed */
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num, num2;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    if ((rc = vol_add(0, "lead", 3, &num2)) != 0 || num2 != 2)
        die("volume add lead: %s, number %" PRIu32, cluster_strerror(rc), num2);
    for (int i = 0; i < 3; i++) {
        await_open_gen(0, "plant", i, 1, 0);
        await_open_gen(0, "lead", i, 1, 0);
    }
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    await_isr(L, "plant", 3, 15000, "every replica of plant up");
    metrics_diverged(L, mports[L], num, 0, "before any plant");

    /* a replica */
    int R = (L + 1) % 3;
    touch_plant(R, num);
    await_local_fault(R, num, 3);
    await_isr(L, "plant", 2, 15000, "a DIVERGED replica leaves the ISR");
    await_status_diverged(R, num, 5000, "a DIVERGED replica");
    metrics_diverged(R, mports[R], num, 1, "a DIVERGED replica");
    metrics_diverged(R, mports[R], num2, 0, "the other volume of a DIVERGED replica's server");
    for (int k = 0; k < 5; k++) {
        ts = 2000 + k;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("a write after a replica diverged: %s", ers(rc));
    }
    tsdbc_close(c);
    if (await_exit(R, 500) >= 0)
        die("server %d exited on its volume's DIVERGED (D13: only the volume stops)", R);

    /* a leader */
    struct meta_volume v2;
    if (!vol_rec(0, "lead", &v2))
        die("no record of lead");
    int L2 = server_of(v2.leader);
    if (L2 < 0 || L2 > 2)
        die("the leader of lead is node %u", v2.leader);
    c = client(L2);
    tsdb_sid id2 = rep_series(c, rep_names[1], "lead", 30000);
    ts = 1000;
    if ((rc = tsdbc_insert_series(c, id2, &ts, &val, 1)) != 0)
        die("a write to lead: %s", ers(rc));
    await_isr(L2, "lead", 3, 15000, "every replica of lead up");
    uint64_t e0 = v2.epoch;
    touch_plant(L2, num2);
    int N2 = await_promoted((L2 + 1) % 3, "lead", ids[L2], e0, &v2);
    if (N2 < 0 || N2 == L2)
        die("the new record of lead: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v2.epoch, e0, v2.leader);
    await_status_diverged(L2, num2, 5000, "a DIVERGED leader");
    metrics_diverged(L2, mports[L2], num2, 1, "a DIVERGED leader");
    ts = 3000;
    insert_expect_moved(c, id2, ts, val, 2, v2.leader, v2.epoch, "a write to the DIVERGED leader");
    tsdbc_close(c);
    c = client(N2);
    for (uint64_t t0 = now_ms(); (rc = tsdbc_insert_series(c, id2, &ts, &val, 1)) != 0; usleep(100000))
        if (now_ms() - t0 > 15000)
            die("a write to lead's new leader (server %d): %s", N2, ers(rc));
    tsdbc_close(c);
    await_local_fault(L2, num2, 3);

    /* a DIVERGED replica asks the leader for a snapshot (r4-xferinst: a4e1aeef, repld.c `div_rebuild`) and gets one, which
     * snaphold keeps instead of installing: the volume stays DIVERGED here, so the file is still there. A DIVERGED
     * leader (deposed, no replica) asks for none: nothing rebuilds it until it opens again as a replica. */
    char held[96], heldl[96];
    snprintf(held, sizeof held, "volume %" PRIu32 ": the snapshot is kept", num);
    snprintf(heldl, sizeof heldl, "volume %" PRIu32 ": the snapshot is kept", num2);
    await_log(R, held, 30000, "the DIVERGED replica asked for no snapshot");
    usleep(3000000);
    if (log_count(L2, heldl) != 0)
        die("the DIVERGED leader of lead was sent a snapshot (a leader is not rebuilt until it opens as a replica)");
    if (log_count(R, "snapshot installed: P") != 0)
        die("a snapshot was installed on server %d although snaphold keeps it", R);
    await_status_diverged(R, num, 5000, "the DIVERGED replica whose snapshot is held");
    await_status_diverged(L2, num2, 5000, "the DIVERGED leader");

    /* the DIVERGED record is a file: with both servers stopped, `tsdb DIR volume diverged` lists it and `--clear` is
     * refused on a cluster volume naming R4 (clearing is the rebuild's, not the CLI's) and removes nothing */
    int again[2] = {R, L2 == R ? -1 : L2};
    struct { uint32_t vol; int stopped_n; } before[2] = {{num, 0}, {num2, 0}};
    char needle[2][96];
    for (int k = 0; k < 2; k++) {
        snprintf(needle[k], sizeof needle[k], "volume %" PRIu32 ": stopped: the volume is DIVERGED", before[k].vol);
        before[k].stopped_n = log_count(k == 0 ? R : L2, needle[k]);
        if (before[k].stopped_n != 1)
            die("server %d logged %d stops of volume %" PRIu32 " as DIVERGED before the restart, not 1",
                k == 0 ? R : L2, before[k].stopped_n, before[k].vol);
    }
    for (int k = 0; k < 2; k++)
        if (again[k] >= 0)
            stop(again[k], SIGTERM);
    char dir[PATH_MAX + 80], args[PATH_MAX * 2 + 64], out[4096];
    server_dir(R, dir, sizeof dir);
    snprintf(args, sizeof args, "%s/v1 volume diverged", dir);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "DIVERGED"))
        die("tsdb %s lists no DIVERGED record:\n%s", args, out);
    snprintf(args, sizeof args, "%s/v1 volume diverged --clear", dir);
    if (cli_run(args, NULL, out, sizeof out) == 0 || !strstr(out, "R4"))
        die("tsdb %s on a cluster volume was not refused naming R4:\n%s", args, out);
    snprintf(args, sizeof args, "%s/v1 volume diverged", dir);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "DIVERGED"))
        die("the refused --clear removed the DIVERGED record:\n%s", out);

    /* a restart opens each volume DIVERGED again from that file (memory is gone: a second "stopped" line); both open as
     * replicas now (the deposed leader too), so both are rebuilt by a snapshot: the leader's copy, which carries no
     * DIVERGED file, is installed (rsnap.c), and the volume comes back healthy, in the ISR, with the leader's rows */
    for (int k = 0; k < 2; k++) {
        if (again[k] < 0)
            continue;
        penv[again[k]] = "TSDB_REPLD_TEST=plantdiverge"; /* the rebuild may install now */
        start(again[k]);
        mports[again[k]] = th_mport;
    }
    for (int k = 0; k < 2; k++) {
        int i = k == 0 ? R : L2;
        uint32_t vn = before[k].vol;
        await_log_count(i, needle[k], before[k].stopped_n + 1, 20000); /* opened DIVERGED from the file */
        char what[96];
        snprintf(what, sizeof what, "the DIVERGED volume %" PRIu32 " after a restart is not rebuilt", vn);
        uint64_t t0 = now_ms();
        char snapneedle[64];
        snprintf(snapneedle, sizeof snapneedle, "volume %" PRIu32 ": snapshot installed: P", vn);
        while (log_count(i, snapneedle) < 1) {
            if (now_ms() - t0 > 60000)
                die("%s: server %d installed no snapshot of it in 60 s", what, i);
            usleep(100000);
        }
        /* STATUS no longer says diverged, and the metrics agree, once the rebuilt volume is open */
        char sline[64], *text = NULL;
        snprintf(sline, sizeof sline, "\nvol.%" PRIu32 ".reason=diverged\n", vn);
        for (t0 = now_ms();; usleep(100000)) {
            tsdbc *c2 = client(i);
            int rc2 = tsdbc_status(c2, &text);
            tsdbc_close(c2);
            int gone = rc2 == 0 && !strstr(text, sline);
            free(text);
            text = NULL;
            if (gone)
                break;
            if (now_ms() - t0 > 60000)
                die("%s: STATUS of server %d still says volume %" PRIu32 " is diverged", what, i, vn);
        }
        metrics_diverged(i, mports[i], vn, 0, "a DIVERGED volume rebuilt after a restart");
    }
    await_isr(N2, "plant", 3, 60000, "the rebuilt replica of plant is back in the ISR");
    await_isr(N2, "lead", 3, 60000, "the rebuilt deposed leader of lead is back in the ISR");
    /* a settled rebuilt volume stops no more: the flag was not carried into the installed copy */
    usleep(3000000);
    for (int k = 0; k < 2; k++)
        if (log_count(k == 0 ? R : L2, needle[k]) != before[k].stopped_n + 1)
            die("volume %" PRIu32 " stopped as DIVERGED again after its rebuild", before[k].vol);
    if (log_count(R, "snapshot installed: P") != 1 + (L2 == R))
        die("server %d installed %d snapshots, not one per rebuilt volume", R, log_count(R, "snapshot installed: P"));
    stop_all();
    /* the rebuilt copies: no DIVERGED record, and the leader's rows of the series each volume held */
    for (int k = 0; k < 2; k++) {
        int i = k == 0 ? R : L2;
        server_dir(i, dir, sizeof dir);
        snprintf(args, sizeof args, "%s/v%" PRIu32 " volume diverged", dir, before[k].vol);
        if (cli_run(args, NULL, out, sizeof out) != 0 || strstr(out, "DIVERGED"))
            die("the rebuilt volume %" PRIu32 " of server %d still has a DIVERGED record:\n%s", before[k].vol, i, out);
    }
    for (int k = 0; k < 2; k++) {
        uint64_t rows[3][REP_NAMES], h[3][REP_NAMES];
        for (int i = 0; i < 3; i++) {
            char vd[PATH_MAX + 120];
            server_dir(i, dir, sizeof dir);
            snprintf(vd, sizeof vd, "%s/v%" PRIu32, dir, before[k].vol);
            int rc2 = cvol_digest(vd, rep_names, REP_NAMES, rows[i], h[i]);
            if (rc2 != 0)
                die("open %s read-only: %s", vd, ers(rc2));
            /* plant: 1 row, then 5 while R was out; lead: 1 row, then 1 at its new leader */
            uint64_t want = k == 0 ? 6 : 2;
            if (rows[i][k] != want || (i && h[i][k] != h[0][k]))
                die("server %d holds %" PRIu64 " rows of %s in volume %" PRIu32 " (want %" PRIu64 ", the same "
                    "digest as server 0)", i, rows[i][k], rep_names[k], before[k].vol, want);
        }
    }
    printf("  a DIVERGED replica leaves the ISR (LOCAL_FAULT) while writes go on, a DIVERGED leader is deposed and "
           "lead moves to server %d at epoch %" PRIu64 ", STATUS and /metrics say diverged, --clear is refused on a "
           "cluster volume (R4); a restart opens both DIVERGED again from the file, and each, as a replica, is rebuilt "
           "by a snapshot: no longer diverged, back in the ISR, the leader's rows\n",
           N2, v2.epoch);
}

static void scen_writerfail(void) { writerfail_run("writerfail", 1); }
static void scen_writerfailq(void) { writerfail_run("writerfailq", 0); }

/* writerdepose (M5, D13 with a healthy engine): the leader's driver fails the volume while its engine is fine
 * (crashfs: EIO on the leader's next fdatasync of its REPL file, the save of the commit floor at most once a second
 * after the floor moved), with a write waiting for a paused replica. Nothing in the engine ends that wait: only the
 * deposal does (eng_leader_depose in vol_fail), and its outcome is unknown (its records went to the replicas), so its
 * connection closes without an answer (D12). A replica is promoted at e+1; a later write on the old leader is MOVED
 * to it and never numbered; the replicas hold no row past what was sent before the failure. TSDB_REPLD_MUTANT=nodepose
 * fails it (the write waits for good). */
static void scen_writerdepose(void)
{
    scenario("writerdepose");
    const char *so, *skip = crashfs_skip(&so);
    if (skip) {
        printf("  skipped: %s\n", skip);
        return;
    }
    static char pe[3][PATH_MAX * 3 + 256];
    static char mark[3][PATH_MAX + 80];
    for (int i = 0; i < 3; i++) {
        char dir[PATH_MAX + 80];
        server_dir(i, dir, sizeof dir);
        if (mkdir(dir, 0755) != 0 && errno != EEXIST)
            die("mkdir %s: %s", dir, strerror(errno));
        snprintf(mark[i], sizeof mark[i], "%s/eio-n%d", base, i);
        snprintf(pe[i], sizeof pe[i],
                 "LD_PRELOAD=%s CRASHFS_ROOT=%s CRASHFS_MODE=eio CRASHFS_EIO_ONLY=REPL CRASHFS_EIO_ON=fdatasync "
                 "CRASHFS_MARK=%s",
                 so, dir, mark[i]);
        penv[i] = pe[i];
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    int sent = 1, acked = 1;
    /* the floor is saved at once after a commit when its last save is a second old, else a second after that save:
     * the commit of `ts` saves it now, the next commit moves it again and its save comes a second later */
    struct timespec ms1200 = {1, 200000000}, ms100 = {0, 100000000};
    nanosleep(&ms1200, NULL);
    ts += 1000;
    sent++;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    acked++;
    nanosleep(&ms100, NULL); /* that save is done (unharmed) */
    ts += 1000;
    sent++;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    acked++;
    uint64_t t_moved = now_ms();
    signal_child(pids[L], SIGUSR2); /* crashfs: the leader's next fdatasync of REPL (that save) fails with EIO */
    int R1 = (L + 1) % 3;
    pause_server(R1, 1); /* the commit point stops below the next write */
    struct wf_writer w = {client(L), id, ts + 1000, 0, 0, 0};
    sent++;
    pthread_t th;
    if (pthread_create(&th, NULL, wf_write_thread, &w) != 0)
        die("pthread_create");
    while (access(mark[L], F_OK) != 0) {
        if (now_ms() - t_moved > 30000)
            die("no fdatasync of server %d's REPL failed in 30 s", L);
        usleep(20000);
    }
    for (uint64_t t0 = now_ms(); !__atomic_load_n(&w.done, __ATOMIC_ACQUIRE); usleep(20000))
        if (now_ms() - t0 > 10000)
            die("the write waiting for the commit point on the failed writer was not ended in 10 s (the writer was "
                "not deposed)");
    pthread_join(th, NULL);
    if (w.rc != TSDB_ERR_IO || w.after != TSDB_ERR_IO)
        die("the write waiting for the commit point on the failed writer got %d (%s), then its connection %d (%s): "
            "not a closed connection (UNAVAILABLE: the save failed before the write was numbered)",
            w.rc, ers(w.rc), w.after, ers(w.after));
    tsdbc_close(w.c);
    tsdbc_close(c);
    pause_server(R1, 0);
    await_local_fault(L, num, 3);
    /* a write after the failure: never numbered; once a replica leads (D13 promotes away from L) it is MOVED there */
    uint64_t e0 = v.epoch;
    int Nw = await_promoted((L + 1) % 3, "plant", ids[L], e0, &v);
    if (Nw < 0 || Nw == L || v.epoch != e0 + 1)
        die("the new record of plant: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v.epoch, e0, v.leader);
    tsdbc *c2 = client(L);
    ts += 100000;
    insert_expect_moved(c2, id, ts, val, 1, v.leader, v.epoch, "a write to the failed volume");
    tsdb_sid any;
    if ((rc = tsdbc_series(c2, "writerfail.none", 0, &any)) != TSDB_ERR_NOTFOUND)
        die("a lookup in server %d's root after its volume failed: %s", L, ers(rc));
    tsdbc_close(c2);
    if (await_exit(L, 500) >= 0)
        die("server %d exited on its cluster volume's failure (D13: only the volume stops)", L);
    for (int i = 0; i < 3; i++)
        stop(i, SIGTERM);
    for (int r = 0; r < 3; r++) {
        if (r == L)
            continue;
        char dir[PATH_MAX + 80], vd[PATH_MAX + 120];
        server_dir(r, dir, sizeof dir);
        snprintf(vd, sizeof vd, "%s/v1", dir);
        uint64_t rows, h;
        if ((rc = cvol_digest(vd, rep_names, 1, &rows, &h)) != 0)
            die("open %s read-only: %s", vd, ers(rc));
        if (rows < (uint64_t)acked || rows > (uint64_t)sent)
            die("replica %d holds %" PRIu64 " rows: %d were acknowledged, %d sent before the volume failed", r, rows,
                acked, sent);
    }
    stop_all();
    printf("  a leader whose driver failed the volume (its engine healthy) closes the connection of the write waiting "
           "for its commit point and sends the next to the promoted replica (MOVED); the replicas hold between %d and "
           "%d rows\n",
           acked, sent);
}

/* ------------------------------------------------------------ leases (§7.1) and the serving loop's stamp (§6.1) */

/* a read on c by `kind` % 3: QUERY_RAW, QUERY_LATEST or QUERY_MULTI (the two ids paths of the lease check) */
struct lread {
    uint64_t sent;
    int rc;
};
static int lease_read(tsdbc *c, tsdb_sid id, int kind, int *rows)
{
    if (kind % 3 == 2) {
        tsdb_multi_query q = {.kind = TSDB_MULTI_VALUES, .start = 0, .end = INT64_MAX / 2};
        tsdb_series_result *r = NULL;
        int rc = tsdbc_query_multi_collect(c, &q, &id, 1, NULL, &r);
        if (rc == 0 && r[0].status != 0)
            rc = r[0].status;
        *rows = rc == 0 ? (int)r[0].n : 0;
        if (r)
            tsdbc_series_results_free(r, 1);
        return rc;
    }
    if (kind % 3 == 1) {
        tsdb_latest_result r;
        int rc = tsdbc_latest(c, &id, 1, NULL, &r);
        if (rc == 0 && r.status != 0)
            rc = r.status;
        *rows = rc == 0 && r.kind == TSDB_LATEST_VALUE;
        return rc;
    }
    nrows = 0;
    int rc = tsdbc_query_raw(c, id, 0, INT64_MAX / 2, count_rows, NULL);
    *rows = nrows;
    return rc;
}

/* reads on c until one succeeds (or `ms` passed): the time it was sent, or 0 */
static uint64_t lease_until_ok(tsdbc *c, tsdb_sid id, int ms, int want_rows)
{
    uint64_t t0 = now_ms();
    for (int k = 0; now_ms() - t0 < (uint64_t)ms; k++) {
        uint64_t t = now_ms();
        int rows, rc = lease_read(c, id, k % 3, &rows);
        if (rc == 0) {
            if (rows != want_rows)
                die("a read answered %d rows, %d were written", rows, want_rows);
            return t;
        }
        if (rc != TSDB_ERR_UNAVAILABLE)
            die("a read: %s", ers(rc));
        struct timespec d = {0, 2000000};
        nanosleep(&d, NULL);
    }
    return 0;
}

/* The volume leader X (not the Raft leader R) holds a lease the Raft leader's HB_ACKs extend: send time + lease_ms *
 * (1 - drift). R paused at T0: X's last grant was for a heartbeat sent before T0, so it answers nothing sent after
 * T0 + 800 ms (lease_ms 1000, drift 20%), and no new Raft leader can grant before an election timeout (1 s at least)
 * has passed: every read sent in (T0 + 810, T0 + 940) must be refused, and some must have been sent. Mutants:
 * leaseanyvoter (the third server's acks keep the lease), nodrift (it runs to T0 + 1000). Then X itself paused past
 * lease and node_timeout, the others paused, X resumed: nobody renews, it answers nothing; all resumed: the row
 * written before is read back. */
struct stalled_read {
    int server;
    tsdb_sid id;
    int rc;
};
static void *stalled_read_thread(void *a)
{
    struct stalled_read *sr = a;
    tsdbc *c = client(sr->server);
    tsdbc_set_retry(c, 0); /* the first answer, not a retried one */
    int rows;
    sr->rc = lease_read(c, sr->id, 0, &rows);
    tsdbc_close(c);
    return NULL;
}

static void scen_lease(void)
{
    scenario("lease");
    static char pe[3][PATH_MAX + 80];
    char stall[3][PATH_MAX + 64];
    for (int i = 0; i < 3; i++) {
        snprintf(stall[i], sizeof stall[i], "%s/rstall-n%d", base, i);
        unlink(stall[i]);
        snprintf(pe[i], sizeof pe[i], "TSDBD_TEST_READ_STALL=%s", stall[i]);
        penv[i] = pe[i];
        start(i);
    }
    struct meta_settings s;
    meta_settings_default(&s);
    s.node_timeout_ms = 3000;
    s.heartbeat_ms = 50;
    s.lease_ms = 1000;
    s.drift_ppm = 200000;
    s.voter_replace_s = 600;
    uint8_t req[4 * (META_SETTINGS_WORDS + 1)], *reply;
    size_t len;
    size_t rl = cluster_settings_encode(&s, META_MODE_REPLICATED, req);
    int rc = admin(0, CLUSTER_OP_INIT, req, rl, 0, &reply, &len);
    free(reply);
    if (rc != 0)
        die("init: %s", cluster_strerror(rc));
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    int R = 0, X = -1;
    char name[16];
    struct meta_volume v;
    for (int k = 0; k < 8 && X < 0; k++) {
        uint32_t num;
        snprintf(name, sizeof name, "lease%d", k);
        if ((rc = vol_add(0, name, 3, &num)) != 0)
            die("volume add %s: %s", name, cluster_strerror(rc));
        if (!vol_rec(0, name, &v))
            die("no record of %s", name);
        int L = server_of(v.leader);
        if (L >= 0 && L <= 2 && L != R)
            X = L;
    }
    if (X < 0)
        die("eight volumes, every one led by the Raft leader");
    int F = 3 - R - X;
    printf("  Raft leader %d, %s led by %d, third server %d\n", R, name, X, F);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, name, i, 1, 0);
    tsdbc *c = client(X);
    tsdb_sid id = rep_series(c, rep_names[0], name, 30000);
    int64_t ts = 1000;
    float val = 7;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write: %s", ers(rc));
    if (!lease_until_ok(c, id, 10000, 1))
        die("no read answered on %d before the pause", X);

    /* a: the Raft leader paused */
    static struct lread log[1 << 16];
    size_t nl = 0;
    pause_server(R, 1);
    uint64_t T0 = now_ms();
    while (now_ms() - T0 < 3000 && nl < sizeof log / sizeof log[0]) {
        int rows;
        log[nl].sent = now_ms();
        log[nl].rc = lease_read(c, id, (int)(nl % 3), &rows);
        if (log[nl].rc != 0 && log[nl].rc != TSDB_ERR_UNAVAILABLE)
            die("a read (%s) %" PRIu64 " ms into the pause: %s", nl & 1 ? "latest" : "raw", log[nl].sent - T0,
                ers(log[nl].rc));
        nl++;
        struct timespec d = {0, 100000}; /* the log spans the whole pause */
        nanosleep(&d, NULL);
    }
    pause_server(R, 0);
    size_t refused = 0, early_ok = 0;
    uint64_t last_ok = 0, first_refused = 0;
    for (size_t k = 0; k < nl; k++) {
        uint64_t at = log[k].sent - T0;
        if (log[k].rc == 0 && at > 810 && at < 940)
            die("a read sent %" PRIu64 " ms after the Raft leader paused was answered: past the lease (ends by 800)", at);
        if (log[k].rc == 0 && at <= 810)
            early_ok++, last_ok = at;
        if (log[k].rc != 0 && !first_refused)
            first_refused = at;
        refused += log[k].rc != 0 && at > 810 && at < 940;
    }
    if (!refused)
        die("no read was sent between 810 and 940 ms into the pause (%zu reads)", nl);
    printf("  pause of the Raft leader: %zu reads, the last answered at %" PRIu64 " ms, the first refused at %" PRIu64
           " ms, %zu refused in the window\n", nl, last_ok, first_refused, refused);
    if (!lease_until_ok(c, id, 20000, 1))
        die("no read answered on %d after the Raft leader came back", X);
    /* review F1: the paused Raft leader, resumed after an election, answered the heartbeats queued meanwhile against
     * the core's clock from before the pause (mutant nocoreclock: the code before the fix) */
    for (int i = 0; i < 3; i++)
        if (log_has(i, "past the end of its own"))
            die("server %d granted a lease after its own check-quorum lease had ended", i);

    /* c (review F4): a read admitted under the lease and stalled before its snapshot (TSDBD_TEST_READ_STALL) while the
     * other two are paused past X's lease (both: phase a moved the Raft leadership, which may now be X's own): it must
     * be refused, not answered from a snapshot taken after the lease */
    int fdst = open(stall[X], O_CREAT | O_WRONLY, 0644);
    if (fdst < 0)
        die("create %s: %s", stall[X], strerror(errno));
    close(fdst);
    struct stalled_read sr = {X, id, 1};
    pthread_t sth;
    if (pthread_create(&sth, NULL, stalled_read_thread, &sr) != 0)
        die("pthread_create");
    struct timespec d0 = {0, 300000000}; /* the read is admitted and waits */
    nanosleep(&d0, NULL);
    pause_server(R, 1);
    pause_server(F, 1);
    struct timespec d1 = {1, 500000000}; /* past X's lease (800 ms), or its core's check-quorum lease as Raft leader */
    nanosleep(&d1, NULL);
    unlink(stall[X]);
    pthread_join(sth, NULL);
    pause_server(R, 0);
    pause_server(F, 0);
    if (sr.rc != TSDB_ERR_UNAVAILABLE)
        die("a read admitted under the lease and stalled past it answered %s, not UNAVAILABLE", ers(sr.rc));
    printf("  a read stalled between admission and snapshot past the lease: refused\n");
    if (!lease_until_ok(c, id, 20000, 1))
        die("no read answered on %d after the stalled read", X);

    /* b: X paused past its lease and node_timeout; the others paused; X resumed: nobody renews its lease */
    pause_server(X, 1);
    struct timespec d = {4, 500000000};
    nanosleep(&d, NULL);
    pause_server(R, 1);
    pause_server(F, 1);
    pause_server(X, 0);
    uint64_t t1 = now_ms();
    int nb = 0;
    while (now_ms() - t1 < 1500) {
        int rows;
        rc = lease_read(c, id, nb % 3, &rows);
        if (rc == 0)
            die("server %d answered a read %" PRIu64 " ms after it was resumed with every other server paused",
                X, now_ms() - t1);
        nb++;
    }
    pause_server(R, 0);
    pause_server(F, 0);
    /* X was away past node_timeout: the group declared it down and moved the volume to another member, and X, deposed,
     * answers MOVED (it serves no reads for a volume it does not lead). The row is read back where MOVED points. */
    int at = X;
    for (uint64_t t2 = now_ms();;) {
        int rows;
        if (now_ms() - t2 > 30000)
            die("no read answered after every server was resumed (last asked server %d)", at);
        rc = lease_read(c, id, 2, &rows); /* a raw query: MOVED for the whole request, with its body */
        if (rc == 0) {
            if (rows != 1)
                die("a read on server %d answered %d rows, 1 was written", at, rows);
            break;
        }
        tsdbc_err_info e;
        if (rc == TSDB_ERR_MOVED && tsdbc_last_error(c, &e) == TSDB_ERR_MOVED && e.has_body && e.nmoved == 1) {
            int s = server_of(e.moved[0].node_id);
            if (s < 0 || s > 2)
                die("a read on server %d: MOVED to node %u, no server of this test", at, e.moved[0].node_id);
            if (s != at) {
                tsdbc_close(c);
                c = client(s);
                at = s;
            }
        } else if (rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) {
            die("a read on server %d: %s", at, ers(rc));
        }
        usleep(20000);
    }
    printf("  %d paused past its lease: %d reads refused while nobody renewed it, then answered on %d\n", X, nb, at);
    tsdbc_close(c);
}

/* n servers, server 0 INITs with heartbeats of 50 ms and the given lease, drift and node_timeout, the others join */
static void lease_cluster(int n, uint32_t lease_ms, uint32_t drift_ppm, uint32_t node_timeout_ms)
{
    for (int i = 0; i < n; i++)
        start(i);
    struct meta_settings s;
    meta_settings_default(&s);
    s.node_timeout_ms = node_timeout_ms;
    s.heartbeat_ms = 50;
    s.lease_ms = lease_ms;
    s.drift_ppm = drift_ppm;
    s.voter_replace_s = 600;
    uint8_t req[4 * (META_SETTINGS_WORDS + 1)], *reply;
    size_t len;
    size_t rl = cluster_settings_encode(&s, META_MODE_REPLICATED, req);
    int rc = admin(0, CLUSTER_OP_INIT, req, rl, 0, &reply, &len);
    free(reply);
    if (rc != 0)
        die("init: %s", cluster_strerror(rc));
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    for (int i = 1; i < n; i++)
        node_add(0, i);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
}

/* review F3: a Raft leader declares a member down no sooner than one lease (with the drift margin) after its last grant
 * to it, even where node_timeout is shorter: lease 4000 ms, drift 20 %, node_timeout 1500. Server 2 paused after the
 * leader has led for longer than a lease: DOWN at 4800 ms at the earliest (less a heartbeat for the last grant), not at
 * 1500. Mutant nopromotewait (node_timeout alone) is DOWN after about 1.5 s. */
static void scen_leasedown(void)
{
    scenario("leasedown");
    lease_cluster(3, 4000, 200000, 1500);
    struct timespec d = {5, 500000000}; /* the leader's own wait of one lease is over */
    nanosleep(&d, NULL);
    pause_server(2, 1);
    uint64_t t0 = now_ms();
    struct state_want down = {ids[2], META_DOWN, 0};
    await_view(0, p_member_state, &down, "the paused server marked DOWN");
    uint64_t at = now_ms() - t0;
    pause_server(2, 0);
    if (at < 4600)
        die("server 2 was marked DOWN %" PRIu64 " ms after it was paused: its lease (4800 ms) could still hold", at);
    printf("  paused member: DOWN after %" PRIu64 " ms (lease with margin 4800, node_timeout 1500)\n", at);
    struct state_want up = {ids[2], META_UP, 0};
    await_view(0, p_member_state, &up, "the server UP again");
}

/* review F2: the Raft leader R, alive and still leading, loses its quorum (the two other voters paused) while the volume
 * leader W, the member that is no voter, still reaches it. R grants only while its core's check-quorum lease holds
 * (it ends by 667 ms: E 1000 * 0.8 / 1.2), so W's lease ends by 667 + 800: every read sent in (1550, 1700) ms is
 * refused. Mutant noquorum grants until check-quorum deposes R (1000 to 2000 ms): W answers until 1750 at least. */
static void scen_leasequorum(void)
{
    scenario("leasequorum");
    lease_cluster(4, 1000, 200000, 3000);
    struct view vw;
    int W = -1;
    for (uint64_t t0 = now_ms(); W < 0 && now_ms() - t0 < (uint64_t)WAIT_MS;) {
        view(0, &vw);
        for (int i = 1; i < 4; i++)
            if (!is_voter(&vw, ids[i]))
                W = i;
        int lead = vw.st.role == RAFT_LEADER;
        view_free(&vw);
        if (!lead)
            die("server 0 no longer leads");
        if (W < 0) {
            struct timespec d = {0, 50000000};
            nanosleep(&d, NULL);
        }
    }
    if (W < 0)
        die("no member outside the voters");
    int A = -1, B = -1;
    for (int i = 1; i < 4; i++)
        if (i != W && A < 0)
            A = i;
        else if (i != W)
            B = i;
    char name[16];
    struct meta_volume v;
    int found = 0;
    for (int k = 0; k < 40 && !found; k++) {
        uint32_t num;
        snprintf(name, sizeof name, "lq%d", k);
        int rc = vol_add(0, name, 3, &num);
        if (rc != 0)
            die("volume add %s: %s", name, cluster_strerror(rc));
        if (!vol_rec(0, name, &v))
            die("no record of %s", name);
        found = server_of(v.leader) == W;
    }
    if (!found)
        die("forty volumes, none led by server %d", W);
    printf("  Raft leader 0, voters 0 %d %d, %s led by %d (no voter)\n", A, B, name, W);
    for (uint32_t r = 0; r < v.nrep; r++) {
        int i = server_of(v.rep[r].node);
        if (i >= 0)
            await_open_gen(0, name, i, 1, 0);
    }
    tsdbc *c = client(W);
    tsdb_sid id = rep_series(c, rep_names[0], name, 30000);
    int64_t ts = 1000;
    float val = 7;
    int rc = tsdbc_insert_series(c, id, &ts, &val, 1);
    if (rc != 0)
        die("a write: %s", ers(rc));
    if (!lease_until_ok(c, id, 10000, 1))
        die("no read answered on %d before the pause", W);
    static struct lread log[1 << 16];
    size_t nl = 0;
    pause_server(A, 1);
    pause_server(B, 1);
    uint64_t T0 = now_ms();
    while (now_ms() - T0 < 2500 && nl < sizeof log / sizeof log[0]) {
        int rows;
        log[nl].sent = now_ms();
        log[nl].rc = lease_read(c, id, (int)(nl % 3), &rows);
        if (log[nl].rc != 0 && log[nl].rc != TSDB_ERR_UNAVAILABLE)
            die("a read %" PRIu64 " ms into the pause: %s", log[nl].sent - T0, ers(log[nl].rc));
        nl++;
        struct timespec d = {0, 100000};
        nanosleep(&d, NULL);
    }
    pause_server(A, 0);
    pause_server(B, 0);
    size_t refused = 0;
    uint64_t last_ok = 0;
    for (size_t k = 0; k < nl; k++) {
        uint64_t at = log[k].sent - T0;
        if (log[k].rc == 0 && at > 1550 && at < 1700)
            die("a read sent %" PRIu64 " ms after the Raft leader lost its quorum was answered (its lease ends by 667)",
                at);
        if (log[k].rc == 0)
            last_ok = at;
        refused += log[k].rc != 0 && at > 1550 && at < 1700;
    }
    if (!refused)
        die("no read was sent between 1550 and 1700 ms (%zu reads)", nl);
    printf("  the Raft leader without its quorum: %zu reads, the last answered at %" PRIu64 " ms\n", nl, last_ok);
    if (!lease_until_ok(c, id, 30000, 1))
        die("no read answered on %d once the voters were back", W);
    tsdbc_close(c);
}

/* The serving loop of a server that is not the Raft leader hangs (TSDBD_TEST_LOOP_STALL): its cluster thread still
 * answers, but it sends no heartbeat, so the Raft leader marks it DOWN; once the loop runs again it is UP. Mutant
 * stampignored (heartbeats whatever the stamp says) keeps it UP. */
static void scen_hungloop(void)
{
    scenario("hungloop");
    static char pe[3][PATH_MAX + 80];
    char stall[3][PATH_MAX + 64];
    for (int i = 0; i < 3; i++) {
        snprintf(stall[i], sizeof stall[i], "%s/stall-n%d", base, i);
        unlink(stall[i]);
        snprintf(pe[i], sizeof pe[i], "TSDBD_TEST_LOOP_STALL=%s", stall[i]);
        penv[i] = pe[i];
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    int S = 2;
    int fd = open(stall[S], O_CREAT | O_WRONLY, 0644);
    if (fd < 0)
        die("create %s: %s", stall[S], strerror(errno));
    close(fd);
    uint64_t t0 = now_ms();
    struct state_want down = {ids[S], META_DOWN, 0};
    await_view(0, p_member_state, &down, "the server with the hung loop marked DOWN");
    printf("  server %d's loop hung: DOWN after %" PRIu64 " ms\n", S, now_ms() - t0);
    struct view vw;
    view(S, &vw); /* its cluster thread still answers */
    view_free(&vw);
    unlink(stall[S]);
    t0 = now_ms();
    struct state_want up = {ids[S], META_UP, 0};
    await_view(0, p_member_state, &up, "the server UP again once its loop runs");
    printf("  its loop ran again: UP after %" PRIu64 " ms\n", now_ms() - t0);
}

/* the newer valid-looking slot of server i's REPL of volume num (by generation): its page */
static void repl_page(int i, uint32_t num, uint8_t pg[2][4096], int *newer, char *path, size_t pn)
{
    snprintf(path, pn, "%s/n%d/v%" PRIu32 "/REPL", base, i, num);
    int fd = open(path, O_RDONLY | O_CLOEXEC);
    if (fd < 0 || pread(fd, pg, 2 * 4096, 0) != 2 * 4096)
        die("%s: %s", path, strerror(errno));
    close(fd);
    uint64_t g0, g1;
    memcpy(&g0, pg[0] + 8, 8);
    memcpy(&g1, pg[1] + 8, 8);
    *newer = g1 > g0;
}

static uint64_t now_us(void)
{
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return (uint64_t)t.tv_sec * 1000000u + (uint64_t)t.tv_nsec / 1000u;
}

static int cmp_u64(const void *a, const void *b)
{
    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;
    return x < y ? -1 : x > y;
}

/* repcheck: three duties of the replication driver that no other scenario sees, each the target of one of its mutants
 * (server/repld.c): a replica's saved floor reaches its engine, which then removes its flushed segments once they are
 * also past the keep caps (repl_retain_s is 2 s here; floornottold keeps them all) and, restarted, opens its log from
 * the floor it saved (floornotsaved never saves it: the log starts above it, the core refuses); a replica whose newest REPL slot is damaged opens "unsure" and its first save at the open takes the
 * group's epoch as fence and led, which clears the flag (unsureignored keeps the older slot's values and the flag);
 * a write whose position in the core is not its log number fails the volume before it is acknowledged (admitnocheck
 * acknowledges it; the fault is TSDB_REPLD_TEST=skippos). It also prints the latency of single-row writes (the fast
 * path sends a batch to the replicas from the bytes callback; nofastpath leaves that to the 5 ms tick). */
static void scen_repcheck(void)
{
    scenario("repcheck");
    for (int i = 0; i < 3; i++) {
        xargs[i] = "--flush-interval-ms 200";
        penv[i] = "TSDB_REPLD_TEST=skippos,stalesent";
        start(i);
    }
    init_retain_s = 2; /* a replica keeps flushed segments past its floor for repl_retain_s (design-cluster.md 8.3) */
    init_cluster(0, 600);
    init_retain_s = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    int R = (L + 1) % 3;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);

    /* single-row writes over about 2 s: flushes every 200 ms on every node. TSDB_TEST_ACK_MS (tests/repld_mutants.sh)
     * bounds their median, the best of up to three rounds: the fast path sends a batch from the bytes callback, the
     * tick would add up to 5 ms to each write */
    enum { NW = 300 };
    static uint64_t lat[NW];
    const char *ackms = getenv("TSDB_TEST_ACK_MS");
    double best = 1e9;
    for (int round = 0; round < 3; round++) {
        for (int j = 0; j < NW; j++) {
            int64_t ts = 1000 + 1000LL * (j + NW * round);
            float val = (float)j;
            uint64_t t0 = now_us();
            if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
                die("small insert %d: %s", j, ers(rc));
            lat[j] = now_us() - t0;
            if (j % 20 == 19)
                usleep(120000);
        }
        qsort(lat, NW, sizeof lat[0], cmp_u64);
        printf("  %d single-row writes on a volume of 3 replicas: median %.2f ms, 90th percentile %.2f ms\n", NW,
               lat[NW / 2] / 1000.0, lat[NW * 9 / 10] / 1000.0);
        best = lat[NW / 2] / 1000.0 < best ? lat[NW / 2] / 1000.0 : best;
        if (!ackms || best < atof(ackms))
            break;
    }
    if (ackms && best >= atof(ackms))
        die("the median latency of a single-row write is %.2f ms (best of three rounds), not below %s ms", best, ackms);
    int nw = 0;
    uint64_t t0 = now_ms();
    for (;;) {
        nw = wal_count(R, num);
        if (nw <= 2)
            break;
        if (now_ms() - t0 > 20000)
            die("replica %d still holds %d WAL segments 20 s after the writes (its saved floor never removed its "
                "flushed segments past the keep caps)", R, nw);
        usleep(100000);
    }
    printf("  the replica removed its flushed segments once its floor was saved (%d left)\n", nw);
    /* a clean restart: the segments went, so the log starts above position 1, and the floor that let them go must be
     * in REPL, or the core refuses the log at this open and every later one (floornotsaved: the engine was told the
     * floor, the save was skipped). Done here because only these 2 s keep caps let a replica's segments go in a test. */
    {
        int o = log_count(R, " of 3, log ");
        stop(R, SIGTERM);
        start(R);
        await_log_count(R, " of 3, log ", o + 1, 30000);
        /* the core's refusal is said by the volume's thread, after the open's line, and the ISR may still hold R for
         * isr_lag_ms: 2 s for the line before the ISR is asked */
        for (uint64_t t1 = now_ms(); isr_of(L, "plant", NULL) != 3 || now_ms() - t1 < 2000;) {
            if (log_has(R, "the log starts above the commit floor"))
                die("replica %d restarted after its flushed segments went refused its log: the log starts above the "
                    "commit floor (the floor that let them go was not saved)", R);
            if (now_ms() - t1 > 30000)
                die("replica %d restarted after its flushed segments went: the ISR of plant has %" PRIu32
                    " members, not 3, after 30000 ms", R, isr_of(L, "plant", NULL));
            usleep(50000);
        }
        if (log_has(R, "the log starts above the commit floor"))
            die("replica %d restarted after its flushed segments went refused its log: the log starts above the "
                "commit floor (the floor that let them go was not saved)", R);
        printf("  restarted, the replica opened its log from the floor it saved and joined the ISR again\n");
    }

    /* damage the newer REPL slot of the replica, restart it: it opens unsure, and the open's save clears that */
    stop(R, SIGTERM);
    uint8_t pg[2][4096];
    int nk;
    char path[PATH_MAX + 120];
    repl_page(R, num, pg, &nk, path, sizeof path);
    {
        int fd = open(path, O_WRONLY | O_CLOEXEC);
        uint8_t b = pg[nk][30] ^ 0x5a; /* inside the volume uuid: the slot's checksum fails */
        if (fd < 0 || pwrite(fd, &b, 1, (off_t)nk * 4096 + 30) != 1 || fsync(fd) != 0)
            die("damaging %s: %s", path, strerror(errno));
        close(fd);
    }
    uint64_t rid, gen;
    {
        uint64_t g;
        memcpy(&g, pg[nk] + 80, 8);
        gen = g;
        memcpy(&rid, pg[nk] + 72, 8);
    }
    /* the open generation is registered by the volume manager before the driver opens (and saves REPL): wait for the
     * driver's line */
    int opens = log_count(R, " of 3, log ");
    start(R);
    await_open_gen(L, "plant", R, gen + 1, rid);
    await_log_count(R, " of 3, log ", opens + 1, 30000);
    if (!vol_rec(L, "plant", &v))
        die("no record of plant");
    uint64_t epoch = v.epoch;
    stop(R, SIGTERM);
    repl_page(R, num, pg, &nk, path, sizeof path);
    uint32_t unsure;
    uint64_t fence, led;
    memcpy(&unsure, pg[nk] + 60, 4);
    memcpy(&fence, pg[nk] + 88, 8);
    memcpy(&led, pg[nk] + 96, 8);
    if (unsure != 0 || fence != led || fence < epoch)
        die("replica %d opened with a damaged REPL slot and saved unsure %u, fence %" PRIu64 ", led %" PRIu64
            " (the group's epoch is %" PRIu64 ")", R, unsure, fence, led, epoch);
    printf("  a replica with a damaged REPL slot opened unsure and took the group's epoch %" PRIu64 " as its fence\n",
           epoch);
    start(R);
    await_open_gen(L, "plant", R, gen + 2, rid);
    await_log_count(R, " of 3, log ", opens + 2, 30000);
    /* the surviving slot's floor was older than the segments the replica had removed: the open takes the log's start
     * as the floor's lower bound, or the core refuses the log at this open and every later one */
    usleep(300000);
    if (log_has(R, "the log starts above the commit floor"))
        die("replica %d stopped after an open with a damaged REPL slot: the log starts above the commit floor it saved",
            R);

    /* a peer's cursor set back below the leader's log start (its segments went with the commit point): the cursor must
     * move up to what the peer acknowledged, or the catch-up finds nothing to read and no write commits again (jepsen
     * kv, seed 1: a resync raced records in flight) */
    {
        /* R back in the ISR first (the fault takes a peer that acknowledged after the file appeared: a replica that
         * has just restarted holds less than its previous run acknowledged). A starved peer can come back without
         * the cursor moving up: it leaves the ISR, the leader drops the segments it lacks and rebuilds it by a
         * snapshot (nocursorup survived that way, 1 in 8 runs side by side). The cursor moving up sends it records
         * at once, so no snapshot is made for it after the fault */
        await_isr(L, "plant", 3, 30000, "after the restarts of a replica with a damaged REPL slot");
        int lines0 = log_count(L, ""); /* the snapshots that count are those logged after this line */
        char stale[PATH_MAX + 80];
        snprintf(stale, sizeof stale, "%s/n%d/stalesent", base, L);
        int sfd = open(stale, O_WRONLY | O_CREAT | O_CLOEXEC, 0644);
        if (sfd < 0)
            die("%s: %s", stale, strerror(errno));
        close(sfd);
        /* The fault waits for the leader's log to start above position 1 (a cursor of 0 is below it only then; with
         * the log still at 1 the catch-up from 0 reads every record and nocursorup survived). Single-row writes keep
         * the 200 ms flushes coming, whose segments the leader drops once every replica acknowledged them, so that
         * start rises however the restarts above left the leader's log; rows below the next step's t0 */
        tsdbc *sc;
        int src = tsdbc_connect("127.0.0.1", cports[L], &sc);
        if (src != 0)
            die("connect to the leader before the stalesent fault: %s", ers(src));
        tsdbc_set_retry(sc, 0);
        t0 = now_ms();
        for (int j = 0; !log_has(L, "test fault: the cursor of peer"); j++) {
            if (now_ms() - t0 > 20000 || j >= 400)
                die("the stalesent fault did not fire in 20 s of writes (the leader's log never started above "
                    "position 1: its flushed segments were never dropped)");
            int64_t ts = 3500000 + 1000LL * j;
            float val = (float)j;
            src = tsdbc_insert_series(sc, id, &ts, &val, 1);
            if (src != 0 && log_has(L, "test fault: the cursor of peer"))
                die("a write as the stalesent fault fired: %s (the cursor never moved up to what the peer "
                    "acknowledged)", ers(src));
            if (src != 0)
                die("a write before the stalesent fault: %s", ers(src));
            usleep(50000);
        }
        tsdbc_close(sc);
        /* only the snapshots made for the faulted peer's node count; one for the other replica says nothing about
         * this cursor */
        char fl[4096], snapfor[64];
        log_line(L, "test fault: the cursor of peer", fl, sizeof fl);
        const char *nd = strstr(fl, "(node ");
        unsigned fnode;
        if (!nd || sscanf(nd, "(node %u)", &fnode) != 1)
            die("the stalesent fault's line names no node: %s", fl);
        snprintf(snapfor, sizeof snapfor, "snapshot made for node %u:", fnode);
        struct rep_writer sw = {cports[L], id, 4000000, 1, 0, 0, 0, 0};
        pthread_t sth;
        if (pthread_create(&sth, NULL, rep_write_thread, &sw) != 0)
            die("pthread_create");
        t0 = now_ms();
        while (!__atomic_load_n(&sw.done, __ATOMIC_ACQUIRE)) {
            if (now_ms() - t0 > 10000)
                die("no write was acknowledged in 10 s after a peer's cursor went back below the leader's log start "
                    "(the cursor never moved up to what the peer acknowledged)");
            usleep(10000);
        }
        pthread_join(sth, NULL);
        if (sw.rc != 0)
            die("the write after a peer's cursor went back failed: %s", ers(sw.rc));
        /* With the ISR shrink the writes go on without the stuck peer (it leaves the ISR after isr_lag_ms): the
         * stall is then that peer's, which never gets another record and never joins again */
        await_isr(L, "plant", 3, 20000,
                  "after a peer's cursor went back below the leader's log start (the cursor never moved up to what the "
                  "peer acknowledged)");
        if (log_count_from(L, snapfor, lines0) != 0)
            die("the peer whose cursor went back below the leader's log start was rebuilt by a snapshot, not sent "
                "records (the cursor never moved up to what the peer acknowledged)");
        printf("  a peer's cursor set back below the leader's log start moved up to what it acknowledged\n");
    }

    /* the core's position one ahead of the log number: the write fails the volume, unacknowledged */
    char skip[PATH_MAX + 80];
    snprintf(skip, sizeof skip, "%s/n%d/skippos", base, L);
    int fd = open(skip, O_WRONLY | O_CREAT | O_CLOEXEC, 0644);
    if (fd < 0)
        die("%s: %s", skip, strerror(errno));
    close(fd);
    struct rep_writer w = {cports[L], id, 5000000, 1, 0, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0)
        die("pthread_create");
    t0 = now_ms();
    while (!__atomic_load_n(&w.done, __ATOMIC_ACQUIRE)) {
        if (now_ms() - t0 > 15000)
            die("a write whose core position is not its log number neither failed nor was acknowledged in 15 s");
        usleep(10000);
    }
    pthread_join(th, NULL);
    if (w.rc == 0)
        die("a write whose core position is not its log number was acknowledged");
    if (!log_has(L, "the core's position is not the log number"))
        die("the leader did not fail the volume on a core position that is not the log number");
    printf("  a write whose core position is not its log number failed the volume (%s), unacknowledged\n", ers(w.rc));
    tsdbc_close(c);
    stop_all();
}


/* design-cluster.md 6.3 (r3e-failover): the leader of a replicated volume is paused (SIGSTOP) past its lease and
 * node_timeout with a write waiting for its commit point (both replicas were paused first, and nothing can shrink
 * the ISR without a Raft quorum). The replicas resume and one is promoted at e+1; it takes a write. The old leader
 * resumes with the others paused: it answers no read (no lease, deposed or not). Once every server runs, its waiting
 * write ends acknowledged (the replicas read the record from their sockets, acknowledged it, and the new epoch starts
 * past it: the old leader may see those acknowledgements before the fence) or with a closed connection (D12: of
 * unknown outcome), never MOVED or UNAVAILABLE; a new write is MOVED to the new leader and a client with a budget
 * follows it there; the old leader rejoins as a replica (cut, caught up) with the same rows as the others. Which of
 * the two ends the waiting write gets is a race, so the planted fault deposemoved is writerdepose's to catch. */
/* the fence in server i's REPL of volume number (the slot with the newer generation; offset 88, src/replfile.c) */
static uint64_t repl_fence_of(int i, uint32_t number)
{
    char dir[PATH_MAX + 80], path[PATH_MAX + 160];
    uint8_t pg[2][4096];
    server_dir(i, dir, sizeof dir);
    snprintf(path, sizeof path, "%s/v%" PRIu32 "/REPL", dir, number);
    FILE *f = fopen(path, "r");
    if (!f)
        die("%s: %s", path, strerror(errno));
    size_t got = fread(pg, 1, sizeof pg, f);
    fclose(f);
    if (got != sizeof pg)
        die("%s: %zu bytes, not two slots", path, got);
    uint64_t g[2], fence;
    memcpy(&g[0], pg[0] + 8, 8);
    memcpy(&g[1], pg[1] + 8, 8);
    memcpy(&fence, pg[g[1] > g[0]] + 88, 8);
    return fence;
}

/* Crash points of a promotion (design-cluster.md 6.2), a replica armed, the leader killed under none of its writes lost:
 * fencecrash: a fenced replica saves the fence in REPL before it answers, so one that stops at fence-saved-before-reply
 * (its reply not yet out) holds the new epoch's fence on disk (mutant fencenosync answers with the fence unsaved); the
 * other replica is promoted alone. promotecrash: both replicas armed with promote-before-epoch, the one the record
 * names stops before its EPOCH marker; restarted, it never resumes that epoch (it resigns, or is promoted again later)
 * and some replica leads with every acknowledged row. deposecrash: the leader paused past its lease and node_timeout is
 * promoted away; resumed, it stops at depose-before-reopen (writer closed, replica not yet open) and, restarted, opens
 * as a replica, rejoins and holds the same rows. Each time the crashed server rejoins. */
static void crash_promo(int promote)
{
    scenario(promote == 2 ? "deposecrash" : promote ? "promotecrash" : "fencecrash");
    for (int i = 0; i < 3; i++) {
        penv[i] = promote == 2 ? "TSDB_CRASH_AT=depose-before-reopen" : NULL; /* only a demotion passes it */
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "fc", 3, &num)) != 0)
        die("volume add fc: %s", cluster_strerror(rc));
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "fc", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "fc", &v))
        die("no record of fc");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of fc is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "fc", 30000);
    for (int j = 0; j < 20; j++) {
        int64_t ts = 1000000 + 1000LL * j;
        float val = (float)j;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d to the leader: %s", j, ers(rc));
    }
    tsdbc_close(c);
    await_isr(0, "fc", 3, 30000, "every replica in the ISR");
    /* the crashing replica is one that is not the Raft leader (the fences come from there) */
    int R = -1;
    for (int i = 0; i < 3 && R < 0; i++)
        if (i != L && i != 0)
            R = i;
    int Q = 3 - L - R;
    const char *spec = promote ? "TSDB_CRASH_AT=promote-before-epoch" : "TSDB_CRASH_AT=fence-saved-before-reply";
    for (int k = 0; k < (promote == 2 ? 0 : promote ? 2 : 1); k++) {
        int x = k ? Q : R;
        stop(x, SIGTERM);
        penv[x] = spec;
        start(x);
        /* back as a replica (its volume opens once the group holds its new incarnation) before the next one stops:
         * two servers restarted at new peer ports at once cannot find each other (scen_minisr) */
        await_log_count(x, "open as the replica", 2, 60000);
        await_isr(k ? R : Q, "fc", 3, 60000, "the restarted replica back in the ISR");
    }
    if (promote == 2) {
        /* paused past its lease and node_timeout, the leader is promoted away; resumed, it is deposed and stops
         * between the close of its writer and the open as a replica; restarted, it opens as a replica and rejoins */
        pause_server(L, 1);
        uint64_t t1 = now_ms();
        while (!(vol_rec(Q, "fc", &v) && v.epoch > e0 && v.leader != ids[L])) {
            if (now_ms() - t1 > 30000)
                die("no new leader of fc 30 s after its leader was paused");
            usleep(50000);
        }
        pause_server(L, 0);
        int st = await_exit(L, 30000);
        for (int i = 0; i < 3; i++)
            penv[i] = NULL;
        if (st != 99)
            die("the deposed leader %d did not stop at depose-before-reopen (status %d)", L, st);
        printf("  the deposed leader %d stopped at depose-before-reopen\n", L);
        start(L);
    } else {
        signal_child(pids[L], SIGKILL);
        if (await_exit(L, 5000) < 0)
            die("server %d did not die of SIGKILL", L);
    }
    if (promote == 2) {
    } else if (promote) {
        /* the one named first stops; the other may be named after it and stop as well */
        uint64_t t1 = now_ms();
        int st = -1;
        for (;;) {
            int got_one = -1;
            for (int x = 0; x < 3 && got_one < 0; x++)
                if (x != L && pids[x] && (st = await_exit(x, 0)) >= 0)
                    got_one = x;
            if (got_one >= 0) {
                if (st != 99)
                    die("replica %d ended with status %d, not at promote-before-epoch", got_one, st);
                printf("  replica %d stopped at promote-before-epoch\n", got_one);
                penv[got_one] = NULL;
                start(got_one);
                break;
            }
            if (now_ms() - t1 > 30000)
                die("no replica stopped at promote-before-epoch 30 s after the leader was killed");
            usleep(50000);
        }
        penv[R] = penv[Q] = NULL;
    } else {
        int st = await_exit(R, 30000);
        penv[R] = NULL;
        if (st != 99)
            die("replica %d did not stop at fence-saved-before-reply (status %d)", R, st);
        uint64_t fence = repl_fence_of(R, num);
        if (fence < e0 + 1)
            die("replica %d: REPL holds fence %" PRIu64 " after it stopped at fence-saved-before-reply for epoch %" PRIu64,
                R, fence, e0 + 1);
        printf("  replica %d stopped at fence-saved-before-reply with fence %" PRIu64 " in REPL\n", R, fence);
        start(R);
    }
    uint64_t t0 = now_ms();
    for (;;) {
        if (promote) {
            /* the replica still armed may stop too when named; it is restarted unarmed */
            for (int x = 0; x < 3; x++)
                if (x != L && pids[x] && await_exit(x, 0) >= 0)
                    start(x);
        }
        int via = pids[Q] ? Q : R;
        char lead[64];
        if (vol_rec(via, "fc", &v) && v.leader != ids[L] && v.epoch > e0 && server_of(v.leader) >= 0 &&
            (snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch), log_has(server_of(v.leader), lead)))
            break;
        if (now_ms() - t0 > 30000)
            die("no new leader of fc 30 s after its leader was killed (epoch %" PRIu64 ", leader %u)", v.epoch, v.leader);
        usleep(20000);
    }
    int Nw = server_of(v.leader);
    int got = rows_in(Nw, id, 1000000, 1000000 + 1000LL * 20, 30000);
    if (got != 20)
        die("the new leader (server %d) holds %d of the 20 acknowledged rows", Nw, got);
    if (promote == 2) {
        await_log_count(L, "open as the replica", 1, 60000); /* its first open was as the leader */
        await_isr(Nw, "fc", 3, 60000, "the deposed leader back in the ISR");
        stop_all();
        uint64_t wantr[REP_NAMES] = {0};
        wantr[0] = 20;
        rep_same(wantr, "after the deposed leader rejoined");
        printf("  server %d leads fc at epoch %" PRIu64 "; the deposed leader reopened as a replica and holds the same "
               "rows\n", Nw, v.epoch);
        return;
    }
    await_isr(Nw, "fc", 2, 60000, "the two live replicas in the ISR");
    printf("  server %d leads fc at epoch %" PRIu64 " with every row; the crashed replica rejoined\n", Nw, v.epoch);
    stop_all();
}

/* leasestale (r3e-leases F5): a deposed writer that has not heard of its deposal gets no read lease. Server L, the
 * leader of the volume, has its volume thread stalled (TSDB_REPLD_TEST=stallinbox, the file in place, a write waiting
 * on its replicas' ACKs, which the stalled thread never takes) and is paused until the record names a new leader. Once
 * it runs again its driver still sees itself the writer at the old epoch (the record change waits in the stalled
 * inbox) and reports OWNER; the promotion's state is gone with the record moved, so only the check of the report
 * against the record keeps the lease from it. Reads on L must be refused (they would miss the new leader's rows) until
 * the stall ends and L, deposed, takes up the new history. TSDB_CLUSTER_MUTANT=leasestale fails it. */
static void scen_leasestale(void)
{
    scenario("leasestale");
    strict_reads = 1; /* every read on the leader (D5), as in production */
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=stallinbox";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "ls", 3, &num)) != 0 || num != 1)
        die("volume add ls: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "ls", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "ls", &v))
        die("no record of ls");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of ls is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "ls", 30000);
    for (int k = 0; k < 10; k++) {
        int64_t ts = 1000 + k;
        float val = 1;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d with every replica up: %s", k, ers(rc));
    }
    tsdbc_close(c);
    await_isr(0, "ls", 3, 30000, "every replica in the ISR before the stall");
    char stall[PATH_MAX + 80];
    server_dir(L, stall, sizeof stall);
    strcat(stall, "/stallinbox");
    FILE *sf = fopen(stall, "w");
    if (!sf)
        die("create %s", stall);
    fclose(sf);
    struct wf_writer w = {client(L), id, 2000, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, wf_write_thread, &w) != 0)
        die("pthread_create");
    nanosleep(&(struct timespec){0, 500000000}, NULL); /* the replicas' ACKs reach L's inbox: its thread stalls */
    if (__atomic_load_n(&w.done, __ATOMIC_ACQUIRE)) {
        unlink(stall);
        die("a write to a leader with a stalled volume thread was answered: %s", ers(w.rc));
    }
    pause_server(L, 1);
    int Nw = await_promoted((L + 1) % 3, "ls", ids[L], e0, &v);
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(Nw, lead, 1, 30000);
    tsdbc *cn = client(Nw);
    tsdbc_set_retry(cn, 10000);
    int64_t ts = 3000;
    float val = 3;
    if ((rc = tsdbc_insert_series(cn, id, &ts, &val, 1)) != 0) {
        unlink(stall);
        die("a write to the new leader: %s", ers(rc));
    }
    tsdbc_close(cn);
    pause_server(L, 0);
    /* L heartbeats again, as OWNER at e0, for 4 s: no read there may be answered */
    tsdbc *cr = client(L);
    tsdbc_set_retry(cr, 0);
    int answered = 0, refused = 0, rows = 0, last = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 4000; usleep(100000)) {
        int r = lease_read(cr, id, 0, &rows);
        if (r == 0) {
            answered++;
            last = rows;
        } else if (r == TSDB_ERR_UNAVAILABLE) {
            refused++;
        }
    }
    tsdbc_close(cr);
    unlink(stall);
    if (answered)
        die("server %d, deposed at epoch %" PRIu64 " while stalled and not yet told, answered %d reads (the last with "
            "%d rows; the new leader has 11): it held a read lease",
            L, e0, answered, last);
    if (!refused)
        die("no read on the stale writer was refused UNAVAILABLE in 4 s (the case proved nothing)");
    pthread_join(th, NULL);
    tsdbc_close(w.c);
    await_isr(Nw, "ls", 3, 60000, "the stale writer back in the ISR once its stall ended");
    stop_all();
    for (int i = 0; i < 3; i++)
        penv[i] = NULL;
    printf("  a writer deposed while stalled reports itself OWNER at epoch %" PRIu64 " and gets no read lease (%d reads "
           "refused); it rejoins once the stall ends\n",
           e0, refused);
}

static void scen_fencecrash(void) { crash_promo(0); }
static void scen_promotecrash(void) { crash_promo(1); }
static void scen_deposecrash(void) { crash_promo(2); }

static void scen_pause(void)
{
    scenario("pause");
    strict_reads = 1; /* the deposed leader back in the ISR holds a lease again: its reads must go to the new leader */
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "pz", 3, &num)) != 0 || num != 1)
        die("volume add pz: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "pz", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "pz", &v))
        die("no record of pz");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of pz is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "pz", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    await_isr(0, "pz", 3, 30000, "every replica in the ISR before the pause");
    int R1 = (L + 1) % 3, R2 = (L + 2) % 3;
    pause_server(R1, 1);
    pause_server(R2, 1);
    struct wf_writer w = {client(L), id, 2000, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, wf_write_thread, &w) != 0)
        die("pthread_create");
    nanosleep(&(struct timespec){0, 300000000}, NULL);
    if (__atomic_load_n(&w.done, __ATOMIC_ACQUIRE))
        die("a write with both replicas paused was answered: %s", ers(w.rc));
    pause_server(L, 1);
    uint64_t tp = now_ms();
    pause_server(R1, 0);
    pause_server(R2, 0);
    int Nw = await_promoted(R1, "pz", ids[L], e0, &v);
    if (Nw < 0 || Nw == L || v.epoch != e0 + 1)
        die("the new record of pz: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v.epoch, e0, v.leader);
    uint64_t tr = now_ms();
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(Nw, lead, 1, 30000);
    tsdbc *cn = client(Nw);
    tsdbc_set_retry(cn, 10000);
    ts = 3000;
    if ((rc = tsdbc_insert_series(cn, id, &ts, &val, 1)) != 0)
        die("a write to the new leader: %s", ers(rc));
    tsdbc_close(cn);
    printf("  leader %d paused with a write waiting: the record names server %d at epoch %" PRIu64 " after %" PRIu64
           " ms\n", L, Nw, v.epoch, tr - tp);
    /* the old leader resumes alone: whatever it learns from what was queued for it, it answers no read */
    pause_server(R1, 1);
    pause_server(R2, 1);
    pause_server(L, 0);
    uint64_t t1 = now_ms();
    int nb = 0;
    while (now_ms() - t1 < 1500) {
        int rows;
        if ((rc = lease_read(c, id, nb % 3, &rows)) == 0)
            die("server %d answered a read %" PRIu64 " ms after it was resumed with every other server paused (%d rows)",
                L, now_ms() - t1, rows);
        nb++;
    }
    if (__atomic_load_n(&w.done, __ATOMIC_ACQUIRE) && w.rc != 0 && (w.rc != TSDB_ERR_IO || w.after != TSDB_ERR_IO))
        die("the write waiting on the paused leader got %d (%s), then its connection %d (%s): not a closed connection",
            w.rc, ers(w.rc), w.after, ers(w.after));
    pause_server(R1, 0);
    pause_server(R2, 0);
    for (uint64_t t0 = now_ms(); !__atomic_load_n(&w.done, __ATOMIC_ACQUIRE); usleep(20000))
        if (now_ms() - t0 > 15000)
            die("the write waiting on the deposed leader %d was not ended in 15 s", L);
    pthread_join(th, NULL);
    if (w.rc != 0 && (w.rc != TSDB_ERR_IO || w.after != TSDB_ERR_IO))
        die("the write waiting on the deposed leader got %d (%s), then its connection %d (%s): neither acknowledged "
            "nor a closed connection (D12)", w.rc, ers(w.rc), w.after, ers(w.after));
    tsdbc_close(w.c);
    tsdbc_close(c);
    printf("  resumed alone it answered none of %d reads; its waiting write ended %s\n", nb,
           w.rc == 0 ? "acknowledged (committed in the new epoch)" : "with a closed connection");
    /* new writes on the old leader are MOVED, and a client with a budget follows them */
    c = client(L);
    ts = 4000;
    insert_expect_moved(c, id, ts, val, 1, v.leader, v.epoch, "a write to the deposed leader");
    tsdbc_set_retry(c, 10000);
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write that follows MOVED from the deposed leader %d: %s", L, ers(rc));
    tsdbc_close(c);
    await_isr(R1, "pz", 3, 60000, "the deposed leader back in the ISR");
    /* back in the ISR the deposed leader holds a read lease again, but the writes the new leader acknowledges reach it
     * only at its next apply: every read there is MOVED to the new leader (D5, review F2), never answered stale. A
     * write acknowledged by the new leader is in every answer a client following MOVED from L gets. */
    c = client(L);
    for (int k = 0; k < 3; k++) {
        int rows = -1;
        rc = lease_read(c, id, k, &rows);
        if (rc == 0)
            die("the deposed leader %d, back in the ISR, answered a read (kind %d, %d rows): a replica's answer may "
                "miss a write the new leader acknowledged", L, k, rows);
        expect_moved_ep(c, rc, (uint16_t)num, v.leader, v.epoch, "a read on the deposed leader");
    }
    tsdbc_set_retry(c, 10000);
    tsdbc *cw = client(Nw);
    /* The pauses above (the old leader resumed alone, its peers paused, then all resumed) can make the metadata group
     * elect again (term 3 or 4) about now, and a lease that lapses meanwhile refuses a write UNAVAILABLE until the new
     * term's heartbeats are answered (§7.1, nothing written): retried, as by any client. What this part checks is the
     * reads through the deposed leader. (ASan under load: 2 of 12 runs of c0047c5 failed here with retry 0, each
     * with such an election.) */
    tsdbc_set_retry(cw, 10000);
    for (int k = 0; k < 20; k++) {
        ts = 10000 + k;
        if ((rc = tsdbc_insert_series(cw, id, &ts, &val, 1)) != 0)
            die("write %d on the new leader: %s", k, ers(rc));
        int want = rows_in(Nw, id, 0, INT64_MAX / 2, 10000), rows = -1;
        if ((rc = lease_read(c, id, k % 2 ? 2 : 0, &rows)) != 0 || rows != want) /* a count: raw, QUERY_MULTI */
            die("a read through the deposed leader %d after write %d was acknowledged: %d (%s), %d rows of %d", L, k,
                rc, ers(rc), rows, want);
    }
    tsdbc_close(cw);
    tsdbc_close(c);
    int total = rows_in(Nw, id, 0, INT64_MAX / 2, 10000);
    if (total != 24 && !(total == 23 && w.rc != 0))
        die("the new leader holds %d rows: 23 acknowledged, and the waiting write %s", total,
            w.rc == 0 ? "acknowledged too" : "of unknown outcome");
    stop_all();
    uint64_t wantr[REP_NAMES] = {0};
    wantr[0] = (uint64_t)total;
    rep_same(wantr, "after the pause");
    printf("  the deposed leader rejoined as a replica: every server holds the same %d rows\n", total);
}

/* fwdlease (S2-2): a forwarded read is judged by the owner's read lease, as a read sent to it directly. scen_lease's
 * phase a with every read sent to the third server F, which forwards it to the volume leader X: the Raft leader R
 * paused at T0, X's lease ends by T0 + 800 ms (lease_ms 1000, drift 20%) and no new Raft leader can grant before an
 * election timeout, so every read F forwards in (T0 + 810, T0 + 940) must be refused, and some must have been sent.
 * Mutant fwdnolease (the owner skips the lease for a forward). */
static void scen_fwdlease(void)
{
    scenario("fwdlease");
    strict_reads = 1;
    fwd_on = 1;
    const char *mut = getenv("TSDBD_FWD_MUTANT");
    static char menv[160];
    snprintf(menv, sizeof menv, "TSDBD_FWD_MUTANT=%s", mut ? mut : "");
    for (int i = 0; i < 3; i++) {
        penv[i] = menv;
        start(i);
    }
    struct meta_settings s;
    meta_settings_default(&s);
    s.node_timeout_ms = 3000;
    s.heartbeat_ms = 50;
    s.lease_ms = 1000;
    s.drift_ppm = 200000;
    s.voter_replace_s = 600;
    uint8_t req[4 * (META_SETTINGS_WORDS + 1)], *reply;
    size_t len;
    size_t rl = cluster_settings_encode(&s, META_MODE_REPLICATED, req);
    int rc = admin(0, CLUSTER_OP_INIT, req, rl, 0, &reply, &len);
    free(reply);
    if (rc != 0)
        die("init: %s", cluster_strerror(rc));
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    int R = 0, X = -1;
    char name[16];
    struct meta_volume v;
    for (int k = 0; k < 8 && X < 0; k++) {
        uint32_t num;
        snprintf(name, sizeof name, "fl%d", k);
        if ((rc = vol_add(0, name, 3, &num)) != 0)
            die("volume add %s: %s", name, cluster_strerror(rc));
        if (!vol_rec(0, name, &v))
            die("no record of %s", name);
        int L = server_of(v.leader);
        if (L >= 0 && L <= 2 && L != R)
            X = L;
    }
    if (X < 0)
        die("eight volumes, every one led by the Raft leader");
    int F = 3 - R - X;
    for (int i = 0; i < 3; i++)
        await_open_gen(0, name, i, 1, 0);
    tsdbc *cx = client(X);
    tsdb_sid id = rep_series(cx, rep_names[0], name, 30000);
    int64_t ts = 1000;
    float val = 7;
    if ((rc = tsdbc_insert_series(cx, id, &ts, &val, 1)) != 0)
        die("a write: %s", ers(rc));
    tsdbc_close(cx);
    tsdbc *c = client(F);
    tsdbc_set_retry(c, 0); /* the first answer, not a retried one */
    if (!lease_until_ok(c, id, 10000, 1))
        die("no read through %d (forwarded to %d) answered before the pause", F, X);
    uint64_t f0 = fw_frames(c, v.leader);

    static struct lread log[1 << 16];
    size_t nl = 0;
    pause_server(R, 1);
    uint64_t T0 = now_ms();
    while (now_ms() - T0 < 2000 && nl < sizeof log / sizeof log[0]) {
        int rows;
        log[nl].sent = now_ms();
        log[nl].rc = lease_read(c, id, (int)(nl % 3), &rows);
        if (log[nl].rc != 0 && log[nl].rc != TSDB_ERR_UNAVAILABLE)
            die("a read through %d %" PRIu64 " ms into the pause: %s", F, log[nl].sent - T0, ers(log[nl].rc));
        nl++;
        struct timespec d = {0, 100000};
        nanosleep(&d, NULL);
    }
    pause_server(R, 0);
    size_t refused = 0;
    for (size_t k = 0; k < nl; k++) {
        uint64_t at = log[k].sent - T0;
        if (log[k].rc == 0 && at > 810 && at < 940)
            die("a read forwarded through %d %" PRIu64 " ms after the Raft leader paused was answered by %d: past its "
                "lease (ends by 800)", F, at, X);
        refused += log[k].rc != 0 && at > 810 && at < 940;
    }
    if (!refused)
        die("no read was sent through %d between 810 and 940 ms into the pause (%zu reads)", F, nl);
    uint64_t f1 = fw_frames(c, v.leader);
    if (f1 < f0 + nl)
        die("%zu reads through %d, %" PRIu64 " frames forwarded to %d", nl, F, f1 - f0, X);
    if (!lease_until_ok(c, id, 20000, 1))
        die("no read through %d answered after the Raft leader came back", F);
    tsdbc_close(c);
    stop_all();
    printf("  reads forwarded from %d to %d with the Raft leader %d paused: %zu refused in (810, 940) ms, none answered "
           "past the lease\n", F, X, R, refused);
}

/* fwddepose (S2-2): a forward that reaches a leader deposed since the entry node's copy was taken is answered MOVED by
 * it, never forwarded a second hop. fd on three servers; the replicas' copies held (TSDB_CLUSTER_TEST hold_copy_file)
 * while the leader L is paused past node_timeout and a replica N is promoted; N's copy is let go, the entry E's kept;
 * L resumes, rejoins as a replica and learns N leads: a write through E goes to L at the old epoch and must come back
 * MOVED, not applied. Mutant fwdtwice (L forwards it on to N). */
static void scen_fwddepose(void)
{
    scenario("fwddepose");
    strict_reads = 1;
    fwd_on = 1;
    const char *mut = getenv("TSDBD_FWD_MUTANT");
    static char menv[160];
    snprintf(menv, sizeof menv, "TSDBD_FWD_MUTANT=%s", mut ? mut : "");
    for (int i = 0; i < 3; i++) {
        penv[i] = menv;
        envs[i] = "hold_copy_file=1";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "fd", 3, &num)) != 0)
        die("volume add fd: %s", cluster_strerror(rc));
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "fd", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "fd", &v))
        die("no record of fd");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of fd is node %u", v.leader);
    uint64_t e0 = v.epoch;
    uint32_t oldlead = v.leader;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "fd", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    tsdbc_close(c);
    await_isr(0, "fd", 3, 30000, "every replica in the ISR before the pause");
    char hold[3][PATH_MAX + 96];
    for (int i = 0; i < 3; i++) {
        server_dir(i, hold[i], sizeof hold[i]);
        strcat(hold[i], "/state/holdcopy");
        if (i == L)
            continue;
        FILE *h = fopen(hold[i], "w");
        if (!h)
            die("%s: %s", hold[i], strerror(errno));
        fclose(h);
    }
    usleep(300000); /* a round of their cluster threads */
    pause_server(L, 1);
    int Nw = await_promoted((L + 1) % 3, "fd", ids[L], e0, &v);
    if (Nw < 0 || Nw == L || v.epoch <= e0)
        die("the new record of fd: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v.epoch, e0, v.leader);
    unlink(hold[Nw]);
    int E = 3 - L - Nw;
    pause_server(L, 0);
    /* L deposed and back as a replica, its own copy naming Nw */
    uint64_t t0 = now_ms();
    for (;;) {
        struct meta_volume w;
        if (vol_rec(L, "fd", &w) && w.leader == v.leader && w.epoch == v.epoch)
            break;
        if (now_ms() - t0 > 30000)
            die("server %d never saw fd led by %u at epoch %" PRIu64, L, v.leader, v.epoch);
        usleep(50000);
    }
    await_isr(Nw, "fd", 3, 30000, "the deposed leader back in the ISR");
    /* wait until the new leader's replication driver has finished promoting (reopened as writer) before reading from it
     * with retries off; the metadata record and ISR count (kept across the promotion) are visible before that finishes */
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log(Nw, lead, 30000, "the new leader serving the volume");
    c = client(E);
    tsdbc_set_retry(c, 0);
    uint64_t f0 = fw_frames(c, oldlead);
    ts = 5000;
    t0 = now_ms();
    while ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) == TSDB_ERR_UNAVAILABLE && now_ms() - t0 < 10000)
        usleep(100000); /* E's link to L coming back */
    uint64_t f1 = fw_frames(c, oldlead);
    tsdbc_close(c);
    if (f1 <= f0)
        die("the write through %d (its copy held at epoch %" PRIu64 ") was not forwarded to %d: %s", E, e0, L, ers(rc));
    if (rc != TSDB_ERR_MOVED)
        die("a write forwarded to the deposed leader %d: %s, not MOVED", L, ers(rc));
    unlink(hold[E]);
    tsdbc *cn = client(Nw);
    nrows = 0;
    if ((rc = tsdbc_query_raw(cn, id, 5000, 5001, count_rows, NULL)) != 0) {
        tsdbc_err_info ei;
        int lrc = tsdbc_last_error(cn, &ei);
        die("a read on the new leader: %s (detail %d, nunavail %u, reason %u)", ers(rc), lrc,
            lrc == TSDB_ERR_UNAVAILABLE ? ei.nunavail : 0,
            lrc == TSDB_ERR_UNAVAILABLE && ei.nunavail ? ei.unavail[0].reason : 0);
    }
    tsdbc_close(cn);
    if (nrows != 0)
        die("the write answered MOVED by the deposed leader is on the new leader");
    stop_all();
    printf("  a write forwarded by %d (copy held at epoch %" PRIu64 ") to the deposed leader %d: MOVED, not applied on "
           "the new leader %d (epoch %" PRIu64 ")\n", E, e0, L, Nw, v.epoch);
}

/* fwdload (S2-2): forwarding under load, without login. Three servers, --workers 2 --fwd-workers 1 on each; two volumes of
 * one replica, vx led on X and vy on Y (X != Y).
 * f. A slow reader (QUERY_RAW of 6 M rows through Y, about 5 s to read) beside a stream of one-row inserts through Y to
 *    the same owner X: the reader's chunks wait for credit on X's only reserved worker, which must count as waiting
 *    (the pool grows), so every insert answers and their p99 stays small; the reader gets every row (ha.md 15.4: the
 *    insert p99 holds and the link survives). Mutant fwdchunknowait.
 * g. X and Y forward to each other under load: 4 clients on each write the other's volume and read 5-chunk replies
 *    from it; everything answers within the bound. Mutant fwdinline (a forward served on the links' dispatcher: two
 *    owners each wait for credit that only the other's dispatcher would let through). */
struct fl_read {
    tsdbc *c;
    tsdb_sid id;
    int64_t lo, hi;
    uint64_t rows, ms;
    int rc, slow;
    atomic_int done; /* set after rc and ms: the stream of inserts in f polls it while the reader runs */
};

static int fl_cb(void *ctx, const int64_t *ts, const float *v, size_t n)
{
    (void)ts, (void)v;
    struct fl_read *r = ctx;
    r->rows += n;
    if (r->slow) {
        struct timespec d = {0, (long)n * 800}; /* 6 M rows: about 5 s */
        nanosleep(&d, NULL);
    }
    return 0;
}

static void *fl_read_run(void *arg)
{
    struct fl_read *r = arg;
    uint64_t t0 = now_ms();
    r->rc = tsdbc_query_raw(r->c, r->id, r->lo, r->hi, fl_cb, r);
    r->ms = now_ms() - t0;
    atomic_store(&r->done, 1);
    return NULL;
}

#define FL_BIG 6000000
#define FL_T0 1700000000000LL

/* n rows of id from FL_T0, 10 ms apart, in calls of 500,000, on the leader */
static void fl_fill(tsdbc *c, tsdb_sid id, size_t n)
{
    size_t step = 500000;
    int64_t *ts = malloc(step * sizeof *ts);
    float *v = malloc(step * sizeof *v);
    if (!ts || !v)
        die("out of memory");
    for (size_t k = 0; k < n; k += step) {
        size_t m = n - k < step ? n - k : step;
        for (size_t i = 0; i < m; i++)
            ts[i] = FL_T0 + (int64_t)(k + i) * 10, v[i] = (float)(k + i);
        int rc = tsdbc_insert_series(c, id, ts, v, m);
        if (rc != 0)
            die("loading %zu rows: %s", n, ers(rc));
    }
    free(ts);
    free(v);
}

static int fl_cmp(const void *a, const void *b)
{
    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;
    return x < y ? -1 : x > y;
}

struct fl_peer {
    int s;              /* entry server */
    tsdb_sid big;       /* the other volume's big series (read) */
    char vol[16];       /* the other volume (written) */
    int k, rc, iters;
    const char *what;
    atomic_int *done;
};

static void *fl_peer_run(void *arg)
{
    struct fl_peer *p = arg;
    tsdbc *c = client(p->s);
    char nm[48];
    snprintf(nm, sizeof nm, "g.%d.%d", p->s, p->k);
    tsdb_sid id = rep_series(c, nm, p->vol, 30000);
    int64_t ts[100];
    float v[100];
    for (int it = 0; it < 200 && !p->rc; it++, p->iters++) {
        for (int i = 0; i < 100; i++)
            ts[i] = FL_T0 + (int64_t)(it * 100 + i) * 1000, v[i] = (float)i;
        if ((p->rc = tsdbc_insert_series(c, id, ts, v, 100)) != 0) {
            p->what = "insert";
            break;
        }
        if (it % 40 == 20) { /* 400,000 rows: 4.8 MB, five chunks, past the first credit of four */
            struct fl_read r = {.c = c, .id = p->big, .lo = FL_T0 + (int64_t)p->k * 1000000, .hi = 0};
            r.hi = r.lo + 400000LL * 10;
            fl_read_run(&r);
            if ((p->rc = r.rc) == 0 && r.rows != 400000)
                p->rc = -1000000 - (int)r.rows;
            if (p->rc)
                p->what = "read";
        }
    }
    tsdbc_close(c);
    atomic_fetch_add(p->done, 1);
    return NULL;
}

static void scen_fwdload(void)
{
    scenario("fwdload");
    strict_reads = 1;
    fwd_on = 1;
    const char *mut = getenv("TSDBD_FWD_MUTANT");
    static char menv[160];
    snprintf(menv, sizeof menv, "TSDBD_FWD_MUTANT=%s", mut ? mut : "");
    for (int i = 0; i < 3; i++) {
        penv[i] = menv;
        xargs[i] = "--workers 2 --fwd-workers 1";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    int X = -1, Y = -1, rc;
    char vx[16] = "", vy[16] = "";
    for (int k = 0; k < 12 && Y < 0; k++) {
        char nm[16];
        uint32_t num;
        struct meta_volume s;
        snprintf(nm, sizeof nm, "ld%d", k);
        if ((rc = vol_add(0, nm, 1, &num)) != 0)
            die("volume add %s: %s", nm, cluster_strerror(rc));
        if (!vol_rec(0, nm, &s))
            die("no record of %s", nm);
        int l = server_of(s.leader);
        await_open_gen(0, nm, l, 1, 0);
        if (X < 0)
            X = l, snprintf(vx, sizeof vx, "%s", nm);
        else if (l != X)
            Y = l, snprintf(vy, sizeof vy, "%s", nm);
    }
    if (Y < 0)
        die("12 volumes of one replica, all led on server %d", X);

    tsdbc *cx = client(X), *cy = client(Y);
    tsdb_sid bigx = rep_series(cx, "f.big", vx, 30000), bigy = rep_series(cy, "g.big", vy, 30000);
    tsdb_sid small = rep_series(cx, "f.small", vx, 30000);
    fl_fill(cx, bigx, FL_BIG);
    fl_fill(cy, bigy, 4 * 1000000 / 10 + 400000); /* every thread's window of g (k * 1e6 ms + 400,000 rows) */
    tsdbc_close(cx);
    tsdbc_close(cy);

    /* f. the slow reader and the insert stream, both through Y to X */
    struct fl_read r = {.c = client(Y), .id = bigx, .lo = 0, .hi = INT64_MAX / 2, .slow = 1};
    pthread_t th;
    if (pthread_create(&th, NULL, fl_read_run, &r) != 0)
        die("pthread_create");
    usleep(700000);
    tsdbc *ci = client(Y);
    uint64_t lat[4096];
    size_t nl = 0;
    for (int64_t t = FL_T0; nl < sizeof lat / sizeof lat[0]; t += 1000) {
        float v = 1;
        uint64_t t0 = now_ms();
        rc = tsdbc_insert_series(ci, small, &t, &v, 1);
        lat[nl++] = now_ms() - t0;
        if (rc != 0)
            die("insert %zu through %d to %d beside a slow reader: %s after %" PRIu64 " ms", nl, Y, X, ers(rc),
                lat[nl - 1]);
        if (atomic_load(&r.done))
            break;
        usleep(5000);
    }
    pthread_join(th, NULL);
    tsdbc_close(r.c);
    tsdbc_close(ci);
    if (r.rc != 0 || r.rows != FL_BIG)
        die("the slow reader through %d: %s, %" PRIu64 " rows of %d", Y, ers(r.rc), r.rows, FL_BIG);
    if (r.ms < 3000)
        die("the slow reader took %" PRIu64 " ms: not slow enough to hold the owner's worker", r.ms);
    qsort(lat, nl, sizeof lat[0], fl_cmp);
    uint64_t p99 = lat[nl * 99 / 100], mx = lat[nl - 1];
    if (nl < 50)
        die("only %zu inserts beside the slow reader", nl);
    if (p99 > 300)
        die("inserts through %d to %d beside a slow reader (%" PRIu64 " ms, --fwd-workers 1): p99 %" PRIu64
            " ms, max %" PRIu64 " ms over %zu",
            Y, X, r.ms, p99, mx, nl);
    printf("  a slow reader of %d rows through %d (%" PRIu64 " ms) beside %zu inserts to the same owner %d: insert "
           "p50 %" PRIu64 " ms, p99 %" PRIu64 " ms, max %" PRIu64 " ms\n",
           FL_BIG, Y, r.ms, nl, X, lat[nl / 2], p99, mx);

    /* g. X and Y forward to each other: writes to the other's volume, reads of 5 chunks from it */
    atomic_int done = 0;
    struct fl_peer pp[8];
    pthread_t pt[8];
    for (int k = 0; k < 8; k++) {
        int s = k < 4 ? X : Y;
        pp[k] = (struct fl_peer){.s = s, .k = k % 4, .big = s == X ? bigy : bigx, .done = &done};
        snprintf(pp[k].vol, sizeof pp[k].vol, "%s", s == X ? vy : vx);
        if (pthread_create(&pt[k], NULL, fl_peer_run, &pp[k]) != 0)
            die("pthread_create");
    }
    uint64_t t0 = now_ms();
    while (atomic_load(&done) < 8) {
        if (now_ms() - t0 > 90000) {
            for (int k = 0; k < 8; k++)
                fprintf(stderr, "  client %d on %d: %d of 200 rounds\n", k, pp[k].s, pp[k].iters);
            die("servers %d and %d forwarding to each other (--workers 2) did not finish in 90 s", X, Y);
        }
        usleep(20000);
    }
    uint64_t took = now_ms() - t0;
    for (int k = 0; k < 8; k++) {
        pthread_join(pt[k], NULL);
        if (pp[k].rc)
            die("client %d on %d forwarding to %d: its %s after %d rounds: %s", k, pp[k].s, pp[k].s == X ? Y : X,
                pp[k].what, pp[k].iters, pp[k].rc < -1000000 ? "a short read" : ers(pp[k].rc));
    }
    stop_all();
    printf("  servers %d and %d forwarding to each other (8 clients, --workers 2): 1,600 inserts and 40 reads of 4.8 MB "
           "in %" PRIu64 " ms\n",
           X, Y, took);
}


/* promoteslow (review F3): a promotion that takes longer than the 3 s after which the Raft leader takes a record leader
 * whose driver does not lead for deposed (leader_deposed: a fence nobody followed up). Every server's swap to the writer
 * waits 5 s first (TSDB_REPLD_TEST=promoteslow: a reopen of a large volume or on a loaded host; jepsen saw 7.7 s). The
 * new leader reports PROMOTING to the record's epoch meanwhile, so the record stays at e0 + 1 and that leader takes
 * writes; mutant promotenone (role NONE while promoting) fences it again and the record moves on to e0 + 2 and beyond
 * (the volume's first promotion is as slow, so under the mutant it may get no writer at all). The swap's 5 s in the
 * volume thread are the thread's own silence, not its peers': the new leader must not ask for an ISR of one after it
 * (repld.c long_step), which the group takes for a leader cut from its replicas and moves away. */
/* tsdbc-bench via (S2-2): the bench of the forwarding hop runs end to end against three members, a volume of three
 * replicas, once through its leader and once through a replica, every write and read checked by the bench itself and
 * the leader holding every row at the end; the entry node must have forwarded frames (STATUS), the numbers must be
 * printed (hop, mean and sd over the reps, CPU per 1000 requests of the three processes). A bench that is given an
 * entry that is no server must fail, not print numbers. */
static void scen_viabench(void)
{
    scenario("viabench");
    strict_reads = 1;
    fwd_on = 1;
    for (int i = 0; i < 3; i++) {
        xargs[i] = "--workers 2";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    struct meta_volume v;
    int rc;
    if ((rc = vol_add(0, "east", 3, &num)) != 0)
        die("volume add east: %s", cluster_strerror(rc));
    if (!vol_rec(0, "east", &v))
        die("no record of east");
    for (uint32_t k = 0; k < v.nrep; k++)
        await_open_gen(0, "east", server_of(v.rep[k].node), 1, 0);
    await_isr(0, "east", 3, 20000, "east with every replica up");
    int L = server_of(v.leader), R = (L + 1) % 3;
    tsdbc *cr = client(R);
    uint64_t f0 = fw_frames(cr, v.leader);

    const char *bench = getenv("TSDBC_BENCH") ? getenv("TSDBC_BENCH") : "./build/tsdbc-bench";
    char cmd[PATH_MAX + 512], line[1024], text[16384];
    snprintf(cmd, sizeof cmd,
             "%s via --host 127.0.0.1 --port %d --via 127.0.0.1:%d --volume east --conns 2 --rows 50 --seconds 1 "
             "--reps 2 --pids %d,%d,%d 2>&1",
             bench, cports[L], cports[R], (int)pids[0], (int)pids[1], (int)pids[2]);
    FILE *p = popen(cmd, "r");
    if (!p)
        die("popen %s: %s", cmd, strerror(errno));
    size_t o = 0;
    text[0] = 0;
    while (fgets(line, sizeof line, p))
        o += (size_t)snprintf(text + o, o < sizeof text ? sizeof text - o : 0, "%s", line);
    int st = pclose(p);
    if (st != 0)
        die("`%s` failed (status %d):\n%s", cmd, st, text);
    static const char *const must[] = {"rep 1 ", "rep 2 ", "direct", " via ", "hop (via - direct)", "write p50 (ms)",
                                       "read p99 (ms)", "requests a second", "CPU ms per 1000 requests",
                                       "the leader holds them all"};
    for (unsigned k = 0; k < sizeof must / sizeof *must; k++)
        if (!strstr(text, must[k]))
            die("the bench's output lacks '%s':\n%s", must[k], text);
    uint64_t f1 = fw_frames(cr, v.leader);
    if (f1 <= f0 + 10)
        die("the bench ran through server %d and it forwarded %" PRIu64 " frames to the leader %d (STATUS "
            "peer.<id>.fwd.frames %" PRIu64 " to %" PRIu64 ")", R, f1 - f0, L, f0, f1);
    tsdbc_close(cr);
    printf("  tsdbc-bench via through server %d to the leader %d: %" PRIu64 " frames forwarded; its output:\n%s", R, L,
           f1 - f0, text);

    /* an entry that is no server: an error, no numbers */
    snprintf(cmd, sizeof cmd,
             "%s via --host 127.0.0.1 --port %d --via 127.0.0.1:1 --volume east --conns 1 --seconds 1 --reps 1 2>&1",
             bench, cports[L]);
    p = popen(cmd, "r");
    if (!p)
        die("popen %s: %s", cmd, strerror(errno));
    o = 0;
    text[0] = 0;
    while (fgets(line, sizeof line, p))
        o += (size_t)snprintf(text + o, o < sizeof text ? sizeof text - o : 0, "%s", line);
    st = pclose(p);
    if (st == 0 || strstr(text, "hop (via - direct)"))
        die("the bench against an entry that is no server went well (status %d):\n%s", st, text);
    printf("  an entry that is no server: %s", text);

    /* an entry that forwards nothing (the leader itself): its numbers would be "direct" under the name "via" (review
     * F7): the bench must say so and print no hop */
    snprintf(cmd, sizeof cmd,
             "%s via --host 127.0.0.1 --port %d --via 127.0.0.1:%d --volume east --conns 1 --seconds 1 --reps 2 2>&1",
             bench, cports[L], cports[L]);
    p = popen(cmd, "r");
    if (!p)
        die("popen %s: %s", cmd, strerror(errno));
    o = 0;
    text[0] = 0;
    while (fgets(line, sizeof line, p))
        o += (size_t)snprintf(text + o, o < sizeof text ? sizeof text - o : 0, "%s", line);
    st = pclose(p);
    if (st == 0 || strstr(text, "hop (via - direct)") || !strstr(text, "forwarded 0 frames"))
        die("the bench against an entry that forwards nothing went well or said nothing (status %d):\n%s", st, text);
    printf("  an entry that forwards nothing: refused\n");
}

static void scen_promoteslow(void)
{
    scenario("promoteslow");
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=promoteslow";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "ps", 3, &num)) != 0 || num != 1)
        die("volume add ps: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "ps", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "ps", &v))
        die("no record of ps");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of ps is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "ps", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    tsdbc_close(c);
    await_isr(0, "ps", 3, 30000, "every replica in the ISR before the kill");
    signal_child(pids[L], SIGKILL);
    if (await_exit(L, 5000) < 0)
        die("server %d did not die of SIGKILL", L);
    int via = (L + 1) % 3;
    int Nw = await_promoted(via, "ps", ids[L], e0, &v);
    if (Nw < 0 || Nw == L || v.epoch != e0 + 1)
        die("the new record of ps: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v.epoch, e0, v.leader);
    uint64_t tr = now_ms();
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", e0 + 1);
    await_log_count(Nw, lead, 1, 30000);
    uint64_t tl = now_ms();
    /* past the 5 s of the swap and the 3 s of leader_deposed, with margin: the record must not have moved on */
    while (now_ms() - tr < 12000) {
        struct meta_volume w;
        if (vol_rec(via, "ps", &w) && (w.epoch != e0 + 1 || w.leader != v.leader))
            die("the record of ps moved past epoch %" PRIu64 " (leader %u): epoch %" PRIu64 ", leader %u, %" PRIu64
                " ms after the promotion; a slow promotion was taken for a deposed leader", e0 + 1, v.leader, w.epoch,
                w.leader, now_ms() - tr);
        usleep(100000);
    }
    c = client(Nw);
    tsdbc_set_retry(c, 10000);
    ts = 2000;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write to the slowly promoted leader %d: %s", Nw, ers(rc));
    tsdbc_close(c);
    printf("  a promotion of %" PRIu64 " ms (5 s of it before the swap): the record stayed at epoch %" PRIu64
           " and server %d took writes\n", tl - tr, e0 + 1, Nw);
}


/* openread (r3e fixer, jepsen kill-classes): a restarted server opens a replicated volume's engine as a replica at REPL's
 * floor (repld_open) a moment before the volume manager counts the volume open; a restarted leader's floor lies below
 * what it acknowledged before the kill, and a read it answered in that window went back in time (stale read and
 * monotonic reads in jepsen-cluster). TSDB_REPLD_TEST=openslow holds the window open for 3 s: a raw query and a
 * QUERY_LATEST on that server meanwhile are refused (UNAVAILABLE, RECOVERING), never answered. */
static void scen_openread(void)
{
    scenario("openread");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "or", 3, &num)) != 0 || num != 1)
        die("volume add or: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "or", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "or", &v))
        die("no record of or");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of or is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "or", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every replica up: %s", ers(rc));
    tsdbc_close(c);
    await_isr(0, "or", 3, 30000, "every replica in the ISR before the restart");
    int R = (L + 1) % 3;
    signal_child(pids[R], SIGKILL);
    if (await_exit(R, 5000) < 0)
        die("server %d did not die of SIGKILL", R);
    penv[R] = "TSDB_REPLD_TEST=openslow";
    start(R);
    penv[R] = NULL;
    await_log_count(R, "(openslow)", 1, 30000);
    c = client(R);
    tsdb_points p;
    rc = tsdbc_query_points(c, id, INT64_MIN, INT64_MAX, &p);
    if (rc == 0)
        die("a raw query on server %d while its volume opens: answered (%zu rows) from the engine at REPL's floor", R,
            p.n);
    expect_unavail(c, rc, (uint16_t)num, TSDB_WHY_RECOVERING, "a raw query while the volume opens");
    tsdb_latest_result lr;
    rc = tsdbc_latest(c, &id, 1, NULL, &lr);
    if (rc == 0 && lr.status == 0)
        die("QUERY_LATEST on server %d while its volume opens: answered", R);
    expect_unavail(c, rc, (uint16_t)num, TSDB_WHY_RECOVERING, "QUERY_LATEST while the volume opens");
    tsdbc_close(c);
    printf("  server %d refused a raw query and QUERY_LATEST while its replica engine was open but the volume was not\n",
           R);
}

/* openreadlead (int-r review F2): openread on the production path (strict reads, D5) and for the LEADER: L, which
 * acknowledged writes, is killed and restarted with TSDB_REPLD_TEST=openslow, so its engine is open as a replica at
 * REPL's floor (below what L acknowledged) for 3 s before the manager counts the volume open. A raw query and a
 * QUERY_LATEST on L meanwhile go through route_decide (route_fill: UNAVAILABLE RECOVERING where the copy still names
 * L, MOVED where it names the leader that replaced it) and must never be answered from that engine. */
static void scen_openreadlead(void)
{
    scenario("openreadlead");
    strict_reads = 1;
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "ol", 3, &num)) != 0 || num != 1)
        die("volume add ol: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "ol", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "ol", &v))
        die("no record of ol");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of ol is node %u", v.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "ol", 30000);
    int acked = 0;
    for (; acked < 50; acked++) {
        int64_t ts = 1000000 + 1000LL * acked;
        float val = (float)acked;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", acked, ers(rc));
    }
    tsdbc_close(c);
    await_isr(0, "ol", 3, 30000, "every replica in the ISR before the restart");
    signal_child(pids[L], SIGKILL);
    if (await_exit(L, 5000) < 0)
        die("server %d did not die of SIGKILL", L);
    penv[L] = "TSDB_REPLD_TEST=openslow";
    start(L);
    penv[L] = NULL;
    await_log_count(L, "(openslow)", 1, 30000);
    c = client(L);
    tsdbc_set_retry(c, 0); /* the first answer, not a followed one */
    tsdb_points p;
    rc = tsdbc_query_points(c, id, INT64_MIN, INT64_MAX, &p);
    if (rc == 0)
        die("a raw query on the restarted leader %d while its volume opens: answered (%zu of %d acknowledged rows) "
            "from the engine at REPL's floor", L, p.n, acked);
    int why = -1;
    tsdb_unavail e;
    unsigned n = 0;
    if (rc == TSDB_ERR_UNAVAILABLE && tsdbc_unavailable(c, &e, 1, &n) == 0 && n == 1)
        why = e.reason;
    if (!(rc == TSDB_ERR_MOVED || (rc == TSDB_ERR_UNAVAILABLE && why == TSDB_WHY_RECOVERING)))
        die("a raw query on the restarted leader %d while its volume opens: %s (reason %d), not UNAVAILABLE "
            "(RECOVERING) or MOVED", L, ers(rc), why);
    const char *raw = rc == TSDB_ERR_MOVED ? "MOVED" : "UNAVAILABLE (RECOVERING)";
    tsdb_latest_result lr;
    rc = tsdbc_latest(c, &id, 1, NULL, &lr);
    if (rc == 0 && lr.status == 0)
        die("QUERY_LATEST on the restarted leader %d while its volume opens: answered", L);
    if (rc == 0)
        rc = lr.status;
    why = -1, n = 0;
    if (rc == TSDB_ERR_UNAVAILABLE && tsdbc_unavailable(c, &e, 1, &n) == 0 && n == 1)
        why = e.reason;
    if (!(rc == TSDB_ERR_MOVED || (rc == TSDB_ERR_UNAVAILABLE && why == TSDB_WHY_RECOVERING)))
        die("QUERY_LATEST on the restarted leader %d while its volume opens: %s (reason %d), not UNAVAILABLE "
            "(RECOVERING) or MOVED", L, ers(rc), why);
    tsdbc_close(c);
    printf("  restarted leader %d, its engine open at REPL's floor: a raw query %s, QUERY_LATEST %s\n", L, raw,
           rc == TSDB_ERR_MOVED ? "MOVED" : "UNAVAILABLE (RECOVERING)");
}

/* jointpause (r3e jc7, finding P): every server of a volume stopped together for 2 s (SIGSTOP: a VM pause, a host
 * that froze) and resumed. Nobody was silent but for the stop itself: the leader must not catch the 2 s up in ticks
 * (every peer then looks silent for isr_lag and it asks for an ISR of one) and no member may name a peer unreachable for
 * its own stop (a cut that deposes the leader: the pause scenario's write after MOVED got a closed connection). The
 * record keeps its epoch and its ISR version, and a write is acknowledged (mutant stallcatchup). */
static void scen_jointpause(void)
{
    scenario("jointpause");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "jp", 3, &num)) != 0 || num != 1)
        die("volume add jp: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "jp", i, 1, 0);
    struct meta_volume v0, v;
    if (!vol_rec(0, "jp", &v0))
        die("no record of jp");
    int L = server_of(v0.leader);
    if (L < 0 || L > 2)
        die("the leader of jp is node %u", v0.leader);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "jp", 30000);
    int64_t ts = 1000;
    float val = 1;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write with every server up: %s", ers(rc));
    await_isr(0, "jp", 3, 30000, "every replica in the ISR before the stop");
    if (!vol_rec(0, "jp", &v0))
        die("no record of jp");
    for (int round = 0; round < 3; round++) {
        for (int i = 0; i < 3; i++)
            pause_server(i, 1);
        nanosleep(&(struct timespec){2, 0}, NULL);
        for (int i = 0; i < 3; i++)
            pause_server(i, 0);
        for (uint64_t t0 = now_ms(); now_ms() - t0 < 4000; usleep(20000)) {
            for (int i = 0; i < 3; i++)
                if (vol_rec(i, "jp", &v) && (v.epoch != v0.epoch || v.isr_version != v0.isr_version || v.nisr != 3))
                    die("round %d: after a stop of every server the record of jp (via server %d) has epoch %" PRIu64
                        " (was %" PRIu64 "), ISR version %" PRIu64 " (was %" PRIu64 ") of %" PRIu32 " members: a "
                        "member took the stop for its peers' silence", round, i, v.epoch, v0.epoch, v.isr_version,
                        v0.isr_version, v.nisr);
        }
        ts = 2000 + round;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("round %d: a write to the leader after a stop of every server: %s", round, ers(rc));
    }
    tsdbc_close(c);
    stop_all();
    uint64_t wantr[REP_NAMES] = {4, 0, 0, 0};
    rep_same(wantr, "after three stops of every server");
    printf("  three stops of every server for 2 s: epoch %" PRIu64 " and ISR version %" PRIu64 " kept, writes go on\n",
           v0.epoch, v0.isr_version);
}

/* design-cluster.md 6.2 (r3e-failover, item 6): the leader of a replicated volume is killed and restarted before the
 * group sees it down (node_timeout 20 s here). Its REPL says it led epoch e, so it never resumes: its core sends
 * RESIGN(v, e), the Raft leader fences the ISR at once (reason RESIGNED, no node_timeout) and the record moves to e+1, the restarted server again
 * when it is still the best; every acknowledged write is there and the new leader takes writes. */
static void scen_resign(void)
{
    scenario("resign");
    strict_reads = 1; /* every read on the leader (D5), as in production */
    for (int i = 0; i < 3; i++)
        start(i);
    init_node_timeout_ms = 20000; /* the restart (open generation recorded, then the core) must beat detection */
    init_cluster(0, 600);
    init_node_timeout_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "rs", 3, &num)) != 0 || num != 1)
        die("volume add rs: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "rs", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "rs", &v))
        die("no record of rs");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of rs is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "rs", 30000);
    int acked = 0;
    for (; acked < 50; acked++) {
        int64_t ts = 1000000 + 1000LL * acked;
        float val = (float)acked;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", acked, ers(rc));
    }
    tsdbc_close(c);
    await_isr(0, "rs", 3, 30000, "every replica in the ISR before the restart");
    signal_child(pids[L], SIGKILL);
    if (await_exit(L, 5000) < 0)
        die("server %d did not die of SIGKILL", L);
    uint64_t tk = now_ms();
    start(L);
    uint64_t ts0 = now_ms();
    char line[96];
    snprintf(line, sizeof line, "cannot lead epoch %" PRIu64 " (led it before a restart); resigns", e0);
    await_log_count(L, line, 1, 30000);
    int via = (L + 1) % 3;
    for (;;) {
        if (vol_rec(via, "rs", &v) && v.epoch > e0)
            break;
        if (now_ms() - ts0 > 30000)
            die("no new record of rs 30 s after its leader restarted (epoch %" PRIu64 ", leader %u)", v.epoch, v.leader);
        usleep(20000);
    }
    uint64_t tr = now_ms();
    int Nw = server_of(v.leader);
    if (v.epoch != e0 + 1 || Nw < 0 || Nw > 2)
        die("the new record of rs: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v.epoch, e0, v.leader);
    /* the RESIGN moves it, not detection: the restart usually made another server the Raft leader, which must record
     * the new incarnation (the volume opens only then) without waiting out its node_timeout of 20 s first; and the
     * restarted server, at a new peer port nobody dials, must find the others at once (its watch), not after 10 s */
    if (tr - ts0 >= 10000)
        die("the record of rs moved %" PRIu64 " ms after its leader restarted: that is detection (node_timeout 20 s), "
            "not the RESIGN", tr - ts0);
    int resigned = 0;
    for (int i = 0; i < 3; i++)
        resigned += log_count(i, "(reason 7); fences");
    if (!resigned)
        die("the record moved to epoch %" PRIu64 " but no Raft leader promoted for a RESIGN (reason 7)", v.epoch);
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(Nw, lead, 1, 30000);
    int got = rows_in(Nw, id, 1000000, 1000000 + 1000LL * acked, 30000);
    if (got != acked)
        die("the leader at epoch %" PRIu64 " (server %d) holds %d of the %d acknowledged rows", v.epoch, Nw, got, acked);
    c = client(Nw);
    tsdbc_set_retry(c, 10000);
    int64_t ts = 9000000;
    float val = 7;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write to the leader at epoch %" PRIu64 ": %s", v.epoch, ers(rc));
    tsdbc_close(c);
    printf("  leader %d restarted %" PRIu64 " ms after its kill resigned epoch %" PRIu64 ": server %d%s leads epoch %"
           PRIu64 " %" PRIu64 " ms after the restart, with all %d acknowledged rows\n", L, ts0 - tk, e0, Nw,
           Nw == L ? " (the restarted one, still the best)" : "", v.epoch, tr - ts0, acked);
    await_isr(via, "rs", 3, 60000, "every server in the ISR after the resign");
    stop_all();
    uint64_t wantr[REP_NAMES] = {0};
    wantr[0] = (uint64_t)acked + 1;
    rep_same(wantr, "after the resign");
}

/* D13 for a volume the restarted leader cannot open (r3c review F4): the leader of a replicated volume is killed, its
 * REPL removed, and it is restarted before the group sees it down (node_timeout 20 s). The manager refuses the volume
 * (MV_REFUSED: no driver, no RESIGN), and the server is UP, so only its heartbeat can tell the group: it reports the
 * volume LOCAL_FAULT, and the Raft leader promotes another replica at e+1 (reason FENCED) well before node_timeout.
 * Before, a refused volume was left out of the report and the volume had no writer for as long as the server ran. */
static void scen_refused(void)
{
    scenario("refused");
    for (int i = 0; i < 3; i++)
        start(i);
    init_node_timeout_ms = 20000;
    init_cluster(0, 600);
    init_node_timeout_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "rf", 3, &num)) != 0 || num != 1)
        die("volume add rf: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "rf", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "rf", &v))
        die("no record of rf");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of rf is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "rf", 30000);
    int acked = 0;
    for (; acked < 50; acked++) {
        int64_t ts = 1000000 + 1000LL * acked;
        float val = (float)acked;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", acked, ers(rc));
    }
    tsdbc_close(c);
    await_isr(0, "rf", 3, 30000, "every replica in the ISR before the restart");
    signal_child(pids[L], SIGKILL);
    if (await_exit(L, 5000) < 0)
        die("server %d did not die of SIGKILL", L);
    char path[2 * PATH_MAX];
    snprintf(path, sizeof path, "%s/n%d/v%" PRIu32 "/REPL", base, L, num);
    if (unlink(path) != 0)
        die("unlink %s: %s", path, strerror(errno));
    start(L);
    uint64_t ts0 = now_ms();
    await_log_count(L, "/REPL is missing: the volume is not opened", 1, 30000);
    int via = (L + 1) % 3;
    for (;;) {
        if (vol_rec(via, "rf", &v) && v.epoch > e0)
            break;
        if (now_ms() - ts0 > 15000)
            die("no new record of rf 15 s after its leader came back unable to open it (epoch %" PRIu64 ", leader %u): "
                "the refused volume was not reported", v.epoch, v.leader);
        usleep(20000);
    }
    uint64_t tr = now_ms();
    int Nw = server_of(v.leader);
    if (v.epoch != e0 + 1 || Nw < 0 || Nw > 2 || Nw == L)
        die("the new record of rf: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v.epoch, e0, v.leader);
    int fenced = 0;
    for (int i = 0; i < 3; i++)
        fenced += log_count(i, "(reason 4); fences");
    if (!fenced)
        die("the record moved to epoch %" PRIu64 " but no Raft leader promoted for a fault (reason 4)", v.epoch);
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(Nw, lead, 1, 30000);
    int got = rows_in(Nw, id, 1000000, 1000000 + 1000LL * acked, 30000);
    if (got != acked)
        die("the leader at epoch %" PRIu64 " (server %d) holds %d of the %d acknowledged rows", v.epoch, Nw, got, acked);
    c = client(Nw);
    tsdbc_set_retry(c, 10000);
    int64_t ts = 9000000;
    float val = 7;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write to the leader at epoch %" PRIu64 ": %s", v.epoch, ers(rc));
    tsdbc_close(c);
    printf("  leader %d restarted without its REPL: refused, reported, server %d leads epoch %" PRIu64 " %" PRIu64
           " ms after the restart, with all %d acknowledged rows\n", L, Nw, v.epoch, tr - ts0, acked);
    stop_all();
}

static void cut_file(int at, int from, int on)
{
    char f[PATH_MAX + 64];
    server_dir(at, f, sizeof f);
    snprintf(f + strlen(f), sizeof f - strlen(f), "/cutfrom.%" PRIu32, ids[from]);
    if (on) {
        FILE *fp = fopen(f, "w");
        if (!fp)
            die("create %s", f);
        fclose(fp);
    } else if (unlink(f) != 0 && errno != ENOENT) {
        die("unlink %s", f);
    }
}

/* oneway (review F6): the case the fence-then-promote wait exists for. The volume leader L (not the Raft leader R) is
 * cut from its replicas on the data links (TSDB_REPLD_TEST=cutlinks), drops every FENCE it receives and hears no
 * volume record (TSDB_CLUSTER_TEST drop_fence_file=1), while its heartbeats still reach R: it stays UP, holds a lease
 * and answers its clients. R moves the volume (the replicas report losing L) and may name the new leader only once L
 * answered the fence or L's last lease has ended, and gives L no lease meanwhile; the move does not give up at
 * PROMO_MOVE_NS while a replica answered (it did, and the ISR shrank to L alone with no new leader). A reader on L logs every read; once the new leader
 * acknowledged its first write, no read sent to L after that ack may be answered (a stale read: L does not have the
 * row). Mutants: fencelease (L keeps its lease: no promotion within 30 s), oldpass (the promotion goes ahead at once: L
 * answers reads after the ack). */
struct ow_read {
    uint64_t sent;
    int rc, kind, rows;
};
struct ow_reader {
    int server;
    tsdb_sid id;
    struct ow_read *log;
    size_t n, cap;
    int stop; /* __atomic */
};
static void *ow_reader_thread(void *a)
{
    struct ow_reader *r = a;
    tsdbc *c = client(r->server);
    for (int k = 0; r->n < r->cap && !__atomic_load_n(&r->stop, __ATOMIC_RELAXED); k++) {
        struct ow_read *e = &r->log[r->n];
        e->kind = k % 3;
        e->sent = now_ms();
        e->rc = lease_read(c, r->id, e->kind, &e->rows);
        r->n++;
        usleep(200);
    }
    tsdbc_close(c);
    return NULL;
}

/* L leads `name` at e0 with `acked` rows of `id`, every server in its ISR: cut it one way (above), read on it through
 * the promotion and check that no read sent after the new leader's first acknowledged write is answered; then the links
 * come back and the new leader holds every row. replay: L sends again the fence answers it gave while it was promoted
 * (oneway2). */
static void ow_cut_promote(int L, const char *name, tsdb_sid id, int acked, uint32_t num, uint64_t e0, uint32_t old,
                           int replay)
{
    struct meta_volume v;
    int rc;
    struct ow_reader rd = {.server = L, .id = id, .cap = 1u << 20};
    if (!(rd.log = calloc(rd.cap, sizeof *rd.log)))
        die("out of memory");
    pthread_t th;
    if (pthread_create(&th, NULL, ow_reader_thread, &rd) != 0)
        die("pthread_create");
    char df[PATH_MAX + 64];
    server_dir(L, df, sizeof df);
    strcat(df, "/state/dropfence");
    FILE *fp = fopen(df, "w");
    if (!fp)
        die("create %s: %s", df, strerror(errno));
    fclose(fp);
    char rf[PATH_MAX + 64];
    server_dir(L, rf, sizeof rf);
    strcat(rf, "/state/replayreply");
    if (replay) {
        if (!(fp = fopen(rf, "w")))
            die("create %s: %s", rf, strerror(errno));
        fclose(fp);
    }
    uint64_t t0 = now_ms();
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 1);
            cut_file(i, L, 1);
        }
    int Nw = await_promoted(0, name, old, e0, &v);
    uint64_t tp = now_ms();
    if (Nw == L || Nw < 0 || Nw > 2)
        die("the record of %s after the cut names node %u at epoch %" PRIu64, name, v.leader, v.epoch);
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(Nw, lead, 1, 30000);
    tsdbc *cn = client(Nw);
    tsdbc_set_retry(cn, 10000);
    int64_t ts = 9000000;
    float val = 7;
    if ((rc = tsdbc_insert_series(cn, id, &ts, &val, 1)) != 0)
        die("the first write to the leader at epoch %" PRIu64 " (server %d): %s", v.epoch, Nw, ers(rc));
    uint64_t tack = now_ms();
    tsdbc_close(cn);
    usleep(2000000); /* reads on L go on past the ack */
    __atomic_store_n(&rd.stop, 1, __ATOMIC_RELAXED);
    pthread_join(th, NULL);
    size_t after = 0, answered = 0;
    uint64_t last_ok = 0;
    for (size_t i = 0; i < rd.n; i++) {
        const struct ow_read *e = &rd.log[i];
        if (e->rc == 0) {
            answered++;
            last_ok = e->sent;
            int want = e->kind == 1 ? 1 : acked;
            if (e->rows != want)
                die("a read on the old leader (kind %d) %" PRIu64 " ms after the cut answered %d rows, not %d", e->kind,
                    e->sent - t0, e->rows, want);
        } else if (e->rc != TSDB_ERR_UNAVAILABLE && e->rc != TSDB_ERR_MOVED) {
            die("a read on the old leader %" PRIu64 " ms after the cut: %s", e->sent - t0, ers(e->rc));
        }
        if (e->sent > tack) {
            after++;
            if (e->rc == 0)
                die("a read sent to the old leader %" PRIu64 " ms after the new leader's first acknowledged write was "
                    "answered (%" PRIu64 " ms after the cut, promotion seen at %" PRIu64 " ms): a stale read",
                    e->sent - tack, e->sent - t0, tp - t0);
        }
    }
    if (!after || !answered)
        die("%zu reads on the old leader after the ack, %zu answered in all (%zu reads): the test saw nothing", after,
            answered, rd.n);
    free(rd.log);
    unlink(df); /* L hears the record again: a write is MOVED */
    unlink(rf);
    tsdbc *co = client(L);
    insert_expect_moved(co, id, 9500000, 1, (uint16_t)num, v.leader, v.epoch, "a write to the old leader");
    tsdbc_close(co);
    printf("  leader %d cut from its replicas, fences dropped, heartbeats whole: server %d leads epoch %" PRIu64
           " %" PRIu64 " ms after the cut; %zu reads on %d, the last answered at %" PRIu64 " ms, none of %zu after the "
           "new leader's first ack (%" PRIu64 " ms)\n", L, Nw, v.epoch, tp - t0, rd.n, L, last_ok - t0, after,
           tack - t0);
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 0);
            cut_file(i, L, 0);
        }
    int got = rows_in(Nw, id, 1000000, 9000001, 30000);
    if (got != acked + 1)
        die("the leader at epoch %" PRIu64 " (server %d) holds %d rows, %d were acknowledged", v.epoch, Nw, got,
            acked + 1);
    await_isr(Nw, name, 3, 60000, "every server in the ISR once the links are back");
}

static void scen_oneway(void)
{
    scenario("oneway");
    strict_reads = 1; /* every read on the leader (D5): a replica's reads are not the question here */
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=cutlinks";
        envs[i] = "drop_fence_file=1";
    }
    lease_cluster(3, 5000, 200000, 3000); /* L's lease runs 4 s past its last grant; R waits 6 s */
    int L = -1, rc;
    uint32_t num = 0;
    char name[16];
    struct meta_volume v;
    for (int k = 0; k < 8 && L < 0; k++) {
        snprintf(name, sizeof name, "ow%d", k);
        if ((rc = vol_add(0, name, 3, &num)) != 0)
            die("volume add %s: %s", name, cluster_strerror(rc));
        if (!vol_rec(0, name, &v))
            die("no record of %s", name);
        int s = server_of(v.leader);
        if (s >= 1 && s <= 2)
            L = s;
    }
    if (L < 0)
        die("eight volumes, every one led by the Raft leader");
    for (int i = 0; i < 3; i++) /* every server opened it: a series made before L knows the volume is NOTFOUND */
        await_open_gen(0, name, i, 1, 0);
    uint64_t e0 = v.epoch;
    uint32_t old = v.leader;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], name, 30000);
    int acked = 0;
    for (; acked < 20; acked++) {
        int64_t ts = 1000000 + 1000LL * acked;
        float val = (float)acked;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", acked, ers(rc));
    }
    tsdbc_close(c);
    await_isr(L, name, 3, 30000, "every replica in the ISR before the cut");
    ow_cut_promote(L, name, id, acked, num, e0, old, 0);
    stop_all();
}

/* oneway2 (review R2): a late answer to an earlier fence must not count as the old leader's answer now. Server 0 (the
 * Raft leader) leads; its data links are cut and a replica N is promoted to e0 + 1, keeping a copy of its answer to
 * fence e0 + 1 (TSDB_CLUSTER_TEST hold_reply_file=1). Once every server is back in the ISR, N is cut one way as in
 * oneway and sends that old answer again every round: the promotion to e0 + 2 still waits for N's lease. Mutant
 * anyepoch (an answer of any epoch counted) promotes at once and N answers reads after the new leader's first ack. */
static void scen_oneway2(void)
{
    scenario("oneway2");
    strict_reads = 1;
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=cutlinks";
        envs[i] = "drop_fence_file=1,hold_reply_file=1";
    }
    lease_cluster(3, 5000, 200000, 3000);
    int rc, L0 = -1;
    uint32_t num = 0;
    char name[16];
    struct meta_volume v;
    for (int k = 0; k < 8 && L0 < 0; k++) {
        snprintf(name, sizeof name, "ox%d", k);
        if ((rc = vol_add(0, name, 3, &num)) != 0)
            die("volume add %s: %s", name, cluster_strerror(rc));
        if (!vol_rec(0, name, &v))
            die("no record of %s", name);
        if (server_of(v.leader) == 0)
            L0 = 0;
    }
    if (L0 < 0)
        die("eight volumes, none led by the Raft leader");
    for (int i = 0; i < 3; i++)
        await_open_gen(0, name, i, 1, 0);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(0);
    tsdb_sid id = rep_series(c, rep_names[0], name, 30000);
    int acked = 0;
    for (; acked < 20; acked++) {
        int64_t ts = 1000000 + 1000LL * acked;
        float val = (float)acked;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", acked, ers(rc));
    }
    tsdbc_close(c);
    await_isr(0, name, 3, 30000, "every replica in the ISR before the first cut");
    char hf[3][PATH_MAX + 64];
    for (int i = 1; i < 3; i++) {
        server_dir(i, hf[i], sizeof hf[i]);
        strcat(hf[i], "/state/holdreply");
        FILE *fp = fopen(hf[i], "w");
        if (!fp)
            die("create %s: %s", hf[i], strerror(errno));
        fclose(fp);
    }
    for (int i = 1; i < 3; i++) {
        cut_file(0, i, 1);
        cut_file(i, 0, 1);
    }
    int Nn = await_promoted(0, name, ids[0], e0, &v);
    if (Nn < 1 || Nn > 2)
        die("the record of %s after the first cut names node %u at epoch %" PRIu64, name, v.leader, v.epoch);
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(Nn, lead, 1, 30000);
    for (int i = 1; i < 3; i++) {
        cut_file(0, i, 0);
        cut_file(i, 0, 0);
        unlink(hf[i]);
    }
    char kept[96];
    snprintf(kept, sizeof kept, "keeps a copy of its answer to fence %" PRIu64 " of volume %" PRIu32, e0 + 1, num);
    if (log_count(Nn, kept) < 1)
        die("server %d led epoch %" PRIu64 " without keeping its answer to the fence (no \"%s\")", Nn, v.epoch, kept);
    await_isr(Nn, name, 3, 60000, "every server in the ISR after the first promotion");
    printf("  server %d leads epoch %" PRIu64 " after the first cut and replays its answer to fence %" PRIu64
           " through the second\n", Nn, v.epoch, e0 + 1);
    ow_cut_promote(Nn, name, id, acked, num, v.epoch, v.leader, 1);
    stop_all();
}

/* manystuck (review F4): cutstuck with more volumes than the proposer's old fixed tables of 16. 72 volumes; the server
 * other than the Raft leader that leads the most (more than 16) is cut from its replicas while they answer no fence: every move is given up and
 * the leader deposed in all of them at once. Once the members answer, each must be taken as resigned and get a leader
 * past its epoch: with 16 slots per table one was overwritten at random each round, and a deposed leader's 3 s timer
 * rarely ran out (the old tables: the last taken as resigned 10 s, re-led 13 s after the members answer). */
static void nofence_file(int at, int on);
static void scen_manystuck(void)
{
    scenario("manystuck");
    enum { NV = 72 };
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=cutlinks,nofencereply";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    static char names[NV][16];
    uint32_t nums[NV];
    uint64_t eps[NV];
    int lead[NV], count[3] = {0};
    int rc;
    for (int k = 0; k < NV; k++) {
        snprintf(names[k], sizeof names[k], "ms%d", k);
        if ((rc = vol_add(0, names[k], 3, &nums[k])) != 0)
            die("volume add %s: %s", names[k], cluster_strerror(rc));
    }
    for (int k = 0; k < NV; k++) {
        for (int i = 0; i < 3; i++)
            await_open_gen(0, names[k], i, 1, 0);
        struct meta_volume v;
        if (!vol_rec(0, names[k], &v))
            die("no record of %s", names[k]);
        lead[k] = server_of(v.leader);
        eps[k] = v.epoch;
        if (lead[k] < 0 || lead[k] > 2)
            die("the leader of %s is node %u", names[k], v.leader);
        count[lead[k]]++;
    }
    int L = count[2] > count[1] ? 2 : 1; /* not the Raft leader: cut, it would not move its volumes but fence them */
    if (count[L] <= 16)
        die("server %d leads %d of %d volumes, not more than 16", L, count[L], NV);
    for (int k = 0; k < NV; k++)
        if (lead[k] == L) {
            await_isr(L, names[k], 3, 30000, "every replica in the ISR before the cut");
            /* the epoch the cut deposes is the one before it: a leader that took more than 3 s to promote itself
             * (24 volumes opening at once under TSan) was taken as resigned and granted again at epoch 2 */
            struct meta_volume v;
            if (!vol_rec(0, names[k], &v) || server_of(v.leader) != L)
                die("%s is no longer led by server %d before the cut", names[k], L);
            eps[k] = v.epoch;
        }
    for (int i = 0; i < 3; i++)
        if (i != L)
            nofence_file(i, 1);
    uint64_t t0 = now_ms();
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 1);
            cut_file(i, L, 1);
        }
    char line[96];
    for (int k = 0; k < NV; k++) /* every move given up and the old leader deposed, in each of its volumes */
        if (lead[k] == L) {
            snprintf(line, sizeof line, "volume %" PRIu32 ": no replica to move the leadership of epoch %" PRIu64 " to;",
                     nums[k], eps[k]);
            await_log_count(0, line, 1, 60000); /* server 0 is the Raft leader throughout */
            snprintf(line, sizeof line, "volume %" PRIu32 ": deposed at epoch %" PRIu64 "", nums[k], eps[k]);
            await_log_count(L, line, 1, 60000);
        }
    uint64_t tg = now_ms();
    for (int i = 0; i < 3; i++)
        if (i != L)
            nofence_file(i, 0);
    /* the proposer's own decision, at most DEPOSED_HOLD_NS (3 s) after each move was given up: 6 s. A new leader's
     * reopen of 24 volumes at once may take longer on a loaded host: 30 s for those */
    int left = count[L];
    uint64_t taken[NV] = {0}, tlast = 0;
    for (; left > 0; usleep(100000)) {
        for (int k = 0; k < NV; k++) {
            if (lead[k] != L || taken[k])
                continue;
            snprintf(line, sizeof line, "volume %" PRIu32 ": leader %" PRIu32 " of epoch %" PRIu64 " is up but",
                     nums[k], ids[L], eps[k]);
            if (log_count(0, line) > 0) {
                taken[k] = tlast = now_ms();
                left--;
            }
        }
        if (left > 0 && now_ms() - tg > 6000) {
            for (int k = 0; k < NV; k++)
                if (lead[k] == L && !taken[k])
                    die("%d of the %d volumes server %d led are not taken as its resignation 6 s after the members "
                        "answer again (%s among them): the proposer lost their deposed time", left, count[L], L,
                        names[k]);
        }
    }
    left = count[L];
    uint64_t done[NV] = {0};
    for (; left > 0; usleep(100000)) {
        for (int k = 0; k < NV; k++) {
            struct meta_volume v;
            if (lead[k] != L || done[k] || !vol_rec(0, names[k], &v) || v.epoch <= eps[k])
                continue;
            int Nw = server_of(v.leader);
            snprintf(line, sizeof line, "volume %" PRIu32 ": leads epoch %" PRIu64 " ", nums[k], v.epoch);
            if (Nw >= 0 && Nw <= 2 && log_count(Nw, line) > 0) {
                done[k] = now_ms();
                left--;
            }
        }
        if (left > 0 && now_ms() - tg > 30000) {
            for (int k = 0; k < NV; k++)
                if (lead[k] == L && !done[k])
                    die("%d of the %d volumes server %d led have no leader past their epoch 30 s after the members "
                        "answer again (%s among them)", left, count[L], L, names[k]);
        }
    }
    uint64_t last = 0;
    for (int k = 0; k < NV; k++)
        if (done[k] > last)
            last = done[k];
    printf("  server %d led %d of %d volumes; cut, every move given up, deposed in all %" PRIu64 " ms after the cut; "
           "each taken as resigned, the last %" PRIu64 " ms, and has a new leader, the last %" PRIu64 " ms after the "
           "members answer again\n", L, count[L], NV, tg - t0, tlast - tg, last - tg);
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 0);
            cut_file(i, L, 0);
        }
    stop_all();
}

/* A leader cut from its replicas on the data links (TSDB_REPLD_TEST=cutlinks; the peer port, heartbeats and the Raft
 * group stay whole) asks to shrink the ISR to itself; the Raft leader, which hears the replicas and reads in their
 * heartbeats that they lost the leader, moves the leadership to one of them instead (design-cluster.md 6.1): no ISR of
 * one member at the old epoch, a replica leads e+1 with every acknowledged row, a write to the old leader is MOVED, and
 * the old leader rejoins once the links are back. TSDB_CLUSTER_MUTANT=cutshrinks (the shrink proposed) fails it. */
/* cut, and cuthold (review R13): the replicas report the cut leader unreachable only after 1.8 s (TSDB_CVOL_TEST
 * unreach_ms), later than the leader asks to drop them (unanswered_ms), so the Raft leader must hold that shrink
 * below 2 (cut_move, CUT_HOLD_NS) until the report comes; mutant nocuthold shrinks the ISR to the cut leader alone,
 * and no replica is promoted. */
static void cut_run(int late)
{
    for (int i = 0; i < 3; i++) {
        penv[i] = late ? "TSDB_REPLD_TEST=cutlinks TSDB_CVOL_TEST=unreach_ms=1800" : "TSDB_REPLD_TEST=cutlinks";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "rs", 3, &num)) != 0 || num != 1)
        die("volume add rs: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "rs", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "rs", &v))
        die("no record of rs");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of rs is node %u", v.leader);
    uint64_t e0 = v.epoch;
    uint32_t old = v.leader;
    tsdbc *c = client(L);
    tsdbc_set_retry(c, 0); /* the MOVED below is to be seen, not followed */
    tsdb_sid id = rep_series(c, rep_names[0], "rs", 30000);
    int acked = 0;
    for (; acked < 50; acked++) {
        int64_t ts = 1000000 + 1000LL * acked;
        float val = (float)acked;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", acked, ers(rc));
    }
    await_isr(L, "rs", 3, 30000, "every replica in the ISR before the cut");
    /* A replica still connecting while the 50 writes run may leave the ISR and come back: only shrinks after the cut
     * count (clus8, 2026-11-19: ISR version 2 of one member at commit point 54, before the cut). */
    char line[96];
    snprintf(line, sizeof line, "ISR of 1 members (epoch %" PRIu64 ",", e0);
    int shrunk0 = 0;
    for (int i = 0; i < 3; i++)
        shrunk0 += log_count(i, line);
    uint64_t t0 = now_ms();
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 1);
            cut_file(i, L, 1);
        }
    int Nw = await_promoted((L + 1) % 3, "rs", old, e0, &v);
    uint64_t tm = now_ms();
    if (v.epoch != e0 + 1 || Nw == L)
        die("the record of rs after the cut: epoch %" PRIu64 " (was %" PRIu64 "), leader %u", v.epoch, e0, v.leader);
    int moved = 0, shrunk = -shrunk0;
    for (int i = 0; i < 3; i++) {
        moved += log_count(i, "(reason 3); fences");
        shrunk += log_count(i, line);
    }
    if (shrunk || !moved)
        die("the cut leader's ISR: %d proposals of one member at epoch %" PRIu64 ", %d moves (want 0 and 1 at least)",
            shrunk, e0, moved);
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(Nw, lead, 1, 30000);
    int got = rows_in(Nw, id, 1000000, 1000000 + 1000LL * acked, 30000);
    if (got != acked)
        die("the leader at epoch %" PRIu64 " (server %d) holds %d of the %d acknowledged rows", v.epoch, Nw, got, acked);
    insert_expect_moved(c, id, 5000000, 1, (uint16_t)num, v.leader, v.epoch, "a write to the cut-off old leader");
    tsdbc_close(c);
    c = client(Nw);
    tsdbc_set_retry(c, 10000);
    int64_t ts = 9000000;
    float val = 7;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write to the leader at epoch %" PRIu64 ": %s", v.epoch, ers(rc));
    tsdbc_close(c);
    printf("  leader %d cut from its replicas: server %d leads epoch %" PRIu64 " %" PRIu64 " ms after the cut, with all "
           "%d acknowledged rows; no ISR of one\n", L, Nw, v.epoch, tm - t0, acked);
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 0);
            cut_file(i, L, 0);
        }
    await_isr(Nw, "rs", 3, 60000, "every server in the ISR once the links are back");
    stop_all();
    uint64_t wantr[REP_NAMES] = {0};
    wantr[0] = (uint64_t)acked + 1;
    rep_same(wantr, "after the cut");
}

static void scen_cut(void)
{
    scenario("cut");
    cut_run(0);
}

static void scen_cuthold(void)
{
    scenario("cuthold");
    cut_run(1);
}

/* 1 if one of server i's WAL segments of volume 1 holds a row with timestamp ts (rows are raw: ts at byte 4 of each) */
static int wal_holds_ts(int i, int64_t ts)
{
    char dir[PATH_MAX + 80];
    server_dir(i, dir, sizeof dir);
    strcat(dir, "/v1");
    DIR *d = opendir(dir);
    if (!d)
        return 0;
    int found = 0;
    struct dirent *e;
    while (!found && (e = readdir(d))) {
        if (strncmp(e->d_name, "wal_", 4) != 0)
            continue;
        char f[PATH_MAX + 400];
        snprintf(f, sizeof f, "%s/%s", dir, e->d_name);
        FILE *fp = fopen(f, "rb");
        if (!fp)
            continue;
        static uint8_t buf[8 << 20];
        size_t n = fread(buf, 1, sizeof buf, fp);
        fclose(fp);
        found = memmem(buf, n, &ts, sizeof ts) != NULL;
    }
    closedir(d);
    return found;
}

/* replflip (rd-nocheck): the data links carry no frame check by default, so a flipped bit in a record reaches the
 * replica's driver. Every 8th APPEND with records gets one byte of its first record flipped as it is received
 * (TSDB_REPLD_TEST=flipin, on every server); the driver drops it before the core (msg_refused: the record is not the
 * one its descriptor names), the leader sends it again, and every row reaches both replicas' logs with the volume up.
 * TSDB_REPLD_MUTANT=nomsgcheck hands the message to the core unchecked: the apply's check stops the volume there. */
static int repl_hook_run(const char *name, const char *env)
{
    scenario(name);
    for (int i = 0; i < 3; i++) {
        penv[i] = env;
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want3 = 3;
    await_view(0, p_voters, &want3, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "rf", 3, &num)) != 0 || num != 1)
        die("volume add rf: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "rf", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "rf", &v))
        die("no record of rf");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of rf is node %u", v.leader);
    await_isr(L, "rf", 3, 30000, "every replica in the ISR before the writes");
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "rf", 30000);
    const int n = 200;
    int64_t last = 0;
    for (int k = 0; k < n; k++) {
        int64_t ts = 2000000 + 1000LL * k;
        float val = (float)k;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s: the leader stopped taking writes under the hook (a planted message reached the "
                "core)", k, ers(rc));
        last = ts;
    }
    tsdbc_close(c);
    for (int i = 0; i < 3; i++) {
        if (i == L)
            continue;
        uint64_t t0 = now_ms();
        while (!wal_holds_ts(i, last)) {
            if (now_ms() - t0 > 20000)
                die("the last row did not reach replica %d's log in 20 s (flipped records were not dropped and sent "
                    "again)", i);
            usleep(5000);
        }
    }
    await_isr(L, "rf", 3, 10000, "every replica in the ISR after the flipped records");
    return L;
}

static void scen_replflip(void)
{
    repl_hook_run("replflip", "TSDB_REPLD_TEST=flipin");
    printf("  replflip: 200 rows, every 8th APPEND flipped at each replica, all in both replicas' logs\n");
    stop_all();
}

/* replmeta (rd-nocheck, AUDIT item 4): a flipped type field turns an APPEND into a metadata-only type, here a FENCE
 * one above the leader's epoch (TSDB_REPLD_TEST=metain, every 8th APPEND with records as it is received). Those come
 * from the metadata group through the driver, never from a peer: msg_refused drops it, the leader sends the APPEND
 * again. TSDB_REPLD_MUTANT=nometarefuse hands it to the core, which takes the fence and refuses its own leader. */
static void scen_replmeta(void)
{
    int L = repl_hook_run("replmeta", "TSDB_REPLD_TEST=metain");
    /* every type in turn (metain): FENCE 6, FENCE_REPLY 7, META 8, ISR_REQ 9, RESIGN 10 (src/repl.h); the driver says
     * the first drop of each type, so each must have its own line on both replicas (TSDB_REPLD_MUTANT=metafenceonly:
     * the four after FENCE reach the core) */
    for (int t = 6; t <= 10; t++) {
        char needle[64];
        snprintf(needle, sizeof needle, "a message of type %d from node", t);
        int seen = 0;
        for (int i = 0; i < 3; i++)
            seen += i != L && log_has(i, needle) && log_has(i, "a metadata-only type from a peer");
        if (seen != 2)
            die("no metadata-only message of type %d was refused on %d of the two replicas", t, 2 - seen);
    }
    printf("  replmeta: 200 rows, every 8th APPEND turned into each metadata-only type at each replica and dropped, "
           "all in both logs\n");
    stop_all();
}

/* replepoch (rd-nocheck review F1): no epoch a peer names may lie above the highest the member knows, or one flipped
 * bit fences the replica durably above every epoch the group will hand out (the leader stops taking writes), and a
 * descriptor's epoch goes up from prev_epoch to the message's, or the history takes a wrong epoch (the replica stops).
 * TSDB_REPLD_TEST=flipin=epoch flips, in turn, bit 40 and bit 1 of every 8th APPEND's epoch and bit 40 of its first
 * descriptor's epoch as it is received; each is dropped and sent again. Mutants noepochbound, nodescepoch. */
static void scen_replepoch(void)
{
    int L = repl_hook_run("replepoch", "TSDB_REPLD_TEST=flipin=epoch");
    const char *why[] = {"an epoch above the highest this member knows", "a descriptor's epoch out of order"};
    for (int w = 0; w < 2; w++) {
        int seen = 0;
        for (int i = 0; i < 3; i++)
            seen += i != L && log_has(i, why[w]);
        if (seen != 2)
            die("no APPEND was dropped for %s on %d of the two replicas", why[w], 2 - seen);
    }
    printf("  replepoch: 200 rows, epochs of every 8th APPEND flipped at each replica and dropped, all in both logs\n");
    stop_all();
}

/* repldesc (rd-nocheck review F5): a descriptor's position or span flipped with its record intact. The record's own
 * checksum holds, so only the comparison with the descriptor (msg_refused) drops it. TSDB_REPLD_TEST=flipin=desc;
 * mutant nodesccmp. */
static void scen_repldesc(void)
{
    int L = repl_hook_run("repldesc", "TSDB_REPLD_TEST=flipin=desc");
    int seen = 0;
    for (int i = 0; i < 3; i++)
        seen += i != L && log_has(i, "a record unlike its descriptor");
    if (seen != 2)
        die("no APPEND with a flipped descriptor was dropped on %d of the two replicas", 2 - seen);
    printf("  repldesc: 200 rows, a descriptor of every 8th APPEND flipped at each replica and dropped, all in both "
           "logs\n");
    stop_all();
}

/* drvcheck (rd-drvcheck; review F3 and F2 of rd-nocheck): every driver message carries the driver's own check
 * (server/replwire.h), at every link check level, `none` (the default, which these servers run at) included.
 * TSDB_REPLD_TEST=flipraw flips one bit of a received message in its wire bytes, before the decode:
 *   ack:  on the writer, while one replica's sync is held back (synchold, file <dir>/synchold) and noclock keeps
 *         NOW markers out of the WAL, two writes (1 row at d+1, then 128 rows) advance that replica's written end
 *         past d+1 while its durable end stays at d; flipraw=ack raises durable inside (d, written] (F3, the flip
 *         no structural bound sees). The first write must NOT be acknowledged (commit point unchanged) while the
 *         replica's sync is held, even after flipped ACKs arrive, and completes once synchold is removed.
 *   head: on the replicas, bit 0 of an APPEND's commit or bit 3 of its off, in turn (both verified logged).
 *   desc: on the replicas, bit 0 of the last descriptor's epoch or span of an APPEND of two records or more (F2:
 *         beyond descriptor 0).
 * Each must be dropped by the driver check, so nothing of it reaches msg_refused or the core, and every row still
 * reaches both replicas. Mutants checknocmp, checkshort (replwire.c) and checklate (repld.c): a flipped message
 * passes the check (or moves the commit point early in drvcheck-ack). */
static void drvcheck_ack_run(void)
{
    scenario("drvcheck-ack");
    init_isr_lag_ms = 5000;
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=flipraw=ack,synchold,noclock";
        start(i);
    }
    init_cluster(0, 600);
    init_isr_lag_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want3 = 3;
    await_view(0, p_voters, &want3, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "rf", 3, &num)) != 0 || num != 1)
        die("volume add rf: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "rf", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "rf", &v))
        die("no record of rf");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of rf is node %u", v.leader);
    await_isr(L, "rf", 3, 30000, "every replica in the ISR before the writes");
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "rf", 30000);
    int64_t ts0 = 2000000;
    float v0 = 1.0f;
    if ((rc = tsdbc_insert_series(c, id, &ts0, &v0, 1)) != 0)
        die("drvcheck-ack: initial write: %s", ers(rc));
    tsdbc_close(c);

    /* Hold back one replica's sync so its durable end stays at d while its written end advances past w1 (at d+1)
     * and w2 (128 rows: guarantees a single-bit flip d ^ (1 << b) lands in [d+1, written] for any small d). */
    int R0 = (L + 1) % 3;
    char hold[PATH_MAX + 64];
    server_dir(R0, hold, sizeof hold);
    snprintf(hold + strlen(hold), sizeof hold - strlen(hold), "/synchold");
    FILE *fp = fopen(hold, "w");
    if (!fp)
        die("drvcheck-ack: create %s", hold);
    fclose(fp);

    struct rep_writer w1 = {cports[L], id, 3000000, 1, 0, 0, 0, 0};
    struct rep_writer w2 = {cports[L], id, 4000000, 0, 0, 0, 128, 0};
    pthread_t th1, th2;
    if (pthread_create(&th1, NULL, rep_write_thread, &w1) != 0)
        die("pthread_create w1");
    uint64_t t0 = now_ms();
    while (!wal_holds_ts(R0, 3000000)) {
        if (__atomic_load_n(&w1.done, __ATOMIC_ACQUIRE))
            die("drvcheck-ack: a write was acknowledged while replica %d's sync was held (flipped ACK moved the "
                "commit point)", R0);
        if (now_ms() - t0 > 10000)
            die("drvcheck-ack: w1 did not reach replica %d's WAL in 10 s", R0);
        usleep(5000);
    }
    if (pthread_create(&th2, NULL, rep_write_thread, &w2) != 0)
        die("pthread_create w2");
    int64_t last = 4000000 + 127 * 1000LL;
    t0 = now_ms();
    while (!wal_holds_ts(R0, last)) {
        if (__atomic_load_n(&w1.done, __ATOMIC_ACQUIRE))
            die("drvcheck-ack: a write was acknowledged while replica %d's sync was held (flipped ACK moved the "
                "commit point)", R0);
        if (now_ms() - t0 > 10000)
            die("drvcheck-ack: w2 did not reach replica %d's WAL in 10 s", R0);
        usleep(5000);
    }
    t0 = now_ms();
    while (!log_has(L, "flipraw: flipped an ACK's durable from node")) {
        if (__atomic_load_n(&w1.done, __ATOMIC_ACQUIRE))
            die("drvcheck-ack: a write was acknowledged while replica %d's sync was held (flipped ACK moved the "
                "commit point)", R0);
        if (now_ms() - t0 > 5000)
            die("drvcheck-ack: leader %d never flipped an ACK's durable", L);
        usleep(10000);
    }
    /* Let several flipped ACKs arrive and verify the commit point never moves past R0's true durable end */
    for (int k = 0; k < 20; k++) {
        if (__atomic_load_n(&w1.done, __ATOMIC_ACQUIRE) || __atomic_load_n(&w2.done, __ATOMIC_ACQUIRE))
            die("drvcheck-ack: a write was acknowledged while replica %d's sync was held (flipped ACK moved the "
                "commit point)", R0);
        usleep(20000);
    }
    uint32_t isr = isr_of(L, "rf", NULL);
    if (isr != 3)
        die("drvcheck-ack: ISR shrank from 3 to %" PRIu32 " while replica %d's sync was held", isr, R0);
    if (__atomic_load_n(&w1.done, __ATOMIC_ACQUIRE) || __atomic_load_n(&w2.done, __ATOMIC_ACQUIRE))
        die("drvcheck-ack: a write was acknowledged while replica %d's sync was held (flipped ACK moved the "
            "commit point)", R0);

    if (unlink(hold) != 0)
        die("drvcheck-ack: unlink %s", hold);
    await_writer(&w1, th1, 10000, "drvcheck-ack: w1 once replica sync resumed");
    await_writer(&w2, th2, 10000, "drvcheck-ack: w2 once replica sync resumed");

    for (int i = 0; i < 3; i++) {
        if (log_has(i, "passed the driver check") || log_has(i, "a flipped ACK reached the core"))
            die("drvcheck-ack: a flipped message passed the driver check on server %d", i);
        if (i == L) {
            if (!log_has(i, "failed its driver check, dropped"))
                die("drvcheck-ack: leader %d dropped no message for its driver check", i);
        } else {
            uint64_t tw = now_ms();
            while (!wal_holds_ts(i, last)) {
                if (now_ms() - tw > 20000)
                    die("drvcheck-ack: the last row did not reach replica %d's log in 20 s", i);
                usleep(5000);
            }
        }
    }
    await_isr(L, "rf", 3, 10000, "drvcheck-ack: every replica in the ISR after sync resumed");
    stop_all();
}

static void drvcheck_head_run(void)
{
    int L = repl_hook_run("drvcheck-head", "TSDB_REPLD_TEST=flipraw=head");
    int seen_commit = 0, seen_off = 0;
    for (int i = 0; i < 3; i++) {
        if (log_has(i, "passed the driver check") || log_has(i, "a flipped ACK reached the core"))
            die("drvcheck-head: a flipped message passed the driver check on server %d", i);
        if (i == L)
            continue;
        seen_commit += log_has(i, "flipraw: flipped an APPEND's commit from node");
        seen_off += log_has(i, "flipraw: flipped an APPEND's off from node");
        if (!log_has(i, "failed its driver check, dropped"))
            die("drvcheck-head: server %d dropped no message for its driver check", i);
    }
    if (!seen_commit)
        die("drvcheck-head: no replica flipped an APPEND's commit");
    if (!seen_off)
        die("drvcheck-head: no replica flipped an APPEND's off");
    stop_all();
}

static void drvcheck_desc_run(void)
{
    scenario("drvcheck-desc");
    init_isr_lag_ms = 500;
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=flipraw=desc,cutlinks";
        start(i);
    }
    init_cluster(0, 600);
    init_isr_lag_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want3 = 3;
    await_view(0, p_voters, &want3, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "rf", 3, &num)) != 0 || num != 1)
        die("volume add rf: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "rf", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "rf", &v))
        die("no record of rf");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of rf is node %u", v.leader);
    await_isr(L, "rf", 3, 30000, "every replica in the ISR before the writes");
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "rf", 30000);
    int64_t next_ts = 2000000;
    /* Cut each replica in turn so the leader accumulates a multi-record backlog (20 WAL records) before healing;
     * the catch-up APPEND carries nrec >= 2 descriptors, so flipraw=desc deterministically flips descriptor nrec-1
     * (beyond descriptor 0). Two cuts on the first replica flip both epoch and span. */
    int reps[2], nr = 0;
    for (int i = 0; i < 3; i++)
        if (i != L)
            reps[nr++] = i;
    int order[3] = {reps[0], reps[0], reps[1]};
    for (int round = 0; round < 3; round++) {
        int r = order[round];
        cut_file(L, r, 1);
        cut_file(r, L, 1);
        await_isr(L, "rf", 2, 10000, "cut replica leaves ISR");
        for (int k = 0; k < 20; k++) {
            int64_t ts = next_ts;
            next_ts += 1000;
            float val = (float)(round * 20 + k);
            if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
                die("drvcheck-desc round %d write %d: %s", round, k, ers(rc));
        }
        cut_file(L, r, 0);
        cut_file(r, L, 0);
        await_isr(L, "rf", 3, 20000, "replica rejoins ISR after flipped multi-descriptor APPEND");
    }
    tsdbc_close(c);
    int64_t last = next_ts - 1000;
    for (int i = 0; i < 3; i++) {
        if (log_has(i, "passed the driver check") || log_has(i, "a flipped ACK reached the core"))
            die("drvcheck-desc: a flipped message passed the driver check on server %d", i);
        if (i == L)
            continue;
        uint64_t t0 = now_ms();
        while (!wal_holds_ts(i, last)) {
            if (now_ms() - t0 > 20000)
                die("drvcheck-desc: the last row did not reach replica %d's log in 20 s", i);
            usleep(5000);
        }
        if (!log_has(i, "flipraw: flipped a descriptor's"))
            die("drvcheck-desc: server %d did not flip a descriptor beyond the first", i);
        if (!log_has(i, "failed its driver check, dropped"))
            die("drvcheck-desc: server %d dropped no message for its driver check", i);
    }
    if (!log_has(reps[0], "flipraw: flipped a descriptor's epoch") ||
        !log_has(reps[0], "flipraw: flipped a descriptor's span"))
        die("drvcheck-desc: server %d did not flip both a descriptor's epoch and span", reps[0]);
    stop_all();
}

static void scen_drvcheck(void)
{
    drvcheck_ack_run();
    drvcheck_head_run();
    drvcheck_desc_run();
    printf("  drvcheck: an ACK's durable raised inside (durable, written] leaves commit point unchanged while sync is "
           "held, an APPEND's head and a descriptor beyond the first flipped on the wire, each dropped by the driver "
           "check under none, all rows in both replicas\n");
}

/* replbulk (rd-nocheck, AUDIT item 8): nothing sends a driver frame on a bulk link, so one there is a frame type a
 * flipped bit turned into a user type: the receiver closes the bulk link (the files on it begin again on the next).
 * TSDB_REPLD_TEST=bulkframe makes the leader send every 16th APPEND on the replica's bulk link as well; the rows all
 * arrive on the log links. TSDB_REPLD_MUTANT=bulkframes takes the frame as one of the log link. */
static void scen_replbulk(void)
{
    int L = repl_hook_run("replbulk", "TSDB_REPLD_TEST=bulkframe");
    int seen = 0;
    for (int i = 0; i < 3; i++)
        seen += i != L && log_has(i, "on a bulk link: the link is closed");
    if (seen != 2)
        die("no driver frame on a bulk link was refused on %d of the two replicas", 2 - seen);
    printf("  replbulk: 200 rows, every 16th APPEND also on the bulk link, refused there, all in both replicas' logs\n");
    stop_all();
}

/* deposetail (jepsen-cluster pause, seed 123, 2026-11-22): a deposed writer whose log runs past the commit point, with
 * a record of its uncommitted tail written only after its demote began, rejoins as a replica. L's replicas hold R1,
 * whose acknowledgements L never heard (cutfrom files at L), so the new leader's epoch e0 ends above L's commit floor;
 * R2 is admitted at L once it is cut both ways, and its bytes reach op_bytes only after the demote cleared the index
 * (TSDB_REPLD_TEST=latebytes: held there until the driver has no core, as a write held in the WAL writer of a stopped
 * process was). The demote's reopen must cut R2 (the new leader never had it) back to the new leader's end of e0, not
 * stop the volume ("the log does not retain a position above its applied end": the stale entry of R2 left at the front
 * of the rebuilt index of record starts), and L must catch up and join the ISR again, holding R1 (committed by the new
 * leader) and every row written there, and not R2. TSDB_REPLD_MUTANT=demotestaleidx (the index rebuilt over what the
 * old engine pushed in the window) fails it. */
static void scen_deposetail(void)
{
    scenario("deposetail");
    init_isr_lag_ms = 2000; /* L, deaf to its replicas between R1 and the full cut, asks to shrink only after this */
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=cutlinks,latebytes";
        start(i);
    }
    init_cluster(0, 600);
    init_isr_lag_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want3 = 3;
    await_view(0, p_voters, &want3, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "rs", 3, &num)) != 0 || num != 1)
        die("volume add rs: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "rs", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "rs", &v))
        die("no record of rs");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of rs is node %u", v.leader);
    uint64_t e0 = v.epoch;
    uint32_t old = v.leader;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "rs", 30000);
    int acked = 0;
    for (; acked < 50; acked++) {
        int64_t ts = 1000000 + 1000LL * acked;
        float val = (float)acked;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", acked, ers(rc));
    }
    tsdbc_close(c);
    await_isr(L, "rs", 3, 30000, "every replica in the ISR before the cut");
    /* R1: reaches both replicas, its acknowledgements never reach L */
    for (int i = 0; i < 3; i++)
        if (i != L)
            cut_file(L, i, 1);
    const int64_t r1 = 7300000123LL, r2 = 7400000321LL;
    struct rep_writer w1 = {.port = cports[L], .id = id, .t0 = r1, .count = 1};
    pthread_t t1;
    if (pthread_create(&t1, NULL, rep_write_thread, &w1) != 0)
        die("pthread_create");
    for (uint64_t t0 = now_ms(); !(wal_holds_ts((L + 1) % 3, r1) && wal_holds_ts((L + 2) % 3, r1)); usleep(2000))
        if (now_ms() - t0 > 10000)
            die("R1 did not reach both replicas' logs in 10 s");
    /* R2: L cut both ways, then written at L and held before op_bytes indexes it */
    for (int i = 0; i < 3; i++)
        if (i != L)
            cut_file(i, L, 1);
    char lb[PATH_MAX + 96];
    server_dir(L, lb, sizeof lb);
    strcat(lb, "/latebytes");
    FILE *fp = fopen(lb, "w");
    if (!fp || fclose(fp) != 0)
        die("%s: %s", lb, strerror(errno));
    struct rep_writer w2 = {.port = cports[L], .id = id, .t0 = r2, .count = 1};
    pthread_t t2;
    if (pthread_create(&t2, NULL, rep_write_thread, &w2) != 0)
        die("pthread_create");
    await_log_count(L, "are held until the writer is deposed", 1, 10000);
    int Nw = await_promoted((L + 1) % 3, "rs", old, e0, &v);
    if (Nw == L)
        die("the record of rs after the cut: leader %u, epoch %" PRIu64, v.leader, v.epoch);
    await_log_count(L, "released by the demote", 1, 30000);
    await_log_count(L, ": a replica again", 1, 30000);
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 0);
            cut_file(i, L, 0);
        }
    uint64_t th = now_ms();
    for (int k = 0; k < 2; k++) { /* both of L's writes end without an acknowledgement: deposed, or their link closed */
        struct rep_writer *w = k ? &w2 : &w1;
        for (uint64_t t0 = now_ms(); !__atomic_load_n(&w->done, __ATOMIC_ACQUIRE); usleep(10000))
            if (now_ms() - t0 > 30000)
                die("R%d on the deposed leader was not answered in 30 s", k + 1);
        pthread_join(k ? t2 : t1, NULL);
        if (w->rc == 0)
            die("R%d was acknowledged by the deposed leader", k + 1);
    }
    c = client(Nw);
    tsdbc_set_retry(c, 10000);
    int more = 5;
    for (int k = 0; k < more; k++) {
        int64_t ts = 9000000 + 1000LL * k;
        float val = (float)k;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d to the leader at epoch %" PRIu64 ": %s", k, v.epoch, ers(rc));
    }
    tsdbc_close(c);
    await_isr(Nw, "rs", 3, 30000, "the deposed writer back in the ISR once the links are back");
    if (log_count(L, "stopped:"))
        die("the deposed writer stopped its volume");
    uint64_t cuts = tr_count(L, CL_TR_CUTS); /* STATUS's cut counter counts a real one (r4-transfer review F4) */
    if (!cuts)
        die("the deposed writer cut R2 from its log, but STATUS counts %" PRIu64 " cuts", cuts);
    printf("  writer %d deposed with R2 written after its demote began: a replica again, back in the ISR %" PRIu64
           " ms after the heal\n", L, now_ms() - th);
    stop_all();
    uint64_t wantr[REP_NAMES] = {0};
    wantr[0] = (uint64_t)acked + 1 + (uint64_t)more; /* R1 committed by the new leader, R2 cut */
    rep_same(wantr, "after the deposed writer rejoined");
}

/* readdepose (int-r review F1): a read on the leader L of a replicated volume, admitted under its lease and the
 * volume led here, then held before its snapshot (TSDBD_TEST_READ_STALL), while L is deposed: cut from its replicas on
 * the data links (TSDB_REPLD_TEST=cutlinks), the group moves the volume and L, fenced, reopens its engine as a
 * replica at REPL's floor ("a replica again"). L's lease goes on (its heartbeats reach the Raft leader), so a check of
 * the lease alone lets the read through to the replica engine, which may lie below writes acknowledged before the
 * read was sent. Once the stall ends the read must be refused (UNAVAILABLE or MOVED), never answered: a raw query (the
 * single-volume path) and a QUERY_LATEST and a QUERY_MULTI (the ids path). Strict reads (D5), as in production.
 * TSDB_REPLD_MUTANT=leadnow (the check before the fix: a lapse on a volume led now) fails it. */
struct held_read {
    int server, kind;
    tsdb_sid id;
    int rc, rows;
    atomic_int done;
};
static void *held_read_thread(void *a)
{
    struct held_read *h = a;
    tsdbc *c = client(h->server);
    tsdbc_set_retry(c, 0); /* the first answer, not a followed one */
    h->rc = lease_read(c, h->id, h->kind, &h->rows);
    tsdbc_close(c);
    atomic_store(&h->done, 1);
    return NULL;
}

static void scen_readdepose(void)
{
    scenario("readdepose");
    strict_reads = 1; /* the production path: reads only on the leader (D5) */
    static char pe[3][PATH_MAX + 128];
    char stall[3][PATH_MAX + 64];
    for (int i = 0; i < 3; i++) {
        snprintf(stall[i], sizeof stall[i], "%s/rstall-n%d", base, i);
        unlink(stall[i]);
        snprintf(pe[i], sizeof pe[i], "TSDB_REPLD_TEST=cutlinks TSDBD_TEST_READ_STALL=%s", stall[i]);
        penv[i] = pe[i];
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "rd", 3, &num)) != 0 || num != 1)
        die("volume add rd: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "rd", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "rd", &v))
        die("no record of rd");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of rd is node %u", v.leader);
    uint64_t e0 = v.epoch;
    uint32_t old = v.leader;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "rd", 30000);
    int acked = 0;
    for (; acked < 50; acked++) { /* W0: acknowledged before any read below was sent */
        int64_t ts = 1000000 + 1000LL * acked;
        float val = (float)acked;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", acked, ers(rc));
    }
    tsdbc_close(c);
    await_isr(L, "rd", 3, 30000, "every replica in the ISR before the reads");
    int got = rows_in(L, id, 1000000, 1000000 + 1000LL * acked, 30000);
    if (got != acked)
        die("the leader %d answers %d of the %d acknowledged rows before the stall", L, got, acked);
    int fd = open(stall[L], O_CREAT | O_WRONLY, 0644);
    if (fd < 0)
        die("create %s: %s", stall[L], strerror(errno));
    close(fd);
    struct held_read h[3];
    pthread_t th[3];
    for (int k = 0; k < 3; k++) {
        h[k] = (struct held_read){.server = L, .kind = k, .id = id, .rc = 1};
        atomic_init(&h[k].done, 0);
        if (pthread_create(&th[k], NULL, held_read_thread, &h[k]) != 0)
            die("pthread_create");
    }
    nanosleep(&(struct timespec){0, 500000000}, NULL);
    for (int k = 0; k < 3; k++)
        if (atomic_load(&h[k].done))
            die("read kind %d on the leader %d came back (%s) before its stall ended: not admitted", k, L,
                ers(h[k].rc));
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 1);
            cut_file(i, L, 1);
        }
    int Nw = await_promoted((L + 1) % 3, "rd", old, e0, &v);
    char deposed[64];
    snprintf(deposed, sizeof deposed, "deposed at epoch %" PRIu64 ":", e0);
    await_log_count(L, deposed, 1, 30000);
    await_log_count(L, "a replica again", 1, 30000); /* the demotion's reopen: the engine is a replica's now */
    unlink(stall[L]);
    for (int k = 0; k < 3; k++)
        pthread_join(th[k], NULL);
    static const char *const kn[3] = {"a raw query", "QUERY_LATEST", "QUERY_MULTI"};
    for (int k = 0; k < 3; k++) {
        if (h[k].rc == 0)
            die("%s admitted on the leader %d under its lease and held while it was deposed answered (%d rows%s) from "
                "the replica engine of its demotion", kn[k], L, h[k].rows,
                h[k].kind == 0 && h[k].rows < acked ? ", fewer than the acknowledged" : "");
        if (h[k].rc != TSDB_ERR_UNAVAILABLE && h[k].rc != TSDB_ERR_MOVED)
            die("%s held across the deposal of its leader got %s, not UNAVAILABLE or MOVED", kn[k], ers(h[k].rc));
    }
    printf("  reads admitted on leader %d and held across its deposal (server %d leads epoch %" PRIu64 "): refused "
           "(%s, %s, %s)\n", L, Nw, v.epoch, ers(h[0].rc), ers(h[1].rc), ers(h[2].rc));
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 0);
            cut_file(i, L, 0);
        }
    stop_all();
}

static void nofence_file(int at, int on)
{
    char f[PATH_MAX + 64];
    server_dir(at, f, sizeof f);
    snprintf(f + strlen(f), sizeof f - strlen(f), "/nofencereply");
    if (on) {
        FILE *fp = fopen(f, "w");
        if (!fp)
            die("create %s", f);
        fclose(fp);
    } else if (unlink(f) != 0 && errno != ENOENT) {
        die("unlink %s", f);
    }
}

/* cutstuck (jepsen-cluster meta,classes kill, 2026-11-19: kvr had no writer for the second half of the run): a move of
 * the leadership away from a cut leader (cut) fences every ISR member, the old leader too, which answers and is
 * deposed; when no candidate answers (TSDB_REPLD_TEST=nofencereply on the replicas: they save the fence and say
 * nothing, as a member killed before its answer) the Raft leader gives the move up, and the record still names the old
 * leader at the old epoch while its core waits for a record past its fence. The group must take that as the old
 * leader's resignation and promote again once the members answer: a leader past the old epoch, which accepts a write
 * and holds every acknowledged row. TSDB_CLUSTER_MUTANT=deposedstuck (never taken as resigned) fails it. */
static void scen_cutstuck(void)
{
    scenario("cutstuck");
    for (int i = 0; i < 3; i++) {
        penv[i] = "TSDB_REPLD_TEST=cutlinks,nofencereply";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "rs", 3, &num)) != 0 || num != 1)
        die("volume add rs: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "rs", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "rs", &v))
        die("no record of rs");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of rs is node %u", v.leader);
    uint64_t e0 = v.epoch;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "rs", 30000);
    int acked = 0;
    for (; acked < 50; acked++) {
        int64_t ts = 1000000 + 1000LL * acked;
        float val = (float)acked;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", acked, ers(rc));
    }
    tsdbc_close(c);
    await_isr(L, "rs", 3, 30000, "every replica in the ISR before the cut");
    for (int i = 0; i < 3; i++)
        if (i != L)
            nofence_file(i, 1);
    uint64_t t0 = now_ms();
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 1);
            cut_file(i, L, 1);
        }
    char gaveup[96], deposed[64];
    snprintf(gaveup, sizeof gaveup, "no replica to move the leadership of epoch %" PRIu64 " to;", e0);
    snprintf(deposed, sizeof deposed, "deposed at epoch %" PRIu64 ":", e0);
    for (int n = 0; n < 1;) {
        n = 0;
        for (int i = 0; i < 3; i++)
            n += log_count(i, gaveup);
        if (now_ms() - t0 > 30000)
            die("no Raft leader gave the move of the cut leader up in 30 s");
        usleep(50000);
    }
    await_log_count(L, deposed, 1, 10000);
    uint64_t tg = now_ms();
    for (int i = 0; i < 3; i++)
        if (i != L)
            nofence_file(i, 0);
    /* a leader past e0 that leads (the old one may be granted e + 1 first and moved from again while it promotes) */
    int Nw = -1;
    for (char lead[64];; usleep(50000)) {
        if (vol_rec(L, "rs", &v) && v.epoch > e0 && (Nw = server_of(v.leader)) >= 0 && Nw <= 2) {
            snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
            if (log_count(Nw, lead) > 0)
                break;
        }
        if (now_ms() - tg > 30000)
            die("rs has no leader past epoch %" PRIu64 " 30 s after the move was given up (record: leader %u at epoch "
                "%" PRIu64 "): the deposed leader is still named", e0, v.leader, v.epoch);
    }
    uint64_t tl = now_ms();
    c = client(Nw);
    tsdbc_set_retry(c, 10000);
    int64_t ts = 9000000;
    float val = 7;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write to the leader at epoch %" PRIu64 " (server %d): %s", v.epoch, Nw, ers(rc));
    tsdbc_close(c);
    int got = rows_in(Nw, id, 1000000, 1000000 + 1000LL * acked, 30000);
    if (got != acked)
        die("the leader at epoch %" PRIu64 " (server %d) holds %d of the %d acknowledged rows", v.epoch, Nw, got, acked);
    printf("  the move away from cut leader %d given up %llu ms after the cut (the old leader deposed); server %d leads "
           "epoch %" PRIu64 " %llu ms after the members answer again, with all %d acknowledged rows\n", L,
           (unsigned long long)(tg - t0), Nw, v.epoch, (unsigned long long)(tl - tg), acked);
    for (int i = 0; i < 3; i++)
        if (i != L) {
            cut_file(L, i, 0);
            cut_file(i, L, 0);
        }
    await_isr(Nw, "rs", 3, 60000, "every server in the ISR once the links are back");
    stop_all();
    uint64_t wantr[REP_NAMES] = {0};
    wantr[0] = (uint64_t)acked + 1;
    rep_same(wantr, "after the cut and the given-up move");
}

/* cluster_copy_caught_up of server i as its copy probe (TSDB_CLUSTER_TEST copy_probe=1, a thread of its own) wrote it
 * last: 1, 0, or -1 while there is no probe file yet */
static int probe_caught(int i)
{
    char out[8192];
    probe_read(i, "copyprobe", out, sizeof out);
    return !strncmp(out, "caught 1", 8) ? 1 : !strncmp(out, "caught 0", 8) ? 0 : -1;
}

static void await_caught(int i, int want, uint64_t t0, uint64_t ms, const char *what)
{
    while (probe_caught(i) != want) {
        if (now_ms() - t0 > ms)
            die("server %d: cluster_copy_caught_up is not %d %" PRIu64 " ms on (%s)", i, want, ms, what);
        usleep(20000);
    }
}

static int meta_leader_of(int n)
{
    for (uint64_t t0 = now_ms();; usleep(50000)) {
        for (int i = 0; i < n; i++) {
            if (stopped[i])
                continue;
            struct view v;
            view(i, &v);
            int lead = v.st.mode == CLUSTER_MODE_CORE && v.st.role == RAFT_LEADER && v.m.initialised;
            view_free(&v);
            if (lead)
                return i;
        }
        if (now_ms() - t0 > WAIT_MS)
            die("no leader of the metadata group");
    }
}

static void stall_file(int i, int on)
{
    char path[PATH_MAX + 96];
    server_dir(i, path, sizeof path);
    strcat(path, "/state/stallloop");
    if (!on) {
        unlink(path);
        return;
    }
    FILE *f = fopen(path, "w");
    if (!f)
        die("%s: %s", path, strerror(errno));
    fclose(f);
}

/* R8 D9 (r8c-meta3 review M1): cluster_copy_caught_up as another thread of tsdbd reads it, through each server's copy
 * probe. Three servers, lease_ms 1000 with 20% drift (a beat's lease ends 800 ms after it was sent). Every server says 1.
 * A follower F whose cluster loop stalls (stall_loop_file) says 0 within the lease and a margin (1700 ms; a flag the
 * loop refreshed said 1 for the whole stall: mutant copynodeadline), and 1 again once it runs; so does the metadata
 * leader (its own read lease). F with its published copy held (hold_copy_file) says 0 once the leader commits past
 * that copy (a volume add), however far the cluster thread itself has applied (mutant copynofloor), and 1 once the
 * copy is let go. The leader paused: F says 0 within the lease and the margin (a fixed 2 s window did not follow
 * lease_ms), and 1 again under the leader elected meanwhile. */
static void scen_copycaught(void)
{
    scenario("copycaught");
    for (int i = 0; i < 3; i++)
        envs[i] = "copy_probe=1,stall_loop_file=1,hold_copy_file=1";
    lease_cluster(3, 1000, 200000, 3000);
    const uint64_t within = 1000 + 700; /* the lease, the probe's and the loop's rounds */
    for (int i = 0; i < 3; i++)
        await_caught(i, 1, now_ms(), WAIT_MS, "three voters");
    int L = meta_leader_of(3), F = (L + 1) % 3;
    uint64_t t0 = now_ms();
    stall_file(F, 1);
    await_caught(F, 0, t0, within, "its cluster loop stalled");
    printf("  a follower's stalled cluster loop: 0 after %" PRIu64 " ms\n", now_ms() - t0);
    stall_file(F, 0);
    await_caught(F, 1, now_ms(), WAIT_MS, "its cluster loop running again");
    t0 = now_ms();
    stall_file(L, 1);
    await_caught(L, 0, t0, within, "the leader's cluster loop stalled");
    printf("  the metadata leader's stalled cluster loop: 0 after %" PRIu64 " ms\n", now_ms() - t0);
    stall_file(L, 0);
    for (int i = 0; i < 3; i++)
        await_caught(i, 1, now_ms(), WAIT_MS, "the leader's loop running again");

    L = meta_leader_of(3);
    F = (L + 1) % 3;
    char hold[PATH_MAX + 96];
    server_dir(F, hold, sizeof hold);
    strcat(hold, "/state/holdcopy");
    FILE *h = fopen(hold, "w");
    if (!h)
        die("%s: %s", hold, strerror(errno));
    fclose(h);
    usleep(300000); /* a round of F's cluster thread */
    uint32_t num;
    int rc;
    if ((rc = vol_add(L, "cc", 3, &num)) != 0)
        die("volume add cc: %s", cluster_strerror(rc));
    await_caught(F, 0, now_ms(), WAIT_MS, "its published copy held behind a volume add");
    struct meta_volume cc;
    for (uint64_t t1 = now_ms(); !vol_rec(F, "cc", &cc); usleep(50000)) /* STATUS: the cluster thread's state */
        if (now_ms() - t1 > WAIT_MS)
            die("server %d's state does not hold the volume cc while its published copy is held", F);
    if (probe_caught(F) != 0)
        die("server %d: cluster_copy_caught_up is 1 with its published copy held behind cc", F);
    printf("  a published copy held behind a volume add the cluster thread applied: 0\n");
    unlink(hold);
    await_caught(F, 1, now_ms(), WAIT_MS, "its published copy let go");

    L = meta_leader_of(3);
    F = (L + 1) % 3;
    t0 = now_ms();
    pause_server(L, 1);
    await_caught(F, 0, t0, within, "the metadata leader paused");
    printf("  the metadata leader paused: a follower's 0 after %" PRIu64 " ms\n", now_ms() - t0);
    await_caught(F, 1, now_ms(), WAIT_MS, "a leader elected while the old one is paused");
    pause_server(L, 0);
    await_caught(L, 1, now_ms(), WAIT_MS, "the old leader back");
    printf("  1 again under the new leader, and on the old one once back\n");
}

/* R8 (r8c-meta3; design-cluster-data.md E1, E3, E9, E14, E24): an erasure-coded volume added through tsdbd. Six
 * servers (the harness's N), five of them restarted with a chunk store: an ec=4+2 add is refused with the line that
 * says how many members qualify (the leader picks the stripe group from the heartbeats, apply never does). The sixth
 * gets a store: the add goes through with a group of six distinct members, m + 1 = 3 replicas and min_isr m = 2, and
 * the group is the same on every member and after the metadata leader restarts. A replica count other than m + 1 is
 * refused. Then e42 loses its ISR (one replica cut off and dropped, the other two killed): force-leader sets
 * gc_suspended, `tsdb cluster status` shows it, and `tsdb cluster volume gc resume` (by name) clears it; on a
 * replicas volume it is refused. */
static int vol_add_ec(int i, const char *name, uint32_t replicas, uint8_t k, uint8_t m, uint32_t *number, char *text,
                      size_t tn)
{
    uint8_t req[2 + META_NAME_MAX + 6], *reply;
    size_t len, rl = cluster_volume_add_ec_encode(name, replicas, k, m, req);
    int rc = admin(i, CLUSTER_OP_VOLUME_ADD_EC, req, rl, 1, &reply, &len);
    *number = 0;
    for (size_t j = 0; rc == 0 && j < 4 && j < len; j++)
        *number |= (uint32_t)reply[j] << (8 * j);
    snprintf(text, tn, "%.*s", rc ? (int)len : 0, reply ? (const char *)reply : "");
    free(reply);
    return rc;
}

/* server i restarted with the extra arguments xa (its chunk store) or none, and back UP */
static void restart_xargs(int i, const char *xa)
{
    int peer = i == 0 ? 1 : 0;
    struct view v;
    view(peer, &v);
    const struct meta_member *mb = meta_member(&v.m, ids[i]);
    struct state_want up = {ids[i], META_UP, mb ? mb->incarnation + 1 : 1};
    view_free(&v);
    stop(i, SIGTERM);
    xargs[i] = xa;
    start(i);
    await_view(peer, p_member_state, &up, xa ? "the server back with a chunk store" : "the server back without one");
}

static void restart_with_store(int i, const uint8_t uuid[16], char *xa, size_t xn)
{
    char sd[PATH_MAX];
    snprintf(sd, sizeof sd, "%s/ecs%d", base, i);
    chunk_store_make(sd, uuid, ids[i]);
    snprintf(xa, xn, "--chunk-dir %s", sd);
    restart_xargs(i, xa);
}

/* all six members UP with their volumes open: each one the leader may place on (placeable() in cluster.c) */
static int p_n_placeable(const struct view *v, void *a)
{
    unsigned want = *(const unsigned *)a, n = 0;
    for (uint32_t k = 0; k < v->m.nmembers; k++)
        n += v->m.members[k].state == META_UP && (v->m.members[k].flags & META_MF_VOLUMES_OK);
    return n == want;
}

static int p_six_placeable(const struct view *v, void *a)
{
    (void)a;
    unsigned six = 6;
    return p_n_placeable(v, &six);
}

/* an ec=4+2 add of `name` refused while five members report a chunk store: FEW naming five, with all six members
 * placeable first, so that the five come from the stores and not from a member the leader has not heard yet */
static void await_ec_five(const char *name)
{
    await_view(5, p_six_placeable, NULL, "six members UP with their volumes open");
    uint32_t num = 0;
    char text[256];
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        int rc = vol_add_ec(5, name, 0, 4, 2, &num, text, sizeof text);
        if (rc == 0)
            die("ec=4+2 %s added with five members holding a chunk store (number %" PRIu32 ")", name, num);
        if (rc == CLUSTER_ERR_FEW && strstr(text, "5 members qualify for an ec=4+2 stripe group of 6"))
            break;
        /* NOTLEADER: the group is electing (seen under TSan after the restarts with stores), asked again */
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ec=4+2 %s with five stores: %s (%s), not FEW naming five", name, cluster_strerror(rc), text);
    }
    printf("  ec=4+2 %s with five members holding a store: refused (%s)\n", name, text);
}

/* every server's copy holds the same stripe group of `name` as `want` (positions, version, gc flag) */
static void await_same_stripe(const char *name, const struct meta_volume *want, const char *what)
{
    for (uint64_t t0 = now_ms();; usleep(50000)) {
        int same = 1;
        /* the published copy too (what the chunk server and the healer read), through each server's copy probe */
        char line[600], probe[8192];
        int n = snprintf(line, sizeof line, "vol %s k %u m %u stripe_version %" PRIu64 " gc %u stripe", name,
                         want->ec_k, want->ec_m, want->stripe_version, want->gc_suspended);
        for (uint32_t k = 0; k < want->nstripe; k++)
            n += snprintf(line + n, sizeof line - (size_t)n, " %" PRIu32, want->stripe[k]);
        snprintf(line + n, sizeof line - (size_t)n, "\n");
        for (int i = 0; i < 6 && same; i++) {
            if (stopped[i] || !pids[i]) /* paused, or killed (force-leader's two) */
                continue;
            struct meta_volume v;
            same = vol_rec(i, name, &v) && v.redundancy == want->redundancy && v.ec_k == want->ec_k &&
                   v.ec_m == want->ec_m && v.nstripe == want->nstripe &&
                   !memcmp(v.stripe, want->stripe, sizeof v.stripe[0] * want->nstripe) &&
                   v.stripe_version == want->stripe_version && v.gc_suspended == want->gc_suspended;
            probe_read(i, "copyprobe", probe, sizeof probe);
            same = same && strstr(probe, line);
        }
        if (same)
            return;
        if (now_ms() - t0 > 30000)
            die("the stripe group of %s differs between the servers' copies 30 s on (%s)", name, what);
    }
}

/* margins (R8-2, r8o-margins; design-cluster-data.md E15, E24, server/margins.h): STATUS of an ec=4+2 volume with 3
 * replicas on six servers says young margin 2 (ISR 3 - 1), settled margin 2 (6 positions - k) and tier ok; a killed
 * stripe member that holds no replica takes the settled margin to 1 and leaves the young one; a killed replica takes
 * both down by one once it left the ISR; each back, both are 2 again. Then the test hook TSDBD_TEST_COLD: three stripe
 * members declared destroyed (alive) make the tier lost, and a read of the volume on its leader (refused as a settled
 * read short of k positions) answers UNAVAILABLE with TSDB_WHY_LOST at once, never retried by the C client; two
 * destroyed and one away is unavailable, reason UNREACHABLE, which the client retries until its budget; LOST carries
 * retry_after TSDB_RETRY_MAX_MS (a client that does not know LOST must not retry it every millisecond); a young
 * part's CORRUPT leaves the tier ok, a settled read that answers CORRUPT makes the leader's tier corrupt (only there,
 * and until a restart). Every STATUS check is repeated on the metrics port (tsdb_volume_young_margin,
 * _settled_margin, _settled_state) of the servers that serve one. Mutants: tests/margin_mutants.sh. */
static int margin_mports[6]; /* the metrics port of server i in scen_margins (0: none) */
static int status_key(int i, const char *key, char *val, size_t vn)
{
    tsdbc *c = client(i);
    char *text = NULL, k[96];
    int rc = tsdbc_status(c, &text);
    tsdbc_close(c);
    if (rc != 0)
        return 0;
    snprintf(k, sizeof k, "\n%s=", key);
    const char *at = strstr(text, k);
    int found = at != NULL;
    if (found) {
        at += strlen(k);
        size_t n = strcspn(at, "\n");
        snprintf(val, vn, "%.*s", (int)n, at);
    }
    free(text);
    return found;
}

static void await_margins(int i, uint32_t num, int young, int settled, const char *tier, int ms, const char *what)
{
    char ky[64], ks[64], kt[64], y[32] = "-", st[32] = "-", t[32] = "-", wy[16], ws[16];
    snprintf(ky, sizeof ky, "vol.%u.young_margin", (unsigned)num);
    snprintf(ks, sizeof ks, "vol.%u.settled_margin", (unsigned)num);
    snprintf(kt, sizeof kt, "vol.%u.tier", (unsigned)num);
    snprintf(wy, sizeof wy, "%d", young);
    snprintf(ws, sizeof ws, "%d", settled);
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        int ok = status_key(i, ky, y, sizeof y) & status_key(i, ks, st, sizeof st) & status_key(i, kt, t, sizeof t);
        if (ok && strcmp(y, wy) == 0 && strcmp(st, ws) == 0 && strcmp(t, tier) == 0)
            break;
        if (now_ms() - t0 > (uint64_t)ms)
            die("%s: STATUS of server %d says young_margin %s settled_margin %s tier %s, want %d %d %s (%d ms)", what,
                i, y, st, t, young, settled, tier, ms);
    }
    printf("  %s: young margin %d, settled margin %d, tier %s\n", what, young, settled, tier);
    if (margin_mports[i] <= 0)
        return;
    /* the metrics port says the same (from the same copy, which only moves forward) */
    static char buf[1 << 20];
    metrics_get(margin_mports[i], buf, sizeof buf);
    static const char *const states[] = {"ok", "unavailable", "corrupt", "lost"};
    char key[128];
    const char *l;
    if (!strstr(buf, "\ntsdb_peer_links{kind=\"log\",check=\"none\"} ") ||
        !strstr(buf, "\ntsdb_peer_links{kind=\"chunkb\",check=\"full\"} 0\n"))
        die("%s: server %d's metrics have no tsdb_peer_links of every kind and check", what, i);
    snprintf(key, sizeof key, "\ntsdb_volume_young_margin{volume=\"%u\"} ", (unsigned)num);
    if (!(l = strstr(buf, key)) || atoi(l + strlen(key)) != young)
        die("%s: server %d's metrics say tsdb_volume_young_margin %s, not %d", what, i, l ? l + strlen(key) : "missing",
            young);
    snprintf(key, sizeof key, "\ntsdb_volume_settled_margin{volume=\"%u\"} ", (unsigned)num);
    if (!(l = strstr(buf, key)) || atoi(l + strlen(key)) != settled)
        die("%s: server %d's metrics say tsdb_volume_settled_margin %s, not %d", what, i,
            l ? l + strlen(key) : "missing", settled);
    for (size_t k = 0; k < sizeof states / sizeof *states; k++) {
        snprintf(key, sizeof key, "\ntsdb_volume_settled_state{volume=\"%u\",state=\"%s\"} ", (unsigned)num,
                 states[k]);
        int want = strcmp(states[k], tier) == 0;
        if (!(l = strstr(buf, key)) || l[strlen(key)] != '0' + want)
            die("%s: server %d's metrics say tsdb_volume_settled_state %s %s, not %d", what, i, states[k],
                l ? l + strlen(key) : "missing", want);
    }
}

static void cold_file(const char *path, const char *text)
{
    char tmp[PATH_MAX + 8];
    snprintf(tmp, sizeof tmp, "%s.tmp", path);
    FILE *f = fopen(tmp, "w");
    if (!f || fputs(text, f) < 0 || fclose(f) != 0 || rename(tmp, path) != 0)
        die("write %s: %s", path, strerror(errno));
}

static int no_rows(void *ctx, const int64_t *ts, const float *v, size_t n)
{
    (void)ctx, (void)ts, (void)v, (void)n;
    return 0;
}

static void scen_margins(void)
{
    scenario("margins");
    static char cold[PATH_MAX + 96], pe[PATH_MAX + 128];
    snprintf(cold, sizeof cold, "%s/cold-hook", base);
    snprintf(pe, sizeof pe, "TSDBD_TEST_COLD=%s", cold);
    for (int i = 0; i < 6; i++) {
        penv[i] = pe;
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 6; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters of six members");
    struct view vw;
    view(0, &vw);
    uint8_t uuid[16];
    memcpy(uuid, vw.m.uuid, 16);
    view_free(&vw);
    static char xa[6][PATH_MAX + 64];
    for (int i = 0; i < 6; i++) { /* restart_with_store's, with a metrics port */
        char sd[PATH_MAX];
        snprintf(sd, sizeof sd, "%s/ecs%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i], "--chunk-dir %s --metrics-port auto", sd);
        restart_xargs(i, xa[i]);
        margin_mports[i] = th_mport;
    }
    await_view(5, p_six_placeable, NULL, "six members UP with their volumes open");
    uint32_t num = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "m42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ec=4+2 m42 with six stores: %s (%s)", cluster_strerror(rc), text);
    struct meta_volume e;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "m42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("no record of m42 with a leader in server 0's copy 30 s after the add");
    if (e.redundancy != META_RED_EC || e.nstripe != 6 || e.nrep != 3)
        die("m42: redundancy %u nstripe %" PRIu32 " replicas %" PRIu32, e.redundancy, e.nstripe, e.nrep);
    int L = server_of(e.leader), R = -1, S = -1;
    for (uint32_t k = 0; k < e.nrep; k++)
        if (e.rep[k].node != e.leader)
            R = server_of(e.rep[k].node); /* a replica that does not lead */
    for (int i = 0; i < 6 && S < 0; i++) {
        bool rep = false;
        for (uint32_t k = 0; k < e.nrep; k++)
            rep |= server_of(e.rep[k].node) == i;
        if (!rep)
            S = i; /* a stripe member without a replica (every member is in the group of six) */
    }
    if (L < 0 || R < 0 || S < 0)
        die("m42: leader server %d, replica %d, stripe-only member %d", L, R, S);
    await_isr(L, "m42", 3, 30000, "m42 with every replica");
    await_margins(L, num, 2, 2, "ok", 30000, "every member up");

    /* a stripe member down: the settled tier is one loss from unavailable, the young tier keeps its ISR */
    stop(S, SIGKILL);
    await_margins(L, num, 2, 1, "ok", 30000, "a stripe member killed");
    start(S);
    margin_mports[S] = th_mport;
    await_margins(L, num, 2, 2, "ok", 30000, "the stripe member back");

    /* a replica down: it leaves the ISR once the leader has something for it (writes), and both margins drop */
    tsdbc *c = client(L);
    tsdbc_set_retry(c, 30000);
    tsdb_sid id = rep_series(c, rep_names[0], "m42", 30000);
    stop(R, SIGKILL);
    struct rep_writer w = {cports[L], id, 5000, 3, 0, 0, 0, 0};
    pthread_t th;
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0)
        die("pthread_create");
    await_writer(&w, th, 60000, "writes with a replica killed");
    await_isr(L, "m42", 2, 30000, "a replica killed");
    await_margins(L, num, 1, 1, "ok", 30000, "a replica killed");
    start(R);
    margin_mports[R] = th_mport;
    w = (struct rep_writer){cports[L], id, 9000, 3, 0, 0, 0, 0};
    if (pthread_create(&th, NULL, rep_write_thread, &w) != 0)
        die("pthread_create");
    await_writer(&w, th, 60000, "writes with the replica back");
    await_isr(L, "m42", 3, 60000, "the replica back");
    await_margins(L, num, 2, 2, "ok", 30000, "the replica back");

    /* lost: more than m positions on members declared destroyed (alive: a destroyed position never counts) */
    char line[160];
    int O = -1; /* another member that stays up */
    for (int i = 0; i < 6 && O < 0; i++)
        if (i != L && i != S)
            O = i;
    snprintf(line, sizeof line, "destroyed %u %u %u\nreads\n", (unsigned)e.stripe[0], (unsigned)e.stripe[1],
             (unsigned)e.stripe[2]);
    cold_file(cold, line);
    await_margins(L, num, 2, -1, "lost", 10000, "three positions declared destroyed");
    await_margins(O, num, 2, -1, "lost", 10000, "three positions declared destroyed, on another member");
    tsdbc_set_retry(c, 30000);
    uint64_t t0 = now_ms();
    rc = tsdbc_query_raw(c, id, 0, INT64_MAX, no_rows, NULL);
    uint64_t took = now_ms() - t0;
    tsdb_unavail u[4];
    unsigned nu = 0;
    if (rc != TSDB_ERR_UNAVAILABLE || tsdbc_unavailable(c, u, 4, &nu) != 0 || nu != 1 || u[0].reason != TSDB_WHY_LOST ||
        u[0].vol != num)
        die("a settled read of a lost volume: %s, %u entries, reason %u volume %u (want UNAVAILABLE, LOST, %u)",
            ers(rc), nu, nu ? u[0].reason : 0, nu ? u[0].vol : 0, (unsigned)num);
    if (took > 1000)
        die("a settled read of a lost volume took %llu ms: the client retried LOST", (unsigned long long)took);
    if (u[0].retry_after_ms != TSDB_RETRY_MAX_MS) /* a client that does not know LOST waits this long, or gives up */
        die("LOST says retry_after %" PRIu32 " ms, not %u: a client that does not know LOST would retry it that often",
            u[0].retry_after_ms, (unsigned)TSDB_RETRY_MAX_MS);
    printf("  a settled read of the lost volume: UNAVAILABLE (LOST) in %llu ms, not retried\n",
           (unsigned long long)took);

    /* two destroyed and one away (the stripe-only member: the ISR stays whole): unavailable, retried (reason
     * UNREACHABLE) until the budget runs out */
    uint32_t dn[2], nd = 0;
    for (uint32_t p = 0; p < e.nstripe && nd < 2; p++)
        if (server_of(e.stripe[p]) != S)
            dn[nd++] = e.stripe[p];
    snprintf(line, sizeof line, "destroyed %u %u\nreads\n", (unsigned)dn[0], (unsigned)dn[1]);
    cold_file(cold, line);
    stop(S, SIGKILL);
    await_margins(L, num, 2, -1, "unavailable", 30000, "two positions destroyed and one away");
    tsdbc_set_retry(c, 1500);
    t0 = now_ms();
    rc = tsdbc_query_raw(c, id, 0, INT64_MAX, no_rows, NULL);
    took = now_ms() - t0;
    if (rc != TSDB_ERR_UNAVAILABLE || tsdbc_unavailable(c, u, 4, &nu) != 0 || nu != 1 ||
        u[0].reason != TSDB_WHY_UNREACHABLE)
        die("a settled read short of k positions: %s, %u entries, reason %u (want UNAVAILABLE, UNREACHABLE)", ers(rc),
            nu, nu ? u[0].reason : 0);
    /* retried at least once: the first refusal's delay is 1000 ms +-20%, and the second's would pass the 1500 ms
     * budget, so the client gives up right after its one retry, at 800 ms or later (never a tuned bound) */
    if (took < 800)
        die("a settled read short of k positions gave up after %llu ms: UNREACHABLE is retried within the budget",
            (unsigned long long)took);
    start(S);
    margin_mports[S] = th_mport;
    cold_file(cold, "reads\ncorrupt-young\n");
    await_margins(L, num, 2, 2, "ok", 60000, "the member back, nothing destroyed");

    /* a young part's damage: answered CORRUPT, the settled tier stays ok (frame_put marks it before the reply) */
    tsdbc_set_retry(c, 0);
    if ((rc = tsdbc_query_raw(c, id, 0, INT64_MAX, no_rows, NULL)) != TSDB_ERR_CORRUPT)
        die("a read with the corrupt-young hook: %s, not CORRUPT", ers(rc));
    await_margins(L, num, 2, 2, "ok", 2000, "a young part's read answered CORRUPT (on the leader)");

    /* corrupt: a settled read that answers CORRUPT marks this server's view of the tier, until a restart */
    cold_file(cold, "reads\ncorrupt\n");
    if ((rc = tsdbc_query_raw(c, id, 0, INT64_MAX, no_rows, NULL)) != TSDB_ERR_CORRUPT)
        die("a settled read with the corrupt hook: %s, not CORRUPT", ers(rc));
    cold_file(cold, "\n");
    await_margins(L, num, 2, 2, "corrupt", 10000, "a read answered CORRUPT (on the leader)");
    await_margins(O, num, 2, 2, "ok", 10000, "a read answered CORRUPT on the leader (another member)");
    tsdbc_close(c);
}

/* ecbasic (r8f, server/chunkpeer.h; design-cluster-data.md E9-E11, E14, E15): an ec=4+2 volume settles through the
 * peer cold ops (each position on its stripe member over CHUNKB, the leader's own in process) and its answers equal a
 * replicas twin's; with one stripe member killed reads decode around it, with three they are UNAVAILABLE, never
 * CORRUPT, and whole again once the members are back. N is 6, so the stripe group is every server. Each phase reads
 * series of its own: the granule cache would answer a series read before from memory. */
#define ECB_SERIES 8
/* The first day's rows per series and batch, with random values (at least 26 bits a row): the day settles as two
 * objects of some 1.1 MB each (one per level-1 part), geometry k' = 4 with 64 KiB cells (E7: cell = L / 8k, at least
 * 64 KiB), about 17 data cells an object, and a series covers some 2 cells of each: two or three data positions, not
 * every one. With three of the six members away at least one of them holds a data position, whose cells cannot be
 * rebuilt from the three positions left, but a series whose cells all lie elsewhere reads whole without a decode
 * (the r8f review's F12: a check of one series passed or failed with the replica placement). So the three-member case
 * reads every series not read before and wants each answer whole or UNAVAILABLE, and UNAVAILABLE at least once. With
 * 3000 rows of smooth values (r8f-ecbasic4) the object was one cell, k' = 1. */
#define ECB_ROWS 43000 /* 2 s apart, two batches interleaved: 86000 rows on one day */
/* The later days (the EPOCH case) are written the same way: with 3000 smooth rows (r8f-ecbasic5) their object was
 * k' = 1, three positions, none of them on the member whose store was unsure, and the settle went through. */
struct ecb_sum {
    uint64_t n, h;
};
static int ecb_rows(void *ctx, const int64_t *ts, const float *v, size_t n)
{
    struct ecb_sum *s = ctx;
    for (size_t i = 0; i < n; i++) {
        uint32_t b;
        memcpy(&b, &v[i], 4);
        s->h = s->h * 1000003u ^ (uint64_t)ts[i] * 31u ^ b;
    }
    s->n += n;
    return 0;
}

static int ecb_read(tsdbc *c, tsdb_sid id, struct ecb_sum *s)
{
    memset(s, 0, sizeof *s);
    return tsdbc_query_raw(c, id, 0, INT64_MAX / 2, ecb_rows, s);
}

/* the chunk files of volume num in stores 0..n_stores-1 (ecs<i>/s<num>/o*.chunk) */
static int ecb_chunks_n(uint32_t num, int n_stores)
{
    int n = 0;
    for (int i = 0; i < n_stores; i++) {
        char p[PATH_MAX + 80];
        snprintf(p, sizeof p, "%s/ecs%d/s%" PRIu32, base, i, num);
        DIR *dd = opendir(p);
        if (!dd)
            continue;
        for (struct dirent *e; (e = readdir(dd));) {
            size_t l = strlen(e->d_name);
            n += e->d_name[0] == 'o' && l > 6 && !strcmp(e->d_name + l - 6, ".chunk");
        }
        closedir(dd);
    }
    return n;
}

static int ecb_chunks(uint32_t num) { return ecb_chunks_n(num, 6); }

/* ECB_SERIES series of e42 written on the day from day_ms in two batches a flush apart (two parts, which the idle
 * merge makes one of level 1: what a cluster settle takes, D18) */
/* batch b of series s on the day from day_ms: ECB_ROWS rows 2 s apart, the batches interleaved */
static void ecb_rows_of(int s, int b, int64_t day_ms, int64_t *ts, float *val)
{
    for (int r = 0; r < ECB_ROWS; r++) {
        ts[r] = day_ms + (int64_t)(2 * r + b) * 1000;
        uint64_t z = ((uint64_t)s << 40 | (uint64_t)b << 32 | (uint64_t)r) + (uint64_t)day_ms * 0x2545f4914f6cdd1dull +
                     0x9e3779b97f4a7c15ull;
        z = (z ^ z >> 30) * 0xbf58476d1ce4e5b9ull;
        z = (z ^ z >> 27) * 0x94d049bb133111ebull;
        z ^= z >> 31;
        uint32_t bits = (uint32_t)(z & 0x7fffffu) | (uint32_t)(127 + (z >> 61)) << 23; /* [1, 256) */
        memcpy(&val[r], &bits, 4); /* 23 random mantissa bits, 3 of exponent: no codec packs them below 26 */
    }
}

static void ecb_write_day(tsdbc *c, const tsdb_sid *ide, int64_t day_ms)
{
    for (int b = 0; b < 2; b++) {
        for (int s = 0; s < ECB_SERIES; s++) {
            static int64_t ts[ECB_ROWS];
            static float val[ECB_ROWS];
            ecb_rows_of(s, b, day_ms, ts, val);
            int rc;
            for (uint64_t t0 = now_ms(); (rc = tsdbc_insert_series(c, ide[s], ts, val, ECB_ROWS)) != 0; usleep(50000))
                if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                    die("insert into e42 on day %" PRId64 ": %s", day_ms, ers(rc));
        }
        usleep(1000000); /* past the flush interval */
    }
}

/* the series `name` of `vol` through its leader's client: MOVED too is retried, because the metadata leader's copy can
 * name a new volume's leader before that member's own copy does or before it has reopened the volume as the writer
 * (route_away answers MOVED to itself in that window; r8f-ecbasic3 met it for the twin) */
static tsdb_sid ecb_series(tsdbc *c, const char *name, const char *vol)
{
    uint64_t t0 = now_ms();
    for (;;) {
        tsdb_sid id = 0;
        int rc = tsdbc_series_at(c, name, vol, &id);
        if (rc == 0)
            return id;
        if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
            die("series %s in %s: %s", name, vol, ers(rc));
        usleep(20000);
    }
}

/* the .ec parts listed in server i's v<num> (retired_ ones not counted) */
/* is server i one of volume e's log replicas */
static bool ecb_is_rep(const struct meta_volume *e, int i)
{
    for (uint32_t k = 0; k < e->nrep; k++)
        if (server_of(e->rep[k].node) == i)
            return true;
    return false;
}

static int ecb_ec_parts(int i, uint32_t num)
{
    char d[PATH_MAX + 80], p[PATH_MAX + 120];
    server_dir(i, d, sizeof d);
    snprintf(p, sizeof p, "%s/v%" PRIu32, d, num);
    DIR *dd = opendir(p);
    if (!dd)
        return 0;
    int n = 0;
    for (struct dirent *e; (e = readdir(dd));) {
        size_t l = strlen(e->d_name);
        n += l > 3 && !strcmp(e->d_name + l - 3, ".ec") && strncmp(e->d_name, "retired_", 8) != 0;
    }
    closedir(dd);
    return n;
}

/* the live .part files (p<K>_<A>_<B>_<L>.part) in server i's v<num>, and their names into buf: rows still outside
 * every object, which a read answers without a decode */
static int ecb_live_parts(int i, uint32_t num, char *buf, size_t cap)
{
    char d[PATH_MAX + 80], p[PATH_MAX + 120];
    server_dir(i, d, sizeof d);
    snprintf(p, sizeof p, "%s/v%" PRIu32, d, num);
    DIR *dd = opendir(p);
    if (!dd)
        return -1;
    int n = 0;
    size_t at = 0;
    buf[0] = 0;
    for (struct dirent *e; (e = readdir(dd));) {
        size_t l = strlen(e->d_name);
        if (e->d_name[0] != 'p' || l < 6 || strcmp(e->d_name + l - 5, ".part") != 0)
            continue;
        n++;
        if (at + l + 2 < cap)
            at += (size_t)snprintf(buf + at, cap - at, " %s", e->d_name);
    }
    closedir(dd);
    return n;
}

static int tr_transfer(uint32_t num, uint32_t to, char *why, size_t n);

static void scen_ecbasic(void)
{
    scenario("ecbasic");
#ifndef TSDB_EC
    /* without the codec (make NO_EC=1) a tsdbd settles nothing: an ec volume's rows stay in .part files */
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#endif
    static char hpenv[PATH_MAX + 4300], hpath[PATH_MAX + 4200];
    snprintf(hpath, sizeof hpath, "%s/holdput", base);
    snprintf(hpenv, sizeof hpenv, "TSDB_CHUNKPEER_TEST=holdput=8000:%s", hpath); /* the last case: a put at SIGTERM */
    for (int i = 0; i < 6; i++) {
        envs[i] = "hold_copy_file=1,copy_probe=1"; /* the EPOCH case holds a stripe member's copy */
        penv[i] = hpenv;
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 6; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters of six members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    view_free(&v);
    static char xa[6][PATH_MAX + 256];
    for (int i = 0; i < 6; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/ecs%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i], "--chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 --merge-idle-s 1 "
                 "--flush-interval-ms 200", sd);
        restart_xargs(i, xa[i]);
    }
    await_view(5, p_six_placeable, NULL, "six members UP with their volumes open");
    uint32_t num = 0, tnum = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ec=4+2 with six stores: %s (%s)", cluster_strerror(rc), text);
    for (uint64_t t0 = now_ms(); (rc = vol_add(0, "t42", 3, &tnum)) != 0; usleep(100000))
        if (rc != CLUSTER_ERR_NOTLEADER || now_ms() - t0 > 30000)
            die("the twin t42: %s", cluster_strerror(rc));
    struct meta_volume e;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("no record of e42 with a leader in server 0's copy 30 s after the add");
    int L = server_of(e.leader);
    if (L < 0)
        die("e42's leader %" PRIu32 " is no server of the test", e.leader);
    struct meta_volume tv;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "t42", &tv) || !tv.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("no record of t42 with a leader in server 0's copy 30 s after the add");
    int Lt = server_of(tv.leader);
    if (Lt < 0)
        die("t42's leader %" PRIu32 " is no server of the test", tv.leader);
    printf("  e42 (volume %" PRIu32 ") led by server %d, twin t42 (volume %" PRIu32 ") by server %d\n", num, L, tnum,
           Lt);
    tsdbc *c = client(L), *ct = client(Lt);
    tsdb_sid ide[ECB_SERIES], idt[ECB_SERIES];
    const int64_t day0 = 1704067200000LL; /* 2024-01-01: long past the settle grace */
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecb.s%d", s);
        ide[s] = ecb_series(c, nm, "e42");
        idt[s] = ecb_series(ct, nm, "t42");
    }
    /* two batches a flush apart: two parts in the day's partition, which its idle merge (1 s) makes one of level 1,
     * the only kind a cluster settle takes (D18) */
    for (int b = 0; b < 2; b++) {
        for (int s = 0; s < ECB_SERIES; s++) {
            static int64_t ts[ECB_ROWS];
            static float val[ECB_ROWS];
            ecb_rows_of(s, b, day0, ts, val);
            for (uint64_t t0 = now_ms(); (rc = tsdbc_insert_series(c, ide[s], ts, val, ECB_ROWS)) != 0; usleep(50000))
                if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                    die("insert into e42: %s", ers(rc));
            int trc;
            for (uint64_t t0 = now_ms(); (trc = tsdbc_insert_series(ct, idt[s], ts, val, ECB_ROWS)) != 0; usleep(50000))
                if ((trc != TSDB_ERR_UNAVAILABLE && trc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                    die("insert into t42: %s", ers(trc));
        }
        usleep(1000000); /* past the flush interval */
    }
    int nec = 0;
    for (uint64_t t0 = now_ms(); (nec = ecb_ec_parts(L, num)) == 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("no .ec part in the leader's v%" PRIu32 " 120 s after the writes: nothing settled", num);
    /* every row of the day in an object before the kills: rows in a .part (a part the gate's flush wrote after the
     * first settle, settled again once rewritten) are answered without a decode, and a read of them cannot tell
     * three members away (the r8f-final run: 2 .ec parts, series 4 read whole with three members killed) */
    char live[1024];
    int nlive;
    for (uint64_t t0 = now_ms(); (nlive = ecb_live_parts(L, num, live, sizeof live)) != 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("%d .part file(s) left in the leader's v%" PRIu32 " 120 s after the first settle:%s", nlive, num, live);
    nec = ecb_ec_parts(L, num);
    printf("  settled: %d .ec part(s) in the leader's volume directory, no .part left\n", nec);
    for (int s = 0; s < 2; s++) {
        struct ecb_sum a, b;
        if ((rc = ecb_read(c, ide[s], &a)) != 0 || ecb_read(ct, idt[s], &b) != 0)
            die("read of series %d after the settle: %s", s, ers(rc));
        if (a.n != 2 * ECB_ROWS || a.n != b.n || a.h != b.h)
            die("series %d after the settle: %" PRIu64 " rows (hash %" PRIx64 "), the twin %" PRIu64 " (%" PRIx64 ")",
                s, a.n, a.h, b.n, b.h);
    }
    printf("  every answer equals the twin's after the settle\n");
    struct ecb_sum twin[ECB_SERIES]; /* read now: the kills below may take t42's members too */
    for (int s = 0; s < ECB_SERIES; s++)
        if ((rc = ecb_read(ct, idt[s], &twin[s])) != 0 || twin[s].n != 2 * ECB_ROWS)
            die("the twin's series %d: %s (%" PRIu64 " rows)", s, ers(rc), twin[s].n);
    /* stripe members killed and restarted: first those that are neither e42's log replicas nor the metadata leader,
     * then, while fewer than three, e42's follower replicas (never its leader L nor the metadata leader): with the
     * metadata leader among e42's replicas only two members are outside both, and the three-member case must never be
     * skipped (a run of a185e2a1 skipped it). A follower killed leaves L leading: reads stay at L. */
    int victims[6] = {-1}, nv = 0, ml = leader_of(L);
    for (int pass = 0; pass < 2; pass++)
        for (int i = 0; i < 6 && (pass == 0 || nv < 3); i++) {
            if (i != ml && i != L && ecb_is_rep(&e, i) == (pass == 1))
                victims[nv++] = i;
        }
    if (nv < 3 || ecb_is_rep(&e, victims[0]))
        die("%d stripe members to kill besides L and the metadata leader (server %d first)", nv, victims[0]);
    stop(victims[0], SIGKILL);
    for (int s = 2; s < 4; s++) {
        struct ecb_sum a, b = twin[s];
        if ((rc = ecb_read(c, ide[s], &a)) != 0)
            die("read of series %d with server %d killed: %s", s, victims[0], ers(rc));
        if (a.n != b.n || a.h != b.h)
            die("series %d with one stripe member away: %" PRIu64 " rows, the twin %" PRIu64, s, a.n, b.n);
    }
    printf("  one stripe member killed (server %d): reads decode around it\n", victims[0]);
    for (int k = 1; k < nv && k < 3; k++)
        stop(victims[k], SIGKILL);
    {
        int nun = 0;
        for (int s = 4; s < ECB_SERIES; s++) { /* none read before: the granule cache holds none of them */
            struct ecb_sum a, b = twin[s];
            rc = ecb_read(c, ide[s], &a);
            if (rc == TSDB_ERR_UNAVAILABLE) {
                nun++;
                continue;
            }
            if (rc != 0 || a.n != b.n || a.h != b.h)
                die("series %d with three stripe members away: %s (%" PRIu64 " rows, the twin %" PRIu64
                    "), want UNAVAILABLE or the twin's rows", s, ers(rc), a.n, b.n);
        }
        if (nun == 0) {
            char live[1024];
            int nl = ecb_live_parts(L, num, live, sizeof live);
            die("series 4-%d with three stripe members away (servers %d %d %d): every one read whole, none UNAVAILABLE "
                "(%d .ec, %d .part:%s)", ECB_SERIES - 1, victims[0], victims[1], victims[2], ecb_ec_parts(L, num), nl,
                live);
        }
        printf("  three stripe members killed (servers %d %d %d): UNAVAILABLE for %d of %d series, the rest whole\n",
               victims[0], victims[1], victims[2], nun, ECB_SERIES - 4);
    }
    for (int k = 0; k < nv && k < 3; k++)
        start(victims[k]);
    for (int s = 4; s < ECB_SERIES; s++) {
        struct ecb_sum a, b = twin[s];
        for (uint64_t t0 = now_ms(); (rc = ecb_read(c, ide[s], &a)) != 0; usleep(200000))
            if (rc != TSDB_ERR_UNAVAILABLE || now_ms() - t0 > 60000)
                die("read of series %d after the restarts: %s", s, ers(rc));
        if (a.n != b.n || a.h != b.h)
            die("series %d after the restarts: %" PRIu64 " rows, the twin %" PRIu64, s, a.n, b.n);
    }
    printf("  the members back: reads whole\n");

    /* e42's leadership moved to another replica: the new leader reads the objects the old one settled, with every
     * cache cold. A chunk's identity names the volume's uuid (META's, the same on every member: the r8f review's
     * mutant B01, a uuid of each member's own, survived while no test read after a leader change). */
    {
        int T = -1;
        for (uint32_t k = 0; k < e.nrep && T < 0; k++)
            if (server_of(e.rep[k].node) != L)
                T = server_of(e.rep[k].node);
        if (T < 0)
            die("e42 has no replica besides its leader %d", L);
        char why[256];
        for (uint64_t t0 = now_ms(); (rc = tr_transfer(num, ids[T], why, sizeof why)) != 0; usleep(500000))
            if (now_ms() - t0 > 60000) /* a member restarted above may still be out of the ISR */
                die("transfer of e42 to server %d: %s (%s)", T, cluster_strerror(rc), why);
        struct meta_volume ne;
        for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &ne) || ne.leader != ids[T]; usleep(50000))
            if (now_ms() - t0 > 30000)
                die("e42's record does not name server %d its leader 30 s after the transfer", T);
        /* The record names T before T has reopened as the writer, and that reopen attaches the tier: it asks every
         * stripe member to hold the new epoch. The EPOCH case below stops a member; let the attach end first, or it
         * finds that member down or unsure and the settle is refused at the writable gate before any put (the r8f
         * fixer's run fx4 base1: no "failed" line from a put in 60 s). */
        char lead[96];
        snprintf(lead, sizeof lead, "volume %" PRIu32 ": leads epoch %" PRIu64 " ", num, ne.epoch);
        for (uint64_t t0 = now_ms(); !log_has(T, lead); usleep(50000))
            if (now_ms() - t0 > 30000)
                die("server %d named e42's leader but has not reopened as its writer in 30 s", T);
        L = T;
        tsdbc_close(c);
        c = client(L);
        for (int s = 0; s < ECB_SERIES; s++) {
            struct ecb_sum a, b = twin[s];
            for (uint64_t t0 = now_ms(); (rc = ecb_read(c, ide[s], &a)) != 0; usleep(200000))
                if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 60000)
                    die("read of series %d at the new leader %d: %s", s, L, ers(rc));
            if (a.n != b.n || a.h != b.h)
                die("series %d at the new leader %d: %" PRIu64 " rows, the twin %" PRIu64, s, L, a.n, b.n);
        }
        printf("  e42 transferred to server %d: every series read whole from the objects\n", L);
    }

    /* D9: one EPOCH slot of e42 damaged in S's store, S restarted: the store is unsure. Its copy held behind a volume
     * add (not caught up), a settle's put to S is refused and the settle fails: neither the put's epoch nor the
     * store's surviving slot (mutant ownepoch) nor a copy that is not caught up (staleraise) raises it. Let go, the
     * copy raises it and the next day settles. */
    int S = victims[0];
    char ep[PATH_MAX + 80], hold[PATH_MAX + 96], needle[96];
    snprintf(ep, sizeof ep, "%s/ecs%d/s%" PRIu32 "/EPOCH", base, S, num);
    {
        struct view vv;
        view((S + 1) % 6, &vv);
        const struct meta_member *mb = meta_member(&vv.m, ids[S]);
        struct state_want up = {ids[S], META_UP, mb ? mb->incarnation + 1 : 1};
        view_free(&vv);
        stop(S, SIGTERM);
        int fd = open(ep, O_RDWR);
        uint8_t byte;
        if (fd < 0 || pread(fd, &byte, 1, 16) != 1)
            die("%s: %s", ep, strerror(errno));
        byte ^= 0x5a;
        if (pwrite(fd, &byte, 1, 16) != 1 || fsync(fd) != 0)
            die("%s: %s", ep, strerror(errno));
        close(fd);
        start(S);
        await_view((S + 1) % 6, p_member_state, &up, "the stripe member back with a damaged EPOCH slot");
    }
    server_dir(S, hold, sizeof hold);
    strcat(hold, "/state/holdcopy");
    FILE *hf = fopen(hold, "w");
    if (!hf)
        die("%s: %s", hold, strerror(errno));
    fclose(hf);
    usleep(300000); /* a round of S's cluster thread */
    uint32_t hnum;
    for (uint64_t t0 = now_ms(); (rc = vol_add(meta_leader_of(6), "hx", 3, &hnum)) != 0; usleep(100000))
        if (rc != CLUSTER_ERR_NOTLEADER || now_ms() - t0 > 30000)
            die("volume add hx: %s", cluster_strerror(rc));
    await_caught(S, 0, now_ms(), WAIT_MS, "its published copy held behind a volume add");
    snprintf(needle, sizeof needle, "on member %" PRIu32 " failed", ids[S]);
    int refused0 = log_count(L, needle), nec0 = ecb_ec_parts(L, num);
    ecb_write_day(c, ide, day0 + 2 * 86400000LL);
    for (uint64_t t0 = now_ms(); log_count(L, needle) == refused0; usleep(200000))
        if (now_ms() - t0 > 60000)
            die("no put to server %d (an unsure store, its copy held) was refused in 60 s: %d .ec parts, %d before", S,
                ecb_ec_parts(L, num), nec0);
    if (!log_has(S, "EPOCH slot 0 is damaged"))
        die("server %d's store did not say its EPOCH slot 0 is damaged", S);
    usleep(1000000);
    if (ecb_ec_parts(L, num) != nec0)
        die("a settle went through with server %d's store unsure and its copy not caught up", S);
    printf("  an unsure store with its copy held: the put refused, nothing settled\n");
    unlink(hold);
    await_caught(S, 1, now_ms(), WAIT_MS, "its published copy let go");
    ecb_write_day(c, ide, day0 + 4 * 86400000LL); /* a failed key waits an hour: another day */
    for (uint64_t t0 = now_ms(); ecb_ec_parts(L, num) == nec0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("nothing settled 120 s after server %d's copy was let go", S);
    printf("  the copy caught up raises it: the next day settles\n");

    /* D13: chunks of a cluster volume are deleted only by a committed MK_GC (r8k). The rows expired, the .ec parts
     * are retired, and within obsolete_part_lifetime_s (480 s) every chunk stays (no direct delete). */
    int nch = ecb_chunks(num);
    if (nch == 0)
        die("no chunk files of e42 in the stores");
    for (int s = 0; s < ECB_SERIES; s++)
        for (uint64_t t0 = now_ms(); (rc = tsdbc_set_retention(c, ide[s], 86400000LL)) != 0; usleep(50000))
            if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                die("retention of e42's series %d: %s", s, ers(rc));
    for (uint64_t t0 = now_ms(); ecb_ec_parts(L, num) != 0; usleep(200000))
        if (now_ms() - t0 > 60000)
            die("e42's expired .ec parts: %d still listed 60 s after retention", ecb_ec_parts(L, num));
    usleep(2000000); /* within obsolete_part_lifetime_s: no direct delete */
    int nch2 = ecb_chunks(num);
    if (nch2 != nch)
        die("e42's chunks: %d before the drop, %d after: deleted before lifetime", nch, nch2);
    printf("  the .ec parts dropped by retention: retired cleanly, %d chunk files kept within lifetime\n", nch);

    /* A settle's put in flight at SIGTERM (the r8f review's F3): the engines' threads call into the chunk server until
     * tsdb_close, after tsdbd frees it, so the free waits for every call holding it. The hook holds the first put once
     * its file exists for 8 s and says whether the chunk server was still open when it let go. New series of their own
     * (no retention) on a new day, so that there is something to settle. */
    tsdb_sid idh[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecb.h%d", s);
        idh[s] = ecb_series(c, nm, "e42");
    }
    FILE *hpf = fopen(hpath, "w");
    if (!hpf)
        die("%s: %s", hpath, strerror(errno));
    fclose(hpf);
    ecb_write_day(c, idh, day0 + 6 * 86400000LL);
    for (uint64_t t0 = now_ms(); !log_has(L, "holdput: a put holds"); usleep(100000))
        if (now_ms() - t0 > 120000)
            die("no settle put held at server %d 120 s after the writes", L);
    tsdbc_close(ct);
    tsdbc_close(c);
    stop(L, SIGTERM); /* exit status 0 required */
    if (!log_has(L, "holdput: released, the chunk server still open"))
        die("server %d stopped with a put in flight: %s", L,
            log_has(L, "closed under it") ? "the chunk server was closed under it" : "the put never let go");
    printf("  a settle's put in flight at SIGTERM: the shutdown waited for it, exit 0\n");
}

/* ecslow (r8n-hedge, server/chunkpeer.c; design-cluster-data.md E11, E15, E31, §10.3): one stripe member's chunk
 * replies delayed -> 5% hedge token bucket keeps total chunk reads <= 1.05x baseline (kills hedgeall), sustained
 * slowness triggers read-avoid after 8 timeouts in 10 s so query p99 stays bounded (kills noavoid), m+1 away returns
 * UNAVAILABLE never CORRUPT (kills hedgecorrupt), and read-avoid recovers automatically after 30 s. */
#ifdef TSDB_EC
static uint64_t ecslow_metric_peer(const char *buf, const char *family, uint32_t peer)
{
    char key[128];
    snprintf(key, sizeof key, "\n%s{peer=\"%" PRIu32 "\"} ", family, peer);
    const char *p = strstr(buf, key);
    if (!p) {
        snprintf(key, sizeof key, "%s{peer=\"%" PRIu32 "\"} ", family, peer);
        if (strncmp(buf, key, strlen(key)) == 0)
            p = buf;
        else
            return 0;
    } else {
        p++;
    }
    return strtoull(p + strlen(key) - (p == buf ? 0 : 1), NULL, 10);
}

static uint64_t ecslow_metric_sum(const char *buf, const char *family, const uint32_t *peers, unsigned n)
{
    uint64_t sum = 0;
    for (unsigned i = 0; i < n; i++)
        sum += ecslow_metric_peer(buf, family, peers[i]);
    return sum;
}

static void ecslow_write_delay(const char *path, uint32_t node, int ms, unsigned max_cnt)
{
    char tmp[PATH_MAX + 64];
    snprintf(tmp, sizeof tmp, "%s.tmp", path);
    FILE *f = fopen(tmp, "w");
    if (!f)
        die("open %s: %s", tmp, strerror(errno));
    fprintf(f, "%" PRIu32 " %d %u\n", node, ms, max_cnt);
    fclose(f);
    if (rename(tmp, path) != 0)
        die("rename %s -> %s: %s", tmp, path, strerror(errno));
}

static int ecslow_cmp_u64(const void *a, const void *b)
{
    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;
    return (x > y) - (x < y);
}

static int ecslow_read_win(tsdbc *c, tsdb_sid id, int64_t t0, int64_t t1, struct ecb_sum *s)
{
    memset(s, 0, sizeof *s);
    return tsdbc_query_raw(c, id, t0, t1, ecb_rows, s);
}
#endif

#define ECS_SERIES 16
#define ECS_WINS 10
static void scen_ecslow(void)
{
    scenario("ecslow");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#else
    static char dpath[PATH_MAX + 64], denv[PATH_MAX + 128];
    snprintf(dpath, sizeof dpath, "%s/read_delay.cfg", base);
    unlink(dpath);
    snprintf(denv, sizeof denv, "TSDB_CHUNKPEER_TEST=read_delay=%s", dpath);
    for (int i = 0; i < 6; i++) {
        penv[i] = denv;
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 6; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters of six members");
    struct view vw;
    view(0, &vw);
    uint8_t uuid[16];
    memcpy(uuid, vw.m.uuid, 16);
    view_free(&vw);
    static char xa[6][PATH_MAX + 256];
    int mport[6] = {0};
    for (int i = 0; i < 6; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/ecs%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i],
                 "--chunk-dir %s --metrics-port auto --ec-settle-grace-s 0 --ec-settle-force-s 1 "
                 "--ec-cache-mb 1 --merge-idle-s 1 --flush-interval-ms 200",
                 sd);
        restart_xargs(i, xa[i]);
        mport[i] = th_mport;
        if (mport[i] <= 0)
            die("server %d: no metrics port reported", i);
    }
    await_view(5, p_six_placeable, NULL, "six members UP with their volumes open");
    uint32_t num = 0, tnum = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ec=4+2 with six stores: %s (%s)", cluster_strerror(rc), text);
    for (uint64_t t0 = now_ms(); (rc = vol_add(0, "t42", 3, &tnum)) != 0; usleep(100000))
        if (rc != CLUSTER_ERR_NOTLEADER || now_ms() - t0 > 30000)
            die("the twin t42: %s", cluster_strerror(rc));
    struct meta_volume e, tv;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("no record of e42 with a leader 30 s after add");
    for (uint64_t t0 = now_ms(); !vol_rec(0, "t42", &tv) || !tv.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("no record of t42 with a leader 30 s after add");
    int L = server_of(e.leader), Lt = server_of(tv.leader), ml = leader_of(L);
    if (L < 0 || Lt < 0)
        die("e42 leader %d or t42 leader %d invalid", L, Lt);
    tsdbc *c = client(L), *ct = client(Lt);
    tsdb_sid ide[ECS_SERIES], idt[ECS_SERIES];
    const int64_t day0 = 1704067200000LL;
    for (int s = 0; s < ECS_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecs.s%d", s);
        ide[s] = ecb_series(c, nm, "e42");
        idt[s] = ecb_series(ct, nm, "t42");
    }
    for (int b = 0; b < 2; b++) {
        for (int s = 0; s < ECS_SERIES; s++) {
            static int64_t ts[ECB_ROWS];
            static float val[ECB_ROWS];
            ecb_rows_of(s, b, day0, ts, val);
            for (uint64_t t0 = now_ms(); (rc = tsdbc_insert_series(c, ide[s], ts, val, ECB_ROWS)) != 0; usleep(50000))
                if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                    die("insert e42: %s", ers(rc));
            int trc;
            for (uint64_t t0 = now_ms(); (trc = tsdbc_insert_series(ct, idt[s], ts, val, ECB_ROWS)) != 0; usleep(50000))
                if ((trc != TSDB_ERR_UNAVAILABLE && trc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                    die("insert t42: %s", ers(trc));
        }
        usleep(1000000);
    }
    for (uint64_t t0 = now_ms(); ecb_ec_parts(L, num) == 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("ecslow: nothing settled in 120 s");
    char live[1024];
    for (uint64_t t0 = now_ms(); ecb_live_parts(L, num, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("ecslow: .part files left after settle:%s", live);

    /* Non-sequential granule windows (one granule per query, 160 total, > 1 MiB cache so each sweep misses). */
    static const int worder[ECS_WINS] = {0, 5, 2, 7, 4, 9, 1, 6, 3, 8};
    static struct ecb_sum oracle[ECS_SERIES][ECS_WINS];
    for (int wi = 0; wi < ECS_WINS; wi++) {
        int g = worder[wi];
        int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL;
        int64_t we = ws + 1000000LL;
        for (int s = 0; s < ECS_SERIES; s++) {
            if ((rc = ecslow_read_win(ct, idt[s], ws, we, &oracle[s][g])) != 0 || oracle[s][g].n == 0)
                die("ecslow: oracle read s=%d g=%d: %s (n=%" PRIu64 ")", s, g, ers(rc), oracle[s][g].n);
        }
    }
    tsdbc_close(ct);

    /* Phase 1: Warmup sweep + Baseline sweep. */
    static char mbuf[256 * 1024];
    for (int pass = 0; pass < 2; pass++) {
        uint64_t r0 = 0, per0[4] = {0};
        if (pass == 1) {
            metrics_get(mport[L], mbuf, sizeof mbuf);
            r0 = ecslow_metric_sum(mbuf, "tsdb_chunk_reads_total", e.stripe, e.nstripe);
            for (unsigned p = 0; p < 4; p++)
                per0[p] = ecslow_metric_peer(mbuf, "tsdb_chunk_reads_total", e.stripe[p]);
        }
        for (int wi = 0; wi < ECS_WINS; wi++) {
            int g = worder[wi];
            int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL, we = ws + 1000000LL;
            for (int s = 0; s < ECS_SERIES; s++) {
                struct ecb_sum a;
                if ((rc = ecslow_read_win(c, ide[s], ws, we, &a)) != 0 || a.n != oracle[s][g].n ||
                    a.h != oracle[s][g].h)
                    die("ecslow: baseline s=%d g=%d: %s (n=%" PRIu64 " want %" PRIu64 ")", s, g, ers(rc), a.n,
                        oracle[s][g].n);
            }
        }
        if (pass == 1) {
            metrics_get(mport[L], mbuf, sizeof mbuf);
            uint64_t base_reads = ecslow_metric_sum(mbuf, "tsdb_chunk_reads_total", e.stripe, e.nstripe) - r0;
            /* Pick a data position (0..3) that is neither L nor ml and received the most reads. */
            int slow_srv = -1;
            uint32_t slow_node = 0;
            uint64_t slow_best = 0;
            for (unsigned p = 0; p < 4; p++) {
                int sv = server_of(e.stripe[p]);
                uint64_t d = ecslow_metric_peer(mbuf, "tsdb_chunk_reads_total", e.stripe[p]) - per0[p];
                if (sv >= 0 && sv != L && sv != ml && d > slow_best) {
                    slow_best = d;
                    slow_srv = sv;
                    slow_node = e.stripe[p];
                }
            }
            if (slow_srv < 0 || base_reads < 80 || slow_best < 15)
                die("ecslow: baseline too small (base_reads=%" PRIu64 ", slow_best=%" PRIu64 ", slow_srv=%d)",
                    base_reads, slow_best, slow_srv);
            printf("  baseline: %" PRIu64 " chunk reads (slow target server %d node %" PRIu32 ": %" PRIu64 " reads)\n",
                   base_reads, slow_srv, slow_node, slow_best);

            /* Phase 2: 5% token bucket cap (6 delayed reads < 8 -> no read-avoid; total reads <= 1.05x baseline;
             * kills mutant hedgeall). */
            uint64_t p2_r0 = ecslow_metric_sum(mbuf, "tsdb_chunk_reads_total", e.stripe, e.nstripe);
            uint64_t p2_h0 = ecslow_metric_peer(mbuf, "tsdb_chunk_read_hedges_total", slow_node);
            ecslow_write_delay(dpath, slow_node, 550, 6);
            for (int wi = 0; wi < ECS_WINS; wi++) {
                int g = worder[wi];
                int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL, we = ws + 1000000LL;
                for (int s = 0; s < ECS_SERIES; s++) {
                    struct ecb_sum a;
                    if ((rc = ecslow_read_win(c, ide[s], ws, we, &a)) != 0 || a.n != oracle[s][g].n ||
                        a.h != oracle[s][g].h)
                        die("ecslow: phase2 s=%d g=%d: %s", s, g, ers(rc));
                }
            }
            usleep(700000); /* let any late primary finish and record */
            metrics_get(mport[L], mbuf, sizeof mbuf);
            uint64_t p2_reads = ecslow_metric_sum(mbuf, "tsdb_chunk_reads_total", e.stripe, e.nstripe) - p2_r0;
            uint64_t p2_hedges = ecslow_metric_peer(mbuf, "tsdb_chunk_read_hedges_total", slow_node) - p2_h0;
            uint64_t p2_avoid = ecslow_metric_peer(mbuf, "tsdb_chunk_read_avoid", slow_node);
            printf("  bucket phase: %" PRIu64 " chunk reads (baseline %" PRIu64 ", ratio %.3fx), %" PRIu64
                   " hedges, avoid=%" PRIu64 "\n",
                   p2_reads, base_reads, (double)p2_reads / (double)base_reads, p2_hedges, p2_avoid);
            if (p2_avoid != 0)
                die("ecslow: entered read-avoid after only 6 delayed reads");
            if (p2_hedges == 0)
                die("ecslow: no hedge launched during delayed reads");
            if (p2_reads > (base_reads * 105u) / 100u)
                die("ecslow: total chunk reads %" PRIu64 " exceeded 1.05x baseline %" PRIu64 " (ratio %.3fx)", p2_reads,
                    base_reads, (double)p2_reads / (double)base_reads);

            /* Phase 3: Sustained delay (550 ms on every read to slow_node) -> enters read-avoid after 8 timeouts;
             * query p99 stays bounded (kills mutant noavoid). */
            ecslow_write_delay(dpath, slow_node, 550, 0);
            uint64_t t_trig = now_ms();
            int entered = 0;
            for (int iter = 0; iter < 6 && !entered && now_ms() - t_trig < 20000; iter++) {
                int g = worder[iter % ECS_WINS];
                int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL, we = ws + 1000000LL;
                for (int s = 0; s < ECS_SERIES && !entered; s++) {
                    struct ecb_sum a;
                    if ((rc = ecslow_read_win(c, ide[s], ws, we, &a)) != 0 || a.n != oracle[s][g].n ||
                        a.h != oracle[s][g].h)
                        die("ecslow: trigger avoid s=%d g=%d: %s", s, g, ers(rc));
                    metrics_get(mport[L], mbuf, sizeof mbuf);
                    if (ecslow_metric_peer(mbuf, "tsdb_chunk_read_avoid", slow_node) == 1)
                        entered = 1;
                }
            }
            /* Timed query loop of 64 queries (4 windows x 16 series) to measure p99 latency. */
            uint64_t lats[64];
            int nlats = 0;
            for (int wi = 4; wi < 8; wi++) {
                int g = worder[wi];
                int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL, we = ws + 1000000LL;
                for (int s = 0; s < ECS_SERIES; s++) {
                    struct ecb_sum a;
                    uint64_t q0 = now_ms();
                    if ((rc = ecslow_read_win(c, ide[s], ws, we, &a)) != 0 || a.n != oracle[s][g].n ||
                        a.h != oracle[s][g].h)
                        die("ecslow: avoid loop s=%d g=%d: %s", s, g, ers(rc));
                    lats[nlats++] = now_ms() - q0;
                }
            }
            qsort(lats, (size_t)nlats, sizeof *lats, ecslow_cmp_u64);
            uint64_t p99_ms = lats[(nlats * 99) / 100];
            metrics_get(mport[L], mbuf, sizeof mbuf);
            uint64_t av_now = ecslow_metric_peer(mbuf, "tsdb_chunk_read_avoid", slow_node);
            uint64_t av_cnt = ecslow_metric_peer(mbuf, "tsdb_chunk_read_avoids_total", slow_node);
            uint64_t dec_cnt = ecslow_metric_peer(mbuf, "tsdb_chunk_decoded_cells_total", slow_node);
            printf("  read-avoid phase: entered=%d avoid_gauge=%" PRIu64 " avoids=%" PRIu64 " decoded=%" PRIu64
                   " query p99=%" PRIu64 " ms\n",
                   entered, av_now, av_cnt, dec_cnt, p99_ms);
            if (!entered || av_now != 1 || av_cnt == 0 || dec_cnt == 0)
                die("ecslow: slow node %" PRIu32 " did not enter read-avoid (entered=%d gauge=%" PRIu64
                    " avoids=%" PRIu64 " decoded=%" PRIu64 ")",
                    slow_node, entered, av_now, av_cnt, dec_cnt);
            if (p99_ms >= 250)
                die("ecslow: query p99 %" PRIu64 " ms exceeded 250 ms bound while slow node in read-avoid", p99_ms);

            /* Phase 4: E15 check — kill 2 other stripe members while slow_node is in read-avoid (m+1=3 away).
             * Must return UNAVAILABLE, never CORRUPT (kills mutant hedgecorrupt). */
            int vict[2] = {-1, -1}, nv = 0;
            for (int kpass = 0; kpass < 2 && nv < 2; kpass++)
                for (int i = 0; i < 6 && nv < 2; i++)
                    if (i != L && i != ml && i != slow_srv && ecb_is_rep(&e, i) == (kpass == 1))
                        vict[nv++] = i;
            if (nv < 2)
                die("ecslow: fewer than 2 victims besides L=%d ml=%d slow=%d", L, ml, slow_srv);
            stop(vict[0], SIGKILL);
            stop(vict[1], SIGKILL);
            int nun = 0;
            for (int wi = 0; wi < 3; wi++) {
                int g = worder[(8 + wi) % ECS_WINS];
                int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL, we = ws + 1000000LL;
                for (int s = 0; s < ECS_SERIES; s++) {
                    struct ecb_sum a;
                    rc = ecslow_read_win(c, ide[s], ws, we, &a);
                    if (rc == TSDB_ERR_UNAVAILABLE) {
                        nun++;
                        continue;
                    }
                    if (rc != 0 || a.n != oracle[s][g].n || a.h != oracle[s][g].h)
                        die("ecslow: 3 away (2 killed + 1 read-avoid) s=%d g=%d: %s (want UNAVAILABLE or exact)", s, g,
                            ers(rc));
                }
            }
            if (nun == 0)
                die("ecslow: 3 away returned no UNAVAILABLE across 48 queries");
            printf("  E15 check (2 killed + 1 read-avoid): %d UNAVAILABLE, 0 CORRUPT\n", nun);
            start(vict[0]);
            start(vict[1]);

            /* Phase 5: Remove delay, wait for 30 s read-avoid to expire, verify automatic recovery. */
            unlink(dpath);
            int recovered = 0;
            for (uint64_t t0 = now_ms(); now_ms() - t0 < 45000; usleep(500000)) {
                metrics_get(mport[L], mbuf, sizeof mbuf);
                if (ecslow_metric_peer(mbuf, "tsdb_chunk_read_avoid", slow_node) == 0) {
                    recovered = 1;
                    break;
                }
            }
            if (!recovered)
                die("ecslow: slow node %" PRIu32 " did not recover from read-avoid within 45 s", slow_node);
            /* Wait for restarted victims to serve again, then verify direct reads resume on slow_node. */
            for (uint64_t t0 = now_ms();; usleep(200000)) {
                struct ecb_sum a;
                int g = worder[0];
                int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL, we = ws + 1000000LL;
                if (ecslow_read_win(c, ide[0], ws, we, &a) == 0)
                    break;
                if (now_ms() - t0 > 30000)
                    die("ecslow: cluster did not become readable after restarting victims");
            }
            /* Run one sweep to clear any stale open handles, then measure a clean recovered sweep. */
            for (int wi = 0; wi < 2; wi++) {
                int g = worder[wi];
                int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL, we = ws + 1000000LL;
                for (int s = 0; s < ECS_SERIES; s++) {
                    struct ecb_sum a;
                    for (uint64_t t0 = now_ms(); (rc = ecslow_read_win(c, ide[s], ws, we, &a)) != 0; usleep(200000))
                        if (rc != TSDB_ERR_UNAVAILABLE || now_ms() - t0 > 30000)
                            die("ecslow: settle after restart s=%d g=%d: %s", s, g, ers(rc));
                }
            }
            metrics_get(mport[L], mbuf, sizeof mbuf);
            uint64_t rec_r0 = ecslow_metric_peer(mbuf, "tsdb_chunk_reads_total", slow_node);
            uint64_t rec_av0 = ecslow_metric_peer(mbuf, "tsdb_chunk_read_avoids_total", slow_node);
            uint64_t rec_dec0 = ecslow_metric_peer(mbuf, "tsdb_chunk_decoded_cells_total", slow_node);
            for (int wi = 0; wi < ECS_WINS; wi++) {
                int g = worder[wi];
                int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL, we = ws + 1000000LL;
                for (int s = 0; s < ECS_SERIES; s++) {
                    struct ecb_sum a;
                    if ((rc = ecslow_read_win(c, ide[s], ws, we, &a)) != 0 || a.n != oracle[s][g].n ||
                        a.h != oracle[s][g].h)
                        die("ecslow: recovered sweep s=%d g=%d: %s", s, g, ers(rc));
                }
            }
            metrics_get(mport[L], mbuf, sizeof mbuf);
            uint64_t rec_r1 = ecslow_metric_peer(mbuf, "tsdb_chunk_reads_total", slow_node);
            uint64_t rec_av1 = ecslow_metric_peer(mbuf, "tsdb_chunk_read_avoids_total", slow_node);
            uint64_t rec_dec1 = ecslow_metric_peer(mbuf, "tsdb_chunk_decoded_cells_total", slow_node);
            printf("  recovered: slow node reads +%" PRIu64 ", avoids +%" PRIu64 ", decoded +%" PRIu64 "\n",
                   rec_r1 - rec_r0, rec_av1 - rec_av0, rec_dec1 - rec_dec0);
            if (rec_r1 <= rec_r0 || rec_av1 != rec_av0 || rec_dec1 != rec_dec0)
                die("ecslow: slow node %" PRIu32 " did not resume clean direct reads (reads +%" PRIu64
                    ", avoids +%" PRIu64 ", decoded +%" PRIu64 ")",
                    slow_node, rec_r1 - rec_r0, rec_av1 - rec_av0, rec_dec1 - rec_dec0);

            /* Phase 6: Clean SIGTERM while a hedged primary thread is still sleeping in read_delay_hook ->
             * tsdbd must wait in chunkpeer_quiesce() and exit 0 (regression test for shutdown quiesce). */
            uint64_t q_h0 = ecslow_metric_peer(mbuf, "tsdb_chunk_read_hedges_total", slow_node);
            ecslow_write_delay(dpath, slow_node, 1500, 1);
            int q_hedged = 0;
            for (int wi = 0; wi < ECS_WINS && !q_hedged; wi++) {
                int g = worder[wi];
                int64_t ws = day0 + (int64_t)g * 8192000LL + 1000LL, we = ws + 1000000LL;
                for (int s = 0; s < ECS_SERIES && !q_hedged; s++) {
                    struct ecb_sum a;
                    if ((rc = ecslow_read_win(c, ide[s], ws, we, &a)) != 0 || a.n != oracle[s][g].n ||
                        a.h != oracle[s][g].h)
                        die("ecslow: quiesce trigger s=%d g=%d: %s", s, g, ers(rc));
                    metrics_get(mport[L], mbuf, sizeof mbuf);
                    if (ecslow_metric_peer(mbuf, "tsdb_chunk_read_hedges_total", slow_node) > q_h0)
                        q_hedged = 1;
                }
            }
            if (!q_hedged)
                die("ecslow: failed to launch a hedge before SIGTERM quiesce check");
            tsdbc_close(c);
            c = NULL;
            uint64_t t_stop = now_ms();
            stop(L, SIGTERM); /* requires exit status 0 */
            uint64_t stop_ms = now_ms() - t_stop;
            unlink(dpath);
            printf("  shutdown quiesce with hedged primary in flight: stop took %" PRIu64 " ms, exit 0\n", stop_ms);
            if (stop_ms < 500)
                die("ecslow: tsdbd exited in %" PRIu64 " ms without waiting for in-flight detached primary thread",
                    stop_ms);
        }
    }
    if (c)
        tsdbc_close(c);
#endif
}

/* ec16 (R8-2, design-cluster-data.md §10.1): 22 nodes on one host (epoll on all but at most two), ec=16+4 volume
 * (5 log replicas, 20 stripe positions + 2 spares) settles, kill four stripe members -> read whole equal to twin;
 * kill five -> UNAVAILABLE (never CORRUPT); restart all five -> read whole again. Skips cleanly under NO_EC=1. */
#define EC16_NODES 22
#define EC16_SERIES 24
static void scen_ec16(void)
{
    scenario("ec16");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#endif
    check_host_limits(EC16_NODES);
    epoll_after_two = 1;
    start_range(EC16_NODES);
    init_cluster(0, 600);
    for (int i = 1; i < EC16_NODES; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters of twenty-two members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    view_free(&v);
    static char xa[EC16_NODES][PATH_MAX + 256];
    for (int i = 0; i < EC16_NODES; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/ecs%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i], "--chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 --merge-idle-s 1 "
                 "--flush-interval-ms 200 --ec-cache-mb 16", sd);
    }
    /* Restart the 5 Raft voters one by one (ephemeral --port 0 peer ports: restarting all 5 at once loses every
     * seed address), then stop and restart the 17 watchers in parallel against the live voters. */
    for (int i = 0; i < 5; i++)
        restart_xargs(i, xa[i]);
    int watchers[EC16_NODES];
    int nw = 0;
    for (int i = 5; i < EC16_NODES; i++) {
        watchers[nw++] = i;
        signal_child(pids[i], SIGTERM);
    }
    for (int k = 0; k < nw; k++) {
        int i = watchers[k], status;
        if (waitpid(pids[i], &status, 0) != pids[i])
            die("waitpid %d: %s", (int)pids[i], strerror(errno));
        if (!(WIFEXITED(status) && WEXITSTATUS(status) == 0))
            die("server %d did not stop cleanly on SIGTERM (status 0x%x)", i, status);
        pids[i] = 0;
        xargs[i] = xa[i];
    }
    start_many(watchers, nw);
    unsigned want_up = EC16_NODES;
    await_view_ms(0, p_n_placeable, &want_up, "twenty-two members UP with their volumes open", 60000);
    uint32_t num = 0, tnum = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e164", 0, 16, 4, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 60000)
            die("ec=16+4 with %d stores: %s (%s)", EC16_NODES, cluster_strerror(rc), text);
    for (uint64_t t0 = now_ms(); (rc = vol_add(0, "t164", 3, &tnum)) != 0; usleep(100000))
        if (rc != CLUSTER_ERR_NOTLEADER || now_ms() - t0 > 30000)
            die("the twin t164: %s", cluster_strerror(rc));
    struct meta_volume e;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e164", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("no record of e164 with a leader in server 0's copy 30 s after the add");
    if (e.redundancy != META_RED_EC || e.ec_k != 16 || e.ec_m != 4 || e.nstripe != 20 || e.nrep != 5)
        die("e164: redundancy %u ec=%u+%u nstripe %" PRIu32 " nrep %" PRIu32, e.redundancy, e.ec_k, e.ec_m, e.nstripe,
            e.nrep);
    int L = server_of(e.leader);
    if (L < 0)
        die("e164's leader %" PRIu32 " is no server of the test", e.leader);
    struct meta_volume tv;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "t164", &tv) || !tv.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("no record of t164 with a leader in server 0's copy 30 s after the add");
    int Lt = server_of(tv.leader);
    if (Lt < 0)
        die("t164's leader %" PRIu32 " is no server of the test", tv.leader);
    await_isr(L, "e164", 5, 60000, "e164 five log replicas in sync");
    printf("  e164 (volume %" PRIu32 ", 16+4, 5 log replicas, 20 stripe members) led by server %d, twin t164 by server %d\n",
           num, L, Lt);
    tsdbc *c = client(L), *ct = client(Lt);
    tsdb_sid ide[EC16_SERIES], idt[EC16_SERIES];
    const int64_t day0 = 1704067200000LL;
    for (int s = 0; s < EC16_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ec16.s%d", s);
        ide[s] = ecb_series(c, nm, "e164");
        idt[s] = ecb_series(ct, nm, "t164");
    }
    for (int b = 0; b < 2; b++) {
        for (int s = 0; s < EC16_SERIES; s++) {
            static int64_t ts[ECB_ROWS];
            static float val[ECB_ROWS];
            ecb_rows_of(s, b, day0, ts, val);
            for (uint64_t t0 = now_ms(); (rc = tsdbc_insert_series(c, ide[s], ts, val, ECB_ROWS)) != 0; usleep(50000))
                if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                    die("insert into e164: %s", ers(rc));
            int trc;
            for (uint64_t t0 = now_ms(); (trc = tsdbc_insert_series(ct, idt[s], ts, val, ECB_ROWS)) != 0; usleep(50000))
                if ((trc != TSDB_ERR_UNAVAILABLE && trc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                    die("insert into t164: %s", ers(trc));
        }
        usleep(1000000);
    }
    int nec = 0;
    for (uint64_t t0 = now_ms(); (nec = ecb_ec_parts(L, num)) == 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("no .ec part in the leader's v%" PRIu32 " 120 s after the writes: nothing settled", num);
    char live[1024];
    int nlive;
    for (uint64_t t0 = now_ms(); (nlive = ecb_live_parts(L, num, live, sizeof live)) != 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("%d .part file(s) left in the leader's v%" PRIu32 " 120 s after the first settle:%s", nlive, num, live);
    nec = ecb_ec_parts(L, num);
    int nch = ecb_chunks_n(num, EC16_NODES);
    if (nch < 20)
        die("e164 settled %d .ec part(s) but only %d chunk files across %d stores (want >= 20)", nec, nch, EC16_NODES);
    printf("  settled: %d .ec part(s), %d chunk files across %d stores, no .part left\n", nec, nch, EC16_NODES);
    struct ecb_sum twin[EC16_SERIES];
    for (int s = 0; s < EC16_SERIES; s++)
        if ((rc = ecb_read(ct, idt[s], &twin[s])) != 0 || twin[s].n != 2 * ECB_ROWS)
            die("the twin's series %d: %s (%" PRIu64 " rows)", s, ers(rc), twin[s].n);
    for (int s = 0; s < 4; s++) {
        struct ecb_sum a, b = twin[s];
        if ((rc = ecb_read(c, ide[s], &a)) != 0)
            die("read of series %d after the settle: %s", s, ers(rc));
        if (a.n != b.n || a.h != b.h)
            die("series %d after the settle: %" PRIu64 " rows (hash %" PRIx64 "), the twin %" PRIu64 " (%" PRIx64 ")",
                s, a.n, a.h, b.n, b.h);
    }
    printf("  healthy reads equal the twin's\n");
    /* Pick 5 stripe members to kill: never L, never any Raft voter (keeps metadata quorum intact), non-log-replicas
     * first so L keeps its lease and does not fail over while we test 4-down degraded decode and 5-down UNAVAILABLE. */
    view(L, &v);
    int victims[20], nv = 0;
    for (int pass = 0; pass < 2 && nv < 5; pass++)
        for (uint32_t p = 0; p < e.nstripe && nv < 5; p++) {
            int i = server_of(e.stripe[p]);
            if (i < 0 || i == L || is_voter(&v, ids[i]))
                continue;
            if (ecb_is_rep(&e, i) != (pass == 1))
                continue;
            victims[nv++] = i;
        }
    view_free(&v);
    if (nv < 5)
        die("only %d non-voter stripe members besides L available to kill (want 5)", nv);
    for (int k = 0; k < 4; k++)
        stop(victims[k], SIGKILL);
    for (int s = 4; s < 16; s++) {
        struct ecb_sum a, b = twin[s];
        if ((rc = ecb_read(c, ide[s], &a)) != 0)
            die("read of series %d with four stripe members killed: %s", s, ers(rc));
        if (a.n != b.n || a.h != b.h)
            die("series %d with four stripe members away: %" PRIu64 " rows, the twin %" PRIu64, s, a.n, b.n);
    }
    printf("  four stripe members killed (servers %d %d %d %d): 12 unread series decode around all four, equal to twin\n",
           victims[0], victims[1], victims[2], victims[3]);
    stop(victims[4], SIGKILL);
    {
        int nun = 0;
        for (int s = 16; s < EC16_SERIES; s++) {
            struct ecb_sum a, b = twin[s];
            rc = ecb_read(c, ide[s], &a);
            if (rc == TSDB_ERR_UNAVAILABLE) {
                nun++;
                continue;
            }
            if (rc != 0 || a.n != b.n || a.h != b.h)
                die("series %d with five stripe members away: %s (%" PRIu64 " rows, the twin %" PRIu64
                    "), want UNAVAILABLE or the twin's rows", s, ers(rc), a.n, b.n);
        }
        if (nun == 0) {
            int nl = ecb_live_parts(L, num, live, sizeof live);
            die("series 16-%d with five stripe members away (servers %d %d %d %d %d): every one read whole, none "
                "UNAVAILABLE (%d .ec, %d .part:%s)", EC16_SERIES - 1, victims[0], victims[1], victims[2], victims[3],
                victims[4], ecb_ec_parts(L, num), nl, live);
        }
        printf("  five stripe members killed (+ server %d): UNAVAILABLE for %d of %d series, the rest whole\n",
               victims[4], nun, EC16_SERIES - 16);
    }
    start_many(victims, 5);
    for (int s = 16; s < EC16_SERIES; s++) {
        struct ecb_sum a, b = twin[s];
        for (uint64_t t0 = now_ms(); (rc = ecb_read(c, ide[s], &a)) != 0; usleep(200000))
            if (rc != TSDB_ERR_UNAVAILABLE || now_ms() - t0 > 60000)
                die("read of series %d after the restarts: %s", s, ers(rc));
        if (a.n != b.n || a.h != b.h)
            die("series %d after the restarts: %" PRIu64 " rows, the twin %" PRIu64, s, a.n, b.n);
    }
    printf("  all five stripe members back: reads whole and equal to twin\n");
    tsdbc_close(ct);
    tsdbc_close(c);
}

/* Count retired_*.ec files in server i's v<num>. */
static int ecb_retired_ec(int i, uint32_t num)
{
    char d[PATH_MAX + 80], p[PATH_MAX + 120];
    server_dir(i, d, sizeof d);
    snprintf(p, sizeof p, "%s/v%" PRIu32, d, num);
    DIR *dd = opendir(p);
    if (!dd)
        return 0;
    int n = 0;
    for (struct dirent *e; (e = readdir(dd));) {
        size_t l = strlen(e->d_name);
        n += l > 11 && strncmp(e->d_name, "retired_", 8) == 0 && strcmp(e->d_name + l - 3, ".ec") == 0;
    }
    closedir(dd);
    return n;
}

static void touch_file(const char *path)
{
    FILE *f = fopen(path, "w");
    if (!f)
        die("touch %s: %s", path, strerror(errno));
    fclose(f);
}

static int ecgc_leader_of(uint32_t num, int via, struct meta_volume *out)
{
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        if (vol_rec(via, "e42", out) && out->leader) {
            int s = server_of(out->leader);
            if (s >= 0 && pids[s] > 0 && !stopped[s]) {
                char lead[96];
                snprintf(lead, sizeof lead, "volume %" PRIu32 ": leads epoch %" PRIu64 " ", num, out->epoch);
                if (log_has(s, lead))
                    return s;
            }
        }
        if (now_ms() - t0 > 60000)
            die("no active leader of e42 (volume %" PRIu32 ") after 60 s", num);
    }
}

/* r8k-gc: cluster EC garbage collection via committed MK_GC (E14, §5.7, D13):
 * 1. Kill leader between puts and MK_COLD commit (marker in replica log -> chunks kept; no marker -> orphan swept).
 * 2. Failover after MK_GC commits and before CHUNK_DEL + replica whose TTL is behind lists .ec at MK_GC.
 * 3. SIGSTOP old leader past failover, SIGCONT: puts and deletes refused FENCED (r8f F4), chunks become orphans.
 * 4. force-leader suspends orphan GC until `tsdb cluster volume gc resume`. */
static void scen_ecgc(void)
{
    scenario("ecgc");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#endif
    static char trig_cold[PATH_MAX + 64], trig_midput[PATH_MAX + 64], trig_crashdel[PATH_MAX + 64],
        trig_pausedel[PATH_MAX + 64];
    snprintf(trig_cold, sizeof trig_cold, "%s/trig_cold", base);
    snprintf(trig_midput, sizeof trig_midput, "%s/trig_midput", base);
    snprintf(trig_crashdel, sizeof trig_crashdel, "%s/trig_crashdel", base);
    snprintf(trig_pausedel, sizeof trig_pausedel, "%s/trig_pausedel", base);

    static char penv_all[4 * PATH_MAX + 512];
    snprintf(penv_all, sizeof penv_all,
             "TSDB_REPLD_TEST=cutlinks,keepall "
             "TSDB_ECGC_TEST=orphan_grace_ms=1000,poll_ms=200,lifetime_s=1,crash_before_del=%s,pause_beforedel=%s "
             "TSDB_CHUNKPEER_TEST=pause_midput=%s TSDB_CRASH_AT=cold-after-marker:1@%s",
             trig_crashdel, trig_pausedel, trig_midput, trig_cold);

    for (int i = 0; i < 6; i++) {
        envs[i] = "copy_probe=1";
        penv[i] = penv_all;
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 6; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters of six members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    view_free(&v);

    static char xa[6][PATH_MAX + 256];
    for (int i = 0; i < 6; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/ecs%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i],
                 "--chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 --merge-idle-s 1 "
                 "--flush-interval-ms 200",
                 sd);
        restart_xargs(i, xa[i]);
    }
    await_view(5, p_six_placeable, NULL, "six members UP with their volumes open");

    uint32_t num = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ec=4+2 add: %s (%s)", cluster_strerror(rc), text);

    struct meta_volume e;
    int L = ecgc_leader_of(num, 0, &e);
    int reps[3], nreps = 0;
    for (uint32_t k = 0; k < e.nrep && nreps < 3; k++)
        reps[nreps++] = server_of(e.rep[k].node);
    if (nreps != 3)
        die("e42 has %d replicas, want 3", nreps);
    int nonrep = -1;
    for (int i = 0; i < 6; i++)
        if (!ecb_is_rep(&e, i)) {
            nonrep = i;
            break;
        }
    printf("  e42 (volume %" PRIu32 ") led by server %d (replicas %d,%d,%d)\n", num, L, reps[0], reps[1], reps[2]);

    tsdbc *c = client(L);
    tsdb_sid ide[ECB_SERIES];
    const int64_t day0 = 1704067200000LL; /* 2024-01-01 */
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecgc.s%d", s);
        ide[s] = ecb_series(c, nm, "e42");
    }

    /* ---- Case 1a: Kill leader right after MK_COLD append (before commit).
     * Replicas that received the marker keep its chunks (new leader commits it and serves all rows); if no replica
     * received it before the crash, the new leader sweeps its orphan chunks via committed MK_GC and still serves
     * every row from the young parts! Either way, all rows survive and no dangling orphan remains.
     * Hold settle at pause_midput during the initial day0 inserts so slow builds (TSan) never hit cold-after-marker
     * mid-insert before ecb_write_day finishes; then arm cold-after-marker and release pause_midput. */
    touch_file(trig_midput);
    ecb_write_day(c, ide, day0);
    tsdbc_close(c);
    c = NULL;
    touch_file(trig_cold);
    unlink(trig_midput);
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        int st = 0;
        if (waitpid(pids[L], &st, WNOHANG) == pids[L]) {
            pids[L] = 0;
            break;
        }
        if (now_ms() - t0 > 90000)
            die("leader %d did not hit cold-after-marker in 90 s", L);
    }
    unlink(trig_cold);
    int oldL = L;
    L = ecgc_leader_of(num, nonrep, &e);
    if (L == oldL)
        die("leader did not move after crash");
    start(oldL);
    c = client(L);
    for (int s = 0; s < ECB_SERIES; s++) {
        struct ecb_sum a;
        for (uint64_t t0 = now_ms(); (rc = ecb_read(c, ide[s], &a)) != 0; usleep(200000))
            if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 60000)
                die("read series %d after cold-after-marker failover: %s", s, ers(rc));
        if (a.n != 2 * ECB_ROWS)
            die("series %d after cold-after-marker failover: %" PRIu64 " rows, want %d", s, a.n, 2 * ECB_ROWS);
    }
    /* Wait until day0 is settled on the new leader and any orphan from the killed settle is swept. */
    for (uint64_t t0 = now_ms();; usleep(200000)) {
        int nec = ecb_ec_parts(L, num);
        int nch = ecb_chunks(num);
        if (nec > 0 && nch == nec * 6)
            break;
        if (now_ms() - t0 > 120000)
            die("day0 not settled cleanly on new leader %d within 120 s (%d .ec, %d chunks)", L, nec, nch);
    }
    printf("  case 1a (kill after MK_COLD append): new leader %d serves all rows (%d .ec, %d chunks)\n", L,
           ecb_ec_parts(L, num), ecb_chunks(num));

    /* ---- Case 1b: Kill leader mid-put (before MK_COLD is ever appended): orphan chunk swept by new leader via MK_GC. */
    int nec_before_1b = ecb_ec_parts(L, num);
    int ch_before_orph = ecb_chunks(num);
    int pm0 = log_count(L, "pause_midput: paused after position 0");
    touch_file(trig_midput);
    ecb_write_day(c, ide, day0 + 2 * 86400000LL);
    for (uint64_t t0 = now_ms(); log_count(L, "pause_midput: paused after position 0") <= pm0; usleep(100000))
        if (now_ms() - t0 > 90000)
            die("leader %d did not hit pause_midput in 90 s", L);
    if (ecb_chunks(num) <= ch_before_orph)
        die("expected orphan chunk after pos 0 put (before %d, now %d)", ch_before_orph, ecb_chunks(num));
    tsdbc_close(c);
    c = NULL;
    stop(L, SIGKILL);
    unlink(trig_midput);
    oldL = L;
    L = ecgc_leader_of(num, nonrep, &e);
    start(oldL);
    await_isr(L, "e42", 3, 60000, "all 3 replicas back in ISR");
    /* Wait for day0+2 to settle AND for the orphan chunk from oldL's killed put to be swept by MK_GC!
     * Each settled .ec part has 6 chunks. */
    for (uint64_t t0 = now_ms();; usleep(200000)) {
        int nec = ecb_ec_parts(L, num);
        int nch = ecb_chunks(num);
        if (nec > nec_before_1b && nch == nec * 6)
            break;
        if (now_ms() - t0 > 120000)
            die("orphan from killed mid-put not swept in 120 s (%d .ec parts, %d chunks)", nec, nch);
    }
    printf("  case 1b (kill mid-put before MK_COLD): new leader %d swept orphan via MK_GC (%d .ec, %d chunks)\n", L,
           ecb_ec_parts(L, num), ecb_chunks(num));

    /* ---- Case 2: Failover after MK_GC commits and before CHUNK_DEL + replica whose TTL is behind.
     * Pause one follower R3 so R3 still lists its .ec parts when MK_GC commits; arm crash_before_del on leader L;
     * expire all settled days by retention. L commits MK_GC{RETIRED} (ISR {L, R2}) and exits 99 before CHUNK_DEL.
     * R2 promotes, deletes all chunks from its durable GCMK list, and commits MK_GC{DONE}. Then L restarts and R3
     * resumes: R3 catches up, applies MK_GC while still listing .ec (retiring it first), and all retired_ names go. */
    int R2 = -1, R3 = -1;
    for (int k = 0; k < 3; k++)
        if (reps[k] != L)
            *(R2 < 0 ? &R2 : &R3) = reps[k];
    /* Ensure R3 lists the .ec parts before pausing it. */
    for (uint64_t t0 = now_ms(); ecb_ec_parts(R3, num) < 2; usleep(200000))
        if (now_ms() - t0 > 60000)
            die("replica %d has %d .ec parts, want >= 2", R3, ecb_ec_parts(R3, num));
    pause_server(R3, 1); /* R3's TTL cannot run: it keeps listing the .ec parts */
    touch_file(trig_crashdel);
    c = client(L);
    for (int s = 0; s < ECB_SERIES; s++)
        for (uint64_t t0 = now_ms(); (rc = tsdbc_set_retention(c, ide[s], 86400000LL)) != 0; usleep(50000))
            if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                die("set retention on series %d: %s", s, ers(rc));
    tsdbc_close(c);
    c = NULL;
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        int st = 0;
        if (waitpid(pids[L], &st, WNOHANG) == pids[L]) {
            pids[L] = 0;
            break;
        }
        if (now_ms() - t0 > 90000)
            die("leader %d did not hit crash_before_del after MK_GC commit in 90 s", L);
    }
    unlink(trig_crashdel);
    if (!log_has(L, "exiting before CHUNK_DEL"))
        die("leader %d exited without hitting crash_before_del", L);
    /* R2 promotes while oldL is dead and R3 is paused; chunks must still be present (oldL exited before CHUNK_DEL). */
    oldL = L;
    L = ecgc_leader_of(num, nonrep, &e);
    if (L != R2)
        die("expected R2 (%d) to promote while R3 (%d) paused, got %d", R2, R3, L);
    int ch_at_failover = ecb_chunks(num);
    if (ch_at_failover == 0)
        die("chunks already deleted before failover despite crash_before_del (gcuncommitted?)");
    /* Bring oldL and R3 back so all 6 stripe members are UP and ISR >= min_isr: R2 finishes CHUNK_DEL from its durable
     * GCMK list and commits MK_GC{DONE}; R3 catches up and applies MK_GC (retiring still-listed .ec if TTL lags). */
    start(oldL);
    pause_server(R3, 0);
    for (uint64_t t0 = now_ms(); ecb_chunks(num) != 0 || ecb_retired_ec(L, num) != 0 || ecb_ec_parts(R3, num) != 0 ||
                                 ecb_retired_ec(R3, num) != 0 || ecb_retired_ec(oldL, num) != 0;
         usleep(200000))
        if (now_ms() - t0 > 120000)
            die("promoted leader %d / replicas did not finish pending GCMK deletes in 120 s "
                "(%d chunks; L ret %d; R3 ec %d ret %d; oldL ret %d)",
                L, ecb_chunks(num), ecb_retired_ec(L, num), ecb_ec_parts(R3, num), ecb_retired_ec(R3, num),
                ecb_retired_ec(oldL, num));
    await_isr(L, "e42", 3, 60000, "all 3 replicas in ISR after case 2");
    printf("  case 2 (failover before CHUNK_DEL + TTL-behind replica): %d chunks at failover; promoted leader %d deleted "
           "all chunks; R3 still-listed retired=%d; all retired_ gone\n",
           ch_at_failover, L, log_has(R3, "retired still-listed .ec part") ? 1 : 0);
    fflush(stdout);

    /* ---- Case 3: SIGSTOP old leader past failover, SIGCONT -> puts refused FENCED (r8f F4), chunks become orphans.
     * Use fresh series with no retention so the new day settles cleanly. */
    tsdb_sid id2[ECB_SERIES];
    c = client(L);
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecgc.p%d", s);
        id2[s] = ecb_series(c, nm, "e42");
    }
    pm0 = log_count(L, "pause_midput: paused after position 0");
    touch_file(trig_midput);
    ecb_write_day(c, id2, day0 + 4 * 86400000LL);
    for (uint64_t t0 = now_ms(); log_count(L, "pause_midput: paused after position 0") <= pm0; usleep(100000))
        if (now_ms() - t0 > 90000)
            die("leader %d did not hit pause_midput for SIGSTOP case in 90 s", L);
    tsdbc_close(c);
    c = NULL;
    pause_server(L, 1); /* SIGSTOP old leader mid-settle! */
    unlink(trig_midput);
    oldL = L;
    L = ecgc_leader_of(num, nonrep, &e);
    if (L == oldL)
        die("leader did not move while oldL (%d) was SIGSTOPped", oldL);
    int fn0 = log_count(oldL, "fenced: below the member's epoch");
    pause_server(oldL, 0); /* SIGCONT old leader: its copy catches up to new epoch, yet its put uses old lead epoch! */
    for (uint64_t t0 = now_ms(); log_count(oldL, "fenced: below the member's epoch") <= fn0; usleep(200000))
        if (now_ms() - t0 > 60000)
            die("SIGCONTed old leader %d did not get FENCED on its resumed put (r8f F4)", oldL);
    await_isr(L, "e42", 3, 60000, "all 3 replicas in ISR after SIGCONT");
    /* New leader settles day0+4 (6 chunks) and sweeps oldL's pos-0 orphan chunk via MK_GC -> total chunks == nec * 6. */
    for (uint64_t t0 = now_ms();; usleep(200000)) {
        int nec = ecb_ec_parts(L, num);
        int nch = ecb_chunks(num);
        if (nec >= 1 && nch == nec * 6)
            break;
        if (now_ms() - t0 > 120000)
            die("orphan from SIGSTOPped leader not swept in 120 s (%d .ec, %d chunks)", nec, nch);
    }
    printf("  case 3a (SIGSTOP past failover + SIGCONT): old leader %d put refused FENCED (r8f F4), "
           "orphan swept by new leader %d\n",
           oldL, L);

    /* ---- Case 3b: SIGSTOP old leader right before CHUNK_DEL (pause_beforedel), failover, SIGCONT -> CHUNK_DEL
     * refused FENCED (r8f F4, "stopping GC on this deposed leader"), new leader finishes deleting from GCMK. */
    if (e.stripe[0] == ids[L]) {
        /* Ensure position 0 is a remote chunk store so the new leader raises its EPOCH before oldL resumes. */
        int target = reps[0] == L ? reps[1] : reps[0];
        uint8_t tbody[8], *treply = NULL;
        size_t trlen = 0, tblen = cluster_volume_force_encode(num, ids[target], tbody);
        for (uint64_t t0 = now_ms();
             (rc = admin(nonrep, CLUSTER_OP_VOLUME_TRANSFER, tbody, tblen, 1, &treply, &trlen)) != 0; usleep(200000)) {
            if ((rc != CLUSTER_ERR_STATE && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
                die("transfer e42 off stripe[0] (%d -> %d): %s (%.*s)", L, target, cluster_strerror(rc), (int)trlen,
                    treply ? (const char *)treply : "");
            free(treply);
            treply = NULL;
        }
        free(treply);
        for (uint64_t t0 = now_ms();; usleep(100000)) {
            L = ecgc_leader_of(num, nonrep, &e);
            if (L == target)
                break;
            if (now_ms() - t0 > 30000)
                die("transfer e42 to %d did not complete in 30 s (still %d)", target, L);
        }
    }
    tsdb_sid id3[ECB_SERIES];
    c = client(L);
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecgc.d%d", s);
        id3[s] = ecb_series(c, nm, "e42");
    }
    int nec_before_3b = ecb_ec_parts(L, num);
    ecb_write_day(c, id3, day0 + 30 * 86400000LL);
    for (uint64_t t0 = now_ms(); ecb_ec_parts(L, num) <= nec_before_3b; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("day0+30 did not settle on leader %d within 120 s", L);
    int pd0 = log_count(L, "paused before CHUNK_DEL (pause_beforedel)");
    touch_file(trig_pausedel);
    for (int s = 0; s < ECB_SERIES; s++)
        for (uint64_t t0 = now_ms(); (rc = tsdbc_set_retention(c, id3[s], 86400000LL)) != 0; usleep(50000))
            if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                die("set retention on id3 series %d: %s", s, ers(rc));
    tsdbc_close(c);
    c = NULL;
    for (uint64_t t0 = now_ms(); log_count(L, "paused before CHUNK_DEL (pause_beforedel)") <= pd0; usleep(100000))
        if (now_ms() - t0 > 90000)
            die("leader %d did not hit pause_beforedel in 90 s", L);
    pause_server(L, 1); /* SIGSTOP old leader right before CHUNK_DEL! */
    unlink(trig_pausedel);
    oldL = L;
    L = ecgc_leader_of(num, nonrep, &e);
    if (L == oldL)
        die("leader did not move while oldL (%d) was SIGSTOPped before CHUNK_DEL", oldL);
    int fd0 = log_count(oldL, "stopping GC on this deposed leader");
    pause_server(oldL, 0); /* SIGCONT old leader: resumed CHUNK_DEL uses old lead_epoch -> FENCED! */
    for (uint64_t t0 = now_ms(); log_count(oldL, "stopping GC on this deposed leader") <= fd0; usleep(200000))
        if (now_ms() - t0 > 60000)
            die("SIGCONTed old leader %d did not get FENCED on resumed CHUNK_DEL (r8f F4)", oldL);
    await_isr(L, "e42", 3, 60000, "all 3 replicas in ISR after SIGCONT (del)");
    for (uint64_t t0 = now_ms();; usleep(200000)) {
        int nec = ecb_ec_parts(L, num);
        int nch = ecb_chunks(num);
        if (nec == nec_before_3b && nch == nec * 6 && ecb_retired_ec(L, num) == 0 && ecb_retired_ec(oldL, num) == 0)
            break;
        if (now_ms() - t0 > 120000)
            die("new leader %d did not finish pending GCMK delete after case 3b (%d .ec, %d chunks, L ret %d, oldL ret %d)",
                L, nec, nch, ecb_retired_ec(L, num), ecb_retired_ec(oldL, num));
    }
    printf("  case 3b (SIGSTOP before CHUNK_DEL + SIGCONT): old leader %d delete refused FENCED (r8f F4), "
           "new leader %d drained GCMK\n",
           oldL, L);

    /* ---- Case 4: force-leader suspends orphan GC until `tsdb cluster volume gc resume`.
     * First leave a real orphan chunk on the stores (by pausing a new settle after pos 0 on L, cutting Cs off out of
     * ISR, killing L and B, then force-leader onto Cs!). */
    int Cs = -1, B = -1;
    for (int k = 0; k < 3; k++)
        if (reps[k] != L)
            *(Cs < 0 ? &Cs : &B) = reps[k];
    /* Cut Cs off and drop it from ISR (same as scen_ecadd), with a fresh settle creating an orphan on L before kill! */
    cut_file(L, Cs, 1);
    cut_file(Cs, L, 1);
    c = client(L);
    int64_t ts1 = day0 + 6 * 86400000LL;
    float v1 = 42.0f;
    if ((rc = tsdbc_insert_series(c, id2[0], &ts1, &v1, 1)) != 0)
        die("write after cutting Cs off: %s", ers(rc));
    await_isr(L, "e42", 2, 30000, "Cs out of e42's ISR");
    /* Make sure L has a fresh pause_midput (restart? No, L is the 3rd leader, never fired pause_midput yet; just in
     * case, check if L already fired it). */
    int ch_before_fl = ecb_chunks(num);
    pm0 = log_count(L, "pause_midput: paused after position 0");
    touch_file(trig_midput);
    ecb_write_day(c, id2, day0 + 8 * 86400000LL);
    for (uint64_t t0 = now_ms(); log_count(L, "pause_midput: paused after position 0") <= pm0; usleep(100000))
        if (now_ms() - t0 > 90000)
            die("leader %d did not hit pause_midput before force-leader in 90 s", L);
    tsdbc_close(c);
    c = NULL;
    int ch_with_orph = ecb_chunks(num);
    if (ch_with_orph <= ch_before_fl)
        die("expected orphan chunk before force-leader (before %d, now %d)", ch_before_fl, ch_with_orph);
    uint64_t e0 = e.epoch;
    uint32_t old_id = e.leader;
    stop(L, SIGKILL);
    stop(B, SIGKILL);
    unlink(trig_midput);
    for (uint64_t t0 = now_ms();; usleep(50000)) {
        view(nonrep, &v);
        int ok = v.st.leader && v.st.leader != ids[L] && v.st.leader != ids[B];
        view_free(&v);
        if (ok)
            break;
        if (now_ms() - t0 > 30000)
            die("metadata leader did not move off killed servers");
    }
    uint8_t req[8], *reply = NULL;
    size_t rlen = 0, rl = cluster_volume_force_encode(num, ids[Cs], req);
    for (uint64_t t0 = now_ms(); (rc = admin(nonrep, CLUSTER_OP_VOLUME_FORCE, req, rl, 1, &reply, &rlen)) != 0;
         usleep(200000)) {
        if (rc != CLUSTER_ERR_STATE || now_ms() - t0 > 30000)
            die("force-leader of e42 to %d: %s (%.*s)", Cs, cluster_strerror(rc), (int)rlen,
                reply ? (const char *)reply : "");
        free(reply);
        reply = NULL;
    }
    free(reply);
    struct meta_volume f;
    if (await_promoted(nonrep, "e42", old_id, e0, &f) != Cs || !f.gc_suspended)
        die("after force-leader: leader %u (want %u), gc_suspended %u", f.leader, ids[Cs], f.gc_suspended);
    /* Restart L and B (clear cuts): they diverged from Cs (a cut below applied); wait for ISR={Cs}, then reset both
     * diverged replicas so they rebuild from Cs and restore ISR=3 (>= min_isr=2). Then all 6 stripe members are UP
     * and writes commit, so orphan GC WOULD run if gc_suspended=1 were not honoured! */
    cut_file(L, Cs, 0);
    cut_file(Cs, L, 0);
    start(L);
    start(B);
    await_isr(nonrep, "e42", 1, 30000, "ISR shrunk to Cs after force-leader");
    char args[PATH_MAX * 2 + 128], out[16384], paddr[META_ADDR_MAX + 1];
    peer_of(nonrep, paddr, sizeof paddr);
    for (int k = 0; k < 2; k++) {
        int who = k ? B : L;
        snprintf(args, sizeof args, "cluster replica reset %s %" PRIu32 " %" PRIu32 " --secret-file %s", paddr, num,
                 ids[who], secret_path);
        if (cli_run(args, NULL, out, sizeof out) != 0)
            die("tsdb %s: %s", args, out);
    }
    await_isr(nonrep, "e42", 3, 90000, "all 3 replicas in ISR after replica reset");
    /* Wait well past orphan_grace_ms (1000 ms) + several poll intervals: orphan chunk MUST stay while suspended! */
    usleep(3500000);
    int ch_susp = ecb_chunks(num), nec_susp = ecb_ec_parts(Cs, num);
    if (ch_susp <= nec_susp * 6)
        die("orphan chunk deleted while gc_suspended=1 (%d .ec, %d chunks; gcsuspendignored!)", nec_susp, ch_susp);
    printf("  case 4a (force-leader gc_suspended=1): orphan chunk kept (%d .ec, %d chunks)\n", nec_susp, ch_susp);
    fflush(stdout);
    /* Resume orphan GC via CLI: orphan chunk MUST now be collected via committed MK_GC! */
    snprintf(args, sizeof args, "cluster volume gc resume %s e42 --secret-file %s", paddr, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "orphan collection resumed"))
        die("tsdb %s: %s", args, out);
    for (uint64_t t0 = now_ms();; usleep(200000)) {
        int nec = ecb_ec_parts(Cs, num);
        int nch = ecb_chunks(num);
        if (nch == nec * 6)
            break;
        if (now_ms() - t0 > 90000)
            die("orphan chunk not swept after gc resume (%d .ec, %d chunks)", nec, nch);
    }
    printf("  case 4b (gc resume): orphan chunk swept via MK_GC (%d .ec, %d chunks)\n", ecb_ec_parts(Cs, num),
           ecb_chunks(num));
}

#ifdef TSDB_EC
static int ecd_chunks_of(int srv, uint32_t num)
{
    char p[PATH_MAX + 80];
    snprintf(p, sizeof p, "%s/ecs%d/s%" PRIu32, base, srv, num);
    DIR *dd = opendir(p);
    if (!dd)
        return 0;
    int n = 0;
    for (struct dirent *e; (e = readdir(dd));) {
        size_t l = strlen(e->d_name);
        n += e->d_name[0] == 'o' && l > 6 && !strcmp(e->d_name + l - 6, ".chunk");
    }
    closedir(dd);
    return n;
}

static uint16_t ecd_le16(const uint8_t *b) { return (uint16_t)(b[0] | ((uint16_t)b[1] << 8)); }
static uint32_t ecd_le32(const uint8_t *b)
{
    return (uint32_t)b[0] | ((uint32_t)b[1] << 8) | ((uint32_t)b[2] << 16) | ((uint32_t)b[3] << 24);
}
static uint64_t ecd_le64(const uint8_t *b)
{
    uint64_t v = 0;
    for (int i = 7; i >= 0; i--)
        v = (v << 8) | b[i];
    return v;
}

/* Inspect every live .ec file in server `srv`'s v<num>: checks k, m and exact `want_pos` bitmap in ec_record. */
static int ecd_check_ec_positions(int srv, uint32_t num, uint16_t want_k, uint16_t want_m, uint32_t want_pos)
{
    char d[PATH_MAX + 80], dirp[PATH_MAX + 120];
    server_dir(srv, d, sizeof d);
    snprintf(dirp, sizeof dirp, "%s/v%" PRIu32, d, num);
    DIR *dd = opendir(dirp);
    if (!dd)
        die("opendir %s: %s", dirp, strerror(errno));
    int count = 0;
    for (struct dirent *de; (de = readdir(dd));) {
        size_t l = strlen(de->d_name);
        if (l <= 3 || strcmp(de->d_name + l - 3, ".ec") != 0 || strncmp(de->d_name, "retired_", 8) == 0)
            continue;
        char fp[PATH_MAX + 256];
        snprintf(fp, sizeof fp, "%s/%s", dirp, de->d_name);
        int fd = open(fp, O_RDONLY | O_CLOEXEC);
        if (fd < 0)
            die("open %s: %s", fp, strerror(errno));
        struct stat st;
        if (fstat(fd, &st) != 0 || st.st_size < 64 + 216)
            die("%s: short .ec file (%lld)", fp, (long long)st.st_size);
        uint8_t tr[64], rhdr[64];
        if (pread(fd, tr, 64, st.st_size - 64) != 64 || memcmp(tr, "TSDB-EC\n", 8) != 0)
            die("%s: bad .ec trailer", fp);
        uint64_t roff = ecd_le64(tr + 16), rlen = ecd_le64(tr + 24);
        if (rlen < 216 || roff + rlen + 64 != (uint64_t)st.st_size)
            die("%s: bad record offset/len", fp);
        if (pread(fd, rhdr, 64, (off_t)roff) != 64)
            die("%s: short record read", fp);
        close(fd);
        uint16_t k = ecd_le16(rhdr + 52), m = ecd_le16(rhdr + 54);
        uint32_t pos = ecd_le32(rhdr + 60);
        if (k != want_k || m != want_m)
            die("%s: geometry %u+%u, want %u+%u", fp, k, m, want_k, want_m);
        if (pos != want_pos)
            die("%s: record positions 0x%x (popcount %d), want 0x%x (degnopositions?)", fp, pos,
                __builtin_popcount(pos), want_pos);
        count++;
    }
    closedir(dd);
    return count;
}
#endif

/* ecdegraded (r9-degsettle, E10): 4+2 on 7 nodes with ec.settle_wait_max_s = 5 s.
 * 1. SIGSTOP 1 stripe holder -> day settles degraded after 5 s with 5 positions (verified in .ec record + store chunks +
 *    reconcile_note_missing log + replica apply); reads equal oracle.
 * 2. SIGSTOP a 2nd holder -> reads still answer from the 4 written positions (k = 4).
 * 3. SIGSTOP a 3rd holder -> UNAVAILABLE, never CORRUPT.
 * 4. SIGCONT all 3 -> whole answers (known-erasure position never causes CORRUPT).
 * 5. SIGSTOP 2 holders -> a new day does NOT settle past 5 s (kills degtwo).
 * 6. Pre-MK_COLD UP check: pause_pre_marker hook + SIGSTOP a written holder before MK_COLD -> aborts (kills degnoupcheck). */
static int ecd_committed_ec_parts(int i, uint32_t num)
{
    char d[PATH_MAX + 80], p[PATH_MAX + 120];
    server_dir(i, d, sizeof d);
    snprintf(p, sizeof p, "%s/v%" PRIu32, d, num);
    DIR *dd = opendir(p);
    if (!dd)
        return 0;
    int n = 0;
    for (struct dirent *e; (e = readdir(dd));) {
        size_t l = strlen(e->d_name);
        n += l > 4 && e->d_name[0] == 'p' && !strcmp(e->d_name + l - 3, ".ec");
    }
    closedir(dd);
    return n;
}

static void scen_ecdegraded(void)
{
    scenario("ecdegraded");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#else
    epoll_after_two = 1;
    static char pmenv[PATH_MAX + 256], pmpath[PATH_MAX + 96];
    snprintf(pmpath, sizeof pmpath, "%s/pause_pre_marker", base);
    snprintf(pmenv, sizeof pmenv, "TSDB_ECCOLD_TEST=pause_pre_marker=%s", pmpath);
    for (int i = 0; i < 7; i++) {
        penv[i] = pmenv;
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 7; i++)
        node_add(0, i);
    unsigned want_v = 5;
    await_view(0, p_voters, &want_v, "five voters of seven members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    int voter_srv[7] = {0};
    for (int i = 0; i < 7; i++)
        voter_srv[i] = is_voter(&v, ids[i]) != 0;
    view_free(&v);

    static char xa[7][PATH_MAX + 256];
    for (int i = 0; i < 7; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/ecs%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i],
                 "--chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 --ec-settle-wait-max-s 5 "
                 "--merge-idle-s 1 --flush-interval-ms 200 --ec-cache-mb 16", sd);
        restart_xargs(i, xa[i]);
    }
    unsigned seven = 7;
    await_view(6, p_n_placeable, &seven, "seven members UP with their volumes open");

    uint32_t num = 0, tnum = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ec=4+2 on 7 nodes: %s (%s)", cluster_strerror(rc), text);
    for (uint64_t t0 = now_ms(); (rc = vol_add(0, "t42", 3, &tnum)) != 0; usleep(100000))
        if (rc != CLUSTER_ERR_NOTLEADER || now_ms() - t0 > 30000)
            die("twin t42: %s", cluster_strerror(rc));

    struct meta_volume e, tv;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("e42 has no leader 30 s after add");
    for (uint64_t t0 = now_ms(); !vol_rec(0, "t42", &tv) || !tv.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("t42 has no leader 30 s after add");
    int L = server_of(e.leader), Lt = server_of(tv.leader);
    if (L < 0 || Lt < 0)
        die("bad leader index L=%d Lt=%d", L, Lt);

    /* Ensure at least one non-voter in e42's stripe is not L (so stopping 3 stripe members leaves >= 3 voters UP). */
    int nv_in_stripe = 0;
    for (uint32_t p = 0; p < e.nstripe; p++) {
        int s = server_of(e.stripe[p]);
        if (s >= 0 && !voter_srv[s] && s != L)
            nv_in_stripe++;
    }
    if (nv_in_stripe == 0 && !voter_srv[L]) {
        int tgt = -1;
        for (uint32_t k = 0; k < e.nrep && tgt < 0; k++) {
            int s = server_of(e.rep[k].node);
            if (s >= 0 && s != L && voter_srv[s])
                tgt = s;
        }
        if (tgt >= 0) {
            char why[256];
            for (uint64_t t0 = now_ms(); (rc = tr_transfer(num, ids[tgt], why, sizeof why)) != 0; usleep(200000))
                if (now_ms() - t0 > 30000)
                    die("transfer e42 to voter %d: %s (%s)", tgt, cluster_strerror(rc), why);
            for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e) || server_of(e.leader) != tgt; usleep(50000))
                if (now_ms() - t0 > 30000)
                    die("e42 did not move to voter %d", tgt);
            L = tgt;
        }
    }
    char lead_line[96];
    snprintf(lead_line, sizeof lead_line, "volume %" PRIu32 ": leads epoch %" PRIu64 " ", num, e.epoch);
    for (uint64_t t0 = now_ms(); !log_has(L, lead_line); usleep(50000))
        if (now_ms() - t0 > 30000)
            die("leader %d did not log %s", L, lead_line);
    await_isr(L, "e42", 3, 30000, "e42 full ISR before degraded settle");

    /* Write day 0 to oracle twin t42 and compute oracle hashes while all 7 nodes are UP. */
    const int64_t day0 = 1704067200000LL;
    tsdbc *ct = client(Lt);
    tsdb_sid idt[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecd.s%d", s);
        idt[s] = ecb_series(ct, nm, "t42");
    }
    ecb_write_day(ct, idt, day0);
    struct ecb_sum twin[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++)
        if ((rc = ecb_read(ct, idt[s], &twin[s])) != 0 || twin[s].n != 2 * ECB_ROWS)
            die("oracle read series %d: %s (%" PRIu64 " rows)", s, ers(rc), twin[s].n);
    tsdbc_close(ct);

    /* Pick 3 stripe victims (v0, v1, v2) at positions (p0, p1, p2): none is L or ml; v0 and v1 are not log replicas
     * of e42 (so e42 keeps full 3/3 ISR during writes!); and at least 1 of {v0, v1, v2} is a non-voter (so Raft keeps
     * >= 3 of 5 voters UP even with all 3 stopped!). */
    int ml = leader_of(L);
    int victims[3] = {-1, -1, -1};
    unsigned vpos[3] = {0, 0, 0};
    int nv = 0;
    for (int pass = 0; pass < 4 && nv < 3; pass++) {
        for (uint32_t p = 0; p < e.nstripe && nv < 3; p++) {
            int s = server_of(e.stripe[p]);
            if (s < 0 || s == L || s == ml)
                continue;
            int already = 0;
            for (int j = 0; j < nv; j++)
                already |= victims[j] == s;
            if (already)
                continue;
            bool rep = ecb_is_rep(&e, s);
            bool vot = voter_srv[s] != 0;
            bool match = (pass == 0 && !rep && !vot) || (pass == 1 && !rep && vot) ||
                         (pass == 2 && rep && !vot) || (pass == 3 && rep && vot);
            if (!match)
                continue;
            /* Ensure the 3rd victim includes a non-voter if the first two were both voters */
            if (nv == 2 && voter_srv[victims[0]] && voter_srv[victims[1]] && vot)
                continue;
            victims[nv] = s;
            vpos[nv] = p;
            nv++;
        }
    }
    if (nv < 3 || ecb_is_rep(&e, victims[0]) || ecb_is_rep(&e, victims[1]))
        die("could not pick 3 stripe victims (nv=%d, v0=%d rep=%d, v1=%d rep=%d)", nv, victims[0],
            victims[0] >= 0 ? ecb_is_rep(&e, victims[0]) : -1, victims[1],
            victims[1] >= 0 ? ecb_is_rep(&e, victims[1]) : -1);
    printf("  e42 (vol %" PRIu32 ") led by %d (ml=%d); victims: srv %d (pos %u), srv %d (pos %u), srv %d (pos %u)\n",
           num, L, ml, victims[0], vpos[0], victims[1], vpos[1], victims[2], vpos[2]);

    /* ---- Phase 1: SIGSTOP 1 stripe holder (v0, pos p0) -> key settles degraded after 5 s with 5 positions ---- */
    tsdbc *c = client(L);
    tsdb_sid ide[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecd.s%d", s);
        ide[s] = ecb_series(c, nm, "e42");
    }
    pause_server(victims[0], 1);
    ecb_write_day(c, ide, day0);
    uint64_t t_wait = now_ms();
    int nec = 0;
    for (uint64_t t0 = now_ms(); (nec = ecb_ec_parts(L, num)) == 0; usleep(200000))
        if (now_ms() - t0 > 90000)
            die("e42 did not settle degraded with 1 holder stopped in 90 s");
    uint64_t settled_ms = now_ms() - t_wait;
    char live[1024];
    int nlive = 0;
    for (uint64_t t0 = now_ms(); (nlive = ecb_live_parts(L, num, live, sizeof live)) != 0; usleep(200000))
        if (now_ms() - t0 > 90000)
            die("%d .part file(s) left in leader v%" PRIu32 " after degraded settle:%s", nlive, num, live);
    nec = ecb_ec_parts(L, num);
    if (settled_ms < 3500)
        die("degraded settle completed too quickly (%" PRIu64 " ms < 3500 ms; ec.settle_wait_max_s = 5)", settled_ms);
    int total_ch = ecb_chunks_n(num, 7);
    int v0_ch = ecd_chunks_of(victims[0], num);
    if (total_ch != nec * 5 || v0_ch != 0)
        die("degraded settle wrote %d chunks (want %d = %d * 5), stopped holder %d has %d chunks", total_ch, nec * 5,
            nec, victims[0], v0_ch);
    uint32_t want_pos = 0x3fu & ~(1u << vpos[0]);
    int checked = ecd_check_ec_positions(L, num, 4, 2, want_pos);
    if (checked != nec)
        die("checked %d .ec files on leader, expected %d", checked, nec);
    if (!log_has(L, "reconcile noted missing position"))
        die("leader %d did not log sreconcile_note_missing after degraded settle", L);
    /* Verify a follower replica also applied the degraded .ec record with identical positions bitmap */
    int frep = -1;
    for (uint32_t k = 0; k < e.nrep && frep < 0; k++) {
        int s = server_of(e.rep[k].node);
        if (s >= 0 && s != L)
            frep = s;
    }
    if (frep >= 0) {
        for (uint64_t t0 = now_ms(); ecb_ec_parts(frep, num) < nec; usleep(200000))
            if (now_ms() - t0 > 30000)
                die("follower %d has %d .ec parts, leader has %d", frep, ecb_ec_parts(frep, num), nec);
        ecd_check_ec_positions(frep, num, 4, 2, want_pos);
    }
    for (int s = 0; s < 2; s++) {
        struct ecb_sum a;
        if ((rc = ecb_read(c, ide[s], &a)) != 0 || a.n != twin[s].n || a.h != twin[s].h)
            die("phase 1 read series %d: %s (%" PRIu64 " vs %" PRIu64 ")", s, ers(rc), a.n, twin[s].n);
    }
    printf("  phase 1: settled degraded in %" PRIu64 " ms (%d .ec, %d chunks = 5/obj, positions 0x%x); reads == oracle\n",
           settled_ms, nec, total_ch, want_pos);

    /* ---- Phase 2: SIGSTOP 2nd holder (v1) -> reads still answer from 4 written positions (k = 4) ---- */
    pause_server(victims[1], 1);
    for (int s = 2; s < 4; s++) {
        struct ecb_sum a;
        if ((rc = ecb_read(c, ide[s], &a)) != 0 || a.n != twin[s].n || a.h != twin[s].h)
            die("phase 2 read series %d with 2 holders stopped: %s (%" PRIu64 " vs %" PRIu64 ")", s, ers(rc), a.n,
                twin[s].n);
    }
    printf("  phase 2: 2nd holder (srv %d) SIGSTOPped: reads decoded from 4 written positions == oracle\n", victims[1]);

    /* ---- Phase 3: SIGSTOP 3rd holder (v2) -> UNAVAILABLE, never CORRUPT ---- */
    pause_server(victims[2], 1);
    int nun = 0;
    for (int s = 4; s < ECB_SERIES; s++) {
        struct ecb_sum a;
        rc = ecb_read(c, ide[s], &a);
        if (rc == TSDB_ERR_UNAVAILABLE) {
            nun++;
            continue;
        }
        if (rc != 0 || a.n != twin[s].n || a.h != twin[s].h)
            die("phase 3 read series %d with 3 holders stopped: %s (want UNAVAILABLE or oracle, never CORRUPT)", s,
                ers(rc));
    }
    if (nun == 0)
        die("phase 3: 0 series returned UNAVAILABLE with 3 stripe holders stopped");
    if (log_has(L, "not readable") || log_has(L, "its object lost more chunks") || log_has(L, "fail its checksum"))
        die("phase 3: leader %d logged corruption with 3 holders stopped", L);
    printf("  phase 3: 3rd holder (srv %d) SIGSTOPped: %d/%d series UNAVAILABLE, zero CORRUPT\n", victims[2], nun,
           ECB_SERIES - 4);

    /* ---- Phase 4: SIGCONT all 3 -> whole answers (known-erasure holder UP with 0 chunks never causes CORRUPT) ---- */
    pause_server(victims[0], 0);
    pause_server(victims[1], 0);
    pause_server(victims[2], 0);
    for (int s = 0; s < ECB_SERIES; s++) {
        struct ecb_sum a;
        for (uint64_t t0 = now_ms(); (rc = ecb_read(c, ide[s], &a)) != 0; usleep(200000))
            if (rc != TSDB_ERR_UNAVAILABLE || now_ms() - t0 > 60000)
                die("phase 4 read series %d after SIGCONT: %s", s, ers(rc));
        if (a.n != twin[s].n || a.h != twin[s].h)
            die("phase 4 series %d after SIGCONT: %" PRIu64 " vs %" PRIu64, s, a.n, twin[s].n);
    }
    if (log_has(L, "not readable") || log_has(L, "its object lost more chunks") || log_has(L, "fail its checksum"))
        die("phase 4: leader %d logged corruption after SIGCONT", L);
    printf("  phase 4: SIGCONT all 3: all %d series read whole == oracle\n", ECB_SERIES);

    /* ---- Phase 5: 2 holders stopped (v0 + v1) must NOT settle past wait_max_s = 5 s (kills degtwo) ---- */
    int nec_before = ecd_committed_ec_parts(L, num);
    pause_server(victims[0], 1);
    pause_server(victims[1], 1);
    ecb_write_day(c, ide, day0 + 2 * 86400000LL);
    usleep(9000000); /* 1 s merge + > 5 s wait_max_s */
    int nec_after2 = ecd_committed_ec_parts(L, num);
    if (nec_after2 != nec_before)
        die("phase 5: settled with 2 stripe holders stopped (%d -> %d .ec parts; degtwo!)", nec_before, nec_after2);
    if (!log_has(L, "at most 1 may be down for a degraded settle"))
        die("phase 5: leader %d did not log the 2-down refusal line", L);
    printf("  phase 5: 2 holders stopped: did not settle past wait_max_s (stayed %d .ec parts)\n", nec_before);

    /* ---- Phase 6: Pre-MK_COLD UP check (kills degnoupcheck) ----
     * Resume v1 (leaving only v0 stopped), arm pause_pre_marker so the leader pauses right after putting 5 chunks
     * and indexing .ec, then SIGSTOP written holder v1 and resume -> pre-MK_COLD check must abort without MK_COLD! */
    FILE *pf = fopen(pmpath, "w");
    if (!pf)
        die("fopen %s: %s", pmpath, strerror(errno));
    fclose(pf);
    int pm0 = log_count(L, "pause_pre_marker: paused before MK_COLD");
    pause_server(victims[1], 0);
    for (uint64_t t0 = now_ms(); log_count(L, "pause_pre_marker: paused before MK_COLD") <= pm0; usleep(100000))
        if (now_ms() - t0 > 90000)
            die("phase 6: leader %d did not reach pause_pre_marker within 90 s", L);
    pause_server(victims[1], 1); /* drop written holder v1 right before MK_COLD! */
    int res0 = log_count(L, "pause_pre_marker: resumed before MK_COLD");
    int ab0 = log_count(L, "dropped before MK_COLD: aborting");
    unlink(pmpath);
    for (uint64_t t0 = now_ms(); log_count(L, "pause_pre_marker: resumed before MK_COLD") <= res0; usleep(100000))
        if (now_ms() - t0 > 30000)
            die("phase 6: leader %d did not resume from pause_pre_marker within 30 s", L);
    for (uint64_t t0 = now_ms(); log_count(L, "dropped before MK_COLD: aborting") <= ab0; usleep(100000)) {
        int nec_now = ecd_committed_ec_parts(L, num);
        if (nec_now != nec_before)
            die("phase 6: MK_COLD committed after written holder %d dropped before marker (%d -> %d .ec; degnoupcheck!)",
                victims[1], nec_before, nec_now);
        if (now_ms() - t0 > 30000)
            die("phase 6: leader %d neither aborted nor committed within 30 s after pause_pre_marker resume", L);
    }
    int nec_after6 = ecd_committed_ec_parts(L, num);
    if (nec_after6 != nec_before)
        die("phase 6: MK_COLD committed after written holder %d dropped before marker (%d -> %d .ec; degnoupcheck!)",
            victims[1], nec_before, nec_after6);
    printf("  phase 6: written holder dropped before MK_COLD: pre-marker UP check aborted cleanly\n");

    pause_server(victims[0], 0);
    pause_server(victims[1], 0);
    tsdbc_close(c);
#endif
}

static void scen_ecadd(void)
{
    scenario("ecadd");
    for (int i = 0; i < 6; i++) {
        penv[i] = "TSDB_REPLD_TEST=cutlinks";
        envs[i] = "copy_probe=1";
    }
    for (int i = 0; i < 6; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 6; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters of six members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    view_free(&v);
    static char xa[6][PATH_MAX + 32];
    for (int i = 0; i < 5; i++)
        restart_with_store(i, uuid, xa[i], sizeof xa[i]);
    uint32_t num = 0;
    char text[256];
    int rc;
    await_ec_five("e42");
    for (uint64_t t0 = now_ms();
         (rc = vol_add_ec(0, "e42", 2, 4, 2, &num, text, sizeof text)) == CLUSTER_ERR_NOTLEADER && now_ms() - t0 < 30000;
         usleep(100000))
        ;
    if (rc != META_ERR_INVALID ||
        !strstr(text, "has 3 replicas (m + 1), not 2"))
        die("ec=4+2 with 2 replicas: %s (%s), not refused", cluster_strerror(rc), text);
    printf("  ec=4+2 with two replicas: refused (%s)\n", text);
    { /* k and m in a plain VOLUME_ADD (what a server before VOLUME_ADD_EC would have read as a replicas volume) */
        uint8_t req[2 + META_NAME_MAX + 6], *reply = NULL;
        size_t len = 0, rl = cluster_volume_add_ec_encode("e42", 0, 4, 2, req);
        struct meta_volume none;
        for (uint64_t t0 = now_ms();
             (rc = admin(0, CLUSTER_OP_VOLUME_ADD, req, rl, 1, &reply, &len)) == CLUSTER_ERR_NOTLEADER &&
             now_ms() - t0 < 30000;
             usleep(100000)) {
            free(reply);
            reply = NULL;
        }
        if (rc != META_ERR_INVALID || vol_rec(0, "e42", &none))
            die("a VOLUME_ADD carrying k and m: %s, not refused", cluster_strerror(rc));
        free(reply);
    }
    restart_with_store(5, uuid, xa[5], sizeof xa[5]);
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ec=4+2 with six stores: %s (%s)", cluster_strerror(rc), text);
    struct meta_volume e;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e); usleep(50000)) /* answered once committed, not applied here */
        if (now_ms() - t0 > 30000)
            die("no record of e42 in server 0's copy 30 s after the add");
    if (e.redundancy != META_RED_EC || e.ec_k != 4 || e.ec_m != 2 || e.nstripe != 6 || e.nrep != 3 ||
        e.min_isr != 2 || e.stripe_version != 1 || e.gc_suspended)
        die("e42: redundancy %u k %u m %u nstripe %" PRIu32 " replicas %" PRIu32 " min_isr %" PRIu32
            " stripe_version %" PRIu64 " gc_suspended %u", e.redundancy, e.ec_k, e.ec_m, e.nstripe, e.nrep,
            e.min_isr, e.stripe_version, e.gc_suspended);
    for (int a = 0; a < 6; a++) {
        if (server_of(e.stripe[a]) < 0)
            die("e42's stripe position %d is node %" PRIu32 ", no server of the test", a, e.stripe[a]);
        for (int b = 0; b < a; b++)
            if (e.stripe[a] == e.stripe[b])
                die("e42's stripe names node %" PRIu32 " twice", e.stripe[a]);
    }
    await_same_stripe("e42", &e, "after the add");
    /* a member whose store is gone (restarted without it): its heartbeats say so, and the next group cannot have it */
    restart_xargs(5, NULL);
    await_ec_five("e43");
    restart_xargs(5, xa[5]);
    int L = -1;
    for (int i = 0; i < 6 && L < 0; i++) {
        view(i, &v);
        if (v.st.mode == CLUSTER_MODE_CORE && v.st.role == RAFT_LEADER)
            L = i;
        view_free(&v);
    }
    if (L < 0)
        die("no leader of the metadata group");
    stop(L, SIGTERM);
    start(L);
    await_same_stripe("e42", &e, "after the metadata leader's restart");
    printf("  ec=4+2 on six stores: stripe %u,%u,%u,%u,%u,%u, 3 replicas, min_isr 2; the same on every server, also "
           "after server %d (the metadata leader) restarted\n", e.stripe[0], e.stripe[1], e.stripe[2], e.stripe[3],
           e.stripe[4], e.stripe[5], L);

    /* force-leader of e42 (noowner's way): one replica cut off and out of the ISR, then the other two killed */
    int Lm = -1;
    for (uint64_t t0 = now_ms(); Lm < 0; usleep(50000)) {
        for (int i = 0; i < 6 && Lm < 0; i++) {
            view(i, &v);
            if (v.st.mode == CLUSTER_MODE_CORE && v.st.role == RAFT_LEADER && v.m.initialised)
                Lm = i;
            view_free(&v);
        }
        if (Lm < 0 && now_ms() - t0 > 30000)
            die("no leader of the metadata group 30 s after server %d restarted", L);
    }
    struct meta_volume f;
    if (!vol_rec(Lm, "e42", &f))
        die("no record of e42");
    int Lv = server_of(f.leader), Cs = -1, B = -1;
    for (uint32_t k = 0; k < f.nrep; k++)
        if (f.rep[k].node != f.leader)
            *(Cs < 0 ? &Cs : &B) = server_of(f.rep[k].node);
    if (Lv < 0 || Cs < 0 || B < 0)
        die("e42: leader %u", f.leader);
    /* the server restarted above holds a replica of e42 too: right after the add the record's ISR still names all
     * three while the leader may already have asked to drop that one until it catches up (seen in a NO_EC run: the
     * write after the cut then met an ISR of one). So a row first, held by both other replicas, then the ISR. */
    tsdbc *c = client(Lv);
    tsdb_sid sid = rep_series(c, rep_names[0], "e42", 30000);
    int64_t ts = 999000;
    float val = 0;
    if ((rc = tsdbc_insert_series(c, sid, &ts, &val, 1)) != 0)
        die("a write to e42 with every replica up: %s", ers(rc));
    for (uint64_t t1 = now_ms(); rows_in(Cs, sid, ts, ts + 1, 30000) != 1 || rows_in(B, sid, ts, ts + 1, 30000) != 1;
         usleep(50000))
        if (now_ms() - t1 > 30000)
            die("servers %d and %d do not both hold the row written to e42 with every replica up", Cs, B);
    await_isr(Lv, "e42", 3, 30000, "every replica of e42 in the ISR");
    /* the leader drops a replica from the ISR once a record it sent goes unanswered: a write after the cut */
    cut_file(Lv, Cs, 1);
    cut_file(Cs, Lv, 1);
    ts = 1000000;
    val = 1;
    if ((rc = tsdbc_insert_series(c, sid, &ts, &val, 1)) != 0)
        die("a write to e42 with a replica cut off: %s", ers(rc));
    tsdbc_close(c);
    await_isr(Lv, "e42", 2, 30000, "the cut replica out of e42's ISR");
    int via = -1;
    for (int i = 0; i < 6 && via < 0; i++)
        if (i != Lv && i != B && i != Cs)
            via = i;
    if (!vol_rec(via, "e42", &f))
        die("no record of e42");
    uint64_t e0 = f.epoch;
    uint32_t old = f.leader;
    stop(Lv, SIGKILL);
    stop(B, SIGKILL);
    for (uint64_t t0 = now_ms();; usleep(50000)) { /* the admin op follows NOTLEADER once: not to a killed server */
        view(via, &v);
        int ok = v.st.leader && v.st.leader != ids[Lv] && v.st.leader != ids[B];
        view_free(&v);
        if (ok)
            break;
        if (now_ms() - t0 > 30000)
            die("the metadata group has no leader but a killed server 30 s on");
    }
    uint8_t req[8], *reply = NULL;
    size_t len = 0, rl = cluster_volume_force_encode(num, ids[Cs], req);
    for (uint64_t t0 = now_ms(); (rc = admin(via, CLUSTER_OP_VOLUME_FORCE, req, rl, 1, &reply, &len)) != 0;
         usleep(200000)) { /* refused while the group still has the killed leader UP */
        if (rc != CLUSTER_ERR_STATE || now_ms() - t0 > 30000)
            die("force-leader of e42 to server %d: %s (%.*s)", Cs, cluster_strerror(rc), (int)len,
                reply ? (const char *)reply : "");
        free(reply);
        reply = NULL;
    }
    free(reply);
    if (await_promoted(via, "e42", old, e0, &f) != Cs || !f.gc_suspended)
        die("after force-leader: e42 led by node %u, gc_suspended %u", f.leader, f.gc_suspended);
    await_same_stripe("e42", &f, "after force-leader");
    char args[PATH_MAX * 2 + 128], out[16384], p[META_ADDR_MAX + 1];
    peer_of(via, p, sizeof p);
    snprintf(args, sizeof args, "cluster status %s --secret-file %s", p, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "redundancy ec=4+2 stripe ") ||
        !strstr(out, "stripe_version 1 gc_suspended 1"))
        die("tsdb cluster status after force-leader: %s", out);
    printf("  force-leader of e42 to server %d: gc_suspended 1, shown by tsdb cluster status\n", Cs);
    snprintf(args, sizeof args, "cluster volume gc resume %s e42 --secret-file %s", p, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "orphan collection resumed"))
        die("tsdb %s: %s", args, out);
    f.gc_suspended = 0;
    for (uint64_t t0 = now_ms();; usleep(50000)) {
        struct meta_volume g;
        if (vol_rec(via, "e42", &g) && !g.gc_suspended && g.stripe_version == f.stripe_version)
            break;
        if (now_ms() - t0 > 30000)
            die("e42 still gc_suspended 30 s after gc resume");
    }
    await_same_stripe("e42", &f, "after gc resume");
    if ((rc = vol_add(via, "r3", 2, &num)) != 0)
        die("volume add r3: %s", cluster_strerror(rc));
    snprintf(args, sizeof args, "cluster volume gc resume %s %" PRIu32 " --secret-file %s", p, num, secret_path);
    if (cli_run(args, NULL, out, sizeof out) == 0)
        die("gc resume of a replicas volume answered: %s", out);
    printf("  tsdb cluster volume gc resume e42: gc_suspended 0; on a replicas volume refused\n");
    for (int i = 0; i < 6; i++)
        if (i != Lv)
            cut_file(i, Lv, 0);
    cut_file(Lv, Cs, 0);
    stop_all();
}

/* No ISR member up (design-cluster.md 6.2): a replica outside the ISR is up, but the group cannot promote it. Clients
 * get UNAVAILABLE(NO_OWNER) from it (not MOVED to the dead leader), the leader of the group says NO_OWNER, and
 * `tsdb cluster volume force-leader` makes the replica the leader at e + 1: its rows stand, the rows the old ISR
 * acknowledged after the cut are lost (unclean, said so), and the old members return and are cut to its history. Two
 * witnesses keep the metadata group's majority with two of the three data servers dead. */
static void scen_noowner(void)
{
    scenario("noowner");
    for (int i = 0; i < 3; i++)
        penv[i] = "TSDB_REPLD_TEST=cutlinks";
    for (int i = 3; i < 5; i++) {
        is_witness[i] = 1;
        xargs[i] = "--peer-port 0"; /* a witness takes the peer port 7071 unless told */
        char wdir[PATH_MAX + 80];
        server_dir(i, wdir, sizeof wdir);
        if (mkdir(wdir, 0755) != 0)
            die("mkdir %s: %s", wdir, strerror(errno));
    }
    for (int i = 0; i < 5; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 5; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters, two of them witnesses");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "nw", 3, &num)) != 0 || num != 1)
        die("volume add nw: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "nw", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "nw", &v))
        die("no record of nw");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of nw is node %u", v.leader);
    int Cs = (L + 1) % 3, B = (L + 2) % 3;
    uint32_t old = v.leader;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "nw", 30000);
    enum { BEFORE = 20, AFTER = 10 };
    await_isr(L, "nw", 3, 30000, "every replica in the ISR");
    for (int j = 0; j < BEFORE; j++) {
        int64_t ts = 1000000 + 1000LL * j;
        float val = (float)j;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d: %s", j, ers(rc));
    }
    for (uint64_t t1 = now_ms(); rows_in(Cs, id, 1000000, 1000000 + 1000LL * BEFORE, 30000) != BEFORE; usleep(50000))
        if (now_ms() - t1 > 30000)
            die("server %d does not hold the %d rows written with every replica in the ISR", Cs, BEFORE);
    cut_file(L, Cs, 1);
    cut_file(Cs, L, 1);
    await_isr(L, "nw", 2, 30000, "the cut replica out of the ISR");
    for (int j = BEFORE; j < BEFORE + AFTER; j++) {
        int64_t ts = 1000000 + 1000LL * j;
        float val = (float)j;
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("write %d with ISR {leader, server %d}: %s", j, B, ers(rc));
    }
    tsdbc_close(c);
    if (!vol_rec(Cs, "nw", &v))
        die("no record of nw");
    uint64_t e0 = v.epoch;
    { /* while an ISR member is up the group promotes by itself: force-leader is refused and moves nothing (review R6) */
        uint8_t freq[8], *frep = NULL;
        size_t flen = 0, frl = cluster_volume_force_encode(num, ids[Cs], freq);
        rc = admin(Cs, CLUSTER_OP_VOLUME_FORCE, freq, frl, 1, &frep, &flen);
        if (rc != CLUSTER_ERR_STATE)
            die("force-leader of server %d with ISR {leader, server %d} up: %s, not refused (%.*s)", Cs, B,
                cluster_strerror(rc), (int)flen, frep ? (const char *)frep : "");
        printf("  force-leader with the ISR up: refused (%.*s)\n", (int)flen, frep ? (const char *)frep : "");
        free(frep);
        if (!vol_rec(Cs, "nw", &v) || v.epoch != e0 || v.leader != old)
            die("a refused force-leader moved nw (epoch %" PRIu64 ", leader %u)", v.epoch, v.leader);
    }
    stop(L, SIGKILL);
    stop(B, SIGKILL);
    uint64_t t0 = now_ms();
    c = client(Cs);
    tsdbc_set_retry(c, 0);
    for (;; usleep(50000)) {
        int64_t ts = 8000000;
        float val = 1;
        rc = tsdbc_insert_series(c, id, &ts, &val, 1);
        tsdb_unavail e;
        unsigned ne = 0;
        if (rc == TSDB_ERR_UNAVAILABLE && tsdbc_unavailable(c, &e, 1, &ne) == 0 && ne == 1 &&
            e.reason == TSDB_WHY_NO_OWNER)
            break;
        if (rc == 0)
            die("server %d acknowledged a write with no ISR member up", Cs);
        if (now_ms() - t0 > 30000)
            die("no UNAVAILABLE(NO_OWNER) from server %d 30 s after its ISR died (last: %s)", Cs, ers(rc));
    }
    int said = 0;
    for (uint64_t t1 = now_ms(); !said; usleep(50000)) {
        for (int i = 0; i < 5; i++)
            if (i != L && i != B)
                said += log_count(i, "NO_OWNER: no ISR member answers");
        if (!said && now_ms() - t1 > 30000)
            die("the leader of the group never said NO_OWNER");
    }
    if (!vol_rec(Cs, "nw", &v) || v.epoch != e0 || v.leader != old)
        die("the record of nw moved with no ISR member up (epoch %" PRIu64 ", leader %u)", v.epoch, v.leader);
    uint8_t req[8], *reply = NULL;
    size_t len = 0;
    uint32_t cnode = ids[Cs];
    size_t rl = cluster_volume_force_encode(num, cnode, req);
    if ((rc = admin(Cs, CLUSTER_OP_VOLUME_FORCE, req, rl, 1, &reply, &len)) != 0)
        die("force-leader %" PRIu32 " %" PRIu32 ": %s (%.*s)", num, cnode, cluster_strerror(rc), (int)len,
            reply ? (const char *)reply : "");
    printf("  force-leader: %.*s\n", (int)len, (const char *)reply);
    free(reply);
    int Nw = await_promoted(Cs, "nw", old, e0, &v);
    if (Nw != Cs || v.epoch != e0 + 1)
        die("after force-leader: leader server %d at epoch %" PRIu64 " (want %d at %" PRIu64 ")", Nw, v.epoch, Cs,
            e0 + 1);
    await_isr(Cs, "nw", 1, 30000, "the dead members out of the forced leader's ISR (unanswered)");
    int logged = 0;
    for (uint64_t t1 = now_ms(); !logged; usleep(50000)) {
        for (int i = 0; i < 5; i++)
            if (i != L && i != B)
                logged += log_count(i, "it holds every write acknowledged before that shrink");
        if (!logged && now_ms() - t1 > 10000)
            die("no log line compares the forced leader's end with the last shrink's commit point");
    }
    tsdbc_set_retry(c, 10000);
    int64_t ts = 9000000;
    float val = 7;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write to the forced leader: %s", ers(rc));
    tsdbc_close(c);
    int got = rows_in(Cs, id, 1000000, 1000000 + 1000LL * (BEFORE + AFTER), 30000);
    if (got != BEFORE)
        die("the forced leader holds %d rows of the first %d, want exactly the %d written before the cut", got,
            BEFORE + AFTER, BEFORE);
    printf("  no ISR member up: NO_OWNER %" PRIu64 " ms after the kill; force-leader made server %d leader at epoch "
           "%" PRIu64 " with the %d rows from before the cut (the %d after it are lost, as said)\n",
           now_ms() - t0, Cs, v.epoch, BEFORE, AFTER);
    cut_file(L, Cs, 0);
    cut_file(Cs, L, 0);
    /* An old member whose REPL floor had reached rows past the forced leader's history (committed at epoch e0)
     * reopens with them applied: it cannot cut below what it applied, so it stops the volume, loudly, rather than
     * rejoin with rows the leader lacks (rebuilding it from the leader is not built). One whose floor was still at or
     * below the forced leader's start (the floor is saved after the commit point moves, and the kill came right after
     * the last acknowledgement; jc5, 2026-11-20) reopens without them, cuts its log there and rejoins: then it must
     * hold exactly the forced leader's rows, none of the lost ones. Either way per member. */
    start(L);
    start(B);
    int olds[2] = {L, B}, stopped[2] = {0, 0}, joined[2] = {0, 0};
    for (uint64_t t1 = now_ms();; usleep(50000)) {
        if (!vol_rec(Cs, "nw", &v))
            die("no record of nw");
        int left = 0;
        for (int k = 0; k < 2; k++) {
            stopped[k] = log_count(olds[k], "stopped: a cut below the applied end") > 0;
            joined[k] = 0;
            for (uint32_t j = 0; j < v.nisr; j++)
                joined[k] |= v.isr[j] == ids[olds[k]];
            if (stopped[k] && joined[k])
                die("server %d stopped at a cut below its applied end and is in the ISR", olds[k]);
            left += !stopped[k] && !joined[k];
        }
        if (!left)
            break;
        if (now_ms() - t1 > 60000)
            die("60 s after the old members returned: server %d %s, server %d %s (want each stopped or in the ISR)",
                L, stopped[0] ? "stopped" : joined[0] ? "joined" : "neither", B,
                stopped[1] ? "stopped" : joined[1] ? "joined" : "neither");
    }
    if (v.leader != ids[Cs] || v.nisr != 1u + (unsigned)joined[0] + (unsigned)joined[1])
        die("after the old members returned: leader %u, ISR of %u (want %u and the %d that rejoined)", v.leader,
            v.nisr, ids[Cs], joined[0] + joined[1]);
    c = client(Cs);
    tsdbc_set_retry(c, 10000);
    ts = 9001000;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("a write to the forced leader after the old members returned: %s", ers(rc));
    tsdbc_close(c);
    if ((got = rows_in(Cs, id, 0, INT64_MAX, 30000)) != BEFORE + 2)
        die("the forced leader holds %d rows, want %d", got, BEFORE + 2);
    for (int k = 0; k < 2; k++) {
        if (!joined[k])
            continue;
        uint64_t t1 = now_ms();
        while ((got = rows_in(olds[k], id, 0, INT64_MAX, 30000)) != BEFORE + 2 && now_ms() - t1 < 30000)
            usleep(100000);
        if (got != BEFORE + 2)
            die("server %d rejoined the forced leader's ISR and holds %d rows, want its %d", olds[k], got, BEFORE + 2);
        if ((got = rows_in(olds[k], id, 1000000 + 1000LL * BEFORE, 1000000 + 1000LL * (BEFORE + AFTER), 30000)) != 0)
            die("server %d rejoined and holds %d of the %d rows lost with the force", olds[k], got, AFTER);
    }
    printf("  the old members returned: server %d %s, server %d %s (a cut below the applied end stops; a member that "
           "had not applied past the forced leader's start cuts and rejoins without the lost rows)\n",
           L, stopped[0] ? "stopped" : "rejoined", B, stopped[1] ? "stopped" : "rejoined");
    stop_all();
}

static int rm_one(const char *path, const struct stat *st, int flag, struct FTW *ftw)
{
    (void)st, (void)flag, (void)ftw;
    return remove(path) != 0 && errno != ENOENT ? -1 : 0;
}

/* ---- r4-setchg: replica set changes on a running volume (server/rset.c, cvolset.c, cvolset_mgr.c, cset.c). ADD and
 * REMOVE have no operator verb before r4-move: the scenarios hand them to the Raft leader through TSDB_CLUSTER_TEST
 * setop_file=1 (cset.c). */

/* proposes one set op ("add V NODE", "remove V NODE", "reset V NODE") through whichever running server leads; returns
 * the line of setop.out (refused or proposed) */
static void set_op(int nserv, const char *line, char *res, size_t rn)
{
    for (int i = 0; i < nserv; i++) {
        char p[PATH_MAX + 96];
        server_dir(i, p, sizeof p);
        strcat(p, "/state/setop.out");
        unlink(p);
    }
    for (int i = 0; i < nserv; i++) {
        if (stopped[i] || !pids[i])
            continue;
        char p[PATH_MAX + 96];
        server_dir(i, p, sizeof p);
        strcat(p, "/state/setop");
        FILE *f = fopen(p, "w");
        if (!f || fprintf(f, "%s\n", line) < 0 || fclose(f) != 0)
            die("%s: %s", p, strerror(errno));
    }
    uint64_t t0 = now_ms();
    for (;;) {
        for (int i = 0; i < nserv; i++) {
            char p[PATH_MAX + 96];
            server_dir(i, p, sizeof p);
            strcat(p, "/state/setop.out");
            FILE *f = fopen(p, "r");
            if (!f)
                continue;
            char ln[512] = "";
            if (!fgets(ln, sizeof ln, f))
                ln[0] = 0;
            fclose(f);
            if (!ln[0])
                continue;
            for (int k = 0; k < nserv; k++) { /* the others' copies must not run once they lead */
                char q[PATH_MAX + 96];
                server_dir(k, q, sizeof q);
                strcat(q, "/state/setop");
                unlink(q);
            }
            ln[strcspn(ln, "\n")] = 0;
            snprintf(res, rn, "%s", ln);
            printf("  setop %s\n", ln);
            return;
        }
        if (now_ms() - t0 > 20000)
            die("set op \"%s\": no Raft leader took it in 20 s", line);
        usleep(50000);
    }
}

static int rep_index(const struct meta_volume *v, int i)
{
    for (uint32_t k = 0; k < v->nrep; k++)
        if (v->rep[k].node == ids[i])
            return (int)k;
    return -1;
}

/* waits until the record of `name` names server i (want 1) or does not (want 0), with n members; returns it */
static void await_member(int via, const char *name, int i, int want, uint32_t n, int ms, struct meta_volume *out)
{
    uint64_t t0 = now_ms();
    for (;;) {
        if (vol_rec(via, name, out) && (rep_index(out, i) >= 0) == want && out->nrep == n)
            return;
        if (now_ms() - t0 > (uint64_t)ms)
            die("the replica set of %s does not %sname server %d with %" PRIu32 " members after %d ms", name,
                want ? "" : "stop to ", i, n, ms);
        usleep(50000);
    }
}

/* rep_same over the servers `s` (a set that changed: not 0, 1, 2) */
static void rep_same_on(const int *s, int ns, const uint64_t *want, const char *what)
{
    uint64_t rows[N][REP_NAMES], h[N][REP_NAMES];
    for (int x = 0; x < ns; x++) {
        char dir[PATH_MAX + 80], v[PATH_MAX + 120];
        server_dir(s[x], dir, sizeof dir);
        snprintf(v, sizeof v, "%s/v1", dir);
        int rc = cvol_digest(v, rep_names, REP_NAMES, rows[x], h[x]);
        if (rc != 0)
            die("%s: open %s read-only: %s", what, v, ers(rc));
        for (int k = 0; k < REP_NAMES; k++) {
            if (rows[x][k] != want[k])
                die("%s: server %d holds %" PRIu64 " rows of %s, not %" PRIu64, what, s[x], rows[x][k], rep_names[k],
                    want[k]);
            if (x && h[x][k] != h[0][k])
                die("%s: server %d's rows of %s differ from server %d's", what, s[x], rep_names[k], s[0]);
        }
    }
}

static uint64_t set_write(tsdbc *c, tsdb_sid id, int64_t *t, int batches, int flush)
{
    uint64_t n = 0;
    for (int k = 0; k < batches; k++) {
        int64_t tv[100];
        float vv[100];
        for (int j = 0; j < 100; j++)
            tv[j] = (*t)++, vv[j] = (float)j;
        int rc = tsdbc_insert_series(c, id, tv, vv, 100);
        if (rc != 0)
            die("a write: %s", ers(rc));
        n += 100;
        if (flush && (rc = tsdbc_flush(c)) != 0)
            die("flush: %s", ers(rc));
    }
    return n;
}

/* a writer of batches of 100 rows (timestamps t, t + 1, ...) until `stop`: `acked` rows were acknowledged; a failed
 * batch is `unsure` (it may or may not be there) when `lenient`, else the writer stops with its error in rc. Every
 * answer within 30 s, so a hang is a failure */
struct set_writer {
    int port;
    tsdb_sid id;
    int64_t t;
    int stop, lenient, rc;
    uint64_t acked, unsure, batches;
};

static void *set_write_thread(void *a)
{
    struct set_writer *w = a;
    tsdbc *c = NULL;
    while (!__atomic_load_n(&w->stop, __ATOMIC_ACQUIRE)) {
        int crc;
        if (!c && (crc = tsdbc_connect("127.0.0.1", w->port, &c)) != 0) {
            __atomic_store_n(&w->rc, crc, __ATOMIC_RELEASE); /* await_batches reads it while we run */
            c = NULL;
            if (!w->lenient)
                break;
            usleep(100000);
            continue;
        }
        tsdbc_set_timeout(c, 30000);
        int64_t tv[100];
        float vv[100];
        for (int j = 0; j < 100; j++)
            tv[j] = w->t++, vv[j] = (float)(j % 37);
        int rc = tsdbc_insert_series(c, w->id, tv, vv, 100);
        __atomic_add_fetch(&w->batches, 1, __ATOMIC_RELEASE);
        if (rc == 0) {
            __atomic_add_fetch(&w->acked, 100, __ATOMIC_RELEASE);
            continue;
        }
        __atomic_store_n(&w->rc, rc, __ATOMIC_RELEASE);
        if (!w->lenient)
            break;
        w->unsure += 100;
        tsdbc_close(c); /* the connection may be the one a written-and-lost forward closed */
        c = NULL;
        usleep(100000);
    }
    if (c)
        tsdbc_close(c);
    if (w->lenient)
        __atomic_store_n(&w->rc, 0, __ATOMIC_RELEASE);
    return NULL;
}

/* waits until a set_writer has had `n` more batches answered than it had at the call */
static void await_batches(struct set_writer *w, uint64_t n, int ms)
{
    uint64_t b0 = __atomic_load_n(&w->batches, __ATOMIC_ACQUIRE), t0 = now_ms();
    while (__atomic_load_n(&w->batches, __ATOMIC_ACQUIRE) < b0 + n)
        if (__atomic_load_n(&w->rc, __ATOMIC_ACQUIRE) && !w->lenient)
            die("a writer: %s", ers(__atomic_load_n(&w->rc, __ATOMIC_ACQUIRE)));
        else if (now_ms() - t0 > (uint64_t)ms)
            die("a writer had fewer than %" PRIu64 " batches answered in %d ms", n, ms);
        else
            usleep(20000);
}

static int dir_has(int i, const char *prefix)
{
    char d[PATH_MAX + 80];
    server_dir(i, d, sizeof d);
    DIR *dp = opendir(d);
    int found = 0;
    struct dirent *e;
    while (dp && (e = readdir(dp)))
        found |= !strncmp(e->d_name, prefix, strlen(prefix));
    if (dp)
        closedir(dp);
    return found;
}

/* a volume "plant" of 3 replicas on servers 0..nserv-1 (setop_file on each); its leader's server. keepall: the leader
 * keeps every segment (TSDB_REPLD_TEST=keepall). A writer drops the segment of position 1 (its open marker) once every
 * member acknowledged it, within seconds; a member added or reset after that fills by a snapshot (addsnap). A scenario
 * that must fill a fresh replica from the log keeps everything */
static const char *set_cenv; /* TSDB_CLUSTER_TEST of set_setup's servers when not NULL (setop_file=1 among it) */

static int set_setup(int nserv, struct meta_volume *v, int keepall)
{
    for (int i = 0; i < nserv; i++) {
        envs[i] = set_cenv ? set_cenv : "setop_file=1";
        if (keepall)
            penv[i] = "TSDB_REPLD_TEST=keepall";
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < nserv; i++)
        node_add(0, i);
    if (nserv >= 3) { /* a member stopped later must not take the metadata group's quorum with it */
        unsigned want = nserv >= 5 ? 5 : 3;
        await_view(0, p_voters, &want, want == 5 ? "five voters" : "three voters");
    }
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    if (!vol_rec(0, "plant", v))
        die("no record of plant");
    for (uint32_t k = 0; k < v->nrep; k++)
        await_open_gen(0, "plant", server_of(v->rep[k].node), 1, 0);
    int L = server_of(v->leader);
    if (L < 0)
        die("the leader of plant is node %u", v->leader);
    return L;
}

/* addreplica: a 4th replica on a young volume under writes fills (from the log, or by a snapshot once the leader dropped
 * position 1: addsnap) and joins the ISR; the rows are equal on all four. Mutant setkeepold (the driver keeps the old set: the learner is never sent the log, never joins). Also the
 * test of r4-meta's F_nofill: the watch push carries the new set_version to the driver (its line names it). */
static void scen_addreplica(void)
{
    scenario("addreplica");
    struct meta_volume v;
    int L = set_setup(4, &v, 0), X = -1;
    for (int i = 0; i < 4; i++)
        if (rep_index(&v, i) < 0)
            X = i;
    if (X < 0)
        die("plant has a replica on every server");
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t t = 1000;
    uint64_t rows = set_write(c, id, &t, 5, 1);
    await_isr(0, "plant", 3, 10000, "every replica up");
    struct set_writer w = {.port = cports[L], .id = id, .t = 10000000};
    pthread_t th;
    if (pthread_create(&th, NULL, set_write_thread, &w) != 0)
        die("pthread_create");
    await_batches(&w, 20, 20000);
    char res[512], op[64];
    uint64_t sv0 = v.set_version;
    snprintf(op, sizeof op, "add 1 %" PRIu32, ids[X]);
    set_op(4, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("add: %s", res);
    await_member(0, "plant", X, 1, 4, 10000, &v);
    if (v.set_version != sv0 + 1)
        die("the add moved set_version %" PRIu64 " -> %" PRIu64, sv0, v.set_version);
    char line[128];
    snprintf(line, sizeof line, "replica set version %" PRIu64 " -> %" PRIu64, sv0, v.set_version);
    await_log_count(L, line, 1, 20000);
    await_isr(0, "plant", 4, 60000, "the learner filled from the log and joined");
    await_batches(&w, 20, 20000); /* and the writes go on with four */
    __atomic_store_n(&w.stop, 1, __ATOMIC_RELEASE);
    pthread_join(th, NULL);
    if (w.rc != 0)
        die("a write during the fill: %s", ers(w.rc));
    rows += w.acked;
    rows += set_write(c, id, &t, 2, 0); /* committed by four */
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, 0, 0, 0};
    int s[4] = {0, 1, 2, 3};
    rep_same_on(s, 4, want, "after a clean stop");
    printf("  server %d added to plant under writes: it filled from the log, joined the ISR and holds the %" PRIu64
           " rows the others hold\n", X, rows);
}


/* the lowest (lo) or highest WAL segment number in server i's v1 (UINT64_MAX / 0 when it has none). Position 1 (the
 * open marker of a young volume) need not be in segment 1: the open as the leader and the reopen as the writer each
 * start a segment, and a run once found segment 1 gone with position 1 still kept in segment 2 (the learner then
 * filled from the log, no snapshot). */
static uint64_t segment_bound(int i, int lo)
{
    char d[PATH_MAX + 64];
    server_dir(i, d, sizeof d);
    strcat(d, "/v1");
    uint64_t b = lo ? UINT64_MAX : 0;
    DIR *dir = opendir(d);
    if (!dir)
        return b;
    struct dirent *e;
    while ((e = readdir(dir))) {
        uint64_t seq;
        char tail[2];
        if (sscanf(e->d_name, "wal_%16" SCNx64 ".lo%1s", &seq, tail) != 2 || strlen(e->d_name) != 24)
            continue;
        if (lo ? seq < b : seq > b)
            b = seq;
    }
    closedir(dir);
    return b;
}

/* addsnap: a 4th replica added once the leader no longer keeps position 1 fills by a snapshot (r4-xferinst), and a
 * REMOVE (of a replica paused out of the ISR first) proposed while its install waits to close the driver
 * (snapclosedelay) is held back on it until the install is done (rset_apply on rv->snap: "waits: a snapshot ...";
 * mutant snapsetnodefer applies it between the install's check and its close); it opens the copy under the newest set,
 * joins, and holds the rows of the other two */
static void scen_addsnap(void)
{
    scenario("addsnap");
    for (int i = 0; i < 4; i++)
        penv[i] = "TSDB_REPLD_TEST=snapclosedelay=3000"; /* only the learner installs */
    struct meta_volume v;
    int L = set_setup(4, &v, 0), X = -1, Y = -1;
    for (int i = 0; i < 4; i++)
        if (rep_index(&v, i) < 0)
            X = i;
        else if (i != L && Y < 0)
            Y = i;
    if (X < 0 || Y < 0)
        die("plant has no free server or no second replica");
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t t = 1000;
    uint64_t rows = set_write(c, id, &t, 5, 1);
    await_isr(0, "plant", 3, 10000, "every replica up");
    /* every segment that existed after the first writes (position 1 among them) goes once every member acknowledged
     * it and it is in parts: the leader's log then starts past 1 */
    uint64_t t0 = now_ms(), s1 = segment_bound(L, 0);
    if (!s1)
        die("the leader has no WAL segment after its first writes");
    while (segment_bound(L, 1) <= s1) {
        if (now_ms() - t0 > 30000)
            die("the leader still keeps a WAL segment at or below %" PRIu64 " after 30 s", s1);
        rows += set_write(c, id, &t, 1, 0);
        usleep(100000);
    }
    /* a REMOVE of an ISR member is refused at apply (the ISR shrinks first): Y leaves the ISR before the add, so the
     * remove proposed inside X's close wait applies at once */
    pause_server(Y, 1);
    await_isr(0, "plant", 2, 20000, "the replica to be removed paused");
    char res[512], op[64];
    snprintf(op, sizeof op, "add 1 %" PRIu32, ids[X]);
    set_op(4, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("add: %s", res);
    await_member(0, "plant", X, 1, 4, 10000, &v);
    await_log(X, "the close for the install waits", 60000, "the learner received a snapshot and installs it");
    if (log_count(X, "snapshot installed: P"))
        die("the install did not wait for its close");
    snprintf(op, sizeof op, "remove 1 %" PRIu32, ids[Y]);
    set_op(4, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("remove: %s", res);
    await_member(0, "plant", Y, 0, 3, 10000, &v);
    uint64_t sv = v.set_version;
    char line[160];
    snprintf(line, sizeof line, "replica set version %" PRIu64 " waits: a snapshot of the volume is in progress", sv);
    t0 = now_ms();
    while (!log_count(X, "snapshot installed: P")) {
        if (now_ms() - t0 > 30000)
            die("server %d installed nothing 30 s after its close began", X);
        usleep(50000);
    }
    if (!log_count(X, line))
        die("a set change applied on server %d while it installed a snapshot (no line \"%s\")", X, line);
    pause_server(Y, 0);
    await_log_count(Y, "this server's replica was removed from the replica set", 1, 20000);
    await_isr(0, "plant", 3, 60000, "the learner that installed a snapshot joins the ISR of the new set");
    rows += set_write(c, id, &t, 2, 0); /* committed by the three */
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, 0, 0, 0};
    int sv3[3], ns = 0;
    for (int i = 0; i < 4; i++)
        if (i != Y)
            sv3[ns++] = i;
    rep_same_on(sv3, 3, want, "after a clean stop");
    printf("  server %d added after position 1 was dropped: filled by a snapshot, a remove of server %d held back "
           "during its install, joined; %" PRIu64 " rows on the three\n", X, Y, rows);
}

/* setnext: two ADDs, the second proposed while every driver's first drain of the first change lets rv->mu go
 * (TSDB_REPLD_TEST=setdrainwait, until a newer record comes or 10 s pass). The driver applies the newest record from the record it holds,
 * never the maps it computed for the first (mutant setnextstale: the second member is taken for an old one): every
 * driver goes from version S to S + 2 with both new members new, both fill from the log and join, rows equal on all. */
static void scen_setnext(void)
{
    scenario("setnext");
    struct meta_volume v;
    for (int i = 0; i < 5; i++)
        penv[i] = "TSDB_REPLD_TEST=keepall,setdrainwait";
    int L = set_setup(5, &v, 0), X = -1, Y = -1;
    for (int i = 0; i < 5; i++)
        if (rep_index(&v, i) < 0)
            *(X < 0 ? &X : &Y) = i;
    if (X < 0 || Y < 0)
        die("plant: leader %d, non-members %d %d", L, X, Y);
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t t = 1000;
    uint64_t rows = set_write(c, id, &t, 5, 1);
    await_isr(0, "plant", 3, 10000, "every replica up");
    char res[512], op[96], line[160];
    uint64_t sv0 = v.set_version;
    snprintf(op, sizeof op, "add 1 %" PRIu32, ids[X]);
    set_op(5, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("add %d: %s", X, res);
    snprintf(line, sizeof line, "setdrainwait: replica set version %" PRIu64 " drains", sv0 + 1);
    await_log_count(L, line, 1, 10000); /* the leader's driver is inside the first change: the second comes now */
    snprintf(op, sizeof op, "add 1 %" PRIu32, ids[Y]);
    set_op(5, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("add %d: %s", Y, res);
    await_member(0, "plant", Y, 1, 5, 10000, &v);
    if (v.set_version != sv0 + 2)
        die("two adds moved set_version %" PRIu64 " -> %" PRIu64, sv0, v.set_version);
    snprintf(line, sizeof line, "replica set version %" PRIu64 " -> %" PRIu64, sv0, sv0 + 2);
    await_log_count(L, line, 1, 20000);
    snprintf(line, sizeof line, "replica set version %" PRIu64 " -> %" PRIu64, sv0, sv0 + 1);
    if (log_count(L, line))
        die("the leader applied set version %" PRIu64 " although %" PRIu64 " came during its drain", sv0 + 1, sv0 + 2);
    snprintf(line, sizeof line, "%" PRIu32 " (new), %" PRIu32 " (new);", ids[X], ids[Y]);
    if (log_count(L, line) != 1)
        die("the leader's set change line does not name servers %d and %d as new (\"%s\")", X, Y, line);
    await_isr(0, "plant", 5, 60000, "both learners filled from the log and joined");
    rows += set_write(c, id, &t, 3, 0); /* committed by five */
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, 0, 0, 0};
    int s5[5] = {0, 1, 2, 3, 4};
    rep_same_on(s5, 5, want, "after a clean stop");
    printf("  two adds during one drain: every driver went to set version %" PRIu64 " at once, servers %d and %d new,"
           " joined; %" PRIu64 " rows on all five\n", sv0 + 2, X, Y, rows);
}

static off_t classes_size(int i)
{
    char p[PATH_MAX + 96];
    server_dir(i, p, sizeof p);
    strcat(p, "/v1/CLASSES");
    struct stat st;
    return stat(p, &st) == 0 ? st.st_size : 0;
}

/* a slow series (24 rows a day, one day per round, in two flushed parts: with --merge-idle-s 1 the idle merge makes
 * one part of them at once and measures its series, src/merge.c; fewer than 64 rows at its first flush leave a fresh
 * series in class 0, src/classes.c) written until the leader's CLASSES grows (the series' class switch); ms from the first batch. *join: when the ISR of plant
 * first had `nisr` members, ms from the same start (0: not while this ran) */
static uint64_t slow_until_switch(tsdbc *c, tsdb_sid id, int64_t *day, uint64_t *rows, int L, uint32_t nisr,
                                  uint64_t *join, int ms)
{
    off_t s0 = classes_size(L);
    uint64_t t0 = now_ms();
    if (join)
        *join = 0;
    for (;;) {
        for (int half = 0; half < 2; half++) { /* two parts: the idle merge makes one and measures it */
            int64_t tv[12];
            float vv[12];
            for (int h = 0; h < 12; h++)
                tv[h] = *day * 86400000LL + 3600000LL * (12 * half + h), vv[h] = (float)h;
            int rc = tsdbc_insert_series(c, id, tv, vv, 12);
            if (rc != 0)
                die("a write of the slow series: %s", ers(rc));
            *rows += 12;
            if ((rc = tsdbc_flush(c)) != 0)
                die("flush: %s", ers(rc));
        }
        (*day)++;
        if (join && !*join && isr_of(0, "plant", NULL) == nisr)
            *join = now_ms() - t0 + !(now_ms() - t0);
        if (classes_size(L) > s0)
            return now_ms() - t0;
        if (now_ms() - t0 > (uint64_t)ms)
            die("the slow series got no class of its own in %d ms (CLASSES of server %d: %lld bytes)", ms, L,
                (long long)classes_size(L));
        usleep(250000);
    }
}

/* addswitch: a class switch during addreplica's fill. A leader's switch waits (CLS_DEFER, src/classes.c: "a class switch
 * waits") while the members' replay floor is below wtail_from; a learner counts with the lowest position sent to it
 * until its replay start passes, so a switch is deferred while it fills. keepall keeps position 1 for the learner but
 * also pins the leader's log start, and with it the floor, at 1: it is lifted (keepoff) once the leader's driver has
 * the learner in its set, whose ack then holds the log. A member's log start counts too (repl_replay_floor): the
 * replicas keep their own segments for repl_retain_s past their commit floor, 5 s here (1800 by default, and then
 * every switch of a young volume waits that long). Measured: the switch's latency while the learner fills, beside
 * the time it took to join, and a switch on the four members after the join (the control); at the end every member's
 * rows are equal and each opens (cls_check_parts: no row in two keys). */
static void scen_addswitch(void)
{
    scenario("addswitch");
    for (int i = 0; i < 4; i++)
        xargs[i] = "--merge-idle-s 1"; /* 0 reads as the default (src/db.c) */
    init_retain_s = 5; /* the replicas' own segments go 5 s past their commit floor (keepall lifts the leader's caps) */
    struct meta_volume v;
    int L = set_setup(4, &v, 1), X = -1;
    for (int i = 0; i < 4; i++)
        if (rep_index(&v, i) < 0)
            X = i;
    if (X < 0)
        die("plant has a replica on every server");
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    tsdb_sid ctl = rep_series(c, rep_names[1], "plant", 30000), slow = rep_series(c, rep_names[3], "plant", 30000);
    int64_t t = 1000, day = 10;
    uint64_t rows = set_write(c, id, &t, 5, 1), nctl = 0, nslow = 0;
    await_isr(0, "plant", 3, 10000, "every replica up");
    struct set_writer w = {.port = cports[L], .id = id, .t = 10000000};
    pthread_t th;
    if (pthread_create(&th, NULL, set_write_thread, &w) != 0)
        die("pthread_create");
    await_batches(&w, 200, 60000); /* a log for the learner to fill */
    char res[512], op[64], line[128];
    uint64_t sv0 = v.set_version, join = 0;
    snprintf(op, sizeof op, "add 1 %" PRIu32, ids[X]);
    set_op(4, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("add: %s", res);
    uint64_t t_add = now_ms();
    await_member(0, "plant", X, 1, 4, 10000, &v);
    if (v.set_version != sv0 + 1)
        die("the add moved set_version %" PRIu64 " -> %" PRIu64, sv0, v.set_version);
    snprintf(line, sizeof line, "replica set version %" PRIu64 " -> %" PRIu64, sv0, v.set_version);
    await_log_count(L, line, 1, 20000);
    for (int i = 0; i < 4; i++) { /* the learner's ack holds the log from here on */
        char f[PATH_MAX + 96];
        server_dir(i, f, sizeof f);
        strcat(f, "/keepoff");
        FILE *k = fopen(f, "w");
        if (!k)
            die("%s: %s", f, strerror(errno));
        fclose(k);
    }
    uint64_t lead = now_ms() - t_add;
    uint64_t sw_ms = slow_until_switch(c, slow, &day, &nslow, L, 4, &join, 120000);
    if (!join) {
        await_isr(0, "plant", 4, 120000, "the learner filled from the log and joined");
        join = now_ms() - t_add - lead;
    }
    /* the switch was deferred at least once on the way (CLS_DEFER: the floor below wtail_from, held there by the
     * learner's lowest position or the members' retained segments): a leader that switched at once (the defer skipped)
     * never says it. Which of the two held it is not told apart here. */
    int waits = log_count(L, "a class switch waits");
    if (waits < 1)
        die("the leader switched the slow series' class with no \"a class switch waits\" line (%" PRIu64 " ms)", sw_ms);
    uint64_t ctl_ms = slow_until_switch(c, ctl, &day, &nctl, L, 0, NULL, 60000);
    await_batches(&w, 20, 20000);
    __atomic_store_n(&w.stop, 1, __ATOMIC_RELEASE);
    pthread_join(th, NULL);
    if (w.rc != 0)
        die("a write during the fill: %s", ers(w.rc));
    rows += w.acked;
    if ((uint64_t)rows_of(c, id) != rows || (uint64_t)rows_of(c, ctl) != nctl || (uint64_t)rows_of(c, slow) != nslow)
        die("the leader reads %d, %d, %d rows, not %" PRIu64 ", %" PRIu64 ", %" PRIu64, rows_of(c, id),
            rows_of(c, ctl), rows_of(c, slow), rows, nctl, nslow);
    tsdbc_close(c);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, nctl, 0, nslow};
    int s[4] = {0, 1, 2, 3};
    rep_same_on(s, 4, want, "after a clean stop");
    init_retain_s = 0;
    printf("  server %d added (in the leader's set %" PRIu64 " ms after the add): a class switch took %" PRIu64
           " ms (%d \"waits\" lines, one per 10 s at most), the learner joined after %" PRIu64 " ms (%s the switch); "
           "a switch on the four after the join: %" PRIu64 " ms; %" PRIu64 " rows equal on all four, every member "
           "opens\n",
           X, lead, sw_ms, waits, join, join <= sw_ms ? "before" : "after", ctl_ms, rows);
}

/* setchurn: replica set changes under 4 writers with the volume leader SIGKILLed in the middle. 5 servers, plant on 3;
 * the writers (lenient: a failed batch is unsure) send to the two servers outside the set (A, B: forwarded, never
 * killed; both join it later). A is added and joins, a member R1 is removed, B is added and the leader killed while B
 * fills; a member is promoted, the old leader started again, B fills from the new leader and joins with it; then the
 * old leader is removed. Each member removed is paused first, until the ISR has shrunk without it (meta.c refuses a
 * REMOVE of an ISR member). At the end every series holds at least its acknowledged rows and at most those plus the
 * unsure ones, and the three members' rows are equal. */
static void scen_setchurn(void)
{
    scenario("setchurn");
    struct meta_volume v;
    int L = set_setup(5, &v, 1), A = -1, B = -1, R1 = -1, R2 = -1;
    for (int i = 0; i < 5; i++)
        if (rep_index(&v, i) < 0)
            *(A < 0 ? &A : &B) = i;
        else if (i != L)
            *(R1 < 0 ? &R1 : &R2) = i;
    if (A < 0 || B < 0 || R1 < 0 || R2 < 0)
        die("plant: leader %d, members %d %d, others %d %d", L, R1, R2, A, B);
    tsdbc *c = client(L);
    tsdb_sid ids4[4];
    for (int k = 0; k < 4; k++)
        ids4[k] = rep_series(c, rep_names[k], "plant", 30000);
    tsdbc_close(c);
    await_isr(A, "plant", 3, 10000, "every replica up");
    struct set_writer w[4];
    pthread_t th[4];
    for (int k = 0; k < 4; k++) {
        w[k] = (struct set_writer){.port = cports[k < 2 ? A : B], .id = ids4[k], .t = 1000, .lenient = 1};
        if (pthread_create(&th[k], NULL, set_write_thread, &w[k]) != 0)
            die("pthread_create");
    }
    for (int k = 0; k < 4; k++)
        await_batches(&w[k], 20, 30000);
    char res[512], op[64];
    snprintf(op, sizeof op, "add 1 %" PRIu32, ids[A]);
    set_op(5, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("add A: %s", res);
    await_member(A, "plant", A, 1, 4, 10000, &v);
    await_isr(A, "plant", 4, 60000, "A filled from the log and joined");
    pause_server(R1, 1); /* a REMOVE needs its member out of the ISR first (meta.c: a move never lowers the copies) */
    await_isr(A, "plant", 3, 20000, "R1 paused");
    snprintf(op, sizeof op, "remove 1 %" PRIu32, ids[R1]);
    set_op(5, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("remove R1: %s", res);
    await_member(A, "plant", R1, 0, 3, 10000, &v);
    pause_server(R1, 0);
    for (int k = 0; k < 4; k++)
        await_batches(&w[k], 10, 30000);
    snprintf(op, sizeof op, "add 1 %" PRIu32, ids[B]);
    set_op(5, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("add B: %s", res);
    await_member(A, "plant", B, 1, 4, 10000, &v);
    uint64_t e0 = v.epoch, tk = now_ms();
    stop(L, SIGKILL); /* B is filling from it */
    int Nw = -1;
    for (;;) {
        if (vol_rec(A, "plant", &v) && v.leader != ids[L] && v.epoch > e0 && (Nw = server_of(v.leader)) >= 0)
            break;
        if (now_ms() - tk > 30000)
            die("no new leader of plant 30 s after its leader was killed (epoch %" PRIu64 ", leader %u)", v.epoch,
                v.leader);
        usleep(20000);
    }
    uint64_t promo = now_ms() - tk;
    start(L);
    await_isr(A, "plant", 4, 120000, "B filled from the new leader and the old leader rejoined");
    uint64_t joined = now_ms() - tk;
    for (int k = 0; k < 4; k++)
        await_batches(&w[k], 10, 30000);
    pause_server(L, 1);
    await_isr(A, "plant", 3, 20000, "the old leader paused");
    snprintf(op, sizeof op, "remove 1 %" PRIu32, ids[L]);
    set_op(5, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("remove the old leader: %s", res);
    await_member(A, "plant", L, 0, 3, 10000, &v);
    pause_server(L, 0);
    if (server_of(v.leader) != Nw)
        die("the leader moved from server %d to %d after the failover", Nw, server_of(v.leader));
    for (int k = 0; k < 4; k++)
        await_batches(&w[k], 10, 30000);
    for (int k = 0; k < 4; k++)
        __atomic_store_n(&w[k].stop, 1, __ATOMIC_RELEASE);
    uint64_t want[REP_NAMES], acked = 0, unsure = 0;
    c = client(Nw);
    for (int k = 0; k < 4; k++) {
        pthread_join(th[k], NULL);
        int n = rows_of(c, ids4[k]);
        if (n < 0 || (uint64_t)n < w[k].acked || (uint64_t)n > w[k].acked + w[k].unsure)
            die("%s: the leader reads %d rows, %" PRIu64 " acknowledged and %" PRIu64 " unsure", rep_names[k], n,
                w[k].acked, w[k].unsure);
        want[k] = (uint64_t)n, acked += w[k].acked, unsure += w[k].unsure;
    }
    tsdbc_close(c);
    stop_all();
    int s[3] = {R2, A, B};
    rep_same_on(s, 3, want, "after a clean stop");
    printf("  A added, R1 removed, B added and the leader killed while B filled (server %d promoted after %" PRIu64
           " ms, ISR of 4 after %" PRIu64 " ms), the old leader removed: %" PRIu64 " rows acknowledged (%" PRIu64
           " unsure) through two forwarding servers, all there, equal on the three members\n",
           Nw, promo, joined, acked, unsure);
}

/* removereplica: a replica out of the ISR (SIGSTOPped) is removed; once it runs again it closes the volume, renames
 * v1 to v1.removed-<rid> and deletes it; the leader goes on committing without it. Mutant removedopen (the removed
 * replica keeps its directory open and serving). */
static void scen_removereplica(void)
{
    scenario("removereplica");
    struct meta_volume v;
    /* copy_lag_ms: the loop's own copy publish comes 500 ms after each push, so a manager that judged the removal by
     * the copy of the round before (published after the push) keeps the volume for good */
    set_cenv = "setop_file=1,copy_lag_ms=500";
    int L = set_setup(3, &v, 0), R = (L + 1) % 3, O = (L + 2) % 3;
    set_cenv = NULL;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t t = 1000;
    uint64_t rows = set_write(c, id, &t, 3, 1);
    await_isr(0, "plant", 3, 10000, "every replica up");
    pause_server(R, 1);
    await_isr(0, "plant", 2, 20000, "a replica paused");
    char res[512], op[64];
    snprintf(op, sizeof op, "remove 1 %" PRIu32, ids[R]);
    set_op(3, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("remove: %s", res);
    await_member(0, "plant", R, 0, 2, 10000, &v);
    rows += set_write(c, id, &t, 2, 1);
    pause_server(R, 0);
    await_log_count(R, "this server's replica was removed from the replica set", 1, 20000);
    uint64_t t0 = now_ms();
    while (dir_has(R, "v1"))
        if (now_ms() - t0 > 20000)
            die("server %d still has v1 or v1.removed-* 20 s after its removal", R);
        else
            usleep(50000);
    rows += set_write(c, id, &t, 2, 0);
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    { /* a client of the removed server: its engine is closed, so a read there is route_decide's from the copy (MOVED
       * to the leader here, the servers run --forward off; forwarded with it on), never NOTFOUND and never an answer
       * from the old replica's rows (cvolset_mgr.c's header) */
        tsdbc *cr = client(R);
        nrows = 0;
        int rc = tsdbc_query_raw(cr, id, 0, INT64_MAX / 2, count_rows, NULL);
        expect_moved(cr, rc, 1, ids[L], L, "a read through the removed server");
        if (nrows != 0)
            die("a read through the removed server %d delivered %d rows before its MOVED", R, nrows);
        tsdbc_close(cr);
    }
    tsdbc_close(c);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, 0, 0, 0};
    int s[2] = {L, O};
    rep_same_on(s, 2, want, "after a clean stop");
    printf("  server %d removed while paused: its v1 renamed and deleted once it ran again; the two others hold %" PRIu64
           " rows\n", R, rows);
}

/* removesnap: a replica removed while it waits for a snapshot (its source stalls: TSDB_REPLD_TEST=snapsrcstall, the
 * receiver's stall timer is 30 s) leaves no v1.snap: the close of its driver ends the volume's snapshot jobs
 * (rsnap_closed), whose worker removes the directory. Before, nothing ticked the job of a closed driver, and no open of
 * v1 followed for snap_leftovers: jepsen-cluster churn found an empty v1.snap on a member a cancelled move had joined.
 * Mutant snapclosekeep. */
static void scen_removesnap(void)
{
    scenario("removesnap");
    for (int i = 0; i < 3; i++)
        penv[i] = "TSDB_REPLD_TEST=snapsrcstall";
    struct meta_volume v;
    init_retain_s = 2;
    int L = set_setup(3, &v, 0), R = (L + 1) % 3, O = (L + 2) % 3;
    init_retain_s = 0;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t t = 1000;
    uint64_t rows = set_write(c, id, &t, 3, 1);
    await_isr(0, "plant", 3, 10000, "every replica up");
    stop(R, SIGKILL);
    await_isr(0, "plant", 2, 10000, "a replica killed");
    struct timespec s1 = {1, 0};
    for (int r = 0; r < 7; r++) { /* past the keep cap: R needs a snapshot when it comes back */
        rows += set_write(c, id, &t, 1, 1);
        nanosleep(&s1, NULL);
    }
    rows += set_write(c, id, &t, 1, 0);
    start(R);
    await_log(R, "asks the leader for one", 30000, "the replica back never asked for a snapshot");
    await_log(L, "(snapsrcstall)", 20000, "the leader's first source never stalled");
    if (!dir_has(R, "v1.snap"))
        die("server %d has no v1.snap while its source stalls: the test proves nothing", R);
    char res[512], op[64];
    snprintf(op, sizeof op, "remove 1 %" PRIu32, ids[R]);
    set_op(3, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("remove: %s", res);
    await_member(0, "plant", R, 0, 2, 10000, &v);
    await_log_count(R, "this server's replica was removed from the replica set", 1, 20000);
    if (log_has(R, "snapshot installed"))
        die("server %d installed its snapshot before the removal: the test proves nothing", R);
    uint64_t t0 = now_ms();
    while (dir_has(R, "v1"))
        if (now_ms() - t0 > 20000)
            die("server %d still has v1 or v1.snap 20 s after its removal (abandoned: %d)", R,
                log_has(R, "the replica is closed here"));
        else
            usleep(50000);
    double gone_s = (double)(now_ms() - t0) / 1000;
    rows += set_write(c, id, &t, 2, 0);
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, 0, 0, 0};
    int s[2] = {L, O};
    rep_same_on(s, 2, want, "after a clean stop");
    printf("  server %d removed while its snapshot's source stalled: its job abandoned and v1.snap removed in %.1f s\n",
           R, gone_s);
}

/* removeindex: REMOVE of a member at a lower index than another (the members after it shift down, the leader's own
 * index too when it was above) under writes: the leader's driver remaps its per-peer state (cursors, acks, the keep
 * bound's input), so the writes go on being committed by the member that stays, which holds every row at the end.
 * Mutant setdrvnoremap (the core remapped, the driver's peers not). */
static void scen_removeindex(void)
{
    scenario("removeindex");
    struct meta_volume v;
    int L = set_setup(3, &v, 0), li = rep_index(&v, L), R = -1, F = -1, ri = -1;
    for (uint32_t k = 0; k < v.nrep; k++) { /* R: the lowest index that is not the leader's; F: the other */
        int s = server_of(v.rep[k].node);
        if (s == L)
            continue;
        if (R < 0)
            R = s, ri = (int)k;
        else
            F = s;
    }
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t t = 1000;
    uint64_t rows = set_write(c, id, &t, 3, 1);
    await_isr(0, "plant", 3, 10000, "every replica up");
    struct set_writer w = {.port = cports[L], .id = id, .t = 10000000};
    pthread_t th;
    if (pthread_create(&th, NULL, set_write_thread, &w) != 0)
        die("pthread_create");
    await_batches(&w, 20, 20000);
    pause_server(R, 1);
    await_isr(0, "plant", 2, 20000, "a replica paused");
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    await_batches(&w, 20, 20000);
    char res[512], op[64];
    snprintf(op, sizeof op, "remove 1 %" PRIu32, ids[R]);
    set_op(3, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("remove: %s", res);
    struct meta_volume shr = v; /* the shrink's record: its commit point is where the paused R's ack stopped */
    await_member(0, "plant", R, 0, 2, 10000, &v);
    char line[160];
    snprintf(line, sizeof line, "this is replica %d of 2", rep_index(&v, L));
    await_log_count(L, line, 1, 20000);
    { /* the driver carried F's own ack over to F's new index: past the shrink's commit point, which the writes after
       * the shrink passed with F's acks alone (setdrvnoremap: R's stale ack or the leader's own empty slot) */
        char path[PATH_MAX + 80], buf[1 << 16], pat[64];
        snprintf(path, sizeof path, "%s/n%d.log", base, L);
        slurp(path, buf, sizeof buf);
        char *at = strstr(buf, "replica set version");
        snprintf(pat, sizeof pat, "%" PRIu32 " (acked ", ids[F]);
        char *nl = at ? strchr(at, '\n') : NULL, *q = at ? strstr(at, pat) : NULL;
        if (!q || (nl && q > nl))
            die("server %d's set change line names no ack for server %d: %.300s", L, F, at ? at : "(none)");
        uint64_t ack = strtoull(q + strlen(pat), NULL, 10);
        if (!shr.isr_commit || ack <= shr.isr_commit)
            die("the driver carried an ack of %" PRIu64 " over for server %d, not past the shrink's commit point %" PRIu64,
                ack, F, shr.isr_commit);
        printf("  server %d's ack %" PRIu64 " carried over to index %d (the shrink's commit point %" PRIu64 ")\n", F,
               ack, rep_index(&v, F), shr.isr_commit);
    }
    /* the stale slot of the removed member must not stand for F: F's ACKs alone carry the commit point now, and a
     * pause of F stops it */
    await_batches(&w, 50, 30000);
    pause_server(F, 1);
    usleep(300000);
    uint64_t b0 = __atomic_load_n(&w.batches, __ATOMIC_ACQUIRE);
    usleep(700000);
    uint64_t b1 = __atomic_load_n(&w.batches, __ATOMIC_ACQUIRE);
    pause_server(F, 0);
    if (b1 != b0)
        die("%" PRIu64 " writes were acknowledged without the one member left beside the leader", b1 - b0);
    await_batches(&w, 50, 30000);
    __atomic_store_n(&w.stop, 1, __ATOMIC_RELEASE);
    pthread_join(th, NULL);
    if (w.rc != 0)
        die("a write across the remove: %s", ers(w.rc));
    rows += w.acked;
    rows += set_write(c, id, &t, 2, 0);
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    pause_server(R, 0);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, 0, 0, 0};
    int s[2] = {L, F};
    rep_same_on(s, 2, want, "after a clean stop");
    printf("  index %d removed (the leader was index %d), %" PRIu64 " batches answered in 0.7 s with the member that"
           " stays paused; %" PRIu64 " rows on the two\n", ri, li, b1 - b0,
           rows);
}

/* removedown: a member's server down through its REMOVE, then started: v1 is set aside (v1.removed-<rid>, deleted) and
 * never opened; an ADD of that node then makes a fresh v1 that fills and joins. Again with the server down through the
 * REMOVE and the ADD: its v1 holds the old rid, is kept as v1.stale-<rid> and never opened, and a fresh v1 joins.
 * Mutant staleopen (the prepare opens a v1 of another rid). */
static void scen_removedown(void)
{
    scenario("removedown");
    struct meta_volume v;
    int L = set_setup(3, &v, 1), R = (L + 1) % 3;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t t = 1000;
    uint64_t rows = set_write(c, id, &t, 3, 0);
    await_isr(0, "plant", 3, 10000, "every replica up");
    char res[512], op[64];
    for (int pass = 0; pass < 2; pass++) {
        uint64_t oldrid = rep_of(&v, R)->rid;
        stop(R, SIGTERM);
        await_isr(0, "plant", 2, 20000, "a replica stopped");
        snprintf(op, sizeof op, "remove 1 %" PRIu32, ids[R]);
        set_op(3, op, res, sizeof res);
        if (!strstr(res, "proposed"))
            die("remove: %s", res);
        await_member(0, "plant", R, 0, 2, 10000, &v);
        rows += set_write(c, id, &t, 2, 0);
        if (pass == 0) { /* started after the REMOVE alone: v1 goes */
            int opens = log_count(R, "volume 1 (plant): open as the");
            start(R);
            uint64_t t0 = now_ms();
            while (dir_has(R, "v1"))
                if (now_ms() - t0 > 20000)
                    die("server %d still has v1 or v1.removed-* 20 s after it started", R);
                else
                    usleep(50000);
            if (log_count(R, "volume 1 (plant): open as the") != opens)
                die("server %d opened the removed volume", R);
        }
        snprintf(op, sizeof op, "add 1 %" PRIu32, ids[R]);
        set_op(3, op, res, sizeof res);
        if (!strstr(res, "proposed"))
            die("pass %d: add: %s", pass, res);
        await_member(0, "plant", R, 1, 3, 10000, &v);
        if (rep_of(&v, R)->rid == oldrid)
            die("the ADD kept the removed replica's rid");
        if (pass == 1) /* started after the REMOVE and the ADD: the old v1 is another identity */
            start(R);
        rows += set_write(c, id, &t, 2, 0);
        await_isr(0, "plant", 3, 60000, "the added replica filled and joined");
        char stale[64];
        snprintf(stale, sizeof stale, "v1.stale-%016" PRIx64, oldrid);
        if (dir_has(R, stale) != pass)
            die("pass %d: server %d %s %s", pass, R, pass ? "has no" : "has", stale);
    }
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, 0, 0, 0};
    int s[3] = {0, 1, 2};
    rep_same_on(s, 3, want, "after a clean stop");
    printf("  removed while down: set aside at start, then added fresh; removed and added while down: v1.stale-* kept,"
           " fresh v1 joined; %" PRIu64 " rows on all three\n", rows);
}

/* setstale: a member held on the old set version (TSDB_REPLD_TEST=setstale, its <dir>/setstale) while a 4th replica is
 * added: it drops the leader's messages of version 2 (the line counts them), takes none, and leaves the ISR; the
 * others go on; let go, it applies the change and joins. Mutant setnoversion (no check: the stale member's messages are taken). */
static void scen_setstale(void)
{
    scenario("setstale");
    struct meta_volume v;
    for (int i = 0; i < 4; i++)
        penv[i] = "TSDB_REPLD_TEST=keepall,setstale";
    int L = set_setup(4, &v, 0), X = -1, S = -1;
    for (int i = 0; i < 4; i++)
        if (rep_index(&v, i) < 0)
            X = i;
        else if (i != L && S < 0)
            S = i;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t t = 1000;
    uint64_t rows = set_write(c, id, &t, 3, 0);
    await_isr(0, "plant", 3, 10000, "every replica up");
    char held[PATH_MAX + 120];
    server_dir(S, held, sizeof held);
    strcat(held, "/setstale");
    int fd = open(held, O_CREAT | O_WRONLY, 0644);
    if (fd < 0 || close(fd) != 0)
        die("%s: %s", held, strerror(errno));
    char res[512], op[64];
    snprintf(op, sizeof op, "add 1 %" PRIu32, ids[X]);
    set_op(4, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("add: %s", res);
    await_log_count(S, "setstale: kept on replica set version 1", 1, 20000);
    for (int k = 0; k < 20; k++)
        rows += set_write(c, id, &t, 1, 0), usleep(50000);
    /* the held member is the one that hears of the other version: the leader's APPENDs at version 2 (it sends nothing
     * the leader would drop, having taken none of them) */
    await_log_count(S, "messages of another replica set version (the last: version 2", 1, 20000);
    struct meta_volume nv;
    uint64_t t0 = now_ms();
    for (;;) { /* the ISR: the leader, the other member and the learner; never the held one */
        if (vol_rec(0, "plant", &nv) && nv.nisr == 3 && !meta_volume_in_isr(&nv, ids[S]))
            break;
        if (now_ms() - t0 > 60000)
            die("the ISR is not the three members on version 2 (%" PRIu32 " members, the held one %s)", nv.nisr,
                meta_volume_in_isr(&nv, ids[S]) ? "in it" : "out");
        rows += set_write(c, id, &t, 1, 0);
        usleep(100000);
    }
    unlink(held);
    await_isr(0, "plant", 4, 60000, "the held member let go, on version 2");
    rows += set_write(c, id, &t, 2, 0);
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, 0, 0, 0};
    int s[4] = {0, 1, 2, 3};
    rep_same_on(s, 4, want, "after a clean stop");
    printf("  server %d held on version 1: its messages dropped, out of the ISR; let go, it joined; %" PRIu64
           " rows on all four\n", S, rows);
}

/* resetlost: a stopped replica's v1 removed is refused at its start with a line naming `tsdb cluster replica reset`;
 * a reset of an ISR member or of the leader is refused with the reason; the reset of the lost one makes a fresh v1
 * that fills and joins, with no v1.lost-* (no directory existed). Then a stopped replica whose v1 is still there is
 * reset (its v1 set aside as v1.stale-<old rid>: down, it never saw the reset), and a paused one (it sees the reset when
 * let go: v1.lost-<old rid>). After each the leader's set change line names it new. Mutants resetinisr (the reason is
 * missing), resetsamerid (the reset never applies: no fresh replica), makemissing (the missing v1 is made again by
 * itself), setoldofnode (the leader carries the old replica's ack over), lostasstale (stale- where lost- is due). */
static void scen_resetlost(void)
{
    scenario("resetlost");
    struct meta_volume v;
    int L = set_setup(3, &v, 0), R = (L + 1) % 3;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t t = 1000;
    uint64_t rows = set_write(c, id, &t, 3, 0);
    await_isr(0, "plant", 3, 10000, "every replica up");
    char p0[META_ADDR_MAX], args[PATH_MAX * 2 + 512], out[8192];
    peer_of(0, p0, sizeof p0);
    for (int k = 0; k < 2; k++) { /* the leader, then an ISR member: refused with the reason */
        int who = k ? R : L;
        snprintf(args, sizeof args, "cluster replica reset %s 1 %" PRIu32 " --secret-file %s", p0, ids[who],
                 secret_path);
        int rc = cli_run(args, NULL, out, sizeof out);
        if (rc == 0 || !strstr(out, k ? "is in the ISR" : "leads volume 1"))
            die("a reset of %s: exit %d: %s", k ? "an ISR member" : "the leader", rc, out);
    }
    stop(R, SIGTERM);
    await_isr(0, "plant", 2, 20000, "a replica stopped");
    uint64_t oldrid = rep_of(&v, R)->rid;
    char d[PATH_MAX + 120], cmd[PATH_MAX + 200];
    server_dir(R, d, sizeof d);
    snprintf(cmd, sizeof cmd, "rm -rf '%s/v1'", d);
    if (system(cmd) != 0)
        die("%s", cmd);
    rows += set_write(c, id, &t, 2, 0);
    start(R);
    /* either the refusal's line or a v1 made, whichever comes first: a start that remakes it never logs the line */
    uint64_t r0 = now_ms();
    while (log_count(R, "tsdb cluster replica reset") < 1 && !dir_has(R, "v1"))
        if (now_ms() - r0 > 20000)
            die("server %d: no line naming `tsdb cluster replica reset` 20 s after it started", R);
        else
            usleep(50000);
    if (dir_has(R, "v1"))
        die("server %d made a v1 for a replica the group recorded as opened", R);
    /* pass 0: no directory; pass 1: stopped through the reset, its v1 still there (a server down through its reset
     * cannot tell it from a REMOVE and an ADD: the reset note is in memory only, so stale-<rid>); pass 2: running and
     * paused out of the ISR through the reset, then let go: it sees the reset, lost-<rid> */
    for (int pass = 0; pass < 3; pass++) {
        if (pass == 1) {
            stop(R, SIGTERM);
            await_isr(0, "plant", 2, 20000, "a replica stopped");
        } else if (pass == 2) {
            pause_server(R, 1);
            await_isr(0, "plant", 2, 20000, "a replica paused");
        }
        snprintf(args, sizeof args, "cluster replica reset %s 1 %" PRIu32 " --secret-file %s", p0, ids[R], secret_path);
        int rc = cli_run(args, NULL, out, sizeof out);
        if (rc != 0 || !strstr(out, "proposed"))
            die("the reset of server %d: exit %d: %s", R, rc, out);
        uint64_t t0 = now_ms();
        struct meta_volume nv;
        while (!vol_rec(0, "plant", &nv) || !rep_of(&nv, R) || rep_of(&nv, R)->rid == oldrid)
            if (now_ms() - t0 > 10000)
                die("the reset of server %d did not apply", R);
            else
                usleep(50000);
        if (pass == 1)
            start(R);
        else if (pass == 2)
            pause_server(R, 0);
        rows += set_write(c, id, &t, 2, 0);
        await_isr(0, "plant", 3, 60000, "the reset replica filled and joined");
        /* the leader's driver took the reset member as new (old_of by node and rid): no ack of the old replica carried
         * over to the fresh one (mutant setoldofnode) */
        char nn[2][48];
        snprintf(nn[0], sizeof nn[0], "nodes %" PRIu32 " (new)", ids[R]);
        snprintf(nn[1], sizeof nn[1], ", %" PRIu32 " (new)", ids[R]);
        if (log_count(L, nn[0]) + log_count(L, nn[1]) < pass + 1)
            die("pass %d: the leader's set change lines name server %d (node %" PRIu32 ") new %d times, not %d", pass,
                R, ids[R], log_count(L, nn[0]) + log_count(L, nn[1]), pass + 1);
        char lost[64], stale[64];
        snprintf(lost, sizeof lost, "v1.lost-%016" PRIx64, oldrid);
        snprintf(stale, sizeof stale, "v1.stale-%016" PRIx64, oldrid);
        int hl = dir_has(R, lost), hs = dir_has(R, stale);
        if (pass == 0 ? hl || hs : pass == 1 ? hl || !hs : !hl || hs)
            die("pass %d: server %d holds %s%s%s, not %s", pass, R, hl ? lost : "", hl && hs ? " and " : "",
                hs ? stale : hl ? "" : "neither", pass == 0 ? "neither" : pass == 1 ? stale : lost);
        oldrid = rep_of(&nv, R)->rid;
    }
    if ((uint64_t)rows_of(c, id) != rows)
        die("the leader reads %d rows, not %" PRIu64, rows_of(c, id), rows);
    tsdbc_close(c);
    stop_all();
    uint64_t want[REP_NAMES] = {rows, 0, 0, 0};
    int s[3] = {0, 1, 2};
    rep_same_on(s, 3, want, "after a clean stop");
    printf("  a lost v1 refused with the reset's line; reset three times (no directory, stale- when down, lost- when"
           " running): fresh, filled,"
           " %" PRIu64 " rows on all three\n", rows);
}

/* r4stubs (r4-iface): R4's operator verbs reach their stubs on the Raft leader and answer "not built" (each later track
 * replaces its line here with its own scenario), and `tsdb cluster init` stores R4's four settings, which STATUS prints
 * back; out-of-range values are refused by the CLI before anything is sent, and by the group if they get past it. */
static void scen_r4stubs(void)
{
    scenario("r4stubs");
    start(0);
    char p0[META_ADDR_MAX], args[PATH_MAX * 2 + 512], out[8192];
    peer_of(0, p0, sizeof p0);
    static const char *const bad[] = {"--rebuild-max 17",       "--rebuild-max 0",        "--rebuild-mb-s 0",
                                      "--transfer-wait-ms 99",   "--transfer-wait-ms 60001", "--leader-balance-s 86401",
                                      "--leader-balance-s x",    "--leader-balance-s -1"};
    for (size_t k = 0; k < sizeof bad / sizeof bad[0]; k++) {
        snprintf(args, sizeof args, "cluster init %s --secret-file %s --node-timeout-ms 1500 --heartbeat-ms 200 %s", p0,
                 secret_path, bad[k]);
        int rc = cli_run(args, NULL, out, sizeof out);
        if (rc != 2 || strstr(out, "initialised"))
            die("cluster init %s: exit %d (not 2): %s", bad[k], rc, out);
    }
    /* past the CLI: an INIT body with rebuild_max 17 is refused by the state machine (settings_valid) */
    struct meta_settings s;
    meta_settings_default(&s);
    s.node_timeout_ms = 1500, s.heartbeat_ms = 200, s.rebuild_max = 17;
    uint8_t req[4 * (META_SETTINGS_WORDS + 1)], *reply = NULL;
    size_t len = 0, rl = cluster_settings_encode(&s, META_MODE_REPLICATED, req);
    int arc = admin(0, CLUSTER_OP_INIT, req, rl, 0, &reply, &len);
    free(reply);
    if (arc == 0)
        die("an INIT with rebuild_max 17 was taken");
    printf("  out-of-range R4 settings refused (CLI exit 2; the group: %s)\n", cluster_strerror(arc));
    snprintf(args, sizeof args,
             "cluster init %s --secret-file %s --node-timeout-ms 1500 --heartbeat-ms 200 --rebuild-mb-s 150 "
             "--rebuild-max 4 --transfer-wait-ms 3000 --leader-balance-s 120", p0, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "initialised"))
        die("cluster init with R4's settings: %s", out);
    ids[0] = 1;
    await_view(0, p_leader_self, NULL, "leading the initialised cluster");
    snprintf(args, sizeof args, "cluster status %s --secret-file %s", p0, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 ||
        !strstr(out, " rebuild_mb_s 150 rebuild_max 4 transfer_wait_ms 3000 leader_balance_s 120\n"))
        die("status does not print R4's settings as init stored them: %s", out);
    printf("  init stored rebuild_mb_s 150, rebuild_max 4, transfer_wait_ms 3000, leader_balance_s 120\n");
    /* the stubs decode the body and say it back: the CLI's encoding against the server's decoder, field by field */
    static const char *const verbs[][2] = {
        {"volume transfer %s 3 5", "volume 3 to node 5: no such volume"}, /* built (r4-transfer): ctr_admin */
        {"volume move %s 3 --log --from 5 --to 6", "move of volume 3 from node 5 to node 6: no such volume"},
        {"volume move %s 3 --log --from 6 --to 5 --cancel",
         "cancel of the move of volume 3 from node 6 to node 5: no such volume"}, /* built (r4-move): cmove_admin */
        {"replica reset %s 4 6", "volume 4 does not exist"}};
    for (size_t k = 0; k < sizeof verbs / sizeof verbs[0]; k++) {
        char v[256];
        snprintf(v, sizeof v, verbs[k][0], p0);
        snprintf(args, sizeof args, "cluster %s --secret-file %s", v, secret_path);
        int rc = cli_run(args, NULL, out, sizeof out);
        if (rc != 1 || !strstr(out, verbs[k][1]))
            die("tsdb cluster %s: exit %d, not \"%s\": %s", v, rc, verbs[k][1], out);
        printf("  %s: %s", v, out);
    }
    /* the bodies past the CLI: one of another length is refused by the decoders (the stubs say its length) */
    uint8_t body[16] = {0};
    static const uint8_t ops[3] = {CLUSTER_OP_VOLUME_TRANSFER, CLUSTER_OP_VOLUME_MOVE, CLUSTER_OP_REPLICA_RESET};
    for (int k = 0; k < 3; k++) {
        reply = NULL, len = 0;
        arc = admin(0, ops[k], body, 12, 0, &reply, &len);
        const char *says = k == 0   ? "a transfer's body is 8 bytes (got 12)"
                           : k == 2 ? "replica reset: a body of 12 bytes"
                                    : "a move's body is 16 bytes (got 12)";
        if (arc != META_ERR_INVALID || !reply || len < strlen(says) || memcmp(reply, says, strlen(says)))
            die("op %d with a 12-byte body: %s", ops[k], cluster_strerror(arc));
        free(reply);
    }
    /* the CLI's own checks of a move: --log, --from and --to are required, and two different nodes */
    static const char *const badmove[] = {"1 --from 1 --to 2", "1 --log --from 1", "1 --log --from 2 --to 2",
                                          "x --log --from 1 --to 2"};
    for (size_t k = 0; k < sizeof badmove / sizeof badmove[0]; k++) {
        snprintf(args, sizeof args, "cluster volume move %s %s --secret-file %s", p0, badmove[k], secret_path);
        int rc = cli_run(args, NULL, out, sizeof out);
        if (rc != 2)
            die("tsdb cluster volume move %s: exit %d, not 2: %s", badmove[k], rc, out);
    }
}

static int bytes_has(const uint8_t *buf, size_t len, const char *sub)
{
    size_t n = strlen(sub);
    if (!buf || n > len)
        return 0;
    for (size_t i = 0; i + n <= len; i++)
        if (memcmp(buf + i, sub, n) == 0)
            return 1;
    return 0;
}

/* r9stubs (r9-iface): R9's operator verbs reach their stubs on the Raft leader (including via a follower redirect)
 * and answer "not built" against a 3-node cluster without disturbing cluster health. */
static void scen_r9stubs(void)
{
    scenario("r9stubs");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned three = 3;
    await_view(0, p_voters, &three, "3 voters up before r9stubs");
    await_view(1, p_names_leader, &ids[0], "follower 1 knows leader before r9stubs");
    uint32_t vnum = 0;
    int rc = vol_add(0, "r9health", 3, &vnum);
    if (rc != 0 || vnum != 1)
        die("volume add r9health before r9stubs: %s", cluster_strerror(rc));
    char p0[META_ADDR_MAX], p1[META_ADDR_MAX], args[PATH_MAX * 2 + 512], out[8192];
    peer_of(0, p0, sizeof p0);
    peer_of(1, p1, sizeof p1);
    /* Each R9 CLI verb hits the Raft leader (half via follower p1 to verify NOTLEADER redirect) and returns a clear
     * refusal reason on invalid targets/preconditions without disturbing cluster state. */
    static const struct {
        const char *fmt;
        int via_follower;
        const char *expect;
    } verbs[] = {
        {"node hold %s 99 --for 600s", 0, "unknown node 99"},
        {"node hold %s 99 --release", 1, "unknown node 99"},
        {"node out %s 99", 0, "unknown node 99"},
        {"node drain %s 99", 1, "unknown node 99"},
        {"node drain %s 2 --cancel", 1, "not draining"},
        {"node replace %s 2 3", 0, "already holds"},
        {"node destroyed %s 2", 1, "not out"},
        {"volume move %s 1 --pos 0 --to 2", 1, "not erasure-coded"},
    };
    for (size_t k = 0; k < sizeof verbs / sizeof verbs[0]; k++) {
        char v[256];
        snprintf(v, sizeof v, verbs[k].fmt, verbs[k].via_follower ? p1 : p0);
        snprintf(args, sizeof args, "cluster %s --secret-file %s", v, secret_path);
        int crc = cli_run(args, NULL, out, sizeof out);
        if (crc != 1 || !strstr(out, verbs[k].expect))
            die("tsdb cluster %s: exit %d, wanted \"%s\": %s", v, crc, verbs[k].expect, out);
        printf("  %s: %s", v, out);
    }
    /* Malformed bodies sent directly to the leader are refused by each decoder with META_ERR_INVALID. */
    uint8_t badbody[16] = {0};
    static const uint8_t r9ops[6] = {CLUSTER_OP_NODE_HOLD,    CLUSTER_OP_NODE_OUT,       CLUSTER_OP_NODE_DRAIN,
                                     CLUSTER_OP_NODE_REPLACE, CLUSTER_OP_NODE_DESTROYED, CLUSTER_OP_VOLUME_MOVE_POS};
    for (int k = 0; k < 6; k++) {
        uint8_t *reply = NULL;
        size_t len = 0;
        int arc = admin(0, r9ops[k], badbody, 5, 0, &reply, &len);
        if (arc != META_ERR_INVALID || !bytes_has(reply, len, "got 5"))
            die("op %u with 5-byte body: rc %d (%s)", r9ops[k], arc, cluster_strerror(arc));
        free(reply);
    }
    /* D23 init flags are wired into meta_settings (r9-meta); sending init to an already-init cluster returns exit 1
     * ("already") rather than exit 2 ("not built" / usage error). */
    snprintf(args, sizeof args,
             "cluster init %s --secret-file %s --opening-hold-s 600 --failstop-out-s 30 --out-guard-pct 20 "
             "--out-guard-hold-s 3600 --repl-retain-down-gb 32 --young-high-pct 85 --balance-mb-s 100 "
             "--rebuild-concurrency 2",
             p0, secret_path);
    int irc = cli_run(args, NULL, out, sizeof out);
    if (irc != 1 || strstr(out, "not built"))
        die("tsdb cluster init with D23 flags: exit %d, wanted 1 (already init): %s", irc, out);
    /* CLI argument validation errors exit 2 before contacting the server. */
    static const char *const badcli[] = {
        "node hold %s 2",
        "node hold %s 2 --for 60s --release",
        "node hold %s 2 --for 86401s",
        "node replace %s 2 2",
        "volume move %s 1 --log --pos 0 --to 2",
        "volume move %s 1 --pos 0",
        "volume move %s 1 --pos 99 --to 2",
    };
    for (size_t k = 0; k < sizeof badcli / sizeof badcli[0]; k++) {
        char v[256];
        snprintf(v, sizeof v, badcli[k], p0);
        snprintf(args, sizeof args, "cluster %s --secret-file %s", v, secret_path);
        int crc = cli_run(args, NULL, out, sizeof out);
        if (crc != 2)
            die("tsdb cluster %s: exit %d, wanted 2: %s", v, crc, out);
    }
    /* Verify the 3-node cluster remains completely healthy after all checks. */
    await_view(0, p_voters, &three, "3 voters still up after r9stubs");
    for (int i = 0; i < 3; i++) {
        struct state_want w = {ids[i], META_UP, 1};
        await_view(0, p_member_state, &w, "member still UP after r9stubs");
    }
    printf("  cluster healthy after r9stubs: 3 nodes up, volume r9health (#%" PRIu32 ")\n", vnum);
}

/* opening (r9-hb; D5, D17): HBS_NODE reports opening=1 from cluster thread start until every startup volume finishes
 * its first open (TSDB_CLUSTER_TEST slow_open_ms=5000 holds the first open for 5 s), then clears to 0 and does NOT
 * return to 1 when a new volume is added later; fill_pct reports real statvfs (0..100) and obeys fill_pct=N override. */
static void scen_opening(void)
{
    scenario("opening");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned three = 3;
    await_view(0, p_voters, &three, "3 voters up before opening");
    /* Verify real statvfs fill_pct is reported (0..100) and opening cleared to 0 with 0 startup volumes. */
    uint64_t t0 = now_ms();
    int settled_ok = 0;
    while (!settled_ok && now_ms() - t0 < 10000) {
        struct view vw;
        view(0, &vw);
        int ok = 1;
        for (int i = 0; i < 3; i++) {
            const struct cluster_heard *h = NULL;
            for (uint32_t k = 0; k < vw.st.nheard; k++)
                if (vw.st.heard[k].id == ids[i])
                    h = &vw.st.heard[k];
            if (!h || h->opening != 0 || h->fill_pct > 100)
                ok = 0;
        }
        view_free(&vw);
        if (ok)
            settled_ok = 1;
        else
            usleep(100000);
    }
    if (!settled_ok)
        die("servers with 0 startup volumes did not report opening=0 and valid fill_pct <= 100");
    uint32_t v1 = 0;
    int rc = vol_add(0, "op1", 3, &v1);
    if (rc != 0 || v1 == 0)
        die("vol_add op1: %s", cluster_strerror(rc));
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "op1", i, 1, 0);
    /* Restart server 1 with slow_open_ms=5000 and fill_pct=73: beats must say opening=1 until the 5 s open ends. */
    stop(1, SIGTERM);
    envs[1] = "slow_open_ms=5000,fill_pct=73";
    start(1);
    t0 = now_ms();
    uint64_t seen_open_ms = 0, cleared_ms = 0;
    int saw_opening = 0, saw_fill = 0;
    while (now_ms() - t0 < 20000) {
        struct view vw;
        view(0, &vw);
        const struct cluster_heard *h = NULL;
        for (uint32_t k = 0; k < vw.st.nheard; k++)
            if (vw.st.heard[k].id == ids[1])
                h = &vw.st.heard[k];
        if (h && h->incarnation >= 2) {
            if (h->fill_pct == 73)
                saw_fill = 1;
            if (h->opening == 1) {
                if (!saw_opening) {
                    saw_opening = 1;
                    seen_open_ms = now_ms();
                }
            } else if (saw_opening) {
                cleared_ms = now_ms();
                view_free(&vw);
                break;
            }
        }
        view_free(&vw);
        usleep(100000);
    }
    if (!saw_opening)
        die("leader never observed opening=1 from server 1 during slow_open_ms=5000 restart");
    if (!cleared_ms)
        die("server 1 never cleared opening back to 0 after slow_open_ms=5000");
    if (cleared_ms - seen_open_ms < 3000)
        die("server 1 cleared opening too early (%" PRIu64 " ms < 3000 ms for slow_open_ms=5000)",
            cleared_ms - seen_open_ms);
    if (!saw_fill)
        die("leader never observed fill_pct=73 override from server 1");
    /* A volume added AFTER startup must NOT set opening=1 again (even while delayed by slow_open_ms=5000). */
    uint32_t v2 = 0;
    if ((rc = vol_add(0, "op2", 3, &v2)) != 0 || v2 == 0)
        die("vol_add op2: %s", cluster_strerror(rc));
    char open_line[128];
    snprintf(open_line, sizeof open_line, "volume %" PRIu32 " (op2): open as", v2);
    t0 = now_ms();
    while (!log_has(1, open_line) && now_ms() - t0 < 20000) {
        struct view vw;
        view(0, &vw);
        for (uint32_t k = 0; k < vw.st.nheard; k++)
            if (vw.st.heard[k].id == ids[1] && vw.st.heard[k].opening != 0)
                die("server 1 set opening=1 again when volume op2 was added after startup");
        view_free(&vw);
        usleep(100000);
    }
    if (!log_has(1, open_line))
        die("server 1 did not finish opening op2 within 20 s");
    printf("  opening=1 held for %" PRIu64 " ms during slow_open_ms=5000, cleared to 0, stayed 0 on later vol_add; "
           "fill_pct=73 verified\n",
           cleared_ms - seen_open_ms);
    stop_all();
}

/* failgasp (r9-hb; D5): a fail-stop sends one last failstop=1 beat (<= 100 ms) before exiting 1; the Raft leader
 * records META_DOWN with META_DOWN_FAILSTOP within one beat (well below node_timeout_ms=20000). Tests both the
 * cluster-thread fail-stop path (real crashfs EIO on Raft log fdatasync on server 1, skipped under ASan) and the
 * tsdbd failwatch_main exit-1 path (injected root EIO via fail_root_file=1 on server 2), plus restart recovery back
 * to META_UP. With mutant `nogasp` (TSDB_CLUSTER_MUTANT=nogasp or TSDB_CLUSTER_TEST=nogasp=1), no last beat is sent
 * and the leader does not mark the node down/failstop in time, failing the test. */
static void scen_failgasp(void)
{
    scenario("failgasp");
    const char *so = NULL;
    const char *skip = crashfs_skip(&so);
    const char *ct = getenv("TSDB_CLUSTER_TEST");
    int nogasp = ct && strstr(ct, "nogasp=1");
    static char pe1[PATH_MAX * 3 + 256];
    char dir1[PATH_MAX + 80], state1[PATH_MAX + 96], mark1[PATH_MAX + 80];
    server_dir(1, dir1, sizeof dir1);
    snprintf(state1, sizeof state1, "%s/state", dir1);
    snprintf(mark1, sizeof mark1, "%s/eio-n1", base);
    if (!skip) {
        if ((mkdir(dir1, 0755) != 0 && errno != EEXIST) || (mkdir(state1, 0700) != 0 && errno != EEXIST))
            die("mkdir %s: %s", state1, strerror(errno));
        snprintf(pe1, sizeof pe1,
                 "LD_PRELOAD=%s CRASHFS_ROOT=%s CRASHFS_MODE=eio CRASHFS_EIO_ON=fdatasync CRASHFS_MARK=%s", so, state1,
                 mark1);
        penv[1] = pe1;
    }
    if (nogasp)
        envs[1] = "nogasp=1";
    envs[2] = nogasp ? "fail_root_file=1,nogasp=1" : "fail_root_file=1";
    for (int i = 0; i < 3; i++)
        start(i);
    init_node_timeout_ms = 20000;
    init_cluster(0, 600);
    init_node_timeout_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned three = 3;
    await_view(0, p_voters, &three, "3 voters up before failgasp");
    await_view(1, p_names_leader, &ids[0], "server 1 knows leader 0");
    await_view(2, p_names_leader, &ids[0], "server 2 knows leader 0");

    /* Part 1: real crashfs EIO on server 1's Raft log fdatasync -> cluster.c fail_stop() -> exit 1. */
    if (!skip) {
        signal_child(pids[1], SIGUSR2);
        uint32_t vnum = 0;
        int rc = vol_add(0, "fgvol", 3, &vnum);
        if (rc != 0 || vnum == 0)
            die("vol_add fgvol during EIO test: %s", cluster_strerror(rc));
        uint64_t t_eio = now_ms();
        int st = await_exit(1, 5000);
        if (st != 1)
            die("server 1 exited with %d on state-dir EIO, expected 1 (fail-stop)", st);
        int got_fs = 0;
        uint64_t t_down = 0;
        uint8_t seen_state = META_UP, seen_reason = META_DOWN_NONE;
        while (now_ms() - t_eio < 4000) {
            struct view vw;
            view(0, &vw);
            const struct meta_member *m = meta_member(&vw.m, ids[1]);
            if (m) {
                seen_state = m->state;
                seen_reason = m->down_reason;
                if (m->state == META_DOWN && m->down_reason == META_DOWN_FAILSTOP && m->down_since_ms > 0) {
                    got_fs = 1;
                    t_down = now_ms();
                    view_free(&vw);
                    break;
                }
            }
            view_free(&vw);
            usleep(50000);
        }
        if (!got_fs)
            die("leader 0 did not record server 1 DOWN/failstop within 4 s of state-dir EIO (state=%s reason=%s)",
                meta_member_state_name(seen_state), meta_down_reason_name(seen_reason));
        printf("  state-dir EIO fail-stop on server 1 recorded DOWN/failstop on leader in %" PRIu64
               " ms (node_timeout 20000 ms)\n",
               t_down - t_eio);
        /* Restart server 1 (without EIO preload) and verify it comes back UP with down_reason NONE. */
        penv[1] = NULL;
        start(1);
        struct state_want w1 = {ids[1], META_UP, 2};
        await_view(0, p_member_state, &w1, "server 1 back UP after restart");
        struct view vw;
        view(0, &vw);
        const struct meta_member *m1 = meta_member(&vw.m, ids[1]);
        if (!m1 || m1->down_reason != META_DOWN_NONE || m1->down_since_ms != 0)
            die("restarted server 1 still carries down_reason/down_since_ms");
        view_free(&vw);
    }

    /* Part 2: tsdbd.c failwatch_main path -> cluster_failstop_beat(100) -> exit 1 on server 2.
     * Also verify the promo_step lease guard: a volume led by server 2 is NOT promoted to epoch+1 before
     * promote_safe_ns (lease_ms=2000) even though server 2 is marked DOWN/failstop immediately (mutant failstoppromo). */
    struct meta_volume fgmv;
    if (!vol_rec(0, "fgvol", &fgmv)) {
        uint32_t vnum = 0;
        int rc = vol_add(0, "fgvol", 3, &vnum);
        if (rc != 0 || vnum == 0)
            die("vol_add fgvol before part 2: %s", cluster_strerror(rc));
        for (int i = 0; i < 3; i++)
            await_open_gen(0, "fgvol", i, 1, 0);
        if (!vol_rec(0, "fgvol", &fgmv))
            die("no record of fgvol before part 2");
    }
    await_isr(0, "fgvol", 3, 30000, "all 3 replicas in ISR of fgvol before part 2");
    if (fgmv.leader != ids[2]) {
        uint8_t tbody[8];
        size_t tblen = cluster_volume_force_encode(fgmv.number, ids[2], tbody);
        uint8_t *treply = NULL;
        size_t trlen = 0;
        int trc = admin(0, CLUSTER_OP_VOLUME_TRANSFER, tbody, tblen, 1, &treply, &trlen);
        free(treply);
        if (trc != 0)
            die("VOLUME_TRANSFER fgvol to node %" PRIu32 ": %s", ids[2], cluster_strerror(trc));
        uint64_t tw = now_ms();
        while (now_ms() - tw < 15000) {
            if (vol_rec(0, "fgvol", &fgmv) && fgmv.leader == ids[2])
                break;
            usleep(50000);
        }
        if (fgmv.leader != ids[2])
            die("fgvol did not transfer to server 2");
    }
    await_isr(0, "fgvol", 3, 30000, "all 3 replicas in ISR of fgvol under server 2");
    /* Let server 2 receive a fresh lease-granting HB_ACK (heartbeat_ms=200, lease_ms=2000) right before fail-stop. */
    usleep(300000);
    uint64_t e0 = fgmv.epoch;
    char dir2[PATH_MAX + 80], froot[PATH_MAX + 96];
    server_dir(2, dir2, sizeof dir2);
    snprintf(froot, sizeof froot, "%s/failroot", dir2);
    FILE *ff = fopen(froot, "w");
    if (!ff || fclose(ff) != 0)
        die("create %s: %s", froot, strerror(errno));
    uint64_t t_root = now_ms();
    int got_fs2 = 0, got_promo = 0;
    uint64_t t_down2 = 0, t_promo = 0;
    uint8_t seen_state2 = META_UP, seen_reason2 = META_DOWN_NONE;
    while (!(got_fs2 && got_promo) && now_ms() - t_root < 15000) {
        struct view vw;
        view(0, &vw);
        const struct meta_member *m = meta_member(&vw.m, ids[2]);
        if (m) {
            seen_state2 = m->state;
            seen_reason2 = m->down_reason;
            if (!got_fs2 && m->state == META_DOWN && m->down_reason == META_DOWN_FAILSTOP && m->down_since_ms > 0) {
                got_fs2 = 1;
                t_down2 = now_ms();
            }
        }
        const struct meta_volume *v = meta_volume(&vw.m, fgmv.number);
        if (!got_promo && v && v->epoch > e0) {
            got_promo = 1;
            t_promo = now_ms();
        }
        view_free(&vw);
        if (!(got_fs2 && got_promo))
            usleep(50000);
    }
    int st2 = await_exit(2, 5000);
    if (st2 != 1)
        die("server 2 exited with %d on root EIO, expected 1 (fail-stop)", st2);
    if (!got_fs2 || t_down2 - t_root >= 4000)
        die("leader 0 did not record server 2 DOWN/failstop within 4 s of root EIO (state=%s reason=%s)",
            meta_member_state_name(seen_state2), meta_down_reason_name(seen_reason2));
    if (!got_promo)
        die("fgvol was not promoted away from fail-stopped server 2 within 15 s");
    if (t_promo - t_root < 1400)
        die("fgvol promoted too early after failstop beat (%" PRIu64 " ms < 1400 ms; lease_ms 2000 ms)",
            t_promo - t_root);
    printf("  root EIO fail-stop on server 2 recorded DOWN/failstop in %" PRIu64
           " ms (node_timeout 20000 ms); fgvol promoted safely after %" PRIu64 " ms\n",
           t_down2 - t_root, t_promo - t_root);
    stop_all();
}

/* Find the first live *.part file inside vdir (directly or in a partition subdir) and return 1 with its path in out. */
static int find_part_file(const char *vdir, char *out, size_t cap)
{
    DIR *d = opendir(vdir);
    if (!d)
        return 0;
    int found = 0;
    for (struct dirent *e; !found && (e = readdir(d)) != NULL;) {
        size_t nl = strlen(e->d_name);
        if (nl > 5 && strcmp(e->d_name + nl - 5, ".part") == 0 && strncmp(e->d_name, "tmp_", 4) != 0 &&
            strncmp(e->d_name, "stage_", 6) != 0 && strncmp(e->d_name, "retired_", 8) != 0) {
            snprintf(out, cap, "%s/%s", vdir, e->d_name);
            found = 1;
            break;
        }
        if (strncmp(e->d_name, "p_", 2) != 0)
            continue;
        char pdir[PATH_MAX * 2];
        snprintf(pdir, sizeof pdir, "%s/%s", vdir, e->d_name);
        DIR *pd = opendir(pdir);
        if (!pd)
            continue;
        for (struct dirent *pe; !found && (pe = readdir(pd)) != NULL;) {
            size_t pnl = strlen(pe->d_name);
            if (pnl > 5 && strcmp(pe->d_name + pnl - 5, ".part") == 0 && strncmp(pe->d_name, "tmp_", 4) != 0 &&
                strncmp(pe->d_name, "stage_", 6) != 0 && strncmp(pe->d_name, "retired_", 8) != 0) {
                snprintf(out, cap, "%s/%s", pdir, pe->d_name);
                found = 1;
            }
        }
        closedir(pd);
    }
    closedir(d);
    return found;
}

/* faultreason (r9-hb; D6): a replica with a damaged .part file fails its open with TSDB_ERR_CORRUPT and is reported
 * LOCAL_FAULT with fault_reason=CL_FAULT_CORRUPT_OPEN (corrupt-open); a replica with missing REPL is reported
 * LOCAL_FAULT with CL_FAULT_REFUSED; and a v<N>.fault-<rid> directory is logged and left untouched at startup sweep. */
static void scen_faultreason(void)
{
    scenario("faultreason");
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned three = 3;
    await_view(0, p_voters, &three, "3 voters up before faultreason");
    uint32_t v1 = 0, v2 = 0;
    int rc;
    if ((rc = vol_add(0, "fr1", 3, &v1)) != 0 || v1 == 0)
        die("vol_add fr1: %s", cluster_strerror(rc));
    if ((rc = vol_add(0, "fr2", 3, &v2)) != 0 || v2 == 0)
        die("vol_add fr2: %s", cluster_strerror(rc));
    for (int i = 0; i < 3; i++) {
        await_open_gen(0, "fr1", i, 1, 0);
        await_open_gen(0, "fr2", i, 1, 0);
    }
    struct meta_volume mv;
    if (!vol_rec(0, "fr1", &mv))
        die("no record of fr1");
    int L = server_of(mv.leader);
    if (L < 0 || L > 2)
        die("leader of fr1 is %u", mv.leader);
    tsdbc *c = client(L);
    tsdb_sid sid = rep_series(c, rep_names[0], "fr1", 30000);
    for (int k = 0; k < 50; k++) {
        int64_t ts = 1000000 + 1000LL * k;
        float val = (float)k;
        if ((rc = tsdbc_insert_series(c, sid, &ts, &val, 1)) != 0)
            die("write %d to fr1: %s", k, ers(rc));
    }
    if ((rc = tsdbc_flush(c)) != 0)
        die("flush fr1 on leader: %s", ers(rc));
    tsdbc_close(c);
    await_isr(0, "fr1", 3, 30000, "all 3 replicas in ISR for fr1");
    stop(L, SIGTERM);
    /* Corrupt a .part file of v1 on L (flip its footer bytes so eng_open_replica returns TSDB_ERR_CORRUPT). */
    char v1dir[PATH_MAX + 128], pfile[PATH_MAX * 2 + 256];
    snprintf(v1dir, sizeof v1dir, "%s/n%d/v%" PRIu32, base, L, v1);
    if (!find_part_file(v1dir, pfile, sizeof pfile))
        die("no .part file found under %s after clean stop", v1dir);
    {
        int fd = open(pfile, O_RDWR);
        struct stat sb;
        if (fd < 0 || fstat(fd, &sb) != 0 || sb.st_size < 64)
            die("cannot open/stat part %s", pfile);
        uint8_t junk[64];
        if (pread(fd, junk, sizeof junk, sb.st_size - 64) != 64)
            die("pread part footer %s", pfile);
        for (size_t k = 0; k < sizeof junk; k++)
            junk[k] ^= 0xa5;
        if (pwrite(fd, junk, sizeof junk, sb.st_size - 64) != 64 || fsync(fd) != 0)
            die("corrupt part footer %s", pfile);
        close(fd);
    }
    /* Remove v2/REPL on L so v2 is refused (CL_FAULT_REFUSED), and drop a v99.fault-<rid> evidence dir. */
    char r2path[PATH_MAX + 128], fdir[PATH_MAX + 128], fmark[PATH_MAX + 160];
    snprintf(r2path, sizeof r2path, "%s/n%d/v%" PRIu32 "/REPL", base, L, v2);
    if (unlink(r2path) != 0)
        die("unlink %s: %s", r2path, strerror(errno));
    snprintf(fdir, sizeof fdir, "%s/n%d/v99.fault-0123456789abcdef", base, L);
    if (mkdir(fdir, 0755) != 0)
        die("mkdir %s: %s", fdir, strerror(errno));
    snprintf(fmark, sizeof fmark, "%s/keep", fdir);
    FILE *fm = fopen(fmark, "w");
    if (!fm || fputs("evidence\n", fm) < 0 || fclose(fm) != 0)
        die("write %s", fmark);
    /* Restart L and inspect the Raft leader's STATUS view. */
    start(L);
    int via = (L + 1) % 3;
    uint64_t t0 = now_ms();
    int got_corrupt = 0, got_refused = 0;
    while (!(got_corrupt && got_refused) && now_ms() - t0 < 20000) {
        struct view vw;
        view(via, &vw);
        int lead = vw.st.leader ? server_of(vw.st.leader) : via;
        if (lead >= 0 && lead != L && lead != via) {
            view_free(&vw);
            view(lead, &vw);
        }
        for (uint32_t k = 0; k < vw.st.nheard; k++) {
            if (vw.st.heard[k].id != ids[L])
                continue;
            for (uint32_t j = 0; j < vw.st.heard[k].nvols; j++) {
                const struct cluster_vol_report *vr = &vw.st.heard[k].vols[j].v;
                if (vr->volume == v1 && vr->health == CL_HEALTH_LOCAL_FAULT &&
                    vr->fault_reason == CL_FAULT_CORRUPT_OPEN)
                    got_corrupt = 1;
                if (vr->volume == v2 && vr->health == CL_HEALTH_LOCAL_FAULT && vr->fault_reason == CL_FAULT_REFUSED)
                    got_refused = 1;
            }
        }
        view_free(&vw);
        if (!(got_corrupt && got_refused))
            usleep(100000);
    }
    if (!got_corrupt)
        die("leader did not observe LOCAL_FAULT corrupt-open for damaged part on server %d (vol %" PRIu32 ")", L, v1);
    if (!got_refused)
        die("leader did not observe LOCAL_FAULT refused for missing REPL on server %d (vol %" PRIu32 ")", L, v2);
    if (log_count(L, "v99.fault-0123456789abcdef") != 1 || access(fmark, F_OK) != 0)
        die("v99.fault-0123456789abcdef was not logged exactly once or was deleted automatically");
    printf("  damaged part reported LOCAL_FAULT corrupt-open, missing REPL reported refused, v99.fault-<rid> logged "
           "and preserved\n");
    stop_all();
}

/* volcmd (r4-iface): the plumbing R4's tracks build on, before any of them sends. The Raft leader (server 0, hook
 * TSDB_CLUSTER_TEST volcmd_file=1) sends each VOLCMD kind to server 1 (the F_VOLCMD frame) and to itself (the
 * self-delivery of cl_volcmd_send); each server's driver routes it (IN_CMD: TRANSFER and CANCEL to rtransfer.c,
 * DROP_MEMBER to rset.c), which refuses each by name and says the sender. rset_cmd's fences (r4-move review F5): a
 * DROP_MEMBER at an epoch the volume is not at is refused by its leader as "another epoch" (the member: "does not lead
 * it"), and one of an older Raft term than one heard (a deposed Raft leader's) is ignored, naming both terms. And each
 * driver dials the other's snapshot kind (TSDB_REPLD_TEST=snapdial): tsdbd's acceptor hands kind 5 to the driver, whose
 * on_frame passes it to rsnap.c. */
static void scen_volcmd(void)
{
    scenario("volcmd");
    for (int i = 0; i < 2; i++) {
        penv[i] = "TSDB_REPLD_TEST=snapdial";
        envs[i] = "volcmd_file=1";
        start(i);
    }
    init_cluster(0, 600);
    node_add(0, 1); /* a member (a group of two keeps one voter): the volume's replicas need only that */
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "cmdv", 2, &num)) != 0)
        die("volume add cmdv: %s", cluster_strerror(rc));
    for (int i = 0; i < 2; i++)
        await_open_gen(0, "cmdv", i, 1, 0);
    /* R4's admin ops on a follower: NOTLEADER (with the leader's peer address), never handed to the stubs */
    uint8_t body[8], *reply = NULL;
    size_t blen = cluster_volume_force_encode(num, ids[1], body), rlen = 0;
    if ((rc = admin(1, CLUSTER_OP_VOLUME_TRANSFER, body, blen, 0, &reply, &rlen)) != CLUSTER_ERR_NOTLEADER)
        die("a VOLUME_TRANSFER to a follower: %s, not NOTLEADER", cluster_strerror(rc));
    free(reply);
    for (int i = 0; i < 2; i++)
        await_log_count(i, "a snapshot link (kind 5) sent a frame of unknown type", 1, 20000);
    printf("  each driver's kind-5 link reached the other's rsnap_frame\n");
    /* the volume's leader refuses another epoch only once its driver leads (before that it does not lead it either):
     * the commands go out after its "leads epoch" line */
    struct meta_volume mv;
    if (!vol_rec(0, "cmdv", &mv) || server_of(mv.leader) < 0)
        die("cmdv has no leader among the servers");
    int ls = server_of(mv.leader);
    {
        char led[64];
        snprintf(led, sizeof led, "volume %" PRIu32 ": leads epoch ", num);
        await_log_count(ls, led, 1, 20000);
    }
    char path[PATH_MAX + 64];
    server_dir(0, path, sizeof path);
    strcat(path, "/state/volcmd.tmp");
    FILE *f = fopen(path, "w");
    if (!f)
        die("%s: %s", path, strerror(errno));
    for (int i = 0; i < 2; i++) /* TO KIND VOLUME EPOCH NODE ARG */
        for (int k = 1; k <= 3; k++)
            fprintf(f, "%u %d %" PRIu32 " %d %d %d\n", ids[i], k, num, 100 * (i + 1) + k, 7 + k, 4000 + 10 * i + k);
    /* DROP_MEMBER's arg is Raft term << 8 | min_isr: 4002 and 4012 are term 15; then one of term 14 to each (sent after,
     * in file order, on the one link and by the self-delivery) */
    for (int i = 0; i < 2; i++)
        fprintf(f, "%u 2 %" PRIu32 " %d 10 %d\n", ids[i], num, 100 * (i + 1) + 2, 14 << 8 | 1);
    if (fclose(f) != 0)
        die("%s: %s", path, strerror(errno));
    char to[PATH_MAX + 64];
    snprintf(to, sizeof to, "%.*s", (int)(strlen(path) - 4), path);
    if (rename(path, to) != 0)
        die("rename %s: %s", path, strerror(errno));
    for (int i = 0; i < 2; i++)
        for (int k = 1; k <= 2; k++) {
            char line[256];
            if (k == 1) /* rtransfer.c (built): an epoch the volume is not at is refused, by name */
                snprintf(line, sizeof line, "volume %" PRIu32 ": TRANSFER to node %d at epoch %d refused: ", num, 7 + k,
                         100 * (i + 1) + k);
            else /* rset.c: the volume's leader refuses another epoch by name, the member that it does not lead */
                snprintf(line, sizeof line, "volume %" PRIu32 ": DROP_MEMBER of node %d at epoch %d from node %u "
                         "refused: %s", num, 7 + k, 100 * (i + 1) + k, ids[0],
                         i == ls ? "another epoch" : "this node does not lead it");
            await_log_count(i, line, 1, 20000);
        }
    for (int i = 0; i < 2; i++) {
        char line[256];
        snprintf(line, sizeof line, "volume %" PRIu32 ": DROP_MEMBER of node 10 from node %u of Raft term 14 ignored "
                 "(term 15 was heard)", num, ids[0]);
        await_log_count(i, line, 1, 20000);
    }
    /* a CANCEL with no transfer to cancel is silent (a new Raft leader sends one to every volume leader); its routing
     * is test_cluster transferraftkill's */
    if (access(to, F_OK) == 0)
        die("the leader kept %s after sending every command", to);
    printf("  every VOLCMD kind reached the member's and the leader's own driver with its fields\n");
    stop_all();
}

/* ------------------------------------------------------------------ planned leader transfer (r4-transfer, D14, D15) */

struct tr_write {
    uint64_t t0, t1;
    int rc;
};
struct tr_writer {
    int server; /* the member it writes through (forwarded to the leader when not led there) */
    tsdb_sid id;
    int64_t ts; /* the next row's time */
    int stop;
    size_t n, cap;
    struct tr_write *w;
    int acked, refused, indet;
    int noretry; /* no client retries: every refusal (UNAVAILABLE, MOVED) is the writer's own answer (review F4); on
                  * MOVED it goes on through the next member (`via`), so it finds the leader and sees its drains */
    int via, unavail;
    int last_rc;          /* atomic: the latest write's answer (for the failure message) */
    uint64_t last_ack_t0; /* atomic: when the latest acknowledged write began (the scenario waits for one past a
                           * transfer, so that each write's pause belongs to one transfer) */
};

/* one row a write, each outcome recorded after the client's own retries (UNAVAILABLE PROMOTING, MOVED: 10 s) */
static void *tr_write_thread(void *a)
{
    struct tr_writer *w = a;
    tsdbc *c = NULL;
    while (!__atomic_load_n(&w->stop, __ATOMIC_ACQUIRE)) {
        if (!c) {
            int through = w->noretry ? w->via : w->server;
            if (tsdbc_connect("127.0.0.1", __atomic_load_n(&cports[through], __ATOMIC_RELAXED), &c) != 0) {
                c = NULL;
                usleep(20000);
                continue;
            }
            tsdbc_set_retry(c, w->noretry ? 0 : 10000);
            tsdbc_set_timeout(c, 30000);
        }
        float val = (float)(w->ts % 977);
        struct tr_write r = {now_ms(), 0, 0};
        r.rc = tsdbc_insert_series(c, w->id, &w->ts, &val, 1);
        r.t1 = now_ms();
        __atomic_store_n(&w->last_rc, r.rc, __ATOMIC_RELAXED);
        if (r.rc == 0) {
            w->acked++;
            __atomic_store_n(&w->last_ack_t0, r.t0, __ATOMIC_RELEASE);
        }
        else if (r.rc == TSDB_ERR_UNAVAILABLE || r.rc == TSDB_ERR_MOVED) {
            w->refused++; /* definite: the server says it was never admitted */
            w->unavail += r.rc == TSDB_ERR_UNAVAILABLE;
            if (w->noretry && r.rc == TSDB_ERR_MOVED) {
                tsdbc_close(c);
                c = NULL;
                w->via = (w->via + 1) % 3;
            }
            if (w->noretry)
                usleep(5000); /* the client's own retries would wait retry_after (50 ms in a drain) */
        }
        else {
            w->indet++; /* a closed connection (D12) or a deadline: the outcome is unknown */
            tsdbc_close(c);
            c = NULL;
        }
        w->ts += 1000;
        if (w->n == w->cap) {
            w->cap = w->cap ? 2 * w->cap : 65536;
            w->w = realloc(w->w, w->cap * sizeof *w->w);
            if (!w->w)
                die("out of memory");
        }
        w->w[w->n++] = r;
    }
    if (c)
        tsdbc_close(c);
    return NULL;
}

/* one transfer of `name` (number num) to node `to` through the Raft leader (server 0, followed): its answer */
static int tr_transfer(uint32_t num, uint32_t to, char *why, size_t n)
{
    uint8_t body[8], *reply = NULL;
    size_t rl = 0, bl = cluster_volume_force_encode(num, to, body);
    int rc = admin(0, CLUSTER_OP_VOLUME_TRANSFER, body, bl, 1, &reply, &rl);
    snprintf(why, n, "%.*s", (int)(rl < 200 ? rl : 200), reply ? (const char *)reply : "");
    free(reply);
    return rc;
}

static uint64_t tr_count(int i, int which)
{
    struct view v;
    view(i, &v);
    uint64_t c = v.st.ntr > (uint32_t)which ? v.st.tr[which] : 0;
    view_free(&v);
    return c;
}

/* After stop_all: on every member each acknowledged row of the writers is there and each refused one (UNAVAILABLE or
 * MOVED after the client's retries: never admitted, D14) is not, and the members hold the same rows. A write with an
 * unknown outcome (a killed server's connection) may be either. */
struct tr_chk {
    struct tr_writer *w;
    int server;
    const char *what;
    int bad;
};
static int tr_chk_fn(void *ctx, const char *name, const int64_t *ts, const float *v, size_t n)
{
    struct tr_chk *k = ctx;
    (void)v;
    for (int i = 0; i < REP_NAMES; i++) {
        if (strcmp(name, rep_names[i]) != 0)
            continue;
        const struct tr_writer *w = &k->w[i];
        size_t at = 0;
        for (size_t j = 0; j < w->n; j++) {
            int64_t t = 1000000 + 1000 * (int64_t)j;
            while (at < n && ts[at] < t)
                at++;
            int has = at < n && ts[at] == t;
            if (w->w[j].rc == 0 && !has && k->bad++ < 3)
                fprintf(stderr, "%s: server %d lost the acknowledged row %" PRId64 " of %s (write %zu, %" PRIu64
                        " ms, via server %d)\n", k->what, k->server, t, name, j, w->w[j].t1 - w->w[j].t0, w->server);
            if ((w->w[j].rc == TSDB_ERR_UNAVAILABLE || w->w[j].rc == TSDB_ERR_MOVED) && has && k->bad++ < 3)
                fprintf(stderr, "%s: server %d holds the row %" PRId64 " of %s, refused with %s (a definite refusal "
                        "applied)\n", k->what, k->server, t, name, ers(w->w[j].rc));
        }
    }
    return 0;
}
static void tr_check(struct tr_writer *w, const char *what)
{
    uint64_t rows[3][REP_NAMES], h[3][REP_NAMES];
    int bad = 0;
    for (int i = 0; i < 3; i++) {
        char dir[PATH_MAX + 80], v[PATH_MAX + 120];
        server_dir(i, dir, sizeof dir);
        snprintf(v, sizeof v, "%s/v1", dir);
        struct tr_chk k = {w, i, what, 0};
        int rc = cvol_rows(v, tr_chk_fn, &k);
        bad += k.bad;
        if (rc == 0)
            rc = cvol_digest(v, rep_names, REP_NAMES, rows[i], h[i]);
        if (rc != 0)
            die("%s: open %s read-only: %s", what, v, ers(rc));
        for (int n = 0; i && n < REP_NAMES; n++)
            if (rows[i][n] != rows[0][n] || h[i][n] != h[0][n])
                die("%s: server %d holds %" PRIu64 " rows of %s, server 0 %" PRIu64 "%s", what, i, rows[i][n],
                    rep_names[n], rows[0][n], rows[i][n] == rows[0][n] ? ", other ones" : "");
    }
    if (bad)
        die("%s: %d rows lost or applied after a refusal (above)", what, bad);
}

/* r4-transfer's other scenarios: 3 servers, volume tv (number 1) on all three, REP_NAMES writers through every
 * member (forwarded where not led) */
struct tr_run {
    struct tr_writer w[REP_NAMES];
    pthread_t th[REP_NAMES];
    uint32_t num;
};
static void tr_setup(struct tr_run *x)
{
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    int rc;
    if ((rc = vol_add(0, "tv", 3, &x->num)) != 0 || x->num != 1)
        die("volume add tv: %s, number %" PRIu32, cluster_strerror(rc), x->num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "tv", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    tsdbc *c = client(server_of(v.leader));
    memset(x->w, 0, sizeof x->w);
    for (int k = 0; k < REP_NAMES; k++) {
        x->w[k].server = k % 3;
        x->w[k].id = rep_series(c, rep_names[k], "tv", 30000);
        x->w[k].ts = 1000000;
    }
    tsdbc_close(c);
    await_isr(0, "tv", 3, 30000, "every replica in the ISR before the writers");
    for (int k = 0; k < REP_NAMES; k++)
        if (pthread_create(&x->th[k], NULL, tr_write_thread, &x->w[k]) != 0)
            die("pthread_create");
    usleep(300000);
}
/* the rows server c itself answers (no retries set on c): -1 while it refuses (MOVED, UNAVAILABLE) */
static int tr_rows_here(tsdbc *c, tsdb_sid id)
{
    nrows = 0;
    int rc = tsdbc_query_raw(c, id, 0, INT64_MAX / 2, count_rows, NULL);
    if (rc == TSDB_ERR_MOVED || rc == TSDB_ERR_UNAVAILABLE)
        return -1;
    if (rc != 0)
        die("query: %s", ers(rc));
    return nrows;
}
/* the writers stopped, every server stopped cleanly, the rows checked; the writers' records freed */
static void tr_finish(struct tr_run *x, const char *what, int indet_ok)
{
    for (int k = 0; k < REP_NAMES; k++)
        __atomic_store_n(&x->w[k].stop, 1, __ATOMIC_RELEASE);
    int indet = 0;
    for (int k = 0; k < REP_NAMES; k++) {
        pthread_join(x->th[k], NULL);
        indet += x->w[k].indet;
    }
    if (indet && !indet_ok)
        die("%s: %d writes had an unknown outcome (D14 promises definite answers)", what, indet);
    /* a commit needs min_isr members, not all: every member holds the leader's rows before the stop */
    struct meta_volume v;
    if (!vol_rec(0, "tv", &v))
        die("%s: no record of tv", what);
    tsdbc *c = client(server_of(v.leader));
    tsdbc_set_retry(c, 30000); /* a MOVED of a record not yet in this copy is followed */
    for (int k = 0; k < REP_NAMES; k++) {
        int want = rows_of(c, x->w[k].id);
        for (int i = 0; i < 3; i++) {
            /* no retries: a MOVED followed to the leader would count the leader's rows as server i's (transferkill:
             * the restarted server, without a lease yet, was stopped before its tail came) */
            tsdbc *r = client(i);
            tsdbc_set_retry(r, 0);
            uint64_t t0 = now_ms();
            int got;
            while ((got = tr_rows_here(r, x->w[k].id)) != want)
                if (now_ms() - t0 > 30000)
                    die("%s: server %d reads %d rows of %s 30 s after the writers stopped, the leader %d", what, i,
                        got, rep_names[k], want);
                else
                    usleep(20000);
            tsdbc_close(r);
        }
    }
    tsdbc_close(c);
    stop_all();
    tr_check(x->w, what);
    for (int k = 0; k < REP_NAMES; k++)
        free(x->w[k].w);
}
/* every writer acknowledged a write that began after t (bounded: 30 s) */
static void tr_await_acks(struct tr_run *x, uint64_t t, const char *what)
{
    for (int k = 0; k < REP_NAMES; k++) {
        uint64_t until = now_ms() + 30000;
        while (__atomic_load_n(&x->w[k].last_ack_t0, __ATOMIC_ACQUIRE) <= t)
            if (now_ms() > until)
                die("writer %d (through server %d) acknowledged nothing in 30 s %s", k, x->w[k].server, what);
            else
                usleep(5000);
    }
}
/* the member of tv that is neither its leader (server L) nor the server `not` */
static int tr_other(int L, int not)
{
    for (int i = 0; i < 3; i++)
        if (i != L && i != not)
            return i;
    return -1;
}
struct tr_async {
    uint32_t num, to;
    int rc;
    char why[256];
};
/* a transfer through server 0 that may be killed under it (no follow): a lost connection is rc 1 and its error */
static void *tr_transfer_thread(void *a)
{
    struct tr_async *t = a;
    char target[META_ADDR_MAX + 1];
    uint8_t body[8], *reply = NULL;
    size_t rl = 0, bl = cluster_volume_force_encode(t->num, t->to, body);
    peer_of(0, target, sizeof target);
    if (cluster_admin(target, secret, secret_len, CLUSTER_OP_VOLUME_TRANSFER, body, bl, 30000, &t->rc, &reply, &rl,
                      t->why, sizeof t->why) != 0) {
        t->rc = 1;
        return NULL;
    }
    snprintf(t->why, sizeof t->why, "%.*s", (int)(rl < 200 ? rl : 200), reply ? (const char *)reply : "");
    free(reply);
    return NULL;
}
static void state_flag(int i, const char *name, int on)
{
    char f[PATH_MAX + 64];
    server_dir(i, f, sizeof f);
    snprintf(f + strlen(f), sizeof f - strlen(f), "/state/%s", name);
    if (on) {
        FILE *fp = fopen(f, "w");
        if (!fp)
            die("create %s: %s", f, strerror(errno));
        fclose(fp);
    } else if (unlink(f) != 0 && errno != ENOENT)
        die("unlink %s: %s", f, strerror(errno));
}

/* transferslow: the target stopped (SIGSTOP) for 3 s across a transfer: the drain times out (transfer_wait_ms 1000),
 * the leader admits again, the transfer is refused, the leader and epoch are unchanged, writes go on */
static void tr_slow(int lag)
{
    scenario(lag ? "transferlag" : "transferslow");
    init_transfer_wait_ms = lag ? 6000 : 1000;
    struct tr_run x;
    tr_setup(&x);
    init_transfer_wait_ms = 0;
    struct meta_volume v, a = {0};
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    int L = server_of(v.leader), T = tr_other(L, 0);
    int ready0 = log_count(L, ": READY at"), drains0 = log_count(L, ": drains (written");
    pause_server(T, 1);
    uint64_t t0 = now_ms();
    char why[256];
    int rc = tr_transfer(x.num, ids[T], why, sizeof why);
    uint64_t took = now_ms() - t0;
    if (lag) { /* the stopped target left the ISR during the drain: the commit point moved on without it */
        struct meta_volume s;
        if (!vol_rec(0, "tv", &s) || s.nisr != 2)
            die("transferlag: the stopped target is still in tv's ISR after the drain of %" PRIu64 " ms", took);
    }
    if (log_count(L, ": READY at") != ready0)
        die("server %d sent READY for a transfer to stopped server %d", L, T);
    /* the Raft leader resends TRANSFER until its own timeout: a drain that timed out never begins again (mutant
     * transferredrain holds the writes a second time) */
    if (log_count(L, ": drains (written") != drains0 + 1)
        die("server %d drained %d times for one transfer", L, log_count(L, ": drains (written") - drains0);
    if (rc == 0)
        die("a transfer to stopped server %d answered OK", T);
    if (!vol_rec(0, "tv", &a) || a.leader != v.leader || a.epoch != v.epoch)
        die("the transfer to stopped server %d moved tv: node %u at epoch %" PRIu64 " (was node %u at %" PRIu64 ")", T,
            a.leader, a.epoch, v.leader, v.epoch);
    uint64_t td = now_ms();
    if (L != T) /* writes through the leader and server 0 go on while the target is still stopped */
        for (int k = 0; k < REP_NAMES; k++)
            if (x.w[k].server != T) {
                uint64_t until = now_ms() + 30000;
                while (__atomic_load_n(&x.w[k].last_ack_t0, __ATOMIC_ACQUIRE) <= td)
                    if (now_ms() > until)
                        die("writer %d acknowledged nothing after the drain timed out", k);
                    else
                        usleep(5000);
            }
    uint64_t resumed = now_ms() - td;
    while (now_ms() - t0 < 3000)
        usleep(10000);
    pause_server(T, 0);
    if (tr_count(L, CL_TR_DRAIN_TIMEDOUT) != 1)
        die("server %d counts %" PRIu64 " drains timed out, not 1", L, tr_count(L, CL_TR_DRAIN_TIMEDOUT));
    await_isr(0, "tv", 3, 60000, "the stopped target back in the ISR");
    tr_await_acks(&x, now_ms(), "after the target resumed");
    printf("  the transfer to a stopped target: %s after %" PRIu64 " ms (%s), writes resumed %" PRIu64
           " ms after it, leader unchanged\n", cluster_strerror(rc), took, why, resumed);
    tr_finish(&x, lag ? "transferlag" : "transferslow", 0);
}
static void scen_transferslow(void) { tr_slow(0); }
/* transferlag: transferslow with transfer_wait_ms 6000, so that the stopped target leaves the ISR (isr_lag_ms 1000)
 * while the leader drains and the commit point moves on without it: the drain must still wait for the target's own
 * durable end and time out, no READY. Mutant transfernotarget (the commit point alone) sends READY. */
static void scen_transferlag(void) { tr_slow(1); }

/* transfermarkers: a transfer with each kind of marker in flight. TSDB_REPLD_TEST=admithold holds the admit of the
 * next marker of the type <dir>/admithold names (with buf_lock held) until the transfer drains, so the drain refuses
 * it: the idle seal's NOW, a series create's SERIES, a retention change's RETENTION, a large write's COMMIT (its files
 * shipped first) and the class switch of a fresh slow series' first flush. No engine fails, the drain ends (every transfer
 * answers OK with the target leading), each client call answers OK (it retries the refusal on the new leader), and
 * every member ends with the rows. DROP is not here: no op of tsdbd calls tsdb_drop_before. */
enum { TMK_COMMIT = 1, TMK_RETENTION = 3, TMK_CLASS = 6, TMK_SERIES = 7, TMK_NOW = 10 }; /* src/marker.h */
struct tm_op {
    int server, kind;
    tsdb_sid big, slow, now;
    int rc;
};
enum { TM_BIG = 100000 };
static void *tm_op_thread(void *a)
{
    struct tm_op *o = a;
    tsdbc *c = client(o->server);
    tsdbc_set_retry(c, 30000);
    o->rc = 0;
    if (o->kind == TMK_SERIES) {
        tsdb_sid id = 0;
        o->rc = tsdbc_series_at(c, "tm.created", "tv", &id);
    } else if (o->kind == TMK_RETENTION) {
        o->rc = tsdbc_set_retention(c, o->big, 100LL * 366 * 86400000);
    } else if (o->kind == TMK_COMMIT) {
        int64_t *ts = malloc(TM_BIG * sizeof *ts);
        float *val = malloc(TM_BIG * sizeof *val);
        if (!ts || !val)
            die("out of memory");
        for (int j = 0; j < TM_BIG; j++)
            ts[j] = 1000 + 1000LL * j, val[j] = (float)(j % 977);
        o->rc = tsdbc_insert_series(c, o->big, ts, val, TM_BIG);
        free(ts);
        free(val);
    } else if (o->kind == TMK_CLASS) {
        int64_t ts[200];
        float val[200];
        for (int j = 0; j < 200; j++)
            ts[j] = 3600000LL * j, val[j] = (float)j;
        /* fresh: a series the leader's open found is taken as decided and never switches */
        o->rc = tsdbc_series_at(c, "tm.slow", "tv", &o->slow);
        if (o->rc == 0)
            o->rc = tsdbc_insert_series(c, o->slow, ts, val, 200);
    } else if (o->kind == TMK_NOW) {
        int64_t ts = 5;
        float val = 5;
        o->rc = tsdbc_insert_series(c, o->now, &ts, &val, 1); /* a row to seal; the seal comes when idle */
    }
    tsdbc_close(c);
    return NULL;
}
static void scen_transfermarkers(void)
{
    scenario("transfermarkers");
    for (int i = 0; i < 3; i++)
        penv[i] = "TSDB_REPLD_TEST=admithold";
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    int rc;
    uint32_t num = 0;
    if ((rc = vol_add(0, "tv", 3, &num)) != 0 || num != 1)
        die("volume add tv: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "tv", i, 1, 0);
    await_isr(0, "tv", 3, 30000, "every replica in the ISR");
    struct meta_volume v;
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    tsdbc *c = client(server_of(v.leader));
    tsdb_sid big = rep_series(c, "tm.big", "tv", 30000), slow = 0, nowid = rep_series(c, "tm.now", "tv", 30000);
    tsdbc_close(c);
    static const struct {
        int kind;
        const char *name;
    } kinds[] = {{TMK_SERIES, "SERIES"}, {TMK_RETENTION, "RETENTION"}, {TMK_COMMIT, "COMMIT"}, {TMK_NOW, "NOW"},
                 {TMK_CLASS, "CLASS"}};
    char held[64];
    for (size_t k = 0; k < sizeof kinds / sizeof kinds[0]; k++) {
        if (!vol_rec(0, "tv", &v))
            die("no record of tv");
        int L = server_of(v.leader), T = tr_other(L, -1);
        char f[PATH_MAX + 40];
        snprintf(f, sizeof f, "%s/n%d/admithold", base, L);
        FILE *fp = fopen(f, "w");
        if (!fp || fprintf(fp, "%d\n", kinds[k].kind) < 0 || fclose(fp) != 0)
            die("write %s: %s", f, strerror(errno));
        snprintf(held, sizeof held, "a marker of type %d held", kinds[k].kind);
        int before = log_count(L, held);
        struct tm_op o = {.server = L, .kind = kinds[k].kind, .big = big, .slow = slow, .now = nowid};
        pthread_t th;
        if (pthread_create(&th, NULL, tm_op_thread, &o) != 0)
            die("pthread_create");
        await_log_count(L, held, before + 1, 60000);
        uint64_t t0 = now_ms();
        char why[256];
        if ((rc = tr_transfer(num, ids[T], why, sizeof why)) != 0)
            die("transfermarkers: the transfer to node %u with a %s marker held: %s (%s)", ids[T], kinds[k].name,
                cluster_strerror(rc), why);
        uint64_t took = now_ms() - t0;
        pthread_join(th, NULL);
        if (kinds[k].kind == TMK_CLASS)
            slow = o.slow;
        struct meta_volume a;
        if (!vol_rec(0, "tv", &a) || a.leader != ids[T])
            die("transfermarkers: node %u leads tv after the transfer to node %u with a %s marker held", a.leader,
                ids[T], kinds[k].name);
        if (o.rc != 0)
            die("transfermarkers: the call with a %s marker held answered %s", kinds[k].name, ers(o.rc));
        if (access(f, F_OK) == 0)
            die("transfermarkers: the %s marker was never held (%s still there)", kinds[k].name, f);
        for (int i = 0; i < 3; i++)
            if (log_count(i, "no more writes until") != 0)
                die("transfermarkers: an engine of server %d failed with a %s marker held", i, kinds[k].name);
        await_isr(0, "tv", 3, 30000, "the ISR whole after the transfer");
        printf("  a transfer with a %s marker held at the admit: %" PRIu64 " ms, the call answered OK on node %u\n",
               kinds[k].name, took, ids[T]);
    }
    /* every member holds the rows: the large write's and the slow series' */
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    c = client(server_of(v.leader));
    tsdbc_set_retry(c, 30000);
    int nb = rows_of(c, big), ns = rows_of(c, slow);
    tsdb_sid made = 0;
    if ((rc = tsdbc_series_at(c, "tm.created", "tv", &made)) != 0)
        die("transfermarkers: the series created with its SERIES marker held: %s", ers(rc));
    tsdbc_close(c);
    if (nb != TM_BIG || ns != 200)
        die("transfermarkers: the leader reads %d and %d rows, not %d and 200", nb, ns, TM_BIG);
    for (int i = 0; i < 3; i++) {
        tsdbc *r = client(i);
        tsdbc_set_retry(r, 0);
        uint64_t t0 = now_ms();
        while (tr_rows_here(r, big) != nb || tr_rows_here(r, slow) != ns)
            if (now_ms() - t0 > 30000)
                die("transfermarkers: server %d does not read the leader's rows 30 s on", i);
            else
                usleep(50000);
        tsdbc_close(r);
    }
    for (int i = 0; i < 3; i++)
        if (log_count(i, "no more writes until") != 0)
            die("transfermarkers: an engine of server %d failed", i);
    stop_all();
}

/* transferhold: transfer_wait_ms 500, and the promotion's FENCE held from every member (TSDB_CLUSTER_TEST
 * drop_fence_file, dropped for 1200 ms after READY, resent every 100 ms): the old leader L stays
 * the writer past transfer_wait_ms, and admits nothing (READY's hold lasts until its epoch is lost or 10 x
 * transfer_wait_ms): no record admitted blind, no cut on any member, the target leads, every acknowledged row on every
 * member. Mutant transferresume (admits again transfer_wait_ms after READY) admits records blind. */
static void scen_transferhold(void)
{
    scenario("transferhold");
    for (int i = 0; i < 3; i++)
        envs[i] = "drop_fence_file=1";
    init_transfer_wait_ms = 500;
    struct tr_run x;
    tr_setup(&x);
    init_transfer_wait_ms = 0;
    struct meta_volume v, a = {0};
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    char why[256];
    int rc;
    if (server_of(v.leader) == 0) { /* the Raft leader's own fence takes no message to drop: lead elsewhere first */
        if ((rc = tr_transfer(x.num, ids[1], why, sizeof why)) != 0)
            die("transferhold: the transfer to node %u: %s (%s)", ids[1], cluster_strerror(rc), why);
        tr_await_acks(&x, now_ms(), "after the first transfer");
        if (!vol_rec(0, "tv", &v))
            die("no record of tv");
    }
    int L = server_of(v.leader), T = tr_other(L, 0);
    int ready0 = log_count(L, ": READY at");
    for (int i = 0; i < 3; i++)
        state_flag(i, "dropfence", 1);
    uint64_t t0 = now_ms();
    struct tr_async ta = {x.num, ids[T], 0, ""};
    pthread_t th;
    if (pthread_create(&th, NULL, tr_transfer_thread, &ta) != 0)
        die("pthread_create");
    await_log_count(L, ": READY at", ready0 + 1, 10000);
    usleep(1200000);
    for (int i = 0; i < 3; i++)
        state_flag(i, "dropfence", 0);
    pthread_join(th, NULL);
    uint64_t took = now_ms() - t0;
    if (ta.rc != 0)
        die("transferhold: the transfer to node %u: %s (%s)", ids[T], ta.rc == 1 ? "lost" : cluster_strerror(ta.rc),
            ta.why);
    if (!vol_rec(0, "tv", &a) || a.leader != ids[T])
        die("transferhold: node %u leads tv after the transfer to node %u", a.leader, ids[T]);
    tr_await_acks(&x, now_ms(), "after the transfer past transfer_wait_ms");
    uint64_t blind = tr_count(L, CL_TR_BLIND), cuts = 0;
    for (int i = 0; i < 3; i++)
        cuts += tr_count(i, CL_TR_CUTS);
    printf("  a transfer whose fence was held 1200 ms: %" PRIu64 " ms (%s); admitted blind %" PRIu64 ", cuts %" PRIu64
           "\n", took, ta.why, blind, cuts);
    if (blind || cuts)
        die("transferhold: server %d admitted %" PRIu64 " records blind, %" PRIu64 " cuts on the members", L, blind, cuts);
    /* a slow bystander (past failover's PROMO_WAIT_NS 500 ms, within PROMO_TRANSFER_WAIT_NS 1500 ms) must still be
     * waited for so its answer counts (3 of 3, no member left unanswered) */
    await_isr(0, "tv", 3, 30000, "every replica in the ISR before the slow-bystander transfer");
    int L2 = server_of(a.leader), T2 = 0, B2 = 3 - L2 - T2; /* T2 = server 0 (Raft leader), B2 = the other non-leader */
    if (L2 == 0)
        T2 = 1, B2 = 2;
    int props0 = 0, whole0 = 0;
    for (int i = 0; i < 3; i++)
        props0 += log_count(i, " fenced members answered"), whole0 += log_count(i, " (3 of 3 fenced members answered");
    int ready1 = log_count(L2, ": READY at");
    state_flag(B2, "dropfence", 1);
    struct tr_async tb = {x.num, ids[T2], 0, ""};
    if (pthread_create(&th, NULL, tr_transfer_thread, &tb) != 0)
        die("pthread_create");
    await_log_count(L2, ": READY at", ready1 + 1, 10000);
    usleep(750000);
    state_flag(B2, "dropfence", 0);
    pthread_join(th, NULL);
    if (tb.rc != 0)
        die("transferhold: slow-bystander transfer to node %u: %s (%s)", ids[T2],
            tb.rc == 1 ? "lost" : cluster_strerror(tb.rc), tb.why);
    int props1 = 0, whole1 = 0;
    for (int i = 0; i < 3; i++)
        props1 += log_count(i, " fenced members answered"), whole1 += log_count(i, " (3 of 3 fenced members answered");
    if (props1 - props0 != 1 || whole1 - whole0 != 1)
        die("transferhold: slow bystander (750 ms) was not counted (%d proposed, %d with 3 of 3 answers)",
            props1 - props0, whole1 - whole0);
    tr_await_acks(&x, now_ms(), "after the slow-bystander transfer");
    tr_finish(&x, "transferhold", 0);
}

/* transfergrant (F2 of the review): the Raft leader proposes the transfer's grant 3000 ms after it decided it
 * (TSDB_CLUSTER_TEST hold_grant_ms, a Raft quorum slow to commit), past PROMO_MOVE_NS (2 s) from the promotion's start.
 * A promotion whose grant is proposed waits for its commit, as a failover's does: the transfer is answered ok, the
 * target leads, nothing fell back or was cancelled, no record admitted blind, no cut. Mutant dropproposed (the
 * promotion dropped at PROMO_MOVE_NS though its grant is proposed) answers "cancelled" and counts a fallback while the
 * grant commits after all. */
static void scen_transfergrant(void)
{
    scenario("transfergrant");
    for (int i = 0; i < 3; i++)
        envs[i] = "hold_grant_ms=3000";
    struct tr_run x;
    tr_setup(&x);
    struct meta_volume v, a = {0};
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    int L = server_of(v.leader), T = tr_other(L, 0);
    char why[256];
    uint64_t t0 = now_ms();
    int rc = tr_transfer(x.num, ids[T], why, sizeof why);
    uint64_t took = now_ms() - t0;
    if (rc != 0)
        die("transfergrant: the transfer to node %u: %s (%s)", ids[T], cluster_strerror(rc), why);
    if (!vol_rec(0, "tv", &a) || a.leader != ids[T])
        die("transfergrant: node %u leads tv after the transfer to node %u", a.leader, ids[T]);
    if (took < 2900)
        die("transfergrant: the transfer took %" PRIu64 " ms: the grant was not held (%s)", took, why);
    tr_await_acks(&x, now_ms(), "after the transfer with its grant held");
    uint64_t fb = 0, cancelled = 0, timedout = 0, cuts = 0;
    for (int i = 0; i < 3; i++) {
        fb += tr_count(i, CL_TR_FALLBACK);
        cancelled += tr_count(i, CL_TR_CANCELLED);
        timedout += tr_count(i, CL_TR_TIMEDOUT);
        cuts += tr_count(i, CL_TR_CUTS);
    }
    uint64_t blind = tr_count(L, CL_TR_BLIND);
    printf("  a transfer whose grant was held 3000 ms: %" PRIu64 " ms (%s); fell back %" PRIu64 ", cancelled %" PRIu64
           ", timed out %" PRIu64 ", blind %" PRIu64 ", cuts %" PRIu64 "\n", took, why, fb, cancelled, timedout, blind,
           cuts);
    if (fb || cancelled || timedout || blind || cuts)
        die("transfergrant: fell back %" PRIu64 ", cancelled %" PRIu64 ", timed out %" PRIu64 ", admitted blind %" PRIu64
            ", cuts %" PRIu64 " (a proposed grant must be waited for)", fb, cancelled, timedout, blind, cuts);
    for (int i = 0; i < 3; i++)
        if (log_count(i, "promotion is dropped"))
            die("transfergrant: server %d dropped the promotion of a proposed grant", i);
    tr_finish(&x, "transfergrant", 0);
}

/* transferadmin (F5 of the review): every refusal of `tsdb cluster volume transfer` (ctransfer.c tr_check) with its
 * message, and nothing changed by one (epoch, leader, the Raft leader's started count): the current leader as target;
 * a second transfer while one drains (TSDB_REPLD_TEST=drainhold); a member that is in the ISR but not up (paused past
 * node_timeout_ms with the ISR held, TSDB_CLUSTER_TEST hold_isr_file); the same member once it left the ISR. Mutants
 * adminself, adminbusy, adminup, adminisr each take one check away. */
static int tr_refused(int R, uint32_t num, uint32_t to, const char *want, const char *what)
{
    struct meta_volume b, a;
    if (!vol_rec(R, "tv", &b))
        die("no record of tv");
    char why[256];
    uint8_t body[8], *reply = NULL;
    size_t rl = 0, bl = cluster_volume_force_encode(num, to, body);
    int rc = admin(R, CLUSTER_OP_VOLUME_TRANSFER, body, bl, 1, &reply, &rl); /* to R: server 0 may be the paused one */
    snprintf(why, sizeof why, "%.*s", (int)(rl < 200 ? rl : 200), reply ? (const char *)reply : "");
    free(reply);
    if (rc == 0 || !strstr(why, want))
        die("transferadmin: a transfer %s: %s (%s), not refused with \"%s\"", what, rc ? cluster_strerror(rc) : "OK",
            why, want);
    if (!vol_rec(R, "tv", &a))
        die("transferadmin: no record of tv after the transfer %s", what);
    if (a.epoch != b.epoch || a.leader != b.leader)
        die("transferadmin: the refused transfer %s changed tv: epoch %" PRIu64 " -> %" PRIu64 ", leader %u -> %u", what,
            b.epoch, a.epoch, b.leader, a.leader);
    printf("  a transfer %s: refused (%s)\n", what, why);
    return rc;
}

static void scen_transferadmin(void)
{
    scenario("transferadmin");
    for (int i = 0; i < 3; i++) {
        envs[i] = "hold_isr_file=1";
        penv[i] = "TSDB_REPLD_TEST=drainhold";
    }
    struct tr_run x;
    tr_setup(&x);
    struct meta_volume v;
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    int R = leader_of(0);
    if (R < 0)
        die("no Raft leader");
    int L = server_of(v.leader);
    /* t2, 2 replicas of 3 members: the third is up and not in its ISR */
    uint32_t n2 = 0;
    int rc2 = vol_add(0, "t2", 2, &n2);
    if (rc2 != 0)
        die("volume add t2: %s", cluster_strerror(rc2));
    struct meta_volume v2 = {0};
    uint64_t tw = now_ms();
    while (!vol_rec(R, "t2", &v2) || !v2.leader || v2.nisr != 2)
        if (now_ms() - tw > 30000)
            die("t2 has no leader and ISR of 2 after 30 s");
        else
            usleep(20000);
    uint32_t out = 0;
    for (int i = 0; i < 3; i++)
        if (ids[i] != v2.isr[0] && ids[i] != v2.isr[1])
            out = ids[i];
    uint64_t started = tr_count(R, CL_TR_STARTED);
    {
        char why[256];
        uint8_t body[8], *reply = NULL;
        size_t rl = 0, bl = cluster_volume_force_encode(n2, out, body);
        int rc = admin(R, CLUSTER_OP_VOLUME_TRANSFER, body, bl, 1, &reply, &rl);
        snprintf(why, sizeof why, "%.*s", (int)(rl < 200 ? rl : 200), reply ? (const char *)reply : "");
        free(reply);
        struct meta_volume a2;
        if (rc == 0 || !strstr(why, "not in its ISR"))
            die("transferadmin: a transfer of t2 to node %u outside its ISR: %s (%s), not refused with \"not in its "
                "ISR\"", out, rc ? cluster_strerror(rc) : "OK", why);
        if (!vol_rec(R, "t2", &a2) || a2.epoch != v2.epoch || a2.leader != v2.leader)
            die("transferadmin: the refused transfer of t2 changed it");
        printf("  a transfer to an up member outside the ISR: refused (%s)\n", why);
    }
    tr_refused(R, x.num, v.leader, "leads it already", "to the current leader");
    if (tr_count(R, CL_TR_STARTED) != started)
        die("transferadmin: a refused transfer counted as started");
    /* a second transfer while the first one's drain is held on the leader */
    int T = tr_other(L, R == L ? -1 : R), U = 3 - L - T;
    char f[PATH_MAX + 40];
    snprintf(f, sizeof f, "%s/n%d/drainhold", base, L);
    FILE *fp = fopen(f, "w");
    if (!fp || fclose(fp) != 0)
        die("write %s: %s", f, strerror(errno));
    int drains = log_count(L, ": drains (written");
    struct tr_async ta = {x.num, ids[T], 0, ""};
    pthread_t th;
    if (pthread_create(&th, NULL, tr_transfer_thread, &ta) != 0)
        die("pthread_create");
    await_log_count(L, ": drains (written", drains + 1, 30000);
    tr_refused(R, x.num, ids[U], "a transfer of it is under way", "while one drains");
    tr_refused(R, x.num, ids[T], "a transfer of it is under way", "to the same target while one drains");
    if (unlink(f) != 0)
        die("unlink %s: %s", f, strerror(errno));
    pthread_join(th, NULL);
    if (ta.rc != 0)
        die("transferadmin: the held transfer to node %u: %s (%s)", ids[T], ta.rc == 1 ? "lost" : cluster_strerror(ta.rc),
            ta.why);
    if (tr_count(R, CL_TR_STARTED) != started + 1)
        die("transferadmin: the Raft leader counts %" PRIu64 " transfers started, not %" PRIu64,
            tr_count(R, CL_TR_STARTED), started + 1);
    tr_await_acks(&x, now_ms(), "after the held transfer");
    /* a member in the ISR that is not up: neither the Raft leader nor the volume's leader (now T) */
    if (!vol_rec(R, "tv", &v) || server_of(v.leader) != T)
        die("tv is not led by server %d after its transfer there", T);
    int P = tr_other(T, R); /* T != R: tr_other above */
    hold_isr(1);
    pause_server(P, 1);
    usleep(3000 * 1000 + 1500 * 1000); /* node_timeout_ms 3000, and a heartbeat round */
    tr_refused(R, x.num, ids[P], "the node is not up", "to a paused member still in the ISR");
    hold_isr(0);
    int via = tr_other(P, -1);
    await_isr(via, "tv", 2, 30000, "the paused member out of the ISR");
    tr_refused(R, x.num, ids[P], "not in its ISR", "to a member outside the ISR");
    pause_server(P, 0);
    await_isr(via, "tv", 3, 60000, "the paused member back in the ISR");
    if (tr_count(R, CL_TR_STARTED) != started + 1)
        die("transferadmin: the Raft leader counts %" PRIu64 " transfers started after the refusals, not %" PRIu64,
            tr_count(R, CL_TR_STARTED), started + 1);
    tr_await_acks(&x, now_ms(), "after the paused member came back");
    tr_finish(&x, "transferadmin", 1);
}

/* transferstale (D14): the volume leader's READY and the Raft leader's CANCEL of the timed-out transfer are both lost
 * (TSDB_CLUSTER_TEST lose_ready_file), so the volume leader holds its writes for a transfer the Raft leader no longer
 * knows. Once READYs get through again, the Raft leader must answer the next resent one with a CANCEL of that id: the
 * writes resume within a few resends, not at the hard cap (10 x transfer_wait_ms = 10 s), and nothing is admitted blind */
static void scen_transferstale(void)
{
    scenario("transferstale");
    for (int i = 0; i < 3; i++)
        envs[i] = "lose_ready_file=1";
    init_transfer_wait_ms = 1000;
    struct tr_run x;
    tr_setup(&x);
    init_transfer_wait_ms = 0;
    struct meta_volume v, a = {0};
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    int L = server_of(v.leader), T = tr_other(L, 0);
    int ready0 = log_count(L, ": READY at"), cancel0 = log_count(L, "cancelled by the Raft leader");
    for (int i = 0; i < 3; i++)
        state_flag(i, "loseready", 1);
    char why[256];
    int rc = tr_transfer(x.num, ids[T], why, sizeof why);
    if (rc == 0 || !strstr(why, "timed out"))
        die("transferstale: the transfer to node %u with every READY lost: %s (%s), not a timeout", ids[T],
            cluster_strerror(rc), why);
    if (log_count(L, ": READY at") != ready0 + 1)
        die("transferstale: server %d sent no READY (or more than one transfer's)", L);
    uint64_t t0 = now_ms();
    for (int i = 0; i < 3; i++)
        state_flag(i, "loseready", 0);
    await_log_count(L, "cancelled by the Raft leader", cancel0 + 1, 3000);
    uint64_t took = now_ms() - t0;
    tr_await_acks(&x, now_ms(), "after the stale READY's CANCEL");
    if (!vol_rec(0, "tv", &a) || a.leader != v.leader || a.epoch != v.epoch)
        die("transferstale: tv moved (node %u at epoch %" PRIu64 ", was node %u at %" PRIu64 ")", a.leader, a.epoch,
            v.leader, v.epoch);
    uint64_t blind = tr_count(L, CL_TR_BLIND), cuts = 0;
    for (int i = 0; i < 3; i++)
        cuts += tr_count(i, CL_TR_CUTS);
    printf("  a READY the Raft leader no longer held: cancelled %" PRIu64 " ms after READYs got through; admitted blind %"
           PRIu64 ", cuts %" PRIu64 "\n", took, blind, cuts);
    if (blind || cuts)
        die("transferstale: server %d admitted %" PRIu64 " records blind, %" PRIu64 " cuts on the members", L, blind, cuts);
    tr_finish(&x, "transferstale", 0);
}

/* transferkill: the old leader killed (SIGKILL) during the drain (the target stopped, so the drain waits), and, on a
 * cluster of its own, at the crash point transfer-ready (READY sent, the fence under way): a normal failover each time,
 * no acknowledged row lost, no refused row applied, the killed server back in the ISR */
static void tr_kill(int ready)
{
    scenario(ready ? "transferkill-ready" : "transferkill");
    if (ready)
        for (int i = 0; i < 3; i++)
            penv[i] = "TSDB_CRASH_AT=transfer-ready";
    init_transfer_wait_ms = ready ? 0 : 5000;
    struct tr_run x;
    tr_setup(&x);
    init_transfer_wait_ms = 0;
    struct meta_volume v, a = {0};
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    int L = server_of(v.leader), T = tr_other(L, L == 0 ? 2 : 0), via = tr_other(L, T);
    if (!ready)
        pause_server(T, 1);
    struct tr_async ta = {x.num, ids[T], 0, ""};
    pthread_t th;
    if (pthread_create(&th, NULL, tr_transfer_thread, &ta) != 0)
        die("pthread_create");
    if (ready) {
        if (await_exit(L, 30000) < 0)
            die("server %d did not stop at transfer-ready", L);
    } else {
        await_log_count(L, ": drains (written", 1, 30000);
        signal_child(pids[L], SIGKILL);
        if (await_exit(L, 5000) < 0)
            die("server %d did not die of SIGKILL", L);
        pause_server(T, 0);
    }
    uint64_t tk = now_ms();
    while (!(vol_rec(via, "tv", &a) && a.epoch > v.epoch && a.leader != v.leader))
        if (now_ms() - tk > 30000)
            die("no new leader of tv 30 s after its leader was killed %s", ready ? "after READY" : "in the drain");
        else
            usleep(20000);
    pthread_join(th, NULL);
    penv[L] = NULL;
    await_isr(via, "tv", 2, 30000, "the killed leader out of the ISR"); /* else the ISR of 3 below is the grant's */
    start(L);
    await_isr(via, "tv", 3, 60000, "the killed leader back in the ISR");
    tr_await_acks(&x, now_ms(), "after the killed leader came back");
    printf("  old leader killed %s: node %u leads at epoch %" PRIu64 " %" PRIu64 " ms later; the transfer: %s%s%s\n",
           ready ? "after READY" : "in the drain", a.leader, a.epoch, now_ms() - tk, ta.rc == 1 ? "lost" : ta.rc ? cluster_strerror(ta.rc) : "OK",
           ta.why[0] ? ", " : "", ta.why);
    tr_finish(&x, ready ? "transferkill-ready" : "transferkill", 1);
}
static void scen_transferkill(void)
{
    tr_kill(0);
    tr_kill(1);
}

/* transferraftkill: READY went to a Raft leader (server 0) that was stopped (SIGSTOP) during the drain (the target
 * stopped too, so the drain waits) and is then killed: nothing promotes. The next Raft leader's CANCEL (its first duty
 * round) lets the old leader admit again within an election and a round, long before READY's hard cap (10 x 5000 ms).
 * Mutant nocancel (TSDB_CLUSTER_MUTANT) waits for the cap and fails it. */
static void scen_transferraftkill(void)
{
    scenario("transferraftkill");
    init_transfer_wait_ms = 5000;
    struct tr_run x;
    tr_setup(&x);
    init_transfer_wait_ms = 0;
    struct meta_volume v;
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    int L = server_of(v.leader);
    char why[256];
    if (L == 0) { /* the volume's leader must outlive the Raft leader's kill */
        int rc = tr_transfer(x.num, ids[1], why, sizeof why);
        if (rc != 0)
            die("the transfer of tv to server 1: %s (%s)", cluster_strerror(rc), why);
        if (!vol_rec(0, "tv", &v) || (L = server_of(v.leader)) != 1)
            die("tv is not led by server 1 after its transfer there");
    }
    /* T is stopped only once L leads with every member in the ISR: stopped while L was still being promoted (a slow
     * machine, ASan), T fell out of the ISR, the drain asked the stopped Raft leader to take it back in, and the next
     * Raft leader's CANCEL came before any READY (the scenario's premise lost, not a fault of the transfer) */
    char lead[64];
    snprintf(lead, sizeof lead, "leads epoch %" PRIu64 " ", v.epoch);
    await_log_count(L, lead, 1, 30000);
    await_isr(L, "tv", 3, 30000, "every member in the ISR before the target is stopped");
    int T = tr_other(L, 0);
    pause_server(T, 1);
    struct tr_async ta = {x.num, ids[T], 0, ""};
    pthread_t th;
    if (pthread_create(&th, NULL, tr_transfer_thread, &ta) != 0)
        die("pthread_create");
    await_log_count(L, ": drains (written", 1, 30000);
    pause_server(0, 1);
    pause_server(T, 0);
    await_log_count(L, ": READY at", 1, 30000);
    signal_child(pids[0], SIGKILL);
    uint64_t tk = now_ms();
    if (await_exit(0, 5000) < 0)
        die("server 0 did not die of SIGKILL");
    stopped[0] = 0;
    pthread_join(th, NULL);
    await_log_count(L, "cancelled by the Raft leader", 1, 15000);
    uint64_t cancelled = now_ms() - tk;
    for (int k = 0; k < REP_NAMES; k++) /* the writers through L and T write again */
        if (x.w[k].server != 0) {
            while (__atomic_load_n(&x.w[k].last_ack_t0, __ATOMIC_ACQUIRE) <= tk)
                if (now_ms() - tk > 15000)
                    die("writer %d (through server %d) acknowledged nothing in 15 s after the Raft leader was killed",
                        k, x.w[k].server);
        }
                else
                    usleep(5000);
    uint64_t resumed = now_ms() - tk;
    if (tr_count(L, CL_TR_BLIND))
        die("server %d admitted %" PRIu64 " records blind", L, tr_count(L, CL_TR_BLIND));
    start(0);
    await_isr(L, "tv", 3, 60000, "every member in the ISR after the Raft leader's restart");
    printf("  the Raft leader killed after READY: CANCEL on node %u %" PRIu64 " ms later, writes again after %" PRIu64
           " ms, no record admitted blind\n",
           v.leader, cancelled, resumed);
    tr_finish(&x, "transferraftkill", 1);
}

/* transferraftdrain: the Raft leader killed while tv's leader drains (TSDB_REPLD_TEST=drainhold: a file on the volume
 * leader keeps the drain from READY; a stopped target would leave too few voters to elect a Raft leader). Nobody holds the transfer any
 * more: the new Raft leader's CANCEL (term << 32, its first duty rounds) ends the drain well before transfer_wait_ms
 * (10 s) would. The mutant nocancel leaves it to the drain's own timeout and fails the 8 s bound. */
static void scen_transferraftdrain(void)
{
    scenario("transferraftdrain");
    for (int i = 0; i < 3; i++)
        penv[i] = "TSDB_REPLD_TEST=drainhold";
    init_transfer_wait_ms = 10000;
    struct tr_run x;
    tr_setup(&x);
    init_transfer_wait_ms = 0;
    struct meta_volume v;
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    int L = server_of(v.leader);
    char why[256];
    if (L == 0) { /* the volume's leader must outlive the Raft leader's kill */
        int rc = tr_transfer(x.num, ids[1], why, sizeof why);
        if (rc != 0)
            die("the transfer of tv to server 1: %s (%s)", cluster_strerror(rc), why);
        if (!vol_rec(0, "tv", &v) || (L = server_of(v.leader)) != 1)
            die("tv is not led by server 1 after its transfer there");
    }
    /* the hold begins once L serves (its promotion committed) */
    uint64_t t1 = now_ms();
    for (int k = 0; k < REP_NAMES; k++)
        while (__atomic_load_n(&x.w[k].last_ack_t0, __ATOMIC_ACQUIRE) <= t1)
            if (now_ms() - t1 > 15000)
                die("writer %d (through server %d) acknowledged nothing in 15 s before the drain", k, x.w[k].server);
            else
                usleep(5000);
    int T = tr_other(L, 0);
    char f[PATH_MAX + 40];
    snprintf(f, sizeof f, "%s/n%d/drainhold", base, L);
    FILE *fp = fopen(f, "w");
    if (!fp || fclose(fp) != 0)
        die("write %s: %s", f, strerror(errno));
    int drains = log_count(L, ": drains (written");
    struct tr_async ta = {x.num, ids[T], 0, ""};
    pthread_t th;
    if (pthread_create(&th, NULL, tr_transfer_thread, &ta) != 0)
        die("pthread_create");
    await_log_count(L, ": drains (written", drains + 1, 30000);
    uint64_t td = now_ms();
    signal_child(pids[0], SIGKILL);
    if (await_exit(0, 5000) < 0)
        die("server 0 did not die of SIGKILL");
    stopped[0] = 0;
    uint64_t tk = now_ms();
    pthread_join(th, NULL);
    if (log_count(L, ": READY at"))
        die("server %d sent READY with its drain held", L);
    await_log_count(L, "cancelled by the Raft leader", 1, 8000);
    uint64_t cancelled = now_ms() - tk;
    if (now_ms() - td >= 10000)
        die("the drain ended %" PRIu64 " ms after it began: by its own timeout, not by the new Raft leader's CANCEL",
            now_ms() - td);
    if (unlink(f) != 0)
        die("unlink %s: %s", f, strerror(errno));
    for (int k = 0; k < REP_NAMES; k++)
        if (x.w[k].server != 0) {
            while (__atomic_load_n(&x.w[k].last_ack_t0, __ATOMIC_ACQUIRE) <= tk)
                if (now_ms() - tk > 15000)
                    die("writer %d (through server %d) acknowledged nothing in 15 s after the Raft leader was killed",
                        k, x.w[k].server);
                else
                    usleep(5000);
        }
    if (tr_count(L, CL_TR_BLIND))
        die("server %d admitted %" PRIu64 " records blind", L, tr_count(L, CL_TR_BLIND));
    start(0);
    await_isr(L, "tv", 3, 60000, "every member in the ISR after the Raft leader's restart");
    printf("  the Raft leader killed during a drain: CANCEL on node %u %" PRIu64 " ms later (transfer_wait 10 s)\n",
           v.leader, cancelled);
    tr_finish(&x, "transferraftdrain", 1);
}

/* balance: leader_balance_s 5. tv's preferred leader (rep[0]) killed, the failover, then restarted: it leads tv again
 * within leader_balance_s + 5 s of its return to the ISR; with leader_balance_s 0 it does not (10 s). */
static void tr_balance(int on)
{
    scenario(on ? "balance" : "balance-off");
    init_leader_balance_s = on ? 5 : 0;
    struct tr_run x;
    tr_setup(&x);
    init_leader_balance_s = 0;
    struct meta_volume v, a = {0};
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    int P = server_of(v.rep[0].node), via = P == 0 ? 1 : 0;
    if (v.leader != v.rep[0].node)
        die("tv is led by node %u, not by its preferred leader node %u", v.leader, v.rep[0].node);
    signal_child(pids[P], SIGKILL);
    if (await_exit(P, 5000) < 0)
        die("server %d did not die of SIGKILL", P);
    uint64_t tk = now_ms();
    while (!(vol_rec(via, "tv", &a) && a.epoch > v.epoch && a.leader != v.leader))
        if (now_ms() - tk > 30000)
            die("no failover of tv 30 s after its leader was killed");
        else
            usleep(20000);
    /* the promotion's grant keeps the ISR of 3 until the new leader drops the dead member: without this wait the ISR
     * of 3 below is the old one, and the 10 s would count P's restart and rejoin as well */
    await_isr(via, "tv", 2, 30000, "the killed preferred leader out of the ISR");
    start(P);
    await_isr(via, "tv", 3, 60000, "the preferred leader back in the ISR");
    uint64_t tj = now_ms();
    int back = 0;
    while (now_ms() - tj < (on ? 10000u : 10000u)) {
        if (vol_rec(via, "tv", &a) && a.leader == v.rep[0].node) {
            back = 1;
            break;
        }
        usleep(20000);
    }
    if (on && !back)
        die("leader_balance_s 5: node %u does not lead tv 10 s after its return to the ISR (node %u does)",
            v.rep[0].node, a.leader);
    if (!on && back)
        die("leader_balance_s 0: node %u leads tv again after its return", v.rep[0].node);
    if (on && getenv("TR_DEBUG")) {
        for (int i = 0; i < 3; i++)
            printf("  server %d: started %" PRIu64 " done %" PRIu64 " timed out %" PRIu64 " cancelled %" PRIu64
                   " fell back %" PRIu64 " drains timed out %" PRIu64 "\n", i, tr_count(i, CL_TR_STARTED),
                   tr_count(i, CL_TR_DONE), tr_count(i, CL_TR_TIMEDOUT), tr_count(i, CL_TR_CANCELLED),
                   tr_count(i, CL_TR_FALLBACK), tr_count(i, CL_TR_DRAIN_TIMEDOUT));
        char cmd[PATH_MAX + 200];
        snprintf(cmd, sizeof cmd, "grep -H 'balance\\|transfer\\|drain\\|READY\\|CANCEL' %s/n*.log | cut -c1-240",
                 base);
        if (system(cmd) < 0)
            perror("system");
    }
    if (on)
        printf("  the preferred leader leads tv again %" PRIu64 " ms after its return to the ISR\n", now_ms() - tj);
    else
        printf("  leader_balance_s 0: tv stays on node %u for 10 s after node %u's return\n", a.leader,
               v.rep[0].node);
    tr_finish(&x, on ? "balance" : "balance-off", 1);
}
static void scen_balance(void)
{
    tr_balance(1);
    tr_balance(0);
}

/* balancetwo: leader_balance_s 5, four volumes on three members, so two of them prefer one node P. P killed (both fail
 * over), restarted: both lead on P again, one after the other (one transfer per server at a time, D15): in the Raft
 * leader's log the second balance transfer to P starts only after the first one's answer, and 1 s or more after the
 * first one's start. The first drain is held 1.5 s (TSDB_REPLD_TEST=drainhold), longer than that gap, so the one
 * transfer per server is checked on its own (mutant balancenobusy); BT_NOHOLD=1 leaves the drains alone, so the second
 * start waits only for the gap (balancenogap). */
static void scen_balancetwo(void)
{
    scenario("balancetwo");
    for (int i = 0; i < 3; i++)
        penv[i] = "TSDB_REPLD_TEST=drainhold";
    init_leader_balance_s = 5;
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    init_leader_balance_s = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    static const char *nm[4] = {"bv0", "bv1", "bv2", "bv3"};
    struct meta_volume v[4];
    for (int k = 0; k < 4; k++) {
        uint32_t num;
        int rc = vol_add(0, nm[k], 3, &num);
        if (rc != 0)
            die("volume add %s: %s", nm[k], cluster_strerror(rc));
        for (int i = 0; i < 3; i++)
            await_open_gen(0, nm[k], i, 1, 0);
        await_isr(0, nm[k], 3, 30000, "every replica in the ISR");
        if (!vol_rec(0, nm[k], &v[k]))
            die("no record of %s", nm[k]);
    }
    int a = -1, b = -1;
    for (int k = 0; k < 4 && b < 0; k++)
        for (int j = k + 1; j < 4 && b < 0; j++)
            if (v[k].rep[0].node == v[j].rep[0].node)
                a = k, b = j;
    if (b < 0)
        die("no two of four volumes on three members share a preferred leader");
    uint32_t pn = v[a].rep[0].node;
    for (int k = 0; k < 4; k++) /* the leader may still be moving to rep[0] from the add */
        for (uint64_t t0 = now_ms(); v[k].leader != v[k].rep[0].node; usleep(50000))
            if (now_ms() - t0 > 30000 || !vol_rec(0, nm[k], &v[k]))
                die("%s is led by node %u, not by its preferred leader %u", nm[k], v[k].leader, v[k].rep[0].node);
    int P = server_of(pn), via = P == 0 ? 1 : 0;
    signal_child(pids[P], SIGKILL);
    if (await_exit(P, 5000) < 0)
        die("server %d did not die of SIGKILL", P);
    int ab[2] = {a, b};
    for (int q = 0; q < 2; q++) {
        struct meta_volume x = {0};
        for (uint64_t t0 = now_ms(); !(vol_rec(via, nm[ab[q]], &x) && x.epoch > v[ab[q]].epoch && x.leader != pn);
             usleep(20000))
            if (now_ms() - t0 > 30000)
                die("no failover of %s 30 s after node %u was killed", nm[ab[q]], pn);
        await_isr(via, nm[ab[q]], 2, 30000, "the killed preferred leader out of the ISR");
    }
    char hold[3][PATH_MAX + 40];
    int held = !getenv("BT_NOHOLD"); /* BT_NOHOLD=1: transfers at their own pace, so the gap is what spaces them */
    for (int i = 0; held && i < 3; i++) { /* the first balance transfer drains 1.5 s: longer than the gap */
        snprintf(hold[i], sizeof hold[i], "%s/n%d/drainhold", base, i);
        FILE *fp = i == P ? NULL : fopen(hold[i], "w");
        if (i != P && (!fp || fclose(fp) != 0))
            die("write %s: %s", hold[i], strerror(errno));
    }
    start(P);
    for (int q = 0; q < 2; q++)
        await_isr(via, nm[ab[q]], 3, 60000, "the preferred leader back in the ISR");
    char bal_s[64];
    snprintf(bal_s, sizeof bal_s, "leader balance: transfer from node");
    for (uint64_t t0 = now_ms(); held; usleep(20000)) {
        int n = 0;
        for (int i = 0; i < 3; i++)
            n += i != P && log_count(i, bal_s) > 0;
        if (n)
            break;
        if (now_ms() - t0 > 20000)
            die("balancetwo: no balance transfer to node %u 20 s after its return", pn);
    }
    if (held)
        usleep(1500000);
    for (int i = 0; held && i < 3; i++)
        if (i != P && unlink(hold[i]) != 0)
            die("unlink %s: %s", hold[i], strerror(errno));
    uint64_t tj = now_ms(), back[2] = {0, 0};
    while ((!back[0] || !back[1]) && now_ms() - tj < 20000) {
        for (int q = 0; q < 2; q++) {
            struct meta_volume x;
            if (!back[q] && vol_rec(via, nm[ab[q]], &x) && x.leader == pn)
                back[q] = now_ms() - tj;
        }
        usleep(20000);
    }
    if (!back[0] || !back[1])
        die("balancetwo: %s and %s do not both lead on node %u 20 s after its return (%" PRIu64 ", %" PRIu64 " ms)",
            nm[a], nm[b], pn, back[0], back[1]);
    /* the order on the Raft leader that ran both: start, answer, start, answer, the starts 1 s apart or more */
    char start_s[64], done_s[64];
    snprintf(start_s, sizeof start_s, "leader balance: transfer from node");
    snprintf(done_s, sizeof done_s, ": transfer to node %u: node %u leads", pn, pn);
    int seen = 0;
    for (int i = 0; i < 3; i++) {
        if (i == P)
            continue;
        char path[PATH_MAX + 80], line[4096];
        snprintf(path, sizeof path, "%s/n%d.log", base, i);
        FILE *f = fopen(path, "r");
        int running = 0, n = 0;
        unsigned long long tlast = 0;
        while (f && fgets(line, sizeof line, f)) {
            if (strstr(line, start_s) && strstr(line, "to node") ) {
                char to[32];
                snprintf(to, sizeof to, "to node %u at", pn);
                if (!strstr(line, to))
                    continue;
                if (running)
                    die("balancetwo: server %d started a second balance transfer to node %u before the first one "
                        "answered: %s", i, pn, line);
                const char *ts = strstr(line, "(t=");
                unsigned long long t = 0;
                if (!ts || sscanf(ts, "(t=%llu ms)", &t) != 1)
                    die("balancetwo: no time in %s", line);
                if (n && t - tlast < 1000)
                    die("balancetwo: server %d started two balance transfers %llu ms apart, less than the 1 s gap: %s",
                        i, t - tlast, line);
                tlast = t, running = 1, n++;
            } else if (strstr(line, done_s))
                running = 0;
        }
        if (f)
            fclose(f);
        seen += n;
    }
    if (seen < 2)
        die("balancetwo: %d balance transfers to node %u in the logs, not 2", seen, pn);
    printf("  %s and %s lead on node %u again %" PRIu64 " and %" PRIu64 " ms after its return, one after the other\n",
           nm[a], nm[b], pn, back[0], back[1]);
    stop_all();
}

/* balancecut: leader_balance_s 5, a volume moved away from its preferred leader P (an operator's transfer), then P cut
 * one way from the Raft leader (TSDB_CLUSTER_TEST drop_fence_file: P drops every FENCE, its heartbeats still reach the
 * Raft leader, so it stays UP and rejoins the ISR): every balance transfer back to P fails (P never answers the fence;
 * the promotion is dropped, CANCEL, a failover by another name). Over 60 s the hold (from each rejoin) and the backoff
 * (5, 10, 20, 40 s) allow at most 4 attempts, each failure counted; mutant balanceflap (no hold, no backoff) tries
 * about once a second. */
static void scen_balancecut(void)
{
    scenario("balancecut");
    for (int i = 0; i < 3; i++)
        envs[i] = "drop_fence_file=1";
    init_leader_balance_s = 5;
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    init_leader_balance_s = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    static const char *nm[3] = {"bc0", "bc1", "bc2"};
    struct meta_volume v[3];
    int k = -1;
    for (int j = 0; j < 3; j++) {
        uint32_t num;
        int rc = vol_add(0, nm[j], 3, &num);
        if (rc != 0)
            die("volume add %s: %s", nm[j], cluster_strerror(rc));
        for (int i = 0; i < 3; i++)
            await_open_gen(0, nm[j], i, 1, 0);
        await_isr(0, nm[j], 3, 30000, "every replica in the ISR");
        for (uint64_t t0 = now_ms(); !vol_rec(0, nm[j], &v[j]) || v[j].leader != v[j].rep[0].node; usleep(50000))
            if (now_ms() - t0 > 30000)
                die("%s is not led by its preferred leader", nm[j]);
        if (k < 0 && server_of(v[j].rep[0].node) != 0) /* server 0 leads the metadata group: P is another */
            k = j;
    }
    if (k < 0)
        die("balancecut: every volume prefers the Raft leader's node");
    uint32_t pn = v[k].rep[0].node;
    int P = server_of(pn), Q = P == 1 ? 2 : 1;
    char why[256];
    int rc = tr_transfer(v[k].number, ids[Q], why, sizeof why);
    if (rc != 0)
        die("balancecut: transfer %s to node %u: %s (%s)", nm[k], ids[Q], cluster_strerror(rc), why);
    /* Wait until P's volume manager has stepped past v[k].epoch: otherwise dropfence holds P's own vwatch at the old
     * epoch as leader (server/cluster.c drop_fence_file), which drops P out of the ISR so balance never targets P. */
    for (uint64_t tw = now_ms();;) {
        struct view vw;
        view(P, &vw);
        int seen = 0;
        for (uint32_t i = 0; i < vw.st.nheard && !seen; i++)
            if (vw.st.heard[i].id == ids[P])
                for (uint32_t j = 0; j < vw.st.heard[i].nvols; j++)
                    if (vw.st.heard[i].vols[j].v.volume == v[k].number &&
                        vw.st.heard[i].vols[j].v.epoch > v[k].epoch)
                        seen = 1;
        view_free(&vw);
        if (seen)
            break;
        if (now_ms() - tw > 4000)
            die("balancecut: server %d did not step past epoch %" PRIu64 " of %s", P, v[k].epoch, nm[k]);
        usleep(20000);
    }
    state_flag(P, "dropfence", 1); /* before the hold of 5 s runs out */
    uint64_t b0[3] = {0}, d0 = 0;
    for (int i = 0; i < 3; i++)
        b0[i] = tr_count(i, CL_TR_BALANCE), d0 += tr_count(i, CL_TR_DONE);
    uint64_t t0 = now_ms();
    struct meta_volume x;
    while (now_ms() - t0 < 60000) {
        if (vol_rec(0, nm[k], &x) && x.leader == pn)
            die("balancecut: node %u leads %s although it answers no fence", pn, nm[k]);
        usleep(200000);
    }
    uint64_t bal = 0, done = 0, failed = 0, max_per = 0;
    int max_s = 0;
    for (int i = 0; i < 3; i++) {
        uint64_t bi = tr_count(i, CL_TR_BALANCE) - b0[i];
        bal += bi;
        if (bi > max_per)
            max_per = bi, max_s = i;
        done += tr_count(i, CL_TR_DONE);
        failed += tr_count(i, CL_TR_TIMEDOUT) + tr_count(i, CL_TR_CANCELLED) + tr_count(i, CL_TR_FALLBACK);
    }
    done -= d0;
    printf("  %s cut one way from its preferred node %u: %" PRIu64 " balance transfers in 60 s (max %" PRIu64
           " on one Raft leader), %" PRIu64 " done, %" PRIu64 " failed\n",
           nm[k], pn, bal, max_per, done, failed);
    if (bal < 1)
        die("balancecut: no balance transfer to node %u in 60 s", pn);
    /* Backoff state lives in memory on each Raft leader (ctransfer.c), so a Raft election during the 60 s lets a new
     * leader start its own backoff sequence (4 + 1 = 5 across two leaders). No single leader may exceed 4 in 60 s, and
     * mutant balanceflap tries ~25 times on a leader. */
    if (max_per > 4)
        die("balancecut: server %d started %" PRIu64 " balance transfers to node %u in 60 s, more than the hold and "
            "the backoff allow (4)", max_s, max_per, pn);
    for (uint64_t t1 = now_ms(); failed < bal && now_ms() - t1 < 20000; usleep(200000)) { /* one may be under way */
        failed = 0;
        for (int i = 0; i < 3; i++)
            failed += tr_count(i, CL_TR_TIMEDOUT) + tr_count(i, CL_TR_CANCELLED) + tr_count(i, CL_TR_FALLBACK);
    }
    if (done || failed < bal)
        die("balancecut: of %" PRIu64 " balance transfers %" PRIu64 " done and %" PRIu64 " counted as failed", bal, done,
            failed);
    state_flag(P, "dropfence", 0);
    stop_all();
}

/* balancehb: leader_balance_s 5, a volume moved away from its preferred leader P, then P's heartbeats to the Raft
 * leader cut and healed again and again (TSDB_CLUSTER_TEST drop_hb_file on the Raft leader: 4 s cut, 3 s healed, or
 * BH_CUT_MS, BH_HEAL_MS; P's data links untouched, so it stays in the ISR and answers fences). The Raft leader must see
 * P other than UP in the cuts, and over 60 s at most 2 balance transfers start and P takes the lead at most twice (no
 * back-and-forth every leader_balance_s). A balance never starts while P is not UP, and a cut does not depose a P that
 * leads (its fence answers and data go on), so one transfer in a healed window ends it. balanceflap is caught by
 * balancecut, where every transfer fails. */
static void scen_balancehb(void)
{
    scenario("balancehb");
    for (int i = 0; i < 3; i++)
        envs[i] = "drop_hb_file=1";
    init_leader_balance_s = 5;
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    init_leader_balance_s = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    static const char *nm[3] = {"bh0", "bh1", "bh2"};
    struct meta_volume v[3];
    int k = -1;
    for (int j = 0; j < 3; j++) {
        uint32_t num;
        int rc = vol_add(0, nm[j], 3, &num);
        if (rc != 0)
            die("volume add %s: %s", nm[j], cluster_strerror(rc));
        for (int i = 0; i < 3; i++)
            await_open_gen(0, nm[j], i, 1, 0);
        await_isr(0, nm[j], 3, 30000, "every replica in the ISR");
        for (uint64_t t0 = now_ms(); !vol_rec(0, nm[j], &v[j]) || v[j].leader != v[j].rep[0].node; usleep(50000))
            if (now_ms() - t0 > 30000)
                die("%s is not led by its preferred leader", nm[j]);
        if (k < 0 && server_of(v[j].rep[0].node) != 0) /* server 0 leads the metadata group: P is another */
            k = j;
    }
    if (k < 0)
        die("balancehb: every volume prefers the Raft leader's node");
    uint32_t pn = v[k].rep[0].node;
    int P = server_of(pn), Q = P == 1 ? 2 : 1;
    char why[256];
    int rc = tr_transfer(v[k].number, ids[Q], why, sizeof why);
    if (rc != 0)
        die("balancehb: transfer %s to node %u: %s (%s)", nm[k], ids[Q], cluster_strerror(rc), why);
    char f[PATH_MAX + 64];
    server_dir(0, f, sizeof f);
    strcat(f, "/state/drophb");
    uint64_t b0 = 0;
    for (int i = 0; i < 3; i++)
        b0 += tr_count(i, CL_TR_BALANCE);
    uint64_t t0 = now_ms();
    uint32_t last = ids[Q], moves = 0, led = 0, downs = 0;
    int cut = 0;
    uint64_t flip = 0, cut_ms = getenv("BH_CUT_MS") ? strtoull(getenv("BH_CUT_MS"), 0, 10) : 4000,
             heal_ms = getenv("BH_HEAL_MS") ? strtoull(getenv("BH_HEAL_MS"), 0, 10) : 3000;
    while (now_ms() - t0 < 60000) {
        if (now_ms() >= flip) {
            cut = !cut;
            if (cut) {
                FILE *fp = fopen(f, "w");
                if (!fp || fprintf(fp, "%u\n", pn) < 0 || fclose(fp) != 0)
                    die("write %s: %s", f, strerror(errno));
            } else if (unlink(f) != 0)
                die("unlink %s: %s", f, strerror(errno));
            flip = now_ms() + (cut ? cut_ms : heal_ms);
        }
        struct view lv;
        view(0, &lv);
        const struct meta_member *mm = meta_member(&lv.m, pn);
        downs += cut && mm && mm->state != META_UP;
        view_free(&lv);
        struct meta_volume x;
        if (vol_rec(0, nm[k], &x) && x.leader && x.leader != last) {
            moves++;
            led += x.leader == pn;
            last = x.leader;
        }
        usleep(100000);
    }
    if (cut && unlink(f) != 0)
        die("unlink %s: %s", f, strerror(errno));
    uint64_t bal = 0;
    for (int i = 0; i < 3; i++)
        bal += tr_count(i, CL_TR_BALANCE);
    bal -= b0;
    printf("  %s with node %u's heartbeats cut %" PRIu64 " ms of every %" PRIu64 ": seen not UP %u times, %" PRIu64
           " balance transfers in 60 s, %u leader changes, %u to node %u\n", nm[k], pn, cut_ms, cut_ms + heal_ms, downs,
           bal, moves, led, pn);
    if (!downs)
        die("balancehb: the Raft leader never saw node %u other than UP: the cut did not take", pn);
    if (bal > 2 || led > 2)
        die("balancehb: %" PRIu64 " balance transfers to node %u in 60 s and %u leader changes to it: the volume "
            "follows the flap", bal, pn, led);
    stop_all();
}

/* transfer: TRANSFERS transfers of one volume round its three members under 4 writers (each through another
 * member, forwarded). D14: every transfer answers once its target leads, the ISR stays whole (the old leader is never
 * dropped as unanswered), no write's outcome is unknown, every acknowledged row is on every member at the end and no
 * member cut its log. The write pause of each transfer (the longest write that overlapped it) is reported. Mutants
 * (TSDB_CLUSTER_MUTANT transferanycand transferfewreplies, TSDB_REPLD_MUTANT transfernodrain transferadmit) fail it. */
static void scen_transfer(void)
{
    scenario("transfer");
    int transfers = getenv("TR_TRANSFERS") ? atoi(getenv("TR_TRANSFERS")) : 100;
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "tv", 3, &num)) != 0 || num != 1)
        die("volume add tv: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "tv", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "tv", &v))
        die("no record of tv");
    int L = server_of(v.leader);
    tsdbc *c = client(L);
    struct tr_writer w[REP_NAMES];
    pthread_t th[REP_NAMES];
    memset(w, 0, sizeof w);
    for (int k = 0; k < REP_NAMES; k++) {
        w[k].server = k % 3;
        w[k].id = rep_series(c, rep_names[k], "tv", 30000);
        w[k].ts = 1000000;
    }
    w[REP_NAMES - 1].noretry = 1; /* its refusals are definite, and tr_check requires each of them absent */
    w[REP_NAMES - 1].via = w[REP_NAMES - 1].server;
    /* TR_PRELOAD_MB: that much WAL written first and kept by the replicas (past their commit floor, under
     * repl_retain_mb 4096 and repl_retain_s 1800 by default), so the first targets' promotions have it in their kept
     * segments (r3-scope/PLAN.md:123); measured, not judged. The leader keeps a flushed segment only while a replica
     * needs it, so its own WAL stays small once both have caught up: the loop counts the replicas' */
    uint64_t preload = getenv("TR_PRELOAD_MB") ? strtoull(getenv("TR_PRELOAD_MB"), NULL, 10) << 20 : 0;
    if (preload) {
        enum { PB = 60000 }; /* below wal_max_batch_rows: through the WAL, not straight to a part */
        int64_t *pts = malloc(PB * sizeof *pts);
        float *pv = malloc(PB * sizeof *pv);
        if (!pts || !pv)
            die("out of memory");
        tsdb_sid pid = rep_series(c, "preload", "tv", 30000);
        int64_t t = 1;
        size_t rows = 0;
        uint64_t p0 = now_ms(), until = p0 + 600000;
        for (;;) {
            int short_ = 0;
            for (int i = 0; i < 3; i++)
                if (i != L && wal_bytes(i, num) < preload)
                    short_ = 1;
            if (!short_)
                break;
            if (now_ms() > until)
                die("the replicas keep %" PRIu64 " / %" PRIu64 " / %" PRIu64 " MB of WAL of tv after %zu rows of preload",
                    wal_bytes(0, num) >> 20, wal_bytes(1, num) >> 20, wal_bytes(2, num) >> 20, rows);
            for (int j = 0; j < PB; j++, t++)
                pts[j] = t, pv[j] = (float)(t * 7919 % 100003) / 7.0f;
            if ((rc = tsdbc_insert_series(c, pid, pts, pv, PB)) != 0)
                die("preload insert: %s", tsdbc_strerror(rc));
            rows += PB;
        }
        free(pts);
        free(pv);
        printf("  preload: %zu rows in %" PRIu64 " ms; WAL of tv kept: %" PRIu64 " / %" PRIu64 " / %" PRIu64 " MB\n",
               rows, now_ms() - p0, wal_bytes(0, num) >> 20, wal_bytes(1, num) >> 20, wal_bytes(2, num) >> 20);
    }
    tsdbc_close(c);
    await_isr(0, "tv", 3, 30000, "every replica in the ISR before the transfers");
    for (int k = 0; k < REP_NAMES; k++)
        if (pthread_create(&th[k], NULL, tr_write_thread, &w[k]) != 0)
            die("pthread_create");
    usleep(500000);
    uint64_t *win = calloc((size_t)transfers * 2, sizeof *win), *pause = calloc((size_t)transfers, sizeof *pause);
    if (!win || !pause)
        die("out of memory");
    for (int t = 0; t < transfers; t++) {
        if (!vol_rec(0, "tv", &v))
            die("no record of tv");
        await_isr(0, "tv", 3, 30000, "every replica in the ISR before a transfer");
        uint32_t to = 0;
        for (uint32_t k = 0; k < v.nrep; k++) /* the next member round the replicas */
            if (v.rep[k].node == v.leader)
                to = v.rep[(k + 1) % v.nrep].node;
        char why[256];
        win[2 * t] = now_ms();
        rc = tr_transfer(num, to, why, sizeof why);
        win[2 * t + 1] = now_ms();
        if (rc != 0)
            die("transfer %d of tv from node %u to node %u: %s (%s)", t, v.leader, to, cluster_strerror(rc), why);
        struct meta_volume a = {0};
        if (!vol_rec(0, "tv", &a) || a.leader != to || a.epoch <= v.epoch)
            die("transfer %d answered OK, but node %u leads tv at epoch %" PRIu64 " (wanted node %u past %" PRIu64 ")",
                t, a.leader, a.epoch, to, v.epoch);
        if (a.nisr != v.nrep)
            die("transfer %d to node %u: the ISR has %u members right after it (a member dropped as unanswered)", t,
                to, a.nisr);
        /* every writer acknowledged once after it before the next: a write refused across back-to-back transfers
         * would add their windows up (and the client's MOVED backoff, which grows with a request's tries) */
        for (int k = 0; k < REP_NAMES; k++) {
            uint64_t until = now_ms() + 30000;
            while (__atomic_load_n(&w[k].last_ack_t0, __ATOMIC_ACQUIRE) <= win[2 * t + 1])
                if (now_ms() > until)
                    die("writer %d (through server %d) acknowledged nothing in 30 s after transfer %d (its latest "
                        "answer %s)", k, w[k].server, t, ers(__atomic_load_n(&w[k].last_rc, __ATOMIC_RELAXED)));
                else
                    usleep(5000);
        }
    }
    for (int k = 0; k < REP_NAMES; k++)
        __atomic_store_n(&w[k].stop, 1, __ATOMIC_RELEASE);
    for (int k = 0; k < REP_NAMES; k++)
        pthread_join(th[k], NULL);
    int acked = 0, refused = 0, indet = 0;
    for (int k = 0; k < REP_NAMES; k++)
        acked += w[k].acked, refused += w[k].refused, indet += w[k].indet;
    if (indet)
        die("%d writes of %d had an unknown outcome across %d transfers (D14 promises definite answers)", indet,
            acked + refused + indet, transfers);
    if (w[REP_NAMES - 1].unavail < 1)
        die("the writer without retries had no write refused UNAVAILABLE across %d transfers (%d MOVED): the check "
            "that rows refused in a drain are absent would see none", transfers,
            w[REP_NAMES - 1].refused - w[REP_NAMES - 1].unavail);
    printf("  the writer without retries: %d refused UNAVAILABLE (drains, handovers), %d MOVED, each checked absent\n",
           w[REP_NAMES - 1].unavail, w[REP_NAMES - 1].refused - w[REP_NAMES - 1].unavail);
    for (int t = 0; t < transfers; t++)
        for (int k = 0; k < REP_NAMES; k++)
            for (size_t j = 0; j < w[k].n; j++)
                if (w[k].w[j].t0 <= win[2 * t + 1] && w[k].w[j].t1 >= win[2 * t] &&
                    w[k].w[j].t1 - w[k].w[j].t0 > pause[t])
                    pause[t] = w[k].w[j].t1 - w[k].w[j].t0;
    uint64_t took = 0;
    for (int t = 0; t < transfers; t++)
        took += win[2 * t + 1] - win[2 * t];
    if (getenv("TR_DEBUG")) /* the slow writes: which writer, when, how long, how it ended */
        for (int k = 0; k < REP_NAMES; k++)
            for (size_t j = 0; j < w[k].n; j++)
                if (w[k].w[j].t1 - w[k].w[j].t0 > 300)
                    printf("  slow write: writer %d via server %d at +%" PRIu64 " ms took %" PRIu64 " ms: %s\n", k,
                           w[k].server, w[k].w[j].t0 - win[0], w[k].w[j].t1 - w[k].w[j].t0, ers(w[k].w[j].rc));
    if (getenv("TR_DEBUG"))
        for (int t = 0; t < transfers; t++)
            printf("  transfer %d: +%" PRIu64 " .. +%" PRIu64 " ms\n", t, win[2 * t] - win[0], win[2 * t + 1] - win[0]);
    qsort(pause, (size_t)transfers, sizeof *pause, cmp_u64);
    uint64_t cuts = 0;
    for (int i = 0; i < 3; i++) {
        uint64_t n = tr_count(i, CL_TR_CUTS);
        if (n)
            die("server %d cut its log %" PRIu64 " times across the transfers", i, n);
        cuts += n;
    }
    uint64_t done = tr_count(0, CL_TR_DONE), started = tr_count(0, CL_TR_STARTED);
    if (done != (uint64_t)transfers || started != (uint64_t)transfers)
        die("STATUS of the Raft leader counts %" PRIu64 " transfers started and %" PRIu64 " done, not %d", started,
            done, transfers);
    /* every member answered every transfer's fence and every answer counted (the candidate filter passes them all, so
     * the grant leaves no member `unanswered`): the Raft leader's "proposes" lines all say 3 of 3 */
    int props = 0, whole = 0;
    for (int i = 0; i < 3; i++)
        props += log_count(i, " fenced members answered"), whole += log_count(i, " (3 of 3 fenced members answered");
    if (props != whole || whole < transfers)
        die("of %d promotions proposed %d counted the answers of all 3 members, %d transfers", props, whole, transfers);
    await_isr(0, "tv", 3, 30000, "every replica in the ISR at the end");
    stop_all();
    tr_check(w, "transfer");
    printf("  %d transfers round 3 members under %d writers (mean %.0f ms each): %d writes acknowledged, %d refused "
           "(definite), 0 unknown, %" PRIu64 " cuts; every acknowledged row on every member\n",
           transfers, REP_NAMES, (double)took / transfers, acked, refused, cuts);
    printf("  write pause of a transfer: p50 %" PRIu64 " ms, p99 %" PRIu64 " ms, max %" PRIu64 " ms\n",
           pause[transfers / 2], pause[(transfers * 99) / 100 < transfers ? (transfers * 99) / 100 : transfers - 1],
           pause[transfers - 1]);
    for (int k = 0; k < REP_NAMES; k++)
        free(w[k].w);
    free(win);
    free(pause);
}

/* ------------------------------------------------------------------ r4-move: moving a log replica (cmove.c) */

/* one record of server w's voltrace (TSDB_CLUSTER_TEST vol_trace=1, cmove_trace): a line per applied entry that
 * changed volume 1's set, epoch, leader or ISR, so a reader of the whole file has seen every committed record */
struct mvt {
    uint64_t index, epoch, isrv;
    uint32_t leader, nisr, isr[16], nrep, rep[16], learner[16];
};

static int mvt_has(const uint32_t *a, uint32_t n, uint32_t node)
{
    for (uint32_t k = 0; k < n; k++)
        if (a[k] == node)
            return 1;
    return 0;
}

static int mvt_parse(const char *ln, struct mvt *t)
{
    if (!strncmp(ln, "req ", 4) || !strstr(ln, " v1 ")) /* a volume leader's ISR request (mv_leave_asked) */
        return 0;
    const char *e = strstr(ln, " epoch "), *l = strstr(ln, " leader "), *i = strstr(ln, " isr "),
               *r = strstr(ln, " rep "), *iv = strstr(ln, " isrv ");
    if (!e || !l || !i || !r || !iv || r < i)
        die("voltrace: a line without its fields: %s", ln);
    memset(t, 0, sizeof *t);
    t->index = strtoull(ln, NULL, 10);
    t->epoch = strtoull(e + 7, NULL, 10);
    t->isrv = strtoull(iv + 6, NULL, 10);
    t->leader = (uint32_t)strtoul(l + 8, NULL, 10);
    for (const char *p = i + 5; p < r && t->nisr < 16;) {
        char *q;
        t->isr[t->nisr++] = (uint32_t)strtoul(p, &q, 10);
        if (q == p)
            break;
        p = *q == ',' ? q + 1 : q;
    }
    for (const char *p = r + 5; *p && *p != '\n' && t->nrep < 16;) {
        char *q;
        uint32_t node = (uint32_t)strtoul(p, &q, 10);
        if (q == p)
            break;
        t->learner[t->nrep] = 0;
        if (!strncmp(q, ":L", 2))
            t->learner[t->nrep] = 1, q += 2;
        if (*q == '<')
            strtoul(q + 1, &q, 10);
        t->rep[t->nrep++] = node;
        p = *q == ',' ? q + 1 : q;
    }
    return 1;
}

/* whether a volume leader asked for an ISR without `a` as a move's leave (the core's REPL_WHY_LEAVE) at the basis
 * (epoch, isrv): the "req" lines repld.c's trace_isr_req adds to the leader's voltrace before the request leaves, so
 * one is there before any server applies the record it led to */
static int mv_leave_asked(uint32_t a, uint64_t epoch, uint64_t isrv)
{
    int hit = 0;
    for (int i = 0; i < N && !hit; i++) {
        char p[PATH_MAX + 96], ln[1100];
        server_dir(i, p, sizeof p);
        strcat(p, "/state/voltrace");
        FILE *f = fopen(p, "r");
        while (f && !hit && fgets(ln, sizeof ln, f)) {
            unsigned long long e, iv;
            char why[16];
            int off = 0;
            if (sscanf(ln, "req v1 epoch %llu isrv %llu why %15s isr %n", &e, &iv, why, &off) != 3 || !off ||
                e != epoch || iv != isrv || strcmp(why, "leave"))
                continue;
            uint32_t isr[16], n = 0;
            for (const char *q = ln + off; n < 16;) {
                char *z;
                unsigned long v = strtoul(q, &z, 10);
                if (z == q)
                    break;
                isr[n++] = (uint32_t)v;
                q = *z == ',' ? z + 1 : z;
            }
            hit = !mvt_has(isr, n, a);
        }
        if (f)
            fclose(f);
    }
    return hit;
}

/* the watched check of a move of volume 1 from node a to node b over every committed record (server w's voltrace; w is
 * never killed): once b is a member, a may leave the ISR as the move's shrink only after b joined it, and the ISR it
 * leaves behind has at least as many members as the ISR had in the last record before b joined (the move never lowers
 * the number of in-sync copies). The move's shrink is the record whose basis the volume leader asked for as a leave
 * (mv_leave_asked); a shrink for lag, of a or of another member, is not the move's and is not judged (review F3), but
 * counted. Records at or below `from` are skipped: a second move in one scenario must not count the first one's history
 * (b may have been a member then). */
struct mv_watch {
    uint32_t a, b;
    uint64_t from;
    int b_member, joined, a_left, ended, b_gone, judged, lag_left;
    uint32_t min, lines;
    struct mvt last;
};

static void move_watch(int w, struct mv_watch *x)
{
    uint32_t a = x->a, b = x->b;
    uint64_t from = x->from;
    memset(x, 0, sizeof *x);
    x->a = a, x->b = b, x->from = from;
    char p[PATH_MAX + 96];
    server_dir(w, p, sizeof p);
    strcat(p, "/state/voltrace");
    FILE *f = fopen(p, "r");
    if (!f)
        return;
    char ln[1100];
    int prev_a = 0;
    struct mvt t, prev = {0};
    while (fgets(ln, sizeof ln, f)) {
        if (!mvt_parse(ln, &t) || t.index <= from)
            continue;
        x->lines++;
        int a_in = mvt_has(t.isr, t.nisr, a), b_in = mvt_has(t.isr, t.nisr, b);
        int a_mem = mvt_has(t.rep, t.nrep, a), b_mem = mvt_has(t.rep, t.nrep, b);
        if (b_mem)
            x->b_member = 1;
        if (!b_in && !x->joined)
            x->min = t.nisr;
        else if (b_in && x->b_member && !x->joined)
            x->joined = 1;
        if (prev_a && !a_in && x->b_member && !mv_leave_asked(a, prev.epoch, prev.isrv))
            x->lag_left++;
        else if (prev_a && !a_in && x->b_member) {
            x->judged++;
            if (!x->joined)
                die("move: node %" PRIu32 " left the ISR of plant at entry %" PRIu64 " before node %" PRIu32
                    " joined it (ISR of %" PRIu32 ")", a, t.index, b, t.nisr);
            if (t.nisr < x->min)
                die("move: node %" PRIu32 " left the ISR of plant at entry %" PRIu64 " with %" PRIu32 " members left, "
                    "fewer than the %" PRIu32 " before node %" PRIu32 " joined", a, t.index, t.nisr, x->min, b);
            x->a_left = 1;
        }
        int bl = 0;
        for (uint32_t k = 0; k < t.nrep; k++)
            if (t.rep[k] == b)
                bl = (int)t.learner[k];
        x->ended = !a_mem && b_mem && !bl && b_in;
        x->b_gone = x->b_member && !b_mem && a_mem && a_in;
        prev_a = a_in;
        prev = t;
        x->last = t;
    }
    fclose(f);
}

static void await_move(int w, struct mv_watch *x, int cancelled, int ms, const char *what)
{
    uint64_t t0 = now_ms();
    for (;;) {
        move_watch(w, x);
        if (!cancelled && x->ended && !x->judged) /* the check would judge nothing: the trace lost its requests */
            die("%s: the move of plant from node %" PRIu32 " to node %" PRIu32 " ended with no shrink of node %" PRIu32
                " judged (%d departures not asked as the move's leave)", what, x->a, x->b, x->a, x->lag_left);
        if (cancelled ? x->b_gone : x->ended)
            return;
        if (now_ms() - t0 > (uint64_t)ms)
            die("%s: the move of plant from node %" PRIu32 " to node %" PRIu32 " did not %s in %d ms (%" PRIu32
                " records; last: entry %" PRIu64 ", ISR of %" PRIu32 ", %" PRIu32 " members, b joined %d, a left %d)",
                what, x->a, x->b, cancelled ? "end cancelled" : "end", ms, x->lines, x->last.index, x->last.nisr,
                x->last.nrep, x->joined, x->a_left);
        usleep(100000);
    }
}

static void await_joined(int w, struct mv_watch *x, int ms)
{
    uint64_t t0 = now_ms();
    for (move_watch(w, x); !x->joined; move_watch(w, x))
        if (now_ms() - t0 > (uint64_t)ms)
            die("node %" PRIu32 " did not join the ISR of plant in %d ms", x->b, ms);
        else
            usleep(50000);
}

/* the admin op (the CLI's encoding; `move` itself goes through the CLI) to the Raft leader, followed from server via */
static void move_op(int via, int from, int to, int cancel, const char *want)
{
    uint8_t body[16], *reply = NULL;
    size_t rl = 0, bl = cluster_volume_move_encode(1, ids[from], ids[to],
                                                   CLUSTER_MOVE_LOG | (cancel ? CLUSTER_MOVE_CANCEL : 0), body);
    int rc = admin(via, CLUSTER_OP_VOLUME_MOVE, body, bl, 1, &reply, &rl);
    char why[512];
    snprintf(why, sizeof why, "%.*s", (int)(rl < 400 ? rl : 400), reply ? (const char *)reply : "");
    free(reply);
    if (rc != 0 || !strstr(why, want))
        die("%smove of plant from server %d to server %d: %s (%s), not \"%s\"", cancel ? "cancel of the " : "", from,
            to, cluster_strerror(rc), why, want);
    printf("  %s", why);
}

/* an admin op the Raft leader must refuse with `want` in its answer (review F9: each of cmove_admin's checks);
 * log 0 leaves out CLUSTER_MOVE_LOG */
static void move_refused(int via, int from, int to, int cancel, int log, const char *want)
{
    uint8_t body[16], *reply = NULL;
    size_t rl = 0, bl = cluster_volume_move_encode(1, ids[from], ids[to],
                                                   (log ? CLUSTER_MOVE_LOG : 0) | (cancel ? CLUSTER_MOVE_CANCEL : 0),
                                                   body);
    int rc = admin(via, CLUSTER_OP_VOLUME_MOVE, body, bl, 1, &reply, &rl);
    char why[512];
    snprintf(why, sizeof why, "%.*s", (int)(rl < 400 ? rl : 400), reply ? (const char *)reply : "");
    free(reply);
    if (rc == 0 || !strstr(why, want))
        die("%smove of plant from server %d to server %d: %s (%s), not refused with \"%s\"",
            cancel ? "cancel of the " : "", from, to, cluster_strerror(rc), why, want);
}

static char move_hold[PATH_MAX + 96], move_penv[PATH_MAX * 2];
static const char *move_extra = ""; /* more of TSDB_CMOVE_TEST (",cancel_lose_leave=1"), before hold_shrink */

/* hold: the move's shrink waits while <base>/holdshrink exists (TSDB_CMOVE_TEST, every server). Always
 * duty_at_propose=1: the Raft leader runs its move duty right after proposing the ADD, in the round before the ADD
 * applies, which must not take the move for ended (review F2: STATUS said "cancelled" and the move resumed; move_status
 * requires cancelled 0) */
static void move_env(int hold)
{
    snprintf(move_hold, sizeof move_hold, "%s/holdshrink", base);
    snprintf(move_penv, sizeof move_penv, "TSDB_CMOVE_TEST=duty_at_propose=1%s%s%s", move_extra,
             hold ? ",hold_shrink=" : "", hold ? move_hold : "");
    move_extra = "";
    for (int i = 0; i < N; i++)
        penv[i] = move_penv;
    set_cenv = "setop_file=1,vol_trace=1";
}

static void move_hold_set(int on)
{
    if (on) {
        FILE *f = fopen(move_hold, "w");
        if (!f || fclose(f) != 0)
            die("%s: %s", move_hold, strerror(errno));
    } else if (unlink(move_hold) != 0 && errno != ENOENT)
        die("unlink %s: %s", move_hold, strerror(errno));
}

/* writers of the four series of plant, one thread each, to server s (lenient: through a transfer or a kill) */
struct mv_run {
    struct set_writer w[REP_NAMES];
    pthread_t th[REP_NAMES];
    uint64_t pre[REP_NAMES];
};

static void move_writers(struct mv_run *r, int s, int lead, int lenient)
{
    tsdbc *c = client(lead); /* the series are made on the leader (made through another member they are forwarded
                              * since fwd-series: fwdseries covers that), the writers write through s */
    for (int k = 0; k < REP_NAMES; k++) {
        tsdb_sid id = rep_series(c, rep_names[k], "plant", 30000);
        int64_t t = 1000;
        r->pre[k] = set_write(c, id, &t, 3, 1);
        memset(&r->w[k], 0, sizeof r->w[k]);
        r->w[k].port = cports[s], r->w[k].id = id, r->w[k].t = 10000000, r->w[k].lenient = lenient;
        if (pthread_create(&r->th[k], NULL, set_write_thread, &r->w[k]) != 0)
            die("pthread_create");
    }
    tsdbc_close(c);
    for (int k = 0; k < REP_NAMES; k++)
        await_batches(&r->w[k], 5, 20000);
}

static void move_writers_stop(struct mv_run *r)
{
    for (int k = 0; k < REP_NAMES; k++)
        __atomic_store_n(&r->w[k].stop, 1, __ATOMIC_RELEASE);
    for (int k = 0; k < REP_NAMES; k++) {
        pthread_join(r->th[k], NULL);
        if (r->w[k].rc != 0)
            die("a writer of %s: %s", rep_names[k], ers(r->w[k].rc));
        if (!r->w[k].acked) /* a lenient writer whose every batch was refused proves nothing */
            die("a writer of %s had no batch acknowledged (%" PRIu64 " sent)", rep_names[k], r->w[k].batches);
    }
}

/* after stop_all: every member of the final set holds the same rows of each series, every acknowledged one, and none
 * past what was sent (a lenient writer's refused or unknown batches may be there or not) */
static void move_rows(const struct mvt *t, const struct mv_run *r, const char *what)
{
    uint64_t rows[REP_NAMES], h[REP_NAMES], r0[REP_NAMES] = {0}, h0[REP_NAMES] = {0};
    for (uint32_t x = 0; x < t->nrep; x++) {
        int s = server_of(t->rep[x]);
        char dir[PATH_MAX + 80], v[PATH_MAX + 120];
        server_dir(s, dir, sizeof dir);
        snprintf(v, sizeof v, "%s/v1", dir);
        int rc = cvol_digest(v, rep_names, REP_NAMES, rows, h);
        if (rc != 0)
            die("%s: open %s read-only: %s", what, v, ers(rc));
        for (int k = 0; k < REP_NAMES; k++) {
            uint64_t lo = r->pre[k] + r->w[k].acked, hi = lo + r->w[k].unsure;
            if (rows[k] < lo || rows[k] > hi)
                die("%s: server %d holds %" PRIu64 " rows of %s, not in [%" PRIu64 ", %" PRIu64 "]", what, s, rows[k],
                    rep_names[k], lo, hi);
            if (x && (rows[k] != r0[k] || h[k] != h0[k]))
                die("%s: server %d's rows of %s differ from the first member's", what, s, rep_names[k]);
            r0[k] = rows[k], h0[k] = h[k];
        }
    }
}

static void move_dir_gone(int s)
{
    uint64_t t0 = now_ms();
    while (dir_has(s, "v1"))
        if (now_ms() - t0 > 30000)
            die("server %d still has v1 30 s after its replica moved away", s);
        else
            usleep(50000);
}

/* the servers of a 4-server plant: L its leader, X the one without a replica, two others (O[0] not the Raft leader R
 * when one of them is: a member paused or killed must not take the Raft leader with it) */
struct mv_servers {
    int L, X, R, O[2];
};

static void move_servers(const struct meta_volume *v, int L, struct mv_servers *s)
{
    s->L = L, s->X = -1, s->R = leader_of(0);
    int n = 0;
    for (int i = 0; i < 4; i++)
        if (rep_index(v, i) < 0)
            s->X = i;
        else if (i != L)
            s->O[n++] = i;
    if (s->X < 0 || n != 2)
        die("plant's replicas are not three of the four servers");
    if (s->O[0] == s->R) {
        int k = s->O[0];
        s->O[0] = s->O[1], s->O[1] = k;
    }
}

/* STATUS of server i, the Raft leader that runs a move: `running` 1: a line "move volume 1 node a -> node b: " names the
 * move; 0: no move runs and the counters say `done` moves done and none cancelled (condition wait: the duty counts a
 * move at the round that sees the REMOVE applied, which may follow the watch's record) */
static void move_status(int i, uint32_t a, uint32_t b, int running, uint64_t done, const char *what)
{
    char want[128];
    snprintf(want, sizeof want, "move volume 1 node %" PRIu32 " -> node %" PRIu32 ": ", a, b);
    uint64_t t0 = now_ms();
    for (;;) {
        struct view v;
        view(i, &v);
        int named = strstr(v.st.moves, want) != NULL;
        uint64_t d = v.st.ntr >= CL_TR_N ? v.st.tr[CL_TR_MV_DONE] : UINT64_MAX;
        uint64_t c = v.st.ntr >= CL_TR_N ? v.st.tr[CL_TR_MV_CANCELLED] : UINT64_MAX;
        uint64_t st = v.st.ntr >= CL_TR_N ? v.st.tr[CL_TR_MV_STARTED] : 0;
        char text[sizeof v.st.moves];
        snprintf(text, sizeof text, "%s", v.st.moves);
        view_free(&v);
        if (running ? named && st >= 1 : !text[0] && d == done && c == 0)
            return;
        if (now_ms() - t0 > 20000)
            die("%s: STATUS of server %d says moves started %" PRIu64 " done %" PRIu64 " cancelled %" PRIu64
                " and running \"%s\", not %s", what, i, st, d, c, text,
                running ? "the move as running" : "no move running and the move done");
        usleep(100000);
    }
}

/* move: under 4 writers a replica A (not the leader) moves to X through `tsdb cluster volume move`; every committed
 * record keeps the ISR without A at least as large as before X joined (move_watch); at the end A's directory is gone,
 * X is in the ISR and the three members hold the same rows, every acknowledged one. Mutants moveshrinkfirst (A shrunk
 * out before X joined), moveremovebeforeshrink (REMOVE of an ISR member: refused by meta, the move never ends) */
static void scen_move(void)
{
    scenario("move");
    move_env(0);
    struct meta_volume v;
    int L = set_setup(4, &v, 0);
    set_cenv = NULL;
    struct mv_servers s;
    move_servers(&v, L, &s);
    int A = s.O[1], B = s.X, W = s.O[0];
    await_isr(0, "plant", 3, 10000, "every replica up");
    struct mv_run r;
    move_writers(&r, L, L, 0);
    move_refused(s.R, A, B, 0, 0, "--log is required");
    move_refused(s.R, A, A, 0, 1, "the same node twice");
    move_refused(s.R, B, A, 0, 1, "the old node is not a member of the volume");
    move_refused(s.R, A, W == A ? L : W, 0, 1, "the new node is a member already");
    move_refused(s.R, A, B, 1, 1, "no such move is running");
    char p[META_ADDR_MAX], args[PATH_MAX * 2 + 256], out[2048];
    peer_of(s.R, p, sizeof p);
    snprintf(args, sizeof args, "cluster volume move %s 1 --log --from %" PRIu32 " --to %" PRIu32 " --secret-file %s",
             p, ids[A], ids[B], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "proposed"))
        die("tsdb %s: %s", args, out);
    printf("  %s", out);
    struct mv_watch x = {.a = ids[A], .b = ids[B]};
    await_move(W, &x, 0, 90000, "move");
    move_status(s.R, ids[A], ids[B], 0, 1, "move");
    move_dir_gone(A);
    for (int k = 0; k < REP_NAMES; k++)
        await_batches(&r.w[k], 10, 20000); /* the writes go on with the new set */
    move_writers_stop(&r);
    stop_all();
    move_watch(W, &x);
    move_rows(&x.last, &r, "after the move");
    printf("  plant moved from server %d to server %d under 4 writers: ISR never below %" PRIu32 " without the old "
           "member (%" PRIu32 " records), its v1 gone, the rows equal on the three members\n", A, B, x.min, x.lines);
}

/* movelag: a member C lags out of the ISR after X joined and before the shrink (held by TSDB_CMOVE_TEST): the move
 * waits (the ISR without A would have 2 members, it had 3 before X joined) until C is back. Mutant movenominisr
 * (DROP_MEMBER with min_isr 0: A leaves with C away, move_watch fails) */
static void scen_movelag(void)
{
    scenario("movelag");
    move_env(1);
    struct meta_volume v;
    int L = set_setup(4, &v, 0);
    set_cenv = NULL;
    struct mv_servers s;
    move_servers(&v, L, &s);
    int A = s.O[1], C = s.O[0], B = s.X, W = L;
    await_isr(0, "plant", 3, 10000, "every replica up");
    struct mv_run r;
    move_writers(&r, L, L, 0);
    move_hold_set(1);
    move_op(s.R, A, B, 0, "proposed");
    struct mv_watch x = {.a = ids[A], .b = ids[B]};
    await_joined(W, &x, 60000);
    move_status(s.R, ids[A], ids[B], 1, 0, "movelag"); /* held before its shrink: STATUS names it */
    move_refused(s.R, C, A, 0, 1, "a move of the volume is running");
    move_refused(s.R, C, B, 1, 1, "no such move is running"); /* a cancel names the running move's two nodes */
    pause_server(C, 1);
    await_isr(L, "plant", 3, 20000, "C lagged out of the ISR after X joined");
    move_hold_set(0);
    usleep(5000000); /* the shrink is sent every second: it must not take A out while C is away */
    move_watch(W, &x);
    if (x.a_left)
        die("movelag: A left the ISR while C was away"); /* move_watch dies first */
    pause_server(C, 0);
    await_move(W, &x, 0, 90000, "movelag");
    move_dir_gone(A);
    move_writers_stop(&r);
    stop_all();
    move_watch(W, &x);
    move_rows(&x.last, &r, "after the move");
    printf("  the move waited while server %d lagged (the ISR without the old member kept %" PRIu32 "), then ended\n", C,
           x.min);
}

/* moveleader: A is the volume's leader: a transfer first (to rep[0] or to X), then the move; the writers (lenient)
 * go on. Mutant moveleaderfirst (REMOVE of the leader's replica without a transfer: refused by meta; the move must
 * still end, so the scenario only fails if the mutant also breaks the end) */
static void scen_moveleader(void)
{
    scenario("moveleader");
    fwd_on = 1; /* the writers go through a member that does not lead */
    move_env(0);
    struct meta_volume v;
    int L = set_setup(4, &v, 0);
    set_cenv = NULL;
    struct mv_servers s;
    move_servers(&v, L, &s);
    int A = L, B = s.X, W = s.O[0];
    await_isr(0, "plant", 3, 10000, "every replica up");
    struct mv_run r;
    move_writers(&r, s.O[1], L, 1); /* through a member that stays */
    move_op(s.R, A, B, 0, "proposed");
    struct mv_watch x = {.a = ids[A], .b = ids[B]};
    await_move(W, &x, 0, 90000, "moveleader");
    if (x.last.leader == ids[A] || !x.last.leader)
        die("moveleader: plant is led by node %" PRIu32 " after the move of its leader's replica", x.last.leader);
    move_dir_gone(A);
    for (int k = 0; k < REP_NAMES; k++)
        await_batches(&r.w[k], 10, 30000);
    move_writers_stop(&r);
    stop_all();
    move_watch(W, &x);
    move_rows(&x.last, &r, "after the move of the leader's replica");
    printf("  the leader's replica moved from server %d to server %d: led by node %" PRIu32 " at the end\n", A, B,
           x.last.leader);
}

/* moverep0: with leader_balance_s 5 the leader is rep[0]; moving it puts X in its slot and X leads (the transfer
 * goes to X), so no balance transfer follows: the epoch stays for 10 s after the move */
static void scen_moverep0(void)
{
    scenario("moverep0");
    fwd_on = 1; /* the writers go through a member that does not lead */
    init_leader_balance_s = 5;
    move_env(0);
    struct meta_volume v;
    int L = set_setup(4, &v, 0);
    set_cenv = NULL;
    init_leader_balance_s = 0;
    uint64_t t0 = now_ms();
    while (!vol_rec(0, "plant", &v) || v.leader != v.rep[0].node || v.nisr != 3)
        if (now_ms() - t0 > 30000)
            die("plant is not led by rep[0] with an ISR of 3 after 30 s");
        else
            usleep(100000);
    L = server_of(v.leader);
    struct mv_servers s;
    move_servers(&v, L, &s);
    int A = L, B = s.X, W = s.O[0];
    struct mv_run r;
    move_writers(&r, s.O[1], L, 1);
    move_op(s.R, A, B, 0, "proposed");
    struct mv_watch x = {.a = ids[A], .b = ids[B]};
    await_move(W, &x, 0, 90000, "moverep0");
    if (!vol_rec(W, "plant", &v) || v.rep[0].node != ids[B])
        die("moverep0: rep[0] of plant is node %" PRIu32 ", not the new node %" PRIu32, v.rep[0].node, ids[B]);
    uint64_t epoch = x.last.epoch;
    usleep(10000000);
    move_watch(W, &x);
    if (x.last.epoch != epoch || x.last.leader != ids[B])
        die("moverep0: plant went from epoch %" PRIu64 " to %" PRIu64 " (leader node %" PRIu32 ") after the move",
            epoch, x.last.epoch, x.last.leader);
    move_writers_stop(&r);
    stop_all();
    move_rows(&x.last, &r, "after the move of rep[0]");
    printf("  rep[0] moved from server %d to server %d, which leads; no balance transfer in 10 s\n", A, B);
}

/* moveraft: the Raft leader is SIGKILLed between X's join and the REMOVE (the shrink held until then): the next Raft
 * leader finds the move in the record (`replaces`) and finishes it. Mutant movenoreplaces (a move this Raft leader did
 * not start is forgotten: the move never ends) */
static void scen_moveraft(void)
{
    scenario("moveraft");
    move_env(1);
    struct meta_volume v;
    int L = set_setup(4, &v, 0);
    set_cenv = NULL;
    struct mv_servers s;
    move_servers(&v, L, &s);
    await_isr(0, "plant", 3, 10000, "every replica up");
    char why[256];
    if (s.R == L) { /* the volume's leader outlives the Raft leader's kill */
        int rc = tr_transfer(1, ids[s.O[0]], why, sizeof why);
        if (rc != 0)
            die("the transfer of plant to server %d: %s (%s)", s.O[0], cluster_strerror(rc), why);
        uint64_t t0 = now_ms();
        while (!vol_rec(s.O[0], "plant", &v) || server_of(v.leader) != s.O[0] || v.nisr != 3)
            if (now_ms() - t0 > 30000)
                die("plant is not led by server %d with an ISR of 3 after its transfer", s.O[0]);
            else
                usleep(100000);
        L = s.O[0];
        move_servers(&v, L, &s);
    }
    /* A: a member that is neither the leader nor the Raft leader; B: X unless X is the Raft leader */
    int A = s.O[0] != s.R ? s.O[0] : s.O[1], B = s.X, W = -1;
    for (int i = 0; i < 4; i++)
        if (i != s.R && i != A && i != B)
            W = i;
    struct mv_run r;
    move_writers(&r, L, L, 1);
    move_hold_set(1);
    move_op(s.R, A, B, 0, "proposed");
    struct mv_watch x = {.a = ids[A], .b = ids[B]};
    await_joined(W, &x, 60000);
    stop(s.R, SIGKILL);
    uint64_t t0 = now_ms();
    int nr;
    while ((nr = leader_of(W)) < 0 || nr == s.R)
        if (now_ms() - t0 > 30000)
            die("no new Raft leader 30 s after the kill of server %d", s.R);
        else
            usleep(100000);
    start(s.R);
    move_hold_set(0);
    await_move(W, &x, 0, 90000, "moveraft");
    if (s.R != B)
        move_dir_gone(A);
    move_writers_stop(&r);
    stop_all();
    move_watch(W, &x);
    move_rows(&x.last, &r, "after the move across a Raft leader's kill");
    printf("  the Raft leader (server %d) killed after the join: server %d finished the move from %d to %d\n", s.R,
           nr, A, B);
}

/* movekill: X is SIGKILLed as soon as the ADD is applied (in its catch-up) and restarted: the move finishes. Then a
 * second move (of a member to the server the first one emptied) held before its shrink is cancelled after its join:
 * the learner goes, the old set is back and the member stays in the ISR */
static void scen_movekill(void)
{
    scenario("movekill");
    move_env(1);
    struct meta_volume v;
    int L = set_setup(4, &v, 0) /* keepall would replace TSDB_CMOVE_TEST */;
    set_cenv = NULL;
    struct mv_servers s;
    move_servers(&v, L, &s);
    int A = s.O[0], B = s.X, W = L != s.R ? L : s.O[1];
    if (B == s.R || A == s.R)
        A = s.O[1] != s.R ? s.O[1] : s.O[0];
    await_isr(0, "plant", 3, 10000, "every replica up");
    struct mv_run r;
    move_writers(&r, L, L, 1);
    struct mv_watch x = {.a = ids[A], .b = ids[B]};
    move_op(s.R == B ? W : s.R, A, B, 0, "proposed");
    uint64_t t0 = now_ms();
    for (move_watch(W, &x); !x.b_member; move_watch(W, &x))
        if (now_ms() - t0 > 20000)
            die("movekill: node %" PRIu32 " not a member 20 s after its move's ADD", ids[B]);
        else
            usleep(5000);
    int joined = x.joined;
    stop(B, SIGKILL);
    usleep(1000000);
    start(B);
    await_move(W, &x, 0, 120000, "movekill");
    move_dir_gone(A);
    printf("  server %d killed %s its catch-up and restarted: the move finished\n", B, joined ? "after" : "during");
    /* the cancel: C (a member, not the leader) to A, held before its shrink */
    int C = -1;
    for (uint32_t k = 0; k < x.last.nrep; k++)
        if (server_of(x.last.rep[k]) != server_of(x.last.leader) && x.last.rep[k] != ids[B])
            C = server_of(x.last.rep[k]);
    if (C < 0)
        C = B;
    move_hold_set(1);
    move_op(W, C, A, 0, "proposed");
    struct mv_watch y = {.a = ids[C], .b = ids[A], .from = x.last.index}; /* A was a member before the first move */
    await_joined(W, &y, 60000);
    move_op(W, C, A, 1, "cancelling");
    move_hold_set(0);
    await_move(W, &y, 1, 60000, "the cancel");
    move_dir_gone(A);
    usleep(3000000);
    move_watch(W, &y);
    if (!mvt_has(y.last.isr, y.last.nisr, ids[C]) || y.last.nisr != 3)
        die("movekill: after the cancel the ISR of plant has %" PRIu32 " members and %s node %" PRIu32, y.last.nisr,
            mvt_has(y.last.isr, y.last.nisr, ids[C]) ? "holds" : "lacks", ids[C]);
    move_writers_stop(&r);
    stop_all();
    move_rows(&y.last, &r, "after the move and the cancel");
    printf("  a move from %d to %d cancelled after the join: the learner went, the ISR of 3 holds %d\n", C, A, C);
}

/* movecancel (review F4): the cancel of a move whose DROP_MEMBER(A) the volume leader holds (X joined, then lagged out:
 * the ISR without A is below the size before X joined), with the cancel's DROP_MEMBER(0) lost (TSDB_CMOVE_TEST
 * cancel_lose_leave=1: the frame is never resent once the REMOVE of X applied). The volume leader must stop A
 * `leaving` from the record alone (rset.c: a set with no member moving in): a member left `leaving` is never asked
 * back into the ISR, so A, paused until it lags out and resumed, must be back in the ISR. Mutant setkeepleave (the
 * record's reset off) fails it there. */
static void scen_movecancel(void)
{
    scenario("movecancel");
    move_extra = ",cancel_lose_leave=1";
    move_env(1);
    struct meta_volume v;
    int L = set_setup(4, &v, 0);
    set_cenv = NULL;
    struct mv_servers s;
    move_servers(&v, L, &s);
    int B = s.X;
    if (s.R == B) { /* X lags out by a pause below: it must not take the Raft leader (and the move's duty) with it */
        pause_server(B, 1);
        uint64_t t0 = now_ms();
        while ((s.R = leader_of(L)) == B || s.R < 0)
            if (now_ms() - t0 > 30000)
                die("movecancel: no Raft leader but server %d 30 s after it was paused", B);
            else
                usleep(100000);
        pause_server(B, 0);
        if (s.O[0] == s.R) {
            int k = s.O[0];
            s.O[0] = s.O[1], s.O[1] = k;
        }
    }
    int A = s.O[0], C = s.O[1];
    await_isr(0, "plant", 3, 10000, "every replica up");
    struct mv_run r;
    move_writers(&r, L, L, 1);
    move_hold_set(1);
    move_op(s.R, A, B, 0, "proposed");
    struct mv_watch x = {.a = ids[A], .b = ids[B]};
    await_joined(L, &x, 60000);
    pause_server(B, 1);
    await_isr(L, "plant", 3, 20000, "X lagged out of the ISR after it joined");
    move_hold_set(0);
    char needle[128];
    snprintf(needle, sizeof needle, "volume 1: node %" PRIu32 " (replica ", ids[A]);
    await_log(L, needle, 20000, "movecancel: the volume leader did not take the move's DROP_MEMBER of A");
    usleep(2000000); /* held: the ISR without A has 2 members, it had 3 before X joined */
    if (isr_of(L, "plant", NULL) != 3)
        die("movecancel: A left the ISR with X away");
    move_op(s.R, A, B, 1, "cancelling");
    await_move(L, &x, 1, 60000, "the cancel");
    pause_server(B, 0);
    pause_server(A, 1);
    await_isr(L, "plant", 2, 20000, "A lagged out of the ISR after the cancel");
    pause_server(A, 0);
    await_isr(L, "plant", 3, 30000,
              "A back in the ISR after the cancel whose DROP_MEMBER(0) was lost (a member left leaving is never asked "
              "back)");
    if (log_count(L, "has no move: replica ") < 1)
        die("movecancel: the volume leader did not log that the record has no move");
    move_writers_stop(&r);
    stop_all();
    move_watch(L, &x);
    move_rows(&x.last, &r, "after the cancel");
    printf("  a move from %d to %d cancelled with its DROP_MEMBER(0) lost: server %d (%d stayed) left leaving no more, "
           "rejoined the ISR after a lag\n", A, B, A, C);
}

/* moveold: the leader no longer keeps position 1 (its first segments are gone): X fills by a snapshot
 * (r4-xferinst), joins, and the move ends */
static void scen_moveold(void)
{
    scenario("moveold");
    move_env(0);
    struct meta_volume v;
    int L = set_setup(4, &v, 0);
    set_cenv = NULL;
    struct mv_servers s;
    move_servers(&v, L, &s);
    int A = s.O[1], B = s.X, W = s.O[0];
    await_isr(0, "plant", 3, 10000, "every replica up");
    struct mv_run r;
    move_writers(&r, L, L, 0);
    uint64_t t0 = now_ms(), s1 = segment_bound(L, 0);
    while (segment_bound(L, 1) <= s1)
        if (now_ms() - t0 > 60000)
            die("moveold: the leader still keeps a WAL segment at or below %" PRIu64 " after 60 s", s1);
        else
            usleep(100000);
    move_op(s.R, A, B, 0, "proposed");
    struct mv_watch x = {.a = ids[A], .b = ids[B]};
    await_move(W, &x, 0, 120000, "moveold");
    if (!log_count(B, "snapshot installed: P"))
        die("moveold: server %d joined without installing a snapshot", B);
    move_dir_gone(A);
    move_writers_stop(&r);
    stop_all();
    move_watch(W, &x);
    move_rows(&x.last, &r, "after the move by a snapshot");
    printf("  plant moved from server %d to server %d by a snapshot (the leader's log starts past segment %" PRIu64 ")\n",
           A, B, s1);
}

/* Reads one integer Prometheus metric line starting with `prefix` from `buf` (-1 if missing). */
static long long rdma_metric_val(const char *buf, const char *prefix)
{
    size_t pl = strlen(prefix);
    for (const char *p = buf; p && *p; ) {
        if (!strncmp(p, prefix, pl))
            return strtoll(p + pl, NULL, 10);
        p = strchr(p, '\n');
        if (p)
            p++;
    }
    return -1;
}

/* rdma (docs/design-rdma.md §8, track rd-rxe): 3-node cluster over real verbs (InfiniBand HCA or Soft-RoCE rxe*) with
 * --peer-rdma on, --peer-rdma-pool-mb 1, and TSDB_PLRDMA_TEST=rnr_retry=0 so any credit bug fails the QP loudly.
 * Writes and replicates small (LOG) and large (BULK) batches, runs forwarded writes (FWD) and forwarded reads (FWDQ),
 * and checks client STATUS, `tsdb cluster status`, and /metrics confirm rdma > 0, tcp == 0, fallbacks == 0,
 * rnr_retries == 0, and qp_errors == 0. Skips cleanly (exit 0) when built with NO_RDMA=1 or no active verbs device is
 * present, unless TSDB_RDMA_REQUIRED=1 is set (which fails instead of skipping). */
static void scen_rdma(void)
{
    scenario("rdma");
    struct rdma_dev_info di;
    char reason[256];
    if (!rdma_dev_discover(&di, reason, sizeof reason)) {
        if (rdma_dev_required())
            die("TSDB_RDMA_REQUIRED=1 but no RDMA verbs device is usable (%s)", reason);
        printf("  rdma: skipped (%s)\n", reason);
        return;
    }
    printf("  rdma: using %s (%s)\n", di.spec[0] ? di.spec : "auto-ib",
           di.link_layer == PLR_LL_IB ? "InfiniBand" : "Ethernet/RoCE");
    strict_reads = 1;
    fwd_on = 1;
    static char xa[256];
    if (di.spec[0])
        snprintf(xa, sizeof xa, "--peer-rdma on --peer-rdma-pool-mb 1 --peer-rdma-device %s --metrics-port auto --workers 2",
                 di.spec);
    else
        snprintf(xa, sizeof xa, "--peer-rdma on --peer-rdma-pool-mb 1 --metrics-port auto --workers 2");
    int mports[3] = {0};
    for (int i = 0; i < 3; i++) {
        xargs[i] = xa;
        penv[i] = "TSDB_PLRDMA_TEST=rnr_retry=0";
        start(i);
        mports[i] = th_mport;
        if (mports[i] <= 0)
            die("server %d: no metrics port reported", i);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    await_isr(0, "plant", 3, WAIT_MS, "plant with 3 replicas in ISR");
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader), R = (L + 1) % 3;
    if (L < 0 || L > 2)
        die("leader of plant is node %" PRIu32, v.leader);

    /* Write small batches (LOG) and one large batch straight to parts (BULK) on leader L. */
    tsdbc *cl = client(L);
    tsdb_sid s_log = rep_series(cl, "rdma.log", "plant", 30000);
    tsdb_sid s_bulk = rep_series(cl, "rdma.bulk", "plant", 30000);
    for (int j = 0; j < 100; j++) {
        int64_t ts = 1000 + 1000LL * j;
        float val = (float)j;
        if ((rc = tsdbc_insert_series(cl, s_log, &ts, &val, 1)) != 0)
            die("small insert %d: %s", j, ers(rc));
    }
    enum { BIG = 70000 };
    int64_t *bts = malloc(BIG * sizeof *bts);
    float *bval = malloc(BIG * sizeof *bval);
    if (!bts || !bval)
        die("out of memory");
    for (int j = 0; j < BIG; j++)
        bts[j] = 1000 + 1000LL * j, bval[j] = (float)(j % 977);
    if ((rc = tsdbc_insert_series(cl, s_bulk, bts, bval, BIG)) != 0)
        die("large insert: %s", ers(rc));
    free(bts);
    free(bval);

    /* Forwarded writes (FWD) and forwarded reads (FWDQ) through follower R to leader L. */
    tsdbc *cr = client(R);
    for (int j = 0; j < 50; j++) {
        int64_t ts = 1000 + 1000LL * (100 + j);
        float val = (float)(100 + j);
        if ((rc = tsdbc_insert_series(cr, s_log, &ts, &val, 1)) != 0)
            die("forwarded insert %d via server %d: %s", j, R, ers(rc));
    }
    int r_log = rows_of(cr, s_log), r_bulk = rows_of(cr, s_bulk);
    int l_log = rows_of(cl, s_log), l_bulk = rows_of(cl, s_bulk);
    tsdbc_close(cr);
    tsdbc_close(cl);
    if (r_log != 150 || l_log != 150 || r_bulk != BIG || l_bulk != BIG)
        die("row counts mismatch: leader (%d, %d) vs forwarded (%d, %d), want (150, %d)", l_log, l_bulk, r_log, r_bulk,
            BIG);

    /* Verify STATUS on all 3 nodes: rdma > 0 and tcp == 0 for log, bulk, fwd, fwdq. */
    static const char *const kinds[] = {"log", "bulk", "fwd", "fwdq"};
    for (int i = 0; i < 3; i++) {
        for (int k = 0; k < 4; k++) {
            char kr[64], kt[64], vr[32], vt[32];
            snprintf(kr, sizeof kr, "links.%s.rdma", kinds[k]);
            snprintf(kt, sizeof kt, "links.%s.tcp", kinds[k]);
            int nr = -1, nt = -1;
            for (uint64_t t0 = now_ms();; usleep(50000)) {
                nr = status_key(i, kr, vr, sizeof vr) ? atoi(vr) : -1;
                nt = status_key(i, kt, vt, sizeof vt) ? atoi(vt) : -1;
                if (nr >= 2 && nt == 0)
                    break;
                if (now_ms() - t0 > WAIT_MS)
                    die("server %d: STATUS says %s=%d %s=%d, want rdma >= 2 and tcp == 0", i, kr, nr, kt, nt);
            }
        }
#ifdef TSDB_TEST_HOOKS
        if (!log_has(i, "rnr_retry=0"))
            die("server %d: log does not confirm TSDB_PLRDMA_TEST rnr_retry=0", i);
#endif
    }

    /* Verify `tsdb cluster status` CLI reports rdma links > 0 and tcp 0. */
    char pL[META_ADDR_MAX], args[PATH_MAX + 256], out[16384];
    peer_of(L, pL, sizeof pL);
    snprintf(args, sizeof args, "cluster status %s --secret-file %s", pL, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("tsdb cluster status failed: %s", out);
    for (int k = 0; k < 4; k++) {
        char head[64];
        snprintf(head, sizeof head, "peer links %s:", kinds[k]);
        const char *ln = strstr(out, head);
        if (!ln)
            die("tsdb cluster status missing '%s':\n%s", head, out);
        const char *eol = strchr(ln, '\n');
        size_t ll = eol ? (size_t)(eol - ln) : strlen(ln);
        char line[256];
        snprintf(line, sizeof line, "%.*s", (int)(ll < sizeof line - 1 ? ll : sizeof line - 1), ln);
        const char *tp = strstr(line, " tcp "), *rp = strstr(line, " rdma ");
        if (!tp || !rp || atoi(tp + 5) != 0 || atoi(rp + 6) < 2)
            die("tsdb cluster status unexpected line '%s' (want tcp 0 and rdma >= 2)", line);
    }

    /* Verify /metrics on all 3 nodes: rdma > 0, tcp == 0, fallbacks == 0, rnr_retries == 0, qp_errors == 0. */
    static char mbuf[1 << 20];
    for (int i = 0; i < 3; i++) {
        metrics_get(mports[i], mbuf, sizeof mbuf);
        for (int k = 0; k < 4; k++) {
            char mrdma[128], mtcp[128];
            snprintf(mrdma, sizeof mrdma, "tsdb_peer_links_transport{kind=\"%s\",transport=\"rdma\"} ", kinds[k]);
            snprintf(mtcp, sizeof mtcp, "tsdb_peer_links_transport{kind=\"%s\",transport=\"tcp\"} ", kinds[k]);
            long long vr = rdma_metric_val(mbuf, mrdma), vt = rdma_metric_val(mbuf, mtcp);
            if (vr < 2 || vt != 0)
                die("server %d /metrics: %s%lld, %s%lld (want rdma >= 2, tcp == 0)", i, mrdma, vr, mtcp, vt);
        }
        /* Every fallback reason counter must be 0. */
        int fb_seen = 0;
        for (const char *p = mbuf; p && *p; ) {
            const char *eol = strchr(p, '\n');
            static const char fbp[] = "tsdb_peer_rdma_fallbacks_total{";
            if (!strncmp(p, fbp, sizeof fbp - 1)) {
                fb_seen++;
                const char *sp = memchr(p, ' ', eol ? (size_t)(eol - p) : strlen(p));
                if (!sp || strtoll(sp + 1, NULL, 10) != 0)
                    die("server %d /metrics: non-zero RDMA fallback: %.120s", i, p);
            }
            p = eol ? eol + 1 : NULL;
        }
        if (fb_seen == 0)
            die("server %d /metrics: missing tsdb_peer_rdma_fallbacks_total", i);
        long long rnr = rdma_metric_val(mbuf, "tsdb_peer_rdma_rnr_retries_total ");
        long long qpe = rdma_metric_val(mbuf, "tsdb_peer_rdma_qp_errors_total ");
        if (rnr != 0 || qpe != 0)
            die("server %d /metrics: rnr_retries=%lld qp_errors=%lld (want 0, 0)", i, rnr, qpe);
    }

    stop_all();
    printf("  rdma: 3 nodes on %s, replicated + forwarded %d rows; STATUS, CLI and /metrics confirm rdma >= 2, tcp 0, "
           "fallbacks 0, rnr_retries 0, qp_errors 0\n",
           di.spec[0] ? di.spec : "auto-ib", 150 + BIG);
}

#if defined(__SANITIZE_ADDRESS__) || defined(__SANITIZE_THREAD__)
#define OPENFAST_SAN 1
#elif defined(__has_feature)
#if __has_feature(address_sanitizer) || __has_feature(thread_sanitizer)
#define OPENFAST_SAN 1
#else
#define OPENFAST_SAN 0
#endif
#else
#define OPENFAST_SAN 0
#endif

/* openfast: a restarted replica reports its new open_gen promptly (cluster_beat_soon in cvol.c:prepare) instead of
 * waiting a full heartbeat_ms, and the Raft leader proposes REPLICA_OPEN for newly reported replicas on the next duty
 * tick instead of blocking behind a global 1 s opens_ns throttle from an earlier proposal. */
static void scen_openfast(void)
{
    scenario("openfast");
    for (int i = 0; i < 3; i++)
        start(i);
    init_heartbeat_ms = 5000;
    init_node_timeout_ms = 25000;
    init_cluster(0, 600);
    init_heartbeat_ms = 0;
    init_node_timeout_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc = vol_add(0, "fast", 3, &num);
    if (rc != 0 || num != 1)
        die("volume add fast: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "fast", i, 1, 0);
    /* Part 1: kill only follower 1 so Raft quorum stays intact (no election interference) and check that prepare()
     * wakes heartbeat immediately instead of waiting heartbeat_ms (5000 ms). */
    stop(1, SIGKILL);
    struct timespec w20 = {0, 20000000};
    start(1);
    await_log_count(1, "open generation 2, waiting", 1, 15000);
    uint64_t t1 = now_ms();
    for (;;) {
        struct meta_volume v;
        const struct meta_replica *r;
        if (vol_rec(0, "fast", &v) && (r = rep_of(&v, 1)) && r->open_gen >= 2)
            break;
        if (now_ms() - t1 > 15000)
            die("node 1 never recorded open_gen 2 within 15 s");
        nanosleep(&w20, NULL);
    }
    uint64_t dt1 = now_ms() - t1;
    uint64_t cap1 = OPENFAST_SAN ? 3000 : 2000;
    if (dt1 > cap1)
        die("node 1 open_gen 2 took %" PRIu64 " ms (> %" PRIu64
            " ms with heartbeat_ms=5000): prepare() did not wake heartbeat",
            dt1, cap1);
    /* Part 2: with all 3 nodes up (quorum intact, no process restart latency), create 6 sequential 3-replica volumes,
     * waiting for every replica to record open_gen 1 before creating the next. Under the old global 1 s opens_ns gate
     * in propose_opens(), each volume after the first waits at least 1000 ms (strict lower bound >= 5000 ms total). */
    uint64_t t2 = now_ms();
    for (int k = 1; k <= 6; k++) {
        char vn[16];
        snprintf(vn, sizeof vn, "fast%d", k);
        uint32_t vnum = 0;
        rc = vol_add(0, vn, 3, &vnum);
        if (rc != 0)
            die("volume add %s: %s", vn, cluster_strerror(rc));
        for (;;) {
            struct meta_volume v;
            int all_open = 1;
            if (vol_rec(0, vn, &v)) {
                for (int i = 0; i < 3; i++) {
                    const struct meta_replica *r = rep_of(&v, i);
                    if (!r || r->open_gen < 1)
                        all_open = 0;
                }
            } else {
                all_open = 0;
            }
            if (all_open)
                break;
            if (now_ms() - t2 > 30000)
                die("%s never recorded open_gen 1 on all 3 replicas within 30 s", vn);
            nanosleep(&w20, NULL);
        }
    }
    uint64_t dt2 = now_ms() - t2;
    uint64_t cap2 = OPENFAST_SAN ? 4500 : 3500;
    if (dt2 > cap2)
        die("6 sequential volumes took %" PRIu64 " ms (> %" PRIu64
            " ms): propose_opens() global throttle?",
            dt2, cap2);
    stop_all();
    printf("  openfast: restarted follower recorded open_gen 2 in %" PRIu64 " ms (heartbeat_ms=5000); 6 sequential "
           "volumes opened all 3 replicas in %" PRIu64 " ms\n",
           dt1, dt2);
}

/* ---- r9-out: DOWN -> OUT timers, holds, opening hold, mass-OUT guard, failstop fast path, replica faults */

static void pout_touch(int i, const char *name, const char *body)
{
    char dir[PATH_MAX + 80], p[PATH_MAX + 128];
    server_dir(i, dir, sizeof dir);
    snprintf(p, sizeof p, "%s/state/%s", dir, name);
    FILE *f = fopen(p, "w");
    if (!f)
        die("fopen %s: %s", p, strerror(errno));
    if (body)
        fputs(body, f);
    fclose(f);
}

static void pout_unlink(int i, const char *name)
{
    char dir[PATH_MAX + 80], p[PATH_MAX + 128];
    server_dir(i, dir, sizeof dir);
    snprintf(p, sizeof p, "%s/state/%s", dir, name);
    (void)unlink(p);
}

static int member_state_of(int via, uint32_t id, uint8_t *reason, uint64_t *hold_until)
{
    struct view v;
    view(via, &v);
    const struct meta_member *m = meta_member(&v.m, id);
    int st = m ? (int)m->state : -1;
    if (reason)
        *reason = m ? m->down_reason : 0;
    if (hold_until)
        *hold_until = m ? m->hold_until_ms : 0;
    view_free(&v);
    return st;
}

static void pout_boot5(void)
{
    for (int i = 0; i < 5; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 5; i++)
        node_add(0, i);
    unsigned five = 5;
    await_view(0, p_voters, &five, "five voters up");
}

/* outtimer: 5 nodes, rebuild_after_s=6, guard 25%. Stopping 1 node marks it DOWN, keeps it DOWN before 6 s, and
 * transitions it to OUT at ~6 s; also exercises crash point `out-proposed` on the Raft leader after OUT commits. */
static void scen_outtimer(void)
{
    scenario("outtimer");
    init_rebuild_after_s = 6;
    init_out_guard_pct = 25;
    init_out_guard_hold_s = 15;
    penv[0] = "TSDB_CRASH_AT=out-proposed";
    pout_boot5();

    stop(4, SIGKILL);
    struct state_want down = {ids[4], META_DOWN, 0};
    await_view(1, p_member_state, &down, "node 5 marked DOWN");
    uint64_t t_down = now_ms();

    /* Stay DOWN well before 6 s (at ~4 s), and crash point must not have fired yet. */
    while (now_ms() - t_down < 4000)
        usleep(100000);
    if (member_state_of(1, ids[4], NULL, NULL) != META_DOWN)
        die("outtimer: node 5 left META_DOWN too early (at %" PRIu64 " ms)", now_ms() - t_down);
    if (await_exit(0, 10) != -1)
        die("outtimer: leader exited before rebuild_after_s");

    /* At ~6 s OUT commits and fires CP_OUT_PROPOSED (status 99) on leader 0. */
    int ex = await_exit(0, 12000);
    uint64_t dt = now_ms() - t_down;
    if (ex != CRASH_EXIT_STATUS || !log_has(0, "crash point out-proposed"))
        die("outtimer: expected leader 0 to hit out-proposed (exit 99), got exit %d", ex);
    if (dt < 5000)
        die("outtimer: OUT committed too early (%" PRIu64 " ms < 5000 ms)", dt);

    struct state_want out = {ids[4], META_OUT, 0};
    await_view(1, p_member_state, &out, "node 5 recorded META_OUT on surviving quorum");

    /* Restart leader 0 without the crash point and verify it recovers with node 5 still OUT. */
    penv[0] = NULL;
    start(0);
    await_view(0, p_member_state, &out, "restarted server 0 sees node 5 META_OUT");
    printf("  outtimer: node 5 OUT after %" PRIu64 " ms, leader hit out-proposed (exit 99) and recovered\n", dt);
}

/* outback: an OUT member that returns under a new incarnation transitions back to UP (D2). */
static void scen_outback(void)
{
    scenario("outback");
    init_rebuild_after_s = 4;
    init_out_guard_pct = 25;
    pout_boot5();

    stop(4, SIGKILL);
    struct state_want out = {ids[4], META_OUT, 0};
    await_view(0, p_member_state, &out, "node 5 marked OUT");

    start(4);
    struct state_want back = {ids[4], META_UP, 2};
    await_view(0, p_member_state, &back, "returning OUT node 5 back to UP with incarnation >= 2");
    check_all_agree(0, 5);
    printf("  outback: node 5 transitioned OUT -> UP on restart\n");
}

/* outguard: 2 of 5 DOWN (> 25% guard), rebuild_after_s=4, out_guard_hold_s=12. No OUT before 12 s; both OUT after
 * with "guard bound passed" logged. */
static void scen_outguard(void)
{
    scenario("outguard");
    init_rebuild_after_s = 4;
    init_out_guard_pct = 25;
    init_out_guard_hold_s = 12;
    pout_boot5();

    stop(3, SIGKILL);
    stop(4, SIGKILL);
    struct state_want d3 = {ids[3], META_DOWN, 0}, d4 = {ids[4], META_DOWN, 0};
    await_view(0, p_member_state, &d3, "node 4 marked DOWN");
    await_view(0, p_member_state, &d4, "node 5 marked DOWN");
    uint64_t t_down = now_ms();

    /* Past rebuild_after_s (4 s), still well before out_guard_hold_s (12 s): neither may be OUT. */
    while (now_ms() - t_down < 8000)
        usleep(100000);
    if (member_state_of(0, ids[3], NULL, NULL) != META_DOWN || member_state_of(0, ids[4], NULL, NULL) != META_DOWN)
        die("outguard: node went OUT while mass-OUT guard should hold (at %" PRIu64 " ms)", now_ms() - t_down);

    struct state_want o3 = {ids[3], META_OUT, 0}, o4 = {ids[4], META_OUT, 0};
    await_view(0, p_member_state, &o3, "node 4 OUT after guard bound passed");
    await_view(0, p_member_state, &o4, "node 5 OUT after guard bound passed");
    uint64_t dt = now_ms() - t_down;
    if (dt < 10500)
        die("outguard: OUT happened too early (%" PRIu64 " ms < 10500 ms)", dt);
    if (!log_has(0, "guard bound passed"))
        die("outguard: leader log missing 'guard bound passed'");
    printf("  outguard: held 2/5 DOWN past rebuild_after, OUT at %" PRIu64 " ms with guard bound passed\n", dt);
}

/* outhold: a 2-day hold is refused by meta apply (D3); a valid 14 s hold keeps a DOWN node from going OUT past
 * rebuild_after_s=4 until the hold expires. */
static void scen_outhold(void)
{
    scenario("outhold");
    init_rebuild_after_s = 4;
    init_out_guard_pct = 25;
    envs[0] = "node_hold_file=1";
    pout_boot5();

    /* 2 days (172800 s > META_HOLD_MAX_MS 86400 s) must be refused, leaving hold_until_ms == 0. Wait until the
     * Raft applied index actually advances past the proposal so we prove meta_apply ran and refused it. */
    uint64_t applied0 = 0;
    {
        struct view v;
        view(0, &v);
        applied0 = v.m.applied;
        view_free(&v);
    }
    pout_touch(0, "nodehold", "5 172800\n");
    await_log(0, "nodehold node 5 for 172800 s: proposed", 5000, "2-day nodehold proposed");
    uint64_t t_ref = now_ms();
    for (;;) {
        struct view v;
        view(0, &v);
        uint64_t ap = v.m.applied;
        view_free(&v);
        if (ap > applied0)
            break;
        if (now_ms() - t_ref > 5000)
            die("outhold: 2-day NODE_HOLD entry never committed/applied");
        usleep(50000);
    }
    uint64_t hold = 0;
    (void)member_state_of(0, ids[4], NULL, &hold);
    if (hold != 0)
        die("outhold: 2-day hold was applied (hold_until_ms=%" PRIu64 ")", hold);

    /* Apply a valid 14 s hold on node 5. */
    pout_touch(0, "nodehold", "5 14\n");
    uint64_t t_hold = now_ms();
    for (;;) {
        (void)member_state_of(0, ids[4], NULL, &hold);
        if (hold != 0)
            break;
        if (now_ms() - t_hold > 5000)
            die("outhold: 14 s hold never applied");
        usleep(100000);
    }

    stop(4, SIGKILL);
    struct state_want down = {ids[4], META_DOWN, 0};
    await_view(0, p_member_state, &down, "held node 5 marked DOWN");

    /* Well past rebuild_after_s (4 s), still well inside the 14 s hold: must remain META_DOWN. */
    while (now_ms() - t_hold < 9500)
        usleep(100000);
    if (member_state_of(0, ids[4], NULL, NULL) != META_DOWN)
        die("outhold: held node 5 went OUT early at %" PRIu64 " ms", now_ms() - t_hold);

    /* After the 14 s hold expires, node 5 goes OUT. */
    struct state_want out = {ids[4], META_OUT, 0};
    await_view(0, p_member_state, &out, "node 5 OUT after hold expired");
    uint64_t dt = now_ms() - t_hold;
    if (dt < 12500)
        die("outhold: node 5 went OUT before hold expired (%" PRIu64 " ms)", dt);
    printf("  outhold: 2-day hold refused; 14 s hold kept node 5 DOWN until %" PRIu64 " ms\n", dt);
}

/* outopening: a DOWN server restarted while reporting opening=1 gets its new incarnation recorded immediately (so
 * vol_watch_duty does not deadlock), stays META_DOWN held past rebuild_after_s=4 up to opening_hold_s=8 (~12 s total),
 * goes OUT once the opening bound passes, and returns UP on a fresh restart once opening clears. */
static void scen_outopening(void)
{
    scenario("outopening");
    init_rebuild_after_s = 4;
    init_opening_hold_s = 8;
    init_out_guard_pct = 25;
    envs[4] = "hb_opening_file=1";
    pout_boot5();

    stop(4, SIGKILL);
    struct state_want down = {ids[4], META_DOWN, 0};
    await_view(0, p_member_state, &down, "node 5 marked DOWN before opening restart");
    uint64_t t_down = now_ms();

    /* Restart server 4 stuck in opening=1: incarnation must advance to 2 immediately while state remains META_DOWN
     * (proving vol_watch_duty is unblocked and opening does not deadlock volume opens). */
    pout_touch(4, "hbopening", "1\n");
    start(4);
    struct state_want down2 = {ids[4], META_DOWN, 2};
    await_view(0, p_member_state, &down2, "opening node 5 recorded incarnation 2 while staying META_DOWN");

    /* Past rebuild_after_s (4 s), still inside 4 + 8 = 12 s: must stay META_DOWN (neither UP nor OUT). */
    while (now_ms() - t_down < 8000)
        usleep(100000);
    int st = member_state_of(0, ids[4], NULL, NULL);
    if (st != META_DOWN)
        die("outopening: node 5 state %d (expected META_DOWN) at %" PRIu64 " ms while opening", st, now_ms() - t_down);

    /* Past 4 + 8 = 12 s: opening hold bound expires and node 5 goes OUT despite opening=1. */
    struct state_want out = {ids[4], META_OUT, 2};
    await_view(0, p_member_state, &out, "node 5 OUT after opening_hold_s bound passed");
    uint64_t dt = now_ms() - t_down;
    if (dt < 10500)
        die("outopening: node 5 went OUT too early (%" PRIu64 " ms < 10500 ms)", dt);

    /* Clearing opening and restarting (incarnation 3) brings node 5 back to META_UP. */
    pout_unlink(4, "hbopening");
    stop(4, SIGTERM);
    start(4);
    struct state_want back = {ids[4], META_UP, 3};
    await_view(0, p_member_state, &back, "node 5 UP on restart after opening cleared");
    printf("  outopening: recorded inc 2 while DOWN+opening, held past 4 s, OUT at %" PRIu64 " ms, UP on restart\n", dt);
}

/* outfailstop: a fail-stop last-gasp heartbeat respects promote_safe_ns (no premature DOWN or volume promotion while
 * the old leader's read lease is still valid), then marks the server DOWN(failstop) and transitions it to OUT in
 * failstop_out_s=2 instead of rebuild_after_s=12. */
static void scen_outfailstop(void)
{
    scenario("outfailstop");
    init_rebuild_after_s = 12;
    init_failstop_out_s = 2;
    init_out_guard_pct = 25;
    for (int i = 0; i < 5; i++)
        envs[i] = "hb_failstop_file=1";
    pout_boot5();

    uint32_t vnum = 0;
    int rc = vol_add(0, "fsvol", 3, &vnum);
    if (rc != 0 || vnum != 1)
        die("outfailstop: volume add fsvol failed: %s", cluster_strerror(rc));
    await_isr(0, "fsvol", 3, 20000, "fsvol 3-replica ISR before failstop");

    struct meta_volume v;
    if (!vol_rec(0, "fsvol", &v))
        die("outfailstop: missing fsvol record");
    /* Ensure the fail-stopping volume leader is NOT the Raft leader (server 0) so Raft quorum stays smooth. */
    int target = -1;
    for (uint32_t k = 0; k < v.nrep; k++) {
        int s = server_of(v.rep[k].node);
        if (s > 0) {
            target = s;
            break;
        }
    }
    if (target < 0)
        die("outfailstop: no non-zero replica for fsvol");
    if (v.leader != ids[target]) {
        uint8_t tbody[8], *treply = NULL;
        size_t trlen = 0, tblen = cluster_volume_force_encode(vnum, ids[target], tbody);
        rc = admin(0, CLUSTER_OP_VOLUME_TRANSFER, tbody, tblen, 1, &treply, &trlen);
        free(treply);
        if (rc != 0)
            die("outfailstop: transfer fsvol to server %d: %s", target, cluster_strerror(rc));
        uint64_t tw = now_ms();
        while (!vol_rec(0, "fsvol", &v) || v.leader != ids[target]) {
            if (now_ms() - tw > 15000)
                die("outfailstop: fsvol did not transfer to server %d", target);
            usleep(50000);
        }
    }
    uint64_t ep0 = v.epoch;
    /* Let at least one heartbeat cycle grant target a fresh read lease (lease_ms = 2000). */
    usleep(400000);

    pout_touch(target, "hbfailstop", "1\n");
    uint64_t t_fs = now_ms();
    /* Lease safety: before lease_ms (~2000 ms) runs out, fsvol must NOT promote (even though DOWN/failstop records
     * within one beat via r9-hb, promo_step holds promotion until promote_safe_ns expires). */
    while (now_ms() - t_fs < 1200) {
        if (vol_rec(0, "fsvol", &v) && v.epoch != ep0)
            die("outfailstop: fsvol promoted from epoch %" PRIu64 " to %" PRIu64 " before lease expired (at %" PRIu64
                " ms)",
                ep0, v.epoch, now_ms() - t_fs);
        usleep(50000);
    }

    for (;;) {
        uint8_t reason = 0;
        if (member_state_of(0, ids[target], &reason, NULL) == META_DOWN && reason == META_DOWN_FAILSTOP)
            break;
        if (now_ms() - t_fs > 8000)
            die("outfailstop: node %" PRIu32 " was not marked DOWN(failstop) within 8 s", ids[target]);
        usleep(50000);
    }
    uint64_t t_down = now_ms();
    /* Server exits after its last-gasp beat. */
    stop(target, SIGKILL);

    struct state_want out = {ids[target], META_OUT, 0};
    await_view(0, p_member_state, &out, "fail-stopped node marked OUT");
    uint64_t dt = now_ms() - t_down;
    if (dt > 7000)
        die("outfailstop: OUT took %" PRIu64 " ms (expected ~2 s, well below rebuild_after_s=12 s)", dt);
    printf("  outfailstop: lease held >=1200 ms, DOWN(failstop) at %" PRIu64 " ms, OUT in %" PRIu64
           " ms (rebuild_after_s=12 s)\n",
           t_down - t_fs, dt);
}

/* replfault: an UP member reporting LOCAL_FAULT on volume 1 continuously for failstop_out_s=2 triggers a
 * PLACE_PROP_REPLICA_ADD replace-replica request while keeping the server UP (D6). */
static void scen_replfault(void)
{
    scenario("replfault");
    init_rebuild_after_s = 60;
    init_failstop_out_s = 2;
    init_out_guard_pct = 25;
    /* Server 2 (member id 3) reports CL_HEALTH_LOCAL_FAULT (1) on volume 1. Add 3 nodes first so rfault is placed on
     * {1, 2, 3}, then add node 4 as the healthy replacement target so pout_plan -> place_plan -> cmove replaces node 3
     * while server 2 remains META_UP. */
    envs[2] = "vol=1/2/1/1/fault";
    for (int i = 0; i < 4; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned three = 3;
    await_view(0, p_voters, &three, "three voters up");

    uint32_t vnum = 0;
    int rc = vol_add(0, "rfault", 3, &vnum);
    if (rc != 0 || vnum != 1)
        die("replfault: volume add failed: %s (vnum=%" PRIu32 ")", cluster_strerror(rc), vnum);
    await_isr(0, "rfault", 3, 20000, "rfault 3-replica ISR before adding spare");
    node_add(0, 3);
    struct state_want w4 = {ids[3], META_UP, 1};
    await_view(0, p_member_state, &w4, "spare node 4 up");

    uint64_t t0 = now_ms();
    for (;;) {
        struct meta_volume v;
        if (vol_rec(0, "rfault", &v) && v.nrep == 3 && v.nisr == 3) {
            int has3 = 0, has4 = 0;
            for (uint32_t k = 0; k < v.nrep; k++) {
                if (v.rep[k].node == ids[2])
                    has3 = 1;
                if (v.rep[k].node == ids[3])
                    has4 = 1;
            }
            if (!has3 && has4)
                break;
        }
        if (now_ms() - t0 > 30000)
            die("replfault: faulted replica on node %" PRIu32 " was not replaced by node %" PRIu32 " within 30 s",
                ids[2], ids[3]);
        usleep(100000);
    }
    if (member_state_of(0, ids[2], NULL, NULL) != META_UP)
        die("replfault: server 2 should remain META_UP on a per-replica fault");
    printf("  replfault: continuous LOCAL_FAULT on vol 1 node 3 auto-replaced onto node 4 while server stayed UP\n");
}

/* pace (R9 D18, E13, §8.4, r9-pace): margin-based rebuild pacing on both send and receive sides and Prometheus pace
 * metrics. Five nodes (5 voters, quorum 3) with rebuild_mb_s=2 and --metrics-port auto:
 *  1) pvol4 (4 replicas), 1 replica down (nisr=3 -> margin 2): snapshot runs at ~rebuild_mb_s (2 MiB/s), counted under
 *     tsdb_pace_bytes_total{dir="send"|"recv",class="margin2plus"} and tsdb_pace_rate_bytes_per_second.
 *  2) pvol4 with 2 replicas down (nisr=2 -> margin 1 on 4-replica group): snapshot accelerates to 4*rebuild_mb_s
 *     (8 MiB/s), counted under class="margin1".
 *  3) pvol3 (3 replicas), 2 replicas down (nisr=1 -> margin 0): snapshot runs unlimited, counted under class="margin0". */
static uint64_t pace_metric_u64(int mport, const char *key)
{
    static char mbuf[1 << 20];
    metrics_get(mport, mbuf, sizeof mbuf);
    const char *p = strstr(mbuf, key);
    if (!p)
        die("metrics on port %d missing '%s'", mport, key);
    return strtoull(p + strlen(key), NULL, 10);
}

static void scen_pace(void)
{
    scenario("pace");
    int mports[5] = {0};
    init_retain_s = 2;
    init_rebuild_mb_s = 2;
    for (int i = 0; i < 5; i++) {
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
    }
    init_cluster(0, 600);
    init_retain_s = 0;
    init_rebuild_mb_s = 0;
    for (int i = 1; i < 5; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters");

    uint32_t v4 = 0, v3 = 0;
    int rc = vol_add(0, "pvol4", 4, &v4);
    if (rc != 0)
        die("volume add pvol4: %s", cluster_strerror(rc));

    struct meta_volume mv4;
    if (!vol_rec(0, "pvol4", &mv4))
        die("missing pvol4 record");
    int L4 = server_of(mv4.leader), R4a = -1, R4b = -1;
    for (uint32_t k = 0; k < mv4.nrep; k++) {
        int srv = server_of(mv4.rep[k].node);
        await_open_gen(0, "pvol4", srv, 1, 0);
        if (srv != L4) {
            if (R4a < 0)
                R4a = srv;
            else if (R4b < 0)
                R4b = srv;
        }
    }

    /* Verify configured pace rate and halved=0 on leader L4 before any snapshot. */
    uint64_t r_send = pace_metric_u64(mports[L4], "\ntsdb_pace_rate_bytes_per_second{dir=\"send\"} ");
    uint64_t r_recv = pace_metric_u64(mports[L4], "\ntsdb_pace_rate_bytes_per_second{dir=\"recv\"} ");
    uint64_t halved = pace_metric_u64(mports[L4], "\ntsdb_pace_halved ");
    if (r_send != (2ull << 20) || r_recv != (2ull << 20) || halved != 0)
        die("initial pace metrics on L4: send=%" PRIu64 " recv=%" PRIu64 " halved=%" PRIu64, r_send, r_recv, halved);

    /* Populate pvol4 with ~3M rows (~10+ MiB snapshot); pvol3 is created only in Phase 3 so it cannot interfere
     * with pvol4's margin classes during Phases 1 and 2. */
    tsdbc *c4 = client(L4);
    tsdb_sid id4 = rep_series(c4, "pace.s4", "pvol4", 30000);
    int64_t t4 = 1000;
    snap_rows(c4, id4, &t4, 3000000);
    await_isr(L4, "pvol4", 4, 20000, "pvol4 all 4 in ISR");

    /* Phase 1: pvol4 margin 2 (1 replica stopped -> nisr=3 -> 2 MiB/s). */
    stop(R4a, SIGKILL);
    await_isr(L4, "pvol4", 3, 15000, "pvol4 R4a stopped");
    struct timespec s1 = {1, 0};
    for (int r = 0; r < 5; r++) {
        snap_rows(c4, id4, &t4, 100);
        if ((rc = tsdbc_flush(c4)) != 0)
            die("flush pvol4: %s", ers(rc));
        nanosleep(&s1, NULL);
    }
    snap_rows(c4, id4, &t4, 1);

    penv[R4a] = "TSDB_REPLD_TEST=snaphold";
    start(R4a);
    mports[R4a] = th_mport;
    await_log(R4a, "(snaphold)", 90000, "Phase 1 (margin 2) snapshot never arrived");
    size_t nf = 0;
    uint64_t bytes4 = snap_verify_held(R4a, v4, &nf);
    char line[4096];
    log_line(R4a, "snapshot received from node", line, sizeof line);
    const char *in = strstr(line, " bytes in ");
    double secs_m2 = in ? strtod(in + 10, NULL) : 0.0;
    double least_m2 = (double)bytes4 / (double)(2ull << 20);
    if (secs_m2 < least_m2 * 0.8)
        die("margin-2 snapshot (%" PRIu64 " bytes) finished in %.2f s at 2 MiB/s (want >= %.2f s)", bytes4, secs_m2,
            least_m2 * 0.8);
    uint64_t m2_send = pace_metric_u64(mports[L4], "\ntsdb_pace_bytes_total{dir=\"send\",class=\"margin2plus\"} ");
    uint64_t m2_recv = pace_metric_u64(mports[R4a], "\ntsdb_pace_bytes_total{dir=\"recv\",class=\"margin2plus\"} ");
    if (m2_send < bytes4 || m2_recv < bytes4)
        die("margin-2 pace bytes: send=%" PRIu64 " recv=%" PRIu64 " want >= %" PRIu64, m2_send, m2_recv, bytes4);

    /* Phase 2: pvol4 margin 1 (2 replicas stopped -> nisr=2 of 4 -> 4 * 2 = 8 MiB/s).
     * R4a never installed its held snapshot, so restarting R4a with R4b stopped immediately requests a new snapshot. */
    stop(R4a, SIGKILL);
    stop(R4b, SIGKILL);
    await_isr(L4, "pvol4", 2, 15000, "pvol4 R4a+R4b stopped (margin 1)");
    start(R4a);
    mports[R4a] = th_mport;
    await_log_count(R4a, "(snaphold)", 2, 90000);
    uint64_t bytes4_p2 = snap_verify_held(R4a, v4, &nf);
    log_line(R4a, "snapshot received from node", line, sizeof line);
    in = strstr(line, " bytes in ");
    double secs_m1 = in ? strtod(in + 10, NULL) : 0.0;
    uint64_t m1_send = pace_metric_u64(mports[L4], "\ntsdb_pace_bytes_total{dir=\"send\",class=\"margin1\"} ");
    uint64_t m1_recv = pace_metric_u64(mports[R4a], "\ntsdb_pace_bytes_total{dir=\"recv\",class=\"margin1\"} ");
    if (m1_send < bytes4_p2 || m1_recv < bytes4_p2)
        die("margin-1 pace bytes: send=%" PRIu64 " recv=%" PRIu64 " want >= %" PRIu64, m1_send, m1_recv, bytes4_p2);
    if (secs_m1 >= secs_m2 * 0.75)
        die("margin-1 snapshot (%.2f s) did not accelerate vs margin-2 (%.2f s)", secs_m1, secs_m2);

    /* Bring R4b back and close pvol4 client before creating pvol3 for Phase 3. */
    penv[R4a] = NULL;
    start(R4b);
    mports[R4b] = th_mport;
    tsdbc_close(c4);

    /* Phase 3: pvol3 (3 replicas), both non-leader replicas stopped -> nisr=1 -> margin 0 (unlimited). */
    rc = vol_add(L4, "pvol3", 3, &v3);
    if (rc != 0)
        die("volume add pvol3: %s", cluster_strerror(rc));
    struct meta_volume mv3;
    if (!vol_rec(L4, "pvol3", &mv3))
        die("missing pvol3 record");
    int L3 = server_of(mv3.leader), R3a = -1, R3b = -1;
    for (uint32_t k = 0; k < mv3.nrep; k++) {
        int srv = server_of(mv3.rep[k].node);
        await_open_gen(L4, "pvol3", srv, 1, 0);
        if (srv != L3) {
            if (R3a < 0)
                R3a = srv;
            else if (R3b < 0)
                R3b = srv;
        }
    }
    tsdbc *c3 = client(L3);
    tsdb_sid id3 = rep_series(c3, "pace.s3", "pvol3", 30000);
    int64_t t3 = 1000;
    snap_rows(c3, id3, &t3, 2000000);
    await_isr(L3, "pvol3", 3, 20000, "pvol3 all 3 in ISR");

    stop(R3a, SIGKILL);
    stop(R3b, SIGKILL);
    await_isr(L3, "pvol3", 1, 15000, "pvol3 R3a+R3b stopped (margin 0)");
    for (int r = 0; r < 5; r++) {
        snap_rows(c3, id3, &t3, 100);
        if ((rc = tsdbc_flush(c3)) != 0)
            die("flush pvol3: %s", ers(rc));
        nanosleep(&s1, NULL);
    }
    snap_rows(c3, id3, &t3, 1);

    penv[R3a] = "TSDB_REPLD_TEST=snaphold";
    start(R3a);
    mports[R3a] = th_mport;
    await_log(R3a, "(snaphold)", 60000, "Phase 3 (margin 0) snapshot never arrived");
    uint64_t bytes3 = snap_verify_held(R3a, v3, &nf);
    log_line(R3a, "snapshot received from node", line, sizeof line);
    in = strstr(line, " bytes in ");
    double secs_m0 = in ? strtod(in + 10, NULL) : 0.0;
    uint64_t m0_send = pace_metric_u64(mports[L3], "\ntsdb_pace_bytes_total{dir=\"send\",class=\"margin0\"} ");
    uint64_t m0_recv = pace_metric_u64(mports[R3a], "\ntsdb_pace_bytes_total{dir=\"recv\",class=\"margin0\"} ");
    if (m0_send < bytes3 || m0_recv < bytes3)
        die("margin-0 pace bytes: send=%" PRIu64 " recv=%" PRIu64 " want >= %" PRIu64, m0_send, m0_recv, bytes3);
    double cap_m0 = (double)bytes3 / (double)(2ull << 20);
    if (secs_m0 >= cap_m0 * 0.75)
        die("margin-0 snapshot (%" PRIu64 " bytes) took %.2f s (should beat 2 MiB/s cap %.2f s)", bytes3, secs_m0,
            cap_m0);

    tsdbc_close(c3);
    for (int i = 0; i < 5; i++) {
        xargs[i] = NULL;
        penv[i] = NULL;
    }
    stop_all();
    printf("  pace: margin-2 (%" PRIu64 " B) in %.2f s, margin-1 in %.2f s, margin-0 (%" PRIu64 " B) in %.2f s; "
           "send/recv pace metrics verified\n",
           bytes4, secs_m2, secs_m1, bytes3, secs_m0);
}

/* ---- R9 E29: WAL retention for DOWN and held members within repl_retain_down_gb (r9-retain) ---- */

static void await_member_state(int via, uint32_t nid, int state, int ms)
{
    uint64_t t0 = now_ms();
    for (;;) {
        struct view v;
        view(via, &v);
        const struct meta_member *m = meta_member(&v.m, nid);
        int ok = m && (int)m->state == state;
        int cur = m ? (int)m->state : -1;
        view_free(&v);
        if (ok)
            return;
        if (now_ms() - t0 > (uint64_t)ms)
            die("member %" PRIu32 " stayed state %d (wanted %d) after %d ms", nid, cur, state, ms);
        usleep(50000);
    }
}

static void await_member_hold(int via, uint32_t nid, int want_held, int ms)
{
    uint64_t t0 = now_ms();
    for (;;) {
        struct view v;
        view(via, &v);
        const struct meta_member *m = meta_member(&v.m, nid);
        int held = m && m->hold_until_ms > 0;
        view_free(&v);
        if (held == want_held)
            return;
        if (now_ms() - t0 > (uint64_t)ms)
            die("member %" PRIu32 " hold_until_ms did not become %s after %d ms", nid,
                want_held ? "nonzero" : "zero", ms);
        usleep(50000);
    }
}

/* downkeep (R9 E29): repl_retain_s 3, a replica stopped for ~15 s under writes then restarted. Both the leader and the
 * surviving replica retain segments past repl_retain_s within repl_retain_down_gb, and the restarted replica catches up
 * from WAL segments with zero snapshots installed. */
static void scen_downkeep(void)
{
    scenario("downkeep");
    init_retain_s = 3;
    init_retain_down_set = 1;
    init_retain_down_gb = 64;
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    init_retain_s = 0;
    init_retain_down_set = 0;
    init_retain_down_gb = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    if (L < 0 || L > 2)
        die("the leader of plant is node %u", v.leader);
    int R = (L + 1) % 3, O = (L + 2) % 3;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1;
    uint64_t rows = 0;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("initial write: %s", ers(rc));
    rows++;
    await_isr(0, "plant", 3, 5000, "every replica up");
    stop(R, SIGKILL);
    await_isr(0, "plant", 2, 10000, "a replica killed");
    await_member_state(L, ids[R], META_DOWN, 10000);
    struct timespec s1 = {1, 0};
    int64_t t = 10000;
    for (int k = 0; k < 14; k++) {
        int64_t tv[100];
        float vv[100];
        for (int j = 0; j < 100; j++)
            tv[j] = t++, vv[j] = (float)(k * 100 + j);
        if ((rc = tsdbc_insert_series(c, id, tv, vv, 100)) != 0)
            die("write %d while replica down: %s", k, ers(rc));
        rows += 100;
        if ((rc = tsdbc_flush(c)) != 0)
            die("flush %d: %s", k, ers(rc));
        nanosleep(&s1, NULL);
    }
    if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0)
        die("commit write while replica down: %s", ers(rc));
    rows++;
    int nwl = wal_count(L, 1), nwo = wal_count(O, 1);
    if (nwl < 12)
        die("downkeep: leader kept only %d WAL segments for DOWN replica (wanted >= 12 across 14 s with repl_retain_s 3)",
            nwl);
    if (nwo < 12)
        die("downkeep: surviving replica %d kept only %d WAL segments for DOWN replica (wanted >= 12)", O, nwo);
    start(R);
    await_isr(L, "plant", 3, 30000, "restarted replica catches up from retained segments and rejoins ISR");
    if (log_has(R, "it needs a snapshot") || log_has(R, "snapshot installed") || log_has(L, "needs a snapshot"))
        die("downkeep: restarted replica installed or needed a snapshot instead of catching up from retained WAL segments");
    tsdbc *cr = client(R);
    int got_rows = -1;
    for (uint64_t t0 = now_ms(); (got_rows = rows_of(cr, id)) != (int)rows && now_ms() - t0 < 10000;)
        usleep(50000);
    if (got_rows != (int)rows)
        die("downkeep: replica %d has %d rows, leader has %" PRIu64, R, got_rows, rows);
    tsdbc_close(cr);
    tsdbc_close(c);
    stop_all();
    uint64_t wantr[REP_NAMES] = {rows, 0, 0, 0};
    rep_same(wantr, "downkeep after clean stop");
    printf("  downkeep: leader kept %d and replica %d kept %d WAL segments across 14 s (repl_retain_s 3); restarted "
           "replica caught up with 0 snapshots and holds %" PRIu64 " rows\n",
           nwl, O, nwo, rows);
}

/* downbudget (R9 E29): tiny per-server repl_retain_down_gb budget via TSDB_CLUSTER_TEST=retain_down_kb=24 with two
 * volumes (plant writes large segments exceeding 24 KiB, plant2 writes small segments fitting within 24 KiB). Largest-
 * excess volume (plant) falls back to normal caps and its returning replica installs a snapshot, while small volume
 * (plant2) stays within budget and catches up from WAL. Mutant downnocap ignores the budget and keeps plant's segments. */
static void scen_downbudget(void)
{
    scenario("downbudget");
    init_retain_s = 2;
    init_retain_down_set = 1;
    init_retain_down_gb = 1;
    for (int i = 0; i < 3; i++) {
        envs[i] = "retain_down_kb=24";
        start(i);
    }
    init_cluster(0, 600);
    init_retain_s = 0;
    init_retain_down_set = 0;
    init_retain_down_gb = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num1 = 0, num2 = 0;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num1)) != 0 || num1 != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num1);
    if ((rc = vol_add(0, "plant2", 3, &num2)) != 0 || num2 != 2)
        die("volume add plant2: %s, number %" PRIu32, cluster_strerror(rc), num2);
    for (int i = 0; i < 3; i++) {
        await_open_gen(0, "plant", i, 1, 0);
        await_open_gen(0, "plant2", i, 1, 0);
    }
    struct meta_volume v1, v2;
    if (!vol_rec(0, "plant", &v1) || !vol_rec(0, "plant2", &v2))
        die("no record of plant/plant2");
    int L1 = server_of(v1.leader), L2 = server_of(v2.leader);
    int R = -1;
    for (int i = 0; i < 3; i++)
        if (i != L1 && i != L2)
            R = i;
    if (R < 0)
        R = (L1 + 1) % 3;
    tsdbc *c1 = client(L1), *c2 = client(L2);
    tsdb_sid id1 = rep_series(c1, rep_names[0], "plant", 30000);
    tsdb_sid id2 = rep_series(c2, rep_names[1], "plant2", 30000);
    int64_t ts = 1000;
    float val = 1.0f;
    if ((rc = tsdbc_insert_series(c1, id1, &ts, &val, 1)) != 0)
        die("plant initial write: %s", ers(rc));
    if ((rc = tsdbc_insert_series(c2, id2, &ts, &val, 1)) != 0)
        die("plant2 initial write: %s", ers(rc));
    await_isr(0, "plant", 3, 5000, "plant ISR 3");
    await_isr(0, "plant2", 3, 5000, "plant2 ISR 3");
    stop(R, SIGKILL);
    await_isr(L1, "plant", 2, 10000, "plant ISR 2");
    await_isr(L1, "plant2", 2, 10000, "plant2 ISR 2");
    await_member_state(L1, ids[R], META_DOWN, 10000);
    /* Write 8 segments 1 s apart: ~30 KiB per flush on plant (exceeds 24 KiB budget), tiny flushes on plant2. */
    struct timespec s1 = {1, 0};
    int64_t t1 = 10000, t2 = 10000;
    uint32_t rng = 0x12345678u;
    int64_t *tv1 = malloc(3000 * sizeof *tv1);
    float *vv1 = malloc(3000 * sizeof *vv1);
    if (!tv1 || !vv1)
        die("oom");
    for (int k = 0; k < 8; k++) {
        for (int j = 0; j < 3000; j++) {
            rng ^= rng << 13;
            rng ^= rng >> 17;
            rng ^= rng << 5;
            tv1[j] = t1++;
            vv1[j] = (float)(rng & 0xffffu) * 0.12345f;
        }
        if ((rc = tsdbc_insert_series(c1, id1, tv1, vv1, 3000)) != 0)
            die("plant write %d: %s", k, ers(rc));
        if ((rc = tsdbc_flush(c1)) != 0)
            die("plant flush %d: %s", k, ers(rc));
        int64_t tv2[10];
        float vv2[10];
        for (int j = 0; j < 10; j++)
            tv2[j] = t2++, vv2[j] = (float)j;
        if ((rc = tsdbc_insert_series(c2, id2, tv2, vv2, 10)) != 0)
            die("plant2 write %d: %s", k, ers(rc));
        if ((rc = tsdbc_flush(c2)) != 0)
            die("plant2 flush %d: %s", k, ers(rc));
        nanosleep(&s1, NULL);
    }
    free(tv1);
    free(vv1);
    if ((rc = tsdbc_insert_series(c1, id1, &t1, &val, 1)) != 0)
        die("plant commit write: %s", ers(rc));
    if ((rc = tsdbc_insert_series(c2, id2, &t2, &val, 1)) != 0)
        die("plant2 commit write: %s", ers(rc));
    nanosleep(&s1, NULL);
    int nw1 = wal_count(L1, 1), nw2 = wal_count(L2, 2);
    if (nw1 > 5)
        die("downbudget: past repl_retain_down_gb budget, leader still keeps %d WAL segments of plant (8 flushed, 1 s "
            "apart)", nw1);
    if (nw2 < 6)
        die("downbudget: small volume plant2 only kept %d WAL segments (largest-excess volume plant should be evicted "
            "first)", nw2);
    start(R);
    await_log(R, "volume 1: snapshot installed", 30000, "downbudget: replica back past budget never installed snapshot for plant");
    await_isr(L1, "plant", 3, 30000, "plant ISR 3 after snapshot");
    await_isr(L1, "plant2", 3, 30000, "plant2 ISR 3 after WAL catch-up");
    if (log_has(R, "volume 2: snapshot installed"))
        die("downbudget: small volume plant2 installed a snapshot instead of catching up from retained WAL segments");
    int want1 = rows_of(c1, id1), want2 = rows_of(c2, id2);
    tsdbc *cr = client(R);
    int got1 = -1, got2 = -1;
    for (uint64_t t0 = now_ms(); ((got1 = rows_of(cr, id1)) != want1 || (got2 = rows_of(cr, id2)) != want2) &&
                                 now_ms() - t0 < 10000;)
        usleep(50000);
    if (got1 != want1 || got2 != want2)
        die("downbudget: replica %d has (%d, %d) rows, leaders have (%d, %d)", R, got1, got2, want1, want2);
    tsdbc_close(cr);
    tsdbc_close(c1);
    tsdbc_close(c2);
    stop_all();
    printf("  downbudget: past 24 KiB server budget, plant evicted to %d WAL segments (replica installed snapshot), while "
           "small plant2 kept %d segments (caught up from WAL, 0 snapshots); rows (%d, %d) match\n",
           nw1, nw2, want1, want2);
}

/* holdkeep (R9 E29): holds a live member (META_OP_NODE_HOLD via setop_file) with a long node_timeout_ms so it stays
 * META_UP while stopped across repl_retain_s -> segments are retained on leader and surviving replica and restarted
 * replica catches up with 0 snapshots; then marks it META_OUT -> retention drops immediately back to normal caps.
 * Mutant keepafterout keeps extending retention after META_OUT and fails the post-OUT segment count check. */
static void scen_holdkeep(void)
{
    scenario("holdkeep");
    init_retain_s = 2;
    init_retain_down_set = 1;
    init_retain_down_gb = 64;
    init_node_timeout_ms = 30000;
    for (int i = 0; i < 3; i++) {
        envs[i] = "setop_file=1";
        start(i);
    }
    init_cluster(0, 600);
    init_retain_s = 0;
    init_retain_down_set = 0;
    init_retain_down_gb = 0;
    init_node_timeout_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num = 0;
    int rc;
    if ((rc = vol_add(0, "plant", 3, &num)) != 0 || num != 1)
        die("volume add plant: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "plant", i, 1, 0);
    struct meta_volume v;
    if (!vol_rec(0, "plant", &v))
        die("no record of plant");
    int L = server_of(v.leader);
    int R = (L + 1) % 3, O = (L + 2) % 3;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, rep_names[0], "plant", 30000);
    int64_t ts = 1000;
    float val = 1.0f;
    if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
        die("initial write: %s", ers(rc));
    await_isr(0, "plant", 3, 5000, "every replica up");
    /* Part 1: Hold live member R for 60 s and stop it while it remains META_UP -> retained past repl_retain_s (2 s). */
    char op[64], res[512];
    snprintf(op, sizeof op, "hold %" PRIu32 " 60", ids[R]);
    set_op(3, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("hold op: %s", res);
    await_member_hold(L, ids[R], 1, 10000);
    stop(R, SIGKILL);
    await_isr(L, "plant", 2, 10000, "held replica stopped");
    struct timespec s1 = {1, 0};
    int64_t t = 10000;
    for (int k = 0; k < 6; k++) {
        int64_t tv[100];
        float vv[100];
        for (int j = 0; j < 100; j++)
            tv[j] = t++, vv[j] = (float)j;
        if ((rc = tsdbc_insert_series(c, id, tv, vv, 100)) != 0)
            die("write while held %d: %s", k, ers(rc));
        if ((rc = tsdbc_flush(c)) != 0)
            die("flush while held %d: %s", k, ers(rc));
        nanosleep(&s1, NULL);
    }
    if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0)
        die("commit write while held: %s", ers(rc));
    int nwl_held = wal_count(L, 1), nwo_held = wal_count(O, 1);
    if (nwl_held < 6 || nwo_held < 6)
        die("holdkeep: held member stopped across repl_retain_s 2 s kept only %d (leader) / %d (replica) segments",
            nwl_held, nwo_held);
    start(R);
    await_isr(L, "plant", 3, 30000, "held replica back and caught up from retained segments");
    if (log_has(R, "it needs a snapshot") || log_has(R, "snapshot installed") || log_has(L, "needs a snapshot"))
        die("holdkeep: held replica needed or installed a snapshot instead of catching up from retained WAL segments");
    /* Part 2: Stop R again, write 6 segments past repl_retain_s (retained), then mark R META_OUT -> retention drops! */
    stop(R, SIGKILL);
    await_isr(L, "plant", 2, 10000, "held replica stopped before OUT");
    for (int k = 0; k < 6; k++) {
        int64_t tv[100];
        float vv[100];
        for (int j = 0; j < 100; j++)
            tv[j] = t++, vv[j] = (float)j;
        if ((rc = tsdbc_insert_series(c, id, tv, vv, 100)) != 0)
            die("write before OUT %d: %s", k, ers(rc));
        if ((rc = tsdbc_flush(c)) != 0)
            die("flush before OUT %d: %s", k, ers(rc));
        nanosleep(&s1, NULL);
    }
    if ((rc = tsdbc_insert_series(c, id, &t, &val, 1)) != 0)
        die("commit write before OUT: %s", ers(rc));
    int nw_before_out = wal_count(L, 1);
    if (nw_before_out < 6)
        die("holdkeep: before META_OUT leader kept only %d WAL segments", nw_before_out);
    snprintf(op, sizeof op, "out %" PRIu32, ids[R]);
    set_op(3, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("out op: %s", res);
    await_member_state(L, ids[R], META_OUT, 10000);
    /* Wait up to 6 s for retention refresh (and normal caps) to drop segments older than repl_retain_s (2 s). */
    int nw_after_out = wal_count(L, 1);
    for (uint64_t t0 = now_ms(); (nw_after_out = wal_count(L, 1)) > 4 && now_ms() - t0 < 6000;)
        usleep(100000);
    if (nw_after_out > 4)
        die("holdkeep: after META_OUT, leader still keeps %d WAL segments (expected <= 4 under repl_retain_s 2 s)",
            nw_after_out);
    int nwo_after_out = wal_count(O, 1);
    for (uint64_t t0 = now_ms(); (nwo_after_out = wal_count(O, 1)) > 4 && now_ms() - t0 < 6000;)
        usleep(100000);
    if (nwo_after_out > 4)
        die("holdkeep: after META_OUT, replica %d still keeps %d WAL segments (expected <= 4)", O, nwo_after_out);
    tsdbc_close(c);
    stop_all();
    printf("  holdkeep: held replica retained %d/%d segments across repl_retain_s and caught up with 0 snapshots; after "
           "META_OUT leader dropped %d -> %d segments and replica %d dropped to %d\n",
           nwl_held, nwo_held, nw_before_out, nw_after_out, O, nwo_after_out);
}

/* outmove (r9-plan): replicas=3 on 5 nodes under 4 writers; mark a live member OUT via setop_file (`out NODE`).
 * The pure planner (server/place.c) detects the OUT replica and routes a tracked move through cmove (cmove_start_auto),
 * moving every volume off the OUT member without ever shrinking ISR below 3 (verified by R4's move_watch), leaving
 * every volume with 3 in-sync replicas, zero lost writes, and the OUT member's v1 directory removed. */
static void scen_outmove(void)
{
    scenario("outmove");
    move_env(0);
    struct meta_volume v, v2;
    int L = set_setup(5, &v, 0);
    set_cenv = NULL;
    uint32_t num2 = 0;
    int rc = vol_add(0, "plant2", 3, &num2);
    if (rc != 0 || num2 != 2)
        die("volume add plant2: %s, number %" PRIu32, cluster_strerror(rc), num2);
    if (!vol_rec(0, "plant2", &v2))
        die("no record of plant2");
    for (uint32_t k = 0; k < v2.nrep; k++)
        await_open_gen(0, "plant2", server_of(v2.rep[k].node), 1, 0);
    await_isr(0, "plant", 3, 15000, "plant ISR of 3 before outmove");
    await_isr(0, "plant2", 3, 15000, "plant2 ISR of 3 before outmove");

    /* Also create a replicas=1 volume led by a non-leader replica of plant (deterministic live OUT leader with ISR=1:
     * exercises cmove + planned transfer off a live OUT sole-ISR leader without any fence loop). */
    uint32_t solo_num = 0;
    struct meta_volume vsolo = {0};
    int A = -1, R = leader_of(0);
    char solo_name[32] = "";
    for (int sidx = 1; sidx <= 5 && A < 0; sidx++) {
        snprintf(solo_name, sizeof solo_name, "solo%d", sidx);
        if ((rc = vol_add(0, solo_name, 1, &solo_num)) != 0)
            die("volume add %s: %s", solo_name, cluster_strerror(rc));
        if (!vol_rec(0, solo_name, &vsolo))
            die("no record of %s", solo_name);
        await_open_gen(0, solo_name, server_of(vsolo.leader), 1, 0);
        await_isr(0, solo_name, 1, 15000, "solo ISR of 1 before outmove");
        int ls = server_of(vsolo.leader);
        if (ls >= 0 && ls != L && ls != R && rep_index(&v, ls) >= 0)
            A = ls;
    }
    if (A < 0)
        die("outmove: could not place a replicas=1 volume led by a non-leader replica of plant");

    struct mv_run r;
    move_writers(&r, L, L, 0);

    /* Mark server A META_OUT via setop_file (r9-out / r9-ops are parallel tracks). */
    char op[64], res[512];
    snprintf(op, sizeof op, "out %" PRIu32, ids[A]);
    set_op(5, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("outmove: setop %s: %s", op, res);
    struct state_want out_w = {ids[A], META_OUT, 1};
    await_view(L, p_member_state, &out_w, "node A marked META_OUT");

    /* Restart the Raft leader R while live OUT node A leads solo (replicas=1): the newly elected Raft leader starts
     * with an empty heard table and must NOT prematurely fence/wedge live OUT leader A before settling. */
    if (R >= 0 && R != L && R != A) {
        stop(R, SIGTERM);
        start(R);
    }

    /* Wait for place_plan + cmove to automatically move plant, plant2, and solo (ISR=1 live OUT leader!) off A. */
    struct meta_volume fv = {0}, fv2 = {0}, fsolo = {0};
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        int ok1 = vol_rec(L, "plant", &fv) && fv.nrep == 3 && fv.nisr == 3 && rep_index(&fv, A) < 0 &&
                  !fv.rep[0].learner && !fv.rep[1].learner && !fv.rep[2].learner;
        int ok2 = vol_rec(L, "plant2", &fv2) && fv2.nrep == 3 && fv2.nisr == 3 && rep_index(&fv2, A) < 0 &&
                  !fv2.rep[0].learner && !fv2.rep[1].learner && !fv2.rep[2].learner;
        int ok3 = vol_rec(L, solo_name, &fsolo) && fsolo.nrep == 1 && fsolo.nisr == 1 && rep_index(&fsolo, A) < 0 &&
                  !fsolo.rep[0].learner && fsolo.leader != ids[A] && fsolo.leader != 0;
        if (ok1 && ok2 && ok3)
            break;
        if (now_ms() - t0 > 90000)
            die("outmove: volumes did not evacuate node %" PRIu32 " in 90 s "
                "(plant nrep=%u nisr=%u hasA=%d; plant2 nrep=%u nisr=%u hasA=%d; %s nrep=%u nisr=%u leader=%u hasA=%d)",
                ids[A], fv.nrep, fv.nisr, rep_index(&fv, A) >= 0, fv2.nrep, fv2.nisr, rep_index(&fv2, A) >= 0,
                solo_name, fsolo.nrep, fsolo.nisr, fsolo.leader, rep_index(&fsolo, A) >= 0);
    }

    /* Verify the evacuated replicas=1 volume is led and writable on its new owner. */
    {
        int sL = server_of(fsolo.leader);
        if (sL < 0 || sL == A)
            die("outmove: %s has invalid new leader %" PRIu32, solo_name, fsolo.leader);
        tsdbc *sc = client(sL);
        tsdb_sid sid = write_read(sc, solo_name, 2000);
        if (rows_of(sc, sid) != 3)
            die("outmove: %s write/read on new leader %d failed", solo_name, sL);
        tsdbc_close(sc);
    }

    /* Identify the target node B chosen by place_plan for plant. */
    int B = -1;
    for (uint32_t k = 0; k < fv.nrep; k++) {
        int s = server_of(fv.rep[k].node);
        if (s >= 0 && rep_index(&v, s) < 0) {
            B = s;
            break;
        }
    }
    if (B < 0)
        die("outmove: could not identify replacement target B for plant");

    struct mv_watch x = {.a = ids[A], .b = ids[B]};
    await_move(L, &x, 0, 30000, "outmove");
    move_dir_gone(A);

    /* Unracked cluster STATUS must report "rack loss survivable: no". */
    char pL[META_ADDR_MAX], args[PATH_MAX * 2 + 256], sout[16384];
    peer_of(L, pL, sizeof pL);
    snprintf(args, sizeof args, "cluster status %s --secret-file %s", pL, secret_path);
    if (cli_run(args, NULL, sout, sizeof sout) != 0 || !strstr(sout, "rack loss survivable: no"))
        die("outmove: cluster status missing 'rack loss survivable: no':\n%s", sout);

    for (int k = 0; k < REP_NAMES; k++)
        await_batches(&r.w[k], 10, 20000);
    move_writers_stop(&r);
    stop_all();
    move_watch(L, &x);
    move_rows(&x.last, &r, "after outmove");
    printf("  outmove: node %" PRIu32 " OUT under 4 writers -> plant auto-moved to node %" PRIu32
           " (ISR never below %" PRIu32 ", %" PRIu32 " records), plant2 also back to 3 ISR, 0 lost writes\n",
           ids[A], ids[B], x.min, x.lines);
}

/* ecout (r9-plan): ec=4+2 on 7 racked nodes across 3 racks (r1={0,1,2}, r2={3,4}, r3={5,6}). Verifies initial E9
 * rack-spread placement and STATUS "rack loss survivable: yes", then marks a stripe holder on r1 OUT via setop_file
 * and verifies place_plan automatically moves its stripe position to the 7th node as META_STRIPE_FILLING with prev
 * set to the OUT node (and keeps rack loss survivable: yes). */
static void scen_ecout(void)
{
    scenario("ecout");
    static const char *const racks7[7] = {"r1", "r1", "r1", "r2", "r2", "r3", "r3"};
    epoll_after_two = 1;
    static char init_xa[7][64];
    for (int i = 0; i < 7; i++) {
        envs[i] = "setop_file=1";
        snprintf(init_xa[i], sizeof init_xa[i], "--rack %s", racks7[i]);
        xargs[i] = init_xa[i];
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 7; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters of seven members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    view_free(&v);
    static char xa[7][PATH_MAX + 160];
    for (int i = 0; i < 7; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/ecs%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i], "--rack %s --chunk-dir %s", racks7[i], sd);
        restart_xargs(i, xa[i]);
    }
    unsigned seven = 7;
    await_view(0, p_n_placeable, &seven, "seven racked members UP");

    uint32_t num = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ecout: ec=4+2 add on 7 stores: %s (%s)", cluster_strerror(rc), text);

    struct meta_volume e;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e); usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecout: no record of e42");
    if (e.redundancy != META_RED_EC || e.ec_k != 4 || e.ec_m != 2 || e.nstripe != 6 || e.stripe_version != 1)
        die("ecout: unexpected e42 record (nstripe %u ver %" PRIu64 ")", e.nstripe, e.stripe_version);
    for (uint32_t k = 0; k < e.nrep; k++)
        await_open_gen(0, "e42", server_of(e.rep[k].node), 1, 0);
    await_isr(0, "e42", 3, 15000, "e42 ISR of 3 before ecout");

    /* Verify STATUS shows "rack loss survivable: yes" on the 3-rack 4+2 placement. */
    char p0[META_ADDR_MAX], args[PATH_MAX * 2 + 256], sout[16384];
    peer_of(0, p0, sizeof p0);
    snprintf(args, sizeof args, "cluster status %s --secret-file %s", p0, secret_path);
    if (cli_run(args, NULL, sout, sizeof sout) != 0 || !strstr(sout, "rack loss survivable: yes"))
        die("ecout: cluster status missing 'rack loss survivable: yes':\n%s", sout);

    /* Find the 7th server S not in e.stripe[], and pick a stripe holder H on the same rack (r1) that is not the
     * Raft leader (and preferably not the volume leader). */
    int S = -1;
    for (int i = 0; i < 7; i++) {
        int in_s = 0;
        for (uint32_t p = 0; p < e.nstripe; p++)
            in_s |= (e.stripe[p] == ids[i]);
        if (!in_s) {
            S = i;
            break;
        }
    }
    if (S < 0)
        die("ecout: every server already in 4+2 stripe");
    int R = leader_of(0), H = -1;
    uint32_t hpos = UINT32_MAX;
    for (uint32_t p = 0; p < e.nstripe; p++) {
        int s = server_of(e.stripe[p]);
        if (s >= 0 && !strcmp(racks7[s], racks7[S]) && s != R) {
            H = s;
            hpos = p;
            break;
        }
    }
    if (H < 0) {
        for (uint32_t p = 0; p < e.nstripe; p++) {
            int s = server_of(e.stripe[p]);
            if (s >= 0 && s != R) {
                H = s;
                hpos = p;
                break;
            }
        }
    }
    if (H < 0)
        die("ecout: could not pick a stripe holder to mark OUT");

    char op[64], res[512];
    snprintf(op, sizeof op, "out %" PRIu32, ids[H]);
    set_op(7, op, res, sizeof res);
    if (!strstr(res, "proposed"))
        die("ecout: setop %s: %s", op, res);
    struct state_want out_w = {ids[H], META_OUT, 1};
    await_view(S, p_member_state, &out_w, "stripe holder H marked META_OUT");

    /* Wait for place_plan to move stripe position `hpos` onto the 7th server S as FILLING with prev = H. */
    struct meta_volume e2 = {0};
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        if (vol_rec(S, "e42", &e2) && e2.stripe[hpos] == ids[S] &&
            e2.stripe_pos[hpos].state == META_STRIPE_FILLING && e2.stripe_pos[hpos].prev == ids[H] &&
            e2.stripe_version >= 2)
            break;
        if (now_ms() - t0 > 30000)
            die("ecout: pos %" PRIu32 " did not move from node %" PRIu32 " to node %" PRIu32
                " as FILLING within 30 s (cur holder %" PRIu32 " state %u prev %" PRIu32 " ver %" PRIu64 ")",
                hpos, ids[H], ids[S], e2.stripe[hpos], e2.stripe_pos[hpos].state, e2.stripe_pos[hpos].prev,
                e2.stripe_version);
    }
    /* Verify all 6 stripe positions remain distinct and rack-loss survivable stays yes. */
    for (uint32_t a = 0; a < e2.nstripe; a++)
        for (uint32_t b = a + 1; b < e2.nstripe; b++)
            if (e2.stripe[a] == e2.stripe[b])
                die("ecout: duplicate node %" PRIu32 " in stripe after replacement", e2.stripe[a]);
    /* If H also held a log replica of e42, wait for it to move off H too so STATUS stays rack-loss survivable. */
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        if (vol_rec(S, "e42", &e2) && e2.nrep == 3 && e2.nisr == 3 && rep_index(&e2, H) < 0 &&
            !e2.rep[0].learner && !e2.rep[1].learner && !e2.rep[2].learner)
            break;
        if (now_ms() - t0 > 60000)
            die("ecout: e42 log replicas did not move off OUT node %" PRIu32 " (nrep=%u nisr=%u)", ids[H], e2.nrep,
                e2.nisr);
    }
    char pS[META_ADDR_MAX];
    peer_of(S, pS, sizeof pS);
    snprintf(args, sizeof args, "cluster status %s --secret-file %s", pS, secret_path);
    if (cli_run(args, NULL, sout, sizeof sout) != 0 || !strstr(sout, "rack loss survivable: yes"))
        die("ecout: cluster status after replacement missing 'rack loss survivable: yes':\n%s", sout);

    epoll_after_two = 0;
    stop_all();
    printf("  ecout: 4+2 on 7 racked nodes -> OUT node %" PRIu32 " (pos %" PRIu32 ") auto-moved to node %" PRIu32
           " (FILLING, prev=%" PRIu32 ", stripe_version=%" PRIu64 "), rack loss survivable: yes\n",
           ids[H], hpos, ids[S], e2.stripe_pos[hpos].prev, e2.stripe_version);
}

/* Helper for scen_metrics: parse an integer metric value from a scraped /metrics buffer. Returns 1 if found. */
static int metrics_find_i64(const char *buf, const char *key, int64_t *out)
{
    const char *p = strstr(buf, key);
    if (!p)
        return 0;
    p += strlen(key);
    char *end = NULL;
    long long v = strtoll(p, &end, 10);
    if (end == p)
        return 0;
    *out = (int64_t)v;
    return 1;
}

/* Unit checks for server/creport.[ch] failure & edge paths (run inside scen_metrics). */
static ssize_t cr_u_enc(uint8_t *buf, size_t cap)
{
    if (cap < 4)
        return -1;
    memcpy(buf, "OKAY", 4);
    return 4;
}
static int cr_u_dec(uint32_t member_id, const uint8_t *data, size_t len, void **out)
{
    (void)member_id;
    if (len != 4 || memcmp(data, "OKAY", 4) != 0)
        return -1;
    char *s = malloc(8);
    if (!s)
        return -1;
    memcpy(s, "ok_val", 7);
    *out = s;
    return 0;
}
static void cr_u_free(void *v) { free(v); }
static size_t cr_u_fmt(uint32_t member_id, const void *v, char *buf, size_t cap)
{
    int n = snprintf(buf, cap, "u%" PRIu32 "=%s\n", member_id, (const char *)v);
    return n > 0 ? (size_t)n : 0;
}

static void creport_unit_checks(void)
{
    creport_reset();
    /* Built-in types (<= 8) and missing callbacks must be rejected. */
    if (creport_section(0, cr_u_enc, cr_u_dec, cr_u_free, cr_u_fmt) == 0 ||
        creport_section(CREPORT_SEC_BUILTIN_MAX, cr_u_enc, cr_u_dec, cr_u_free, cr_u_fmt) == 0 ||
        creport_section(100, NULL, cr_u_dec, cr_u_free, cr_u_fmt) == 0)
        die("creport unit: invalid section registration succeeded");
    /* Duplicate type rejected; valid type decodes, replaces without leaking, skips unknown and malformed. */
    if (creport_section(100, cr_u_enc, cr_u_dec, cr_u_free, cr_u_fmt) != 0 ||
        creport_section(100, cr_u_enc, cr_u_dec, cr_u_free, cr_u_fmt) == 0)
        die("creport unit: section register/dup check failed");
    struct creport_heard_secs hs;
    creport_heard_init(&hs);
    if (creport_sec_decode_into(&hs, 101, 1, (const uint8_t *)"xx", 2) != 1)
        die("creport unit: unknown section did not return 1");
    uint64_t err0 = creport_sec_decode_errors();
    if (creport_sec_decode_into(&hs, 100, 1, (const uint8_t *)"BAD!", 4) != -1 ||
        creport_sec_decode_errors() != err0 + 1)
        die("creport unit: malformed section did not fail and increment error count");
    if (creport_sec_decode_into(&hs, 100, 1, (const uint8_t *)"OKAY", 4) != 0 ||
        creport_sec_decode_into(&hs, 100, 1, (const uint8_t *)"OKAY", 4) != 0)
        die("creport unit: valid decode/replace failed");
    /* Format truncation check (tiny cap must NUL-terminate without overflow). */
    char small[5];
    size_t fn = creport_heard_format(&hs, 1, small, sizeof small);
    if (fn != 4 || small[4] != '\0')
        die("creport unit: format truncation bad (fn=%zu)", fn);
    creport_heard_clear(&hs);
    /* Full section table check. */
    for (int t = 101; t < 100 + CREPORT_SEC_MAX; t++)
        if (creport_section((uint8_t)t, cr_u_enc, cr_u_dec, cr_u_free, cr_u_fmt) != 0)
            die("creport unit: filling section table failed at %d", t);
    if (creport_section(200, cr_u_enc, cr_u_dec, cr_u_free, cr_u_fmt) == 0)
        die("creport unit: overflowed section table");
    /* Direct gauge/counter metrics + snapshot + cleanup. */
    struct creport_label lbl = {"node", "1"};
    struct creport_metric *g = creport_metric_gauge("test_u_g", "help", &lbl, 1);
    struct creport_metric *c = creport_metric_counter("test_u_c", "help", NULL, 0);
    if (!g || !c)
        die("creport unit: metric alloc failed");
    creport_metric_set(g, 42.5);
    creport_metric_add(c, 7);
    creport_metric_inc(c);
    struct creport_snap *sn = creport_snap_take();
    if (!sn || sn->nfamilies != 2 || sn->families[0].samples[0].dval != 42.5 || sn->families[1].samples[0].uval != 8)
        die("creport unit: direct metric snapshot mismatch");
    creport_snap_free(sn);
    creport_metric_del(g);
    creport_metric_del(c);
    creport_reset();
}

/* R14 (r14-report, D22/D23): cluster metrics & heartbeat-section registries end-to-end.
 * 3 nodes with --metrics-port auto and report_test=1:
 *   1. Registry dump test hook (<state-dir>/creport.dump) lists CREPORT_SEC_TEST (250) and cluster collectors.
 *   2. Registered creport_section (type 250) arrives in CLUSTER_OP_STATUS for every member (catches sectionsdrop).
 *   3. Every required P4 cluster metric family is present on every node; a 2-replica volume is absent (never 0) on
 *      the non-holding 3rd node.
 *   4. Killing a replica drops tsdb_cluster_volume_isr_size and tsdb_cluster_volume_young_margin on the leader's
 *      /metrics within 2 s (catches metricstale); restarting recovers them.
 *   5. Leadership transfer moves tsdb_cluster_volume_role to the new leader and bumps tsdb_cluster_transfers_total. */
static void scen_metrics(void)
{
    scenario("metrics");
    creport_unit_checks();
    int mports[3] = {0};
    init_isr_lag_ms = 500;
    for (int i = 0; i < 3; i++) {
        envs[i] = "report_test=1";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
        if (mports[i] <= 0)
            die("metrics: server %d reported no metrics port", i);
    }
    init_cluster(0, 600);
    init_isr_lag_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");

    /* Create vol3 (replicas=3: held by all 3 nodes) and vol2 (replicas=2: held by 2, absent on 3rd). */
    uint32_t v3 = 0, v2 = 0;
    int rc = vol_add(0, "mvol3", 3, &v3);
    if (rc != 0)
        die("metrics: vol_add mvol3: %s", cluster_strerror(rc));
    rc = vol_add(0, "mvol2", 2, &v2);
    if (rc != 0)
        die("metrics: vol_add mvol2: %s", cluster_strerror(rc));

    struct meta_volume mv3, mv2;
    if (!vol_rec(0, "mvol3", &mv3) || !vol_rec(0, "mvol2", &mv2))
        die("metrics: missing volume record");
    int L = server_of(mv3.leader), R1 = -1, R2 = -1;
    for (uint32_t k = 0; k < mv3.nrep; k++) {
        int s = server_of(mv3.rep[k].node);
        await_open_gen(0, "mvol3", s, 1, 0);
        if (s != L) {
            if (R1 < 0)
                R1 = s;
            else
                R2 = s;
        }
    }
    int nonholder = -1;
    for (int i = 0; i < 3; i++) {
        int holds = 0;
        for (uint32_t k = 0; k < mv2.nrep; k++)
            if (mv2.rep[k].node == ids[i])
                holds = 1;
        if (holds)
            await_open_gen(0, "mvol2", i, 1, 0);
        else
            nonholder = i;
    }
    if (L < 0 || R1 < 0 || R2 < 0 || nonholder < 0)
        die("metrics: unexpected topology L=%d R1=%d R2=%d nonholder=%d", L, R1, R2, nonholder);

    await_isr(L, "mvol3", 3, 20000, "mvol3 3/3 ISR");
    await_isr(0, "mvol2", 2, 20000, "mvol2 2/2 ISR");

    /* Write a small batch so replication state is exercised. */
    tsdbc *c = client(L);
    tsdb_sid sid = rep_series(c, "metrics.s1", "mvol3", 30000);
    int64_t ts[16];
    float vals[16];
    for (int k = 0; k < 16; k++)
        ts[k] = 10000 + k * 100, vals[k] = (float)(k + 1);
    if ((rc = tsdbc_insert_series(c, sid, ts, vals, 16)) != 0)
        die("metrics: insert mvol3: %s", ers(rc));
    tsdbc_close(c);

    /* 1. Verify registry dump test hook file on node 0. */
    {
        char dpath[PATH_MAX + 128];
        snprintf(dpath, sizeof dpath, "%s/n0/state/creport.dump", base);
        FILE *f = fopen(dpath, "rb");
        if (!f)
            die("metrics: missing registry dump file %s", dpath);
        char dbuf[16384];
        size_t dn = fread(dbuf, 1, sizeof dbuf - 1, f);
        fclose(f);
        dbuf[dn] = '\0';
        if (!strstr(dbuf, "section type=250\n") || !strstr(dbuf, "collector tsdb_cluster_raft_term type=gauge\n"))
            die("metrics: registry dump %s missing expected entries:\n%s", dpath, dbuf);
    }

    /* 2. Verify registered creport_section (type 250) arrives in CLUSTER_OP_STATUS on the Raft leader. */
    int sec_ok = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 8000 && !sec_ok; usleep(150000)) {
        struct view v;
        view(0, &v);
        int found = 0;
        for (int i = 0; i < 3; i++) {
            char needle[64];
            snprintf(needle, sizeof needle, "r14test node=%" PRIu32 " seq=", ids[i]);
            for (uint32_t k = 0; k < v.st.nheard; k++) {
                if (v.st.heard[k].id == ids[i] && v.st.heard[k].sections &&
                    strstr(v.st.heard[k].sections, needle)) {
                    found++;
                    break;
                }
            }
        }
        view_free(&v);
        if (found == 3)
            sec_ok = 1;
    }
    if (!sec_ok)
        die("metrics: registered creport_section (type 250) did not arrive in STATUS for all 3 members");

    /* 3. Verify every required metric family is present on every node, and non-held vol2 is absent on nonholder. */
    static const char *const required_families[] = {
        "\n# TYPE tsdb_cluster_raft_term gauge\n",
        "\n# TYPE tsdb_cluster_raft_leader gauge\n",
        "\n# TYPE tsdb_cluster_raft_commit_lag gauge\n",
        "\n# TYPE tsdb_cluster_raft_quorum gauge\n",
        "\n# TYPE tsdb_cluster_member_state gauge\n",
        "\n# TYPE tsdb_cluster_volume_role gauge\n",
        "\n# TYPE tsdb_cluster_volume_epoch gauge\n",
        "\n# TYPE tsdb_cluster_volume_isr_size gauge\n",
        "\n# TYPE tsdb_cluster_volume_min_isr gauge\n",
        "\n# TYPE tsdb_cluster_volume_young_margin gauge\n",
        "\n# TYPE tsdb_cluster_volume_settled_margin gauge\n",
        "\n# TYPE tsdb_cluster_volume_health gauge\n",
        "\n# TYPE tsdb_cluster_volume_diverged gauge\n",
        "\n# TYPE tsdb_cluster_volume_lag_positions gauge\n",
        "\n# TYPE tsdb_cluster_volume_lag_ms gauge\n",
        "\n# TYPE tsdb_cluster_volume_unavailable gauge\n",
        "\n# TYPE tsdb_chunk_store_state gauge\n",
        "\n# TYPE tsdb_cluster_out_guard_passed_total counter\n",
        "\n# TYPE tsdb_cluster_transfers_total counter\n",
        "\n# TYPE tsdb_cluster_moves_total counter\n",
        "\n# TYPE tsdb_cluster_settles_total counter\n",
    };
    static const char *const held_prefixes[] = {
        "\ntsdb_cluster_volume_role{volume=\"",
        "\ntsdb_cluster_volume_epoch{volume=\"",
        "\ntsdb_cluster_volume_isr_size{volume=\"",
        "\ntsdb_cluster_volume_min_isr{volume=\"",
        "\ntsdb_cluster_volume_young_margin{volume=\"",
        "\ntsdb_cluster_volume_settled_margin{volume=\"",
        "\ntsdb_cluster_volume_health{volume=\"",
        "\ntsdb_cluster_volume_diverged{volume=\"",
        "\ntsdb_cluster_volume_lag_positions{volume=\"",
        "\ntsdb_cluster_volume_lag_ms{volume=\"",
        "\ntsdb_cluster_volume_unavailable{volume=\"",
    };

    static char mbuf[1 << 20];
    int raft_leaders = 0;
    int64_t initial_epoch = 0;
    for (int i = 0; i < 3; i++) {
        /* Wait briefly until node i's /metrics has caught up to vol3 and quorum. */
        int ready = 0;
        for (uint64_t t0 = now_ms(); now_ms() - t0 < 5000 && !ready; usleep(100000)) {
            metrics_get(mports[i], mbuf, sizeof mbuf);
            int64_t q = 0, isr = 0;
            char k_isr[96];
            snprintf(k_isr, sizeof k_isr, "\ntsdb_cluster_volume_isr_size{volume=\"%" PRIu32 "\"} ", v3);
            if (metrics_find_i64(mbuf, "\ntsdb_cluster_raft_quorum ", &q) && q == 1 &&
                metrics_find_i64(mbuf, k_isr, &isr) && isr == 3)
                ready = 1;
        }
        if (!ready)
            die("metrics: server %d never reported raft_quorum=1 and mvol3 isr_size=3", i);

        for (size_t f = 0; f < sizeof required_families / sizeof required_families[0]; f++) {
            if (!strstr(mbuf, required_families[f]))
                die("metrics: server %d missing family:%s", i, required_families[f]);
        }
        int64_t term = 0, rlead = 0, clag = -1, quorum = 0;
        if (!metrics_find_i64(mbuf, "\ntsdb_cluster_raft_term ", &term) || term < 1 ||
            !metrics_find_i64(mbuf, "\ntsdb_cluster_raft_leader ", &rlead) || (rlead != 0 && rlead != 1) ||
            !metrics_find_i64(mbuf, "\ntsdb_cluster_raft_commit_lag ", &clag) || clag < 0 ||
            !metrics_find_i64(mbuf, "\ntsdb_cluster_raft_quorum ", &quorum) || quorum != 1)
            die("metrics: server %d bad raft gauges (term=%" PRId64 " leader=%" PRId64 " lag=%" PRId64 " quorum=%" PRId64 ")",
                i, term, rlead, clag, quorum);
        raft_leaders += (int)rlead;

        for (int j = 0; j < 3; j++) {
            char km[96];
            int64_t mst = -1;
            snprintf(km, sizeof km, "\ntsdb_cluster_member_state{node=\"%" PRIu32 "\"} ", ids[j]);
            if (!metrics_find_i64(mbuf, km, &mst) || mst != META_UP)
                die("metrics: server %d member %" PRIu32 " state=%" PRId64 " (want %d)", i, ids[j], mst, META_UP);
        }

        char k[128];
        int64_t role = -1, ep = 0, isr = -1, misr = -1, ym = -99, hlth = -1, div = -1, lpos = -1, lms = -1;
        snprintf(k, sizeof k, "\ntsdb_cluster_volume_role{volume=\"%" PRIu32 "\"} ", v3);
        if (!metrics_find_i64(mbuf, k, &role) || role != (i == L ? TSDB_ROLE_OWNER : TSDB_ROLE_STANDBY))
            die("metrics: server %d mvol3 role=%" PRId64 " (want %d)", i, role,
                i == L ? TSDB_ROLE_OWNER : TSDB_ROLE_STANDBY);
        snprintf(k, sizeof k, "\ntsdb_cluster_volume_epoch{volume=\"%" PRIu32 "\"} ", v3);
        if (!metrics_find_i64(mbuf, k, &ep) || ep < 1)
            die("metrics: server %d mvol3 epoch=%" PRId64, i, ep);
        if (i == L)
            initial_epoch = ep;
        snprintf(k, sizeof k, "\ntsdb_cluster_volume_isr_size{volume=\"%" PRIu32 "\"} ", v3);
        if (!metrics_find_i64(mbuf, k, &isr) || isr != 3)
            die("metrics: server %d mvol3 isr_size=%" PRId64 " (want 3)", i, isr);
        snprintf(k, sizeof k, "\ntsdb_cluster_volume_min_isr{volume=\"%" PRIu32 "\"} ", v3);
        if (!metrics_find_i64(mbuf, k, &misr) || misr < 1)
            die("metrics: server %d mvol3 min_isr=%" PRId64, i, misr);
        snprintf(k, sizeof k, "\ntsdb_cluster_volume_young_margin{volume=\"%" PRIu32 "\"} ", v3);
        if (!metrics_find_i64(mbuf, k, &ym) || ym != 2)
            die("metrics: server %d mvol3 young_margin=%" PRId64 " (want 2)", i, ym);
        snprintf(k, sizeof k, "\ntsdb_cluster_volume_health{volume=\"%" PRIu32 "\"} ", v3);
        if (!metrics_find_i64(mbuf, k, &hlth) || hlth != CL_HEALTH_OK)
            die("metrics: server %d mvol3 health=%" PRId64 " (want 0)", i, hlth);
        snprintf(k, sizeof k, "\ntsdb_cluster_volume_diverged{volume=\"%" PRIu32 "\"} ", v3);
        if (!metrics_find_i64(mbuf, k, &div) || div != 0)
            die("metrics: server %d mvol3 diverged=%" PRId64 " (want 0)", i, div);
        snprintf(k, sizeof k, "\ntsdb_cluster_volume_lag_positions{volume=\"%" PRIu32 "\"} ", v3);
        if (!metrics_find_i64(mbuf, k, &lpos) || lpos < 0)
            die("metrics: server %d missing mvol3 lag_positions", i);
        snprintf(k, sizeof k, "\ntsdb_cluster_volume_lag_ms{volume=\"%" PRIu32 "\"} ", v3);
        if (!metrics_find_i64(mbuf, k, &lms) || lms < 0)
            die("metrics: server %d missing mvol3 lag_ms", i);

        /* Non-held volume absence check: vol2 MUST be absent on nonholder, present on holders. */
        if (i == nonholder) {
            for (size_t p = 0; p < sizeof held_prefixes / sizeof held_prefixes[0]; p++) {
                snprintf(k, sizeof k, "%s%" PRIu32 "\"", held_prefixes[p], v2);
                if (strstr(mbuf, k))
                    die("metrics: non-holding server %d emitted non-held volume %" PRIu32 " (%s)", i, v2, k + 1);
            }
        } else {
            int64_t isr2 = -1;
            snprintf(k, sizeof k, "\ntsdb_cluster_volume_isr_size{volume=\"%" PRIu32 "\"} ", v2);
            if (!metrics_find_i64(mbuf, k, &isr2) || isr2 != 2)
                die("metrics: holding server %d missing mvol2 isr_size=2 (got %" PRId64 ")", i, isr2);
        }
    }
    if (raft_leaders != 1)
        die("metrics: expected exactly 1 Raft leader across 3 nodes, got %d", raft_leaders);

    /* 4. Kill replica R1: isr_size drops to 2 and young_margin drops to 1 on leader L's /metrics within 2 s of
     *    ISR shrink (catches metricstale). Then restart R1 and verify both recover to 3 and 2. */
    stop(R1, SIGKILL);
    await_isr(L, "mvol3", 2, 15000, "mvol3 ISR shrink after kill R1");
    int dropped = 0;
    uint64_t drop_ms = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 <= 2000; usleep(50000)) {
        metrics_get(mports[L], mbuf, sizeof mbuf);
        char ki[96], ky[96];
        int64_t isr = -1, ym = -99;
        snprintf(ki, sizeof ki, "\ntsdb_cluster_volume_isr_size{volume=\"%" PRIu32 "\"} ", v3);
        snprintf(ky, sizeof ky, "\ntsdb_cluster_volume_young_margin{volume=\"%" PRIu32 "\"} ", v3);
        if (metrics_find_i64(mbuf, ki, &isr) && isr == 2 && metrics_find_i64(mbuf, ky, &ym) && ym == 1) {
            drop_ms = now_ms() - t0;
            dropped = 1;
            break;
        }
    }
    if (!dropped)
        die("metrics: leader %d /metrics did not drop mvol3 isr_size->2 and young_margin->1 within 2 s", L);

    start(R1);
    mports[R1] = th_mport;
    await_isr(L, "mvol3", 3, 20000, "mvol3 ISR recovery after restart R1");
    int recovered = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 <= 2000; usleep(50000)) {
        metrics_get(mports[L], mbuf, sizeof mbuf);
        char ki[96], ky[96];
        int64_t isr = -1, ym = -99;
        snprintf(ki, sizeof ki, "\ntsdb_cluster_volume_isr_size{volume=\"%" PRIu32 "\"} ", v3);
        snprintf(ky, sizeof ky, "\ntsdb_cluster_volume_young_margin{volume=\"%" PRIu32 "\"} ", v3);
        if (metrics_find_i64(mbuf, ki, &isr) && isr == 3 && metrics_find_i64(mbuf, ky, &ym) && ym == 2) {
            recovered = 1;
            break;
        }
    }
    if (!recovered)
        die("metrics: leader %d /metrics did not recover mvol3 isr_size->3 and young_margin->2 within 2 s", L);

    /* 5. Transfer leadership of vol3 from L to R2: verify role gauge moves to R2 and epoch advances. */
    uint8_t tbody[8], *treply = NULL;
    size_t tblen = cluster_volume_force_encode(v3, ids[R2], tbody), trlen = 0;
    rc = -1;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 10000; usleep(150000)) {
        rc = admin(0, CLUSTER_OP_VOLUME_TRANSFER, tbody, tblen, 1, &treply, &trlen);
        free(treply);
        treply = NULL;
        if (rc == 0)
            break;
    }
    if (rc != 0)
        die("metrics: volume transfer mvol3 -> node %" PRIu32 ": %s", ids[R2], cluster_strerror(rc));
    int moved = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000 && !moved; usleep(100000)) {
        char kr[96], ke[96];
        int64_t role_old = -1, role_new = -1, ep_new = 0;
        snprintf(kr, sizeof kr, "\ntsdb_cluster_volume_role{volume=\"%" PRIu32 "\"} ", v3);
        snprintf(ke, sizeof ke, "\ntsdb_cluster_volume_epoch{volume=\"%" PRIu32 "\"} ", v3);
        metrics_get(mports[L], mbuf, sizeof mbuf);
        int ok1 = metrics_find_i64(mbuf, kr, &role_old);
        metrics_get(mports[R2], mbuf, sizeof mbuf);
        int ok2 = metrics_find_i64(mbuf, kr, &role_new) && metrics_find_i64(mbuf, ke, &ep_new);
        if (ok1 && ok2 && role_old == TSDB_ROLE_STANDBY && role_new == TSDB_ROLE_OWNER && ep_new > initial_epoch)
            moved = 1;
    }
    if (!moved)
        die("metrics: tsdb_cluster_volume_role did not move from server %d to server %d after transfer", L, R2);

    /* Verify transfer counter bumped on the Raft leader. */
    int raft_l = -1;
    for (int i = 0; i < 3; i++) {
        metrics_get(mports[i], mbuf, sizeof mbuf);
        int64_t rl = 0;
        if (metrics_find_i64(mbuf, "\ntsdb_cluster_raft_leader ", &rl) && rl == 1) {
            raft_l = i;
            int64_t td = 0;
            if (!metrics_find_i64(mbuf, "\ntsdb_cluster_transfers_total{event=\"done\"} ", &td) || td < 1)
                die("metrics: Raft leader %d tsdb_cluster_transfers_total{event=\"done\"}=%" PRId64 " (want >= 1)", i,
                    td);
            break;
        }
    }
    if (raft_l < 0)
        die("metrics: could not find Raft leader for transfer counter check");

    stop_all();
    printf("  metrics: 3 nodes, all 21 families verified, non-held volume absent on server %d, "
           "creport_section 250 in STATUS, kill/restart drop in %" PRIu64 " ms, role moved %d->%d\n",
           nonholder, drop_ms, L, R2);
}

/* Unit checks for HBS_PROGRESS encode/decode/bounds, scrub hook points, stall computation, and STATUS progress block. */
static struct creport_vol_progress pu_vol;
static struct creport_store_progress pu_store;
static uint32_t pu_vols_cb(void *arg, struct creport_vol_progress *out, uint32_t cap)
{
    (void)arg;
    if (cap == 0)
        return 0;
    out[0] = pu_vol;
    out[0].young_scrub_age_s = creport_progress_query_young_scrub(out[0].volume);
    return 1;
}
static uint32_t pu_stores_cb(void *arg, struct creport_store_progress *out, uint32_t cap)
{
    (void)arg;
    if (cap == 0)
        return 0;
    out[0] = pu_store;
    creport_progress_query_store_extra(out[0].store, &out[0].scrub_age_s, &out[0].drain_bytes_left);
    return 1;
}
static uint64_t pu_young_scrub_cb(void *arg, uint32_t volume)
{
    (void)arg;
    return volume == 7 ? 321u : 0u;
}
static void pu_store_extra_cb(void *arg, uint32_t store, uint64_t *scrub_age_s, uint64_t *drain_bytes_left)
{
    (void)arg;
    if (store == 2) {
        if (scrub_age_s)
            *scrub_age_s = 654u;
        if (drain_bytes_left)
            *drain_bytes_left = 987654u;
    }
}
struct pu_emit_ctx {
    uint16_t type;
    uint8_t buf[2048];
    size_t len;
    int seen;
};
static void pu_emit_cb(void *ctx, uint16_t type, const uint8_t *data, size_t len)
{
    struct pu_emit_ctx *e = ctx;
    if (type == HBS_PROGRESS && len <= sizeof e->buf) {
        e->type = type;
        memcpy(e->buf, data, len);
        e->len = len;
        e->seen = 1;
    }
}

static void progress_unit_checks(void)
{
    creport_reset();

    /* 1. Unknown section skipped cleanly when HBS_PROGRESS is not registered (older peer simulation). */
    struct creport_heard_secs hs;
    creport_heard_init(&hs);
    uint64_t err0 = creport_sec_decode_errors();
    uint8_t dummy[17] = {1};
    if (creport_sec_decode_into(&hs, HBS_PROGRESS, 1, dummy, sizeof dummy) != 1 ||
        creport_sec_decode_errors() != err0)
        die("progress unit: unregistered HBS_PROGRESS was not skipped cleanly");

    /* 2. Register HBS_PROGRESS (idempotent) + encode/decode round-trip + scrub/drain hooks. */
    if (creport_progress_register() != 0 || creport_progress_register() != 0)
        die("progress unit: creport_progress_register failed");
    pu_vol = (struct creport_vol_progress){
        .volume = 7,
        .role = CREPORT_REBUILD_SNAP_DST,
        .bytes_done = 4096,
        .bytes_total = 16384,
        .started_ms = 100000,
        .last_progress_ms = 100500,
        .settle_keys_waiting = 3,
        .settle_oldest_wait_s = 45,
    };
    pu_store = (struct creport_store_progress){.store = 2};
    creport_progress_set_providers(pu_vols_cb, NULL, pu_stores_cb, NULL);

    /* Unregistered scrub/drain hooks return 0. */
    if (creport_progress_query_young_scrub(7) != 0)
        die("progress unit: unregistered young scrub hook returned non-zero");
    uint64_t sa = 1, dl = 1;
    creport_progress_query_store_extra(2, &sa, &dl);
    if (sa != 0 || dl != 0)
        die("progress unit: unregistered store extra hook returned non-zero");

    /* Register hooks and verify values flow through encode -> decode. */
    creport_progress_set_young_scrub(pu_young_scrub_cb, NULL);
    creport_progress_set_store_extra(pu_store_extra_cb, NULL);
    struct pu_emit_ctx em = {0};
    creport_sec_encode_all(pu_emit_cb, &em);
    if (!em.seen || em.len != 17 + 57 + 20)
        die("progress unit: unexpected HBS_PROGRESS encoded length %zu (seen=%d)", em.len, em.seen);
    if (creport_sec_decode_into(&hs, HBS_PROGRESS, 2, em.buf, em.len) != 0)
        die("progress unit: HBS_PROGRESS decode failed");
    const struct creport_progress *pr = creport_heard_get(&hs, HBS_PROGRESS);
    if (!pr || pr->nvols != 1 || pr->nstores != 1 || pr->vols[0].volume != 7 ||
        pr->vols[0].role != CREPORT_REBUILD_SNAP_DST || pr->vols[0].bytes_done != 4096 ||
        pr->vols[0].settle_keys_waiting != 3 || pr->vols[0].settle_oldest_wait_s != 45 ||
        pr->vols[0].young_scrub_age_s != 321 || pr->stores[0].store != 2 || pr->stores[0].scrub_age_s != 654 ||
        pr->stores[0].drain_bytes_left != 987654)
        die("progress unit: decoded HBS_PROGRESS mismatch");

    /* 3. Malformed HBS_PROGRESS payloads rejected & counted. */
    uint64_t e1 = creport_sec_decode_errors();
    uint8_t bad_ver[17] = {2};
    uint8_t bad_cnt[17] = {1};
    bad_cnt[9] = 1; /* nvols=1 but 0 vol bytes */
    uint8_t bad_role[17 + 57 + 20];
    memcpy(bad_role, em.buf, em.len);
    bad_role[17 + 4] = 99; /* invalid role */
    if (creport_sec_decode_into(&hs, HBS_PROGRESS, 2, em.buf, 16) != -1 ||
        creport_sec_decode_into(&hs, HBS_PROGRESS, 2, bad_ver, sizeof bad_ver) != -1 ||
        creport_sec_decode_into(&hs, HBS_PROGRESS, 2, bad_cnt, sizeof bad_cnt) != -1 ||
        creport_sec_decode_into(&hs, HBS_PROGRESS, 2, bad_role, em.len) != -1 ||
        creport_sec_decode_errors() != e1 + 4)
        die("progress unit: malformed HBS_PROGRESS not rejected/counted");

    /* 4. Stall boundary checks. */
    uint64_t thresh = creport_progress_stall_ms();
    if (creport_progress_is_stalled(CREPORT_REBUILD_NONE, thresh + 1000, 1, 0, 0) != 0)
        die("progress unit: idle role reported stalled");
    if (creport_progress_is_stalled(CREPORT_REBUILD_SNAP_DST, 1000 + thresh - 1, 1000, 0, 0) != 0)
        die("progress unit: below stall threshold reported stalled");
    if (creport_progress_is_stalled(CREPORT_REBUILD_SNAP_DST, 1000 + thresh, 1000, 0, 0) != 1)
        die("progress unit: at stall threshold did not report stalled");
    if (creport_progress_is_stalled(CREPORT_REBUILD_SNAP_DST, 1000, 1000, 1000000ull,
                                    1000000ull + thresh * 1000000ull) != 1)
        die("progress unit: beat_age at stall threshold did not report stalled");

    /* 5. cluster_status_parse appended progress block strict bounds checks. */
    uint8_t base_st[256];
    size_t boff = 0;
    memset(base_st, 0, sizeof base_st);
    /* Minimal valid STATUS body with nheard=1 (id=1), 0 vols/doms/unreach/sections/fills, 0 tr, empty moves/links, 0 image. */
    base_st[0] = 1; /* self=1 */
    boff = 4 + 1 + 1 + 1 + 8 + 4 + 8 + 8; /* header before nheard: 35 bytes */
    base_st[boff] = 1; /* nheard=1 */
    boff += 4;
    base_st[boff] = 1; /* heard[0].id=1 */
    boff += 4 + 8 + 8 + 1 + 1 + 1 + 1 + 1 + 1 + 8; /* 34 bytes */
    boff += 4; /* nvols=0 */
    boff += 4; /* ndoms=0 */
    boff += 4; /* nunreach=0 */
    boff += 8 + 8; /* answered_ms, lease_left_ms */
    boff += 2; /* slen=0 */
    boff += 4; /* nfills=0 */
    boff += 4; /* nlive_objs=0 */
    boff += 1; /* users_caught_up=0 */
    boff += 4; /* ntr=0 */
    boff += 2; /* moves="" */
    boff += 2; /* links="" */
    boff += 8; /* wall_ms=0 */
    boff += 4; /* image_len=0 */
    struct cluster_status pst;
    if (cluster_status_parse(base_st, boff, &pst) != 0 || pst.nheard != 1)
        die("progress unit: minimal base STATUS without progress block failed to parse");
    cluster_status_free(&pst);

    /* Truncated magic, bad magic, pn > nheard, unknown mid, trailing garbage must all fail cleanly. */
    uint8_t bad_st[320];
    memcpy(bad_st, base_st, boff);
    bad_st[boff] = 0x47;
    if (cluster_status_parse(bad_st, boff + 1, &pst) == 0)
        die("progress unit: truncated progress magic accepted");
    bad_st[boff] = 0x47, bad_st[boff + 1] = 0x4f, bad_st[boff + 2] = 0x52, bad_st[boff + 3] = 0x50; /* "PROG" */
    bad_st[boff + 4] = 1; /* version=1 */
    bad_st[boff + 5] = 2, bad_st[boff + 6] = 0, bad_st[boff + 7] = 0, bad_st[boff + 8] = 0; /* pn=2 > nheard=1 */
    if (cluster_status_parse(bad_st, boff + 9, &pst) == 0)
        die("progress unit: pn > nheard accepted");
    bad_st[boff + 5] = 1; /* pn=1 */
    /* member_id=99 (not in heard), nvols=0, nstores=0 */
    memset(bad_st + boff + 9, 0, 12);
    bad_st[boff + 9] = 99;
    if (cluster_status_parse(bad_st, boff + 21, &pst) == 0)
        die("progress unit: unknown member_id in progress block accepted");
    /* Valid member_id=1, nvols=0, nstores=0 -> must succeed, then +1 trailing byte must fail. */
    bad_st[boff + 9] = 1;
    if (cluster_status_parse(bad_st, boff + 21, &pst) != 0)
        die("progress unit: valid empty progress block rejected");
    cluster_status_free(&pst);
    bad_st[boff + 21] = 0;
    if (cluster_status_parse(bad_st, boff + 22, &pst) == 0)
        die("progress unit: trailing garbage after progress block accepted");

    /* Verify idle entries are omitted from HBS_PROGRESS (zero bytes on idle heartbeats). */
    pu_vol = (struct creport_vol_progress){.volume = 7, .role = CREPORT_REBUILD_NONE};
    pu_store = (struct creport_store_progress){.store = 2};
    creport_progress_set_young_scrub(NULL, NULL);
    creport_progress_set_store_extra(NULL, NULL);
    struct pu_emit_ctx em_idle = {0};
    creport_sec_encode_all(pu_emit_cb, &em_idle);
    if (em_idle.seen)
        die("progress unit: idle HBS_PROGRESS was not omitted");

    creport_heard_clear(&hs);
    creport_reset();
}

static const struct creport_vol_progress *view_find_progress(const struct view *v, uint32_t node_id, uint32_t vol)
{
    for (uint32_t i = 0; i < v->st.nheard; i++) {
        if (v->st.heard[i].id != node_id)
            continue;
        for (uint32_t j = 0; j < v->st.heard[i].nprogress_vols; j++) {
            if (v->st.heard[i].progress_vols[j].volume == vol)
                return &v->st.heard[i].progress_vols[j];
        }
    }
    return NULL;
}

/* R14 (r14-progress, E43, D23): rebuild/snapshot & settle backlog progress in HBS_PROGRESS, STATUS, and /metrics.
 *   1. Unit checks for HBS_PROGRESS wire bounds, scrub hooks, stall math, and STATUS appended progress block.
 *   2. 3-node cluster with low rebuild_mb_s=1 and progress_stall_ms=1500:
 *      - Node 0 stays Raft leader; volume leader L != 0; replica R killed & falls past repl_retain_s.
 *      - Restart R: bytes_done rises in Raft leader STATUS and R's /metrics; bytes_total matches snapshot size;
 *        stalled=0 (catches progressfrozen and progressnototal).
 *      - SIGSTOP source L past progress_stall_ms: stalled=1 in STATUS and R's /metrics.
 *      - SIGCONT source L: transfer finishes, stalled returns to 0 and role returns to none.
 *   3. (TSDB_EC builds) Hold settles via TSDB_SETTLE_HOLD=<file>: create ec=2+1 volume, write 2 past-day partitions,
 *      verify settle_keys_waiting >= 2 and settle_oldest_wait_s > 0 in STATUS and leader /metrics; release hold and
 *      verify backlog drains to 0. */
static void scen_progress(void)
{
    scenario("progress");
    progress_unit_checks();

    int mports[4] = {0};
    init_retain_s = 2;
    init_rebuild_mb_s = 1;
    init_node_timeout_ms = 15000;
    init_isr_lag_ms = 500;
    for (int i = 0; i < 3; i++) {
        envs[i] = "progress_stall_ms=2500";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
        if (mports[i] <= 0)
            die("progress: server %d reported no metrics port", i);
    }
    init_cluster(0, 600);
    init_retain_s = 0;
    init_rebuild_mb_s = 0;
    init_node_timeout_ms = 0;
    init_isr_lag_ms = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");

    uint32_t vnum = 0;
    int rc = vol_add(0, "pvol", 3, &vnum);
    if (rc != 0)
        die("progress: vol_add pvol: %s", cluster_strerror(rc));
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "pvol", i, 1, 0);
    await_isr(0, "pvol", 3, 20000, "pvol 3/3 ISR");

    /* Ensure volume leader L is NOT node 0 (the Raft leader), so SIGSTOPping L leaves Raft leader 0 answering STATUS. */
    struct meta_volume mv;
    if (!vol_rec(0, "pvol", &mv))
        die("progress: missing pvol record");
    int L = server_of(mv.leader);
    if (L == 0) {
        uint8_t tbody[8], *treply = NULL;
        size_t tblen = cluster_volume_force_encode(vnum, ids[1], tbody), trlen = 0;
        rc = -1;
        for (uint64_t t0 = now_ms(); now_ms() - t0 < 10000; usleep(150000)) {
            rc = admin(0, CLUSTER_OP_VOLUME_TRANSFER, tbody, tblen, 1, &treply, &trlen);
            free(treply);
            treply = NULL;
            if (rc == 0)
                break;
        }
        if (rc != 0)
            die("progress: transfer pvol to node %" PRIu32 ": %s", ids[1], cluster_strerror(rc));
        for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000; usleep(100000)) {
            if (vol_rec(1, "pvol", &mv) && server_of(mv.leader) == 1) {
                struct view v;
                view(1, &v);
                int is_owner = 0;
                for (uint32_t h = 0; h < v.st.nheard; h++)
                    if (v.st.heard[h].id == ids[1])
                        for (uint32_t j = 0; j < v.st.heard[h].nvols; j++)
                            if (v.st.heard[h].vols[j].v.volume == vnum && v.st.heard[h].vols[j].v.role == CL_ROLE_OWNER)
                                is_owner = 1;
                view_free(&v);
                if (is_owner)
                    break;
            }
        }
        L = server_of(mv.leader);
    }
    if (L != 1 && L != 2)
        die("progress: expected pvol leader on server 1 or 2, got %d", L);
    int R = (L == 1) ? 2 : 1;

    /* Write ~3M random rows (~10-12 MB compressed -> ~10-12 s transfer at 1 MB/s). */
    tsdbc *c = client(L);
    tsdb_sid sid = rep_series(c, "prog.s0", "pvol", 30000);
    int64_t t = 1000;
    snap_rows(c, sid, &t, 3000000);
    await_isr(0, "pvol", 3, 20000, "pvol synced before kill R");

    stop(R, SIGKILL);
    await_isr(0, "pvol", 2, 15000, "pvol ISR shrunk after kill R");
    struct timespec s1 = {1, 0};
    for (int r = 0; r < 7; r++) {
        snap_rows(c, sid, &t, 100);
        if ((rc = tsdbc_flush(c)) != 0)
            die("progress: flush: %s", ers(rc));
        nanosleep(&s1, NULL);
    }
    snap_rows(c, sid, &t, 1);
    tsdbc_close(c);

    /* Restart R with snapstallms=1000 (< progress_stall_ms=2500) to prove stall persists across abandon/retry loops. */
    penv[R] = "TSDB_REPLD_TEST=snapstallms=1000";
    start(R);
    mports[R] = th_mport;
    if (mports[R] <= 0)
        die("progress: restarted server %d reported no metrics port", R);

    char needle[128], line[4096];
    snprintf(needle, sizeof needle, "snapshot made for node %" PRIu32 ":", ids[R]);
    await_log(L, needle, 30000, "leader never made snapshot for R");
    log_line(L, needle, line, sizeof line);
    uint64_t snap_bytes = 0;
    const char *fp = strstr(line, " files, ");
    if (fp)
        snap_bytes = strtoull(fp + 8, NULL, 10);
    if (snap_bytes < (1u << 20))
        die("progress: parsed unexpected snapshot size %" PRIu64 " from log line: %s", snap_bytes, line);

    /* Verify bytes_done > 0 and bytes_total == snap_bytes and stalled == 0 in STATUS and R's /metrics, then rises. */
    static char mbuf[1 << 20];
    uint64_t st_b1 = 0, st_b2 = 0, mt_b1 = 0, mt_b2 = 0;
    int got_first = 0, got_rise = 0;
    char k_done[96], k_tot[96], k_stall[96];
    snprintf(k_done, sizeof k_done, "\ntsdb_cluster_rebuild_bytes_done{volume=\"%" PRIu32 "\"} ", vnum);
    snprintf(k_tot, sizeof k_tot, "\ntsdb_cluster_rebuild_bytes_total{volume=\"%" PRIu32 "\"} ", vnum);
    snprintf(k_stall, sizeof k_stall, "\ntsdb_cluster_rebuild_stalled{volume=\"%" PRIu32 "\"} ", vnum);

    for (uint64_t w0 = now_ms(); now_ms() - w0 < 20000 && !got_rise; usleep(150000)) {
        struct view v;
        view(0, &v);
        const struct creport_vol_progress *vp = view_find_progress(&v, ids[R], vnum);
        if (vp && vp->role == CREPORT_REBUILD_SNAP_DST && vp->bytes_done > 0) {
            if (vp->bytes_total != snap_bytes) {
                uint64_t got_t = vp->bytes_total;
                view_free(&v);
                die("progress: STATUS bytes_total=%" PRIu64 " != snapshot size %" PRIu64, got_t, snap_bytes);
            }
            if (vp->started_ms == 0 || vp->last_progress_ms < vp->started_ms) {
                uint64_t sm = vp->started_ms, lm = vp->last_progress_ms;
                view_free(&v);
                die("progress: STATUS bad timestamps started=%" PRIu64 " last=%" PRIu64, sm, lm);
            }
            if (vp->stalled != 0) {
                view_free(&v);
                die("progress: STATUS reported stalled=1 while snapshot was actively transferring");
            }
            metrics_get(mports[R], mbuf, sizeof mbuf);
            int64_t md = -1, mt = -1, ms = -1;
            if (metrics_find_i64(mbuf, k_done, &md) && metrics_find_i64(mbuf, k_tot, &mt) &&
                metrics_find_i64(mbuf, k_stall, &ms) && md > 0) {
                if ((uint64_t)mt != snap_bytes) {
                    view_free(&v);
                    die("progress: /metrics bytes_total=%" PRId64 " != snapshot size %" PRIu64, mt, snap_bytes);
                }
                if (ms != 0) {
                    view_free(&v);
                    die("progress: /metrics reported stalled=%" PRId64 " while transferring", ms);
                }
                if (!got_first) {
                    st_b1 = vp->bytes_done;
                    mt_b1 = (uint64_t)md;
                    got_first = 1;
                } else if (vp->bytes_done > st_b1 && (uint64_t)md > mt_b1) {
                    st_b2 = vp->bytes_done;
                    mt_b2 = (uint64_t)md;
                    got_rise = 1;
                }
            }
        }
        view_free(&v);
    }
    if (!got_first)
        die("progress: never saw active snapshot bytes_done > 0 in STATUS and /metrics");
    if (!got_rise)
        die("progress: bytes_done did not rise in STATUS (st_b1=%" PRIu64 ") and /metrics (mt_b1=%" PRIu64 ")", st_b1,
            mt_b1);

    /* SIGSTOP source L past BOTH snapstallms (1000 ms) AND progress_stall_ms (2500 ms): verify R abandons on the
     * stall timer yet stalled still becomes 1 in STATUS and R's /metrics across the retry loop. */
    pause_server(L, 1);
    await_log(R, "the stall timer", 6000, "R never hit snapstallms=1000 while source was SIGSTOPped");
    int got_stalled = 0;
    for (uint64_t w0 = now_ms(); now_ms() - w0 < 10000 && !got_stalled; usleep(150000)) {
        struct view v;
        view(0, &v);
        const struct creport_vol_progress *vp = view_find_progress(&v, ids[R], vnum);
        int st_ok = vp && vp->role == CREPORT_REBUILD_SNAP_DST && vp->stalled == 1;
        view_free(&v);
        if (!st_ok)
            continue;
        metrics_get(mports[R], mbuf, sizeof mbuf);
        int64_t ms = -1;
        if (metrics_find_i64(mbuf, k_stall, &ms) && ms == 1)
            got_stalled = 1;
    }
    pause_server(L, 0);
    if (!got_stalled)
        die("progress: stalled did not become 1 in STATUS and /metrics after SIGSTOPping source %d past snapstallms", L);

    /* Wait for snapshot to finish and R to rejoin ISR, then verify stalled=0 and idle (omitted or role=none). */
    await_isr(0, "pvol", 3, 60000, "pvol 3/3 ISR after snapshot resume");
    int cleared = 0;
    for (uint64_t w0 = now_ms(); now_ms() - w0 < 8000 && !cleared; usleep(150000)) {
        struct view v;
        view(0, &v);
        const struct creport_vol_progress *vp = view_find_progress(&v, ids[R], vnum);
        int st_ok = !vp || (vp->role == CREPORT_REBUILD_NONE && vp->stalled == 0);
        view_free(&v);
        if (!st_ok)
            continue;
        metrics_get(mports[R], mbuf, sizeof mbuf);
        int64_t ms = -1, nf = -1, fr = -1;
        char k_fr[96];
        snprintf(k_fr, sizeof k_fr, "\ntsdb_cluster_full_refusals_total{volume=\"%" PRIu32 "\"} ", vnum);
        if (metrics_find_i64(mbuf, k_stall, &ms) && ms == 0 &&
            metrics_find_i64(mbuf, "\ntsdb_cluster_node_full ", &nf) && nf == 0 &&
            metrics_find_i64(mbuf, k_fr, &fr) && fr == 0)
            cleared = 1;
    }
    if (!cleared)
        die("progress: rebuild state did not clear to idle / stalled=0 after snapshot completed");

    /* Part 2 (EC builds): hold settles via TSDB_SETTLE_HOLD file -> verify settle backlog counts rise & drain. */
    uint32_t saw_keys = 0;
    uint64_t saw_oldest = 0;
#ifdef TSDB_EC
    struct view uv;
    view(0, &uv);
    uint8_t cuuid[16];
    memcpy(cuuid, uv.m.uuid, 16);
    view_free(&uv);

    char holdpath[sizeof base + 32], holdenv[sizeof base + 64];
    snprintf(holdpath, sizeof holdpath, "%s/settlehold", base);
    snprintf(holdenv, sizeof holdenv, "TSDB_SETTLE_HOLD=%s", holdpath);
    FILE *hf = fopen(holdpath, "wb");
    if (!hf)
        die("progress: create %s: %s", holdpath, strerror(errno));
    fclose(hf);

    static char pxa[3][sizeof base + 256];
    for (int i = 0; i < 3; i++) {
        char sd[sizeof base + 32];
        snprintf(sd, sizeof sd, "%s/ps%d", base, i);
        chunk_store_make(sd, cuuid, ids[i]);
        penv[i] = holdenv;
        snprintf(pxa[i], sizeof pxa[i],
                 "--metrics-port auto --chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 "
                 "--merge-idle-s 1 --flush-interval-ms 200",
                 sd);
        restart_xargs(i, pxa[i]);
        mports[i] = th_mport;
    }

    uint32_t ecnum = 0;
    char etxt[256];
    for (uint64_t w0 = now_ms(); (rc = vol_add_ec(0, "pec", 0, 2, 1, &ecnum, etxt, sizeof etxt)) != 0; usleep(150000)) {
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - w0 > 30000)
            die("progress: vol_add_ec pec (2+1): %s (%s)", cluster_strerror(rc), etxt);
    }
    struct meta_volume ecv;
    for (uint64_t w0 = now_ms(); !vol_rec(0, "pec", &ecv) || !ecv.leader; usleep(100000))
        if (now_ms() - w0 > 20000)
            die("progress: no pec record with leader");
    int EL = server_of(ecv.leader);
    if (EL < 0)
        die("progress: bad pec leader %u", ecv.leader);
    for (uint32_t k = 0; k < ecv.nrep; k++) {
        int s = server_of(ecv.rep[k].node);
        if (s >= 0)
            await_open_gen(0, "pec", s, 1, 0);
    }
    await_isr(EL, "pec", 2, 20000, "pec 2/2 ISR");

    tsdbc *ec = client(EL);
    tsdb_sid esid = rep_series(ec, "pec.s0", "pec", 30000);
    const int64_t day0 = 1704067200000LL; /* 2024-01-01 */
    for (int d = 0; d < 8; d++) {
        int64_t dt = day0 + (int64_t)d * 86400000LL;
        for (int b = 0; b < 2; b++) {
            snap_rows(ec, esid, &dt, 300000);
            if ((rc = tsdbc_flush(ec)) != 0)
                die("progress: flush pec: %s", ers(rc));
        }
    }
    tsdbc_close(ec);

    /* Wait for idle merge -> >= 2 keys eligible & held by TSDB_SETTLE_HOLD -> backlog >= 2 in STATUS and /metrics. */
    char k_skeys[96], k_sold[96];
    snprintf(k_skeys, sizeof k_skeys, "\ntsdb_settle_backlog_keys{volume=\"%" PRIu32 "\"} ", ecnum);
    snprintf(k_sold, sizeof k_sold, "\ntsdb_settle_backlog_oldest_seconds{volume=\"%" PRIu32 "\"} ", ecnum);
    int got_backlog = 0;
    for (uint64_t w0 = now_ms(); now_ms() - w0 < 30000 && !got_backlog; usleep(200000)) {
        struct view v;
        view(0, &v);
        int rl = server_of(v.st.leader);
        if (rl >= 0 && rl != 0) {
            view_free(&v);
            view(rl, &v);
        }
        const struct creport_vol_progress *vp = view_find_progress(&v, ids[EL], ecnum);
        uint32_t sk = vp ? vp->settle_keys_waiting : 0;
        uint64_t so = vp ? vp->settle_oldest_wait_s : 0;
        view_free(&v);
        if (sk < 2 || so == 0)
            continue;
        metrics_get(mports[EL], mbuf, sizeof mbuf);
        int64_t mk = -1, mo = -1;
        if (metrics_find_i64(mbuf, k_skeys, &mk) && metrics_find_i64(mbuf, k_sold, &mo) && mk >= 2 && mo > 0) {
            saw_keys = sk;
            saw_oldest = so;
            got_backlog = 1;
        }
    }
    if (!got_backlog)
        die("progress: settle backlog did not reach >= 2 keys (oldest > 0) in STATUS and /metrics while held");

    /* Release settle hold and verify backlog drains back to 0. */
    unlink(holdpath);
    int drained = 0;
    for (uint64_t w0 = now_ms(); now_ms() - w0 < 60000 && !drained; usleep(250000)) {
        struct view v;
        view(0, &v);
        int rl = server_of(v.st.leader);
        if (rl >= 0 && rl != 0) {
            view_free(&v);
            view(rl, &v);
        }
        const struct creport_vol_progress *vp = view_find_progress(&v, ids[EL], ecnum);
        int st_zero = !vp || (vp->settle_keys_waiting == 0 && vp->settle_oldest_wait_s == 0);
        view_free(&v);
        if (!st_zero)
            continue;
        metrics_get(mports[EL], mbuf, sizeof mbuf);
        int64_t mk = -1, mo = -1;
        if (metrics_find_i64(mbuf, k_skeys, &mk) && metrics_find_i64(mbuf, k_sold, &mo) && mk == 0 && mo == 0)
            drained = 1;
    }
    if (!drained)
        die("progress: settle backlog did not drain to 0 after releasing settle hold");

    /* End-to-end stripe-fill progress on a storage-only node (server 3 does not hold a log replica of pec). */
    epoll_after_two = 1;
    envs[3] = "progress_stall_ms=2500";
    xargs[3] = "--metrics-port auto";
    start(3);
    mports[3] = th_mport;
    if (mports[3] <= 0)
        die("progress: server 3 reported no metrics port");
    node_add(0, 3);
    unsigned four = 4;
    await_view(0, p_n_placeable, &four, "4 members UP before stripe-fill progress");
    char sd3[sizeof base + 32];
    static char pxa3[sizeof base + 256];
    snprintf(sd3, sizeof sd3, "%s/ps3", base);
    chunk_store_make(sd3, cuuid, ids[3]);
    snprintf(pxa3, sizeof pxa3, "--metrics-port auto --chunk-dir %s", sd3);
    restart_xargs(3, pxa3);
    mports[3] = th_mport;
    await_view(0, p_n_placeable, &four, "server 3 UP with chunk store");

    char p0addr[META_ADDR_MAX], mvargs[PATH_MAX * 2 + 256], mvout[4096];
    peer_of(0, p0addr, sizeof p0addr);
    snprintf(mvargs, sizeof mvargs, "cluster volume move %s %" PRIu32 " --pos 0 --to %" PRIu32 " --secret-file %s",
             p0addr, ecnum, ids[3], secret_path);
    if (cli_run(mvargs, NULL, mvout, sizeof mvout) != 0)
        die("progress: volume move --pos 0 --to %" PRIu32 " failed: %s", ids[3], mvout);

    char k_fdone[96], k_ftot[96];
    snprintf(k_fdone, sizeof k_fdone, "\ntsdb_cluster_rebuild_bytes_done{volume=\"%" PRIu32 "\"} ", ecnum);
    snprintf(k_ftot, sizeof k_ftot, "\ntsdb_cluster_rebuild_bytes_total{volume=\"%" PRIu32 "\"} ", ecnum);
    uint64_t fill_st_done = 0, fill_st_tot = 0, fill_mt_done = 0, fill_mt_tot = 0;
    for (uint64_t w0 = now_ms(); now_ms() - w0 < 30000; usleep(50000)) {
        struct view v;
        view(0, &v);
        int rl = server_of(v.st.leader);
        if (rl >= 0 && rl != 0) {
            view_free(&v);
            view(rl, &v);
        }
        const struct creport_vol_progress *vp = view_find_progress(&v, ids[3], ecnum);
        if (vp && vp->role == CREPORT_REBUILD_FILL && vp->bytes_total > 0) {
            if (vp->bytes_total > fill_st_tot)
                fill_st_tot = vp->bytes_total;
            if (vp->bytes_done > fill_st_done)
                fill_st_done = vp->bytes_done;
        }
        view_free(&v);

        metrics_get(mports[3], mbuf, sizeof mbuf);
        int64_t md = -1, mt = -1;
        if (metrics_find_i64(mbuf, k_fdone, &md) && metrics_find_i64(mbuf, k_ftot, &mt) && mt > 0) {
            if ((uint64_t)mt > fill_mt_tot)
                fill_mt_tot = (uint64_t)mt;
            if (md > 0 && (uint64_t)md > fill_mt_done)
                fill_mt_done = (uint64_t)md;
        }
        if (fill_st_done > 0 && fill_st_tot > 0 && fill_mt_done > 0 && fill_mt_tot > 0)
            break;
        struct meta_volume cur = {0};
        if (vol_rec(0, "pec", &cur) && cur.stripe[0] == ids[3] && cur.stripe_pos[0].state == META_STRIPE_WHOLE)
            break;
    }
    if (fill_st_done == 0 || fill_st_tot == 0 || fill_mt_done == 0 || fill_mt_tot == 0)
        die("progress: stripe fill on storage-only node 3 not observed with bytes_done/total > 0 "
            "(STATUS %" PRIu64 "/%" PRIu64 ", metrics %" PRIu64 "/%" PRIu64 ")",
            fill_st_done, fill_st_tot, fill_mt_done, fill_mt_tot);

    /* Wait for pos 0 to reach STRIPE_WHOLE and verify fill progress clears in STATUS and /metrics. */
    for (uint64_t w0 = now_ms();; usleep(100000)) {
        struct meta_volume cur = {0};
        if (vol_rec(0, "pec", &cur) && cur.stripe[0] == ids[3] && cur.stripe_pos[0].state == META_STRIPE_WHOLE)
            break;
        if (now_ms() - w0 > 45000)
            die("progress: pec pos 0 on node %" PRIu32 " did not reach STRIPE_WHOLE", ids[3]);
    }
    int fill_cleared = 0;
    for (uint64_t w0 = now_ms(); now_ms() - w0 < 15000 && !fill_cleared; usleep(150000)) {
        struct view v;
        view(0, &v);
        int rl = server_of(v.st.leader);
        if (rl >= 0 && rl != 0) {
            view_free(&v);
            view(rl, &v);
        }
        const struct creport_vol_progress *vp = view_find_progress(&v, ids[3], ecnum);
        int st_ok = !vp || vp->role == CREPORT_REBUILD_NONE;
        view_free(&v);
        if (!st_ok)
            continue;
        metrics_get(mports[3], mbuf, sizeof mbuf);
        int64_t md = -1;
        if (!metrics_find_i64(mbuf, k_fdone, &md))
            fill_cleared = 1;
    }
    if (!fill_cleared)
        die("progress: stripe fill progress did not clear on storage-only node 3 after STRIPE_WHOLE");
    epoll_after_two = 0;
#endif

    stop_all();
    printf("  progress: snapshot bytes_done rose %" PRIu64 "->%" PRIu64 " / %" PRIu64
           " (metrics %" PRIu64 "->%" PRIu64 "), SIGSTOP stalled=1->0, settle backlog %" PRIu32
           " keys (oldest %" PRIu64 "s) -> 0\n",
           st_b1, st_b2, snap_bytes, mt_b1, mt_b2, saw_keys, saw_oldest);
}

/* Atomically writes <state-dir>/fillpct for server i (used with TSDB_CLUSTER_TEST fill_pct_file=1). */
static void fillpct_set(int i, int pct)
{
    char dir[PATH_MAX + 80], tmp[PATH_MAX + 140], dst[PATH_MAX + 128];
    server_dir(i, dir, sizeof dir);
    snprintf(tmp, sizeof tmp, "%s/state/fillpct.tmp", dir);
    snprintf(dst, sizeof dst, "%s/state/fillpct", dir);
    FILE *f = fopen(tmp, "w");
    if (!f)
        die("fopen %s: %s", tmp, strerror(errno));
    fprintf(f, "%d\n", pct);
    fclose(f);
    if (rename(tmp, dst) != 0)
        die("rename %s -> %s: %s", tmp, dst, strerror(errno));
}

struct full_retry_arg {
    int port;
    tsdb_sid sid;
    int64_t ts;
    float val;
    int rc;
    int done;
};

static void *full_retry_thread(void *p)
{
    struct full_retry_arg *a = p;
    tsdbc *c = NULL;
    if (tsdbc_connect("127.0.0.1", a->port, &c) != 0) {
        a->rc = TSDB_ERR_IO;
        __atomic_store_n(&a->done, 1, __ATOMIC_RELEASE);
        return NULL;
    }
    tsdbc_set_retry(c, 15000);
    a->rc = tsdbc_insert_series(c, a->sid, &a->ts, &a->val, 1);
    tsdbc_close(c);
    __atomic_store_n(&a->done, 1, __ATOMIC_RELEASE);
    return NULL;
}

struct full_scan_ctx {
    int64_t *ts;
    float *vals;
    size_t n, cap;
};

static int full_scan_cb(void *arg, const int64_t *ts, const float *v, size_t n)
{
    struct full_scan_ctx *s = arg;
    if (s->n + n > s->cap) {
        size_t nc = s->cap ? s->cap * 2 : 256;
        while (nc < s->n + n)
            nc *= 2;
        int64_t *nt = realloc(s->ts, nc * sizeof *nt);
        float *nv = realloc(s->vals, nc * sizeof *nv);
        if (!nt || !nv) {
            free(nt);
            free(nv);
            return TSDB_ERR_NOMEM;
        }
        s->ts = nt;
        s->vals = nv;
        s->cap = nc;
    }
    memcpy(s->ts + s->n, ts, n * sizeof *ts);
    memcpy(s->vals + s->n, v, n * sizeof *v);
    s->n += n;
    return 0;
}

static void full_check_unavail(tsdbc *c, const char *what)
{
    tsdb_unavail u[4];
    unsigned nu = 0;
    if (tsdbc_unavailable(c, u, 4, &nu) != 0 || nu < 1)
        die("full: %s refused without UNAVAILABLE body (%u entries)", what, nu);
    if (u[0].reason != TSDB_WHY_FULL)
        die("full: %s refused with reason %u, expected TSDB_WHY_FULL (%u)", what, u[0].reason,
            (unsigned)TSDB_WHY_FULL);
    if (u[0].retry_after_ms < 800 || u[0].retry_after_ms > 1200)
        die("full: %s retry_after_ms %u outside 1000 ms +-20%% [800, 1200]", what, u[0].retry_after_ms);
}

/* full (r9-full; E30, D17): 3-node cluster (young_high_pct 90). Raising fill_pct=92 on an ISR replica makes small
 * writes, large writes, replaces and deletes return UNAVAILABLE TSDB_WHY_FULL (retry_after ~1000 ms) within 2 s;
 * hysteresis keeps FULL at 89 and 88 and clears below 88 (at 87); a retrying C client succeeds once fill drops to 87;
 * leader-self FULL also refuses and clears; jepsen-style check verifies every acknowledged row is present and ZERO
 * refused rows are present (kills mutant fullafteradmit). */
static void scen_full(void)
{
    scenario("full");
    for (int i = 0; i < 3; i++) {
        envs[i] = "fill_pct_file=1";
        start(i);
        fillpct_set(i, 50);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num = 0;
    int rc;
    if ((rc = vol_add(0, "fl", 3, &num)) != 0 || num != 1)
        die("full: volume add fl: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "fl", i, 1, 0);
    struct meta_volume v = {0};
    if (!vol_rec(0, "fl", &v))
        die("full: no record of fl");
    int L = server_of(v.leader);
    int R = (L + 1) % 3;
    tsdbc *c = client(L);
    tsdbc_set_retry(c, 0);
    tsdb_sid id = rep_series(c, "fl.s1", "fl", 30000);
    await_isr(0, "fl", 3, 10000, "all 3 replicas in ISR");

    int64_t ack_ts[256], ref_ts[256];
    size_t n_ack = 0, n_ref = 0;
    /* Baseline small writes succeed. */
    for (int k = 0; k < 10; k++) {
        int64_t ts = 1000 + k;
        float val = (float)(10 + k);
        if ((rc = tsdbc_insert_series(c, id, &ts, &val, 1)) != 0)
            die("full: baseline write %d failed: %s", k, ers(rc));
        ack_ts[n_ack++] = ts;
    }

    /* Raise fill_pct=92 (>= young_high_pct 90) on ISR replica R: writes must get TSDB_WHY_FULL within 2 s. */
    fillpct_set(R, 92);
    uint64_t t_raise = now_ms();
    int saw_full = 0;
    for (int k = 0; now_ms() - t_raise < 2000; k++) {
        int64_t ts = 2000 + k;
        float val = 2.0f;
        rc = tsdbc_insert_series(c, id, &ts, &val, 1);
        if (rc == TSDB_ERR_UNAVAILABLE) {
            full_check_unavail(c, "small probe after fill_pct=92");
            if (n_ref < sizeof ref_ts / sizeof ref_ts[0])
                ref_ts[n_ref++] = ts;
            saw_full = 1;
            break;
        }
        if (rc != 0)
            die("full: unexpected error waiting for FULL: %s", ers(rc));
        if (n_ack < sizeof ack_ts / sizeof ack_ts[0])
            ack_ts[n_ack++] = ts;
        usleep(50000);
    }
    if (!saw_full)
        die("full: writes did not return UNAVAILABLE TSDB_WHY_FULL within 2 s of fill_pct=92 on ISR replica %d", R);
    uint64_t detect_ms = now_ms() - t_raise;

    /* Small insert refused with TSDB_WHY_FULL. */
    {
        int64_t ts[5] = {3000, 3001, 3002, 3003, 3004};
        float fv[5] = {3.0f, 3.1f, 3.2f, 3.3f, 3.4f};
        rc = tsdbc_insert_series(c, id, ts, fv, 5);
        if (rc != TSDB_ERR_UNAVAILABLE)
            die("full: small batch while FULL returned %s, expected UNAVAILABLE", ers(rc));
        full_check_unavail(c, "small batch");
        for (int k = 0; k < 5; k++)
            ref_ts[n_ref++] = ts[k];
    }

    /* Large insert (>= wal_max_batch_rows = 65536) refused before lw_enter with TSDB_WHY_FULL. */
    const size_t large_n = 70000;
    const int64_t large_lo = 100000, large_hi = 100000 + (int64_t)large_n - 1;
    {
        int64_t *lts = malloc(large_n * sizeof *lts);
        float *lv = malloc(large_n * sizeof *lv);
        if (!lts || !lv)
            die("full: malloc large batch");
        for (size_t k = 0; k < large_n; k++) {
            lts[k] = large_lo + (int64_t)k;
            lv[k] = 7.0f;
        }
        rc = tsdbc_insert_series(c, id, lts, lv, large_n);
        free(lts);
        free(lv);
        if (rc != TSDB_ERR_UNAVAILABLE)
            die("full: large insert (%zu rows) while FULL returned %s, expected UNAVAILABLE", large_n, ers(rc));
        full_check_unavail(c, "large insert");
    }

    /* Replace range and delete range refused before lw_enter with TSDB_WHY_FULL. */
    {
        int64_t rts = 1000;
        float rval = 999.0f;
        tsdb_values rv_col = {.type = TSDB_FLOAT32, .values = &rval, .valid = NULL};
        rc = tsdbc_replace_range(c, id, 1000, 1005, &rts, &rv_col, 1);
        if (rc != TSDB_ERR_UNAVAILABLE)
            die("full: replace_range while FULL returned %s, expected UNAVAILABLE", ers(rc));
        full_check_unavail(c, "replace_range");

        rc = tsdbc_delete_range(c, id, 1000, 1005);
        if (rc != TSDB_ERR_UNAVAILABLE)
            die("full: delete_range while FULL returned %s, expected UNAVAILABLE", ers(rc));
        full_check_unavail(c, "delete_range");

        /* Non-row housekeeping/metadata markers (MK_SERIES, MK_RETENTION) still proceed during FULL. */
        tsdb_sid id2 = 0;
        if ((rc = tsdbc_series_create(c, "fl.s2", TSDB_FLOAT32, "fl", &id2)) != 0 || !id2)
            die("full: series_create while FULL failed: %s", ers(rc));
        if ((rc = tsdbc_set_retention(c, id2, 86400000)) != 0)
            die("full: set_retention while FULL failed: %s", ers(rc));
    }

    /* Verify STATUS exposes per-server node.full=1 on R and vol.1.full=1 + vol.1.full_refusals >= 5 on L. */
    {
        tsdbc *cr = client(R);
        char *st = NULL;
        if (tsdbc_status(cr, &st) != 0 || !st || !strstr(st, "node.full=1\n"))
            die("full: STATUS on FULL replica %d missing node.full=1:\n%s", R, st ? st : "(null)");
        free(st);
        tsdbc_close(cr);

        st = NULL;
        if (tsdbc_status(c, &st) != 0 || !st || !strstr(st, "vol.1.full=1\n"))
            die("full: STATUS on leader %d missing vol.1.full=1:\n%s", L, st ? st : "(null)");
        const char *rp = strstr(st, "vol.1.full_refusals=");
        if (!rp || strtoull(rp + 20, NULL, 10) < 5)
            die("full: STATUS on leader %d vol.1.full_refusals < 5:\n%s", L, st);
        free(st);
    }

    /* Hysteresis: fill_pct=89 and fill_pct=88 (>= young_high_pct - 2 = 88) MUST stay FULL. */
    for (int hp = 89; hp >= 88; hp--) {
        fillpct_set(R, hp);
        usleep(400000);
        int64_t ts = 3100 + (89 - hp);
        float fv = 4.0f;
        rc = tsdbc_insert_series(c, id, &ts, &fv, 1);
        if (rc != TSDB_ERR_UNAVAILABLE)
            die("full: hysteresis failed at fill_pct=%d (young_high_pct=90): write returned %s", hp, ers(rc));
        full_check_unavail(c, "hysteresis check");
        ref_ts[n_ref++] = ts;
    }

    /* C client with retry blocks on TSDB_WHY_FULL and succeeds automatically once fill_pct drops to 87 (< 90 - 2). */
    struct full_retry_arg ra = {.port = cports[L], .sid = id, .ts = 4000, .val = 42.0f};
    pthread_t rth;
    if (pthread_create(&rth, NULL, full_retry_thread, &ra) != 0)
        die("full: pthread_create");
    usleep(400000);
    if (__atomic_load_n(&ra.done, __ATOMIC_ACQUIRE))
        die("full: retrying client finished while replica was still FULL (rc %d)", ra.rc);
    fillpct_set(R, 87);
    uint64_t t_drop = now_ms();
    while (!__atomic_load_n(&ra.done, __ATOMIC_ACQUIRE) && now_ms() - t_drop < 10000)
        usleep(50000);
    if (!__atomic_load_n(&ra.done, __ATOMIC_ACQUIRE))
        die("full: retrying client did not complete within 10 s after fill_pct dropped to 87");
    pthread_join(rth, NULL);
    if (ra.rc != 0)
        die("full: retrying client failed after fill_pct=87: %s", ers(ra.rc));
    ack_ts[n_ack++] = ra.ts;

    /* Leader-self FULL: fill_pct=91 on leader L refuses writes with TSDB_WHY_FULL, clearing at 87. */
    fillpct_set(L, 91);
    uint64_t t_lfull = now_ms();
    int saw_lfull = 0;
    for (int k = 0; now_ms() - t_lfull < 2000; k++) {
        int64_t ts = 5000 + k;
        float fv = 5.0f;
        rc = tsdbc_insert_series(c, id, &ts, &fv, 1);
        if (rc == TSDB_ERR_UNAVAILABLE) {
            full_check_unavail(c, "leader-self FULL");
            if (n_ref < sizeof ref_ts / sizeof ref_ts[0])
                ref_ts[n_ref++] = ts;
            saw_lfull = 1;
            break;
        }
        if (rc != 0)
            die("full: unexpected error waiting for leader-self FULL: %s", ers(rc));
        if (n_ack < sizeof ack_ts / sizeof ack_ts[0])
            ack_ts[n_ack++] = ts;
        usleep(50000);
    }
    if (!saw_lfull)
        die("full: writes did not return UNAVAILABLE TSDB_WHY_FULL within 2 s of leader-self fill_pct=91");
    fillpct_set(L, 87);
    uint64_t t_lclr = now_ms();
    int cleared_l = 0;
    for (int k = 0; now_ms() - t_lclr < 2000; k++) {
        int64_t ts = 6000 + k;
        float fv = 6.0f;
        rc = tsdbc_insert_series(c, id, &ts, &fv, 1);
        if (rc == 0) {
            if (n_ack < sizeof ack_ts / sizeof ack_ts[0])
                ack_ts[n_ack++] = ts;
            cleared_l = 1;
            break;
        }
        if (rc != TSDB_ERR_UNAVAILABLE)
            die("full: unexpected error waiting for leader-self FULL clear: %s", ers(rc));
        if (n_ref < sizeof ref_ts / sizeof ref_ts[0])
            ref_ts[n_ref++] = ts;
        usleep(50000);
    }
    if (!cleared_l)
        die("full: leader-self FULL did not clear within 2 s of fill_pct=87");

    /* Jepsen-style invariant check: EVERY acknowledged row must be present AND ZERO refused rows may appear! */
    struct full_scan_ctx sc = {0};
    if ((rc = tsdbc_query_raw(c, id, 0, INT64_MAX / 2, full_scan_cb, &sc)) != 0)
        die("full: query_raw failed: %s", ers(rc));
    for (size_t i = 0; i < sc.n; i++) {
        int64_t t = sc.ts[i];
        if (t >= large_lo && t <= large_hi)
            die("full: refused row ts %" PRId64 " (from large insert) appeared in the database", t);
        for (size_t j = 0; j < n_ref; j++)
            if (t == ref_ts[j])
                die("full: refused row ts %" PRId64 " appeared in the database", t);
        if (t == 1000 && sc.vals[i] == 999.0f)
            die("full: refused row ts 1000 replace_range value 999 appeared in the database");
    }
    for (size_t j = 0; j < n_ack; j++) {
        int found = 0;
        for (size_t i = 0; i < sc.n; i++)
            if (sc.ts[i] == ack_ts[j]) {
                found = 1;
                break;
            }
        if (!found)
            die("full: acknowledged row ts %" PRId64 " is missing from the database", ack_ts[j]);
    }
    if (sc.n != n_ack)
        die("full: row count %zu != acknowledged %zu", sc.n, n_ack);
    free(sc.ts);
    free(sc.vals);
    tsdbc_close(c);
    stop_all();
    for (int i = 0; i < 3; i++)
        envs[i] = NULL;
    printf("  full: replica fill_pct=92 refused small/large/replace/delete with TSDB_WHY_FULL in %" PRIu64
           " ms; hysteresis held at 89/88; retrying client succeeded at 87; leader-self FULL verified; %zu acked "
           "present, 0 of %zu+%zu refused present\n",
           detect_ms, n_ack, n_ref, large_n);
}

/* fullnonisr (r9-full; E30, D17): a non-ISR replica with fill_pct=95 pauses its own catch-up and logs once, while
 * small and large writes to the volume continue succeeding on the healthy ISR; once fill_pct drops to 87, it resumes
 * catch-up and rejoins the ISR. */
static void scen_fullnonisr(void)
{
    scenario("fullnonisr");
    for (int i = 0; i < 3; i++) {
        envs[i] = "fill_pct_file=1";
        start(i);
        fillpct_set(i, 50);
    }
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");
    uint32_t num = 0;
    int rc;
    if ((rc = vol_add(0, "fni", 3, &num)) != 0 || num != 1)
        die("fullnonisr: volume add fni: %s, number %" PRIu32, cluster_strerror(rc), num);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "fni", i, 1, 0);
    struct meta_volume v = {0};
    if (!vol_rec(0, "fni", &v))
        die("fullnonisr: no record of fni");
    int L = server_of(v.leader);
    int R = (L + 1) % 3;
    tsdbc *c = client(L);
    tsdbc_set_retry(c, 0);
    tsdb_sid id = rep_series(c, "fni.s1", "fni", 30000);
    await_isr(0, "fni", 3, 10000, "all 3 replicas in ISR");

    uint64_t expected_rows = 0;
    for (int k = 0; k < 10; k++) {
        int64_t ts = 1000 + k;
        float fv = 1.0f;
        if ((rc = tsdbc_insert_series(c, id, &ts, &fv, 1)) != 0)
            die("fullnonisr: initial write %d: %s", k, ers(rc));
        expected_rows++;
    }

    /* Stop replica R until it drops out of the ISR, then write more rows so it lags behind. */
    stop(R, SIGKILL);
    for (int k = 0; k < 20; k++) {
        int64_t ts = 2000 + k;
        float fv = 2.0f;
        if ((rc = tsdbc_insert_series(c, id, &ts, &fv, 1)) != 0)
            die("fullnonisr: write %d while R stopped: %s", k, ers(rc));
        expected_rows++;
    }
    await_isr(L, "fni", 2, 15000, "stopped replica R dropped from ISR");

    /* Restart non-ISR replica R with fill_pct=95: it must pause its own catch-up and log once. */
    fillpct_set(R, 95);
    start(R);
    await_log(R, "non-ISR replica is FULL", 15000, "non-ISR replica R logged catch-up pause for FULL");

    /* Writes (small and large) MUST continue succeeding on the healthy 2-member ISR while R is FULL and non-ISR! */
    for (int k = 0; k < 20; k++) {
        int64_t ts = 3000 + k;
        float fv = 3.0f;
        if ((rc = tsdbc_insert_series(c, id, &ts, &fv, 1)) != 0)
            die("fullnonisr: small write %d failed while non-ISR replica R was FULL: %s", k, ers(rc));
        expected_rows++;
    }
    const size_t large_n = 70000;
    {
        int64_t *lts = malloc(large_n * sizeof *lts);
        float *lv = malloc(large_n * sizeof *lv);
        if (!lts || !lv)
            die("fullnonisr: malloc large batch");
        for (size_t k = 0; k < large_n; k++) {
            lts[k] = 100000 + (int64_t)k;
            lv[k] = 7.0f;
        }
        rc = tsdbc_insert_series(c, id, lts, lv, large_n);
        free(lts);
        free(lv);
        if (rc != 0)
            die("fullnonisr: large write failed while non-ISR replica R was FULL: %s", ers(rc));
        expected_rows += large_n;
    }

    /* R must remain out of the ISR while FULL (catch-up paused) AND must not have staged/spilled the large write's
     * part files onto its FULL disk (E30: bulk_out skips non-ISR FULL peers and bin_open refuses them). */
    usleep(1000000);
    if (!vol_rec(L, "fni", &v) || v.nisr != 2)
        die("fullnonisr: expected ISR size 2 while non-ISR replica R is FULL, got %" PRIu32, v.nisr);
    {
        char sdir[PATH_MAX + 80], vdir[PATH_MAX + 128];
        server_dir(R, sdir, sizeof sdir);
        snprintf(vdir, sizeof vdir, "%s/v1", sdir);
        DIR *d = opendir(vdir);
        if (!d)
            die("fullnonisr: opendir %s: %s", vdir, strerror(errno));
        struct dirent *de;
        while ((de = readdir(d)) != NULL) {
            if (!strncmp(de->d_name, "stage_", 6) || !strncmp(de->d_name, "spill_", 6) ||
                !strncmp(de->d_name, "tmp_", 4))
                die("fullnonisr: FULL non-ISR replica %d staged/spilled bulk file %s during large write", R, de->d_name);
        }
        closedir(d);
    }

    /* Drop fill_pct=87 on R: it must resume catch-up, log resume, and rejoin the 3-member ISR. */
    fillpct_set(R, 87);
    await_log(R, "FULL cleared; resuming catch-up", 10000, "non-ISR replica R logged resume");
    await_isr(L, "fni", 3, 25000, "replica R caught up and rejoined ISR after fill dropped to 87");

    if ((uint64_t)rows_of(c, id) != expected_rows)
        die("fullnonisr: leader has %d rows, expected %" PRIu64, rows_of(c, id), expected_rows);
    tsdbc_close(c);
    stop_all();
    for (int i = 0; i < 3; i++)
        envs[i] = NULL;
    printf("  fullnonisr: non-ISR replica %d at fill_pct=95 paused catch-up while small+large writes (%" PRIu64
           " rows) succeeded on healthy ISR; resumed and rejoined ISR at fill_pct=87\n",
           R, expected_rows);
}

/* Helpers for scen_youngscrub: find first .part file in <dir>/v<vol> and flip one byte inside its granule payload. */
static int find_first_part(const char *vdir, char *out_name, size_t cap)
{
    DIR *d = opendir(vdir);
    if (!d)
        return 0;
    struct dirent *de;
    int found = 0;
    while ((de = readdir(d)) != NULL) {
        size_t len = strlen(de->d_name);
        if (de->d_name[0] == 'p' && len > 5 && strcmp(de->d_name + len - 5, ".part") == 0) {
            snprintf(out_name, cap, "%s", de->d_name);
            found = 1;
            break;
        }
    }
    closedir(d);
    return found;
}

static void flip_part_payload_byte(const char *vdir, const char *pname)
{
    char path[PATH_MAX + 256];
    snprintf(path, sizeof path, "%s/%s", vdir, pname);
    int fd = open(path, O_RDWR | O_CLOEXEC);
    if (fd < 0)
        die("youngscrub: open %s: %s", path, strerror(errno));
    struct stat st;
    if (fstat(fd, &st) != 0 || st.st_size < 160)
        die("youngscrub: part %s too small (%lld)", path, (long long)st.st_size);
    /* Offset 64 lies right after the 48-byte part_header, strictly inside granule 0's payload. */
    off_t off = 64;
    uint8_t b = 0;
    if (pread(fd, &b, 1, off) != 1)
        die("youngscrub: pread %s: %s", path, strerror(errno));
    b ^= 0x5au;
    if (pwrite(fd, &b, 1, off) != 1)
        die("youngscrub: pwrite %s: %s", path, strerror(errno));
    close(fd);
}

static int vol_health_in_status(int leader_srv, uint32_t node_id, uint32_t vol)
{
    struct view vw = {0};
    view(leader_srv, &vw);
    int res = -1;
    for (uint32_t k = 0; k < vw.st.nheard; k++) {
        if (vw.st.heard[k].id != node_id)
            continue;
        for (uint32_t j = 0; j < vw.st.heard[k].nvols; j++) {
            if (vw.st.heard[k].vols[j].v.volume == vol) {
                res = (int)vw.st.heard[k].vols[j].v.health;
                break;
            }
        }
    }
    view_free(&vw);
    return res;
}

static int node_in_isr(int srv, const char *vname, uint32_t node_id, uint32_t *nisr_out)
{
    struct meta_volume v = {0};
    if (!vol_rec(srv, vname, &v))
        return -1;
    if (nisr_out)
        *nisr_out = v.nisr;
    for (uint32_t i = 0; i < v.nisr; i++)
        if (v.isr[i] == node_id)
            return 1;
    return 0;
}

/* youngscrub (R12, r12-young; D4, D7, D10):
 * Part A (3 replicas, min_isr = 2):
 *   - Flip a granule payload byte on follower R1 -> scrubd detects damage, reports CL_HEALTH_DAMAGED in HBS_VOLUMES,
 *     /metrics (tsdb_cluster_volume_health=3, tsdb_young_scrub_*), and TOPOLOGY (DEGRADED/SUSPECT).
 *   - R1 asks to leave the ISR through the core; ISR drops 3 -> 2; writes continue on leader L.
 *   - v1/SCRUB persists damaged state; restarting R1 re-scrubs the damaged part first and stays DAMAGED & out of ISR.
 *   - Flip a granule payload byte on leader L -> leader reports CL_HEALTH_DAMAGED and keeps leading cleanly.
 * Part B (3 replicas, min_isr = 3):
 *   - Flip a granule payload byte on follower R1 -> reports CL_HEALTH_DAMAGED, stays in ISR (nisr == 3), logs clearly,
 *     and exports tsdb_young_scrub_min_isr_held{volume="1"} == 1 (catches mutant youngleavebelow!). */
static void scen_youngscrub(void)
{
    scenario("youngscrub");

    /* ---- Part A: 3 replicas, min_isr = 2 (disable r12-heal auto-reset to test r12-young detection in isolation) ---- */
    int mports[3] = {0};
    init_min_isr = 2;
    for (int i = 0; i < 3; i++) {
        envs[i] = "heal_off=1";
        penv[i] = "TSDB_SCRUB_TEST=interval_ms=50";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
        if (mports[i] <= 0)
            die("youngscrub: server %d reported no metrics port", i);
    }
    init_cluster(0, 600);
    init_min_isr = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");

    uint32_t vnum = 0;
    int rc;
    if ((rc = vol_add(0, "ys", 3, &vnum)) != 0 || vnum != 1)
        die("youngscrub: vol_add ys: %s num=%" PRIu32, cluster_strerror(rc), vnum);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "ys", i, 1, 0);
    struct meta_volume v = {0};
    if (!vol_rec(0, "ys", &v) || v.min_isr != 2)
        die("youngscrub: no record of ys or min_isr=%" PRIu32 " != 2", v.min_isr);
    int L = server_of(v.leader);
    int R1 = (L + 1) % 3;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, "ys.s0", "ys", 30000);
    await_isr(L, "ys", 3, 15000, "ys 3/3 ISR");

    /* Large insert (> 65536 rows) produces a committed .part file immediately on all 3 replicas. */
    const size_t nbatch = 70000;
    int64_t *ts = malloc(nbatch * sizeof *ts);
    float *vals = malloc(nbatch * sizeof *vals);
    if (!ts || !vals)
        die("youngscrub: malloc");
    for (size_t k = 0; k < nbatch; k++) {
        ts[k] = 100000 + (int64_t)k * 10;
        vals[k] = (float)(k % 100) * 0.5f;
    }
    if ((rc = tsdbc_insert_series(c, id, ts, vals, nbatch)) != 0)
        die("youngscrub: large insert: %s", ers(rc));

    /* Wait for R1 to hold a .part file and complete at least one clean scrub pass. */
    char sdir[PATH_MAX + 80], vdir[PATH_MAX + 128], pname[128] = "";
    server_dir(R1, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    uint64_t t0 = now_ms();
    while (!find_first_part(vdir, pname, sizeof pname)) {
        if (now_ms() - t0 > 15000)
            die("youngscrub: follower %d never received a .part file in %s", R1, vdir);
        usleep(50000);
    }

    char mbuf[65536];
    int scrubbed_clean = 0;
    for (t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        metrics_get(mports[R1], mbuf, sizeof mbuf);
        int64_t parts = 0, dmg = -1, hlth = -1;
        if (metrics_find_i64(mbuf, "\ntsdb_young_scrub_parts_total{volume=\"1\"} ", &parts) && parts >= 1 &&
            metrics_find_i64(mbuf, "\ntsdb_young_scrub_damaged_total{volume=\"1\"} ", &dmg) && dmg == 0 &&
            metrics_find_i64(mbuf, "\ntsdb_cluster_volume_health{volume=\"1\"} ", &hlth) && hlth == CL_HEALTH_OK) {
            scrubbed_clean = 1;
            break;
        }
    }
    if (!scrubbed_clean)
        die("youngscrub: follower %d never finished a clean scrub pass", R1);

    /* Flip a granule payload byte on follower R1. */
    flip_part_payload_byte(vdir, pname);

    /* 1. R1 reports CL_HEALTH_DAMAGED in HBS_VOLUMES (via Raft leader STATUS) and leaves the ISR (3 -> 2). */
    int saw_hb_dmg = 0, left_isr = 0;
    for (t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        if (vol_health_in_status(0, ids[R1], 1) == CL_HEALTH_DAMAGED)
            saw_hb_dmg = 1;
        uint32_t nisr = 0;
        int in = node_in_isr(L, "ys", ids[R1], &nisr);
        if (in == 0 && nisr == 2)
            left_isr = 1;
        if (saw_hb_dmg && left_isr)
            break;
    }
    if (!saw_hb_dmg)
        die("youngscrub: follower %d did not report CL_HEALTH_DAMAGED in HBS_VOLUMES", R1);
    if (!left_isr)
        die("youngscrub: damaged follower %d did not leave ISR (min_isr=2)", R1);

    /* 2. Check TOPOLOGY on R1 reports DEGRADED/SUSPECT for R1's entry, and /metrics reports all young scrub families. */
    tsdbc *cr1 = client(R1);
    tsdbc_topo *topo = NULL;
    if (tsdbc_topology(cr1, &topo) != 0 || !topo)
        die("youngscrub: TOPOLOGY on R1 failed");
    int saw_topo_deg = 0;
    for (size_t i = 0; i < topo->nvols; i++) {
        if (topo->vols[i].vol == 1 && topo->vols[i].owner == ids[R1]) {
            if (topo->vols[i].health == TSDB_HEALTH_DEGRADED && topo->vols[i].reason == TSDB_WHY_SUSPECT)
                saw_topo_deg = 1;
        }
    }
    tsdbc_topology_free(topo);
    tsdbc_close(cr1);
    if (!saw_topo_deg)
        die("youngscrub: TOPOLOGY on R1 did not report DEGRADED/SUSPECT for damaged replica");

    metrics_get(mports[R1], mbuf, sizeof mbuf);
    int64_t m_hlth = -1, m_bytes = 0, m_parts = 0, m_dmg = 0, m_held = -1;
    if (!metrics_find_i64(mbuf, "\ntsdb_cluster_volume_health{volume=\"1\"} ", &m_hlth) || m_hlth != CL_HEALTH_DAMAGED ||
        !metrics_find_i64(mbuf, "\ntsdb_young_scrub_bytes_total{volume=\"1\"} ", &m_bytes) || m_bytes <= 0 ||
        !metrics_find_i64(mbuf, "\ntsdb_young_scrub_parts_total{volume=\"1\"} ", &m_parts) || m_parts < 1 ||
        !metrics_find_i64(mbuf, "\ntsdb_young_scrub_damaged_total{volume=\"1\"} ", &m_dmg) || m_dmg < 1 ||
        !strstr(mbuf, "\ntsdb_young_scrub_age_seconds{volume=\"1\"} ") ||
        !metrics_find_i64(mbuf, "\ntsdb_young_scrub_min_isr_held{volume=\"1\"} ", &m_held) || m_held != 0)
        die("youngscrub: R1 metrics mismatch (health=%" PRId64 " bytes=%" PRId64 " parts=%" PRId64 " dmg=%" PRId64
            " held=%" PRId64 ")",
            m_hlth, m_bytes, m_parts, m_dmg, m_held);

    /* 3. Writes continue succeeding on leader L while R1 is out of ISR. */
    for (int k = 0; k < 20; k++) {
        int64_t wts = 2000000 + k * 100;
        float wv = 9.0f;
        if ((rc = tsdbc_insert_series(c, id, &wts, &wv, 1)) != 0)
            die("youngscrub: write %d after damaged follower left ISR failed: %s", k, ers(rc));
    }

    /* 4. Restart R1: v1/SCRUB must trigger priority re-scrub of damaged part -> still DAMAGED & out of ISR. */
    char spath[PATH_MAX + 160];
    snprintf(spath, sizeof spath, "%s/SCRUB", vdir);
    if (access(spath, F_OK) != 0)
        die("youngscrub: expected advisory progress file %s", spath);
    stop(R1, SIGTERM);
    start(R1);
    mports[R1] = th_mport;
    await_open_gen(0, "ys", R1, 2, 0);
    int re_dmg = 0;
    for (t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        metrics_get(mports[R1], mbuf, sizeof mbuf);
        int64_t r_dmg = 0, r_hlth = -1;
        if (metrics_find_i64(mbuf, "\ntsdb_young_scrub_damaged_total{volume=\"1\"} ", &r_dmg) && r_dmg >= 1 &&
            metrics_find_i64(mbuf, "\ntsdb_cluster_volume_health{volume=\"1\"} ", &r_hlth) &&
            r_hlth == CL_HEALTH_DAMAGED && vol_health_in_status(0, ids[R1], 1) == CL_HEALTH_DAMAGED) {
            re_dmg = 1;
            break;
        }
    }
    if (!re_dmg)
        die("youngscrub: restarted follower %d did not re-scrub and re-detect CL_HEALTH_DAMAGED", R1);
    usleep(500000);
    uint32_t nisr_after = 0;
    if (node_in_isr(L, "ys", ids[R1], &nisr_after) != 0 || nisr_after != 2)
        die("youngscrub: restarted damaged follower %d rejoined ISR (nisr=%" PRIu32 ")", R1, nisr_after);

    /* 4b. Vanished damaged priority part across restart (e.g. merged away before scrubd ran):
     * Write a valid v1/SCRUB naming a non-existent damaged_part on clean follower R2 and restart R2.
     * scrubd MUST keep R2 CL_HEALTH_DAMAGED (never silently clear damage when the priority part vanished). */
    int R2a = (L + 2) % 3;
    char r2dir[PATH_MAX + 80], r2scrub[PATH_MAX + 160];
    server_dir(R2a, r2dir, sizeof r2dir);
    snprintf(r2scrub, sizeof r2scrub, "%s/v1/SCRUB", r2dir);
    stop(R2a, SIGTERM);
    {
        const char *body = "tsdb-scrub 1\n"
                           "pass_start_s 1000\n"
                           "last_pass_s 1000\n"
                           "first_pass_s 1000\n"
                           "cursor 0 0 0 0 0 0\n"
                           "damaged 1\n"
                           "damaged_part p0_999_999_0.part\n";
        int sfd = open(r2scrub, O_RDWR | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
        if (sfd < 0 || write(sfd, body, strlen(body)) != (ssize_t)strlen(body))
            die("youngscrub: write body to %s", r2scrub);
        uint64_t bsz = 0, bh = 0;
        if (snap_xxh64_fd(sfd, &bsz, &bh) != 0)
            die("youngscrub: snap_xxh64_fd %s", r2scrub);
        char tail[64];
        int tl = snprintf(tail, sizeof tail, "end %016" PRIx64 "\n", bh);
        if (lseek(sfd, 0, SEEK_END) < 0 || write(sfd, tail, (size_t)tl) != tl)
            die("youngscrub: write end to %s", r2scrub);
        close(sfd);
    }
    start(R2a);
    mports[R2a] = th_mport;
    await_open_gen(0, "ys", R2a, 2, 0);
    await_log(R2a, "vanished before restart re-scrub; keeping volume DAMAGED", 15000,
              "R2 kept volume DAMAGED when priority part vanished");
    int r2_kept_dmg = 0;
    for (t0 = now_ms(); now_ms() - t0 < 10000; usleep(50000)) {
        metrics_get(mports[R2a], mbuf, sizeof mbuf);
        int64_t h2 = -1;
        if (metrics_find_i64(mbuf, "\ntsdb_cluster_volume_health{volume=\"1\"} ", &h2) && h2 == CL_HEALTH_DAMAGED) {
            r2_kept_dmg = 1;
            break;
        }
    }
    if (!r2_kept_dmg)
        die("youngscrub: R2 cleared CL_HEALTH_DAMAGED after priority part vanished");

    /* 5. Flip a granule byte on leader L: leader reports CL_HEALTH_DAMAGED and keeps leading cleanly. */
    char ldir[PATH_MAX + 80], lvdir[PATH_MAX + 128], lpname[128] = "";
    server_dir(L, ldir, sizeof ldir);
    snprintf(lvdir, sizeof lvdir, "%s/v1", ldir);
    if (!find_first_part(lvdir, lpname, sizeof lpname))
        die("youngscrub: leader %d has no .part file", L);
    flip_part_payload_byte(lvdir, lpname);
    int lead_dmg = 0;
    for (t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        if (vol_health_in_status(0, ids[L], 1) == CL_HEALTH_DAMAGED) {
            lead_dmg = 1;
            break;
        }
    }
    if (!lead_dmg)
        die("youngscrub: damaged leader %d did not report CL_HEALTH_DAMAGED", L);
    for (int k = 0; k < 10; k++) {
        int64_t wts = 3000000 + k * 100;
        float wv = 11.0f;
        if ((rc = tsdbc_insert_series(c, id, &wts, &wv, 1)) != 0)
            die("youngscrub: damaged leader %d stopped taking writes: %s", L, ers(rc));
    }

    tsdbc_close(c);
    stop_all();

    /* ---- Part B: 3 replicas, min_isr = 3 (damaged follower MUST stay in ISR, log & export min_isr_held=1) ---- */
    scenario("youngscrub-minisr3");
    init_min_isr = 3;
    for (int i = 0; i < 3; i++) {
        envs[i] = "heal_off=1";
        penv[i] = "TSDB_SCRUB_TEST=interval_ms=50";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
    }
    init_cluster(0, 600);
    init_min_isr = 0;
    node_add(0, 1);
    node_add(0, 2);
    want = 3;
    await_view(0, p_voters, &want, "three voters (min_isr=3)");

    vnum = 0;
    if ((rc = vol_add(0, "ys3", 3, &vnum)) != 0 || vnum != 1)
        die("youngscrub(min_isr=3): vol_add ys3: %s num=%" PRIu32, cluster_strerror(rc), vnum);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "ys3", i, 1, 0);
    if (!vol_rec(0, "ys3", &v) || v.min_isr != 3)
        die("youngscrub(min_isr=3): bad record min_isr=%" PRIu32, v.min_isr);
    L = server_of(v.leader);
    R1 = (L + 1) % 3;
    c = client(L);
    id = rep_series(c, "ys3.s0", "ys3", 30000);
    await_isr(L, "ys3", 3, 15000, "ys3 3/3 ISR");

    if ((rc = tsdbc_insert_series(c, id, ts, vals, nbatch)) != 0)
        die("youngscrub(min_isr=3): large insert: %s", ers(rc));
    free(ts);
    free(vals);

    server_dir(R1, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    pname[0] = '\0';
    for (t0 = now_ms(); !find_first_part(vdir, pname, sizeof pname); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("youngscrub(min_isr=3): follower %d never received .part", R1);
    flip_part_payload_byte(vdir, pname);

    /* Wait for R1 to report CL_HEALTH_DAMAGED, log min_isr hold, and set tsdb_young_scrub_min_isr_held=1.
     * Check ISR on every poll so a mutant that leaves below min_isr fails immediately with its oracle line. */
    int saw_held = 0;
    for (t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        uint32_t nisr_chk = 0;
        int in_chk = node_in_isr(L, "ys3", ids[R1], &nisr_chk);
        if (in_chk == 0 || (in_chk == 1 && nisr_chk < 3))
            die("youngscrub(min_isr=3): damaged follower %d left ISR below min_isr=3 (nisr=%" PRIu32 ")", R1, nisr_chk);
        metrics_get(mports[R1], mbuf, sizeof mbuf);
        int64_t hlth = -1, held = 0;
        if (metrics_find_i64(mbuf, "\ntsdb_cluster_volume_health{volume=\"1\"} ", &hlth) &&
            hlth == CL_HEALTH_DAMAGED &&
            metrics_find_i64(mbuf, "\ntsdb_young_scrub_min_isr_held{volume=\"1\"} ", &held) && held == 1) {
            saw_held = 1;
            break;
        }
    }
    if (!saw_held)
        die("youngscrub(min_isr=3): follower %d did not report CL_HEALTH_DAMAGED + tsdb_young_scrub_min_isr_held=1",
            R1);
    await_log(R1, "damaged replica stays in ISR", 10000, "follower R1 logged min_isr hold");

    /* Wait 1.5 s and assert R1 STAYS in ISR (catches youngleavebelow!). */
    usleep(1500000);
    uint32_t nisr3 = 0;
    if (node_in_isr(L, "ys3", ids[R1], &nisr3) != 1 || nisr3 != 3)
        die("youngscrub(min_isr=3): damaged follower %d left ISR below min_isr=3 (nisr=%" PRIu32 ")", R1, nisr3);

    int64_t wts = 5000000;
    float wv = 42.0f;
    if ((rc = tsdbc_insert_series(c, id, &wts, &wv, 1)) != 0)
        die("youngscrub(min_isr=3): write failed while held in ISR: %s", ers(rc));

    tsdbc_close(c);
    stop_all();

    /* ---- Part C: 3 replicas, min_isr = 1, TWO damaged followers must both leave ISR and stay out without flapping ---- */
    scenario("youngscrub-two-damaged");
    init_min_isr = 1;
    for (int i = 0; i < 3; i++) {
        envs[i] = "heal_off=1";
        penv[i] = "TSDB_SCRUB_TEST=interval_ms=50";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
    }
    init_cluster(0, 600);
    init_min_isr = 0;
    node_add(0, 1);
    node_add(0, 2);
    want = 3;
    await_view(0, p_voters, &want, "three voters (min_isr=1)");

    vnum = 0;
    if ((rc = vol_add(0, "ys1", 3, &vnum)) != 0 || vnum != 1)
        die("youngscrub(two-damaged): vol_add ys1: %s num=%" PRIu32, cluster_strerror(rc), vnum);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "ys1", i, 1, 0);
    if (!vol_rec(0, "ys1", &v) || v.min_isr != 1)
        die("youngscrub(two-damaged): bad record min_isr=%" PRIu32, v.min_isr);
    L = server_of(v.leader);
    R1 = (L + 1) % 3;
    int R2 = (L + 2) % 3;
    c = client(L);
    id = rep_series(c, "ys1.s0", "ys1", 30000);
    await_isr(L, "ys1", 3, 15000, "ys1 3/3 ISR");

    ts = malloc(nbatch * sizeof *ts);
    vals = malloc(nbatch * sizeof *vals);
    if (!ts || !vals)
        die("youngscrub(two-damaged): malloc");
    for (size_t k = 0; k < nbatch; k++) {
        ts[k] = 100000 + (int64_t)k * 10;
        vals[k] = (float)(k % 100) * 0.5f;
    }
    if ((rc = tsdbc_insert_series(c, id, ts, vals, nbatch)) != 0)
        die("youngscrub(two-damaged): large insert: %s", ers(rc));
    free(ts);
    free(vals);

    char vdir2[PATH_MAX + 128], pname2[128] = "";
    server_dir(R1, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    server_dir(R2, ldir, sizeof ldir);
    snprintf(vdir2, sizeof vdir2, "%s/v1", ldir);
    pname[0] = '\0';
    for (t0 = now_ms(); !find_first_part(vdir, pname, sizeof pname) || !find_first_part(vdir2, pname2, sizeof pname2);
         usleep(50000))
        if (now_ms() - t0 > 15000)
            die("youngscrub(two-damaged): followers %d/%d never received .part", R1, R2);

    flip_part_payload_byte(vdir, pname);
    flip_part_payload_byte(vdir2, pname2);

    int both_left = 0;
    for (t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        uint32_t n1 = 0, n2 = 0;
        if (node_in_isr(L, "ys1", ids[R1], &n1) == 0 && node_in_isr(L, "ys1", ids[R2], &n2) == 0 && n1 == 1) {
            both_left = 1;
            break;
        }
    }
    if (!both_left)
        die("youngscrub(two-damaged): both damaged followers did not leave ISR (min_isr=1)");

    struct meta_volume v_before = {0};
    if (!vol_rec(L, "ys1", &v_before))
        die("youngscrub(two-damaged): vol_rec before stability window failed");
    /* Send writes and wait 1.5 s: neither damaged follower may rejoin and isr_version must stay stable (no flapping). */
    for (int k = 0; k < 10; k++) {
        int64_t t2 = 6000000 + k * 100;
        float v2 = 3.0f;
        if ((rc = tsdbc_insert_series(c, id, &t2, &v2, 1)) != 0)
            die("youngscrub(two-damaged): write %d failed: %s", k, ers(rc));
    }
    usleep(1500000);
    struct meta_volume v_after = {0};
    if (!vol_rec(L, "ys1", &v_after) || v_after.nisr != 1 || v_after.isr_version != v_before.isr_version)
        die("youngscrub(two-damaged): ISR flapped (nisr=%" PRIu32 " isrv %" PRIu64 " -> %" PRIu64 ")", v_after.nisr,
            v_before.isr_version, v_after.isr_version);

    tsdbc_close(c);
    stop_all();
    for (int i = 0; i < 3; i++) {
        envs[i] = NULL;
        penv[i] = NULL;
        xargs[i] = NULL;
    }
    printf("  youngscrub: min_isr=2 damaged follower left ISR + restart re-scrubbed first + damaged leader kept leading; "
           "min_isr=3 stayed in ISR with metric & log; two damaged followers (min_isr=1) both left ISR stably\n");
}

/* Helpers for scen_scrubheal (R12, r12-heal; PLAN.md D8). */
struct sh_digest {
    uint64_t count;
    uint64_t hash;
};

static int sh_digest_cb(void *ctx, const int64_t *ts, const float *v, size_t n)
{
    struct sh_digest *d = ctx;
    for (size_t i = 0; i < n; i++) {
        uint64_t ut = (uint64_t)ts[i];
        uint32_t uv = 0;
        memcpy(&uv, &v[i], sizeof uv);
        d->hash ^= ut + 0x9e3779b97f4a7c15ull;
        d->hash *= 0xbf58476d1ce4e5b9ull;
        d->hash ^= (uint64_t)uv + 0x94d049bb133111ebull;
        d->hash *= 0x94d049bb133111ebull;
        d->count++;
    }
    return 0;
}

static struct sh_digest sh_read_digest(int srv, tsdb_sid id)
{
    tsdbc *c = client(srv);
    struct sh_digest d = {.count = 0, .hash = 14695981039346656037ull};
    int rc = tsdbc_query_raw(c, id, 0, INT64_MAX / 2, sh_digest_cb, &d);
    tsdbc_close(c);
    if (rc != 0)
        die("scrubheal: query on server %d failed: %s", srv, ers(rc));
    return d;
}

static int sh_raft_leader(int count)
{
    for (int i = 0; i < count; i++) {
        if (stopped[i] || !pids[i])
            continue;
        struct view vw = {0};
        view(i, &vw);
        uint32_t lid = vw.st.leader;
        view_free(&vw);
        if (lid)
            return server_of(lid);
    }
    return 0;
}

/* Transfer volume `vnum` (`vname`) to each of the 3 replicas in turn and verify every key/row matches `want`. */
static void sh_verify_all_replicas_equal(int count, uint32_t vnum, const char *vname, tsdb_sid id,
                                         struct sh_digest want)
{
    struct meta_volume v = {0};
    for (int target = 0; target < count; target++) {
        int rl = sh_raft_leader(count);
        await_isr(rl, vname, (uint32_t)count, 15000, "full ISR before transfer");
        if (!vol_rec(rl, vname, &v))
            die("scrubheal: vol_rec(%s) before transfer to %d failed", vname, target);
        if (v.leader != ids[target]) {
            uint8_t body[8];
            size_t bl = cluster_volume_force_encode(vnum, ids[target], body);
            uint8_t *rep = NULL;
            size_t rlen = 0;
            int rc = admin(rl, CLUSTER_OP_VOLUME_TRANSFER, body, bl, 1, &rep, &rlen);
            if (rc != 0)
                die("scrubheal: transfer %s to server %d failed: %s (%.*s)", vname, target, cluster_strerror(rc),
                    (int)rlen, rep ? (const char *)rep : "");
            free(rep);
            for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
                if (vol_rec(target, vname, &v) && v.leader == ids[target])
                    break;
            }
            if (!vol_rec(target, vname, &v) || v.leader != ids[target])
                die("scrubheal: server %d did not become leader of %s after transfer", target, vname);
        }
        /* Wait briefly until the new leader answers reads cleanly. */
        struct sh_digest got = {0};
        for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000; usleep(100000)) {
            tsdbc *c = client(target);
            got = (struct sh_digest){.count = 0, .hash = 14695981039346656037ull};
            int qrc = tsdbc_query_raw(c, id, 0, INT64_MAX / 2, sh_digest_cb, &got);
            tsdbc_close(c);
            if (qrc == 0)
                break;
        }
        if (got.count != want.count || got.hash != want.hash)
            die("scrubheal: replica %d data mismatch on %s (count %" PRIu64 " vs %" PRIu64 ", hash %016" PRIx64
                " vs %016" PRIx64 ")", target, vname, got.count, want.count, got.hash, want.hash);
    }
}

/* Write a valid v<vol>/SCRUB naming `pname` as damaged so scrubd_preload_locked marks the replica DAMAGED on boot. */
static void sh_write_damaged_scrub(int srv, uint32_t vol, const char *pname)
{
    char sdir[PATH_MAX + 80], spath[PATH_MAX + 160], body[512];
    server_dir(srv, sdir, sizeof sdir);
    snprintf(spath, sizeof spath, "%s/v%" PRIu32 "/SCRUB", sdir, vol);
    int bl = snprintf(body, sizeof body,
                      "tsdb-scrub 1\n"
                      "pass_start_s 1000\n"
                      "last_pass_s 1000\n"
                      "first_pass_s 1000\n"
                      "cursor 0 0 0 0 0 0\n"
                      "damaged 1\n"
                      "damaged_part %s\n",
                      pname);
    int fd = open(spath, O_RDWR | O_CREAT | O_TRUNC | O_CLOEXEC, 0644);
    if (fd < 0 || write(fd, body, (size_t)bl) != bl)
        die("scrubheal: write %s", spath);
    uint64_t bsz = 0, bh = 0;
    if (snap_xxh64_fd(fd, &bsz, &bh) != 0)
        die("scrubheal: snap_xxh64_fd %s", spath);
    char tail[64];
    int tl = snprintf(tail, sizeof tail, "end %016" PRIx64 "\n", bh);
    if (lseek(fd, 0, SEEK_END) < 0 || write(fd, tail, (size_t)tl) != tl)
        die("scrubheal: write end %s", spath);
    close(fd);
}

/* scrubheal (R12, r12-heal; PLAN.md D8):
 *   Part 1 (3 replicas, min_isr=2, heal_cooldown_ms=500):
 *     - Flip a granule on follower R1 -> DAMAGED -> leaves ISR -> auto-reset -> v1.lost-<oldrid> kept -> snapshot ->
 *       R1 rejoins ISR; verify every key equal on all three via planned leader transfer to each in turn.
 *     - Flip a granule on leader L -> planned transfer first (catches healleader!), then old leader leaves ISR,
 *       auto-reset -> v1.lost-<oldrid> kept -> snapshot -> rejoins ISR; verify every key equal on all three.
 *     - Stop R2, flip R1 (held in ISR at min_isr=2), flip leader L -> no non-DAMAGED ISR member exists -> transfer
 *       withheld, logged, tsdb_cluster_auto_resets_total{why="no_candidate"} >= 1 & heal_blocked == 1.
 *   Part 2 (3 replicas, min_isr=2, heal_cooldown_ms=500; catches healbelowmin!):
 *     - Stop R1 (ISR={L,R2}), flip R2 (held in ISR), flip R1 + persist SCRUB, start R1 -> R1 is DAMAGED & non-ISR
 *       while healthy non-DAMAGED ISR == 1 < min_isr == 2 -> MUST NOT reset R1 (heal_blocked{why="below_min_isr"}==1).
 *   Part 3 (3 replicas, min_isr=1, heal_cooldown_ms=500):
 *     - Flip BOTH followers R1 and R2 at once -> healed strictly ONE AT A TIME (never 2 learners simultaneously),
 *       last good copy L never reset, both lost dirs kept, all 3 equal.
 *   Part 4 (3 replicas, min_isr=2, heal_cooldown_ms=3600000; catches healrepeat!):
 *     - Flip R1 -> heals once (auto_resets{why="damaged"} == 1) -> immediately flip R1 again within 1 h cooldown ->
 *       no 2nd reset during cooldown window (counter stays <= 1). */
static void scen_scrubheal(void)
{
    const size_t nbatch = 70000;
    int64_t *ts = malloc(nbatch * sizeof *ts);
    float *vals = malloc(nbatch * sizeof *vals);
    if (!ts || !vals)
        die("scrubheal: malloc");
    for (size_t k = 0; k < nbatch; k++) {
        ts[k] = 100000 + (int64_t)k * 10;
        vals[k] = (float)((k * 7) % 1000) * 0.25f;
    }

    /* ---- Part 1: follower heal, leader transfer+heal (catches healleader), no-candidate withhold ---- */
    scenario("scrubheal-p1");
    int mports[3] = {0};
    init_min_isr = 2;
    for (int i = 0; i < 3; i++) {
        envs[i] = "heal_cooldown_ms=500";
        penv[i] = "TSDB_SCRUB_TEST=interval_ms=50";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
        if (mports[i] <= 0)
            die("scrubheal: server %d reported no metrics port", i);
    }
    init_cluster(0, 600);
    init_min_isr = 0;
    node_add(0, 1);
    node_add(0, 2);
    unsigned want = 3;
    await_view(0, p_voters, &want, "three voters");

    uint32_t vnum = 0;
    int rc;
    if ((rc = vol_add(0, "sh1", 3, &vnum)) != 0 || vnum != 1)
        die("scrubheal: vol_add sh1: %s num=%" PRIu32, cluster_strerror(rc), vnum);
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "sh1", i, 1, 0);
    struct meta_volume v = {0};
    if (!vol_rec(0, "sh1", &v) || v.min_isr != 2)
        die("scrubheal: bad record for sh1");
    int L = server_of(v.leader);
    int R1 = (L + 1) % 3;
    int R2 = (L + 2) % 3;
    tsdbc *c = client(L);
    tsdb_sid id = rep_series(c, "sh1.s0", "sh1", 30000);
    await_isr(L, "sh1", 3, 15000, "sh1 3/3 ISR");
    if ((rc = tsdbc_insert_series(c, id, ts, vals, nbatch)) != 0)
        die("scrubheal: large insert sh1: %s", ers(rc));
    tsdbc_close(c);

    char sdir[PATH_MAX + 80], vdir[PATH_MAX + 128], pname[128] = "";
    for (int i = 0; i < 3; i++) {
        server_dir(i, sdir, sizeof sdir);
        snprintf(vdir, sizeof vdir, "%s/v1", sdir);
        uint64_t t0 = now_ms();
        while (!find_first_part(vdir, pname, sizeof pname)) {
            if (now_ms() - t0 > 15000)
                die("scrubheal: server %d never got a .part file", i);
            usleep(50000);
        }
    }
    struct sh_digest ref_dig = sh_read_digest(L, id);
    if (ref_dig.count != nbatch)
        die("scrubheal: expected %zu rows on leader, got %" PRIu64, nbatch, ref_dig.count);

    /* 1a. Flip a granule byte on follower R1 -> auto-reset -> snapshot -> rejoins ISR -> all 3 equal. */
    if (!vol_rec(0, "sh1", &v))
        die("scrubheal: vol_rec sh1 before follower flip");
    uint64_t r1_oldrid = rep_of(&v, R1)->rid;
    server_dir(R1, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    if (!find_first_part(vdir, pname, sizeof pname))
        die("scrubheal: R1 has no .part");
    flip_part_payload_byte(vdir, pname);

    uint64_t r1_newrid = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 45000; usleep(100000)) {
        if (vol_rec(0, "sh1", &v) && rep_of(&v, R1) && rep_of(&v, R1)->rid != r1_oldrid) {
            r1_newrid = rep_of(&v, R1)->rid;
            break;
        }
    }
    if (!r1_newrid)
        die("scrubheal: follower R1 (%d) was not automatically reset within 45 s", R1);
    await_isr(0, "sh1", 3, 60000, "sh1 follower R1 rebuilt and rejoined ISR");

    /* Verify v1.lost-<oldrid> was set aside and kept, and R1 health is back to OK. */
    char lost[64];
    snprintf(lost, sizeof lost, "v1.lost-%016" PRIx64, r1_oldrid);
    if (!dir_has(R1, lost))
        die("scrubheal: follower R1 (%d) missing preserved directory %s", R1, lost);
    int r1_ok = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        if (vol_health_in_status(sh_raft_leader(3), ids[R1], 1) == CL_HEALTH_OK) {
            r1_ok = 1;
            break;
        }
    }
    if (!r1_ok)
        die("scrubheal: rebuilt follower R1 (%d) did not return to CL_HEALTH_OK", R1);

    char mbuf[65536];
    int rl = sh_raft_leader(3);
    metrics_get(mports[rl], mbuf, sizeof mbuf);
    int64_t c_dmg = -1;
    if (!metrics_find_i64(mbuf, "\ntsdb_cluster_auto_resets_total{why=\"damaged\"} ", &c_dmg) || c_dmg < 1)
        die("scrubheal: Raft leader %d missing tsdb_cluster_auto_resets_total{why=\"damaged\"} >= 1 (got %" PRId64 ")",
            rl, c_dmg);

    sh_verify_all_replicas_equal(3, vnum, "sh1", id, ref_dig);

    /* 1b. Flip a granule byte on the current leader -> planned transfer first, then reset & rebuild. */
    if (!vol_rec(0, "sh1", &v))
        die("scrubheal: vol_rec sh1 before leader flip");
    L = server_of(v.leader);
    uint64_t l_oldrid = rep_of(&v, L)->rid;
    rl = sh_raft_leader(3);
    metrics_get(mports[rl], mbuf, sizeof mbuf);
    int64_t dmg_before_lead = 0;
    (void)metrics_find_i64(mbuf, "\ntsdb_cluster_auto_resets_total{why=\"damaged\"} ", &dmg_before_lead);
    server_dir(L, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    pname[0] = '\0';
    if (!find_first_part(vdir, pname, sizeof pname))
        die("scrubheal: leader L (%d) has no .part", L);
    flip_part_payload_byte(vdir, pname);

    int moved_off_l = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 25000; usleep(100000)) {
        rl = sh_raft_leader(3);
        if (vol_rec(rl, "sh1", &v) && v.leader && v.leader != ids[L]) {
            moved_off_l = 1;
            break;
        }
        metrics_get(mports[rl], mbuf, sizeof mbuf);
        int64_t dmg_now = 0;
        if (metrics_find_i64(mbuf, "\ntsdb_cluster_auto_resets_total{why=\"damaged\"} ", &dmg_now) &&
            dmg_now > dmg_before_lead && vol_rec(rl, "sh1", &v) && v.leader == ids[L])
            die("scrubheal: auto-reset proposed while damaged leader L (%d) still leads (healleader)", L);
    }
    if (!moved_off_l)
        die("scrubheal: damaged leader L (%d) was not transferred to a healthy ISR member within 25 s", L);

    uint64_t l_newrid = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 45000; usleep(100000)) {
        rl = sh_raft_leader(3);
        if (vol_rec(rl, "sh1", &v) && rep_of(&v, L) && rep_of(&v, L)->rid != l_oldrid) {
            l_newrid = rep_of(&v, L)->rid;
            break;
        }
    }
    if (!l_newrid)
        die("scrubheal: former leader L (%d) was not reset after planned transfer", L);
    await_isr(0, "sh1", 3, 60000, "sh1 former leader L rebuilt and rejoined ISR");

    snprintf(lost, sizeof lost, "v1.lost-%016" PRIx64, l_oldrid);
    if (!dir_has(L, lost))
        die("scrubheal: former leader L (%d) missing preserved directory %s", L, lost);

    rl = sh_raft_leader(3);
    metrics_get(mports[rl], mbuf, sizeof mbuf);
    int64_t c_xfer = -1;
    if (!metrics_find_i64(mbuf, "\ntsdb_cluster_auto_resets_total{why=\"leader_transfer\"} ", &c_xfer) || c_xfer < 1)
        die("scrubheal: Raft leader %d missing leader_transfer counter >= 1 (got %" PRId64 ")", rl, c_xfer);

    sh_verify_all_replicas_equal(3, vnum, "sh1", id, ref_dig);

    /* 1c. DAMAGED leader with NO non-DAMAGED ISR member: transfer withheld, logged, blocked metric exposed. */
    if (!vol_rec(0, "sh1", &v))
        die("scrubheal: vol_rec sh1 before no-candidate check");
    L = server_of(v.leader);
    R1 = (L + 1) % 3;
    R2 = (L + 2) % 3;
    stop(R2, SIGTERM);
    await_isr(L, "sh1", 2, 20000, "sh1 ISR shrinks to {L, R1}");
    /* Flip R1 (held in ISR because min_isr == 2), wait for Raft leader to observe R1 DAMAGED. */
    server_dir(R1, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    pname[0] = '\0';
    if (!find_first_part(vdir, pname, sizeof pname))
        die("scrubheal: R1 has no .part for no-candidate check");
    flip_part_payload_byte(vdir, pname);
    int r1_dmg = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        if (vol_health_in_status(sh_raft_leader(3), ids[R1], 1) == CL_HEALTH_DAMAGED) {
            r1_dmg = 1;
            break;
        }
    }
    if (!r1_dmg)
        die("scrubheal: R1 did not report CL_HEALTH_DAMAGED in no-candidate check");
    /* Now flip leader L too -> neither ISR member is non-DAMAGED. */
    uint64_t l_rid_nc = rep_of(&v, L)->rid;
    server_dir(L, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    pname[0] = '\0';
    if (!find_first_part(vdir, pname, sizeof pname))
        die("scrubheal: L has no .part for no-candidate check");
    flip_part_payload_byte(vdir, pname);
    rl = sh_raft_leader(3);
    await_log(rl, "with no non-DAMAGED ISR member; transfer withheld", 15000,
              "Raft leader logged withheld transfer (no non-DAMAGED ISR candidate)");
    int saw_nc_metric = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 10000; usleep(100000)) {
        metrics_get(mports[rl], mbuf, sizeof mbuf);
        int64_t nc = -1, blk = -1;
        if (metrics_find_i64(mbuf, "\ntsdb_cluster_auto_resets_total{why=\"no_candidate\"} ", &nc) && nc >= 1 &&
            metrics_find_i64(mbuf, "\ntsdb_cluster_heal_blocked{volume=\"1\",why=\"no_candidate\"} ", &blk) &&
            blk == 1) {
            saw_nc_metric = 1;
            break;
        }
    }
    if (!saw_nc_metric)
        die("scrubheal: missing no_candidate counter/blocked gauge on Raft leader %d", rl);
    usleep(1000000);
    if (!vol_rec(rl, "sh1", &v) || v.leader != ids[L] || rep_of(&v, L)->rid != l_rid_nc)
        die("scrubheal: damaged leader moved or reset despite no non-DAMAGED ISR candidate");
    stop_all();

    /* ---- Part 2: remaining non-DAMAGED ISR < min_isr -> MUST NOT reset (catches healbelowmin!) ---- */
    scenario("scrubheal-belowmin");
    init_min_isr = 2;
    for (int i = 0; i < 3; i++) {
        envs[i] = "heal_cooldown_ms=500";
        penv[i] = "TSDB_SCRUB_TEST=interval_ms=50";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
    }
    init_cluster(0, 600);
    init_min_isr = 0;
    node_add(0, 1);
    node_add(0, 2);
    want = 3;
    await_view(0, p_voters, &want, "three voters (belowmin)");
    vnum = 0;
    if ((rc = vol_add(0, "shbm", 3, &vnum)) != 0 || vnum != 1)
        die("scrubheal(belowmin): vol_add: %s", cluster_strerror(rc));
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "shbm", i, 1, 0);
    if (!vol_rec(0, "shbm", &v) || v.min_isr != 2)
        die("scrubheal(belowmin): bad record");
    L = server_of(v.leader);
    R1 = (L + 1) % 3;
    R2 = (L + 2) % 3;
    c = client(L);
    id = rep_series(c, "shbm.s0", "shbm", 30000);
    await_isr(L, "shbm", 3, 15000, "shbm 3/3 ISR");
    if ((rc = tsdbc_insert_series(c, id, ts, vals, nbatch)) != 0)
        die("scrubheal(belowmin): insert: %s", ers(rc));
    tsdbc_close(c);

    char p1[128] = "", p2[128] = "";
    server_dir(R1, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    for (uint64_t t0 = now_ms(); !find_first_part(vdir, p1, sizeof p1); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("scrubheal(belowmin): R1 never got .part");
    char r2sdir[PATH_MAX + 80], r2vdir[PATH_MAX + 128];
    server_dir(R2, r2sdir, sizeof r2sdir);
    snprintf(r2vdir, sizeof r2vdir, "%s/v1", r2sdir);
    for (uint64_t t0 = now_ms(); !find_first_part(r2vdir, p2, sizeof p2); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("scrubheal(belowmin): R2 never got .part");

    /* Stop R1 -> ISR = {L, R2}. Flip R2 -> R2 reports DAMAGED and stays in ISR (min_isr=2). */
    stop(R1, SIGTERM);
    await_isr(L, "shbm", 2, 20000, "shbm ISR shrinks to {L, R2}");
    flip_part_payload_byte(r2vdir, p2);
    int r2_dmg = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        if (vol_health_in_status(sh_raft_leader(3), ids[R2], 1) == CL_HEALTH_DAMAGED) {
            r2_dmg = 1;
            break;
        }
    }
    if (!r2_dmg)
        die("scrubheal(belowmin): R2 did not report CL_HEALTH_DAMAGED");

    /* Flip R1 while stopped and write v1/SCRUB so scrubd_preload marks R1 DAMAGED from boot before repld connects. */
    if (!vol_rec(L, "shbm", &v))
        die("scrubheal(belowmin): vol_rec before R1 start");
    uint64_t bm_r1_rid = rep_of(&v, R1)->rid;
    flip_part_payload_byte(vdir, p1);
    sh_write_damaged_scrub(R1, 1, p1);
    start(R1);
    mports[R1] = th_mport;

    /* Wait for Raft leader to observe R1 DAMAGED (out of ISR) while good_isr == 1 < min_isr == 2. */
    int saw_r1_bm = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        rl = sh_raft_leader(3);
        if (vol_rec(rl, "shbm", &v) && rep_of(&v, R1)->rid != bm_r1_rid)
            die("scrubheal(belowmin): reset R1 while healthy non-DAMAGED ISR < min_isr (healbelowmin)");
        if (vol_health_in_status(rl, ids[R1], 1) == CL_HEALTH_DAMAGED) {
            saw_r1_bm = 1;
            break;
        }
    }
    if (!saw_r1_bm)
        die("scrubheal(belowmin): R1 did not report CL_HEALTH_DAMAGED after restart");

    /* Hold 2.5 s: R1 must NOT be reset, blocked gauge must be 1, auto_resets{why="damaged"} must remain 0. */
    int saw_bm_metric = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 2500; usleep(100000)) {
        rl = sh_raft_leader(3);
        if (!vol_rec(rl, "shbm", &v) || rep_of(&v, R1)->rid != bm_r1_rid)
            die("scrubheal(belowmin): reset R1 while healthy non-DAMAGED ISR < min_isr (healbelowmin)");
        metrics_get(mports[rl], mbuf, sizeof mbuf);
        int64_t dm = -1, bm = -1, blk = -1;
        if (metrics_find_i64(mbuf, "\ntsdb_cluster_auto_resets_total{why=\"damaged\"} ", &dm) && dm != 0)
            die("scrubheal(belowmin): auto_resets_total{why=\"damaged\"} = %" PRId64 " != 0 (healbelowmin)", dm);
        if (metrics_find_i64(mbuf, "\ntsdb_cluster_auto_resets_total{why=\"below_min_isr\"} ", &bm) && bm >= 1 &&
            metrics_find_i64(mbuf, "\ntsdb_cluster_heal_blocked{volume=\"1\",why=\"below_min_isr\"} ", &blk) &&
            blk == 1)
            saw_bm_metric = 1;
    }
    if (!saw_bm_metric)
        die("scrubheal(belowmin): missing below_min_isr counter/blocked gauge");
    stop_all();

    /* ---- Part 3: two replicas DAMAGED at once (min_isr=1) -> healed one at a time, last good copy never reset ---- */
    scenario("scrubheal-two");
    init_min_isr = 1;
    for (int i = 0; i < 3; i++) {
        envs[i] = "heal_cooldown_ms=500";
        penv[i] = "TSDB_SCRUB_TEST=interval_ms=50";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
    }
    init_cluster(0, 600);
    init_min_isr = 0;
    node_add(0, 1);
    node_add(0, 2);
    want = 3;
    await_view(0, p_voters, &want, "three voters (two-damaged)");
    vnum = 0;
    if ((rc = vol_add(0, "sh2", 3, &vnum)) != 0 || vnum != 1)
        die("scrubheal(two): vol_add: %s", cluster_strerror(rc));
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "sh2", i, 1, 0);
    if (!vol_rec(0, "sh2", &v) || v.min_isr != 1)
        die("scrubheal(two): bad record");
    L = server_of(v.leader);
    R1 = (L + 1) % 3;
    R2 = (L + 2) % 3;
    c = client(L);
    id = rep_series(c, "sh2.s0", "sh2", 30000);
    await_isr(L, "sh2", 3, 15000, "sh2 3/3 ISR");
    if ((rc = tsdbc_insert_series(c, id, ts, vals, nbatch)) != 0)
        die("scrubheal(two): insert: %s", ers(rc));
    tsdbc_close(c);
    ref_dig = sh_read_digest(L, id);

    p1[0] = p2[0] = '\0';
    server_dir(R1, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    for (uint64_t t0 = now_ms(); !find_first_part(vdir, p1, sizeof p1); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("scrubheal(two): R1 never got .part");
    server_dir(R2, r2sdir, sizeof r2sdir);
    snprintf(r2vdir, sizeof r2vdir, "%s/v1", r2sdir);
    for (uint64_t t0 = now_ms(); !find_first_part(r2vdir, p2, sizeof p2); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("scrubheal(two): R2 never got .part");

    if (!vol_rec(0, "sh2", &v))
        die("scrubheal(two): vol_rec before dual flip");
    uint64_t l_rid0 = rep_of(&v, L)->rid;
    uint64_t r1_rid0 = rep_of(&v, R1)->rid;
    uint64_t r2_rid0 = rep_of(&v, R2)->rid;

    flip_part_payload_byte(vdir, p1);
    flip_part_payload_byte(r2vdir, p2);

    int both_healed = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 90000; usleep(100000)) {
        rl = sh_raft_leader(3);
        if (!vol_rec(rl, "sh2", &v))
            continue;
        if (rep_of(&v, L)->rid != l_rid0)
            die("scrubheal(two): last good copy L (%d) was reset!", L);
        int nlearn = 0;
        for (uint32_t k = 0; k < v.nrep; k++)
            nlearn += v.rep[k].learner != 0;
        if (nlearn > 1)
            die("scrubheal(two): %d replicas rebuilding simultaneously (must heal one at a time)", nlearn);
        if (rep_of(&v, R1)->rid != r1_rid0 && rep_of(&v, R2)->rid != r2_rid0 && v.nisr == 3) {
            both_healed = 1;
            break;
        }
    }
    if (!both_healed)
        die("scrubheal(two): both damaged followers did not heal and rejoin ISR within 90 s");
    snprintf(lost, sizeof lost, "v1.lost-%016" PRIx64, r1_rid0);
    if (!dir_has(R1, lost))
        die("scrubheal(two): R1 missing %s", lost);
    snprintf(lost, sizeof lost, "v1.lost-%016" PRIx64, r2_rid0);
    if (!dir_has(R2, lost))
        die("scrubheal(two): R2 missing %s", lost);
    sh_verify_all_replicas_equal(3, vnum, "sh2", id, ref_dig);
    stop_all();

    /* ---- Part 4: per-volume cooldown window prevents repeat reset storm (catches healrepeat!) ---- */
    scenario("scrubheal-cooldown");
    init_min_isr = 2;
    for (int i = 0; i < 3; i++) {
        /* Large cooldown (1 h) so slow/TSan runs never outrun the window; healrepeat skips it and fires at once. */
        envs[i] = "heal_cooldown_ms=3600000";
        penv[i] = "TSDB_SCRUB_TEST=interval_ms=50";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
    }
    init_cluster(0, 600);
    init_min_isr = 0;
    node_add(0, 1);
    node_add(0, 2);
    want = 3;
    await_view(0, p_voters, &want, "three voters (cooldown)");
    vnum = 0;
    if ((rc = vol_add(0, "shcd", 3, &vnum)) != 0 || vnum != 1)
        die("scrubheal(cooldown): vol_add: %s", cluster_strerror(rc));
    for (int i = 0; i < 3; i++)
        await_open_gen(0, "shcd", i, 1, 0);
    if (!vol_rec(0, "shcd", &v) || v.min_isr != 2)
        die("scrubheal(cooldown): bad record");
    L = server_of(v.leader);
    R1 = (L + 1) % 3;
    c = client(L);
    id = rep_series(c, "shcd.s0", "shcd", 30000);
    await_isr(L, "shcd", 3, 15000, "shcd 3/3 ISR");
    if ((rc = tsdbc_insert_series(c, id, ts, vals, nbatch)) != 0)
        die("scrubheal(cooldown): insert: %s", ers(rc));
    tsdbc_close(c);

    server_dir(R1, sdir, sizeof sdir);
    snprintf(vdir, sizeof vdir, "%s/v1", sdir);
    pname[0] = '\0';
    for (uint64_t t0 = now_ms(); !find_first_part(vdir, pname, sizeof pname); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("scrubheal(cooldown): R1 never got .part");

    if (!vol_rec(0, "shcd", &v))
        die("scrubheal(cooldown): vol_rec before flip 1");
    uint64_t cd_rid0 = rep_of(&v, R1)->rid;
    flip_part_payload_byte(vdir, pname);

    /* Wait for first heal to complete. */
    uint64_t cd_rid1 = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 45000; usleep(100000)) {
        if (vol_rec(0, "shcd", &v) && rep_of(&v, R1)->rid != cd_rid0) {
            cd_rid1 = rep_of(&v, R1)->rid;
            break;
        }
    }
    if (!cd_rid1)
        die("scrubheal(cooldown): first auto-reset of R1 did not happen");
    await_isr(0, "shcd", 3, 60000, "shcd R1 rebuilt after first flip");
    int cd_ok = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        if (vol_health_in_status(sh_raft_leader(3), ids[R1], 1) == CL_HEALTH_OK) {
            cd_ok = 1;
            break;
        }
    }
    if (!cd_ok)
        die("scrubheal(cooldown): rebuilt R1 did not return to CL_HEALTH_OK");

    /* Immediately flip R1 a second time (well within the 1 h cooldown window). */
    pname[0] = '\0';
    for (uint64_t t0 = now_ms(); !find_first_part(vdir, pname, sizeof pname); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("scrubheal(cooldown): R1 has no .part after first rebuild");
    flip_part_payload_byte(vdir, pname);

    /* Wait for R1 to report DAMAGED and leave ISR again (catching an immediate repeat reset under healrepeat). */
    int second_left = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 15000; usleep(50000)) {
        rl = sh_raft_leader(3);
        if (vol_rec(rl, "shcd", &v) && rep_of(&v, R1)->rid != cd_rid1)
            die("scrubheal(cooldown): R1 was reset again during cooldown window (healrepeat)");
        uint32_t nisr = 0;
        if (vol_health_in_status(rl, ids[R1], 1) == CL_HEALTH_DAMAGED && node_in_isr(L, "shcd", ids[R1], &nisr) == 0) {
            second_left = 1;
            break;
        }
    }
    if (!second_left)
        die("scrubheal(cooldown): R1 did not report DAMAGED and leave ISR on second flip");

    /* Hold 2.5 s (still inside 1 h cooldown): NO second reset may fire; counter MUST stay <= 1! */
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 2500; usleep(100000)) {
        rl = sh_raft_leader(3);
        if (!vol_rec(rl, "shcd", &v) || rep_of(&v, R1)->rid != cd_rid1)
            die("scrubheal(cooldown): R1 was reset again during cooldown window (healrepeat)");
        metrics_get(mports[rl], mbuf, sizeof mbuf);
        int64_t dm = -1;
        if (metrics_find_i64(mbuf, "\ntsdb_cluster_auto_resets_total{why=\"damaged\"} ", &dm) && dm > 1)
            die("scrubheal(cooldown): reset storm counter %" PRId64 " > 1 within cooldown (healrepeat)", dm);
    }

    stop_all();
    free(ts);
    free(vals);
    for (int i = 0; i < 3; i++) {
        envs[i] = NULL;
        penv[i] = NULL;
        xargs[i] = NULL;
    }
    printf("  scrubheal: follower auto-reset+snapshot+equal; leader planned transfer+reset+equal; no-candidate withheld; "
           "below-min_isr withheld; dual damage healed one-at-a-time keeping last good copy; cooldown rate-limit held\n");
}


struct saved_chunk {
    char name[128];
    uint8_t *data;
    size_t len;
};

static int load_vol_chunks(const char *sdir, uint32_t vol, struct saved_chunk *out, int cap)
{
    char vdir[PATH_MAX + 128];
    snprintf(vdir, sizeof vdir, "%s/s%" PRIu32, sdir, vol);
    DIR *d = opendir(vdir);
    if (!d)
        return 0;
    int n = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL && n < cap) {
        size_t nl = strlen(de->d_name);
        if (de->d_name[0] != 'o' || nl < 8 || strcmp(de->d_name + nl - 6, ".chunk") != 0)
            continue;
        char fp[PATH_MAX + 256];
        snprintf(fp, sizeof fp, "%s/%s", vdir, de->d_name);
        int fd = open(fp, O_RDONLY);
        if (fd < 0)
            continue;
        struct stat st;
        if (fstat(fd, &st) == 0 && st.st_size > 0) {
            uint8_t *buf = malloc((size_t)st.st_size);
            if (!buf) {
                close(fd);
                closedir(d);
                die("ecrebuild: out of memory reading %s", fp);
            }
            size_t got = 0;
            while (got < (size_t)st.st_size) {
                ssize_t r = read(fd, buf + got, (size_t)st.st_size - got);
                if (r <= 0)
                    break;
                got += (size_t)r;
            }
            if (got == (size_t)st.st_size) {
                snprintf(out[n].name, sizeof out[n].name, "%s", de->d_name);
                out[n].data = buf;
                out[n].len = got;
                n++;
            } else {
                free(buf);
            }
        }
        close(fd);
    }
    closedir(d);
    return n;
}

/* Flip byte 0 of cell 0 (offset 96 = CHUNK_HDR_BYTES) in every chunk file of volume `vol` in `sdir`. */
static int rot_vol_chunks(const char *sdir, uint32_t vol)
{
    char vdir[PATH_MAX + 128];
    snprintf(vdir, sizeof vdir, "%s/s%" PRIu32, sdir, vol);
    DIR *d = opendir(vdir);
    if (!d)
        return 0;
    int n = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        size_t nl = strlen(de->d_name);
        if (de->d_name[0] != 'o' || nl < 8 || strcmp(de->d_name + nl - 6, ".chunk") != 0)
            continue;
        char fp[PATH_MAX + 256];
        snprintf(fp, sizeof fp, "%s/%s", vdir, de->d_name);
        int fd = open(fp, O_RDWR);
        if (fd < 0)
            continue;
        uint8_t b = 0;
        if (pread(fd, &b, 1, 96) == 1) {
            b ^= 0xffu;
            if (pwrite(fd, &b, 1, 96) == 1 && fsync(fd) == 0)
                n++;
        }
        close(fd);
    }
    closedir(d);
    return n;
}

/* ecrebuild (r9-fill): 4+2 on 7 nodes with rebuild_after_s=6. Settles >= 2 objects, saves original bytes of victim V's
 * chunks, rots cell 0 on a surviving holder R_srv, arms CP_FILL_WRITTEN on 7th node S, kills V for good -> OUT ->
 * STRIPE_SET(S, FILLING) -> S writes first rebuilt chunk and crashes at fill-written (status 99) -> S restarts,
 * resumes idempotently, finishes remaining objects -> whole=1 -> STRIPE_WHOLE commits. Verifies every rebuilt chunk
 * file on S is byte-for-byte identical to V's saved original (despite the rotted survivor!), then stops R_srv and one
 * more original holder to prove live reads succeed via S after CS_OP_REOPEN (`eccache_reopen`). */
static void scen_ecrebuild(void)
{
    scenario("ecrebuild");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#else
    epoll_after_two = 1;
    init_rebuild_after_s = 6;
    for (int i = 0; i < 7; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 7; i++)
        node_add(0, i);
    unsigned want_v = 5;
    await_view(0, p_voters, &want_v, "five voters of seven members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    int voter_srv[7] = {0};
    for (int i = 0; i < 7; i++)
        voter_srv[i] = is_voter(&v, ids[i]) != 0;
    view_free(&v);

    static char xa[7][PATH_MAX + 256];
    static char sdirs[7][PATH_MAX + 96];
    for (int i = 0; i < 7; i++) {
        snprintf(sdirs[i], sizeof sdirs[i], "%s/ecs%d", base, i);
        chunk_store_make(sdirs[i], uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i],
                 "--chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 --merge-idle-s 1 "
                 "--flush-interval-ms 200 --ec-cache-mb 16", sdirs[i]);
        restart_xargs(i, xa[i]);
    }
    unsigned seven = 7;
    await_view(6, p_n_placeable, &seven, "seven members UP with chunk stores");

    uint32_t num = 0, tnum = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ecrebuild: vol_add_ec 4+2: %s (%s)", cluster_strerror(rc), text);
    for (uint64_t t0 = now_ms(); (rc = vol_add(0, "t42", 3, &tnum)) != 0; usleep(100000))
        if (rc != CLUSTER_ERR_NOTLEADER || now_ms() - t0 > 30000)
            die("ecrebuild: twin t42: %s", cluster_strerror(rc));

    struct meta_volume e, tv;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecrebuild: e42 has no leader");
    for (uint64_t t0 = now_ms(); !vol_rec(0, "t42", &tv) || !tv.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecrebuild: t42 has no leader");
    int L = server_of(e.leader), Lt = server_of(tv.leader);
    if (L < 0 || Lt < 0)
        die("ecrebuild: bad leaders L=%d Lt=%d", L, Lt);
    await_isr(L, "e42", 3, 30000, "e42 full ISR before writes");

    /* Write two days so >= 2 .ec objects settle (allowing crash after chunk 1 and resume on chunk 2+). */
    const int64_t day0 = 1704067200000LL;
    tsdbc *c = client(L), *ct = client(Lt);
    tsdb_sid ide[ECB_SERIES], idt[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecr.s%d", s);
        ide[s] = ecb_series(c, nm, "e42");
        idt[s] = ecb_series(ct, nm, "t42");
    }
    ecb_write_day(c, ide, day0);
    ecb_write_day(ct, idt, day0);
    ecb_write_day(c, ide, day0 + 2 * 86400000LL);
    ecb_write_day(ct, idt, day0 + 2 * 86400000LL);

    int nec = 0;
    for (uint64_t t0 = now_ms(); (nec = ecb_ec_parts(L, num)) < 2; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("ecrebuild: only %d .ec part(s) settled within 120 s (need >= 2)", nec);
    char live[1024];
    for (uint64_t t0 = now_ms(); ecb_live_parts(L, num, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("ecrebuild: live .part files still remain: %s", live);
    nec = ecb_ec_parts(L, num);

    struct ecb_sum twin[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++)
        if ((rc = ecb_read(ct, idt[s], &twin[s])) != 0 || twin[s].n != 4 * ECB_ROWS)
            die("ecrebuild: twin read series %d: %s (%" PRIu64 " rows)", s, ers(rc), twin[s].n);
    tsdbc_close(ct);

    /* Find 7th node S (spare not in e.stripe[]), victim V (holder != L, != ml, preferably non-rep/non-voter),
     * rotted survivor R_srv (another holder != V, != S), and extra stoppable holder W (for post-fill read check). */
    int S = -1;
    for (int i = 0; i < 7; i++) {
        int in_s = 0;
        for (uint32_t p = 0; p < e.nstripe; p++)
            in_s |= (e.stripe[p] == ids[i]);
        if (!in_s) {
            S = i;
            break;
        }
    }
    if (S < 0)
        die("ecrebuild: no spare 7th server");
    int ml = leader_of(L);
    int V = -1;
    uint32_t vpos = UINT32_MAX;
    for (int pass = 0; pass < 4 && V < 0; pass++) {
        for (uint32_t p = 0; p < e.nstripe && V < 0; p++) {
            int s = server_of(e.stripe[p]);
            if (s < 0 || s == L || s == ml || s == S)
                continue;
            bool rep = ecb_is_rep(&e, s);
            bool vot = voter_srv[s] != 0;
            bool match = (pass == 0 && !rep && !vot) || (pass == 1 && !rep && vot) ||
                         (pass == 2 && rep && !vot) || (pass == 3 && rep && vot);
            if (match) {
                V = s;
                vpos = p;
            }
        }
    }
    if (V < 0)
        die("ecrebuild: could not pick victim holder");

    int R_srv = -1;
    uint32_t rpos = UINT32_MAX;
    for (int pass = 0; pass < 2 && R_srv < 0; pass++) {
        for (uint32_t p = 0; p < e.nstripe && R_srv < 0; p++) {
            int s = server_of(e.stripe[p]);
            if (s < 0 || s == V || s == S)
                continue;
            if ((pass == 0 && s != L && s != ml) || pass == 1) {
                R_srv = s;
                rpos = p;
            }
        }
    }
    if (R_srv < 0)
        die("ecrebuild: could not pick surviving holder to rot");

    /* Save original chunk files from V BEFORE killing V! */
    struct saved_chunk orig[32];
    memset(orig, 0, sizeof orig);
    int norig = load_vol_chunks(sdirs[V], num, orig, 32);
    if (norig < 2)
        die("ecrebuild: victim srv %d holds only %d chunk(s) of vol %" PRIu32 " (expected >= 2)", V, norig, num);

    /* Rot cell 0 of every chunk on surviving holder R_srv! */
    int nrot = rot_vol_chunks(sdirs[R_srv], num);
    if (nrot < norig)
        die("ecrebuild: only rotted %d chunk(s) on survivor srv %d (expected >= %d)", nrot, R_srv, norig);
    printf("  ecrebuild: %d .ec objects settled; victim srv %d (pos %" PRIu32 ", %d chunks saved), rotted srv %d (pos %" PRIu32 "), spare srv %d\n",
           nec, V, vpos, norig, R_srv, rpos, S);

    /* Arm CP_FILL_WRITTEN on spare S so it crashes right after writing its first rebuilt chunk! */
    penv[S] = "TSDB_CRASH_AT=fill-written:1";
    restart_xargs(S, xa[S]);
    await_view(L, p_n_placeable, &seven, "spare S back UP with fill-written armed");

    /* Kill victim V for good! */
    stop(V, SIGKILL);

    /* Read series 0 while V is DOWN so L's eccache caches the objects degraded (exercises CS_OP_REOPEN after fill). */
    {
        struct ecb_sum a;
        if ((rc = ecb_read(c, ide[0], &a)) != 0 || a.n != twin[0].n || a.h != twin[0].h)
            die("ecrebuild: degraded read while V down: %s (rows %" PRIu64 "/%" PRIu64 ")", ers(rc), a.n, twin[0].n);
    }

    /* Wait for V -> META_OUT (rebuild_after_s = 6 s) and S to crash at CP_FILL_WRITTEN (status 99)! */
    struct state_want out_w = {ids[V], META_OUT, 1};
    await_view(L, p_member_state, &out_w, "victim V marked META_OUT after rebuild_after_s");

    int cst = 0;
    for (uint64_t t0 = now_ms();;) {
        pid_t w = waitpid(pids[S], &cst, WNOHANG);
        if (w == pids[S]) {
            pids[S] = 0;
            break;
        }
        if (now_ms() - t0 > 45000)
            die("ecrebuild: spare S did not hit CP_FILL_WRITTEN within 45 s");
        usleep(50000);
    }
    if (!WIFEXITED(cst) || WEXITSTATUS(cst) != CRASH_EXIT_STATUS)
        die("ecrebuild: spare S exited with status 0x%x (expected %d from CP_FILL_WRITTEN)", cst, CRASH_EXIT_STATUS);
    if (!log_has(S, "crash point fill-written"))
        die("ecrebuild: spare S log missing 'crash point fill-written'");

    /* Verify S wrote at least 1 chunk durably before crashing and pos is still FILLING. */
    struct saved_chunk partial[32];
    memset(partial, 0, sizeof partial);
    int npart = load_vol_chunks(sdirs[S], num, partial, 32);
    for (int i = 0; i < npart; i++)
        free(partial[i].data);
    if (npart < 1)
        die("ecrebuild: spare S wrote 0 chunks before CP_FILL_WRITTEN");

    /* Restart S cleanly (no crash point): fill must resume, skip already-held chunk, finish the rest, and commit STRIPE_WHOLE! */
    penv[S] = NULL;
    start(S);
    struct meta_volume e2 = {0};
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        if (vol_rec(L, "e42", &e2) && e2.stripe[vpos] == ids[S] &&
            e2.stripe_pos[vpos].state == META_STRIPE_WHOLE && e2.stripe_version >= 2)
            break;
        if (now_ms() - t0 > 60000)
            die("ecrebuild: pos %" PRIu32 " on S (node %" PRIu32 ") did not reach STRIPE_WHOLE within 60 s "
                "(cur holder %" PRIu32 " state %u ver %" PRIu64 ")",
                vpos, ids[S], e2.stripe[vpos], e2.stripe_pos[vpos].state, e2.stripe_version);
    }

    /* Compare EVERY rebuilt chunk on S byte-for-byte against the original saved from V! */
    struct saved_chunk rebuilt[32];
    memset(rebuilt, 0, sizeof rebuilt);
    int nreb = load_vol_chunks(sdirs[S], num, rebuilt, 32);
    if (nreb < norig)
        die("ecrebuild: spare S holds only %d rebuilt chunk(s) (expected >= %d)", nreb, norig);
    for (int i = 0; i < norig; i++) {
        int found = -1;
        for (int j = 0; j < nreb; j++)
            if (strcmp(orig[i].name, rebuilt[j].name) == 0) {
                found = j;
                break;
            }
        if (found < 0)
            die("ecrebuild: missing rebuilt chunk %s on S", orig[i].name);
        if (rebuilt[found].len != orig[i].len || memcmp(rebuilt[found].data, orig[i].data, orig[i].len) != 0)
            die("ecrebuild: rebuilt chunk %s on S differs from V's original (%zu vs %zu bytes)",
                orig[i].name, rebuilt[found].len, orig[i].len);
    }
    for (int i = 0; i < norig; i++)
        free(orig[i].data);
    for (int i = 0; i < nreb; i++)
        free(rebuilt[i].data);

    /* Stop one healthy non-S, non-L, non-ml stripe holder W (and also R_srv when quorum permits):
     * because W is killed and R_srv's cell 0 is rotted (fails xxh64 even if R_srv stays up), at most 3 non-S chunks
     * have valid cell 0 (< k=4), so reading ALL series from e42 MUST use S's newly rebuilt chunks and proves
     * CS_OP_REOPEN (`eccache_reopen`). */
    ml = leader_of(L);
    int W = -1;
    for (int pass = 0; pass < 2 && W < 0; pass++) {
        for (uint32_t p = 0; p < e2.nstripe && W < 0; p++) {
            int s = server_of(e2.stripe[p]);
            if (s < 0 || s == L || s == S || s == ml || s == V || s == R_srv)
                continue;
            if (pass == 0 && voter_srv[s])
                continue;
            if (voter_srv[V] + voter_srv[s] <= 2)
                W = s;
        }
    }
    if (W < 0)
        die("ecrebuild: could not pick healthy stripe holder W to stop for post-rebuild read proof");
    stop(W, SIGKILL);
    int voters_down = voter_srv[V] + voter_srv[W];
    if (R_srv != L && R_srv != ml && voters_down + voter_srv[R_srv] <= 2)
        stop(R_srv, SIGKILL);

    for (int s = 0; s < ECB_SERIES; s++) {
        struct ecb_sum a;
        if ((rc = ecb_read(c, ide[s], &a)) != 0)
            die("ecrebuild: post-rebuild read series %d failed: %s", s, ers(rc));
        if (a.n != twin[s].n || a.h != twin[s].h)
            die("ecrebuild: post-rebuild series %d mismatch: %" PRIu64 " rows (%" PRIx64 "), twin %" PRIu64 " (%" PRIx64 ")",
                s, a.n, a.h, twin[s].n, twin[s].h);
    }
    tsdbc_close(c);

    epoll_after_two = 0;
    stop_all();
    printf("  ecrebuild: 4+2 on 7 nodes -> V killed, R_srv rotted, S crashed at fill-written & resumed -> "
           "STRIPE_WHOLE committed (ver %" PRIu64 "), %d/%d rebuilt chunks bit-exact, all %d series read cleanly\n",
           e2.stripe_version, norig, norig, ECB_SERIES);
#endif
}

#ifdef TSDB_EC
#define ECW_SERIES 2
#define ECW_ROWS 32000
#define ECW_INIT_DAYS 30
#define ECW_NEW_DAYS 2
#define ECW_STEP_MS 86400000LL

static int ecw_read_range(tsdbc *c, tsdb_sid id, int64_t t0, int64_t t1, struct ecb_sum *s)
{
    memset(s, 0, sizeof *s);
    return tsdbc_query_raw(c, id, t0, t1, ecb_rows, s);
}

static void ecw_write_days(tsdbc *c, const tsdb_sid *ide, int64_t day0, int first_day, int ndays)
{
    static int64_t ts[ECW_ROWS];
    static float val[ECW_ROWS];
    for (int b = 0; b < 2; b++) {
        for (int d = first_day; d < first_day + ndays; d++) {
            int64_t day_ms = day0 + (int64_t)d * ECW_STEP_MS;
            for (int s = 0; s < ECW_SERIES; s++) {
                for (int r = 0; r < ECW_ROWS; r++) {
                    /* 1 s spacing within each batch -> 86400 rows/day rate locks class 0 (1-day partitions);
                     * 2 batches * 20000 = 40000 rows/series/day stays inside class 0's 2x band (> 32768),
                     * and 2 series * 40000 rows of 26-bit random floats -> ~280 KiB/part (k'=4, npos=6). */
                    ts[r] = day_ms + (int64_t)(2 * r + b) * 500;
                    uint64_t z = ((uint64_t)s << 40 | (uint64_t)b << 32 | (uint64_t)r) +
                                 (uint64_t)day_ms * 0x2545f4914f6cdd1dull + 0x9e3779b97f4a7c15ull;
                    z = (z ^ z >> 30) * 0xbf58476d1ce4e5b9ull;
                    z = (z ^ z >> 27) * 0x94d049bb133111ebull;
                    z ^= z >> 31;
                    uint32_t bits = (uint32_t)(z & 0x7fffffu) | (uint32_t)(127 + (z >> 61)) << 23;
                    memcpy(&val[r], &bits, 4);
                }
                int rc;
                for (uint64_t t0 = now_ms(); (rc = tsdbc_insert_series(c, ide[s], ts, val, ECW_ROWS)) != 0;
                     usleep(50000))
                    if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                        die("ecwhole: insert day %d series %d: %s", d, s, ers(rc));
            }
            /* Flush day 0 batch 0 by itself so decide_fresh sees 86400 rows/day and locks class 0 (1-day parts). */
            if (b == 0 && first_day == 0 && d == 0)
                usleep(500000);
        }
        usleep(600000); /* past flush_interval_ms=200 */
    }
}

static int ecw_count_vol_chunks(const char *sdir, uint32_t vol)
{
    char vdir[PATH_MAX + 128];
    snprintf(vdir, sizeof vdir, "%s/s%" PRIu32, sdir, vol);
    DIR *d = opendir(vdir);
    if (!d)
        return 0;
    int n = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        size_t nl = strlen(de->d_name);
        if (de->d_name[0] == 'o' && nl >= 8 && strcmp(de->d_name + nl - 6, ".chunk") == 0)
            n++;
    }
    closedir(d);
    return n;
}

static int ecw_count_pos_chunks(const char *sdir, uint32_t vol, uint32_t pos)
{
    char vdir[PATH_MAX + 128], suf[32];
    snprintf(vdir, sizeof vdir, "%s/s%" PRIu32, sdir, vol);
    snprintf(suf, sizeof suf, ".%" PRIu32 ".chunk", pos);
    size_t sl = strlen(suf);
    DIR *d = opendir(vdir);
    if (!d)
        return 0;
    int n = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        size_t nl = strlen(de->d_name);
        if (de->d_name[0] == 'o' && nl > sl && strcmp(de->d_name + nl - sl, suf) == 0)
            n++;
    }
    closedir(d);
    return n;
}

/* Copy one chunk file of `vol` from `src_sdir` into `dst_sdir` (at another position != vpos) so we verify
 * MK_GC_RELEASE deletes ONLY the released `(vol, vpos)` chunks and leaves other positions of `vol` intact. */
static bool ecw_copy_one_chunk(const char *src_sdir, const char *dst_sdir, uint32_t vol, char out_name[128])
{
    char sdir[PATH_MAX + 128], ddir[PATH_MAX + 128];
    snprintf(sdir, sizeof sdir, "%s/s%" PRIu32, src_sdir, vol);
    snprintf(ddir, sizeof ddir, "%s/s%" PRIu32, dst_sdir, vol);
    DIR *d = opendir(sdir);
    if (!d)
        return false;
    bool copied = false;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        size_t nl = strlen(de->d_name);
        if (de->d_name[0] != 'o' || nl < 8 || strcmp(de->d_name + nl - 6, ".chunk") != 0)
            continue;
        char sp[PATH_MAX + 256], dp[PATH_MAX + 256];
        snprintf(sp, sizeof sp, "%s/%s", sdir, de->d_name);
        snprintf(dp, sizeof dp, "%s/%s", ddir, de->d_name);
        int in = open(sp, O_RDONLY);
        if (in < 0)
            continue;
        int out = open(dp, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (out >= 0) {
            uint8_t buf[65536];
            ssize_t r;
            bool ok = true;
            while ((r = read(in, buf, sizeof buf)) > 0) {
                if (write(out, buf, (size_t)r) != r) {
                    ok = false;
                    break;
                }
            }
            if (r == 0 && ok && fsync(out) == 0) {
                snprintf(out_name, 128, "%s", de->d_name);
                copied = true;
            }
            close(out);
        }
        close(in);
        if (copied)
            break;
    }
    closedir(d);
    return copied;
}

/* Toggle 1 byte every 2 KiB in cell 0 (offset 96..96+65536) for every chunk of `vol` in `sdir_target`
 * whose filename is NOT present in `sdir_filled`. Self-inverting: calling twice restores original bytes. */
static int ecw_flip_unfilled(const char *sdir_target, const char *sdir_filled, uint32_t vol)
{
    char vdir[PATH_MAX + 128], fdir[PATH_MAX + 128];
    snprintf(vdir, sizeof vdir, "%s/s%" PRIu32, sdir_target, vol);
    snprintf(fdir, sizeof fdir, "%s/s%" PRIu32, sdir_filled, vol);
    DIR *d = opendir(vdir);
    if (!d)
        return 0;
    int n = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        size_t nl = strlen(de->d_name);
        if (de->d_name[0] != 'o' || nl < 8 || strcmp(de->d_name + nl - 6, ".chunk") != 0)
            continue;
        char fchk[PATH_MAX + 256];
        snprintf(fchk, sizeof fchk, "%s/%s", fdir, de->d_name);
        if (access(fchk, F_OK) == 0)
            continue; /* already filled on B */
        char fp[PATH_MAX + 256];
        snprintf(fp, sizeof fp, "%s/%s", vdir, de->d_name);
        int fd = open(fp, O_RDWR);
        if (fd < 0)
            continue;
        struct stat st;
        if (fstat(fd, &st) == 0 && st.st_size > 256) {
            off_t lim = st.st_size - 64;
            if (lim > 96 + 65536)
                lim = 96 + 65536;
            bool ok = true;
            for (off_t off = 96; off < lim; off += 2048) {
                uint8_t b = 0;
                if (pread(fd, &b, 1, off) != 1) {
                    ok = false;
                    break;
                }
                b ^= 0xffu;
                if (pwrite(fd, &b, 1, off) != 1) {
                    ok = false;
                    break;
                }
            }
            if (ok && fsync(fd) == 0)
                n++;
        }
        close(fd);
    }
    closedir(d);
    return n;
}
#endif

/* ecwhole (r9-whole): 4+2 on 7 nodes with 30 settled objects paced slowly during fill.
 * Verifies:
 *   1. STRIPE_WHOLE does NOT commit while fill is in progress (kills wholeearly).
 *   2. New settles during fill write directly to B (S) while pos stays FILLING.
 *   3. Reads of pre-barrier unfilled objects while A (V) is DOWN treat pos as CHUNK_ST_DOWN erasure and never ask B
 *      for an unfilled object (kills readfromfilling).
 *   4. CP_WHOLE_PROPOSED fires when B finishes the last old object; STRIPE_WHOLE commits at barrier version V.
 *   5. When A (V) returns UP, leader verifies B's CHUNK_LIST against OBJLIST, commits MK_GC_RELEASE (hitting
 *      CP_RELEASE_GC -> kills releasenomark), resumes from durable GCMK, and deletes ONLY (e42, vpos) chunks on V
 *      while leaving sibling volume e42b's chunks on V intact.
 *   6. All 32 days of e42 match the replicas=3 oracle t42 throughout and at the end. */
static void scen_ecwhole(void)
{
    scenario("ecwhole");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#else
    epoll_after_two = 1;
    init_rebuild_after_s = 6;
    for (int i = 0; i < 7; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 7; i++)
        node_add(0, i);
    unsigned want_v = 5;
    await_view(0, p_voters, &want_v, "five voters of seven members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    int voter_srv[7] = {0};
    for (int i = 0; i < 7; i++)
        voter_srv[i] = is_voter(&v, ids[i]) != 0;
    view_free(&v);

    static char xa[7][PATH_MAX + 256];
    static char sdirs[7][PATH_MAX + 96];
    for (int i = 0; i < 7; i++) {
        snprintf(sdirs[i], sizeof sdirs[i], "%s/ecs%d", base, i);
        chunk_store_make(sdirs[i], uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i],
                 "--chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 --merge-idle-s 1 "
                 "--flush-interval-ms 200 --ec-cache-mb 16", sdirs[i]);
        restart_xargs(i, xa[i]);
    }
    unsigned seven = 7;
    await_view(6, p_n_placeable, &seven, "seven members UP with chunk stores");

    uint32_t num = 0, num_b = 0, tnum = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ecwhole: vol_add_ec e42: %s (%s)", cluster_strerror(rc), text);
    /* e42b uses ec=5+2 across all 7 nodes (no spare), so V remains its holder across V's OUT and its chunks on V
     * must stay untouched when e42 releases (num, vpos). */
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42b", 0, 5, 2, &num_b, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ecwhole: vol_add_ec e42b: %s (%s)", cluster_strerror(rc), text);
    for (uint64_t t0 = now_ms(); (rc = vol_add(0, "t42", 3, &tnum)) != 0; usleep(100000))
        if (rc != CLUSTER_ERR_NOTLEADER || now_ms() - t0 > 30000)
            die("ecwhole: twin t42: %s", cluster_strerror(rc));

    struct meta_volume e, eb, tv;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecwhole: e42 has no leader");
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42b", &eb) || !eb.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecwhole: e42b has no leader");
    for (uint64_t t0 = now_ms(); !vol_rec(0, "t42", &tv) || !tv.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecwhole: t42 has no leader");
    int L = server_of(e.leader), Lb = server_of(eb.leader), Lt = server_of(tv.leader);
    if (L < 0 || Lb < 0 || Lt < 0)
        die("ecwhole: bad leaders L=%d Lb=%d Lt=%d", L, Lb, Lt);
    await_isr(L, "e42", 3, 30000, "e42 full ISR before writes");
    await_isr(Lb, "e42b", 3, 30000, "e42b full ISR before writes");
    await_isr(Lt, "t42", 3, 30000, "t42 full ISR before writes");

    const int64_t day0 = 1704067200000LL;
    tsdbc *c = client(L), *cb = client(Lb), *ct = client(Lt);
    tsdb_sid ide[ECW_SERIES], idb[ECW_SERIES], idt[ECW_SERIES];
    for (int s = 0; s < ECW_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecw.s%d", s);
        ide[s] = ecb_series(c, nm, "e42");
        idt[s] = ecb_series(ct, nm, "t42");
        snprintf(nm, sizeof nm, "ecwb.s%d", s);
        idb[s] = ecb_series(cb, nm, "e42b");
    }
    ecw_write_days(c, ide, day0, 0, ECW_INIT_DAYS);
    ecw_write_days(ct, idt, day0, 0, ECW_INIT_DAYS);
    /* Write two disjoint halves of day 0 into e42b (~520 KiB > 4*64 KiB) so k'=5 and all 7 nodes hold a chunk. */
    ecw_write_days(cb, idb, day0, 0, 1);
    ecw_write_days(cb, idb, day0 + 40000000LL, 0, 1);

    int nec = 0;
    for (uint64_t t0 = now_ms(); (nec = ecb_ec_parts(L, num)) < ECW_INIT_DAYS; usleep(250000))
        if (now_ms() - t0 > 180000)
            die("ecwhole: only %d/%d .ec parts settled on e42 within 180 s", nec, ECW_INIT_DAYS);
    char live[1024];
    for (uint64_t t0 = now_ms(); ecb_live_parts(L, num, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("ecwhole: live .part files still remain on e42: %s", live);
    nec = ecb_ec_parts(L, num);
    for (uint64_t t0 = now_ms(); ecb_ec_parts(Lb, num_b) < 1; usleep(200000))
        if (now_ms() - t0 > 60000)
            die("ecwhole: e42b did not settle 1 .ec part within 60 s");
    for (uint64_t t0 = now_ms(); ecb_live_parts(Lb, num_b, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 60000)
            die("ecwhole: live .part files still remain on e42b: %s", live);

    struct ecb_sum base_b[ECW_SERIES];
    for (int s = 0; s < ECW_SERIES; s++)
        if ((rc = ecb_read(cb, idb[s], &base_b[s])) != 0 || base_b[s].n != 4 * ECW_ROWS)
            die("ecwhole: e42b baseline read series %d: %s (%" PRIu64 " rows)", s, ers(rc), base_b[s].n);

    /* Pick spare 7th server S, victim V (in both e42 and e42b, non-leader, preferably !rep && !voter),
     * and two surviving holders R1, R2 of e42 (!= V, != S). */
    if (!vol_rec(L, "e42", &e) || !vol_rec(Lb, "e42b", &eb))
        die("ecwhole: lost vol_rec for e42/e42b");
    int S = -1;
    for (int i = 0; i < 7; i++) {
        int in_s = 0;
        for (uint32_t p = 0; p < e.nstripe; p++)
            in_s |= (e.stripe[p] == ids[i]);
        if (!in_s) {
            S = i;
            break;
        }
    }
    if (S < 0)
        die("ecwhole: no spare 7th server");
    int ml = leader_of(L);
    int V = -1;
    uint32_t vpos = UINT32_MAX;
    for (int pass = 0; pass < 4 && V < 0; pass++) {
        for (uint32_t p = 0; p < e.nstripe && V < 0; p++) {
            int s = server_of(e.stripe[p]);
            if (s < 0 || s == L || s == Lb || s == ml || s == S)
                continue;
            bool in_b = false;
            for (uint32_t bp = 0; bp < eb.nstripe; bp++)
                in_b |= (eb.stripe[bp] == ids[s]);
            if (!in_b)
                continue;
            bool rep = ecb_is_rep(&e, s) || ecb_is_rep(&eb, s);
            bool vot = voter_srv[s] != 0;
            bool match = (pass == 0 && !rep && !vot) || (pass == 1 && !rep && vot) ||
                         (pass == 2 && rep && !vot) || (pass == 3 && rep && vot);
            if (match) {
                V = s;
                vpos = p;
            }
        }
    }
    if (V < 0)
        die("ecwhole: could not pick victim holder in both e42 and e42b");

    int R1 = -1, R2 = -1;
    for (int pass = 0; pass < 2 && R2 < 0; pass++) {
        for (uint32_t p = 0; p < e.nstripe && R2 < 0; p++) {
            int s = server_of(e.stripe[p]);
            if (s < 0 || s == V || s == S || s == R1)
                continue;
            if ((pass == 0 && s != L && s != ml) || pass == 1) {
                if (R1 < 0)
                    R1 = s;
                else
                    R2 = s;
            }
        }
    }
    if (R1 < 0 || R2 < 0)
        die("ecwhole: could not pick two surviving holders R1/R2");

    int norig = ecw_count_vol_chunks(sdirs[V], num);
    int norig_b = ecw_count_vol_chunks(sdirs[V], num_b);
    if (norig < ECW_INIT_DAYS)
        die("ecwhole: victim srv %d holds %d chunks of e42 (expected >= %d)", V, norig, ECW_INIT_DAYS);
    if (norig_b < 1)
        die("ecwhole: victim srv %d holds %d chunks of e42b (expected >= 1)", V, norig_b);
    printf("  ecwhole: %d e42 objects settled; victim srv %d (pos %" PRIu32 ", %d e42 chunks, %d e42b chunks), "
           "spare srv %d, survivors R1=%d R2=%d\n", nec, V, vpos, norig, norig_b, S, R1, R2);

    /* Arm CP_WHOLE_PROPOSED (gated by whole_arm file) on all voters, and pace+pause fill after 5 objects on S. */
    char pause_file[PATH_MAX + 96], whole_arm[PATH_MAX + 96], rel_arm[PATH_MAX + 96];
    snprintf(pause_file, sizeof pause_file, "%s/ecwhole.pause", base);
    snprintf(whole_arm, sizeof whole_arm, "%s/ecwhole.whole_arm", base);
    snprintf(rel_arm, sizeof rel_arm, "%s/ecwhole.rel_arm", base);
    int pfd = open(pause_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (pfd < 0)
        die("ecwhole: create %s: %s", pause_file, strerror(errno));
    close(pfd);
    unlink(whole_arm);
    unlink(rel_arm);

    static char pbuf[7][PATH_MAX * 2 + 256];
    for (int i = 0; i < 7; i++) {
        pbuf[i][0] = 0;
        if (i == S && voter_srv[i])
            snprintf(pbuf[i], sizeof pbuf[i],
                     "TSDB_SFILL_TEST=obj_delay_ms=25,pause_after=5:%s TSDB_CRASH_AT=whole-proposed:1@%s",
                     pause_file, whole_arm);
        else if (i == S)
            snprintf(pbuf[i], sizeof pbuf[i], "TSDB_SFILL_TEST=obj_delay_ms=25,pause_after=5:%s", pause_file);
        else if (voter_srv[i] && i != V)
            snprintf(pbuf[i], sizeof pbuf[i], "TSDB_CRASH_AT=whole-proposed:1@%s", whole_arm);
        if (pbuf[i][0]) {
            penv[i] = pbuf[i];
            restart_xargs(i, xa[i]);
            await_view(i, p_n_placeable, &seven, "restarted member back UP");
        }
    }
    tsdbc_close(c);
    tsdbc_close(cb);
    tsdbc_close(ct);
    for (uint64_t t0 = now_ms(); !vol_rec(S, "e42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecwhole: e42 has no leader after arm");
    for (uint64_t t0 = now_ms(); !vol_rec(S, "e42b", &eb) || !eb.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecwhole: e42b has no leader after arm");
    for (uint64_t t0 = now_ms(); !vol_rec(S, "t42", &tv) || !tv.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecwhole: t42 has no leader after arm");
    L = server_of(e.leader);
    Lb = server_of(eb.leader);
    Lt = server_of(tv.leader);
    await_isr(L, "e42", 3, 30000, "e42 ISR after arm");
    await_isr(Lt, "t42", 3, 30000, "t42 ISR after arm");
    c = client(L);
    ct = client(Lt);

    /* Kill victim V -> V goes META_OUT -> STRIPE_SET(S, FILLING) -> S fills 5 objects and pauses! */
    stop(V, SIGKILL);
    struct state_want out_w = {ids[V], META_OUT, 1};
    await_view(L, p_member_state, &out_w, "victim V marked META_OUT");

    struct meta_volume e2 = {0};
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        if (vol_rec(L, "e42", &e2) && e2.stripe[vpos] == ids[S] && e2.stripe_version >= 2)
            break;
        if (now_ms() - t0 > 30000)
            die("ecwhole: STRIPE_SET did not assign pos %" PRIu32 " to S within 30 s", vpos);
    }
    uint64_t barrier_ver = e2.stripe_pos[vpos].set_ver ? e2.stripe_pos[vpos].set_ver : e2.stripe_version;
    for (uint64_t t0 = now_ms(); ecw_count_vol_chunks(sdirs[S], num) < 5; usleep(100000))
        if (now_ms() - t0 > 45000)
            die("ecwhole: spare S filled only %d chunks within 45 s (expected >= 5)",
                ecw_count_vol_chunks(sdirs[S], num));

    /* Check 1 (kills wholeearly): after 1.5 s paused at 5/30 chunks, pos MUST still be META_STRIPE_FILLING! */
    usleep(1500000);
    if (!vol_rec(L, "e42", &e2))
        die("ecwhole: lost e42 record mid-fill");
    int n_mid = ecw_count_vol_chunks(sdirs[S], num);
    if (e2.stripe_pos[vpos].state != META_STRIPE_FILLING)
        die("ecwhole: pos %" PRIu32 " became state %u (expected META_STRIPE_FILLING=%u) while S held only %d/%d chunks",
            vpos, e2.stripe_pos[vpos].state, META_STRIPE_FILLING, n_mid, norig);
    if (e2.stripe_pos[vpos].prev != ids[V])
        die("ecwhole: pos %" PRIu32 " prev=%" PRIu32 " (expected V=%" PRIu32 ")", vpos, e2.stripe_pos[vpos].prev, ids[V]);

    /* Check 2: settle 2 NEW days during fill -> chunks go directly to B (S), pos stays FILLING, reads match oracle. */
    ecw_write_days(c, ide, day0, ECW_INIT_DAYS, ECW_NEW_DAYS);
    ecw_write_days(ct, idt, day0, ECW_INIT_DAYS, ECW_NEW_DAYS);
    for (uint64_t t0 = now_ms(); ecb_ec_parts(L, num) < nec + ECW_NEW_DAYS; usleep(200000))
        if (now_ms() - t0 > 90000)
            die("ecwhole: new days during fill did not settle within 90 s (%d/%d)", ecb_ec_parts(L, num),
                nec + ECW_NEW_DAYS);
    for (uint64_t t0 = now_ms(); ecb_live_parts(L, num, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 60000)
            die("ecwhole: live .part files remain after mid-fill settle: %s", live);
    int n_after_new = ecw_count_vol_chunks(sdirs[S], num);
    if (n_after_new < n_mid + ECW_NEW_DAYS)
        die("ecwhole: new settles during fill did not land on B (S has %d chunks, expected >= %d)",
            n_after_new, n_mid + ECW_NEW_DAYS);
    if (!vol_rec(L, "e42", &e2) || e2.stripe_pos[vpos].state != META_STRIPE_FILLING)
        die("ecwhole: pos %" PRIu32 " left FILLING (state %u) before old objects finished",
            vpos, e2.stripe_pos[vpos].state);
    for (int d = ECW_INIT_DAYS; d < ECW_INIT_DAYS + ECW_NEW_DAYS; d++) {
        int64_t d0 = day0 + (int64_t)d * ECW_STEP_MS, d1 = d0 + 86400000LL;
        for (int s = 0; s < ECW_SERIES; s++) {
            struct ecb_sum a, b;
            if ((rc = ecw_read_range(c, ide[s], d0, d1, &a)) != 0 ||
                (rc = ecw_read_range(ct, idt[s], d0, d1, &b)) != 0 || a.n != b.n || a.h != b.h)
                die("ecwhole: mid-fill new day %d series %d mismatch (rc=%s, %" PRIu64 "/%" PRIu64 ")",
                    d, s, ers(rc), a.n, b.n);
        }
    }

    /* Check 3 (kills readfromfilling): rot cell 0 on R1 & R2 for all unfilled old objects while V is DOWN.
     * Normal code marks vpos as CHUNK_ST_DOWN (erasure) without asking B -> ngood(3) + down(1) == k(4) -> UNAVAILABLE.
     * Under readfromfilling, asking B gets NOTFOUND (CHUNK_ST_ABSENT) -> ngood(3) + down(0) < 4 -> CORRUPT! */
    int f1 = ecw_flip_unfilled(sdirs[R1], sdirs[S], num);
    int f2 = ecw_flip_unfilled(sdirs[R2], sdirs[S], num);
    if (f1 < 20 || f2 < 20)
        die("ecwhole: expected >= 20 unfilled chunks to rot on R1/R2 (got %d, %d)", f1, f2);
    int n_unavail = 0, n_corrupt = 0, corrupt_day = -1;
    for (int d = 0; d < 10 && n_unavail < 2 && n_corrupt == 0; d++) {
        int64_t d0 = day0 + (int64_t)d * ECW_STEP_MS, d1 = d0 + 86400000LL;
        for (int s = 0; s < ECW_SERIES; s++) {
            struct ecb_sum a;
            rc = ecw_read_range(c, ide[s], d0, d1, &a);
            if (rc == TSDB_ERR_CORRUPT) {
                n_corrupt++;
                corrupt_day = d;
                break;
            }
            if (rc == TSDB_ERR_UNAVAILABLE) {
                n_unavail++;
                break;
            }
        }
    }
    /* Always restore R1 & R2 before checking results. */
    if (ecw_flip_unfilled(sdirs[R1], sdirs[S], num) != f1 || ecw_flip_unfilled(sdirs[R2], sdirs[S], num) != f2)
        die("ecwhole: failed to restore rotted unfilled chunks on R1/R2");
    if (n_corrupt > 0)
        die("ecwhole: mid-fill read of unfilled day %d returned CORRUPT (must treat filling pos as DOWN/UNAVAILABLE, "
            "never ask B for an unfilled object)", corrupt_day);
    if (n_unavail < 1)
        die("ecwhole: expected >= 1 UNAVAILABLE read while V DOWN and R1/R2 rotted (got 0)");

    /* Check 4: with R1 & R2 restored, old days still read cleanly via RS decode while V is DOWN and S is FILLING. */
    for (int d = 0; d < 5; d++) {
        int64_t d0 = day0 + (int64_t)d * ECW_STEP_MS, d1 = d0 + 86400000LL;
        struct ecb_sum a, b;
        if ((rc = ecw_read_range(c, ide[0], d0, d1, &a)) != 0 ||
            (rc = ecw_read_range(ct, idt[0], d0, d1, &b)) != 0 || a.n != b.n || a.h != b.h)
            die("ecwhole: mid-fill old day %d read mismatch (rc=%s, %" PRIu64 "/%" PRIu64 ")", d, ers(rc), a.n, b.n);
    }

    /* Check 5: arm whole_arm, unpause S -> S finishes remaining 25 objects -> Raft leader hits CP_WHOLE_PROPOSED! */
    int wfd = open(whole_arm, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (wfd < 0)
        die("ecwhole: create %s: %s", whole_arm, strerror(errno));
    close(wfd);
    unlink(pause_file);

    int v_hit = -1, cst = 0;
    for (uint64_t t0 = now_ms(); v_hit < 0;) {
        for (int i = 0; i < 7; i++) {
            if (!voter_srv[i] || i == V || pids[i] <= 0)
                continue;
            pid_t w = waitpid(pids[i], &cst, WNOHANG);
            if (w == pids[i]) {
                pids[i] = 0;
                v_hit = i;
                break;
            }
        }
        if (v_hit >= 0)
            break;
        if (now_ms() - t0 > 60000)
            die("ecwhole: no voter hit CP_WHOLE_PROPOSED within 60 s (S has %d/%d chunks)",
                ecw_count_vol_chunks(sdirs[S], num), norig + ECW_NEW_DAYS);
        usleep(50000);
    }
    if (!WIFEXITED(cst) || WEXITSTATUS(cst) != CRASH_EXIT_STATUS)
        die("ecwhole: voter %d exited with status 0x%x (expected %d from CP_WHOLE_PROPOSED)",
            v_hit, cst, CRASH_EXIT_STATUS);
    if (!log_has(v_hit, "crash point whole-proposed"))
        die("ecwhole: voter %d log missing 'crash point whole-proposed'", v_hit);
    unlink(whole_arm);
    penv[v_hit] = NULL;
    start(v_hit);
    {
        struct state_want vh_up = {ids[v_hit], META_UP, 1};
        await_view(S, p_member_state, &vh_up, "restarted whole-proposed voter back UP");
    }

    /* Wait for STRIPE_WHOLE to commit at barrier_ver and verify S holds all 32 chunks. */
    struct meta_volume e3 = {0};
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        if (vol_rec(S, "e42", &e3) && e3.stripe[vpos] == ids[S] &&
            e3.stripe_pos[vpos].state == META_STRIPE_WHOLE)
            break;
        if (now_ms() - t0 > 60000)
            die("ecwhole: pos %" PRIu32 " did not reach STRIPE_WHOLE within 60 s (state %u)",
                vpos, e3.stripe_pos[vpos].state);
    }
    if (e3.stripe_pos[vpos].set_ver != barrier_ver)
        die("ecwhole: STRIPE_WHOLE set_ver %" PRIu64 " != barrier %" PRIu64, e3.stripe_pos[vpos].set_ver, barrier_ver);
    int n_whole = ecw_count_vol_chunks(sdirs[S], num);
    if (n_whole != norig + ECW_NEW_DAYS)
        die("ecwhole: S holds %d chunks at STRIPE_WHOLE (expected %d)", n_whole, norig + ECW_NEW_DAYS);

    /* Check 6 (kills releasenomark): arm CP_RELEASE_GC on e42's leader (and new leader if leadership moves
     * during restart) while V is still DOWN, then bring V back UP -> leader commits MK_GC_RELEASE (hits
     * CP_RELEASE_GC) -> resumes from GCMK -> deletes ONLY V's chunks of (e42, vpos) while keeping both the
     * other-position sentinel chunk of e42 and V's chunks of sibling e42b! */
    int rfd = open(rel_arm, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (rfd < 0)
        die("ecwhole: create %s: %s", rel_arm, strerror(errno));
    close(rfd);
    for (int i = 0; i < 7; i++)
        penv[i] = NULL;
    int armed_reps[3] = {-1, -1, -1}, narmed = 0;
    for (int attempt = 0; attempt < 3; attempt++) {
        for (uint64_t t0 = now_ms(); !vol_rec(S, "e42", &e3) || !e3.leader; usleep(50000))
            if (now_ms() - t0 > 30000)
                die("ecwhole: e42 has no leader before arming release-gc");
        int cur_l = server_of(e3.leader);
        if (cur_l < 0 || cur_l == V)
            die("ecwhole: bad e42 leader %d before release-gc", cur_l);
        bool already = false;
        for (int k = 0; k < narmed; k++)
            already |= (armed_reps[k] == cur_l);
        if (already)
            break;
        snprintf(pbuf[cur_l], sizeof pbuf[cur_l], "TSDB_CRASH_AT=release-gc:1@%s", rel_arm);
        penv[cur_l] = pbuf[cur_l];
        /* SIGKILL + immediate restart keeps downtime (~150 ms) well below node_timeout_ms (1500 ms) and
         * rebuild_after_s (6 s); retry once if the new incarnation raced an old heartbeat timeout. */
        int vpeer = cur_l == S ? (R1 != cur_l ? R1 : R2) : S;
        for (int tries = 0; tries < 2; tries++) {
            struct view cv;
            view(vpeer, &cv);
            const struct meta_member *mb = meta_member(&cv.m, ids[cur_l]);
            uint64_t next_inc = mb ? mb->incarnation + 1 : 1;
            view_free(&cv);
            stop(cur_l, SIGKILL);
            xargs[cur_l] = xa[cur_l];
            start(cur_l);
            bool up_ok = false;
            for (uint64_t t0 = now_ms(); now_ms() - t0 < 10000; usleep(100000)) {
                view(vpeer, &cv);
                mb = meta_member(&cv.m, ids[cur_l]);
                bool is_up = mb && mb->state == META_UP && mb->incarnation >= next_inc;
                bool is_down = mb && mb->state != META_UP && mb->incarnation >= next_inc;
                view_free(&cv);
                if (is_up) {
                    up_ok = true;
                    break;
                }
                if (is_down && now_ms() - t0 > 500)
                    break;
            }
            if (up_ok)
                break;
            if (tries == 1)
                die("ecwhole: e42 leader %d did not return UP with release-gc armed", cur_l);
        }
        armed_reps[narmed++] = cur_l;
    }
    tsdbc_close(c);
    tsdbc_close(ct);

    /* Plant one chunk of e42 at a DIFFERENT position (from R1) into V's store while V is still DOWN,
     * to verify MK_GC_RELEASE deletes ONLY (num, vpos) and leaves other positions of the SAME volume untouched. */
    char sentinel_name[128] = {0};
    if (!ecw_copy_one_chunk(sdirs[R1], sdirs[V], num, sentinel_name))
        die("ecwhole: failed to plant other-position sentinel chunk into V");

    /* Bring victim V back UP! */
    penv[V] = NULL;
    start(V);
    struct state_want vw = {ids[V], META_UP, 1};
    await_view(S, p_member_state, &vw, "victim V returned META_UP");

    int r_hit = -1;
    cst = 0;
    for (uint64_t t0 = now_ms(); r_hit < 0;) {
        for (int k = 0; k < narmed; k++) {
            int rs = armed_reps[k];
            if (pids[rs] <= 0)
                continue;
            pid_t w = waitpid(pids[rs], &cst, WNOHANG);
            if (w == pids[rs]) {
                pids[rs] = 0;
                r_hit = rs;
                break;
            }
        }
        if (r_hit >= 0)
            break;
        if (now_ms() - t0 > 45000)
            die("ecwhole: no e42 replica hit CP_RELEASE_GC within 45 s (V has %d pos-%" PRIu32 " chunks left)",
                ecw_count_pos_chunks(sdirs[V], num, vpos), vpos);
        usleep(50000);
    }
    if (!WIFEXITED(cst) || WEXITSTATUS(cst) != CRASH_EXIT_STATUS)
        die("ecwhole: e42 replica %d exited with status 0x%x (expected %d from CP_RELEASE_GC)",
            r_hit, cst, CRASH_EXIT_STATUS);
    if (!log_has(r_hit, "crash point release-gc"))
        die("ecwhole: e42 replica %d log missing 'crash point release-gc'", r_hit);
    unlink(rel_arm);
    penv[r_hit] = NULL;
    start(r_hit);

    /* Wait for V's chunks of (e42, vpos) to be released to 0 (completed from durable GCMK after CP_RELEASE_GC!). */
    for (uint64_t t0 = now_ms(); ecw_count_pos_chunks(sdirs[V], num, vpos) != 0; usleep(100000))
        if (now_ms() - t0 > 45000)
            die("ecwhole: victim V still holds %d chunks of (e42, pos %" PRIu32 ") after release (expected 0)",
                ecw_count_pos_chunks(sdirs[V], num, vpos), vpos);
    char sentinel_path[PATH_MAX + 256];
    snprintf(sentinel_path, sizeof sentinel_path, "%s/s%" PRIu32 "/%s", sdirs[V], num, sentinel_name);
    if (access(sentinel_path, F_OK) != 0)
        die("ecwhole: release of (e42, pos %" PRIu32 ") deleted other-position sentinel chunk %s on V", vpos,
            sentinel_name);
    int v_left_b = ecw_count_vol_chunks(sdirs[V], num_b);
    if (v_left_b != norig_b)
        die("ecwhole: release touched sibling volume e42b on V (%d chunks left, expected %d)", v_left_b, norig_b);
    if (ecw_count_vol_chunks(sdirs[S], num) != norig + ECW_NEW_DAYS)
        die("ecwhole: S lost chunks after release (%d left, expected %d)",
            ecw_count_vol_chunks(sdirs[S], num), norig + ECW_NEW_DAYS);

    /* Final oracle verification: all 32 days of e42 match t42, and e42b matches its baseline. */
    for (uint64_t t0 = now_ms(); !vol_rec(S, "e42", &e3) || !e3.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecwhole: e42 has no leader at end");
    for (uint64_t t0 = now_ms(); !vol_rec(S, "e42b", &eb) || !eb.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecwhole: e42b has no leader at end");
    for (uint64_t t0 = now_ms(); !vol_rec(S, "t42", &tv) || !tv.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecwhole: t42 has no leader at end");
    L = server_of(e3.leader);
    Lb = server_of(eb.leader);
    Lt = server_of(tv.leader);
    c = client(L);
    cb = client(Lb);
    ct = client(Lt);
    uint64_t expect_rows = (uint64_t)(ECW_INIT_DAYS + ECW_NEW_DAYS) * 2u * ECW_ROWS;
    for (int s = 0; s < ECW_SERIES; s++) {
        struct ecb_sum a, b;
        if ((rc = ecb_read(c, ide[s], &a)) != 0 || (rc = ecb_read(ct, idt[s], &b)) != 0)
            die("ecwhole: final read series %d failed: %s", s, ers(rc));
        if (a.n != expect_rows || a.n != b.n || a.h != b.h)
            die("ecwhole: final series %d mismatch: %" PRIu64 " (%" PRIx64 "), twin %" PRIu64 " (%" PRIx64 ")",
                s, a.n, a.h, b.n, b.h);
        if ((rc = ecb_read(cb, idb[s], &a)) != 0 || a.n != base_b[s].n || a.h != base_b[s].h)
            die("ecwhole: final e42b series %d mismatch: %s (%" PRIu64 "/%" PRIu64 ")",
                s, ers(rc), a.n, base_b[s].n);
    }
    tsdbc_close(c);
    tsdbc_close(cb);
    tsdbc_close(ct);

    for (int i = 0; i < 7; i++)
        penv[i] = NULL;
    epoll_after_two = 0;
    stop_all();
    printf("  ecwhole: 30+2 objects, paced fill, mid-fill settles->B, filling reads->DOWN, whole-proposed & "
           "STRIPE_WHOLE(ver %" PRIu64 "), release-gc & V released (0 e42 / %d e42b chunks), all %d series match oracle\n",
           barrier_ver, v_left_b, ECW_SERIES);
#endif
}

/* ---- r9-ops: operator CLI verbs (node hold/out/drain/replace/destroyed, volume move --pos) and STATUS details */

/* nodehold (r9-ops): `tsdb cluster node hold` keeps a DOWN node from going OUT past rebuild_after_s=4, STATUS prints
 * down_reason/down_age/out_in/hold_left (and guard when active), `--release` lets it go OUT, and a 2-day hold is
 * refused both by the CLI and on the wire. */
static void scen_nodehold(void)
{
    scenario("nodehold");
    init_rebuild_after_s = 4;
    init_out_guard_pct = 25;
    pout_boot5();

    char p0[META_ADDR_MAX], p1[META_ADDR_MAX], args[PATH_MAX * 2 + 256], out[16384];
    peer_of(0, p0, sizeof p0);
    peer_of(1, p1, sizeof p1);

    /* 2-day hold refused by CLI (exit 2) and on the wire (META_ERR_INVALID). */
    snprintf(args, sizeof args, "cluster node hold %s %" PRIu32 " --for 2d --secret-file %s", p0, ids[4], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 2)
        die("nodehold: 2d CLI hold was not refused with exit 2: %s", out);
    uint8_t hreq[12], *hrep = NULL;
    size_t hlen = 0, hrl = cluster_node_hold_encode(ids[4], 172800, 0, hreq);
    int hrc = admin(0, CLUSTER_OP_NODE_HOLD, hreq, hrl, 0, &hrep, &hlen);
    if (hrc != META_ERR_INVALID || !bytes_has(hrep, hlen, "exceeds 1 day"))
        die("nodehold: 2-day wire hold rc=%d (%.*s)", hrc, (int)hlen, hrep ? (const char *)hrep : "");
    free(hrep);

    /* Hold node 5 for 60 s via follower p1 (tests NOTLEADER redirect + commit wait). */
    snprintf(args, sizeof args, "cluster node hold %s %" PRIu32 " --for 60s --secret-file %s", p1, ids[4], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "held against automatic OUT"))
        die("nodehold: node hold 60s failed: %s", out);
    uint64_t hold = 0;
    (void)member_state_of(leader_of(0), ids[4], NULL, &hold);
    if (hold == 0)
        die("nodehold: hold_until_ms still 0 after CLI returned success");

    /* Kill node 5; wait until DOWN, then past rebuild_after_s=4 (6.5 s): must stay DOWN. */
    stop(4, SIGKILL);
    struct state_want down_w = {ids[4], META_DOWN, 0};
    await_view(0, p_member_state, &down_w, "held node 5 marked DOWN");
    uint64_t t_down = now_ms();

    /* STATUS prints down_reason, down_age, out_in, hold_left. */
    snprintf(args, sizeof args, "cluster status %s --secret-file %s", p0, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "down_reason timeout") ||
        !strstr(out, "down_age ") || !strstr(out, "out_in ") || !strstr(out, "hold_left "))
        die("nodehold: cluster status missing DOWN/hold fields:\n%s", out);

    /* Kill a second member (node 4) briefly so 2/5 = 40% > 25% triggers the mass-OUT guard; check STATUS guard line. */
    stop(3, SIGKILL);
    struct state_want down3 = {ids[3], META_DOWN, 0};
    await_view(0, p_member_state, &down3, "node 4 DOWN for guard status check");
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "guard active yes reason pct down 2/5"))
        die("nodehold: cluster status missing active guard line:\n%s", out);
    start(3);
    struct state_want up3 = {ids[3], META_UP, 0};
    await_view(0, p_member_state, &up3, "node 4 back UP after guard check");

    while (now_ms() - t_down < 6500)
        usleep(100000);
    if (member_state_of(0, ids[4], NULL, NULL) != META_DOWN)
        die("nodehold: held node 5 left DOWN while hold was active");

    /* Release the hold: node 5 is already past rebuild_after_s=4, so pout_plan transitions it to OUT. */
    snprintf(args, sizeof args, "cluster node hold %s %" PRIu32 " --release --secret-file %s", p1, ids[4], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "hold released"))
        die("nodehold: --release failed: %s", out);
    struct state_want out_w = {ids[4], META_OUT, 0};
    await_view(0, p_member_state, &out_w, "node 5 OUT after --release");
    printf("  nodehold: 2-day hold refused, 60 s hold kept node %" PRIu32 " DOWN past rebuild_after_s=4, STATUS showed "
           "down/hold/guard lines, OUT after --release\n", ids[4]);
}

/* nodeout (r9-ops): `tsdb cluster node out` on a LIVE volume leader marks it OUT immediately (after commit), hands
 * off leadership promptly so writes continue without waiting in NO_OWNER, and evacuates the volume to 3 ISR. */
static void scen_nodeout(void)
{
    scenario("nodeout");
    move_env(0);
    struct meta_volume v;
    int L = set_setup(5, &v, 0);
    set_cenv = NULL;
    await_isr(0, "plant", 3, 15000, "plant ISR of 3 before nodeout");

    int R = leader_of(0);
    char pF[META_ADDR_MAX], args[PATH_MAX * 2 + 256], out[8192];
    /* If plant's volume leader happens to be the Raft leader, transfer plant to another ISR replica so we can mark
     * the live volume leader OUT without stepping down the Raft leader. */
    if (L == R) {
        int dst = -1;
        for (uint32_t k = 0; k < v.nrep; k++) {
            int s = server_of(v.rep[k].node);
            if (s >= 0 && s != R) {
                dst = s;
                break;
            }
        }
        if (dst < 0)
            die("nodeout: no non-Raft-leader replica to transfer plant to");
        peer_of(R, pF, sizeof pF);
        snprintf(args, sizeof args, "cluster volume transfer %s %" PRIu32 " %" PRIu32 " --secret-file %s", pF, v.number,
                 ids[dst], secret_path);
        if (cli_run(args, NULL, out, sizeof out) != 0)
            die("nodeout: pre-transfer failed: %s", out);
        L = dst;
    }
    int A = L, F = -1;
    for (int i = 0; i < 5 && F < 0; i++)
        if (i != R && i != A)
            F = i;
    if (F < 0)
        die("nodeout: could not pick follower F");

    tsdbc *wc = client(L);
    tsdbc_set_retry(wc, 30000);
    tsdb_sid sid = rep_series(wc, "nodeout.s0", "plant", 30000);
    int64_t ts0 = 1000;
    float val0 = 1.0f;
    if (tsdbc_insert_series(wc, sid, &ts0, &val0, 1) != 0)
        die("nodeout: pre-out write failed");

    peer_of(F, pF, sizeof pF);
    snprintf(args, sizeof args, "cluster node out %s %" PRIu32 " --secret-file %s", pF, ids[A], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "marked out"))
        die("nodeout: CLI node out failed: %s", out);
    if (member_state_of(R, ids[A], NULL, NULL) != META_OUT)
        die("nodeout: node %" PRIu32 " not META_OUT immediately after commit", ids[A]);

    /* Second node out is refused as already out. */
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "already out"))
        die("nodeout: second node out was not refused: %s", out);

    /* Wait for leadership to transfer off OUT leader A, then verify a write succeeds on the new leader. */
    struct meta_volume fv = {0};
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        if (vol_rec(R, "plant", &fv) && fv.leader && fv.leader != ids[A])
            break;
        if (now_ms() - t0 > 30000)
            die("nodeout: leadership did not transfer off OUT live leader %" PRIu32 " in 30 s", ids[A]);
    }
    tsdbc_close(wc);
    wc = client(server_of(fv.leader));
    tsdbc_set_retry(wc, 30000);
    int64_t ts1 = 2000;
    float val1 = 2.0f;
    if (tsdbc_insert_series(wc, sid, &ts1, &val1, 1) != 0)
        die("nodeout: post-out write on new leader failed");

    /* Wait for place_plan + cmove to move plant off A back to 3 ISR. */
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        if (vol_rec(R, "plant", &fv) && fv.nrep == 3 && fv.nisr == 3 && rep_index(&fv, A) < 0 &&
            !fv.rep[0].learner && !fv.rep[1].learner && !fv.rep[2].learner)
            break;
        if (now_ms() - t0 > 60000)
            die("nodeout: plant did not evacuate OUT node %" PRIu32 " in 60 s", ids[A]);
    }
    if (rows_of(wc, sid) != 2)
        die("nodeout: expected 2 rows on plant after evacuation, got %d", rows_of(wc, sid));
    tsdbc_close(wc);
    move_dir_gone(A);
    printf("  nodeout: `node out %" PRIu32 "` on live leader marked OUT via follower, transferred leadership, "
           "preserved writes, evacuated to 3 ISR\n", ids[A]);
}

/* nodedrain (r9-ops):
 *   Part A: on 3 nodes (no 4th spare), `node drain` holds DRAINING while the member still holds a replica (catches
 *           mutant `drainleaves` deterministically!), and `node drain --cancel` returns it to UP.
 *   Part B: with a 4th node added under live writers, `node drain` moves every log replica off with zero lost writes,
 *           never transitioning to OUT while holding any replica, then automatically transitions DRAINING -> OUT.
 *   Part C: ec=4+2 on 7 nodes under writes -> `node drain` moves both log replica and stripe position off (stripe
 *           position FILLING with prev = drained node, shown in STATUS), then automatically transitions to OUT. */
static void scen_nodedrain(void)
{
    scenario("nodedrain");
    /* Part A: 3-node cluster with replicas=3 (no spare -> stays DRAINING -> catches `drainleaves`, then --cancel). */
    for (int i = 0; i < 3; i++)
        start(i);
    init_cluster(0, 600);
    node_add(0, 1);
    node_add(0, 2);
    unsigned three = 3;
    await_view(0, p_voters, &three, "3 voters up before nodedrain part A");
    uint32_t vnum = 0;
    if (vol_add(0, "d3", 3, &vnum) != 0 || vnum != 1)
        die("nodedrain: volume add d3 failed");
    struct meta_volume dv;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "d3", &dv); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("nodedrain: no record of d3");
    for (uint32_t k = 0; k < dv.nrep; k++)
        await_open_gen(0, "d3", server_of(dv.rep[k].node), 1, 0);
    await_isr(0, "d3", 3, 15000, "d3 ISR of 3");

    char p0[META_ADDR_MAX], p1[META_ADDR_MAX], args[PATH_MAX * 2 + 256], out[16384];
    peer_of(0, p0, sizeof p0);
    peer_of(1, p1, sizeof p1);

    /* Drain node 3 (holds a replica of d3, no 4th server to move it to): must stay DRAINING across >= 2 duty ticks. */
    snprintf(args, sizeof args, "cluster node drain %s %" PRIu32 " --secret-file %s", p1, ids[2], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "draining"))
        die("nodedrain: node drain part A failed: %s", out);
    uint64_t inc_before = 0;
    {
        struct view vw;
        view(0, &vw);
        const struct meta_member *m2 = meta_member(&vw.m, ids[2]);
        inc_before = m2 ? m2->incarnation : 0;
        view_free(&vw);
    }
    uint64_t t_hold = now_ms();
    while (now_ms() - t_hold < 2500) {
        int st = member_state_of(0, ids[2], NULL, NULL);
        if (st != META_DRAINING)
            die("nodedrain: node %" PRIu32 " left DRAINING (state %s) while still holding d3 (drainleaves!)", ids[2],
                meta_member_state_name(st));
        usleep(100000);
    }

    /* Restart draining node 3 cleanly: new incarnation must be recorded while staying DRAINING, and d3 must reopen. */
    stop(2, SIGTERM);
    start(2);
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        struct view vw;
        view(0, &vw);
        const struct meta_member *m2 = meta_member(&vw.m, ids[2]);
        int ok = m2 && m2->state == META_DRAINING && m2->incarnation > inc_before;
        view_free(&vw);
        if (ok)
            break;
        if (now_ms() - t0 > 15000)
            die("nodedrain: restarted draining node %" PRIu32 " did not bump incarnation while staying DRAINING",
                ids[2]);
    }
    await_open_gen(0, "d3", 2, 2, 0);
    await_isr(0, "d3", 3, 15000, "d3 ISR of 3 after draining node restart");

    /* Kill draining node 3: must transition DRAINING -> DOWN(drain), then on restart return to DRAINING (not UP!). */
    uint64_t inc_kill = 0;
    {
        struct view vw;
        view(0, &vw);
        const struct meta_member *m2 = meta_member(&vw.m, ids[2]);
        inc_kill = m2 ? m2->incarnation : 0;
        view_free(&vw);
    }
    stop(2, SIGKILL);
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        uint8_t dr = 0;
        int st = member_state_of(0, ids[2], &dr, NULL);
        if (st == META_DOWN && dr == META_DOWN_DRAIN)
            break;
        if (st == META_DOWN && dr != META_DOWN_DRAIN)
            die("nodedrain: killed draining node %" PRIu32 " went DOWN with reason %s, not drain", ids[2],
                meta_down_reason_name(dr));
        if (now_ms() - t0 > 20000)
            die("nodedrain: killed draining node %" PRIu32 " was never marked DOWN(drain) (st=%d)", ids[2], st);
    }
    start(2);
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        struct view vw;
        view(0, &vw);
        const struct meta_member *m2 = meta_member(&vw.m, ids[2]);
        int st = m2 ? (int)m2->state : -1;
        uint64_t inc = m2 ? m2->incarnation : 0;
        view_free(&vw);
        if (st == META_UP)
            die("nodedrain: draining node %" PRIu32 " returned UP instead of DRAINING after crash+restart", ids[2]);
        if (st == META_DRAINING && inc > inc_kill)
            break;
        if (now_ms() - t0 > 20000)
            die("nodedrain: node %" PRIu32 " did not return to DRAINING after crash+restart (st=%d)", ids[2], st);
    }
    await_open_gen(0, "d3", 2, 3, 0);
    await_isr(0, "d3", 3, 15000, "d3 ISR of 3 after draining node crash+restart");

    /* Cancel the drain: returns DRAINING -> UP. */
    snprintf(args, sizeof args, "cluster node drain %s %" PRIu32 " --cancel --secret-file %s", p0, ids[2], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "drain cancelled"))
        die("nodedrain: --cancel failed: %s", out);
    if (member_state_of(leader_of(0), ids[2], NULL, NULL) != META_UP)
        die("nodedrain: node %" PRIu32 " did not return to UP after --cancel", ids[2]);

    /* Part B: add 4th server, run live writes on d3, drain node 3 (or d3's leader!), verify 0 lost writes and OUT. */
    start(3);
    node_add(0, 3);
    unsigned four = 4;
    await_view(0, p_n_placeable, &four, "4 placeable members for nodedrain part B");

    int dL = server_of(dv.leader);
    int D = dL; /* drain the volume's leader itself to exercise live serving + planned transfer during DRAINING! */
    if (D == leader_of(0)) {
        for (uint32_t k = 0; k < dv.nrep; k++) {
            int s = server_of(dv.rep[k].node);
            if (s >= 0 && s != leader_of(0)) {
                D = s;
                break;
            }
        }
    }
    tsdbc *wc = client(dL);
    tsdbc_set_retry(wc, 30000);
    tsdb_sid sid = rep_series(wc, "drain.s0", "d3", 30000);
    int64_t acked = 0;
    for (int b = 0; b < 5; b++) {
        int64_t ts = 10000 + b * 10;
        float val = (float)b;
        if (tsdbc_insert_series(wc, sid, &ts, &val, 1) != 0)
            die("nodedrain: pre-drain write failed");
        acked++;
    }

    snprintf(args, sizeof args, "cluster node drain %s %" PRIu32 " --secret-file %s", p0, ids[D], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "draining"))
        die("nodedrain: part B node drain failed: %s", out);

    int b_idx = 5;
    for (uint64_t t0 = now_ms();; usleep(50000)) {
        /* Write a row periodically while draining (following MOVED if leadership transferred off D). */
        if (b_idx < 25) {
            struct meta_volume cur;
            if (vol_rec(0, "d3", &cur) && cur.leader) {
                int cl = server_of(cur.leader);
                if (cl >= 0 && cl != dL) {
                    tsdbc_close(wc);
                    dL = cl;
                    wc = client(dL);
                    tsdbc_set_retry(wc, 30000);
                }
            }
            int64_t ts = 10000 + b_idx * 10;
            float val = (float)b_idx;
            if (tsdbc_insert_series(wc, sid, &ts, &val, 1) == 0) {
                acked++;
                b_idx++;
            }
        }
        struct view vw;
        view(0, &vw);
        const struct meta_member *dm = meta_member(&vw.m, ids[D]);
        const struct meta_volume *v1 = meta_volume(&vw.m, 1);
        int still_holds = v1 && meta_replica(v1, ids[D]) != NULL;
        int st = dm ? (int)dm->state : -1;
        int done = !still_holds && v1 && v1->nrep == 3 && v1->nisr == 3 && st == META_OUT;
        view_free(&vw);
        if (still_holds && st == META_OUT)
            die("nodedrain: node %" PRIu32 " marked OUT while still holding d3 (drainleaves!)", ids[D]);
        if (done)
            break;
        if (now_ms() - t0 > 60000)
            die("nodedrain: part B did not finish draining node %" PRIu32 " in 60 s (st=%d holds=%d)", ids[D], st,
                still_holds);
    }
    /* Verify every acknowledged write reads back with zero loss. */
    struct meta_volume fv;
    if (!vol_rec(0, "d3", &fv) || !fv.leader)
        die("nodedrain: d3 has no leader after drain");
    tsdbc_close(wc);
    wc = client(server_of(fv.leader));
    tsdbc_set_retry(wc, 30000);
    if ((int64_t)rows_of(wc, sid) != acked)
        die("nodedrain: lost writes on d3: got %d, acked %" PRId64, rows_of(wc, sid), acked);
    tsdbc_close(wc);
    printf("  nodedrain part A+B: replicas=3 --cancel ok, drained node %" PRIu32 " -> OUT with %" PRId64 " rows intact\n",
           ids[D], acked);

    /* Part C: ec=4+2 on 7 nodes under writes -> drain moves log replica & marks stripe pos FILLING(prev=H);
     * H MUST stay DRAINING while it is still the FILLING copy source (`prev == H`), then transitions to OUT once
     * STRIPE_WHOLE commits (driven via stripe_whole_file=1 test hook until r9-fill/r9-whole land). */
    stop_all();
    snprintf(base, sizeof base, "%s/nodedrain-ec", root);
    if (mkdir(base, 0755) != 0)
        die("mkdir %s: %s", base, strerror(errno));
    memset(ids, 0, sizeof ids);
    memset(pports, 0, sizeof pports);
    memset(stopped, 0, sizeof stopped);
    memset(xargs, 0, sizeof xargs);
    epoll_after_two = 1;
    for (int i = 0; i < 7; i++) {
        envs[i] = "stripe_whole_file=1";
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 7; i++)
        node_add(0, i);
    unsigned five = 5;
    await_view(0, p_voters, &five, "5 voters of 7 for nodedrain part C");
    struct view v0;
    view(0, &v0);
    uint8_t uuid[16];
    memcpy(uuid, v0.m.uuid, 16);
    view_free(&v0);
    static char xa[7][PATH_MAX + 128];
    for (int i = 0; i < 7; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/ds%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i], "--chunk-dir %s", sd);
        restart_xargs(i, xa[i]);
    }
    unsigned seven = 7;
    await_view(0, p_n_placeable, &seven, "7 placeable EC members for nodedrain part C");
    uint32_t ecnum = 0;
    char etxt[256];
    int erc;
    for (uint64_t t0 = now_ms(); (erc = vol_add_ec(0, "d42", 0, 4, 2, &ecnum, etxt, sizeof etxt)) != 0; usleep(100000))
        if ((erc != CLUSTER_ERR_FEW && erc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("nodedrain: ec=4+2 add: %s (%s)", cluster_strerror(erc), etxt);
    struct meta_volume e42;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "d42", &e42); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("nodedrain: no record of d42");
    for (uint32_t k = 0; k < e42.nrep; k++)
        await_open_gen(0, "d42", server_of(e42.rep[k].node), 1, 0);
    await_isr(0, "d42", 3, 15000, "d42 ISR of 3");

    /* Pick H holding BOTH a log replica and a stripe position of d42 (not Raft leader), and find spare S. */
    int R = leader_of(0), H = -1, S = -1;
    uint32_t hpos = UINT32_MAX;
    for (int i = 0; i < 7; i++) {
        int in_s = 0;
        for (uint32_t p = 0; p < e42.nstripe; p++)
            in_s |= (e42.stripe[p] == ids[i]);
        if (!in_s)
            S = i;
    }
    for (uint32_t p = 0; p < e42.nstripe; p++) {
        int s = server_of(e42.stripe[p]);
        if (s >= 0 && s != R && rep_index(&e42, s) >= 0) {
            H = s;
            hpos = p;
            break;
        }
    }
    if (H < 0) {
        for (uint32_t p = 0; p < e42.nstripe; p++) {
            int s = server_of(e42.stripe[p]);
            if (s >= 0 && s != R) {
                H = s;
                hpos = p;
                break;
            }
        }
    }
    if (H < 0 || S < 0)
        die("nodedrain part C: could not pick H and spare S");

    int eL = server_of(e42.leader);
    tsdbc *ec = client(eL);
    tsdbc_set_retry(ec, 30000);
    tsdb_sid esid = rep_series(ec, "drain.ec0", "d42", 30000);
    int64_t eacked = 0;
    for (int b = 0; b < 5; b++) {
        int64_t ts = 20000 + b * 10;
        float val = (float)b;
        if (tsdbc_insert_series(ec, esid, &ts, &val, 1) != 0)
            die("nodedrain part C: pre-drain write failed");
        eacked++;
    }

    peer_of(R, p0, sizeof p0);
    snprintf(args, sizeof args, "cluster node drain %s %" PRIu32 " --secret-file %s", p0, ids[H], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "draining"))
        die("nodedrain part C: node drain failed: %s", out);

    /* Wait until log replica moved off H and pos hpos is FILLING on S with prev = H. */
    uint64_t fill_ver = 0;
    for (uint64_t t0 = now_ms();; usleep(50000)) {
        struct view vw;
        view(R, &vw);
        const struct meta_member *hm = meta_member(&vw.m, ids[H]);
        const struct meta_volume *ev = meta_volume(&vw.m, ecnum);
        int holds_log = ev && meta_replica(ev, ids[H]) != NULL;
        int pos_filling = ev && ev->stripe[hpos] == ids[S] && ev->stripe_pos[hpos].state == META_STRIPE_FILLING &&
                          ev->stripe_pos[hpos].prev == ids[H];
        int st = hm ? (int)hm->state : -1;
        uint64_t sv = ev ? ev->stripe_version : 0;
        int done = !holds_log && pos_filling && ev && ev->nrep == 3 && ev->nisr == 3;
        view_free(&vw);
        if (st == META_OUT)
            die("nodedrain part C: node %" PRIu32 " marked OUT while still holding/serving FILLING pos (drainleaves!)",
                ids[H]);
        if (done) {
            fill_ver = sv;
            break;
        }
        if (now_ms() - t0 > 60000)
            die("nodedrain part C: log/stripe did not move off node %" PRIu32 " (st=%d log=%d fill=%d)", ids[H], st,
                holds_log, pos_filling);
    }
    /* H MUST remain DRAINING across >= 2 duty ticks while hpos is FILLING with prev == H! */
    for (uint64_t t_wait = now_ms(); now_ms() - t_wait < 2500; usleep(100000)) {
        int st = member_state_of(R, ids[H], NULL, NULL);
        if (st != META_DRAINING)
            die("nodedrain part C: node %" PRIu32 " left DRAINING (state %s) while still FILLING prev source!",
                ids[H], meta_member_state_name(st));
    }

    snprintf(args, sizeof args, "cluster status %s --secret-file %s", p0, secret_path);
    char want_fill[128];
    snprintf(want_fill, sizeof want_fill, "fill volume %" PRIu32 " pos %" PRIu32 " node %" PRIu32 " prev %" PRIu32,
             ecnum, hpos, ids[S], ids[H]);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, want_fill))
        die("nodedrain part C: STATUS missing '%s':\n%s", want_fill, out);

    /* Commit STRIPE_WHOLE via test hook -> now H has zero positions and zero FILLING prev refs, so it goes OUT! */
    {
        char swline[64];
        snprintf(swline, sizeof swline, "%" PRIu32 " %" PRIu32 " %" PRIu64 "\n", ecnum, hpos, fill_ver);
        pout_touch(R, "stripewhole", swline);
    }
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        struct view vw;
        view(R, &vw);
        const struct meta_member *hm = meta_member(&vw.m, ids[H]);
        const struct meta_volume *ev = meta_volume(&vw.m, ecnum);
        int ok = hm && hm->state == META_OUT && ev && ev->stripe[hpos] == ids[S] &&
                 ev->stripe_pos[hpos].state == META_STRIPE_WHOLE;
        view_free(&vw);
        if (ok)
            break;
        if (now_ms() - t0 > 20000)
            die("nodedrain part C: node %" PRIu32 " did not transition DRAINING -> OUT after STRIPE_WHOLE", ids[H]);
    }
    struct meta_volume e42f;
    if (!vol_rec(R, "d42", &e42f) || !e42f.leader)
        die("nodedrain part C: d42 missing after drain");
    tsdbc_close(ec);
    ec = client(server_of(e42f.leader));
    tsdbc_set_retry(ec, 30000);
    if ((int64_t)rows_of(ec, esid) != eacked)
        die("nodedrain part C: lost writes on d42");
    tsdbc_close(ec);
    epoll_after_two = 0;
    printf("  nodedrain part C: ec=4+2 held DRAINING while pos %" PRIu32 " FILLING(prev=%" PRIu32 "), then OUT after "
           "STRIPE_WHOLE (STATUS showed fill line)\n", hpos, ids[H]);
}

/* nodereplace (r9-ops): 8-node cluster (6 initial nodes holding ec=4+2 + replicas=3, plus 2 spares S1 < NEW).
 * Kill OLD (holding both log replicas and an EC stripe pos), run `tsdb cluster node replace OLD NEW`, verify
 * replaced_by + hold in metadata and STATUS, restart the Raft leader mid-replace so the new leader resumes from
 * metadata (with rebuild_max=1 so the second volume's move starts AFTER Raft failover!), verify ALL of OLD's log and
 * stripe positions land specifically on NEW (never S1), zero unrelated positions move, and OLD ends OUT with
 * replaced_by cleared. */
static void scen_nodereplace(void)
{
    scenario("nodereplace");
    init_rebuild_after_s = 60;
    init_rebuild_max = 1;
    epoll_after_two = 1;
    for (int i = 0; i < 6; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 6; i++)
        node_add(0, i);
    unsigned five = 5;
    await_view(0, p_voters, &five, "5 voters of 6 before nodereplace");
    struct view v0;
    view(0, &v0);
    uint8_t uuid[16];
    memcpy(uuid, v0.m.uuid, 16);
    view_free(&v0);
    static char xa[8][PATH_MAX + 128];
    for (int i = 0; i < 6; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/rs%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i], "--chunk-dir %s", sd);
        restart_xargs(i, xa[i]);
    }
    unsigned six = 6;
    await_view(0, p_n_placeable, &six, "6 initial EC servers UP");

    uint32_t ecnum = 0, repnum = 0;
    char etxt[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "nr42", 0, 4, 2, &ecnum, etxt, sizeof etxt)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("nodereplace: ec=4+2 add: %s (%s)", cluster_strerror(rc), etxt);
    if (vol_add(0, "nrrep", 3, &repnum) != 0)
        die("nodereplace: replicas=3 add failed");

    struct meta_volume e0, r0;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "nr42", &e0) || !vol_rec(0, "nrrep", &r0); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("nodereplace: volumes not in view");
    for (uint32_t k = 0; k < e0.nrep; k++)
        await_open_gen(0, "nr42", server_of(e0.rep[k].node), 1, 0);
    for (uint32_t k = 0; k < r0.nrep; k++)
        await_open_gen(0, "nrrep", server_of(r0.rep[k].node), 1, 0);
    await_isr(0, "nr42", 3, 15000, "nr42 ISR 3");
    await_isr(0, "nrrep", 3, 15000, "nrrep ISR 3");

    /* Add 2 spare storage servers: S1 (index 6, id 7) and NEW (index 7, id 8). */
    for (int i = 6; i < 8; i++) {
        start(i);
        node_add(0, i);
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/rs%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i], "--chunk-dir %s", sd);
        restart_xargs(i, xa[i]);
    }
    unsigned eight = 8;
    await_view(0, p_n_placeable, &eight, "8 servers UP with stores");

    /* Wait for a non-leader voter F to know the Raft leader R, and pick OLD != R && OLD != F. */
    int R = leader_of(0), S1 = 6, NEW = 7, OLD = -1, F = -1;
    for (uint32_t k = 0; k < e0.nrep; k++) {
        int s = server_of(e0.rep[k].node);
        if (s >= 0 && s != R) {
            OLD = s;
            break;
        }
    }
    for (int i = 0; i < 5 && F < 0; i++)
        if (i != R && i != OLD)
            F = i;
    if (OLD < 0 || F < 0)
        die("nodereplace: could not pick OLD and follower F");
    await_view(F, p_names_leader, &ids[R], "follower F knows leader before nodereplace");
    uint32_t old_pos = UINT32_MAX;
    for (uint32_t p = 0; p < e0.nstripe; p++)
        if (e0.stripe[p] == ids[OLD])
            old_pos = p;
    if (old_pos == UINT32_MAX)
        die("nodereplace: OLD not in nr42 stripe");
    int old_in_rep = rep_index(&r0, OLD) >= 0;

    char pF[META_ADDR_MAX], args[PATH_MAX * 2 + 256], out[16384];
    peer_of(F, pF, sizeof pF);

    /* Refusals: NEW already holds a position of OLD's volume; unknown node. */
    uint32_t peer_in_e0 = e0.stripe[(old_pos + 1) % e0.nstripe];
    snprintf(args, sizeof args, "cluster node replace %s %" PRIu32 " %" PRIu32 " --secret-file %s", pF, ids[OLD],
             peer_in_e0, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "already holds"))
        die("nodereplace: replace onto existing volume holder not refused: %s", out);
    snprintf(args, sizeof args, "cluster node replace %s 99 %" PRIu32 " --secret-file %s", pF, ids[NEW], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "unknown old node"))
        die("nodereplace: unknown old node not refused: %s", out);

    /* Kill OLD and wait for DOWN (stays DOWN because rebuild_after_s=60). */
    stop(OLD, SIGKILL);
    struct state_want down_w = {ids[OLD], META_DOWN, 0};
    await_view(F, p_member_state, &down_w, "OLD marked DOWN");

    /* Run `tsdb cluster node replace OLD NEW` (retry briefly if NEW's chunk-store HB has not landed yet). */
    snprintf(args, sizeof args, "cluster node replace %s %" PRIu32 " %" PRIu32 " --secret-file %s", pF, ids[OLD],
             ids[NEW], secret_path);
    for (uint64_t t0 = now_ms();; usleep(200000)) {
        int crc = cli_run(args, NULL, out, sizeof out);
        if (crc == 0 && strstr(out, "replacing with node"))
            break;
        if (!strstr(out, "no chunk stores") || now_ms() - t0 > 10000)
            die("nodereplace: CLI node replace failed (rc=%d): %s", crc, out);
    }

    /* Verify replaced_by == NEW and hold_until_ms != 0 in metadata and STATUS. */
    {
        struct view vw;
        view(R, &vw);
        const struct meta_member *om = meta_member(&vw.m, ids[OLD]);
        if (!om || om->replaced_by != ids[NEW] || om->hold_until_ms == 0)
            die("nodereplace: OLD missing replaced_by=%" PRIu32 " or hold (got repl=%u hold=%" PRIu64 ")", ids[NEW],
                om ? om->replaced_by : 0, om ? om->hold_until_ms : 0);
        view_free(&vw);
    }
    char want_rb[64];
    snprintf(want_rb, sizeof want_rb, "replaced_by %" PRIu32, ids[NEW]);
    char pR[META_ADDR_MAX];
    peer_of(R, pR, sizeof pR);
    snprintf(args, sizeof args, "cluster status %s --secret-file %s", pR, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, want_rb))
        die("nodereplace: STATUS missing '%s':\n%s", want_rb, out);

    /* Restart the Raft leader mid-replace so a new Raft leader must resume from persisted replaced_by! */
    stop(R, SIGTERM);
    start(R);

    /* Wait for replace to complete: OLD holds nothing, replaced_by cleared, OLD becomes META_OUT. */
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        struct view vw;
        view(F, &vw);
        const struct meta_member *om = meta_member(&vw.m, ids[OLD]);
        const struct meta_volume *ev = meta_volume(&vw.m, ecnum);
        const struct meta_volume *rv = meta_volume(&vw.m, repnum);
        int still_holds = (ev && (meta_replica(ev, ids[OLD]) != NULL || ev->stripe[old_pos] == ids[OLD])) ||
                          (old_in_rep && rv && meta_replica(rv, ids[OLD]) != NULL);
        int early_clear = still_holds && om && (om->replaced_by == 0 || om->state == META_OUT);
        int ok_e = ev && ev->nrep == 3 && ev->nisr >= ev->min_isr && meta_replica(ev, ids[OLD]) == NULL &&
                   meta_replica(ev, ids[NEW]) != NULL && meta_volume_in_isr(ev, ids[NEW]) &&
                   ev->stripe[old_pos] == ids[NEW] && ev->stripe_pos[old_pos].state == META_STRIPE_FILLING &&
                   ev->stripe_pos[old_pos].prev == ids[OLD];
        int ok_r = !old_in_rep || (rv && rv->nrep == 3 && rv->nisr >= rv->min_isr &&
                                   meta_replica(rv, ids[OLD]) == NULL && meta_replica(rv, ids[NEW]) != NULL &&
                                   meta_volume_in_isr(rv, ids[NEW]));
        int ok_m = om && om->state == META_OUT && om->replaced_by == 0;
        view_free(&vw);
        if (early_clear)
            die("nodereplace: OLD cleared replaced_by / marked OUT while still holding positions (replaceclear!)");
        if (ok_e && ok_r && ok_m)
            break;
        if (now_ms() - t0 > 90000)
            die("nodereplace: replace did not complete in 90 s (ok_e=%d ok_r=%d ok_m=%d)", ok_e, ok_r, ok_m);
    }

    /* Verify zero unrelated positions were touched and S1 received nothing. */
    struct meta_volume ef, rf;
    if (!vol_rec(F, "nr42", &ef) || !vol_rec(F, "nrrep", &rf))
        die("nodereplace: volumes missing after replace");
    for (uint32_t p = 0; p < ef.nstripe; p++) {
        if (p == old_pos) {
            if (ef.stripe[p] != ids[NEW])
                die("nodereplace: pos %u went to %u, not NEW %u", p, ef.stripe[p], ids[NEW]);
        } else if (ef.stripe[p] != e0.stripe[p]) {
            die("nodereplace: unrelated stripe pos %u moved (%u -> %u)", p, e0.stripe[p], ef.stripe[p]);
        }
    }
    if (rep_index(&ef, S1) >= 0 || rep_index(&rf, S1) >= 0)
        die("nodereplace: spare S1 received a replica instead of NEW");

    /* Also verify `node replace --cancel` and auto-abandon when replace target goes OUT (releasing OLD's hold). */
    int X = -1;
    for (uint32_t p = 0; p < ef.nstripe; p++) {
        int s = server_of(ef.stripe[p]);
        if (s >= 0 && s != OLD && s != S1 && s != NEW) {
            X = s;
            break;
        }
    }
    if (X < 0)
        die("nodereplace: could not pick surviving node X for cancel/abandon check");
    int curR = leader_of(F);
    peer_of(curR, pR, sizeof pR);
    snprintf(args, sizeof args, "cluster node replace %s %" PRIu32 " %" PRIu32 " --secret-file %s", pR, ids[X], ids[S1],
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("nodereplace: second replace for --cancel failed: %s", out);
    snprintf(args, sizeof args, "cluster node replace %s %" PRIu32 " --cancel --secret-file %s", pR, ids[X],
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "cancelled"))
        die("nodereplace: --cancel failed: %s", out);
    {
        struct view vw;
        view(curR, &vw);
        const struct meta_member *xm = meta_member(&vw.m, ids[X]);
        if (!xm || xm->replaced_by != 0 || xm->hold_until_ms != 0)
            die("nodereplace: --cancel left replaced_by=%u hold=%" PRIu64, xm ? xm->replaced_by : 0,
                xm ? xm->hold_until_ms : 0);
        view_free(&vw);
    }
    /* Start replace onto S1 again, then mark S1 OUT -> cnode_duty must clear replaced_by and release hold on X. */
    snprintf(args, sizeof args, "cluster node replace %s %" PRIu32 " %" PRIu32 " --secret-file %s", pR, ids[X], ids[S1],
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("nodereplace: replace onto S1 for target-OUT abandon check failed: %s", out);
    snprintf(args, sizeof args, "cluster node out %s %" PRIu32 " --secret-file %s", pR, ids[S1], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("nodereplace: node out S1 failed: %s", out);
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        struct view vw;
        view(curR, &vw);
        const struct meta_member *xm = meta_member(&vw.m, ids[X]);
        int ok = xm && xm->replaced_by == 0 && xm->hold_until_ms == 0;
        view_free(&vw);
        if (ok)
            break;
        if (now_ms() - t0 > 15000)
            die("nodereplace: cnode_duty did not abandon replace & release hold after target S1 went OUT");
    }
    epoll_after_two = 0;
    printf("  nodereplace: dead node %" PRIu32 " replaced directly onto node %" PRIu32
           " across Raft leader restart (0 unrelated positions moved, OLD now OUT, --cancel & target-OUT abandon ok)\n",
           ids[OLD], ids[NEW]);
}

/* nodedestroyed (r9-ops): `tsdb cluster node destroyed` is refused on UP and DOWN members, succeeds on OUT (final:
 * restarted server cannot return UP), and destroying m+1=3 stripe holders of ec=4+2 marks the volume LOST in OP_STATUS
 * and makes settled reads fail immediately with TSDB_ERR_UNAVAILABLE / TSDB_WHY_LOST (no retry). */
static void scen_nodedestroyed(void)
{
    scenario("nodedestroyed");
    init_voters = 3; /* nodes 0..2 are the 3 voters; watchers 3..5 can all be destroyed while Raft keeps quorum */
    epoll_after_two = 1;
    static char cold[PATH_MAX + 96], pe[PATH_MAX + 128];
    snprintf(cold, sizeof cold, "%s/cold-hook", base);
    snprintf(pe, sizeof pe, "TSDBD_TEST_COLD=%s", cold);
    /* Only "reads" in cold-hook (NO "destroyed ..." line!): LOST must come purely from real META_DESTROYED! */
    cold_file(cold, "reads\n");
    for (int i = 0; i < 6; i++) {
        penv[i] = pe;
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 6; i++)
        node_add(0, i);
    unsigned three = 3;
    await_view(0, p_voters, &three, "3 voters of 6 before nodedestroyed");
    struct view v0;
    view(0, &v0);
    uint8_t uuid[16];
    memcpy(uuid, v0.m.uuid, 16);
    view_free(&v0);
    static char xa[6][PATH_MAX + 128];
    for (int i = 0; i < 6; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/nd%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i], "--chunk-dir %s", sd);
        restart_xargs(i, xa[i]);
    }
    unsigned six = 6;
    await_view(0, p_n_placeable, &six, "6 members UP for nodedestroyed");

    uint32_t num = 0;
    char etxt[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "nd42", 0, 4, 2, &num, etxt, sizeof etxt)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("nodedestroyed: ec=4+2 add: %s (%s)", cluster_strerror(rc), etxt);
    struct meta_volume ev;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "nd42", &ev); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("nodedestroyed: no record of nd42");
    for (uint32_t k = 0; k < ev.nrep; k++)
        await_open_gen(0, "nd42", server_of(ev.rep[k].node), 1, 0);
    await_isr(0, "nd42", 3, 15000, "nd42 ISR 3");

    /* Ensure the volume leader is one of the surviving voters 0..2 (transfer if it landed on 3..5). */
    int L = server_of(ev.leader);
    if (L >= 3) {
        int dst = -1;
        for (uint32_t k = 0; k < ev.nrep; k++) {
            int s = server_of(ev.rep[k].node);
            if (s >= 0 && s < 3) {
                dst = s;
                break;
            }
        }
        if (dst >= 0) {
            char p0[META_ADDR_MAX], args[PATH_MAX * 2 + 128], out[4096];
            peer_of(0, p0, sizeof p0);
            snprintf(args, sizeof args, "cluster volume transfer %s %" PRIu32 " %" PRIu32 " --secret-file %s", p0, num,
                     ids[dst], secret_path);
            if (cli_run(args, NULL, out, sizeof out) != 0)
                die("nodedestroyed: transfer off watcher failed: %s", out);
            L = dst;
        }
    }
    tsdbc *c = client(L);
    tsdbc_set_retry(c, 30000);
    tsdb_sid sid = rep_series(c, "nd.s0", "nd42", 30000);

    char p0[META_ADDR_MAX], args[PATH_MAX * 2 + 256], out[8192];
    peer_of(0, p0, sizeof p0);

    /* Refused on UP member 3. */
    snprintf(args, sizeof args, "cluster node destroyed %s %" PRIu32 " --secret-file %s", p0, ids[3], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "not out"))
        die("nodedestroyed: UP node not refused: %s", out);

    /* Kill member 3 -> DOWN -> still refused on DOWN. */
    stop(3, SIGKILL);
    struct state_want d3 = {ids[3], META_DOWN, 0};
    await_view(0, p_member_state, &d3, "node 4 DOWN");
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "not out"))
        die("nodedestroyed: DOWN node not refused: %s", out);

    /* Mark member 3 OUT, then DESTROYED -> succeeds; restarting member 3 cannot bring it back UP. */
    snprintf(args, sizeof args, "cluster node out %s %" PRIu32 " --secret-file %s", p0, ids[3], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0)
        die("nodedestroyed: node out 4 failed: %s", out);
    snprintf(args, sizeof args, "cluster node destroyed %s %" PRIu32 " --secret-file %s", p0, ids[3], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "declared destroyed"))
        die("nodedestroyed: node destroyed 4 failed: %s", out);
    if (member_state_of(leader_of(0), ids[3], NULL, NULL) != META_DESTROYED)
        die("nodedestroyed: node 4 not META_DESTROYED");

    start(3);
    usleep(2500000);
    if (member_state_of(leader_of(0), ids[3], NULL, NULL) != META_DESTROYED)
        die("nodedestroyed: restarted destroyed node 4 left META_DESTROYED!");
    stop(3, SIGKILL);

    /* Destroy 2 more stripe holders (watchers 4 and 5) -> m+1 = 3 holders DESTROYED! */
    for (int s = 4; s <= 5; s++) {
        stop(s, SIGKILL);
        snprintf(args, sizeof args, "cluster node out %s %" PRIu32 " --secret-file %s", p0, ids[s], secret_path);
        if (cli_run(args, NULL, out, sizeof out) != 0)
            die("nodedestroyed: node out %d failed: %s", s, out);
        snprintf(args, sizeof args, "cluster node destroyed %s %" PRIu32 " --secret-file %s", p0, ids[s], secret_path);
        if (cli_run(args, NULL, out, sizeof out) != 0)
            die("nodedestroyed: node destroyed %d failed: %s", s, out);
    }

    /* Wait for L's metadata copy to show vol.1.tier=lost in OP_STATUS. */
    char want_tier[64];
    snprintf(want_tier, sizeof want_tier, "vol.%" PRIu32 ".tier=lost", num);
    for (uint64_t t0 = now_ms();; usleep(100000)) {
        char *stxt = NULL;
        int src = tsdbc_status(c, &stxt);
        int ok = src == 0 && stxt && strstr(stxt, want_tier) != NULL;
        free(stxt);
        if (ok)
            break;
        if (now_ms() - t0 > 15000)
            die("nodedestroyed: OP_STATUS never showed '%s'", want_tier);
    }

    /* Settled read fails immediately with TSDB_ERR_UNAVAILABLE / TSDB_WHY_LOST (not retried). */
    tsdbc_set_retry(c, 30000);
    uint64_t t0 = now_ms();
    rc = tsdbc_query_raw(c, sid, 0, INT64_MAX, no_rows, NULL);
    uint64_t took = now_ms() - t0;
    tsdb_unavail u[4];
    unsigned nu = 0;
    if (rc != TSDB_ERR_UNAVAILABLE || tsdbc_unavailable(c, u, 4, &nu) != 0 || nu != 1 || u[0].reason != TSDB_WHY_LOST ||
        u[0].vol != num || u[0].retry_after_ms != TSDB_RETRY_MAX_MS)
        die("nodedestroyed: read of lost volume: %s nu=%u reason=%u vol=%u retry=%u", ers(rc), nu,
            nu ? u[0].reason : 0, nu ? u[0].vol : 0, nu ? u[0].retry_after_ms : 0);
    if (took > 1500)
        die("nodedestroyed: read of lost volume retried (took %" PRIu64 " ms)", took);
    tsdbc_close(c);
    epoll_after_two = 0;
    printf("  nodedestroyed: UP/DOWN refused, OUT -> DESTROYED final, 3 destroyed holders -> tier=lost and read "
           "TSDB_WHY_LOST in %" PRIu64 " ms\n", took);
}

/* posmove (r9-ops): `tsdb cluster volume move PEER V --pos P --to N` moves stripe position P of an EC volume onto
 * target N (FILLING, prev = old_holder, stripe_version + 1, shown in STATUS), and refuses non-EC volumes, invalid
 * positions, targets already in the stripe, targets with no chunk stores, and positions already FILLING. */
static void scen_posmove(void)
{
    scenario("posmove");
    epoll_after_two = 1;
    for (int i = 0; i < 8; i++) {
        envs[i] = "stripe_whole_file=1";
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 8; i++)
        node_add(0, i);
    unsigned five = 5;
    await_view(0, p_voters, &five, "5 voters of 8 before posmove");
    struct view v0;
    view(0, &v0);
    uint8_t uuid[16];
    memcpy(uuid, v0.m.uuid, 16);
    view_free(&v0);
    /* Give nodes 0..6 chunk stores; leave node 7 without a chunk store to test the no-chunk-stores refusal! */
    static char xa[7][PATH_MAX + 128];
    for (int i = 0; i < 7; i++) {
        char sd[PATH_MAX + 96];
        snprintf(sd, sizeof sd, "%s/ps%d", base, i);
        chunk_store_make(sd, uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i], "--chunk-dir %s", sd);
        restart_xargs(i, xa[i]);
    }
    unsigned eight = 8;
    await_view(0, p_n_placeable, &eight, "8 members UP for posmove");

    uint32_t ecnum = 0, repnum = 0;
    char etxt[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "pm42", 0, 4, 2, &ecnum, etxt, sizeof etxt)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("posmove: ec=4+2 add: %s (%s)", cluster_strerror(rc), etxt);
    if (vol_add(0, "pmrep", 3, &repnum) != 0)
        die("posmove: replicas=3 add failed");

    struct meta_volume ev;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "pm42", &ev); usleep(50000))
        if (now_ms() - t0 > 15000)
            die("posmove: no record of pm42");

    int S = -1; /* the 7th storage server (0..6) not in pm42's stripe */
    for (int i = 0; i < 7; i++) {
        int in_s = 0;
        for (uint32_t p = 0; p < ev.nstripe; p++)
            in_s |= (ev.stripe[p] == ids[i]);
        if (!in_s) {
            S = i;
            break;
        }
    }
    if (S < 0)
        die("posmove: could not find 7th storage server");
    uint32_t old_holder = ev.stripe[0];
    int NS = 7; /* node without a chunk store */

    char p0[META_ADDR_MAX], p1[META_ADDR_MAX], args[PATH_MAX * 2 + 256], out[16384];
    peer_of(0, p0, sizeof p0);
    peer_of(1, p1, sizeof p1);

    /* Refusals: non-EC volume, pos out of range, target already in stripe, target with no stores, unknown vol/node. */
    snprintf(args, sizeof args, "cluster volume move %s %" PRIu32 " --pos 0 --to %" PRIu32 " --secret-file %s", p1,
             repnum, ids[S], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "not erasure-coded"))
        die("posmove: non-EC not refused: %s", out);
    snprintf(args, sizeof args, "cluster volume move %s %" PRIu32 " --pos 6 --to %" PRIu32 " --secret-file %s", p0,
             ecnum, ids[S], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "out of range"))
        die("posmove: pos 6 not refused: %s", out);
    snprintf(args, sizeof args, "cluster volume move %s %" PRIu32 " --pos 0 --to %" PRIu32 " --secret-file %s", p0,
             ecnum, ev.stripe[1], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "already holds"))
        die("posmove: target already in stripe not refused: %s", out);
    snprintf(args, sizeof args, "cluster volume move %s %" PRIu32 " --pos 0 --to %" PRIu32 " --secret-file %s", p0,
             ecnum, ids[NS], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "no chunk stores"))
        die("posmove: target with no chunk stores not refused: %s", out);
    snprintf(args, sizeof args, "cluster volume move %s 99 --pos 0 --to %" PRIu32 " --secret-file %s", p0, ids[S],
             secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "does not exist"))
        die("posmove: unknown volume not refused: %s", out);

    /* Valid move via follower p1: pos 0 -> S (FILLING, prev = old_holder, stripe_version = 2). */
    snprintf(args, sizeof args, "cluster volume move %s %" PRIu32 " --pos 0 --to %" PRIu32 " --secret-file %s", p1,
             ecnum, ids[S], secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, "moving from node") || !strstr(out, "filling"))
        die("posmove: valid move failed: %s", out);

    struct meta_volume ev2 = {0};
    if (!vol_rec(leader_of(0), "pm42", &ev2) || ev2.stripe[0] != ids[S] ||
        ev2.stripe_pos[0].state != META_STRIPE_FILLING || ev2.stripe_pos[0].prev != old_holder ||
        ev2.stripe_version != 2)
        die("posmove: unexpected record after move (holder=%u state=%u prev=%u ver=%" PRIu64 ")", ev2.stripe[0],
            ev2.stripe_pos[0].state, ev2.stripe_pos[0].prev, ev2.stripe_version);

    /* STATUS on the Raft leader prints the fill line immediately after commit. */
    char pL[META_ADDR_MAX], want_fill[128];
    peer_of(leader_of(0), pL, sizeof pL);
    snprintf(want_fill, sizeof want_fill, "fill volume %" PRIu32 " pos 0 node %" PRIu32 " prev %" PRIu32 " version 2",
             ecnum, ids[S], old_holder);
    snprintf(args, sizeof args, "cluster status %s --secret-file %s", pL, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 0 || !strstr(out, want_fill))
        die("posmove: STATUS missing '%s':\n%s", want_fill, out);

    /* Moving pos 0 again while already FILLING is refused. */
    snprintf(args, sizeof args, "cluster volume move %s %" PRIu32 " --pos 0 --to %" PRIu32 " --secret-file %s", p0,
             ecnum, old_holder, secret_path);
    if (cli_run(args, NULL, out, sizeof out) != 1 || !strstr(out, "already filling"))
        die("posmove: move of already-FILLING pos not refused: %s", out);

    epoll_after_two = 0;
    printf("  posmove: vol %" PRIu32 " pos 0 moved %" PRIu32 " -> %" PRIu32 " (FILLING, ver 2); refusals and STATUS ok\n",
           ecnum, old_holder, ids[S]);
}

/* ---- r9-reconcile: CHUNK_LIST both ways on start and return (ecback, ecbackempty, ecbackgc) */
#ifdef TSDB_EC
struct rec_chunk_ino {
    char name[128];
    ino_t ino;
    uint64_t cell_bytes;
};

static int rec_scan_chunks(const char *sdir, uint32_t vol, struct rec_chunk_ino *out, int cap, bool verify_all)
{
    char vdir[PATH_MAX + 128];
    snprintf(vdir, sizeof vdir, "%s/s%" PRIu32, sdir, vol);
    DIR *d = opendir(vdir);
    if (!d)
        return 0;
    int n = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL && n < cap) {
        size_t nl = strlen(de->d_name);
        if (de->d_name[0] != 'o' || nl < 8 || strcmp(de->d_name + nl - 6, ".chunk") != 0)
            continue;
        char fp[PATH_MAX + 256];
        snprintf(fp, sizeof fp, "%s/%s", vdir, de->d_name);
        struct stat st;
        if (stat(fp, &st) != 0 || st.st_size <= 0)
            continue;
        uint64_t cell_bytes = 0;
        if (verify_all) {
            int fd = open(fp, O_RDONLY);
            if (fd < 0)
                die("rec_scan_chunks: open %s: %s", fp, strerror(errno));
            uint8_t *buf = malloc((size_t)st.st_size);
            if (!buf)
                die("rec_scan_chunks: out of memory");
            size_t got = 0;
            while (got < (size_t)st.st_size) {
                ssize_t r = read(fd, buf + got, (size_t)st.st_size - got);
                if (r <= 0)
                    break;
                got += (size_t)r;
            }
            close(fd);
            chunk_hdr h;
            const uint8_t *cells = NULL, *sums_le = NULL;
            if (got != (size_t)st.st_size || chunk_image_parse(buf, got, true, &h, &cells, &sums_le) != 0)
                die("rec_scan_chunks: chunk %s failed full cell checksum verification", fp);
            cell_bytes = h.chunk_len;
            free(buf);
        }
        snprintf(out[n].name, sizeof out[n].name, "%s", de->d_name);
        out[n].ino = st.st_ino;
        out[n].cell_bytes = cell_bytes;
        n++;
    }
    closedir(d);
    return n;
}

static int rec_parse_log_filled(int srv, uint32_t vol, uint32_t pos, uint64_t *filled_out, uint64_t *bytes_out,
                                int *lines_out)
{
    char lp[PATH_MAX + 128];
    snprintf(lp, sizeof lp, "%s/n%d.log", base, srv);
    FILE *f = fopen(lp, "r");
    if (!f)
        return -1;
    uint64_t tot_filled = 0, tot_bytes = 0;
    int lines = 0;
    char line[1024];
    char prefix[96];
    snprintf(prefix, sizeof prefix, "tsdbd: reconcile: volume %" PRIu32 " pos %" PRIu32 " version ", vol, pos);
    while (fgets(line, sizeof line, f)) {
        const char *p = strstr(line, prefix);
        if (!p)
            continue;
        unsigned long long ver = 0, done = 0, total = 0, bytes = 0;
        if (sscanf(p + strlen(prefix), "%llu: complete (%llu/%llu missing filled, %llu bytes", &ver, &done, &total,
                   &bytes) == 4) {
            tot_filled += done;
            tot_bytes += bytes;
            lines++;
        }
    }
    fclose(f);
    if (filled_out)
        *filled_out = tot_filled;
    if (bytes_out)
        *bytes_out = tot_bytes;
    if (lines_out)
        *lines_out = lines;
    return 0;
}
#endif

/* ecback (r9-reconcile): 4+2 on 7 nodes. Settle day 0 with all 6 holders UP, then SIGSTOP one stripe holder H past
 * ec.settle_wait_max_s = 5 s so day 2 settles degraded (5 positions, H missing). SIGCONT H before rebuild_after_s:
 * ONLY day 2's missing chunk is filled (day 0's chunk keeps its exact inode, counted bytes equal one chunk).
 * Kills planted mutants `backfullcopy` and `backskipmissing`. */
static void scen_ecback(void)
{
    scenario("ecback");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#else
    epoll_after_two = 1;
    init_rebuild_after_s = 600;
    for (int i = 0; i < 7; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 7; i++)
        node_add(0, i);
    unsigned want_v = 5;
    await_view(0, p_voters, &want_v, "five voters of seven members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    int voter_srv[7] = {0};
    for (int i = 0; i < 7; i++)
        voter_srv[i] = is_voter(&v, ids[i]) != 0;
    view_free(&v);

    static char xa[7][PATH_MAX + 256];
    static char sdirs[7][PATH_MAX + 96];
    for (int i = 0; i < 7; i++) {
        snprintf(sdirs[i], sizeof sdirs[i], "%s/ecs%d", base, i);
        chunk_store_make(sdirs[i], uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i],
                 "--chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 --ec-settle-wait-max-s 5 "
                 "--merge-idle-s 1 --flush-interval-ms 200 --ec-cache-mb 16",
                 sdirs[i]);
        restart_xargs(i, xa[i]);
    }
    unsigned seven = 7;
    await_view(6, p_n_placeable, &seven, "seven members UP with chunk stores");

    uint32_t num = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ecback: vol_add_ec 4+2: %s (%s)", cluster_strerror(rc), text);

    struct meta_volume e;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecback: e42 has no leader");
    int L = server_of(e.leader);
    if (L < 0)
        die("ecback: bad leader %d", L);
    await_isr(L, "e42", 3, 30000, "e42 full ISR before day 0");

    /* Phase 1: Write and settle day 0 while all 6 stripe holders are UP. */
    const int64_t day0 = 1704067200000LL;
    tsdbc *c = client(L);
    tsdb_sid ide[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecb.s%d", s);
        ide[s] = ecb_series(c, nm, "e42");
    }
    ecb_write_day(c, ide, day0);
    int n0 = 0;
    for (uint64_t t0 = now_ms(); (n0 = ecb_ec_parts(L, num)) < 1; usleep(200000))
        if (now_ms() - t0 > 90000)
            die("ecback: day 0 did not settle within 90 s");
    char live[1024];
    for (uint64_t t0 = now_ms(); ecb_live_parts(L, num, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 90000)
            die("ecback: live .part files left after day 0: %s", live);
    n0 = ecb_ec_parts(L, num);

    /* Pick a non-leader, non-Raft-leader, preferably non-rep/non-voter stripe holder H. */
    int ml = leader_of(L);
    int H = -1;
    uint32_t hpos = UINT32_MAX;
    for (int pass = 0; pass < 4 && H < 0; pass++) {
        for (uint32_t p = 0; p < e.nstripe && H < 0; p++) {
            int s = server_of(e.stripe[p]);
            if (s < 0 || s == L || s == ml)
                continue;
            bool rep = ecb_is_rep(&e, s);
            bool vot = voter_srv[s] != 0;
            bool match = (pass == 0 && !rep && !vot) || (pass == 1 && !rep && vot) ||
                         (pass == 2 && rep && !vot) || (pass == 3 && rep && vot);
            if (match) {
                H = s;
                hpos = p;
            }
        }
    }
    if (H < 0)
        die("ecback: could not pick stripe holder H");

    struct rec_chunk_ino before[32];
    int nbef = rec_scan_chunks(sdirs[H], num, before, 32, false);
    if (nbef != n0)
        die("ecback: holder H (srv %d, pos %" PRIu32 ") has %d chunk(s) before SIGSTOP, want %d", H, hpos, nbef, n0);

    /* Phase 2: SIGSTOP H -> wait for META_DOWN -> write day 2 -> settles degraded past settle_wait_max_s = 5 s. */
    pause_server(H, 1);
    struct state_want down_w = {ids[H], META_DOWN, 0};
    await_view(L, p_member_state, &down_w, "holder H marked META_DOWN after SIGSTOP");

    ecb_write_day(c, ide, day0 + 2 * 86400000LL);
    int ntot = 0;
    for (uint64_t t0 = now_ms(); (ntot = ecb_ec_parts(L, num)) <= n0; usleep(200000))
        if (now_ms() - t0 > 90000)
            die("ecback: day 2 did not settle degraded within 90 s (ec parts=%d)", ntot);
    for (uint64_t t0 = now_ms(); ecb_live_parts(L, num, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 90000)
            die("ecback: live .part files left after degraded settle: %s", live);
    ntot = ecb_ec_parts(L, num);
    int ndeg = ntot - n0;
    if (ndeg < 1)
        die("ecback: expected >= 1 degraded object, got %d", ndeg);
    if (ecd_chunks_of(H, num) != n0)
        die("ecback: paused holder H has %d chunks (expected %d)", ecd_chunks_of(H, num), n0);
    if (!log_has(L, "reconcile noted missing position"))
        die("ecback: leader %d did not log sreconcile_note_missing", L);

    /* Record reconcile log baseline before SIGCONT. */
    uint64_t filled_before = 0, bytes_before = 0;
    int lines_before = 0;
    rec_parse_log_filled(H, num, hpos, &filled_before, &bytes_before, &lines_before);

    /* Phase 3: SIGCONT H before rebuild_after_s -> H reconciles ONLY the degraded object's missing chunk! */
    pause_server(H, 0);
    struct state_want up_w = {ids[H], META_UP, 0};
    await_view(L, p_member_state, &up_w, "holder H back META_UP after SIGCONT");

    for (uint64_t t0 = now_ms();; usleep(150000)) {
        int hch = ecd_chunks_of(H, num);
        uint64_t fn = 0, bn = 0;
        int ln = 0;
        rec_parse_log_filled(H, num, hpos, &fn, &bn, &ln);
        if (hch == ntot && ln > lines_before && fn > filled_before)
            break;
        if (now_ms() - t0 > 45000)
            die("ecback: holder H did not reconcile missing chunk within 45 s (chunks %d/%d, log lines %d->%d, filled %" PRIu64 ")",
                hch, ntot, lines_before, ln, fn - filled_before);
    }

    /* Verify:
     *   1. Every chunk on H parses and passes full cell checksum verification.
     *   2. Pre-existing day-0 chunks kept their EXACT original inodes (never rewritten -> kills backfullcopy).
     *   3. Newly filled chunk(s)' cell bytes equal EXACTLY the reconcile bytes counted in H's log (kills backfullcopy). */
    struct rec_chunk_ino after[32];
    int naft = rec_scan_chunks(sdirs[H], num, after, 32, true);
    if (naft != ntot)
        die("ecback: holder H has %d chunk(s) after reconcile, want %d", naft, ntot);

    uint64_t want_new_bytes = 0;
    int new_found = 0;
    for (int i = 0; i < naft; i++) {
        int old_idx = -1;
        for (int j = 0; j < nbef; j++) {
            if (strcmp(after[i].name, before[j].name) == 0) {
                old_idx = j;
                break;
            }
        }
        if (old_idx >= 0) {
            if (after[i].ino != before[old_idx].ino)
                die("ecback: pre-existing chunk %s on H was rewritten (inode changed %" PRIu64 " -> %" PRIu64 "; backfullcopy!)",
                    after[i].name, (uint64_t)before[old_idx].ino, (uint64_t)after[i].ino);
        } else {
            want_new_bytes += after[i].cell_bytes;
            new_found++;
        }
    }
    if (new_found != ndeg)
        die("ecback: found %d new chunk(s) on H, expected %d", new_found, ndeg);

    uint64_t filled_after = 0, bytes_after = 0;
    int lines_after = 0;
    rec_parse_log_filled(H, num, hpos, &filled_after, &bytes_after, &lines_after);
    uint64_t delta_filled = filled_after - filled_before;
    uint64_t delta_bytes = bytes_after - bytes_before;
    if (delta_filled != (uint64_t)ndeg || delta_bytes != want_new_bytes)
        die("ecback: counted reconcile work %" PRIu64 " chunk(s) / %" PRIu64 " bytes != expected %d chunk(s) / %" PRIu64
            " bytes (backfullcopy!)",
            delta_filled, delta_bytes, ndeg, want_new_bytes);
    int total_ch = ecb_chunks_n(num, 7);
    if (total_ch != ntot * 6)
        die("ecback: total chunks %d != %d * 6", total_ch, ntot);

    tsdbc_close(c);
    epoll_after_two = 0;
    stop_all();
    printf("  ecback: 4+2 on 7 nodes -> H (srv %d, pos %" PRIu32 ") SIGSTOPped past wait_max_s, %d degraded obj(s) settled, "
           "SIGCONT -> ONLY %" PRIu64 " missing chunk(s) filled (%" PRIu64 " bytes == exact chunk), %d existing chunk(s) untouched\n",
           H, hpos, ndeg, delta_filled, delta_bytes, nbef);
#endif
}

/* ecbackempty (r9-reconcile): 4+2 on 7 nodes. Settle >= 2 days, stop stripe holder H, wipe & re-initialize H's
 * store directory (empty with a new store id), restart H before rebuild_after_s: H logs the store id change with
 * path and both ids, refills every chunk, and reads with two OTHER stripe holders stopped return exact oracle data. */
static void scen_ecbackempty(void)
{
    scenario("ecbackempty");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#else
    epoll_after_two = 1;
    init_rebuild_after_s = 600;
    for (int i = 0; i < 7; i++)
        start(i);
    init_cluster(0, 600);
    for (int i = 1; i < 7; i++)
        node_add(0, i);
    unsigned want_v = 5;
    await_view(0, p_voters, &want_v, "five voters of seven members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    int voter_srv[7] = {0};
    for (int i = 0; i < 7; i++)
        voter_srv[i] = is_voter(&v, ids[i]) != 0;
    view_free(&v);

    static char xa[7][PATH_MAX + 256];
    static char sdirs[7][PATH_MAX + 96];
    for (int i = 0; i < 7; i++) {
        snprintf(sdirs[i], sizeof sdirs[i], "%s/ecs%d", base, i);
        chunk_store_make(sdirs[i], uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i],
                 "--chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 --merge-idle-s 1 "
                 "--flush-interval-ms 200 --ec-cache-mb 16",
                 sdirs[i]);
        restart_xargs(i, xa[i]);
    }
    unsigned seven = 7;
    await_view(6, p_n_placeable, &seven, "seven members UP with chunk stores");

    uint32_t num = 0, tnum = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ecbackempty: vol_add_ec 4+2: %s (%s)", cluster_strerror(rc), text);
    for (uint64_t t0 = now_ms(); (rc = vol_add(0, "t42", 3, &tnum)) != 0; usleep(100000))
        if (rc != CLUSTER_ERR_NOTLEADER || now_ms() - t0 > 30000)
            die("ecbackempty: twin t42: %s", cluster_strerror(rc));

    struct meta_volume e, tv;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecbackempty: e42 has no leader");
    for (uint64_t t0 = now_ms(); !vol_rec(0, "t42", &tv) || !tv.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecbackempty: t42 has no leader");
    int L = server_of(e.leader), Lt = server_of(tv.leader);
    if (L < 0 || Lt < 0)
        die("ecbackempty: bad leaders L=%d Lt=%d", L, Lt);
    await_isr(L, "e42", 3, 30000, "e42 full ISR before writes");

    const int64_t day0 = 1704067200000LL;
    tsdbc *c = client(L), *ct = client(Lt);
    tsdb_sid ide[ECB_SERIES], idt[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecbe.s%d", s);
        ide[s] = ecb_series(c, nm, "e42");
        idt[s] = ecb_series(ct, nm, "t42");
    }
    ecb_write_day(c, ide, day0);
    ecb_write_day(ct, idt, day0);
    ecb_write_day(c, ide, day0 + 2 * 86400000LL);
    ecb_write_day(ct, idt, day0 + 2 * 86400000LL);

    int nec = 0;
    for (uint64_t t0 = now_ms(); (nec = ecb_ec_parts(L, num)) < 2; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("ecbackempty: only %d .ec part(s) settled within 120 s", nec);
    char live[1024];
    for (uint64_t t0 = now_ms(); ecb_live_parts(L, num, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("ecbackempty: live .part files remain: %s", live);
    nec = ecb_ec_parts(L, num);

    struct ecb_sum twin[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++)
        if ((rc = ecb_read(ct, idt[s], &twin[s])) != 0 || twin[s].n != 4 * ECB_ROWS)
            die("ecbackempty: twin read series %d: %s (%" PRIu64 " rows)", s, ers(rc), twin[s].n);
    tsdbc_close(ct);

    /* Pick stripe holder H (not L, not ml) and record its original store id. */
    int ml = leader_of(L);
    int H = -1;
    uint32_t hpos = UINT32_MAX;
    for (int pass = 0; pass < 4 && H < 0; pass++) {
        for (uint32_t p = 0; p < e.nstripe && H < 0; p++) {
            int s = server_of(e.stripe[p]);
            if (s < 0 || s == L || s == ml)
                continue;
            bool rep = ecb_is_rep(&e, s);
            bool vot = voter_srv[s] != 0;
            bool match = (pass == 0 && !rep && !vot) || (pass == 1 && !rep && vot) ||
                         (pass == 2 && rep && !vot) || (pass == 3 && rep && vot);
            if (match) {
                H = s;
                hpos = p;
            }
        }
    }
    if (H < 0)
        die("ecbackempty: could not pick holder H");

    uint8_t old_sid[16], new_sid[16];
    if (chunk_store_meta_read(sdirs[H], old_sid, NULL) != 0)
        die("ecbackempty: could not read original store id of %s", sdirs[H]);
    char old_hex[33], new_hex[33];
    chunk_oid_hex(old_sid, old_hex);

    /* Stop H, empty its store directory completely and re-init fresh empty store (new store id), then restart H! */
    stop(H, SIGKILL);
    struct state_want down_w = {ids[H], META_DOWN, 0};
    await_view(L, p_member_state, &down_w, "holder H marked META_DOWN after stop");

    if (nftw(sdirs[H], rm_one, 16, FTW_DEPTH | FTW_PHYS) != 0)
        die("ecbackempty: failed to empty %s: %s", sdirs[H], strerror(errno));
    chunk_store_make(sdirs[H], uuid, ids[H]);
    if (chunk_store_meta_read(sdirs[H], new_sid, NULL) != 0)
        die("ecbackempty: could not read new store id of %s", sdirs[H]);
    chunk_oid_hex(new_sid, new_hex);

    start(H);
    struct state_want up_w = {ids[H], META_UP, 0};
    await_view(L, p_member_state, &up_w, "holder H back META_UP with empty store");

    /* Wait until every chunk is refilled onto H! */
    for (uint64_t t0 = now_ms(); ecd_chunks_of(H, num) < nec; usleep(150000))
        if (now_ms() - t0 > 60000)
            die("ecbackempty: holder H refilled only %d/%d chunks within 60 s", ecd_chunks_of(H, num), nec);

    /* Verify store-id mismatch was logged with store path and both ids. */
    char want_log[PATH_MAX + 160];
    snprintf(want_log, sizeof want_log, "reconcile: store %s answered with another store id (expected %s, got %s)",
             sdirs[H], old_hex, new_hex);
    if (!log_has(H, want_log))
        die("ecbackempty: holder H log missing store-id mismatch line '%s'", want_log);

    /* Verify all refilled chunks on H pass full cell checksum verification. */
    struct rec_chunk_ino refilled[32];
    int nref = rec_scan_chunks(sdirs[H], num, refilled, 32, true);
    if (nref != nec)
        die("ecbackempty: holder H has %d verified chunks, want %d", nref, nec);

    /* Stop TWO other stripe holders W1, W2 (keeping Raft quorum >= 3 of 5 voters and keeping L and H UP):
     * with 2 of 6 stripe holders down, ONLY 4 remain UP (H + 3 others = k = 4), proving reads MUST use H! */
    ml = leader_of(L);
    int W[2] = {-1, -1};
    int nw = 0;
    int vdown = 0;
    for (int pass = 0; pass < 2 && nw < 2; pass++) {
        for (uint32_t p = 0; p < e.nstripe && nw < 2; p++) {
            int s = server_of(e.stripe[p]);
            if (s < 0 || s == L || s == ml || s == H)
                continue;
            if (nw == 1 && s == W[0])
                continue;
            if (pass == 0 && voter_srv[s])
                continue;
            if (vdown + voter_srv[s] > 2)
                continue;
            W[nw++] = s;
            vdown += voter_srv[s];
        }
    }
    if (nw < 2)
        die("ecbackempty: could not pick 2 other stripe holders to stop (found %d)", nw);
    stop(W[0], SIGKILL);
    stop(W[1], SIGKILL);

    for (int s = 0; s < ECB_SERIES; s++) {
        struct ecb_sum a;
        if ((rc = ecb_read(c, ide[s], &a)) != 0)
            die("ecbackempty: post-refill read series %d failed: %s", s, ers(rc));
        if (a.n != twin[s].n || a.h != twin[s].h)
            die("ecbackempty: post-refill series %d mismatch: %" PRIu64 " (%" PRIx64 ") vs %" PRIu64 " (%" PRIx64 ")",
                s, a.n, a.h, twin[s].n, twin[s].h);
    }

    tsdbc_close(c);
    epoll_after_two = 0;
    stop_all();
    printf("  ecbackempty: holder H (srv %d, pos %" PRIu32 ") store wiped (%s -> %s), %d/%d chunks refilled & verified, "
           "reads whole == oracle with 2 other holders stopped\n",
           H, hpos, old_hex, new_hex, nref, nec);
#endif
}

/* ecbackgc (r9-reconcile): 4+2 on 7 nodes. Settle day 0, SIGSTOP non-replica stripe holder H, expire day 0 by
 * retention while H is away so MK_GC commits and deletes chunks on the 5 UP holders while staying pending in GCMK
 * for H. SIGCONT H before rebuild_after_s: MK_GC is applied on return (H's chunks deleted via r8k's pending list,
 * never falsely reported as orphans). */
static void scen_ecbackgc(void)
{
    scenario("ecbackgc");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#else
    epoll_after_two = 1;
    init_rebuild_after_s = 600;
    for (int i = 0; i < 7; i++) {
        penv[i] = "TSDB_ECGC_TEST=poll_ms=200,lifetime_s=1";
        start(i);
    }
    init_cluster(0, 600);
    for (int i = 1; i < 7; i++)
        node_add(0, i);
    unsigned want_v = 5;
    await_view(0, p_voters, &want_v, "five voters of seven members");
    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    int voter_srv[7] = {0};
    for (int i = 0; i < 7; i++)
        voter_srv[i] = is_voter(&v, ids[i]) != 0;
    view_free(&v);

    static char xa[7][PATH_MAX + 256];
    static char sdirs[7][PATH_MAX + 96];
    for (int i = 0; i < 7; i++) {
        snprintf(sdirs[i], sizeof sdirs[i], "%s/ecs%d", base, i);
        chunk_store_make(sdirs[i], uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i],
                 "--chunk-dir %s --ec-settle-grace-s 0 --ec-settle-force-s 1 --merge-idle-s 1 "
                 "--flush-interval-ms 200 --ec-cache-mb 16",
                 sdirs[i]);
        restart_xargs(i, xa[i]);
    }
    unsigned seven = 7;
    await_view(6, p_n_placeable, &seven, "seven members UP with chunk stores");

    uint32_t num = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "e42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("ecbackgc: vol_add_ec 4+2: %s (%s)", cluster_strerror(rc), text);

    struct meta_volume e;
    for (uint64_t t0 = now_ms(); !vol_rec(0, "e42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("ecbackgc: e42 has no leader");
    int L = server_of(e.leader);
    if (L < 0)
        die("ecbackgc: bad leader %d", L);
    await_isr(L, "e42", 3, 30000, "e42 full ISR before writes");

    const int64_t day0 = 1704067200000LL;
    tsdbc *c = client(L);
    tsdb_sid ide[ECB_SERIES];
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "ecbgc.s%d", s);
        ide[s] = ecb_series(c, nm, "e42");
    }
    ecb_write_day(c, ide, day0);

    int nec = 0;
    for (uint64_t t0 = now_ms(); (nec = ecb_ec_parts(L, num)) < 1; usleep(200000))
        if (now_ms() - t0 > 90000)
            die("ecbackgc: day 0 did not settle within 90 s");
    char live[1024];
    for (uint64_t t0 = now_ms(); ecb_live_parts(L, num, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 90000)
            die("ecbackgc: live .part files remain: %s", live);
    nec = ecb_ec_parts(L, num);

    /* Pick a non-replica stripe holder H (so all 3 log replicas stay UP and commit MK_GC immediately while H is down). */
    int ml = leader_of(L);
    int H = -1;
    uint32_t hpos = UINT32_MAX;
    for (int pass = 0; pass < 2 && H < 0; pass++) {
        for (uint32_t p = 0; p < e.nstripe && H < 0; p++) {
            int s = server_of(e.stripe[p]);
            if (s < 0 || s == L || s == ml || ecb_is_rep(&e, s))
                continue;
            if ((pass == 0 && !voter_srv[s]) || pass == 1) {
                H = s;
                hpos = p;
            }
        }
    }
    if (H < 0)
        die("ecbackgc: could not pick non-replica stripe holder H");
    if (ecd_chunks_of(H, num) != nec)
        die("ecbackgc: holder H has %d chunks before pause, want %d", ecd_chunks_of(H, num), nec);

    /* Pause H -> wait for META_DOWN -> expire day 0 by retention while H is away -> MK_GC commits! */
    pause_server(H, 1);
    struct state_want down_w = {ids[H], META_DOWN, 0};
    await_view(L, p_member_state, &down_w, "holder H marked META_DOWN before MK_GC");

    for (int s = 0; s < ECB_SERIES; s++)
        for (uint64_t t0 = now_ms(); (rc = tsdbc_set_retention(c, ide[s], 86400000LL)) != 0; usleep(50000))
            if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                die("ecbackgc: set retention on series %d: %s", s, ers(rc));

    /* Wait until MK_GC retired day 0 on L and deleted chunks on the 5 UP holders while H still holds its chunks. */
    for (uint64_t t0 = now_ms();; usleep(200000)) {
        int tot = ecb_chunks_n(num, 7);
        int hch = ecd_chunks_of(H, num);
        if (ecb_ec_parts(L, num) == 0 && tot == hch && hch == nec)
            break;
        if (now_ms() - t0 > 90000)
            die("ecbackgc: MK_GC did not delete UP holders' chunks while H away (ec=%d tot=%d hch=%d want=%d)",
                ecb_ec_parts(L, num), tot, hch, nec);
    }

    /* Resume H -> MK_GC pending deletes apply on H's return (0 chunks left, 0 false orphan reports). */
    pause_server(H, 0);
    struct state_want up_w = {ids[H], META_UP, 0};
    await_view(L, p_member_state, &up_w, "holder H back META_UP after MK_GC");

    for (uint64_t t0 = now_ms(); ecd_chunks_of(H, num) != 0 || ecb_chunks_n(num, 7) != 0; usleep(200000))
        if (now_ms() - t0 > 60000)
            die("ecbackgc: H's chunks not deleted on return within 60 s (hch=%d tot=%d)", ecd_chunks_of(H, num),
                ecb_chunks_n(num, 7));

    if (log_has(H, ": orphan chunk "))
        die("ecbackgc: holder H falsely reported committed MK_GC chunk as an orphan");

    tsdbc_close(c);
    epoll_after_two = 0;
    stop_all();
    printf("  ecbackgc: holder H (srv %d, pos %" PRIu32 ") paused while MK_GC committed (%d chunks deleted on 5 UP holders); "
           "on return MK_GC applied cleanly (0 chunks left, 0 false orphans)\n",
           H, hpos, nec * 5);
#endif
}

/* Helper for scen_scrub: find first parity chunk (pos >= h.g.k with h.g.m == 2) under <store>/s<vol>. */
static int find_parity_chunk(const char *sdir, uint32_t vol, char *path_out, size_t cap, char oid_out[33],
                             unsigned *pos_out)
{
    char vdir[PATH_MAX + 64];
    snprintf(vdir, sizeof vdir, "%s/s%" PRIu32, sdir, vol);
    DIR *d = opendir(vdir);
    if (!d)
        return 0;
    struct dirent *e;
    int found = 0;
    while ((e = readdir(d)) != NULL) {
        size_t len = strlen(e->d_name);
        if (len < 41 || e->d_name[0] != 'o' || e->d_name[33] != '.')
            continue;
        char *end = NULL;
        unsigned long pos = strtoul(e->d_name + 34, &end, 10);
        if (!end || strcmp(end, ".chunk") != 0)
            continue;
        char cand[PATH_MAX + 128];
        snprintf(cand, sizeof cand, "%s/%s", vdir, e->d_name);
        int fd = open(cand, O_RDONLY | O_CLOEXEC);
        if (fd < 0)
            continue;
        uint8_t hb[CHUNK_HDR_BYTES];
        ssize_t rn = pread(fd, hb, sizeof hb, 0);
        close(fd);
        chunk_hdr h;
        if (rn != (ssize_t)sizeof hb || chunk_hdr_decode(hb, &h) != 0 || h.g.m != 2 || h.pos < h.g.k ||
            h.pos != (uint16_t)pos)
            continue;
        snprintf(path_out, cap, "%s", cand);
        memcpy(oid_out, e->d_name + 1, 32);
        oid_out[32] = '\0';
        *pos_out = (unsigned)pos;
        found = 1;
        break;
    }
    closedir(d);
    return found;
}

/* scrub (R12, r12-chunk; E25, E26, §5.9): 4+2 EC volume on 7 nodes, flip a parity byte at rest ->
 *   1. Clean scrub pass exports tsdb_chunk_scrub_{bytes,chunks,damaged}_total{store="0"} and age_seconds, and
 *      CREPORT_SEC_CHUNKSCRUB arrives in STATUS on the Raft leader.
 *   2. Flipping a parity cell byte at rest triggers CHUNK_DAMAGED over R8's CHUNK link to the volume leader
 *      within one pass at test pace (verified via both the leader's log line and counter metric). */
static void scen_scrub(void)
{
    scenario("scrub");
#ifndef TSDB_EC
    printf("  skipped: this build has no erasure codec (x86-64 only)\n");
    return;
#endif
    int mports[7] = {0};
    for (int i = 0; i < 7; i++) {
        penv[i] = "TSDB_CHUNKSCRUB_TEST=interval_ms=200,mb_s=50";
        xargs[i] = "--metrics-port auto";
        start(i);
        mports[i] = th_mport;
    }
    init_cluster(0, 600);
    for (int i = 1; i < 7; i++)
        node_add(0, i);
    unsigned want = 5;
    await_view(0, p_voters, &want, "five voters of seven members");

    struct view v;
    view(0, &v);
    uint8_t uuid[16];
    memcpy(uuid, v.m.uuid, 16);
    view_free(&v);

    static char xa[7][PATH_MAX + 256];
    static char sdirs[7][PATH_MAX + 96];
    for (int i = 0; i < 7; i++) {
        snprintf(sdirs[i], sizeof sdirs[i], "%s/scs%d", base, i);
        chunk_store_make(sdirs[i], uuid, ids[i]);
        snprintf(xa[i], sizeof xa[i],
                 "--chunk-dir %s --metrics-port auto --ec-settle-grace-s 0 --ec-settle-force-s 1 --merge-idle-s 1 "
                 "--flush-interval-ms 200",
                 sdirs[i]);
        restart_xargs(i, xa[i]);
        mports[i] = th_mport;
        if (mports[i] <= 0)
            die("scrub: server %d reported no metrics port after restart", i);
    }
    unsigned seven = 7;
    await_view(6, p_n_placeable, &seven, "seven members UP with their volumes open");

    uint32_t num = 0;
    char text[256];
    int rc;
    for (uint64_t t0 = now_ms(); (rc = vol_add_ec(0, "sc42", 0, 4, 2, &num, text, sizeof text)) != 0; usleep(100000))
        if ((rc != CLUSTER_ERR_FEW && rc != CLUSTER_ERR_NOTLEADER) || now_ms() - t0 > 30000)
            die("scrub: ec=4+2 add: %s (%s)", cluster_strerror(rc), text);

    struct meta_volume e = {0};
    for (uint64_t t0 = now_ms(); !vol_rec(0, "sc42", &e) || !e.leader; usleep(50000))
        if (now_ms() - t0 > 30000)
            die("scrub: no record of sc42 with a leader 30 s after add");
    int L = server_of(e.leader);
    if (L < 0)
        die("scrub: sc42 leader %" PRIu32 " is no server of the test", e.leader);
    printf("  sc42 (volume %" PRIu32 ") led by server %d\n", num, L);

    tsdbc *c = client(L);
    tsdb_sid ide[ECB_SERIES];
    const int64_t day0 = 1704067200000LL;
    for (int s = 0; s < ECB_SERIES; s++) {
        char nm[32];
        snprintf(nm, sizeof nm, "scb.s%d", s);
        ide[s] = ecb_series(c, nm, "sc42");
    }
    for (int b = 0; b < 2; b++) {
        for (int s = 0; s < ECB_SERIES; s++) {
            static int64_t ts[ECB_ROWS];
            static float val[ECB_ROWS];
            ecb_rows_of(s, b, day0, ts, val);
            for (uint64_t t0 = now_ms(); (rc = tsdbc_insert_series(c, ide[s], ts, val, ECB_ROWS)) != 0; usleep(50000))
                if ((rc != TSDB_ERR_UNAVAILABLE && rc != TSDB_ERR_MOVED) || now_ms() - t0 > 30000)
                    die("scrub: insert into sc42: %s", ers(rc));
        }
        usleep(1000000);
    }

    for (uint64_t t0 = now_ms(); ecb_ec_parts(L, num) == 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("scrub: no .ec part in leader's v%" PRIu32 " 120 s after writes", num);
    char live[1024];
    for (uint64_t t0 = now_ms(); ecb_live_parts(L, num, live, sizeof live) != 0; usleep(200000))
        if (now_ms() - t0 > 120000)
            die("scrub: .part files left in leader's v%" PRIu32 ":%s", num, live);

    /* Find a parity chunk (*.4.chunk or *.5.chunk) across the 7 storage nodes. */
    int target_srv = -1;
    char ppath[PATH_MAX + 128] = "";
    char poid[33] = "";
    unsigned ppos = 0;
    for (int i = 0; i < 7 && target_srv < 0; i++) {
        if (find_parity_chunk(sdirs[i], num, ppath, sizeof ppath, poid, &ppos))
            target_srv = i;
    }
    if (target_srv < 0)
        die("scrub: no parity chunk (pos >= 4) found across 7 stores for volume %" PRIu32, num);
    printf("  found parity chunk on server %d: oid=%s pos=%u\n", target_srv, poid, ppos);

    /* Wait for at least one clean chunk scrub pass on target_srv and verify metrics + heartbeat section. */
    char mbuf[65536];
    int clean_ok = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 20000; usleep(100000)) {
        metrics_get(mports[target_srv], mbuf, sizeof mbuf);
        int64_t chunks = 0, bytes = 0, dmg = -1;
        if (metrics_find_i64(mbuf, "\ntsdb_chunk_scrub_chunks_total{store=\"0\"} ", &chunks) && chunks >= 1 &&
            metrics_find_i64(mbuf, "\ntsdb_chunk_scrub_bytes_total{store=\"0\"} ", &bytes) && bytes > 0 &&
            metrics_find_i64(mbuf, "\ntsdb_chunk_scrub_damaged_total{store=\"0\"} ", &dmg) && dmg == 0 &&
            strstr(mbuf, "\ntsdb_chunk_scrub_age_seconds{store=\"0\"} ")) {
            clean_ok = 1;
            break;
        }
    }
    if (!clean_ok)
        die("scrub: server %d did not complete a clean chunk scrub pass with expected metrics", target_srv);

    int sec_ok = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 10000 && !sec_ok; usleep(150000)) {
        int rl = leader_of(0);
        if (rl < 0)
            continue;
        struct view sv;
        view(rl, &sv);
        char needle[96];
        snprintf(needle, sizeof needle, "chunk_scrub node=%" PRIu32 " store=0 state=UP", ids[target_srv]);
        for (uint32_t k = 0; k < sv.st.nheard; k++) {
            if (sv.st.heard[k].id == ids[target_srv] && sv.st.heard[k].sections &&
                strstr(sv.st.heard[k].sections, needle)) {
                sec_ok = 1;
                break;
            }
        }
        view_free(&sv);
    }
    if (!sec_ok)
        die("scrub: CREPORT_SEC_CHUNKSCRUB section for server %d did not arrive in STATUS", target_srv);

    /* Flip one byte inside a cell of the parity chunk at rest. */
    int fd = open(ppath, O_RDWR | O_CLOEXEC);
    if (fd < 0)
        die("scrub: open parity chunk %s: %s", ppath, strerror(errno));
    uint8_t byte = 0;
    if (pread(fd, &byte, 1, CHUNK_HDR_BYTES + 16) != 1)
        die("scrub: pread parity chunk %s: %s", ppath, strerror(errno));
    byte ^= 0x5au;
    if (pwrite(fd, &byte, 1, CHUNK_HDR_BYTES + 16) != 1 || fsync(fd) != 0)
        die("scrub: pwrite/fsync parity chunk %s: %s", ppath, strerror(errno));
    close(fd);

    /* Wait for storage server scrub to detect damage and report CHUNK_DAMAGED to volume leader L. */
    char want_log[160];
    snprintf(want_log, sizeof want_log, "volume %" PRIu32 ": CHUNK_DAMAGED from node %" PRIu32 " oid=%s pos=%u", num,
             ids[target_srv], poid, ppos);
    char want_metric[96];
    snprintf(want_metric, sizeof want_metric, "\ntsdb_chunk_scrub_reports_received_total{volume=\"%" PRIu32 "\"} ", num);

    int saw_store_dmg = 0, saw_leader_log = 0, saw_leader_cnt = 0;
    for (uint64_t t0 = now_ms(); now_ms() - t0 < 20000; usleep(100000)) {
        if (!saw_store_dmg) {
            metrics_get(mports[target_srv], mbuf, sizeof mbuf);
            int64_t dmg = 0;
            if (metrics_find_i64(mbuf, "\ntsdb_chunk_scrub_damaged_total{store=\"0\"} ", &dmg) && dmg >= 1)
                saw_store_dmg = 1;
        }
        if (!saw_leader_log && log_has(L, want_log))
            saw_leader_log = 1;
        if (!saw_leader_cnt) {
            metrics_get(mports[L], mbuf, sizeof mbuf);
            int64_t rcnt = 0;
            if (metrics_find_i64(mbuf, want_metric, &rcnt) && rcnt >= 1)
                saw_leader_cnt = 1;
        }
        if (saw_store_dmg && saw_leader_log && saw_leader_cnt)
            break;
    }
    if (!saw_store_dmg)
        die("scrub: server %d did not count parity rot in tsdb_chunk_scrub_damaged_total", target_srv);
    if (!saw_leader_log)
        die("scrub: volume leader %d log missing expected line: %s", L, want_log);
    if (!saw_leader_cnt)
        die("scrub: volume leader %d counter %s did not increment", L, want_metric + 1);

    /* Healthy reads still succeed bit-exact after parity rot. */
    struct ecb_sum rs;
    if ((rc = ecb_read(c, ide[0], &rs)) != 0 || rs.n != 2 * ECB_ROWS)
        die("scrub: read after parity rot failed: rc=%d rows=%" PRIu64, rc, rs.n);
    tsdbc_close(c);
    printf("  CHUNK_DAMAGED reached leader %d (log + counter) within one pass\n", L);
}

int main(int argc, char **argv)
{
    signal(SIGPIPE, SIG_IGN);
    th_watchdog("test_cluster", 1800);
    if (argc == 3 && !strcmp(argv[1], "hardslot-child"))
        return hardslot_child(argv[2]);
#ifdef __linux__
    if (argc == 2 && !strcmp(argv[1], "crashpt-child"))
        return crashpt_child();
    if (argc == 2 && !strcmp(argv[1], "crashpt-long-child"))
        return crashpt_long_child();
#endif
    /* TMPDIR when no directory is given: /tmp is often a RAM tmpfs, and a 22-node run writes to /var/tmp */
    const char *scratch = argc > 1 && *argv[1] ? argv[1] : getenv("TMPDIR");
    if (!scratch || !*scratch)
        scratch = "/var/tmp";
    snprintf(root, sizeof root, "%s/tsdb_cluster.XXXXXX", scratch);
    if (!mkdtemp(root)) {
        fprintf(stderr, "test_cluster: mkdtemp %s: %s\n", root, strerror(errno));
        return 1;
    }
    snprintf(base, sizeof base, "%s", root);
    snprintf(secret_path, sizeof secret_path, "%s/cluster.secret", root);
    /* a secret of its own per run (the one a worktree running at the same time shares would no longer separate runs) */
    char serr[256];
    if (cluster_make_secret(secret_path, serr, sizeof serr) != 0 ||
        cluster_read_secret(secret_path, secret, sizeof secret, &secret_len, serr, sizeof serr) != 0)
        die("the cluster secret %s: %s", secret_path, serr);

    static const struct {
        const char *name;
        void (*fn)(void);
    } all[] = {{"secret", scen_secret},     {"relay", scen_relay},     {"initcrash", scen_initcrash},
               {"dirsync", scen_dirsync},   {"exitthreads", scen_exitthreads},   {"install", scen_install}, {"reseed", scen_reseed},
               {"torn", scen_torn},         {"rebase", scen_rebase},
               {"slowinstall", scen_slowinstall},
               {"ids", scen_ids},           {"watch", scen_watch},     {"stall", scen_stall},
               {"witness", scen_witness},   {"users", scen_users}, {"login", scen_login}, {"userimport", scen_userimport},
               {"userstale", scen_userstale}, {"userpromote", scen_userpromote}, {"userreplay", scen_userreplay},
               {"userlease", scen_userlease},   {"flags", scen_flags},     {"hbsections", scen_hbsections},
               {"retired", scen_retired},   {"feed", scen_feed}, {"syncrace", scen_syncrace}, {"power", scen_power}, {"powersnap", scen_powersnap},   {"life", scen_life},
               {"copyback", scen_copyback}, {"voterstale", scen_voterstale}, {"snapmove", scen_snapmove}, {"dirsyncshared", scen_dirsync_shared},
               {"installshared", scen_install_shared}, {"powervote", scen_powervote}, {"pendshared", scen_pend_shared}, {"copyfault", scen_copyfault},
               {"volumes", scen_volumes}, {"volrefuse", scen_volrefuse}, {"snapversion", scen_snapversion}, {"links", scen_links}, {"fwdlinks", scen_fwdlinks}, {"replicate", scen_replicate}, {"replindet", scen_replindet}, {"replfail", scen_replfail}, {"failover", scen_failover}, {"failoverkeep", scen_failoverkeep}, {"fencecrash", scen_fencecrash}, {"promotecrash", scen_promotecrash}, {"deposecrash", scen_deposecrash}, {"pause", scen_pause}, {"promoteslow", scen_promoteslow}, {"openread", scen_openread}, {"openreadlead", scen_openreadlead}, {"jointpause", scen_jointpause}, {"leasestale", scen_leasestale}, {"resign", scen_resign}, {"refused", scen_refused}, {"cut", scen_cut}, {"cuthold", scen_cuthold}, {"deposetail", scen_deposetail}, {"replflip", scen_replflip}, {"replmeta", scen_replmeta}, {"replepoch", scen_replepoch}, {"repldesc", scen_repldesc}, {"drvcheck", scen_drvcheck}, {"replbulk", scen_replbulk}, {"readdepose", scen_readdepose}, {"oneway", scen_oneway}, {"oneway2", scen_oneway2}, {"cutstuck", scen_cutstuck}, {"manystuck", scen_manystuck}, {"noowner", scen_noowner}, {"isr", scen_isr}, {"topology", scen_topology}, {"copyhold", scen_copyhold}, {"movedself", scen_movedself}, {"route", scen_route}, {"forward", scen_forward}, {"fwdseries", scen_fwdseries}, {"fwdseriesstrict", scen_fwdseries_strict}, {"fwdlease", scen_fwdlease}, {"fwddepose", scen_fwddepose}, {"fwdload", scen_fwdload}, {"viabench", scen_viabench}, {"ccstress", scen_ccstress}, {"minisr", scen_minisr}, {"closegone", scen_closegone}, {"writersync", scen_writersync}, {"shipstall", scen_shipstall}, {"keepcap", scen_keepcap}, {"snapxfer", scen_snapxfer}, {"snaplarge", scen_snaplarge}, {"snapnospace", scen_snapnospace}, {"snapbusy", scen_snapbusy}, {"snapsrckill", scen_snapsrckill}, {"snaplost", scen_snaplost}, {"snapstall", scen_snapstall}, {"rejoin", scen_rejoin}, {"rejoinsteady", scen_rejoinsteady}, {"rejoinslow", scen_rejoinslow}, {"tickwall", scen_tickwall}, {"rejoinlate", scen_rejoinlate}, {"keepfloor", scen_keepfloor}, {"reopenhold", scen_reopenhold}, {"backpressure", scen_backpressure}, {"stallstop", scen_stallstop}, {"inboxshared", scen_inboxshared}, {"idleseal", scen_idleseal}, {"chunksrv", scen_chunksrv}, {"ecadd", scen_ecadd}, {"margins", scen_margins}, {"ecbasic", scen_ecbasic}, {"ecslow", scen_ecslow}, {"ec16", scen_ec16}, {"ecgc", scen_ecgc}, {"ecdegraded", scen_ecdegraded}, {"copycaught", scen_copycaught}, {"r4stubs", scen_r4stubs}, {"r9stubs", scen_r9stubs}, {"opening", scen_opening}, {"failgasp", scen_failgasp}, {"faultreason", scen_faultreason}, {"addreplica", scen_addreplica}, {"setnext", scen_setnext}, {"addswitch", scen_addswitch}, {"removereplica", scen_removereplica}, {"removeindex", scen_removeindex}, {"removedown", scen_removedown}, {"setstale", scen_setstale}, {"setchurn", scen_setchurn}, {"resetlost", scen_resetlost}, {"volcmd", scen_volcmd}, {"transfer", scen_transfer}, {"transferslow", scen_transferslow}, {"transferlag", scen_transferlag}, {"transferhold", scen_transferhold}, {"transfergrant", scen_transfergrant}, {"transferadmin", scen_transferadmin}, {"transferstale", scen_transferstale}, {"transfermarkers", scen_transfermarkers}, {"transferkill", scen_transferkill}, {"transferraftkill", scen_transferraftkill}, {"transferraftdrain", scen_transferraftdrain}, {"balance", scen_balance}, {"balancetwo", scen_balancetwo}, {"balancecut", scen_balancecut}, {"balancehb", scen_balancehb}, {"snapcatch", scen_snapcatch}, {"snapkill", scen_snapkill}, {"snappower", scen_snappower}, {"snapfence", scen_snapfence}, {"snapdiverged", scen_snapdiverged}, {"addsnap", scen_addsnap}, {"classfailover", scen_classfailover}, {"removesnap", scen_removesnap}, {"move", scen_move}, {"movelag", scen_movelag}, {"moveleader", scen_moveleader}, {"moverep0", scen_moverep0}, {"moveraft", scen_moveraft}, {"movekill", scen_movekill}, {"movecancel", scen_movecancel}, {"moveold", scen_moveold},
               {"ackdurable", scen_ackdurable}, {"writerfail", scen_writerfail}, {"writerfailq", scen_writerfailq}, {"diverged", scen_diverged}, {"writerdepose", scen_writerdepose}, {"lease", scen_lease}, {"hungloop", scen_hungloop},
               {"leasedown", scen_leasedown}, {"leasequorum", scen_leasequorum}, {"hardslot", scen_hardslot},
               {"repcheck", scen_repcheck}, {"rdma", scen_rdma}, {"openfast", scen_openfast},
               {"outtimer", scen_outtimer}, {"outback", scen_outback}, {"outguard", scen_outguard},
               {"outhold", scen_outhold}, {"outopening", scen_outopening}, {"outfailstop", scen_outfailstop},
               {"replfault", scen_replfault}, {"pace", scen_pace},
               {"downkeep", scen_downkeep}, {"downbudget", scen_downbudget}, {"holdkeep", scen_holdkeep},
               {"outmove", scen_outmove}, {"ecout", scen_ecout}, {"metrics", scen_metrics}, {"progress", scen_progress},
               {"full", scen_full}, {"fullnonisr", scen_fullnonisr}, {"ecrebuild", scen_ecrebuild},
               {"ecwhole", scen_ecwhole},
               {"nodehold", scen_nodehold}, {"nodeout", scen_nodeout}, {"nodedrain", scen_nodedrain},
               {"nodereplace", scen_nodereplace}, {"nodedestroyed", scen_nodedestroyed}, {"posmove", scen_posmove},
               {"youngscrub", scen_youngscrub}, {"scrubheal", scen_scrubheal},
               {"ecback", scen_ecback}, {"ecbackempty", scen_ecbackempty}, {"ecbackgc", scen_ecbackgc}, {"scrub", scen_scrub}};
    int n = (int)(sizeof all / sizeof all[0]);
    for (int a = 2; a < argc; a++) { /* a name that matches nothing would run nothing and print OK */
        int known = 0;
        for (int k = 0; k < n; k++)
            known |= !strcmp(argv[a], all[k].name);
        if (!known)
            die("unknown scenario \"%s\"", argv[a]);
    }
    for (int k = 0; k < n; k++) {
        int run = argc <= 2;
        for (int a = 2; a < argc; a++)
            run |= !strcmp(argv[a], all[k].name);
        if (run)
            all[k].fn();
    }
    stop_all();
    /* a passing run removes its directory (a failing one dies above and keeps it for a look);
       TSDB_KEEP_SCRATCH=1 keeps it */
    const char *keep = getenv("TSDB_KEEP_SCRATCH");
    if (keep && *keep && strcmp(keep, "0"))
        printf("test_cluster: OK (%s kept)\n", root);
    else if (nftw(root, rm_one, 16, FTW_DEPTH | FTW_PHYS) != 0)
        printf("test_cluster: OK (could not remove all of %s: %s)\n", root, strerror(errno));
    else
        printf("test_cluster: OK\n");
    return 0;
}
